# ---- Version: the one source, bumped by hand at each release by the policy in
# docs/ROADMAP.md ("Versioning"); recorded in settings, so a newer build can
# say it was updated ----
APP_VERSION = "0.97.405"


def parse_version(v):
    """'2.1.0' -> (2, 1, 0). Bad input sorts as (0,0,0) so it never crashes a
    comparison."""
    try:
        parts = [int(x) for x in str(v).strip().split(".")]
        while len(parts) < 3:
            parts.append(0)
        return tuple(parts[:3])
    except (ValueError, AttributeError):
        return (0, 0, 0)


