def _undo_atom(method=None, *, tags_only=False, only_if=None):
    """One table operation = ONE undo unit: Tk made each insert of a commit
    its own Ctrl+Z step, and an Undo stopped halfway. Nested calls keep the
    outermost unit. *tags_only*, for an action laying tags only, leaves the
    autoseparators alone (a configure re-lays out the note, 150-200 ms).
    *only_if* opens the unit only when it answers true for the instance.
    """
    if method is None:
        return lambda m: _undo_atom(m, tags_only=tags_only, only_if=only_if)

    @functools.wraps(method)
    def wrapped(self, *args, **kwargs):
        if only_if is not None and not only_if(self):
            return method(self, *args, **kwargs)
        # Read and cleared by the open it is meant for.
        self._undo_atom_tags_only = tags_only
        self._undo_atom_begin()
        try:
            return method(self, *args, **kwargs)
        finally:
            self._undo_atom_end()
    return wrapped


def _fmt_journal_tag(name):
    """Is this a tag the formatting journal keeps? Character formatting
    and the paragraph tags (indent, alignment): what Tk's undo stack never
    records. The one list -- the snapshot, the restore and the look-ahead
    for Tk's own deletes all ask it."""
    return (is_format_tag(name) or name.startswith("para_")
            or name in ("align_center", "align_right"))


def _stored_signature(note):
    """What a note stores, its "updated" stamp aside, as one string -- to
    tell a save that changed something from one that changed nothing."""
    return json.dumps({k: v for k, v in note.items() if k != "updated"},
                      sort_keys=True, ensure_ascii=False, default=str)


def _is_month_day(chunk):
    """One of a monthly repeat's days, as the box holds it: 1 to 31."""
    # isdecimal(): "3²" passed isdigit() and crashed int().
    return chunk.isdecimal() and 1 <= int(chunk) <= 31


def _whole_number(text):
    """Is this a repeat's count or interval the app can store: a whole
    number of at least 1, as int() reads it."""
    try:
        return int(text) >= 1
    except (TypeError, ValueError):
        return False


def _index_key(index):
    """A Tk text index, "line.col", as (line, col), to compare in Python."""
    line, col = str(index).split(".")
    return int(line), int(col)


def _entry_selected(entry):
    """How many characters a tk.Entry's selection holds, 0 with none. Its
    indices count an astral character as two, and a limit counts one."""
    try:
        if not entry.selection_present():
            return 0
        first, last = entry.index("sel.first"), entry.index("sel.last")
    except tk.TclError:
        return 0
    chars, units = 0, 0
    for ch in entry.get():
        if units >= last:
            break
        if units >= first:
            chars += 1
        units += 2 if ord(ch) > 0xFFFF else 1
    return chars


# One round trip for a whole snapshot: where the embedded windows sit, then
# one "tag ranges" string per tag, in the order asked. Tag names travel as
# a real Tcl list, so a font family with a space in it is still one name.
_FMT_RANGES_TCL = """proc ::noteorg_fmt_ranges {w tags} {
    set out [list [join [lmap name [$w window names] {$w index $name}]]]
    foreach t $tags { lappend out [join [$w tag ranges $t]] }
    return [join $out "\\n"]
}"""


def _fmt_pairs(ranges):
    """A "tag ranges" string as a set of (start, end) index pairs."""
    tokens = ranges.split()
    return set(zip(tokens[0::2], tokens[1::2]))


def _fmt_move_ranges(ranges, src, dst):
    """*ranges*, read with embedded windows at *src*, as they read with the
    windows at *dst* instead: a drawn table's window is a character to Tk,
    and its undo puts the text back without it. Each index is taken to its
    column without windows, then past *dst*'s windows on its line.
    """
    def by_line(windows):
        out = {}
        for w in windows:
            line, _, col = w.partition(".")
            out.setdefault(line, []).append(int(col))
        for cols in out.values():
            cols.sort()
        return out

    old, new = by_line(src), by_line(dst)
    moved = []
    for index in ranges.split():
        line, _, col = index.partition(".")
        if line in old or line in new:
            c = int(col)
            c -= sum(1 for w in old.get(line, ()) if w < c)
            for w in new.get(line, ()):
                if w <= c:
                    c += 1
            index = f"{line}.{c}"
        moved.append(index)
    return " ".join(moved)


def _fmt_window_free(state):
    """A snapshot's formatting as it reads WITHOUT the drawn tables'
    windows -- {tag: ((line, col), (line, col)) pairs}, ranges that meet
    joined -- to tell whether two sides differ by more than where tables
    are drawn. Moved into the other's windows, Tk did not always put an
    index past a window; here its character drops out of both sides."""
    _sig, windows, ranges = state
    cols = {}
    for w in windows:
        line, _, col = w.partition(".")
        cols.setdefault(line, []).append(int(col))
    out = {}
    for tag, spans in ranges:
        points = []
        for index in spans.split():
            line, _, col = index.partition(".")
            c = int(col)
            points.append((int(line),
                           c - sum(1 for w in cols.get(line, ()) if w < c)))
        joined = []
        for lo, hi in sorted(zip(points[0::2], points[1::2])):
            if lo >= hi:
                continue
            if joined and lo <= joined[-1][1]:
                joined[-1] = (joined[-1][0], max(hi, joined[-1][1]))
            else:
                joined.append((lo, hi))
        if joined:
            out[tag] = tuple(joined)
    return out


def _undo_hidden(method):
    """The method's edits never reach the undo stack: recorded, the grids'
    redraws made every second Ctrl+Z undo a drawing. The pipe text stays
    recorded; Tk keeps its stack across undo=False (verified live). Tk's
    modified flag (_undo_tail_held) is left as found, as deleting a grid's
    window sets it.
    """
    @functools.wraps(method)
    def wrapped(self, *args, **kwargs):
        depth = getattr(self, "_undo_hidden_depth", 0)
        self._undo_hidden_depth = depth + 1
        prev = None
        clean = False
        if depth == 0 and hasattr(self, "body_text"):
            try:
                prev = self.body_text.cget("undo")
                clean = not self.body_text.edit_modified()
                self.body_text.configure(undo=False)
            except tk.TclError:
                prev = None
        try:
            return method(self, *args, **kwargs)
        finally:
            self._undo_hidden_depth = depth
            if depth == 0 and prev is not None:
                try:
                    self.body_text.configure(undo=prev)
                    if clean:
                        self.body_text.edit_modified(False)
                except tk.TclError:
                    pass
    return wrapped


def _holds_repeat_off(method):
    """The method's saves hold back the turn-off of a repeat whose days
    hold edits of their own (see _date_and_repeat_to_store): a save no one
    asked for -- the autosave's -- must not move a series' days away."""
    @functools.wraps(method)
    def wrapped(self, *args, **kwargs):
        held = getattr(self, "_holding_repeat_off", False)
        self._holding_repeat_off = True
        try:
            return method(self, *args, **kwargs)
        finally:
            self._holding_repeat_off = held
    return wrapped


def _checklist_rows_current(drawn, items, theme):
    """True when the checklist rows on screen were drawn from exactly this
    list -- the same items, in this order, saying the same -- and in this
    theme: only then may a change touch one row, as each row's tick box and
    bin close over its own item. *drawn* is _render_checklist_items' record.
    """
    return (drawn is not None and drawn["items"] is items
            and drawn["theme"] == theme
            and len(drawn["rows"]) == len(items)
            and all(rec[0] is item
                    and rec[2] == (item.get("text", ""), bool(item.get("done")))
                    for rec, item in zip(drawn["rows"], items)))


def _selection_holds_caret(text_widget):
    """Tk's own test before a key replaces the selection (its
    TextCursorInSelection): there is one, and the caret is in it, ends
    included. A handler that takes a key over from Tk asks it too."""
    try:
        return bool(text_widget.tag_ranges("sel")
                    and text_widget.compare("sel.first", "<=", "insert")
                    and text_widget.compare("insert", "<=", "sel.last"))
    except tk.TclError:
        return False


def _table_edge_holds(app, index):
    """Does a drawn table's edge -- the line break above it, all of it, the
    break below -- hold the body character at *index*? Moved or removed,
    those glue prose onto a row. The one place the boundary is written,
    for the deletion keys and Ctrl+T. May raise tk.TclError.
    """
    b = app.body_text
    for info in getattr(app, "_table_grids", []):
        first = app._grid_first_line(info)
        if first is None:
            continue
        last = first + info["nrows"] - 1
        start = f"{first - 1}.end" if first > 1 else "1.0"
        if (b.compare(start, "<=", index)
                and b.compare(index, "<=", f"{last}.end")):
            return True
    return False



class NoteOrganizer(AttachmentsMixin, CalculatorPanelMixin, CalendarViewMixin,
                    DialogsMixin, NoteListMixin, SettingsPageMixin, SpellingMixin,
                    tk.Tk):
    def __init__(self):
        # Make sure the data layer is open before anything reads it. Safe to
        # call repeatedly; _main() calls it too.
        initialise()
        super().__init__()
        # This screen's scale, for the sizes given in pixels (px): fonts grow,
        # pixels do not. Snapped to quarters (CI's display says 100 dpi, and
        # 1.04 moved every pixel), never below 1.
        self._ui_scale = max(1.0, round(self.winfo_fpixels("1i") / 96 * 4) / 4)
        for name in self._SIZES_AT_100:
            setattr(self, name, self.px(getattr(type(self), name)))
        self.title("Note Organizer")
        # For every window, a popup's too (typed in, it is the active one); on
        # the two window classes, not bind_all, which ran per widget -- 2,132
        # calls an Alt+Tab with 300 notes.
        for window_class in (self.winfo_class(), "Toplevel"):
            self.bind_class(window_class, "<Deactivate>",
                            self._on_app_deactivated, add="+")
            self.bind_class(window_class, "<Activate>",
                            self._on_app_activated, add="+")
        self._deactivate_bound = True
        # ...and the heartbeat, because a popup holding the activation
        # receives neither event when the user switches away.
        self.after(300, self._popup_foreground_watch)
        # core says "that write FAILED" on screen (routes nobody checked hid
        # it), and logs every failure to crash_log.txt.
        from noteorganizer.core import storage as _core_storage
        _core_storage.on_write_failure = self._on_data_write_failure
        # And what a crash log says about the running app (core/diagnostics):
        # how it draws here, how big the notebook is.
        _core_diagnostics.app_details = self._technical_details
        self.geometry("%dx%d" % self._fit_to_screen(900, 600))
        # The smallest window that still looks like the app, measured: at
        # 500x400 the sidebar's fixed parts left the list no room. As at 100%,
        # grown with the scale but never past the screen.
        self.minsize(*self._fit_to_screen(640, 600))
        # On <Map>: before it, wm_frame() names a window Windows throws away,
        # and a fresh launch kept the system colours. On the window ITSELF
        # (_bind_window_only), not once per widget -- 1,939 paints a rebuild.
        self._bind_window_only("<Map>", lambda _e: self._paint_title_bar())
        # On <Map> for the same reason: before the window is mapped,
        # wm_frame() names a different window. See _stop_whole_repaints.
        self._bind_window_only("<Map>", lambda _e: self._stop_whole_repaints())

        self.theme_name = self.load_theme_setting()
        self.colors = THEMES[self.theme_name]
        # Not before this line: the icon follows the accent, and asked for
        # earlier, the window wore Tk's feather until a theme switch.
        self._set_window_icon()
        # Read before the editor is built, so the body text is created in the
        # right font rather than being restyled a moment after it appears.
        self._load_editor_font()
        # Track last-used dark/light for the quick toggle button.
        self._last_dark_theme = self.theme_name if self.theme_name in DARK_THEMES else "dark"
        self._last_light_theme = self.theme_name if self.theme_name in LIGHT_THEMES else "light"

        # Load the user's categories into the live map BEFORE notes load, so
        # normalize_note validates each note's category against the real set.
        CATEGORY_COLORS.clear()
        CATEGORY_COLORS.update(load_categories())

        self._cleanup_report = None  # filled in by load_notes if cleanup ran
        self._categories_adopted = []  # names load_notes brought back from the notes
        self._version_backup_path = None  # filled in by load_notes on a version upgrade
        self._corrupt_notes_report = None  # (flag, preserved-copy path) if the notes file was unreadable
        # A note's uid -> words its full checklist's Add box could not take on
        # the way out, given back when it opens -- said once, until added.
        self._add_box_waiting = {}
        self._waiting_said = {}
        self.notes = self.load_notes()
        self.selected_note_id = None

        # User-defined note templates.
        self.templates = load_templates()

        # Load trash and auto-purge anything past the retention window --
        # but not on a launch whose notes file could not be read: the list
        # is empty then, so no file a note still uses would be spared.
        self.trash = load_trash()
        if not self._notes_file_unread():
            self.trash, purged = purge_expired_trash(self.trash, self.notes)
            if purged:
                save_trash(self.trash)

        # User-chosen colors for individual calendar days (date -> #hex) and
        # emoji markers (date -> up to 3), independent of any note.
        self._load_day_decorations()
        self.current_occurrence_date = None  # set when opened from a calendar day
        self.themed_widgets = []

        # Open note tabs: a list of editor-state snapshots, one per open note.
        # self.active_tab_index points at the one currently shown in the editor.
        self.open_tabs = []
        self.active_tab_index = None
        self._tab_counter = 0  # for stable keys on unsaved new notes

        today = datetime.now()
        self.cal_year = today.year
        self.cal_month = today.month

        self.configure(bg=self.colors["bg"])
        self.build_ui()
        self._bind_global_shortcuts()
        self.bind_all("<ButtonPress-1>", self._release_caret_on_empty_click,
                      add="+")
        # After the window is built: a save that fails says so in a dialog.
        self._maybe_seed_welcome_note()
        self.refresh_note_list()
        self.render_calendar()
        last_open_id = load_settings().get("last_open_note_id")
        if last_open_id is not None:
            last_note = self.find_note(last_open_id)
            if last_note is not None:
                self.open_note_in_tab(last_note)
        self.after(250, self.announce_startup_changes)
        self.after(400, self.maybe_show_reminder)
        self._reminder_day = datetime.now().strftime("%Y-%m-%d")
        self.after(60_000, self._watch_the_day)
        self._last_active_dirty = None
        self.after(600, self._poll_active_dirty)

    # The compositor's attribute numbers (DWM docs): the caption's fill and
    # text, the border, and the glyphs' light or dark -- needed, or a dark
    # caption's close button cannot be seen.
    _DWMWA_USE_IMMERSIVE_DARK_MODE = 20
    _DWMWA_BORDER_COLOR = 34
    _DWMWA_CAPTION_COLOR = 35
    _DWMWA_TEXT_COLOR = 36

    # A bind tag only the main window carries. See _bind_window_only.
    _WINDOW_ONLY_TAG = "NoteOrganizerWindowOnly"

    # The Notes/Calendar tabs (style_ttk): the open one stands 4px taller.
    TAB_PADDING = (16, 8)
    TAB_PADDING_SELECTED = (16, 12, 16, 8)

    def _tab_ring_colour(self):
        """The tabs' focus ring is for the keyboard. After a click it stayed
        dotted on the open tab until the window lost focus, so a click hides
        it -- drawn in the open tab's own fill -- and a key on the tabs, or
        a Tab key arriving at them, shows it in that tab's letters again."""
        if getattr(self, "_tab_ring_hidden", False):
            return self.colors["accent"]
        return self._on_fill("accent")

    def _set_tab_ring(self, shown):
        self._tab_ring_hidden = not shown
        try:
            ttk.Style().configure("TNotebook.Tab",
                                  focuscolor=self._tab_ring_colour())
        except tk.TclError:
            pass

    def _tab_ring_if_tabbed_to(self, event, backwards=False):
        # Asks where the Tab key is taking the keyboard, the way Tk's own
        # traversal does, rather than asking focus_get afterwards.
        # ISSUES_LOG, smaller lessons: _tab_ring_if_tabbed_to.
        try:
            w = event.widget
            target = w.tk_focusPrev() if backwards else w.tk_focusNext()
        except (tk.TclError, KeyError, AttributeError):
            return
        if target is self.notebook:
            self._set_tab_ring(True)

    def _bind_window_only(self, sequence, func):
        """Bind `func` to `sequence` on the main window itself, never on the
        widgets inside it, through a tag of its own: every widget carries
        the window's tag, and a <Map> bound there repainted the title bar
        1,939 times a rebuild. Before moving a handler here, ask what the
        storm was doing for it -- the calendar's step rode on it.
        """
        tags = self.bindtags()
        if self._WINDOW_ONLY_TAG not in tags:
            self.bindtags((tags[0], self._WINDOW_ONLY_TAG) + tuple(tags[1:]))
        return self.bind_class(self._WINDOW_ONLY_TAG, sequence, func, add="+")

    # Class-level sizes as at 100%, holding text or a drawn mark, set again
    # by __init__ at this screen's scale for their readers; a literal size
    # where it is used goes through px().
    _SIZES_AT_100 = (
        "LIST_DRAW_WIDTH", "HEADER_HEIGHT", "CARD_CHECK",          # note list
        "SETTINGS_NAV_WIDTH", "SETTINGS_CONTENT_MAX",              # Settings
        "CAL_GRID_HEIGHT", "CAL_ROW_MIN", "CAL_CHIP_WRAP",         # calendar
        "CHECKLIST_WRAP", "CHECKLIST_SHORT", "TICK_BOX",           # checklist
        "INDENT_STEP",                                             # paragraphs
    )

    def px(self, n):
        """*n* pixels as drawn at 100%, in this screen's pixels -- for sizes
        holding text or a drawn mark, not padding (a tighter gap reads fine,
        a cut word does not). At 100% exactly *n*, so the older checks
        still prove nothing moved there."""
        return int(round(n * self._ui_scale))

    def _scale_drawing(self, canvas, tag="all"):
        """Grow what was just drawn on *canvas*, in coordinates as at 100%,
        to this screen's scale: every position and size, and the thickness
        of every line, which Tk's own scale() leaves as it was. Nothing at
        100%. Call it once per drawing -- after a delete and redraw, never
        twice over the same items, or they grow again."""
        scale = self._ui_scale
        if scale == 1:
            return
        canvas.scale(tag, 0, 0, scale, scale)
        for item in canvas.find_withtag(tag):
            try:
                width = float(canvas.itemcget(item, "width") or 0)
            except (tk.TclError, ValueError):
                continue                       # an image: it has no width
            if width:
                canvas.itemconfigure(item, width=width * scale)

    def _screen_room(self):
        """The width and height a window can take on the main screen: its
        work area (the screen less the taskbar), less the window's own
        frame and title bar."""
        width, height = self.winfo_screenwidth(), self.winfo_screenheight()
        if sys.platform.startswith("win"):
            try:
                import ctypes
                import ctypes.wintypes
                area = ctypes.wintypes.RECT()
                spi_getworkarea = 0x0030
                if ctypes.windll.user32.SystemParametersInfoW(
                        spi_getworkarea, 0, ctypes.byref(area), 0):
                    width = area.right - area.left
                    height = area.bottom - area.top
            except Exception:                         # noqa: BLE001
                self._log_swallowed("screen work area")
        return width - self.px(16), height - self.px(48)

    def _fit_to_screen(self, width, height):
        """A window size given at 100%, at this screen's scale, and never
        bigger than the screen can show (see _screen_room)."""
        room_w, room_h = self._screen_room()
        return (max(1, min(self.px(width), room_w)),
                max(1, min(self.px(height), room_h)))

    # The two window classes Tk registers on Windows, and the class styles
    # that make Windows repaint a window WHOLE whenever its size changes.
    _TK_WINDOW_CLASSES = ("TkTopLevel", "TkChild")
    _CS_WHOLE_REPAINT = 0x0001 | 0x0002         # CS_VREDRAW | CS_HREDRAW

    def _stop_whole_repaints(self):
        """Stop Windows repainting every window whole on each size change:
        Tk's classes carry CS_HREDRAW/CS_VREDRAW, and each step of a resize
        cost 72 ms, while its widgets redraw themselves anyway (10 ms
        without, the photographs identical). On <Map> (see _paint_title_bar);
        Windows only, and a failed question changes nothing.
        """
        if not sys.platform.startswith("win"):
            return
        try:
            import ctypes
            user32 = ctypes.windll.user32
            get_style = user32.GetClassLongPtrW
            set_style = user32.SetClassLongPtrW
            get_style.restype = set_style.restype = ctypes.c_size_t
            get_style.argtypes = [ctypes.c_void_p, ctypes.c_int]
            set_style.argtypes = [ctypes.c_void_p, ctypes.c_int, ctypes.c_size_t]
            gcl_style = -26
            name = ctypes.create_unicode_buffer(64)
            windows = [int(self.wm_frame(), 16), self.winfo_id()]
            if getattr(self, "main_canvas", None) is not None:
                windows.append(self.main_canvas.winfo_id())   # measured: TkChild
            for hwnd in windows:
                user32.GetClassNameW(ctypes.c_void_p(hwnd), name, 64)
                if name.value not in self._TK_WINDOW_CLASSES:
                    continue
                style = get_style(hwnd, gcl_style)
                if style & self._CS_WHOLE_REPAINT:
                    set_style(hwnd, gcl_style, style & ~self._CS_WHOLE_REPAINT)
        except Exception:                             # noqa: BLE001
            self._log_swallowed("window class repaint styles")

    def _paint_title_bar(self):
        """Ask Windows to draw the title bar in the current theme -- the
        native caption kept, with its snapping, system menu and accessibility,
        which a hand-drawn one would lose; only its colours change. Windows
        11 only, silently nothing elsewhere; never a reason not to open.
        """
        if not sys.platform.startswith("win"):
            return
        try:
            import ctypes

            def colorref(hex_colour):
                # Windows wants 0x00BBGGRR -- a CSS hex, byte-reversed.
                r = int(hex_colour[1:3], 16)
                g = int(hex_colour[3:5], 16)
                b = int(hex_colour[5:7], 16)
                return (b << 16) | (g << 8) | r

            # winfo_id() is Tk's child window; the caption belongs to the
            # frame above it, which is what wm_frame names.
            handle = int(self.wm_frame(), 16)
            dwm = ctypes.windll.dwmapi
            dark = self.theme_name in DARK_THEMES
            for attribute, value in (
                    (self._DWMWA_USE_IMMERSIVE_DARK_MODE, int(dark)),
                    (self._DWMWA_CAPTION_COLOR, colorref(self.colors["bg"])),
                    (self._DWMWA_TEXT_COLOR, colorref(self.colors["text"])),
                    (self._DWMWA_BORDER_COLOR,
                     colorref(self.colors["accent"]))):
                payload = ctypes.c_int(value)
                # c_void_p, not wintypes.HWND: `import ctypes` does not
                # bring ctypes.wintypes with it, and a handle is a
                # pointer either way.
                dwm.DwmSetWindowAttribute(
                    ctypes.c_void_p(handle), ctypes.c_uint(attribute),
                    ctypes.byref(payload), ctypes.sizeof(payload))
        except Exception:                             # noqa: BLE001
            self._log_swallowed("title bar colours")

    def _icon_files(self):
        """The icon files for the current theme, best first: named after the
        accent (`icon_d97a2b.ico`), not the theme, so no table can drift;
        the plain `icon.ico` when a colour has none.
        """
        # getattr: called once before the colours existed; the default icon
        # beats none.
        colors = self.colors or {}
        accent = (colors.get("accent") or "").lstrip("#").lower()
        stems = ([("icon_%s.ico" % accent, "icon_%s.png" % accent)]
                 if accent else [])
        stems.append(("icon.ico", "icon_256.png"))
        return stems

    def _set_window_icon(self):
        """Put the app's icon on the window, in the theme's colour; wrapped
        end to end, a failure going to the crash log. The .ico for Windows,
        a PNG for X11, which takes no .ico. Set twice on Windows: `default=`
        is for windows made later, the plain form repaints this one.
        """
        try:
            for ico_name, png_name in self._icon_files():
                ico = bundled_file("assets", ico_name)
                if os.path.exists(ico):
                    try:
                        self.iconbitmap(ico)
                        self.iconbitmap(default=ico)
                        return
                    except tk.TclError:
                        pass      # not Windows, or a Tk built without it
                png = bundled_file("assets", png_name)
                if os.path.exists(png):
                    # Held on self: Tk keeps no reference of its own, and
                    # a collected PhotoImage silently blanks the icon.
                    self._window_icon = tk.PhotoImage(file=png)
                    self.iconphoto(True, self._window_icon)
                    return
        except Exception:                             # noqa: BLE001
            self._log_swallowed("window icon")

    # The longest title typed or pasted in: tk.Entry slows with the square
    # of what it holds (a keystroke 38 ms at 10,000 characters, 3.5 s at
    # 100,000), and a document pasted by accident froze the field.
    TITLE_MAX_LEN = 200

    def _title_within_limit(self, proposed, current=""):
        """Validator for the title field: reject an edit past the cap. A
        title already longer -- a share code's, a backup's -- still
        shortens: Backspace was refused on one, as being too long."""
        if getattr(self, "_setting_title", False):
            return True                      # a stored title being loaded
        if len(proposed) <= self.TITLE_MAX_LEN or len(proposed) < len(current):
            return True
        # Deferred: Tk turns validation off if the validate command touches
        # a widget while it runs, and the status bar is a widget.
        self.after_idle(
            lambda: self._say_by_the_box(
                self.title_entry,
                f"A note title can be up to {self.TITLE_MAX_LEN} characters"))
        return False

    def _limit_entry(self, entry, limit, what):
        """Keep *entry* to *limit* characters, as the title's box is kept: a
        key past it is refused, a paste past it shortened to fit, and the
        status bar says so -- or, where that is out of sight, the box's own
        popup (_say_by_the_box). A value already longer -- a template from a
        backup -- still shortens. Registered on the entry, so the command
        goes with it."""
        def within(proposed, current):
            if len(proposed) <= limit or len(proposed) < len(current):
                return True
            # Deferred, as for the title: Tk turns validation off if the
            # command touches a widget while it runs.
            self.after_idle(lambda: self._say_by_the_box(
                entry, f"{what} can be up to {limit:,} characters"))
            return False
        entry.configure(validate="key",
                        validatecommand=(entry.register(within), "%P", "%s"))

        def put(raw, over_selection):
            # Shortened to fit, as the title's paste is: refused whole, it
            # looked as if it had failed. In one go -- Tk's own, off X11,
            # deletes the selection and inserts as two edits.
            chosen = _entry_selected(entry) if over_selection else 0
            room = limit - (len(entry.get()) - chosen)
            if len(raw) <= room:
                return None
            try:
                # Nothing taken out unless something goes in: a selection
                # deleted first was lost when nothing then fitted (round 10).
                if room > 0:
                    if chosen:
                        entry.delete("sel.first", "sel.last")
                    entry.insert("insert", raw[:room])
                    self.tk.call("tk::EntrySeeInsert", entry)
            except tk.TclError:
                return "break"
            if room > 0 and not raw[room:].strip():
                # Only the paste's own spaces were left out: nothing to say, as at the title.
                return "break"
            self._say_by_the_box(entry, (
                f"Pasted text shortened: {what[:1].lower()}{what[1:]} can be up "
                f"to {limit:,} characters" if room > 0
                else f"{what} can be up to {limit:,} characters"))
            return "break"

        def paste(_event=None):
            # Each line break one character, as Tk's own paste puts it in
            # (_cap_paste): Windows' clipboard keeps CR LF, so a paste that
            # fitted was weighed as too long, and the CR went in with it.
            raw, _cut = self._clipboard_text(entry)
            return None if raw is None else put(raw, over_selection=True)

        def paste_selection(event):
            # A middle-click, where the pointer is, as Tk's own puts it --
            # which put it in past the limit, refused whole (round 10).
            try:
                if self.tk.eval("expr {[info exists ::tk::Priv(mouseMoved)]"
                                " && $::tk::Priv(mouseMoved)}") == "1":
                    return None
                raw, _cut = self._cap_paste(entry.selection_get(selection="PRIMARY"))
                entry.icursor(self.tk.call("tk::EntryClosestGap", entry, event.x))
            except tk.TclError:
                return None
            done = put(raw, over_selection=False)
            if done:
                entry.focus_set()
            return done
        entry.bind("<<Paste>>", paste, add="+")
        entry.bind("<<PasteSelection>>", paste_selection, add="+")

    def _say_by_the_box(self, box, text):
        """*text* on the status line, and while that is out of sight
        (_in_sight: behind Settings, or below the scrolled editor) on the
        popup *box*'s own line (``_say_here``) or a banner -- a cut paste
        went unsaid. The words stand as long as a banner, or the paste's
        autosave wrote over them."""
        self.set_status(text)
        self._box_words_until = time.monotonic() + self.TOAST_MS / 1000
        try:
            if self._in_sight(self.status_lbl):
                return
            say_here = getattr(box.winfo_toplevel(), "_say_here", None)
        except tk.TclError:
            return
        if say_here is not None:
            say_here(text)
        elif self._offer_on_banner():
            # Beneath an Undo still on offer, not over it, nor quiet under
            # it: the line it would have stayed on is the one out of sight.
            self._show_words_beneath(text)
        else:
            # The newest words on the banner, and no older ones under it.
            self._hide_words_beneath()
            self._show_toast(text, kind="info")

    # How close to the cap the counter starts showing. Far enough out to be
    # a warning rather than a surprise, close enough that an ordinary title
    # never sees it.
    TITLE_COUNT_FROM = 40

    # The search box's hint, written once: three copies could drift, and
    # the app would filter by its own hint.
    SEARCH_PLACEHOLDER = "Search notes..."

    def _search_query(self):
        """What the user is searching for, folded as the notes are
        (fold_for_search), ends trimmed (a phone's suggested word brings a
        space; the apps search alike). Empty while the box shows only its
        hint, which `search_var` reads like a query.
        """
        typed = self.search_var.get()
        return "" if typed == self.SEARCH_PLACEHOLDER else fold_for_search(typed.strip())

    def _refresh_search_clear(self):
        """Show the ✕ only while the box holds something typed, spaces too.

        A clear button that is always there invites clearing an empty box,
        and one sitting beside the hint text suggests the hint is something
        you could remove.
        """
        btn = self.search_clear_btn
        if btn is None:
            return                      # called while the row is being built
        if self.search_var.get() not in ("", self.SEARCH_PLACEHOLDER):
            if not self._is_placed(btn):
                btn.pack(side="right", padx=(0, 6))
        elif self._is_placed(btn):
            btn.pack_forget()

    def _clear_search(self):
        """Empty the search box and put the full list back, at once.

        The hint is NOT written back here. The box takes the focus instead,
        which is the state add_placeholder already gives a box someone has
        clicked into, and its own <FocusOut> puts the hint back when they
        look elsewhere — one mechanism for the hint rather than two.
        """
        self.search_var.set("")
        try:
            self.search_entry.focus_set()
        except tk.TclError:
            pass
        # A cleared search snaps back now: the 180 ms debounce is for typing,
        # and this is one event.
        if self._search_debounce_job is not None:
            try:
                self.after_cancel(self._search_debounce_job)
            except (tk.TclError, ValueError):
                pass
            self._search_debounce_job = None
        self.refresh_note_list()

    # One sentence for one fact, said alike in the sidebar and the editor: a
    # code carries no files, and the sentence names where files DO travel.
    SHARE_ATTACHMENT_WARNING = (
        "⚠ A code carries the text, not attached files — "
        "use Settings → Backup → Export for those.")

    def _refresh_title_count(self, event=None):
        """Show how much title is left, once there is little enough of it.

        Also called after a note is loaded, so opening one that is already
        near the cap says so straight away rather than waiting for a
        keystroke to reveal it.
        """
        used = len(self.title_entry.get())
        if self._title_is_placeholder():
            used = 0
        if used < self.TITLE_MAX_LEN - self.TITLE_COUNT_FROM:
            if self._is_placed(self.title_count_lbl):
                self.title_count_lbl.pack_forget()
            return
        self.title_count_lbl.config(
            text=f"{used}/{self.TITLE_MAX_LEN}",
            fg=self.colors["danger_text"] if used >= self.TITLE_MAX_LEN
            else self.colors["subtext"],
        )
        if not self._is_placed(self.title_count_lbl):
            # Before the category button, which is packed to the right first,
            # so the counter sits between the title and it rather than past
            # the edge of the row.
            self.title_count_lbl.pack(side="left", padx=(8, 0))

    def _title_is_placeholder(self):
        """True while the field is showing its grey 'Note title...' prompt."""
        return self.title_entry.get() == "Note title..."

    def _insert_title(self, text):
        """Put a stored title into the field, cap or no cap: validation fires
        on inserts too, and an older, longer title was cut and saved back
        shortened. Loading a note must never edit it.
        """
        self._setting_title = True
        try:
            self.title_entry.insert(0, text)
        finally:
            self._setting_title = False
        self._refresh_title_count()

    # The breaks a paste into the title's one line joins: a line break or a
    # tab. One character, never "\s*" around it: that tried every place in a
    # run of spaces, and 40,000 of them froze the window 5 s (round 9).
    _TITLE_PASTE_BREAK = re.compile(r"[\t\n\x0b\x0c\r\x1c-\x1e\x85\u2028\u2029]")

    @classmethod
    def _title_paste_line(cls, pasted):
        """*pasted* on one line: a break, with the spaces around it, is one
        space between words and nothing at either end; every other space
        goes in as it was copied. Linear in the paste's length."""
        parts = cls._TITLE_PASTE_BREAK.split(pasted)
        parts[1:] = [part.lstrip() for part in parts[1:]]
        parts[:-1] = [part.rstrip() for part in parts[:-1]]
        return " ".join(part for part in parts if part)

    def _on_title_paste(self, event=None):
        """Paste into the title, trimmed to fit rather than refused.

        A validator can only accept or reject a change whole, so pasting
        something long past the cap would otherwise leave the field empty --
        which looks like the paste failed rather than like it was shortened.
        """
        try:
            pasted = self.clipboard_get()
        except tk.TclError:
            return "break"
        return self._title_take_paste(pasted, over_selection=True)

    def _on_title_paste_selection(self, event):
        """A middle-click into the title: the selection, put where the
        pointer is as Tk's own binding puts it, on one line and within the
        cap as any paste into it. Tk's own put its line breaks in (round 10)."""
        entry = self.title_entry
        try:
            # Tk's own pastes nothing after a drag with the middle button,
            # which scrolled the box instead.
            if self.tk.eval("expr {[info exists ::tk::Priv(mouseMoved)]"
                            " && $::tk::Priv(mouseMoved)}") == "1":
                return "break"
            entry.icursor(self.tk.call("tk::EntryClosestGap", entry, event.x))
            pasted = entry.selection_get(selection="PRIMARY")
        except tk.TclError:
            pasted = None
        if pasted is not None:
            self._title_take_paste(pasted, over_selection=False)
        entry.focus_set()
        return "break"

    def _title_take_paste(self, pasted, over_selection):
        """*pasted* into the title at the caret, over its selection when
        *over_selection*: cut to the room the cap leaves, the room measured
        before anything is taken out -- a selection deleted first was lost
        when nothing then fitted (round 10)."""
        # No more of it is read than any paste reads (_cap_paste).
        pasted, cut = self._cap_paste(pasted)
        chosen = _entry_selected(self.title_entry) if over_selection else 0
        room = self.TITLE_MAX_LEN - (len(self.title_entry.get()) - chosen)
        if room <= 0:
            self._say_by_the_box(
                self.title_entry,
                f"A note title can be up to {self.TITLE_MAX_LEN} characters")
            return "break"
        if chosen:
            self.title_entry.delete("sel.first", "sel.last")
        # Weighed as it goes in, on one line: a copied line break read as cut.
        # Only breaks are joined -- split() made "fresh " + "milk" "freshmilk".
        whole = self._title_paste_line(pasted)
        clipped = whole[:room]
        self.title_entry.insert("insert", clipped)
        self._refresh_title_count()
        # Shortened only if words were left out: a paste's own trailing
        # space, all the cap took, was said to be (round 9).
        if cut or whole[room:].strip():
            self._say_by_the_box(
                self.title_entry,
                f"Pasted title shortened to {self.TITLE_MAX_LEN} characters")
        return "break"

    def _schedule_autosave(self, event=None, skip_word_count=False):
        """Debounced auto-save: (re)start a short timer on every edit, so a
        pause saves the note. `skip_word_count` leaves the count, which reads
        the whole body, to the timer -- emoji inserted fast lagged -- as it
        does while the find bar shows hits (_count_waits_for_pause)."""
        # Every edit passes here, whatever made it, so the find bar hears of
        # each: a key's release alone left a menu's paste or a toolbar's list
        # stepping to stale places (round 10).
        self._find_on_body_edit()
        if not skip_word_count:
            if self._count_waits_for_pause():
                self._word_count_due = True
            else:
                try:
                    self.update_word_count()
                except Exception:
                    self._log_swallowed("autosave: schedule-time word count")
        self._cancel_pending_autosave()
        self._autosave_job = self.after(500, self._autosave_now)

    def _count_waits_for_pause(self):
        """Whether a key's word count waits for the pause's (the autosave's
        catch-up, or the find bar closing): while the bar shows hits, each
        read of their lines costs the square of their toggles, and a read a
        key held every key back (final audit, round 10)."""
        return bool(getattr(self, "_find_open", False)
                    and getattr(self, "_find_matches", None))

    # Where the edits no key makes are heard: first in a box's bindtags, so a
    # handler of the box's own that returns "break" cannot hide one.
    _NO_KEY_EDIT_TAG = "EditWithoutKey"

    def _after_edits_without_a_key(self, widget, then):
        """Run *then* once an edit no key made -- the menu's Cut or Paste, a
        middle-click -- has landed in *widget*. The work a key's release
        sets off (the autosave, the counts, the find bar) never heard of
        them: a right-click Paste was saved only when the note was left."""
        widget._after_edit_without_key = then
        if self._NO_KEY_EDIT_TAG not in widget.bindtags():
            widget.bindtags((self._NO_KEY_EDIT_TAG,) + tuple(widget.bindtags()))
        if not getattr(self, "_no_key_edits_bound", False):
            self._no_key_edits_bound = True
            for virtual in ("<<Cut>>", "<<Paste>>", "<<Clear>>", "<<PasteSelection>>"):
                self.bind_class(self._NO_KEY_EDIT_TAG, virtual, self._edit_without_key)

    def _edit_without_key(self, event):
        then = getattr(event.widget, "_after_edit_without_key", None)
        if then is not None:
            self.after_idle(lambda: self._still_alive() and then())

    def _cancel_pending_autosave(self):
        """Drop a scheduled autosave, if one is waiting."""
        if getattr(self, "_autosave_job", None) is not None:
            try:
                self.after_cancel(self._autosave_job)
            except (tk.TclError, ValueError):
                pass
            self._autosave_job = None

    def _log_swallowed(self, where):
        """A guarded spot chose to carry on: leave the trace a bare `pass`
        never did (audit Z02-F04 -- the autosave could stop in silence). The
        crash log, no toast, once per spot a session, as a guard on the
        typing path can be hit at every keystroke."""
        seen = getattr(self, "_swallowed_seen", None)
        if seen is None:
            seen = self._swallowed_seen = set()
        if where in seen:
            return
        seen.add(where)
        import traceback
        _core_diagnostics.append_crash_log(
            "swallowed: %s" % where, traceback.format_exc(), APP_DIR)

    @_holds_repeat_off
    def _autosave_now(self):
        """Run an auto-save if the current editor content is worth saving and
        actually differs from what's on disk. A repeat turned off on a series
        whose days hold edits of their own is held back from it (see
        _date_and_repeat_to_store): leaving the note or Save makes that save."""
        # Cancelled, not forgotten: a timer only set to None ran untracked and
        # passed it on -- 28 stray saves a qa1 run, one splitting a held
        # BackSpace's undo step.
        self._cancel_pending_autosave()
        if not self._still_alive():
            return
        # A note gone while the timer waited: no "Note missing" dialog from a
        # save nobody asked for (as _flush_autosave guards).
        if self.selected_note_id is not None and self.find_note(self.selected_note_id) is None:
            return
        # Before any early return below: an editor that matches the note has
        # nothing to save.
        self._say_nothing_is_left_out()
        # A day of a series saves here like any note, to that day, asking
        # nothing: it waited for the old question, and a category picked for
        # one day seemed to do nothing (field report).
        try:
            st, body_read = self._capture_and_read()
        except Exception:
            self._log_swallowed("autosave: capture_editor_state")
            body_read = None
        # Catch the word count up now, in case rapid edits (e.g. inserting
        # several emojis in a row) skipped recomputing it on every click --
        # from the capture's read: each read of a long styled line is dear.
        try:
            self.update_word_count(body_read)
        except Exception:
            self._log_swallowed("autosave: catch-up word count")
        if body_read is None:
            return
        # An empty NEVER-SAVED note is not saved (junk at every New Note); a
        # saved one emptied is, deliberately (this gate threw it away: T0-5).
        if not self._editor_state_has_content(st) and not self._editing_saved_note():
            return
        # Only save if something actually changed vs. the saved version.
        try:
            if self.editor_state_matches_saved(st):
                return
        except Exception:
            self._log_swallowed("autosave: editor_state_matches_saved")
        # Reuse the normal save path, but mark it as automatic so the status
        # message is gentle rather than a loud "Saved!".
        self.save_current_note(auto=True, body_read=body_read)

    def _repeat_off_waits(self):
        """Whether the editor turns off the repeat of a series whose days
        hold edits of their own -- a save a timer never makes (see
        _autosave_now)."""
        if self.selected_note_id is None or self.selected_freq_key():
            return False
        note = self.find_note(self.selected_note_id)
        return bool(note is not None and is_recurring(note)
                    and (note.get("overrides") or note.get("exceptions")))

    def _say_nothing_is_left_out(self):
        """Put the status line right once nothing is left out any more: a
        value put back leaves nothing to save, and "-- except the date ..."
        stayed. The save's own words come back (kept by save_current_note)."""
        said = getattr(self, "_status_names_left_out", None)
        if not said:
            return
        try:
            left_out = self._date_and_repeat_to_store()[2]
        except Exception:
            self._log_swallowed("autosave: left-out status check")
            return
        if not left_out:
            self._status_names_left_out = None
            self.set_status(said)

    def _still_alive(self):
        """True if the app window is still around and usable. Checked before
        any code that would otherwise touch a Tkinter widget from a timer
        callback that might fire after the app has closed. winfo_exists()
        itself can raise once the whole Tk application (not just one widget)
        has been torn down, not only when a single widget is gone — so the
        existence check itself needs a guard, not just what comes after it."""
        try:
            return bool(self.winfo_exists())
        except tk.TclError:
            return False

    def _is_placed(self, widget):
        """Whether a widget has its place in the layout -- packed, gridded or
        placed -- as every show/hide decision means to ask. Not
        winfo_ismapped(), which says no until first drawn and while its page
        is hidden: a hidden button woke up with its page. The one-definition
        gate keeps winfo_ismapped() out of these decisions."""
        try:
            return bool(widget.winfo_manager())
        except tk.TclError:
            return False

    def _poll_active_dirty(self):
        """Cheaply keep the active tab's dirty dot in sync while the user types,
        without binding every widget. Only redraws when the state flips."""
        try:
            if self.open_tabs and self.active_tab_index is not None and len(self.open_tabs) > 1:
                st = self.capture_editor_state()
                dirty = not self.editor_state_matches_saved(st)
                if dirty != self._last_active_dirty:
                    self._last_active_dirty = dirty
                    self.open_tabs[self.active_tab_index]["state"] = st
                    self._sync_editor_snapshot()
        except (tk.TclError, Exception):
            pass
        # Rescheduled only while the window lives: after() on a destroyed root
        # raises (a script closing the app under the timer).
        if self._still_alive():
            self.after(600, self._poll_active_dirty)

    # ---------- Settings (theme) persistence ----------
    def load_theme_setting(self):
        """The saved theme, or the default if it names one that no longer exists."""
        theme = get_setting("theme")
        return theme if theme in THEMES else "dark"

    def save_theme_setting(self):
        save_setting("theme", self.theme_name)

    def load_username(self):
        return get_setting("username", "", expect=str)

    def save_username(self, name):
        save_setting("username", name.strip())

    def _refresh_greeting(self):
        """Show 'Hi <name>,' if a name is set in Settings, otherwise a gentle
        nudge to set one. Recomputed whenever the name changes."""
        name = self.load_username()
        if name:
            self.greeting_lbl.config(text=f"Hi {name},")
        else:
            self.greeting_lbl.config(text="")

    def _remember_last_open_note(self, note_id):
        """Persist which note is currently open, so the app reopens directly
        into it next launch instead of always starting on a blank editor."""
        save_setting("last_open_note_id", note_id)

    # ---------- One-time startup notice ----------
    def announce_startup_changes(self):
        """Shown once: where the notes now live, and what cleanup removed."""
        if not self._still_alive():
            return
        lines = []

        if self._corrupt_notes_report is not None:
            msg = (
                "⚠ Your notes file could not be read this time, so the app "
                "started with an empty list. Your notes did NOT delete "
                "themselves — the file on disk was unreadable (a bad "
                "shutdown, a disk problem, or saving it from another "
                "program can do this)."
            )
            if self._corrupt_notes_report:
                msg += (
                    "\n\nThe unreadable file was preserved, untouched, at:\n"
                    f"{self._corrupt_notes_report}\n\n"
                    "It may be repairable — keep it safe and restore from "
                    "your most recent backup (Settings → Backup), or ask "
                    "for help with the preserved file."
                )
            else:
                # Nothing writes over it this run (storage._preserve_corrupt):
                # said so, with the likeliest cause, a file another program
                # holds, which opening the app again usually cures.
                msg += (
                    "\n\nA copy of it could not be kept either — another "
                    "program may be holding the file. Note Organizer will "
                    "not save anything over it in this session: anything "
                    "you write now is kept only by Settings → Backup → "
                    "Export. Close Note Organizer and open it again; if "
                    "this comes back, back up notes_data.json from the data "
                    "folder first."
                )
            lines.append(msg)

        # Set by load_settings on an unreadable settings.json; said once,
        # and the Trash keeps everything until a window is chosen again.
        if _core_paths.writes_held(SETTINGS_FILE):
            # Not damaged: refused, most likely held by another program. Its
            # defaults stand in, and none of them is written over the file.
            lines.append(
                "Your settings file couldn't be opened — another program may "
                "be holding it. Note Organizer uses its own defaults this "
                "time, saves no setting until it is opened again, and removes "
                "nothing from the Trash.")
        elif get_setting(TRASH_WINDOW_UNKNOWN) is True:
            save_setting(TRASH_WINDOW_UNKNOWN, "told")
            lines.append(
                "Your settings file couldn't be read, so Note Organizer "
                "doesn't know how long you chose to keep deleted notes. "
                "Nothing will be removed from the Trash until you choose "
                "again in Settings → Recently deleted.")
        # A Trash or templates file held the same way showed an empty page,
        # and every delete answered "Is the disk full?" (round 4).
        held = [what for path, what in ((TRASH_FILE, "the Trash (Recently deleted)"),
                                        (TEMPLATES_FILE, "your templates"))
                if _core_paths.writes_held(path)]
        if held:
            them = len(held) > 1
            lines.append(
                f"{' and '.join(held).capitalize()} couldn't be opened — another "
                f"program may be holding {'them' if them else 'the file'} — so "
                f"this time {'they show' if them else 'it shows'} empty, and "
                "nothing is saved there until Note Organizer is opened again. "
                "Nothing is lost.")

        # A template written when Windows signed out, past the most kept.
        not_kept = get_setting("template_not_kept", None, expect=str)
        if not_kept:
            save_setting("template_not_kept", None)
            lines.append(
                f"The template “{one_line(not_kept, 80)}”, being written when "
                f"Windows signed out or shut down, was not kept: you already "
                f"had {MAX_TEMPLATES:,} templates, which is the most Note "
                "Organizer keeps.")

        # Recorded by _settle_background_work_at_close, said once.
        cut = get_setting("backup_cut_short", None, expect=dict)
        if cut:
            save_setting("backup_cut_short", None)
            name = os.path.basename(str(cut.get("file") or "")) or "the backup"
            when = ("Windows signed out or shut down"
                    if cut.get("when") == "session" else "Note Organizer closed")
            if cut.get("kind") == "import":
                # Ended while its questions waited: what it copied goes now --
                # or, on a run holding none of the notes, at the next start
                # that does, the word kept for it and said once (round 8).
                self._drop_left_import(cut)
                if self._notes_file_unread() and cut.get("copied"):
                    save_setting("backup_cut_short", dict(cut, temp_dir="", said=True))
                if not cut.get("said"):
                    lines.append(
                        f"The import of {name} was cut short when {when}, so "
                        "nothing from it was kept: no notes and no files. To bring "
                        "it in, import it again (Settings → Backup → Import).")
            elif cut.get("kind") == "export_partial":
                # Finished as the window closed, its own message unsaid.
                count = cut.get("session_only")
                if isinstance(count, int) and not isinstance(count, bool):
                    lines.append(
                        f"The backup saved to {name} as Note Organizer closed "
                        f"holds only the {count} note(s) written in that "
                        "session, not your notes file, which could not be "
                        "opened then. Settings → Backup → Import brings its "
                        "notes in beside yours.")
                named = cut.get("left_out")
                left = ([n for n in named if isinstance(n, str)]
                        if isinstance(named, list) else [])
                if left:
                    lines.append(
                        f"The export to {name} finished as Note Organizer "
                        "closed, but not all of it. " + self._left_out_said(left))
            else:
                # A process ended mid-export leaves its unfinished file
                # beside the target (export_data writes there first).
                leftover = str(cut.get("file") or "") + ".tmp"
                if cut.get("file") and os.path.isfile(leftover):
                    try:
                        os.remove(leftover)
                    except OSError:
                        pass
                lines.append(
                    f"The export to {name} was cut short when {when}, so no "
                    "new backup was made. A file already there under that name "
                    "is as it was. To make one, export again (Settings → "
                    "Backup → Export).")

        if VERSION_CHANGE:
            direction, old, new = VERSION_CHANGE
            if direction == "up":
                msg = (
                    f"Updated to version {new} (from {old}).\n\n"
                    "Your notes came through the update."
                )
                if self._version_backup_path:
                    msg += (
                        "\n\nAs an extra safety net, a backup of your notes "
                        "from just before this update was saved to:\n"
                        f"{self._version_backup_path}"
                    )
                elif getattr(self, "_version_backup_failed", False):
                    msg += (
                        "\n\nThe extra backup of your notes from just before "
                        "this update could not be saved, so there is none — "
                        "the disk may be full. Settings → Backup → Export "
                        "makes one.")
                lines.append(msg)
            else:
                lines.append(
                    f"⚠ You're running an older version ({new}) over data last "
                    f"used with {old}. Everything should still work, but if "
                    "anything looks off, open them with the newer version."
                )

        made = getattr(self, "_set_aside_at_start", 0)
        if made:
            # Both reasons said: a day the note deleted is one (round 21), and
            # the line once named only the other. The phone's says the same.
            lines.append(
                f"Some days of a repeating note had earlier text that only an older "
                f"copy of it kept: those days now show other text, or were deleted. "
                f"It is kept as {made} note{'s' if made != 1 else ''} of "
                f"{'their' if made != 1 else 'its'} own, each on its day, titled with "
                "the day's or the series' name and \"(earlier text)\".")

        if STORAGE_WARNING:
            lines.append("⚠ " + STORAGE_WARNING)

        if MIGRATION_INFO:
            # Said by the migration itself, per case, only what is true (a
            # fixed tail here was false in source mode, and jargon).
            lines.append(MIGRATION_INFO)

        if self._categories_adopted:
            # settings.json had lost track of the notes' categories: said, as
            # their colours are now the defaults.
            count = len(self._categories_adopted)
            shown = self._categories_adopted[:8]
            listed = "\n".join(f"  • {name}" for name in shown)
            if count > len(shown):
                listed += f"\n  • …and {count - len(shown)} more"
            lines.append(
                f"{count} categor{'y' if count == 1 else 'ies'} your notes "
                "are filed under had gone missing from the settings, so "
                f"{'it was' if count == 1 else 'they were'} added back, "
                "with default colours:\n"
                f"{listed}\n\n"
                "Your notes stayed where you filed them. Settings → "
                "Categories changes the colours.")

        if PURGED_DIRS:
            listed = "\n".join(f"  • {d}" for d in PURGED_DIRS)
            lines.append(
                "Removed leftover copies of your notes from:\n"
                f"{listed}\n\n"
                "Each one was checked first — nothing was deleted unless every "
                "note and attachment in it already existed in your notes folder."
            )

        # Said only when the pass DID something: a fresh install's first
        # screen read "0 note(s) remain, IDs renumbered 1–0".
        if self._cleanup_report and (
                self._cleanup_report[0].get("empty_removed")
                or self._cleanup_report[0].get("duplicates_removed")):
            stats, backup_path = self._cleanup_report
            # Plain words: this removes notes PERMANENTLY, once worded as a
            # "Cleanup pass" under "setup complete".
            removed_bits = []
            if stats["empty_removed"]:
                removed_bits.append(f"{stats['empty_removed']} empty note(s)")
            if stats["duplicates_removed"]:
                removed_bits.append(
                    f"{stats['duplicates_removed']} exact duplicate(s)")
            summary = (
                f"While tidying up, {' and '.join(removed_bits)} "
                f"were removed.\n"
                f"{stats['after']} of your {stats['before']} note(s) remain."
            )
            if backup_path:
                summary += (f"\n\nEverything as it was before is saved in:\n"
                            f"{backup_path}")
            lines.append(summary)

        if lines:
            self.show_info("Note Organizer — your notes", "\n\n———\n\n".join(lines))

    # ---------- Data handling ----------
    def load_notes(self):
        """Read the notes file (core/storage.py) and keep its two pieces of
        news -- an upgrade backup, the cleanup report -- on the app.
        VERSION_CHANGE is passed in, as this module has two identities when
        launched as a script (see core/storage.load_notes).
        """
        notes, report = core_load_notes(VERSION_CHANGE)
        self._fresh_notebook = bool(report.get("fresh_notebook"))
        if report["version_backup_path"]:
            self._version_backup_path = report["version_backup_path"]
        self._version_backup_failed = bool(report.get("version_backup_failed"))
        if report["cleanup_report"]:
            self._cleanup_report = report["cleanup_report"]
        self._categories_adopted = report.get("categories_adopted") or []
        # Notes made of days a series' copy set aside, said with the start's
        # other news (written by the load itself, round 16).
        self._set_aside_at_start = report.get("set_aside_made", 0)
        if report.get("notes_file_corrupt"):
            self._corrupt_notes_report = report.get("corrupt_backup_path")
            # Sentinel distinct from "nothing happened": the file WAS
            # unreadable even if copying it aside also failed.
            if self._corrupt_notes_report is None:
                self._corrupt_notes_report = ""
        return notes

    def _notes_file_unread(self):
        """Whether this run holds none of the notes its file has: a start that
        could not read it, or could not bring an older notebook in (its
        writes held, paths.hold_writes). What the app holds then is only what
        was written since -- a backup of it is not a backup of the notebook."""
        return (self._corrupt_notes_report is not None
                or _core_paths.writes_held(DATA_FILE))

    def _maybe_seed_welcome_note(self):
        """A first install opens on the welcome note -- once ever: a notebook
        that had no notes file this launch, and was never offered it before.
        Remembered as the note last open, so the start-up reopen shows it."""
        # Not on a start that could not bring the notebook in: no notes file
        # looked like a first install, and the note's refused save came first.
        if not getattr(self, "_fresh_notebook", False) or self._notes_file_unread():
            return None
        if load_settings().get("welcome_offered"):
            return None
        note = self._add_welcome_note()
        save_setting("welcome_offered", True)
        self._remember_last_open_note(note["id"])
        return note

    def _add_welcome_note(self):
        """Add a fresh welcome note to the notebook and save it; its uid is
        kept, so Settings -> About can find it again rather than add more."""
        note = normalize_note(dict(
            build_welcome_note(),
            id=max([n["id"] for n in self.notes], default=0) + 1))
        self.notes.append(note)
        self.save_notes()
        save_setting("welcome_note_uid", note["uid"])
        return note

    def show_welcome_note(self):
        """Settings -> About's Show, beside the welcome note: the one in the
        notebook if it is still there, a new one if it was deleted, opened
        in the editor either way."""
        uid = load_settings().get("welcome_note_uid")
        note = next((n for n in self.notes
                     if uid and n.get("uid") == uid), None)
        if not self._leave_settings_for_the_editor():
            return
        if note is None:
            note = self._add_welcome_note()
            self.refresh_note_list()
        try:
            self.notebook.select(self.TAB_NOTES)
        except tk.TclError:
            pass
        self._open_unless_shown(note)

    def _set_aside_days(self, say=True):
        """Make notes of their own of the days a series' copy held that a day
        already holding words could not take (core settle_set_aside), each on
        its date, and say so (*say*). Returns how many were made. The start's
        are made by the load (core load_notes)."""
        made = settle_set_aside(self.notes)
        if made and say:
            news = (f"Earlier text of {made} day{'s' if made != 1 else ''} of a "
                    "repeating note kept as notes of their own")
            # A banner of its own, the status line left to the save: over it,
            # a turn-off's Restore previous went; after it, it ran past the
            # bar's edge or onto a line about something else (rounds 16-17).
            first = self.notes[-made]
            first_id, first_uid = first.get("id"), first.get("uid")
            self._show_toast(news, kind="info", action=lambda: self._show_set_aside(first_id, first_uid),
                             action_text="Show")
        return made

    def _keep_text_aside(self, note, comments_only=False):
        """The words *note* holds before this save, kept as a note of their
        own, "<title> (earlier text)", and said with Show: the rescue copy is
        an Update's, the note as it was before it in no other file, and stays;
        the words a big delete takes away now would be in no file. Only the
        comments when the save clears no more (*comments_only*): a whole copy
        was made of a note whose comment alone went (round 6)."""
        title, body = note.get("title") or "", note.get("body") or ""
        comments = note.get("comments") or ""
        if comments_only:
            body = ""
        if not (title.strip() or body.strip() or comments.strip()):
            return
        stamp = now_stamp()
        kept = normalize_note({
            "id": max([n["id"] for n in self.notes], default=0) + 1,
            "title": (title + " (earlier text)").strip(), "body": body,
            "formatting": [] if comments_only else copy.deepcopy(note.get("formatting") or []),
            "paragraphs": [] if comments_only else copy.deepcopy(note.get("paragraphs") or []),
            "comments": comments, "category": note.get("category") or "General",
            # A one-off's date comes along; a series' start is no day of the words.
            "date": "" if is_recurring(note) else note.get("date") or "",
            "color": note.get("color") or "", "created": stamp, "updated": stamp})
        self.notes.append(kept)
        self._asides_changed = True
        # What makes it spent: those words back in the note (_take_back_aside).
        words = {"comments": comments} if comments_only else {
            "title": title, "body": body, "comments": comments}
        self._kept_asides = getattr(self, "_kept_asides", {})
        self._kept_asides.setdefault(note.get("uid"), []).append(
            (kept.get("uid"), words, self._aside_look(kept)))
        said = ("The comments this cleared are kept as a note of their own: " if comments_only
                else "The words this took away are kept as a note of their own: ")
        # Said when the list hides it, as a new note is: Show then shows all
        # (_show_set_aside); unsaid, it was nowhere to be seen (wave 2, round 6).
        hides = self._what_hides_notes(kept)
        self._show_toast(said + one_line(kept["title"], 60)
                         + (f", hidden by {hides}" if hides else ""), kind="info",
                         action=lambda: self._show_set_aside(kept["id"], kept.get("uid")),
                         action_text="Show")

    def _take_back_aside(self, note):
        """The note _keep_text_aside made of *note*'s words taken away again,
        when the note holds those words once more -- Ctrl+Z, a cut pasted
        back -- and that note is untouched since: it is spent, as a rescue
        copy is (round 6: one stayed in the list for good after every Undo).
        Each of the note's asides, by words_lost: a paragraph moved, or two
        deletes undone in turn, left one for good (round 7)."""
        held = getattr(self, "_kept_asides", {}).get(note.get("uid"))
        if not held:
            return
        back = [entry for entry in held
                if all(words_lost(value, note.get(key) or "") == 0 for key, value in entry[1].items())]
        for entry in back:
            held.remove(entry)
            aside = next((n for n in self.notes if entry[0] and n.get("uid") == entry[0]), None)
            # Untouched is as made: a pin or a category kept no stamp, and a
            # note someone had filed went outright (wave 2, round 7).
            if aside is not None and self._aside_look(aside) == entry[2]:
                self.notes.remove(aside)
                self._asides_changed = True
                said = "The words are back in the note; the note kept aside of them is gone again"
                self.set_status(said)
                self._box_words_until = time.monotonic() + 4
                # On the banner too, over its Show: it offered a note just gone.
                self._show_toast(said, kind="info")
        if not held:
            del self._kept_asides[note.get("uid")]

    @staticmethod
    def _aside_look(note):
        """What an '(earlier text)' note is made of, to tell it untouched:
        its content, a pin among it, and the stamp any edit leaves."""
        return content_signature(note), note.get("updated")

    def _show_set_aside(self, note_id, uid):
        """The '(earlier text)' banner's Show: the first note made, found by
        its identity -- the list may have been read again since -- opened
        where the editor is seen. From Settings, after a backup's Update, it
        opened in the hidden editor (the audit's round 18), as show_welcome_note
        leaves Settings first."""
        note = self._note_for_undo(note_id, uid)
        if note is None:
            self._show_toast("That note is no longer here", kind="info")
            return
        if not self._leave_settings_for_the_editor():
            return
        try:
            self.notebook.select(self.TAB_NOTES)
        except tk.TclError:
            pass
        if self._what_hides_notes(note):
            self._show_all_notes(note)
        self._open_unless_shown(note)

    def save_notes(self):
        """Write notes to disk, and say so plainly if it fails.

        A failure here used to be invisible - the app looked like it saved
        but nothing hit the disk, which is exactly how notes "vanished" on
        other PCs. core/storage.py does the writing and reports the reason;
        turning that into a dialog is this layer's job.
        """
        self._set_aside_days()
        ok, exc = core_save_notes(self.notes)
        # Remembered for the close, which must not throw away what only the
        # screen still holds (ISSUES_LOG: "The close that outran a failed save").
        self._notes_unsaved = not ok
        if ok:
            return True
        # Never a dialog inside a sign-out: Windows waits on it, then ends the
        # process anyway. The crash log has the failure (_report_write_failure).
        if getattr(self, "_ending_session", False):
            return False
        if _core_paths.writes_held(DATA_FILE):
            # A held run saves nothing, so "make a change" is false there: said
            # once, on the status line too, over the save's "Auto-saved".
            self.set_status("Not saved — nothing is saved in this session; "
                            "Settings → Backup → Export keeps what you wrote")
            if getattr(self, "_held_save_said", False):
                return False
            self._held_save_said = True
            self.show_error(
                "Nothing is saved in this session",
                "When Note Organizer started it could not open your notes, so "
                "it writes nothing over them until it is opened again. The "
                "notes you already had are safe where they are.\n\n"
                "What you write now stays only on screen. To keep it, use "
                "Settings → Backup → Export: the backup holds what you wrote "
                "in this session. Then close Note Organizer and open it again.")
            return False
        self.show_error(
            "Couldn't save your notes",
            "Your notes could not be written to disk. What you changed since "
            "the last save is still on screen, so keep the app open until it "
            "can be saved.\n\n"
            f"Location:\n{DATA_FILE}\n\n"
            f"Reason: {exc}\n\n"
            "Usually the disk is full, or another program (a backup or sync "
            "tool, an antivirus) is holding the file. Free some space or "
            "close that program, then make any change and it saves again. "
            "Settings → Backup can also export a copy somewhere else."
        )
        return False

    # ---------- Export / Import (moving your notebook between devices) ----------
    def _start_io_worker(self, target):
        """Start a background file-I/O worker and remember it, so closing
        the app can wait for it instead of killing a write mid-file (a
        daemon thread dies with the process, whatever it was writing)."""
        t = threading.Thread(target=target, daemon=True)
        self._io_workers = [w for w in getattr(self, "_io_workers", [])
                            if w.is_alive()]
        self._io_workers.append(t)
        t.start()
        return t

    def _wait_for_io_workers(self, cap_s=30.0):
        """Let an export finish before the process goes, and stop an import
        at once (the close drops it anyway: past the cap it died mid-file).
        Hard-capped, the threads daemon, so a hung worker cannot hold the
        close; an export stopped at the cap takes its unfinished file away,
        and the tmp-then-replace keeps the old backup. Each answers within
        one chunk (StoppableFile)."""
        workers = [t for t in getattr(self, "_io_workers", [])
                   if t.is_alive()]
        if not workers:
            return
        if self._import_state is not None:
            self._import_state["stop"] = True
        try:
            self.set_status("Finishing the file operation in progress…")
            self.update_idletasks()
        except tk.TclError:
            pass

        def join(cap):
            deadline = time.time() + cap
            for t in workers:
                remaining = deadline - time.time()
                if remaining <= 0:
                    break
                t.join(timeout=remaining)
        join(cap_s)
        if self._export_state is not None and any(t.is_alive() for t in workers):
            self._export_state["stop"] = True
            join(5.0)

    def export_data(self):
        """Bundle the notebook -- notes, settings, Trash, templates, every
        attached file -- into one .zip, so moving is copying one file. Written
        on a background thread (it froze the app) that touches only a shared
        dict; the main thread polls it and alone touches widgets."""
        # One file operation at a time (audit Z05-F05): a second Export ran a
        # second worker onto the SAME .tmp.
        if self._export_state is not None or self._import_state is not None:
            self.set_status("An export or import is already running — "
                            "let it finish first.")
            return
        # A start that could not read the notes file holds none: "Export
        # complete" stood over an empty notebook. Notes written since go out,
        # their only way out on a run that saves nothing, and it says so.
        session_only = self._notes_file_unread()
        if session_only and not self.notes:
            self.show_warning(
                "Nothing to back up yet",
                "Your notes could not be opened when Note Organizer started, "
                "so the app holds none of them and a backup made now would "
                "hold none either. They are untouched where they are. Close "
                "Note Organizer and open it again; the warning at the start "
                "says what happened.")
            return
        default_name = f"NotesBackup_{datetime.now().strftime('%Y-%m-%d')}.zip"
        save_path = self._while_native(lambda: filedialog.asksaveasfilename(
            title="Export your notes to a backup file",
            defaultextension=".zip",
            initialfile=default_name,
            filetypes=[("Zip files", "*.zip")])
        )
        if not save_path:
            return
        # The last typing first, as every route that saves on its way does.
        self._flush_autosave(leaving=False)

        # The list up front, for a real progress total. The notes, Trash and
        # templates as the app holds them, as bytes: after a failed save the
        # files are behind, and a backup of them lost the work it rescued.
        entries = []  # list of (source path or bytes, arcname)
        entries.append((json_text(self.notes).encode("utf-8"), "notes_data.json"))
        if os.path.exists(SETTINGS_FILE):
            entries.append((SETTINGS_FILE, "settings.json"))
        # The WHOLE notebook, templates and Trash too; one this start could
        # not read travels as its file's bytes, not an empty list.
        left_out = []
        for held, path, arcname, ident in (
                (self.templates, TEMPLATES_FILE, "templates.json", lambda e: e.get("name")),
                (self.trash, TRASH_FILE, "trash.json", lambda e: e.get("uid") or e.get("id"))):
            if _core_paths.writes_held(path) and os.path.exists(path):
                # Unread at the start, the app holds only this session's: one
                # template saved made "Export complete" of a backup without
                # the file's (round 5). The file read now, or named left out.
                kept = read_list_now(path)
                if kept is None:
                    left_out.append(arcname)
                    kept = []
                if arcname == "templates.json":
                    # A name the session made again, unable to see the file's:
                    # both travel, the session's first, as an import keeps it.
                    mine = {json_text(e) for e in held}
                    kept = list(held) + [e for e in kept if json_text(e) not in mine]
                else:
                    seen = {ident(e) for e in kept}
                    kept += [e for e in held if ident(e) not in seen]
                if kept:
                    entries.append((json_text(kept).encode("utf-8"), arcname))
            elif held:
                entries.append((json_text(held).encode("utf-8"), arcname))
            elif os.path.exists(path):
                entries.append((path, arcname))
        if os.path.isdir(ATTACHMENTS_DIR):
            for filename in os.listdir(ATTACHMENTS_DIR):
                full_path = os.path.join(ATTACHMENTS_DIR, filename)
                if os.path.isfile(full_path):
                    entries.append((full_path, os.path.join("attachments", filename)))

        self._export_state = {"current": 0, "total": len(entries), "done": False,
                              "error": None, "save_path": save_path, "left_out": left_out,
                              "session_only": len(self.notes) if session_only else None}
        self.export_progress_bar.configure(maximum=max(len(entries), 1), value=0)
        self.export_progress_lbl.config(text=f"Exporting… 0 / {len(entries)} files")
        self.export_progress_frame.place(relx=0.5, rely=1.0, anchor="s", y=-14)
        self.export_progress_frame.lift()

        def worker():
            state = self._export_state

            def stop():
                return state.get("stop")   # asked by the close, past its wait
            # Beside the target, moved into place only when whole: opened ON
            # it, a failure destroyed the backup being replaced.
            tmp_path = save_path + ".tmp"
            try:
                with open(tmp_path, "wb") as raw:
                    with zipfile.ZipFile(StoppableFile(raw, stop), "w",
                                         zipfile.ZIP_DEFLATED) as zf:
                        for i, (src, arcname) in enumerate(entries, start=1):
                            if isinstance(src, bytes):
                                zf.writestr(arcname, src)
                            else:
                                # One file another program holds failed the
                                # whole backup: one that will not open is left
                                # out and named. A failure writing the zip still ends it.
                                try:
                                    with open(src, "rb"):
                                        pass
                                except OSError:
                                    state.setdefault("left_out", []).append(
                                        os.path.basename(arcname))
                                else:
                                    zf.write(src, arcname=arcname)
                            state["current"] = i
                    # On the disk before it replaces the backup of that
                    # name, the only copy off this computer.
                    raw.flush()
                    os.fsync(raw.fileno())
                # Asked of what was written, by the import's own rules: a
                # backup that cannot be restored is not put in place.
                with zipfile.ZipFile(tmp_path, "r") as written:
                    problem = backup_entries_problem(written.infolist())
                if problem:
                    raise ValueError("This backup would not import back. " + problem)
                os.replace(tmp_path, save_path)
            except Exception as e:
                # Broad on purpose: anything escaping kills the thread silently,
                # before state["done"], and the progress bar polled for ever.
                state["error"] = str(e)
                try:
                    os.remove(tmp_path)
                except OSError:
                    pass
            state["done"] = True

        self._start_io_worker(worker)
        self._poll_export_progress()

    def _poll_export_progress(self):
        """Runs on the main thread only, on a timer — reads the plain dict the
        background export thread updates, and reflects it in the progress
        bar. This is the ONLY place export touches any Tkinter widget."""
        if not self._still_alive():
            # The app was closed while the background thread was still
            # running — nothing left to update; the close has already
            # waited for it, or stopped it (_wait_for_io_workers).
            return
        state = self._export_state
        if state is None:
            return
        self.export_progress_bar.configure(value=state["current"])
        self.export_progress_lbl.config(
            text=f"Exporting… {state['current']} / {state['total']} files")
        if state["done"]:
            self.export_progress_frame.place_forget()
            self._export_state = None
            self._take_back_cut_short("export")
            left = state.get("left_out") or []
            left_said = ("\n\n" + self._left_out_said(left)) if left else ""
            if state["error"]:
                self.show_error("Export failed",
                               f"Couldn't create the backup file:\n{state['error']}")
            elif state.get("session_only") is not None:
                # Not remembered as the notebook's backup: it holds none of it.
                self.show_info(
                    "Backup of this session saved",
                    f"Saved to:\n{state['save_path']}\n\n"
                    f"It holds the {state['session_only']} note(s) written since "
                    "Note Organizer started, and not your notes file, which "
                    "could not be opened then. Close Note Organizer and open it "
                    "again; Settings → Backup → Import brings this backup's "
                    "notes in beside yours." + left_said)
            else:
                self._remember_finished_export()
                self.show_info(
                    "Export complete" if not left else "Export complete, but not all of it",
                    f"Your notes, settings, and attachments were saved to:\n"
                    f"{state['save_path']}\n\n"
                    "Copy or email this single file to another device; there, "
                    "Settings → Backup → Import brings your notes in." + left_said
                )
            return
        self._export_poll_job = self.after(100, self._poll_export_progress)

    @staticmethod
    def _left_out_said(left):
        """The sentence naming the files an export left out, said by its own
        message or, when the window closed first, by the next start."""
        them = "them" if len(left) > 1 else "it"
        return (f"Left out, because another program may be holding {them}: "
                + ", ".join(left[:5])
                + (f" and {len(left) - 5} more" if len(left) > 5 else "")
                + f". Close that program and export again to include {them}.")

    @staticmethod
    def _take_back_cut_short(kind):
        """Forget the line left for the next start about a backup of *kind*
        cut short: the end of a Windows session leaves it while the work
        goes on, in case the session does end, and work that then finishes
        makes it untrue."""
        cut = get_setting("backup_cut_short", None, expect=dict)
        if cut and cut.get("kind") == kind:
            save_setting("backup_cut_short", None)

    def _remember_finished_export(self):
        """Record the moment a backup export succeeded -- the Backup panel
        shows it, since an export is the only copy of the notes outside
        the app's own folder."""
        stamp = datetime.now().strftime("%Y-%m-%d %H:%M")
        save_setting("last_export_at", stamp)
        lbl = getattr(self, "last_export_lbl", None)
        if lbl is not None:
            try:
                lbl.config(text=f"Last exported: {stamp}")
            except tk.TclError:
                pass

    def _settle_background_work_at_close(self):
        """At close, what the poll would have done once a worker finished: an
        export is recorded; an import never merged is dropped whole, its
        unpacked backup and copied files removed (forty were orphaned in one
        run). Either leaves a line the next start reads out
        (announce_startup_changes), or the work looked done.
        """
        state = self._export_state
        if state is not None and state.get("done") and not state.get("error"):
            self._take_back_cut_short("export")
            self._export_state = None
            # As the poll would have: a backup of the session alone is not the
            # notebook's, and files left out are named -- by the next start,
            # where the close recorded both as whole (round 6 of the audit).
            if state.get("session_only") is None:
                self._remember_finished_export()
            if state.get("session_only") is not None or state.get("left_out"):
                save_setting("backup_cut_short", {
                    "kind": "export_partial", "file": state.get("save_path") or "",
                    "session_only": state.get("session_only"),
                    "left_out": list(state.get("left_out") or [])})
        elif state is not None:
            # Stopped past the wait, or still running: no new backup. A
            # window that is closing cannot say so; the next start does.
            save_setting("backup_cut_short", {
                "kind": "export", "file": state.get("save_path") or ""})
        state = self._import_state
        if state is not None:
            save_setting("backup_cut_short", {
                "kind": "import", "file": state.get("zip") or ""})
        if state is None or not state.get("done"):
            # Still running past the wait's cap: leave it alone.
            return
        self._import_state = None
        if state.get("temp_dir"):
            shutil.rmtree(state["temp_dir"], ignore_errors=True)
        self._drop_unclaimed_import_files(state)

    def _drop_left_import(self, cut):
        """Take out what an import the end of a session cut short while its
        questions waited left behind: the files it copied that no note uses,
        and its unpacked backup. Read from settings.json, which another
        program can write: only bare names in attachments, and only a
        notes_import_ folder directly in the temporary folder. Never on a
        run that holds none of its notes: a file they use would look free."""
        copied = cut.get("copied")
        if not self._notes_file_unread():
            self._drop_unclaimed_import_files(
                {"copied": [n for n in copied if isinstance(n, str)]
                 if isinstance(copied, list) else []})
        temp_dir = cut.get("temp_dir")
        if not (isinstance(temp_dir, str) and temp_dir):
            return
        where = os.path.abspath(temp_dir)
        if (os.path.dirname(where) == os.path.abspath(tempfile.gettempdir())
                and os.path.basename(where).startswith("notes_import_")
                and os.path.isdir(where) and not os.path.islink(where)):
            shutil.rmtree(where, ignore_errors=True)

    def _drop_unclaimed_import_files(self, state):
        """Remove the files a backup import copied into attachments that no
        note and no Trash entry uses: copied before anything is asked, they
        were left by every Cancel, error or skip. Nothing a note names, or
        the import did not copy itself, is touched.
        """
        in_use = attachment_names_in(self.notes + self.trash)
        for name in state.get("copied") or []:
            if name in in_use or os.path.basename(name) != name:
                continue
            try:
                os.remove(os.path.join(ATTACHMENTS_DIR, name))
            except OSError:
                pass

    # ---------- Share codes ----------
    def _add_paste_menu(self, text_widget, extra_items=None):
        """Give a Text/Entry widget a right-click menu with Cut, Copy, Paste
        and Select All, for those who do not know Ctrl+V. *extra_items*,
        (label, command[, accelerator]) tuples after the emoji entry, give
        the note body the toolbar's formatting toggles, shortcuts shown."""
        menu = tk.Menu(text_widget, tearoff=0)
        # Hover colour at POST time: track_theme leaked for short-lived fields,
        # a build-time colour froze long-lived ones on the old accent.
        menu.configure(postcommand=lambda m=menu: m.configure(
            activebackground=self.colors["accent"], activeforeground=self._on_fill("accent")))
        menu.configure(bg=self.colors["card"], fg=self.colors["text"],
                       activebackground=self.colors["accent"],
                       activeforeground=self._on_fill("accent"),
                       relief="flat", bd=0, font=("Segoe UI", 9))

        def do(action):
            try:
                text_widget.event_generate(action)
            except tk.TclError:
                pass

        menu.add_command(label="Cut", command=lambda: do("<<Cut>>"))
        menu.add_command(label="Copy", command=lambda: do("<<Copy>>"))
        menu.add_command(label="Paste", command=lambda: do("<<Paste>>"))
        # Only the note body knows what to do with formatting; everywhere
        # else this widget appears -- the import box, a rename field -- takes
        # plain text anyway, so offering the choice there would be noise.
        if text_widget is getattr(self, "body_text", None):
            menu.add_command(label="Paste without formatting",
                             accelerator="Ctrl+Shift+V",
                             command=self._paste_plain)
        menu.add_separator()
        menu.add_command(label="Select All",
                         # "end-1c": "end" takes Text's own trailing newline,
                         # and the highlight ran the last line's full width.
                         command=lambda: (text_widget.tag_add("sel", "1.0", "end-1c")
                                          if isinstance(text_widget, tk.Text)
                                          else text_widget.select_range(0, "end")))
        menu.add_separator()
        menu.add_command(label="Insert emoji…",
                         command=lambda: self._show_emoji_picker(text_widget))

        if extra_items:
            menu.add_separator()
            for item in extra_items:
                label, command = item[0], item[1]
                accelerator = item[2] if len(item) > 2 else ""
                menu.add_command(label=label, command=command, accelerator=accelerator)

        def popup(event):
            try:
                text_widget.focus_set()
                # A misspelled word under the pointer brings its
                # suggestions to the top (ui/spelling.py).
                self._spell_menu(text_widget, menu, event)
                self._while_native(lambda: menu.tk_popup(event.x_root, event.y_root))
            finally:
                menu.grab_release()
        text_widget.bind("<Button-3>", popup)

    # ---------- Note body rich text formatting: offset spans in the note
    # (normalize_formatting), Tk tags on the widget, bridged at load and save
    # only -- Tk keeps tags anchored while typing ----------
    _FONT_STYLES = ("bold", "italic", "bold_italic")  # mutually exclusive
    _PENDING_STYLE_ANCHOR = "pending_style_anchor"  # see _toggle_body_style

    # ---------- Bullet and numbered lists ----------
    def _setup_list_tags(self, text_widget):
        """Tags for the paragraph properties: hanging indent (lmargin1 the
        first line, lmargin2 the wrapped rest, under the item's text) and
        alignment, its own tags -- justify and lmargin compose, so a centred
        bullet keeps its indent.
        """
        self._paragraph_tags = {}
        text_widget.tag_configure("align_center", justify="center")
        text_widget.tag_configure("align_right", justify="right")

    # Shown in both font dropdowns for "no span at all": the note follows the
    # Settings default, not whatever it was on the day it was written.
    DEFAULT_FONT_LABEL = "Default"

    INDENT_STEP = 24
    # A marker's room before its text, measured at _MARKER_ROOM_AT points and
    # scaled (_marker_room) -- against a fixed size, not the moving base one.
    _MARKER_ROOM = {"bullet": 24, "number": 28}
    _MARKER_ROOM_AT = 12

    def _load_editor_font(self):
        """Read the editor's baseline font from settings.

        Falls back to the app's own defaults rather than to whatever the
        widget happens to be set to, so a settings file with a font that is
        no longer offered degrades to something known instead of sticking.
        """
        family = get_setting("editor_font_family", FONT_FAMILIES[0], str)
        if family not in FONT_FAMILIES:
            family = FONT_FAMILIES[0]
        size = get_setting("editor_font_size", 12, int)
        if size not in FONT_SIZES:
            size = 12
        self.editor_font_family, self.editor_font_size = family, size

    def _set_editor_font(self, family=None, size=None):
        """Change the baseline font every note is written in.

        Rebuilds the tags derived from it as well as the widget's own font:
        bold and italic are separate Font objects built from the base
        family and size, and the list margins are in pixels scaled by that
        size, so neither follows automatically.
        """
        if family is not None:
            self.editor_font_family = family
            save_setting("editor_font_family", family)
        if size is not None:
            self.editor_font_size = size
            save_setting("editor_font_size", size)

        spec = (self.editor_font_family, self.editor_font_size)
        for widget in (self.body_text, self.comments_text):
            if widget is not None:
                widget.configure(font=spec)
        self._setup_body_formatting_tags(self.body_text)
        # Rebuilt at the new base size: a tag's margin was computed from the
        # old one, and nothing else recomputes it.
        for name in list(self._paragraph_tags):
            self._configure_paragraph_tag(self.body_text, name)
        # The table face follows the base size too, or a table would stay at
        # whatever size it was built at while the text around it moved.
        self._configure_table_tag(self.body_text)
        # Grids carry their own fonts and cell widths, so they are rebuilt
        # at the new size rather than left at the old one -- all but a row
        # being typed, which a new size is no reason to leave.
        self._render_table_grids(keep_typed=self._row_being_typed())
        self._refresh_format_buttons()

    def _marker_room(self, kind):
        """How much room a list marker needs before its text.

        Scaled by the editor's font size, because the margin is in pixels
        and the marker is not: "• " measures 11px at 12pt and 22px at 24pt,
        so a fixed 42px lmargin2 that hangs correctly at the default size
        leaves a large-font item's second line 11px out of true.
        """
        room = self.px(self._MARKER_ROOM[kind])
        current = self._editor_font_size()
        if current and current != self._MARKER_ROOM_AT:
            room = int(round(room * current / self._MARKER_ROOM_AT))
        return room

    def _editor_font_size(self):
        """The size the body text is actually set in right now."""
        try:
            return tkfont.Font(font=self.body_text["font"]).actual("size")
        except (tk.TclError, AttributeError):
            return getattr(self, "_body_base_size", 0)

    def _paragraph_tag(self, text_widget, kind, indent):
        """The margin tag for this combination of properties, made on demand:
        one per combination, as they all set lmargin1 and lmargin2 and only
        the winning tag's value applies; lazily, as the colour tags are.
        """
        name = f"para_{kind or 'plain'}_{indent}"
        if name not in self._paragraph_tags:
            self._paragraph_tags[name] = (kind, indent)
            self._configure_paragraph_tag(text_widget, name)
        return name

    TABLE_TAG = "table_row"

    def _table_block_at(self, line_no):
        """The first and last line of the table *line_no* belongs to, 1-based.

        None if that line is not a table row. Read from the widget rather
        than from anything remembered, because the text is what decides.
        """
        if not is_table_row(self.body_text.get(f"{line_no}.0", f"{line_no}.end")):
            return None
        first = last = line_no
        end = int(self.body_text.index("end-1c").split(".")[0])
        while first > 1 and is_table_row(
                self.body_text.get(f"{first - 1}.0", f"{first - 1}.end")):
            first -= 1
        while last < end and is_table_row(
                self.body_text.get(f"{last + 1}.0", f"{last + 1}.end")):
            last += 1
        return first, last

    @_undo_atom
    def _align_table_block(self, line_no):
        """Line the columns of one table up again, touching only spaces, so
        the cells keep their tags. The caret is left to Tk's insert mark,
        not put back by index (it landed nineteen characters early), with
        left gravity: padding goes where a caret sits after typing, and the
        default gravity drifted it past the new spaces.
        """
        block = self._table_block_at(line_no)
        if not block:
            return False
        first, last = block
        if self._grid_at_line(first) is None:
            # Not drawn: recorded with no window, replayed with none.
            self._mark_unit_window_free()
        lines = [self.body_text.get(f"{n}.0", f"{n}.end")
                 for n in range(first, last + 1)]
        # Lined up while the padding stays under its ceiling, ragged past it
        # (core_tables.row_widths): a long cell in a long table padded every
        # row to it.
        per_row, aligns = core_tables.tidy_plan(lines)
        changed = False
        try:
            was_gravity = self.body_text.mark_gravity("insert")
            self.body_text.mark_gravity("insert", "left")
        except tk.TclError:
            was_gravity = None
        for offset, line in enumerate(lines):
            row = first + offset
            # A rendered grid's window occupies column 0 of its first line,
            # so edits on that line land one Tk column further right than
            # the offsets computed from get(), which skips windows.
            base = self._col_base(row)
            for at, delta in core_tables.pad_ops(
                    line, per_row[offset],
                    aligns[offset] if offset < len(aligns) else None):
                changed = True
                if base:
                    self._note_edit_with_window()
                # Ops come right-to-left, so the prefix each one converts
                # against is still the snapshot the offsets were computed
                # from. The deltas themselves are spaces -- one unit each.
                t_at = base + self._tk_col(line, at)
                if delta > 0:
                    self.body_text.insert(f"{row}.{t_at}", " " * delta)
                else:
                    self.body_text.delete(f"{row}.{t_at}",
                                          f"{row}.{t_at + (-delta)}")
        if was_gravity:
            try:
                self.body_text.mark_gravity("insert", was_gravity)
            except tk.TclError:
                pass
        if changed:
            self._resync_list_tags()
        return changed

    def _align_table_on_leaving(self, event=None):
        """Re-pad a table once the caret is no longer inside it.

        Not on every keystroke: the columns would jump about under the
        hands of whoever is typing, and every keystroke would rewrite
        characters. Waiting until the row is left means one rewrite, at a
        moment nobody is mid-word.
        """
        try:
            now = int(self.body_text.index("insert").split(".")[0])
        except tk.TclError:
            return
        was = getattr(self, "_last_caret_line", None)
        self._last_caret_line = now
        if was is None or was == now:
            return
        # The line just left, not the one just arrived at: a table is tidied
        # when it is finished with, and a caret moving between two rows of
        # the same table is not finished with it.
        leaving = self._table_block_at(was)
        if leaving and leaving != self._table_block_at(now):
            self._align_table_block(was)
            # A table that has just been left is finished with, which is the
            # moment it turns from typed pipes into a drawn grid.
            self._render_table_grids()
            # An edit, made on a click as well as on a key's release.
            self._schedule_autosave()

    # ---------- Tables drawn as real grids: the pipe text stays the one stored
    # truth, which everything else reads. A grid's window shifts Tk's index
    # columns on its line by one (_col_base); offsets skip it ----------

    TABLE_HIDE_TAG = "table_hidden"

    def _grid_first_line(self, info):
        """The 1-based line a grid starts on, read from a mark that moves with
        the text, or None if gone -- asked alive first: a full delete kills
        the windows and leaves the marks at 1.0, and a dead grid walked a
        fresh note's caret to its end.
        """
        try:
            if not info["frame"].winfo_exists():
                return None
            return int(self.body_text.index(info["mark"]).split(".")[0])
        except (tk.TclError, KeyError, ValueError):
            return None

    def _grid_at_line(self, line_no):
        for info in getattr(self, "_table_grids", []):
            if self._grid_first_line(info) == line_no:
                return info
        return None

    def _col_base(self, line_no):
        """1 when a grid window occupies column 0 of this line, else 0."""
        return 1 if self._grid_at_line(line_no) is not None else 0

    def _teardown_table_grids(self):
        """Take every drawn table down to its text (_remove_grid_windows),
        telling an open undo unit first (_undo_atom_grids_coming_down), while
        Tk still records: its edits are by index, and a grid's window holds
        column 0 of its line."""
        if (getattr(self, "_table_grids", None)
                and getattr(self, "_undo_atom_depth", 0) > 0):
            self._undo_atom_grids_coming_down()
        self._remove_grid_windows()

    @_undo_hidden
    def _remove_grid_windows(self):
        for info in getattr(self, "_table_grids", []):
            # The window's character deleted, or a phantom index shifted its
            # line one more each redraw ("a/b" became " |a/be").
            try:
                self.body_text.delete(self.body_text.index(info["frame"]))
            except tk.TclError:
                pass
            # ...and tkinter's destroy() too: Tk's alone kept the callbacks as
            # Tcl commands, ten more at every redraw.
            try:
                info["frame"].destroy()
            except tk.TclError:
                pass
            try:
                self.body_text.mark_unset(info["mark"])
            except tk.TclError:
                pass
        self._table_grids = []
        self._grid_sel = None
        self._grid_pressed = None
        self._grid_resizing = None
        try:
            self.body_text.tag_remove(self.TABLE_HIDE_TAG, "1.0", "end")
        except tk.TclError:
            pass

    def _add_line_under_last_table(self):
        """The line under the note's last table, for the caret guard: the
        drawing's, unrecorded by Tk, so the app holds it -- while the text is
        unchanged (Tk's modified flag), undo counts the note without it and
        takes it out before Tk replays a step (_undo_tail_held)."""
        b = self.body_text
        # A line held before this one is settled first: a second line can
        # only be needed once the text has changed under the first.
        self._undo_tail_held()
        text = b.get("1.0", "end-1c")
        b.insert("end", "\n")
        # The signature of the text the line was put under.
        self._undo_tail = (len(text), hash(text))
        try:
            b.edit_modified(False)
        except tk.TclError:
            self._undo_tail = None

    def _undo_tail_held(self):
        """Whether the note's last line is still the drawing's, with not a
        character changed since: once anything changes, it is the note's for
        good (_settle_undo_tail) -- taken out, Tk replayed a typed letter's
        steps onto the table's last row."""
        if getattr(self, "_undo_tail", None) is None:
            return False
        try:
            changed = bool(self.body_text.edit_modified())
        except tk.TclError:
            changed = True
        if changed:
            self._settle_undo_tail()
            return False
        return True

    def _settle_undo_tail(self):
        """The line the drawing put under the last table stays for good:
        every state undo noted gets it at its end, counted as one more line
        break (_undo_sig_is), as Tk walking back leaves the unrecorded line
        there -- open units' and delete runs' snapshots too."""
        self._undo_tail = None

        def counted(state):
            sig = state[0]
            return (((sig[0], sig[1], (sig[2] if len(sig) > 2 else 0) + 1),)
                    + tuple(state[1:]))

        for journal in (getattr(self, "_fmt_undo", None) or [],
                        getattr(self, "_fmt_redo", None) or []):
            for step in journal:
                step["before"] = counted(step["before"])
                step["after"] = counted(step["after"])
        if getattr(self, "_fmt_atom_before", None) is not None:
            self._fmt_atom_before = counted(self._fmt_atom_before)
        run = getattr(self, "_styled_delete_run", None)
        if run is not None:
            run["before"] = counted(run["before"])

    @staticmethod
    def _undo_sig_is(sig, plain, text):
        """Whether a journal side's signature names the body's text: *plain*
        is that text's own signature, *text* the text itself. A side noted
        before lines under a table were settled into the note counts the
        line breaks they put at its end (_settle_undo_tail)."""
        if len(sig) < 3:
            return sig == plain
        k = sig[2]
        return (text is not None and len(text) - k == sig[0]
                and text.endswith("\n" * k) and hash(text[:-k]) == sig[1])

    @_undo_hidden
    def _drop_undo_tail(self):
        """Take out the line the drawing put under the last table, as long
        as the text has not changed since (_undo_tail_held): Tk replays
        every step on the text it recorded."""
        if self._undo_tail_held():
            self.body_text.delete("end-2c")
        self._undo_tail = None

    @_undo_hidden
    def _render_table_grids(self, keep_typed=None):
        """Draw every table in the note as a grid of real cells, rebuilt
        whole -- never with focus in a cell, which the callers see to.
        *keep_typed*: a table line still being typed (a paste left the caret
        there, or the caret's row in a redraw that is no edit) stays text
        until the caret leaves; drawn, the next letter went under it.
        """
        if not hasattr(self, "body_text"):
            return
        # Torn down, the page reads as short and snapped to the top: the view
        # is restored after the queue's handlers. A menu operation tears down
        # first and leaves its own snapshot, taken before the jump.
        saved = getattr(self, "_grid_saved_view", None)
        self._grid_saved_view = None
        explicit_capture = saved is not None
        if saved is not None:
            restore_view, restore_body, restore_x = saved
        else:
            restore_view, restore_body, restore_x = self._capture_grid_views()
        self._teardown_table_grids()
        # Anything a plain destroy left behind -- a dead window dumps with an
        # empty name -- is swept out bottom-up, so the deletions do not move
        # the indices still to be visited.
        for _kind, name, index in reversed(
                self.body_text.dump("1.0", "end", window=True)):
            if not name:
                try:
                    self.body_text.delete(index)
                except tk.TclError:
                    pass
        self.body_text.tag_configure(self.TABLE_HIDE_TAG, elide=True)
        text = self.body_text.get("1.0", "end-1c")
        blocks = []
        for first0, last0 in core_tables.find_blocks(text):
            if keep_typed is None or not first0 + 1 <= keep_typed <= last0 + 1:
                blocks.append((first0, last0))
                continue
            # The row being typed stays text; the rows on either side of it,
            # drawn before the paste, are drawn as they were.
            kept0 = keep_typed - 1
            if kept0 > first0:
                blocks.append((first0, kept0 - 1))
            if kept0 < last0:
                blocks.append((kept0 + 1, last0))
        lines = text.split("\n")
        too_big = [b for b in blocks if self._table_too_big_to_draw(lines, *b)]
        blocks = [b for b in blocks if b not in too_big]
        for first0, last0 in blocks:
            self._build_table_grid(first0 + 1, last0 + 1)
        if too_big:
            self.set_status("A table this large is shown as its text, so the note "
                            "stays quick to open")
        # There is always a line under the last table, or the caret guard
        # would have nowhere to put the caret and writing could never
        # continue past it (_add_line_under_last_table).
        if blocks:
            total = int(self.body_text.index("end-1c").split(".")[0])
            if blocks[-1][1] + 1 >= total:
                self._add_line_under_last_table()
        for info in getattr(self, "_table_grids", []):
            line = self._grid_first_line(info)
            if line in restore_x:
                try:
                    info["canvas"].xview_moveto(restore_x[line])
                except tk.TclError:
                    pass
        # Both wait for the queue: unmapped, the windows' heights are guessed,
        # and a fraction restored drifted 0.316 to 0.164.
        if restore_body is not None or restore_view is not None:
            self.after_idle(lambda page=restore_view, body=restore_body,
                            expl=explicit_capture:
                            self._restore_views_idle(page, body, expl))

    def _grid_fonts(self):
        key = (self.editor_font_family, self.editor_font_size)
        cache = getattr(self, "_grid_font_cache", None)
        if cache is None:
            cache = self._grid_font_cache = {}
        if key not in cache:
            cache[key] = (
                tkfont.Font(family=key[0], size=key[1], weight="bold"),
                tkfont.Font(family=key[0], size=key[1]),
            )
        return cache[key]

    def _measuring_font(self, font):
        """A font that can measure -- the emoji cells pass a plain tuple,
        which draws fine but cannot answer measure()."""
        if hasattr(font, "measure"):
            return font
        cache = getattr(self, "_measure_font_cache", None)
        if cache is None:
            cache = self._measure_font_cache = {}
        if font not in cache:
            cache[font] = tkfont.Font(family=font[0], size=font[1])
        return cache[font]

    def _measure_text(self, font, text):
        """``_measuring_font(font).measure(text)``, remembered per font and
        text. Opening a 60-row table asked Tk for 1,563 widths -- a third
        of the open -- over a few hundred distinct strings. The grid's
        fonts are never reconfigured in place (a new size or family makes
        new Font objects, see _grid_fonts), so a remembered width cannot
        go stale; the store is dropped whole if it ever grows large."""
        font = self._measuring_font(font)
        cache = getattr(self, "_measure_text_cache", None)
        if cache is None or len(cache) > 50000:
            cache = self._measure_text_cache = {}
        key = (str(font), text)
        width = cache.get(key)
        if width is None:
            width = cache[key] = font.measure(text)
        return width

    def _ellipsize(self, value, font, max_px):
        """The drawing clips, the text never does: a value wider than its
        column is drawn shortened with an ellipsis, while the note's own
        text keeps every character."""
        if max_px <= 0 or self._measure_text(font, value) <= max_px:
            return value
        ellipsis = "\u2026"
        lo, hi = 0, len(value)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if self._measure_text(font, value[:mid] + ellipsis) <= max_px:
                lo = mid
            else:
                hi = mid - 1
        return value[:lo] + ellipsis

    # How much of a name is laid out at all before it is fitted: a name kept
    # whole in its file, as a backup can bring one, asked Tk for a label
    # past the 32,767 pixels X can draw.
    NAME_SHOWN_CHARS = 400

    def _fit_name(self, name, font, max_px):
        """*name* drawn on one line at most *max_px* wide, shortened with an
        ellipsis -- one holding line breaks, or past NAME_SHOWN_CHARS, first
        made one line as _fit_title makes it. Display only: the name itself
        keeps every character."""
        return self._ellipsize(one_line(name or "", self.NAME_SHOWN_CHARS),
                               font, max_px)

    @staticmethod
    def _char_is_emoji(ch):
        return ord(ch) >= 0x1F000 or 0x2600 <= ord(ch) <= 0x27BF or ord(ch) > 0xFFFF

    def _cell_value_styles(self, line_no, line, c, base=None):
        """Per-character style of one cell's raw value, read straight off
        the body tags: one dict per character. The drawing folds equal
        neighbours into runs, so a single coloured letter -- or a single
        coloured checkmark -- shows exactly as itself instead of painting
        the whole cell. *base*: _col_base's answer, when the caller knows
        it -- asking walks every drawn grid, once per cell."""
        bounds = core_tables.cell_bounds(line)
        if c >= len(bounds):
            return []
        start, end = bounds[c]
        if start >= end:
            return []
        if base is None:
            base = self._col_base(line_no)
        # The column walks along with the characters -- counting each one's
        # UTF-16 width from the line's start again made this quadratic.
        col = base + self._tk_col(line, start)
        out = []
        for ch in line[start:end]:
            try:
                tags = set(self.body_text.tag_names(f"{line_no}.{col}"))
            except tk.TclError:
                tags = set()
            col += 2 if ord(ch) > 0xFFFF else 1
            st = {"bold": bool(tags & {"bold", "bold_italic"}),
                  "italic": bool(tags & {"italic", "bold_italic"}),
                  "underline": "underline" in tags,
                  "strike": "strike" in tags, "fg": None, "bg": None}
            for t in tags:
                if t.startswith("text_color_"):
                    st["fg"] = "#" + t[len("text_color_"):]
                elif t.startswith("highlight_"):
                    st["bg"] = "#" + t[len("highlight_"):]
            out.append(st)
        return out

    _PLAIN_STYLE = {"bold": False, "italic": False, "underline": False,
                    "strike": False, "fg": None, "bg": None}

    def _grid_run_font(self, key, header):
        """The face one run is drawn with. key is (bold, italic,
        underline, strike, fg, emoji)."""
        bold, italic, underline, strike, _fg, emoji = key
        if emoji:
            return ("Segoe UI Emoji", self.editor_font_size)
        header_font, cell_font = self._grid_fonts()
        base = header_font if header else cell_font
        mods = [m for m, on in (("bold", bold or header),
                                ("italic", italic),
                                ("underline", underline),
                                ("overstrike", strike)) if on]
        family, size = base.cget("family"), base.cget("size")
        return (family, size, " ".join(mods)) if mods else (family, size)

    def _grid_draw_cell_text(self, canvas, cell, value, styles, align,
                             header, pad_x, row_h):
        """One cell's text as runs of equal style, one row of runs per
        display line, vertically centred in the cell. Returns the canvas
        item ids -- the caller keeps them to delete on redraw."""
        state = core_tables.checkbox_state(value)
        if state is not None:
            # The cell IS a checkbox: drawn as a real box, not as text.
            # The colour it was given rides as a text_color span on the
            # marker characters, so it survives every save unchanged.
            ink = next((st["fg"] for st in styles if st.get("fg")), None) \
                or self.colors["text"]
            side = max(self.px(12), min(self.px(18), row_h - self.px(14)))
            cx = cell["x"] + cell["w"] / 2
            cy = cell["y"] + cell["h"] / 2
            items = [canvas.create_rectangle(
                cx - side / 2, cy - side / 2, cx + side / 2, cy + side / 2,
                outline=ink, width=2)]
            if state:
                items.append(canvas.create_text(
                    cx, cy, text="✓", fill=ink,
                    font=("Segoe UI", max(9, int(side * 0.7)), "bold")))
            return items
        items = []
        lines = core_tables.cell_display_lines(value)
        top = cell["y"] + (cell["h"] - len(lines) * row_h) / 2
        raw_i = 0
        for li, seg in enumerate(lines):
            seg_styles = styles[raw_i:raw_i + len(seg)]
            raw_i += len(seg) + len(core_tables.LINE_BREAK)
            runs = []
            for j, ch in enumerate(seg):
                st = seg_styles[j] if j < len(seg_styles) else self._PLAIN_STYLE
                key = (st["bold"], st["italic"], st["underline"],
                       st["strike"], st["fg"], self._char_is_emoji(ch))
                if runs and runs[-1][0] == key:
                    runs[-1][1] += ch
                else:
                    runs.append([key, ch])
            budget = cell["w"] - 2 * pad_x
            laid, used = [], 0
            for key, txt in runs:
                font = self._grid_run_font(key, header)
                width = self._measure_text(font, txt)
                if used + width <= budget:
                    laid.append((txt, font, key[4]))
                    used += width
                else:
                    shown = self._ellipsize(txt, font, budget - used)
                    if shown:
                        laid.append((shown, font, key[4]))
                        used += self._measure_text(font, shown)
                    break
            if align == core_tables.ALIGN_CENTER:
                x = cell["x"] + (cell["w"] - used) / 2
            elif align == core_tables.ALIGN_RIGHT:
                x = cell["x"] + cell["w"] - pad_x - used
            else:
                x = cell["x"] + pad_x
            y_mid = top + li * row_h + row_h / 2
            for txt, font, fg in laid:
                items.append(canvas.create_text(
                    x, y_mid, anchor="w", font=font,
                    fill=fg or self.colors["text"], text=txt))
                x += self._measure_text(font, txt)
        return items

    def _grid_redraw_cell_text(self, info, r, c):
        """Repaint one drawn cell from its tags -- its fill, and its text
        as a fresh run layout -- after a commit, a restyle, or anything
        that changed the value or the tags underneath it. The fill used to
        wait for a full restyle, so a highlight showed only on a reopen."""
        cell = info["cells"].get((r, c))
        if cell is None:
            return
        canvas = info["canvas"]
        paint = self._grid_cell_paint(info, r, c)
        surface = (inset_surface(self.colors) if r == 0
                   else self.colors["card"])
        # The saved colour stays pure; only the DRAWING blends it toward the
        # cell's own surface, so the text stays readable on either theme.
        try:
            canvas.itemconfigure(cell["rect"], fill=(
                self._blend_hex(paint["bg"], surface, 0.45)
                if paint["bg"] else surface))
        except tk.TclError:
            pass
        if c in info.get("hidden_cols", ()):
            return
        for item in cell.get("texts", ()):
            try:
                canvas.delete(item)
            except tk.TclError:
                pass
        line_no = self._grid_line_of_row(info, r)
        if line_no is None:
            cell["texts"] = []
            return
        line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
        aligns = core_tables.cell_alignments(line)
        align = aligns[c] if c < len(aligns) else core_tables.ALIGN_LEFT
        # This grid's own first line holds its window, as
        # _grid_cell_text_range asks: no walk through every grid per cell.
        styles = self._cell_value_styles(
            line_no, line, c,
            base=1 if line_no == self._grid_first_line(info) else 0)
        cell["texts"] = self._grid_draw_cell_text(
            info["canvas"], cell, cell["value"], styles, align,
            r == 0, 10, info["row_h"])

    def _editor_configure_style_tags(self, t, header):
        """The cell editor's own copies of the styles it can show live:
        the same names the body uses, so sampling back out is one code
        path."""
        header_font, cell_font = self._grid_fonts()
        base = header_font if header else cell_font
        family, size = base.cget("family"), base.cget("size")
        t.tag_configure("bold", font=(family, size, "bold"))
        t.tag_configure("italic", font=(
            family, size, "bold italic" if header else "italic"))
        t.tag_configure("bold_italic", font=(family, size, "bold italic"))
        t.tag_configure("underline", underline=True)
        t.tag_configure("strike", overstrike=True)
        t.tag_configure("emojif",
                        font=("Segoe UI Emoji", self.editor_font_size))
        t.tag_raise("sel")

    def _editor_apply_display_styles(self, t, raw_value, raw_styles):
        """Lay the cell's saved styles over the editor's display text, so
        the user edits the coloured text they see -- not a plain black
        stand-in that recolours only after commit."""
        li, colu, i = 1, 0, 0
        marker = core_tables.LINE_BREAK
        while i < len(raw_value):
            if raw_value.startswith(marker, i):
                i += len(marker)
                li += 1
                colu = 0
                continue
            ch = raw_value[i]
            st = raw_styles[i] if i < len(raw_styles) else self._PLAIN_STYLE
            units = self._tk_units(ch)
            s_idx = f"{li}.{colu}"
            e_idx = f"{li}.{colu + units}"
            try:
                if st["bold"] and st["italic"]:
                    t.tag_add("bold_italic", s_idx, e_idx)
                elif st["bold"]:
                    t.tag_add("bold", s_idx, e_idx)
                elif st["italic"]:
                    t.tag_add("italic", s_idx, e_idx)
                if st["underline"]:
                    t.tag_add("underline", s_idx, e_idx)
                if st["strike"]:
                    t.tag_add("strike", s_idx, e_idx)
                if st["fg"]:
                    t.tag_add(self._ensure_color_tag(
                        t, "text_color", st["fg"]), s_idx, e_idx)
                if st["bg"]:
                    t.tag_add(self._ensure_color_tag(
                        t, "highlight", st["bg"]), s_idx, e_idx)
            except tk.TclError:
                pass
            colu += units
            i += 1

    def _editor_retag_emoji(self, t):
        """Emoji get their face per character, live -- the old Entry
        switched the WHOLE box to the emoji font at the first emoji."""
        try:
            t.tag_remove("emojif", "1.0", "end")
            content = t.get("1.0", "end-1c")
        except tk.TclError:
            return
        li, colu = 1, 0
        for ch in content:
            if ch == "\n":
                li += 1
                colu = 0
                continue
            units = self._tk_units(ch)
            if self._char_is_emoji(ch):
                try:
                    t.tag_add("emojif", f"{li}.{colu}",
                              f"{li}.{colu + units}")
                except tk.TclError:
                    pass
            colu += units

    def _editor_sample_styles(self, t, content):
        """Read the editor's live tags back as per-character styles, in
        the same shape _cell_value_styles returns; newlines read plain."""
        out = []
        li, colu = 1, 0
        for ch in content:
            if ch == "\n":
                out.append(dict(self._PLAIN_STYLE))
                li += 1
                colu = 0
                continue
            try:
                tags = set(t.tag_names(f"{li}.{colu}"))
            except tk.TclError:
                tags = set()
            st = {"bold": bool(tags & {"bold", "bold_italic"}),
                  "italic": bool(tags & {"italic", "bold_italic"}),
                  "underline": "underline" in tags,
                  "strike": "strike" in tags, "fg": None, "bg": None}
            for tag in tags:
                if tag.startswith("text_color_"):
                    st["fg"] = "#" + tag[len("text_color_"):]
                elif tag.startswith("highlight_"):
                    st["bg"] = "#" + tag[len("highlight_"):]
            out.append(st)
            colu += self._tk_units(ch)
        return out

    def _styles_display_to_raw(self, display_value, display_styles):
        """The editor's display text (real newlines) as the stored raw
        value (<br> markers), with the style list stretched to match --
        the marker's characters carry no style of their own."""
        raw, out = [], []
        for i, ch in enumerate(display_value):
            st = (display_styles[i] if i < len(display_styles)
                  else dict(self._PLAIN_STYLE))
            if ch == "\n":
                raw.append(core_tables.LINE_BREAK)
                out.extend(dict(self._PLAIN_STYLE)
                           for _ in core_tables.LINE_BREAK)
            else:
                raw.append(ch)
                out.append(st)
        return "".join(raw), out

    def _apply_styles_to_cell(self, info, r, c, value, raw_styles):
        """One cell's per-character styles, written back to the body tags
        -- the inverse of _cell_value_styles. Only the styles the editor
        models are cleared and re-laid; a font size or family tag already
        on the cell is left exactly where it was."""
        line_no = self._grid_line_of_row(info, r)
        if line_no is None:
            return
        b = self.body_text
        line = b.get(f"{line_no}.0", f"{line_no}.end")
        bounds = core_tables.cell_bounds(line)
        if c >= len(bounds):
            return
        start, end = bounds[c]
        if line[start:end] != value:
            # The text on the line is not what these styles were sampled
            # against -- write nothing rather than style the wrong chars.
            return
        base = self._col_base(line_no)

        def idx(off):
            return f"{line_no}.{base + self._tk_col(line, off)}"

        s_idx, e_idx = idx(start), idx(end)
        if b.compare(s_idx, ">=", e_idx):
            return
        for tag in b.tag_names():
            if is_format_tag(tag, fonts=False):
                b.tag_remove(tag, s_idx, e_idx)
        i = 0
        while i < len(raw_styles):
            st = raw_styles[i]
            j = i
            while j < len(raw_styles) and raw_styles[j] == st:
                j += 1
            cs, ce = idx(start + i), idx(start + j)
            if st["bold"] and st["italic"]:
                b.tag_add("bold_italic", cs, ce)
            elif st["bold"]:
                b.tag_add("bold", cs, ce)
            elif st["italic"]:
                b.tag_add("italic", cs, ce)
            if st["underline"]:
                b.tag_add("underline", cs, ce)
            if st["strike"]:
                b.tag_add("strike", cs, ce)
            if st["fg"]:
                b.tag_add(self._ensure_color_tag(b, "text_color", st["fg"]),
                          cs, ce)
            if st["bg"]:
                b.tag_add(self._ensure_color_tag(b, "highlight", st["bg"]),
                          cs, ce)
            i = j
        self._grid_reassert_cell_highlight(info, r, c)

    def _grid_reassert_cell_highlight(self, info, r, c):
        """A CELL-level highlight lives pipe-to-pipe; keep it whole. Text
        typed into an empty highlighted cell sampled nothing, and punched a
        hole the next rebuild showed ("type in a coloured cell, drag the
        column, colour gone"): the whole region is dressed again."""
        span = self._grid_cell_text_range(info, r, c, pad_ok=True, full=True)
        if not span:
            return
        b = self.body_text
        for tag in b.tag_names():
            if (tag.startswith("highlight_")
                    and b.tag_nextrange(tag, span[0], span[1])):
                b.tag_add(tag, span[0], span[1])
                return

    def _editor_apply_style(self, kind, value=None):
        """A toolbar action while the cell editor is open styles the
        SELECTION inside the editor -- one letter, one emoji, one word --
        or the whole cell when nothing is selected. Visible immediately,
        in the editor itself; the commit carries it to the body."""
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return
        t = editor["entry"]
        try:
            s, e = t.index("sel.first"), t.index("sel.last")
            has_sel = t.compare(s, "<", e)
        except tk.TclError:
            has_sel = False
        if not has_sel and kind == "text_color":
            # No selection: the colour becomes the PENDING one -- shown
            # as a swatch on the toolbar button, worn by whatever is
            # typed next, in the cell and in the body alike.
            self._pending_text_color = value
            self.set_status("Text color on — applies to what you type next"
                            if value else "Text color off")
            self._refresh_format_buttons()
            return
        if not has_sel:
            s, e = "1.0", "end-1c"
        if kind == "highlight":
            # A cell's highlight is a whole-cell wash, as the drawing paints
            # it: it takes the whole cell, selected or not, shows at once,
            # and the commit lays it pipe to pipe, an empty cell included.
            s, e = "1.0", "end-1c"
            editor["cell_highlight"] = value
            surface = (inset_surface(self.colors) if editor["r"] == 0
                       else self.colors["card"])
            t.configure(bg=self._blend_hex(value, surface, 0.45)
                        if value else surface)
        if t.compare(s, ">=", e):
            return

        def chars():
            idx = s
            while t.compare(idx, "<", e):
                nxt = t.index(f"{idx}+1c")
                if t.get(idx, nxt) != "\n":
                    yield idx, nxt
                idx = nxt

        if kind in ("bold", "italic"):
            family = {"bold": {"bold", "bold_italic"},
                      "italic": {"italic", "bold_italic"}}[kind]
            have = all(set(t.tag_names(i)) & family for i, _ in chars())
            turn_on = not have
            for i, n in chars():
                tags = set(t.tag_names(i))
                b_now = bool(tags & {"bold", "bold_italic"})
                i_now = bool(tags & {"italic", "bold_italic"})
                if kind == "bold":
                    b_now = turn_on
                else:
                    i_now = turn_on
                for tag in ("bold", "italic", "bold_italic"):
                    t.tag_remove(tag, i, n)
                if b_now and i_now:
                    t.tag_add("bold_italic", i, n)
                elif b_now:
                    t.tag_add("bold", i, n)
                elif i_now:
                    t.tag_add("italic", i, n)
        elif kind in ("underline", "strike"):
            have = all(kind in t.tag_names(i) for i, _ in chars())
            for i, n in chars():
                if have:
                    t.tag_remove(kind, i, n)
                else:
                    t.tag_add(kind, i, n)
        elif kind in ("text_color", "highlight"):
            prefix = kind + "_"
            for tag in list(t.tag_names()):
                if tag.startswith(prefix):
                    t.tag_remove(tag, s, e)
            if value:
                t.tag_add(self._ensure_color_tag(t, kind, value), s, e)
        self._refresh_format_buttons()

    def _editor_typing_style(self, t):
        """What the NEXT typed character in the cell should wear: the
        pending colours first, otherwise the style of the character the
        caret sits after (or of the selection about to be replaced, or of
        the character ahead at the very start) -- typing in the middle of
        a blue word stays blue instead of falling back to plain ink."""
        ref = None
        try:
            if t.compare("sel.first", "<", "sel.last"):
                ref = t.index("sel.first")
        except tk.TclError:
            pass
        if ref is None:
            ins = t.index("insert")
            if (t.compare(ins, ">", "1.0")
                    and t.get(f"{ins} -1c", ins) != "\n"):
                ref = t.index(f"{ins} -1c")
            elif t.get(ins, f"{ins} +1c") not in ("", "\n"):
                ref = ins
        st = dict(self._PLAIN_STYLE)
        if ref is not None:
            tags = set(t.tag_names(ref))
            st = {"bold": bool(tags & {"bold", "bold_italic"}),
                  "italic": bool(tags & {"italic", "bold_italic"}),
                  "underline": "underline" in tags,
                  "strike": "strike" in tags, "fg": None, "bg": None}
            for tag in tags:
                if tag.startswith("text_color_"):
                    st["fg"] = "#" + tag[len("text_color_"):]
                elif tag.startswith("highlight_"):
                    st["bg"] = "#" + tag[len("highlight_"):]
        if self._pending_text_color:
            st["fg"] = self._pending_text_color
        if self._pending_highlight_color:
            st["bg"] = self._pending_highlight_color
        return st

    def _editor_paint_range(self, t, s, e, st):
        """One uniform style over [s, e) in the editor -- the modeled
        tags are cleared first, so the range wears exactly *st*."""
        for tag in list(t.tag_names()):
            if is_format_tag(tag, fonts=False):
                t.tag_remove(tag, s, e)
        if st["bold"] and st["italic"]:
            t.tag_add("bold_italic", s, e)
        elif st["bold"]:
            t.tag_add("bold", s, e)
        elif st["italic"]:
            t.tag_add("italic", s, e)
        if st["underline"]:
            t.tag_add("underline", s, e)
        if st["strike"]:
            t.tag_add("strike", s, e)
        if st["fg"]:
            t.tag_add(self._ensure_color_tag(t, "text_color", st["fg"]),
                      s, e)
        if st["bg"]:
            t.tag_add(self._ensure_color_tag(t, "highlight", st["bg"]),
                      s, e)

    _EDITOR_PASSTHROUGH_KEYS = {
        "Return", "KP_Enter", "Tab", "Escape", "BackSpace", "Delete",
        "Left", "Right", "Up", "Down", "Home", "End", "Prior", "Next",
    }

    def _editor_flush_type_paint(self):
        """Dress whatever the last recorded keystroke typed, if it has
        not been dressed yet. Called from BOTH ends of the key pair --
        fast typing interleaves the events (press, press, release,
        release), and a paint that waited for its own release skipped
        every character whose bookkeeping the next press overwrote."""
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return
        st = editor.pop("type_style", None)
        if st is None:
            return
        t = editor["entry"]
        try:
            s, e = t.index("typestart"), t.index("insert")
            if t.compare(s, "<", e):
                self._editor_paint_range(t, s, e, st)
                self._editor_retag_emoji(t)
        except tk.TclError:
            pass

    def _editor_key_press(self, event=None):
        """BEFORE the class binding inserts the typed character: dress what
        the last keystroke left plain, and note where this one lands and
        what it wears -- Tk inherits a tag only between two carriers, and a
        letter at a coloured run's END arrived plain."""
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return
        self._editor_flush_type_paint()
        char = getattr(event, "char", "") or ""
        keysym = getattr(event, "keysym", "")
        if (len(char) != 1 or ord(char) < 32
                or keysym in self._EDITOR_PASSTHROUGH_KEYS):
            return
        t = editor["entry"]
        try:
            editor["type_style"] = self._editor_typing_style(t)
            try:
                start = (t.index("sel.first")
                         if t.compare("sel.first", "<", "sel.last")
                         else t.index("insert"))
            except tk.TclError:
                start = t.index("insert")
            t.mark_set("typestart", start)
            t.mark_gravity("typestart", "left")
        except tk.TclError:
            editor.pop("type_style", None)

    def _editor_key_release(self, event=None):
        """AFTER the character landed: dress it."""
        self._editor_flush_type_paint()

    def _grid_line_of_row(self, info, r):
        """The text line a data row lives on -- the separator makes the
        mapping non-trivial, and every write must go through it."""
        first = self._grid_first_line(info)
        if first is None:
            return None
        offsets = info.get("row_off")
        if offsets and r < len(offsets):
            return first + offsets[r]
        return first + r

    def _grid_boundary_at(self, info, x):
        """Which column's right edge sits within grabbing distance of x."""
        for c in range(1, len(info["col_x"])):
            if abs(x - info["col_x"][c]) <= 4:
                return c - 1
        return None

    def _grid_row_boundary_at(self, info, y):
        """Which row's bottom edge sits within grabbing distance of y --
        the vertical twin of the column rule, for dragging rows taller
        or shorter."""
        row_y = info.get("row_y") or []
        for r in range(1, len(row_y)):
            if abs(y - row_y[r]) <= 4:
                return r - 1
        return None

    @_undo_atom
    def _grid_set_row_lines(self, info, r, lines):
        """One row's height, as its line count. Growing pads the row's
        tallest cell with empty <br> lines; shrinking trims trailing
        empty lines from every cell -- never below anyone's real
        content, so the table's text is never cut by a drag."""
        cells_in_row = [(c, cell) for (rr, c), cell in info["cells"].items()
                        if rr == r and cell.get("rs", 1) == 1]
        if not cells_in_row:
            return
        first = self._grid_first_line(info)
        if first is None:
            return

        def core_of(value):
            segs = core_tables.cell_display_lines(value)
            while len(segs) > 1 and not segs[-1].strip():
                segs.pop()
            return segs

        floor = max(len(core_of(cell["value"])) for _c, cell in cells_in_row)
        target = max(max(1, lines), floor)
        anchor_c = max(cells_in_row,
                       key=lambda item: len(core_tables.cell_display_lines(
                           item[1]["value"])))[0]
        changed = False
        for c, cell in cells_in_row:
            core = core_of(cell["value"])
            want = target if c == anchor_c else len(core)
            new_value = core_tables.LINE_BREAK.join(
                core + [""] * (want - len(core)))
            if new_value != cell["value"]:
                self._write_cell(info, r, c, new_value)
                cell["value"] = new_value
                changed = True
        if changed:
            self._grid_after_op(first)

    def _grid_cell_at_xy(self, info, x, y):
        """Which cell a canvas point falls in. Covered positions have no
        cell of their own, so a click inside a merge finds its anchor."""
        for (r, c), cell in info["cells"].items():
            if (cell["x"] <= x < cell["x"] + cell["w"]
                    and cell["y"] <= y < cell["y"] + cell["h"]):
                return r, c
        return None

    def _open_cell_editor(self, info, r, c, select=True):
        """One floating Entry over one cell -- the only live widget a table
        ever has. Everything else is drawn, which is what lets a table of
        hundreds of rows scroll without dragging the editor down."""
        # Committing the previous editor can rebuild the grids, destroying the
        # canvas `info` names: anchored by line first, as _editor_step does.
        anchor_line = self._grid_first_line(info)
        self._commit_cell_editor()
        if anchor_line is not None:
            fresh = self._grid_at_line(anchor_line)
            if fresh is not None:
                info = fresh
        cell = info["cells"].get((r, c))
        if cell is None:
            return
        canvas = info["canvas"]
        if not int(canvas.winfo_exists()):
            return
        header_font, cell_font = self._grid_fonts()
        base_font = header_font if r == 0 else cell_font
        # A Text, not an Entry: a cell holds line breaks (<br>) and shows its
        # styles while edited. It wears the cell's own background, or "half
        # the cell's colour" was gone while typing (field report).
        paint = self._grid_cell_paint(info, r, c)
        surface = (inset_surface(self.colors) if r == 0
                   else self.colors["card"])
        editor_bg = (self._blend_hex(paint["bg"], surface, 0.45)
                     if paint["bg"] else surface)
        entry = tk.Text(canvas, relief="flat", bd=0, wrap="none",
                        font=(base_font.cget("family"),
                              base_font.cget("size"),
                              "bold" if r == 0 else "normal"),
                        bg=editor_bg, fg=self.colors["text"],
                        insertbackground=self.colors["text"],
                        highlightthickness=0, padx=2, pady=2, undo=True)
        # A checkbox opens empty: its marker is how the box is stored, not
        # words -- shown, it read as raw brackets until replaced (field
        # pass). What goes in takes the box's place; nothing keeps the box.
        box = core_tables.checkbox_state(cell["value"]) is not None
        if not box:
            entry.insert("1.0", cell["value"].replace(
                core_tables.LINE_BREAK, "\n"))
        self._editor_configure_style_tags(entry, r == 0)
        raw_styles = []
        row_line = self._grid_line_of_row(info, r)
        if row_line is not None:
            line = self.body_text.get(f"{row_line}.0", f"{row_line}.end")
            if not box:
                raw_styles = self._cell_value_styles(row_line, line, c)
                self._editor_apply_display_styles(entry, cell["value"],
                                                  raw_styles)
            row_aligns = core_tables.cell_alignments(line)
            if c < len(row_aligns):
                entry.tag_configure("cellalign", justify={
                    core_tables.ALIGN_CENTER: "center",
                    core_tables.ALIGN_RIGHT: "right",
                }.get(row_aligns[c], "left"))
                entry.tag_add("cellalign", "1.0", "end")
        self._editor_retag_emoji(entry)
        # The cell's words are where it starts, not an edit: left on its
        # Undo, Ctrl+Z took them out and leaving the cell saved it empty
        # (the final audit's twelfth round), as _reset_text_undo keeps the body.
        entry.edit_reset()
        if select:
            entry.tag_add("sel", "1.0", "end-1c")
        entry.mark_set("insert", "end-1c")
        win = canvas.create_window(cell["x"] + 1, cell["y"] + 1, anchor="nw",
                                   width=cell["w"] - 2, height=cell["h"] - 2,
                                   window=entry)
        self._cell_editor = {"entry": entry, "win": win, "info": info,
                             "r": r, "c": c, "box": box,
                             "styles_in": [dict(s) for s in raw_styles]}
        entry.focus_set()
        self._refresh_list_buttons()
        # The old editor's destroy hands focus to the root a moment later:
        # asked again once the queue settles.
        self.after_idle(lambda e=entry: e.focus_set()
                        if e.winfo_exists() else None)
        # The record dies with the widget, by any route (<Destroy>): kept, the
        # toolbar aimed at a dead editor on the next note. The identity test
        # spares a new editor's record.
        entry.bind("<Destroy>",
                   lambda _e, this=entry: self._forget_dead_cell_editor(this),
                   add="+")
        entry.bind("<Tab>", lambda e: self._editor_step(+1, e))
        entry.bind("<Shift-Tab>", lambda e: self._editor_step(-1, e))
        # X11's Shift+Tab is its own keysym, unknown on Windows, where the
        # binding may fail.
        try:
            entry.bind("<ISO_Left_Tab>",
                       lambda e: self._editor_step(-1, e))
        except tk.TclError:
            pass
        # The toolbar's Bold and the rest style the open cell; so do their
        # keys, which Tk's Text took for its own (Ctrl+I a tab over the words).
        for key, style in self.FORMAT_KEYS:
            entry.bind(key, lambda _e, s=style: (self._toggle_body_style(s), "break")[1])
        entry.bind("<Return>", lambda _e: self._editor_newline())
        entry.bind("<Shift-Return>", lambda _e: self._editor_newline())
        # The cell's menu from the keyboard, as a drawn control's opens: every
        # row, column and merge command lived in a right-click alone. "App"
        # is Windows' menu key, "Menu" X11's; Tk raises on the one it lacks.
        for seq in ("<Shift-F10>", "<App>", "<Menu>"):
            try:
                entry.bind(seq, lambda _e, i=info: self._grid_menu_from_keys(i))
            except tk.TclError:
                pass
        # Escape LEAVES the cell keeping the typing, as Tab and a click do: it
        # closed without a commit, and threw the typing away.
        entry.bind("<Escape>", lambda _e: self._editor_escape())
        entry.bind("<FocusOut>",
                   lambda _e, this=entry: self.after_idle(
                       lambda: self._maybe_close_cell_editor(this)))
        entry.bind("<KeyPress>", self._editor_key_press, add="+")
        entry.bind("<KeyRelease>", self._editor_key_release, add="+")
        entry.bind("<KeyRelease>",
                   lambda _e, w=win, cv=canvas: self._grow_cell_editor(w, cv),
                   add="+")
        entry.bind("<MouseWheel>", self._forward_grid_wheel)
        # The floating editor sits exactly over its cell, so a right-click
        # lands on it, not the canvas -- commit and show the same menu.
        entry.bind("<Button-3>",
                   lambda e, i=info: self._editor_context_menu(i, e))
        # Ctrl+V with a copied block of cells spreads it from this cell;
        # plain text falls through to the Entry's own paste.
        entry.bind("<Control-v>",
                   lambda e, i=info: self._editor_paste(i))
        entry.bind("<Control-V>",
                   lambda e, i=info: self._editor_paste(i))
        entry.bind("<<PasteSelection>>",
                   lambda e: self._paste_selection_capped(e, in_body=True))
        # Ctrl+A selects the whole cell -- Tk's Text default for it is
        # an emacs-style line-start jump nobody here is looking for.
        def _select_all_cell(_e, t=entry):
            try:
                t.tag_add("sel", "1.0", "end-1c")
                t.mark_set("insert", "end-1c")
            except tk.TclError:
                pass
            return "break"
        entry.bind("<Control-a>", _select_all_cell)
        entry.bind("<Control-A>", _select_all_cell)
        # Keep the edited cell inside the scrolled viewport.
        try:
            shown = int(float(canvas.cget("width")))
            left = canvas.canvasx(0)
            if cell["x"] < left or cell["x"] + cell["w"] > left + shown:
                canvas.xview_moveto(
                    max(0.0, cell["x"] / max(1, info["natural"])))
        except tk.TclError:
            pass
        # ...and inside the note's view, top to bottom: Tab into a row below
        # the edge sent the typing into a cell nobody could see (round 6).
        self.after_idle(lambda: self._see_cell(info, r, c))

    def _see_cell(self, info, row, col):
        """Bring a drawn table's cell into the note's view, top to bottom. A
        table is one line as tall as its grid, and seeing that line left a
        cell of a tall table below the edge. Measured where the view is: a
        cell in sight moves nothing, and every move made here comes before
        the commit's re-pin is let go, which put a moved view back (round 7)."""
        first = self._grid_first_line(info)
        cell = info["cells"].get((row, col))
        if first is None or cell is None:
            return
        b = self.body_text
        try:
            line = b.dlineinfo(f"{first}.0")
            if line is None:
                self._grid_view_restore = None
                b.see(f"{first}.0")
                line = b.dlineinfo(f"{first}.0")
                if line is None:
                    return
            top = line[1] + 6 + cell["y"]          # 6: the grid window's pady
            bottom = top + cell.get("h", info.get("row_h", 24))
            if top < 0:
                self._grid_view_restore = None
                b.yview_scroll(int(top) - 4, "pixels")
            elif bottom > b.winfo_height():
                self._grid_view_restore = None
                b.yview_scroll(int(bottom - b.winfo_height()) + 4, "pixels")
        except tk.TclError:
            pass

    def _close_cell_editor(self):
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return
        self._cell_editor = None
        try:
            editor["info"]["canvas"].delete(editor["win"])
        except tk.TclError:
            pass
        try:
            editor["entry"].destroy()
        except tk.TclError:
            pass
        # A commit that widened a column left the drawing behind the text;
        # the rebuild waits for this moment so it never happens under an
        # editor still open on the grid.
        if editor["info"].pop("stale", False):
            # The commit promises the view stays where the user was --
            # capture explicitly so the restore holds in force through
            # the late window-mapping (the double-click jump's root).
            self._grid_saved_view = self._capture_grid_views()
            self._render_table_grids()

    def _forget_dead_cell_editor(self, entry):
        """A destroyed cell editor stops being the open one (see where
        _open_cell_editor binds this)."""
        editor = getattr(self, "_cell_editor", None)
        if editor is not None and editor.get("entry") is entry:
            self._cell_editor = None

    def _maybe_close_cell_editor(self, source=None):
        """FocusOut closes the editor -- except under the emoji picker, whose
        emoji still needs somewhere to land. *source* is the entry whose
        FocusOut scheduled this: a destroyed one's must not close the NEW
        editor (stepping through cells died after one).
        """
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return
        if source is not None and source is not editor["entry"]:
            return
        try:
            focus = self.focus_get()
        except (tk.TclError, KeyError):
            focus = None
        if focus is editor["entry"]:
            return
        if focus is None or focus is self:
            # Mid-transfer, the focus reads as the root: closing here killed
            # every step-through's second cell. A click names a widget.
            return
        popup = getattr(self, "_mini_popup", None)
        try:
            if popup is not None and popup.winfo_exists():
                return
        except tk.TclError:
            pass
        self._commit_cell_editor()

    # Opening a cell and every table operation commit first, mostly with no
    # cell open: such a call is a no-op, and its unit noted the note's
    # formatting twice for nothing.
    @_undo_atom(only_if=lambda self: getattr(self, "_cell_editor", None))
    def _commit_cell_editor(self, close=True):
        """The editor's value reaches the hidden text, then the drawing.

        The text is written while the grid's mark is still alive -- writing
        after a teardown would find no line to write to, and the keystrokes
        still sitting in the box would be lost.
        """
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return False
        # A commit can arrive between a keystroke's press and release --
        # the typed character gets its dress before it is sampled.
        self._editor_flush_type_paint()
        info, r, c = editor["info"], editor["r"], editor["c"]
        try:
            content = editor["entry"].get("1.0", "end-1c")
            display_styles = self._editor_sample_styles(
                editor["entry"], content)
        except tk.TclError:
            content, display_styles = None, None
        if editor.get("box") and content is not None and not content.strip():
            content = None      # a box opened and left empty stays a box
        wrote = False
        cell = info["cells"].get((r, c))
        if content is not None and cell is not None:
            # Spaces and tabs trim off the ends; NEWLINES stay -- an
            # empty last line the user just made with Enter is the room
            # they are about to type into, not stray whitespace.
            lead = len(content) - len(content.lstrip(" \t"))
            trimmed = content.strip(" \t").replace(core_tables.CELL, "/")
            display_styles = (display_styles or [])[lead:lead + len(trimmed)]
            while len(display_styles) < len(trimmed):
                display_styles.append(dict(self._PLAIN_STYLE))
            trimmed = mend_surrogates(trimmed)
            display_styles = display_styles[:len(trimmed)]
            value, raw_styles = self._styles_display_to_raw(
                trimmed, display_styles)
            changed_text = value != cell["value"]
            styles_changed = raw_styles != editor.get("styles_in")
            if changed_text:
                old_lines = len(core_tables.cell_display_lines(
                    cell["value"]))
                self._write_cell(info, r, c, value)
                cell["value"] = value
                if len(core_tables.cell_display_lines(value)) != old_lines:
                    # The row must grow or shrink to the new line count;
                    # the rebuild waits for the editor to close.
                    info["stale"] = True
                first = self._grid_first_line(info)
                if first is not None:
                    data = [self.body_text.get(f"{n}.0", f"{n}.end")
                            for n in (self._grid_line_of_row(info, i)
                                      for i in range(info["data_rows"]))
                            if n is not None]
                    widths = core_tables.column_widths(
                        [core_tables.split_row(line) for line in data])
                    if widths != info["widths_chars"]:
                        info["stale"] = True
            if changed_text or styles_changed:
                # The editor's styles ARE the cell's: to the body tags, then
                # the drawing, redrawn as runs.
                self._apply_styles_to_cell(info, r, c, value, raw_styles)
                self._grid_redraw_cell_text(info, r, c)
                editor["styles_in"] = [dict(s) for s in raw_styles]
                wrote = True
        if "cell_highlight" in editor:
            # The cell's own highlight, laid the way a highlight on a closed
            # cell is: pipe to pipe, so an empty cell keeps it. At every
            # commit -- leaving the note flushes without closing the cell.
            self._grid_apply_style(info, (r, c, r, c), "highlight",
                                   editor.pop("cell_highlight"),
                                   through_editor=False)
            wrote = True
        if close:
            self._close_cell_editor()
        if wrote:
            self._schedule_autosave()
        return wrote

    def _write_cell(self, info, r, c, value):
        b = self.body_text
        first = self._grid_first_line(info)
        if first is None:
            return
        line_no = self._grid_line_of_row(info, r)
        if line_no is None:
            return
        base = 1 if line_no == first else 0
        line = b.get(f"{line_no}.0", f"{line_no}.end")
        bounds = core_tables.cell_bounds(line)
        if c >= len(bounds):
            return
        start, end = bounds[c]
        old = line[start:end]
        if old != value:
            # Only the differing middle: a whole delete took every tag, and a
            # styled cell padded by a row-height drag came back plain.
            p = 0
            while p < len(old) and p < len(value) and old[p] == value[p]:
                p += 1
            sfx = 0
            while (sfx < len(old) - p and sfx < len(value) - p
                   and old[len(old) - 1 - sfx] == value[len(value) - 1 - sfx]):
                sfx += 1
            t_a = base + self._tk_col(line, start + p)
            t_b = base + self._tk_col(line, end - sfx)
            if base:
                self._note_edit_with_window()
            if t_b > t_a:
                b.delete(f"{line_no}.{t_a}", f"{line_no}.{t_b}")
            mid = value[p:len(value) - sfx]
            if mid:
                b.insert(f"{line_no}.{t_a}", mid)
            self._align_table_block(first)

    def _editor_step(self, delta, event=None):
        """Tab and Shift+Tab between cells; Tab at the very last one adds
        a row, which is what lets a whole table be typed without the
        mouse. Backwards out of the first cell stays put. Ctrl+Tab and
        Ctrl+Shift+Tab reach these bindings too, and leave the note."""
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return "break"
        if getattr(event, "state", 0) & 0x4:      # Control held
            self._commit_cell_editor()
            return self._leave_note_by_keys(delta)
        info, r, c = editor["info"], editor["r"], editor["c"]
        anchor_line = self._grid_first_line(info)
        self._commit_cell_editor()
        fresh = (self._grid_at_line(anchor_line)
                 if anchor_line is not None else None)
        if fresh is None:
            self._keyboard_to_kept_table(anchor_line, r, c + delta)
            return "break"
        order = sorted(fresh["cells"])
        try:
            index = order.index((r, c)) + delta
        except ValueError:
            index = 0
        if index >= len(order):
            self._grid_add_row(fresh)
            return "break"
        if index < 0:
            index = 0
        self._open_cell_editor(fresh, *order[index])
        return "break"

    def _editor_newline(self):
        """Enter (and Shift+Enter) start a new line INSIDE the cell, stored
        as <br>; the ROW grows now -- the taller editor hid the row below --
        by commit, rebuild, reopen, caret where it was. Tab, Escape or a
        click leave the cell."""
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return "break"
        entry = editor["entry"]
        self._editor_flush_type_paint()
        try:
            # Taken over from Tk's own Enter, which replaces a selection
            # first: the selected words stayed, a line break cut into them.
            if _selection_holds_caret(entry):
                entry.delete("sel.first", "sel.last")
            entry.insert("insert", "\n")
            entry.tag_add("cellalign", "1.0", "end")
            caret = entry.index("insert")
            typed = entry.get("1.0", "insert")
        except tk.TclError:
            return "break"
        info, r, c = editor["info"], editor["r"], editor["c"]
        anchor_line = self._grid_first_line(info)
        self._commit_cell_editor()
        fresh = (self._grid_at_line(anchor_line)
                 if anchor_line is not None else None)
        if fresh is not None and (r, c) in fresh["cells"]:
            self._open_cell_editor(fresh, r, c, select=False)
            reopened = getattr(self, "_cell_editor", None)
            if reopened is not None:
                try:
                    reopened["entry"].mark_set("insert", caret)
                except tk.TclError:
                    pass
        elif fresh is None:
            self._keyboard_to_kept_table(anchor_line, r, c, typed=typed)
        return "break"

    def _editor_escape(self):
        """Escape leaves the cell, keeping what was typed, and the keyboard
        goes to the note's text under the table -- where the caret always
        goes from a drawn table's lines (_caret_out_of_hidden) -- or, when
        the commit left the table as text, into it at the cell. The editor
        held it, and Tk left it on the window once the editor went: what was
        typed next went nowhere, and Tab began again at the tab strip."""
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return "break"
        info, r, c = editor["info"], editor["r"], editor["c"]
        anchor_line = self._grid_first_line(info)
        self._commit_cell_editor()
        fresh = (self._grid_at_line(anchor_line)
                 if anchor_line is not None else None)
        if fresh is None:
            self._keyboard_to_kept_table(anchor_line, r, c)
        elif self._keyboard_nowhere():
            b = self.body_text
            try:
                b.mark_set("insert", f"{anchor_line + fresh['nrows']}.0")
                b.see("insert")
            except tk.TclError:
                pass
            self._keyboard_to(b)
        return "break"

    def _editor_fit_window(self):
        """Grow the floating editor's window to its line count -- the
        drawn row itself grows on commit, when the grids may rebuild."""
        editor = getattr(self, "_cell_editor", None)
        if not editor:
            return
        info, cell = editor["info"], editor["info"]["cells"].get(
            (editor["r"], editor["c"]))
        if cell is None:
            return
        try:
            lines = int(editor["entry"].index("end-1c").split(".")[0])
            # Capped as a drawn table is: past it the box scrolls inside.
            need = min(max(cell["h"] - 2, lines * info["row_h"]),
                       self.MAX_DRAWN_TABLE_PX)
            if need > int(float(info["canvas"].itemcget(
                    editor["win"], "height"))):
                info["canvas"].itemconfigure(editor["win"], height=need)
        except (tk.TclError, ValueError):
            pass

    def _insert_emoji_from_toolbar(self):
        """The toolbar emoji button lands in whatever is being written --
        the open table cell if there is one, the note body otherwise."""
        editor = getattr(self, "_cell_editor", None)
        target = editor["entry"] if editor else self.body_text
        self._show_emoji_picker(target, anchor=self.emoji_btn)

    def _grid_available_width(self):
        """How wide a table may draw before it has to scroll instead."""
        try:
            width = self.body_text.winfo_width()
        except tk.TclError:
            width = 0
        # Before the editor is mapped the widget reports 1; better to let a
        # table draw at its natural width than to squeeze it into nothing.
        return width - 50 if width > 120 else 10_000

    def _fit_grid(self, info):
        """Size one grid's viewport, showing a scrollbar only when needed."""
        canvas = info.get("canvas")
        if canvas is None:
            return
        avail = max(160, self._grid_available_width())
        shown = min(info["natural"] + 1, avail)
        try:
            if int(float(canvas.cget("width"))) != shown:
                canvas.configure(width=shown)
        except tk.TclError:
            return
        needs_bar = info["natural"] + 1 > avail
        hbar = info.get("hbar")
        if needs_bar and hbar is None:
            hbar = ttk.Scrollbar(info["frame"], orient="horizontal",
                                 command=canvas.xview)
            canvas.configure(xscrollcommand=hbar.set)
            info["hbar"] = hbar
        if hbar is not None:
            if needs_bar:
                hbar.pack(side="top", fill="x")
            else:
                hbar.pack_forget()

    def _on_body_resize_grids(self, _event=None):
        for info in getattr(self, "_table_grids", []):
            self._fit_grid(info)

    def _wheel_pixels(self, delta):
        """One notch of the wheel, in pixels. A unit is a text LINE, and
        a drawn table is one line as tall as the whole grid -- so unit
        scrolling leapt from table to table instead of gliding."""
        if not delta:
            return 0
        notches = -delta / 120.0
        step = int(notches * 60)
        if step == 0:
            step = -1 if delta > 0 else 1
        return step

    def _text_wheel_scroll(self, text_widget, event, fallback_canvas=None):
        """One wheel step over a text box, in PIXELS: THE handler for the
        body's wheel, its own and the grids' forwarded (an earlier one was
        overwritten by bind() without add, the tests green). A box whose
        content fits scrolls the page instead."""
        # A deliberate wheel move beats a grid rebuild's pending
        # view restore -- the user outranks the machinery here just
        # as on the note list.
        self._grid_view_restore = None
        try:
            first, last = text_widget.yview()
        except (tk.TclError, ValueError):
            return
        fits = first <= 0.0 and last >= 1.0
        if fits:
            target = fallback_canvas or getattr(self, "editor_canvas", None)
            if target is not None:
                try:
                    target.yview_scroll(int(-1 * (event.delta / 120)),
                                        "units")
                except (tk.TclError, ValueError):
                    pass
            return "break"
        try:
            text_widget.yview_scroll(self._wheel_pixels(event.delta),
                                     "pixels")
        except tk.TclError:
            pass
        return "break"

    def _forward_grid_wheel(self, event):
        """The wheel over a table scrolls the note, as it does over text."""
        return self._text_wheel_scroll(self.body_text, event)

    def _grid_wheel_x(self, canvas, event):
        """Shift+wheel pans a wide table sideways."""
        try:
            canvas.xview_scroll(-1 if event.delta > 0 else 1, "units")
        except tk.TclError:
            pass
        return "break"

    # A table past either stays text: drawn whole, 300x300 froze the app 40 s
    # and 1,000 rows passed the 32,767-px canvas (ISSUES_LOG: "The table
    # drawn whole"). 400 rows stay under it at 225%.
    MAX_DRAWN_TABLE_ROWS = 400
    MAX_DRAWN_TABLE_CELLS = 3000
    # And past this height, at the scale and text size it would be drawn at:
    # a row is as tall as its cell with the most lines, and 250 rows of
    # four-line addresses passed the canvas limit inside both caps above.
    MAX_DRAWN_TABLE_PX = 30_000

    def _table_too_big_to_draw(self, lines, first0, last0):
        """Whether the table on lines *first0*..*last0* (0-based) is past
        what is drawn as a grid."""
        rows = last0 - first0 + 1
        if rows > self.MAX_DRAWN_TABLE_ROWS:
            return True
        cells = [core_tables.split_row(lines[i])
                 for i in range(first0, min(last0 + 1, len(lines)))]
        widest = max((len(row) for row in cells), default=0)
        if rows * widest > self.MAX_DRAWN_TABLE_CELLS:
            return True
        # Every line of every row counted, the separator's too: a few
        # pixels over-counted, never under.
        row_h = self._grid_row_height()
        return sum(row_h * max((len(core_tables.cell_display_lines(v))
                                for v in row), default=1)
                   for row in cells) > self.MAX_DRAWN_TABLE_PX

    def _grid_row_height(self):
        """The height of one line of a drawn table's row, padding included:
        what the grid is built with, and what its size is judged by."""
        header_font, cell_font = self._grid_fonts()
        return max(header_font.metrics("linespace"),
                   cell_font.metrics("linespace")) + 2 * 7

    def _build_table_grid(self, first, last):
        b = self.body_text
        block = [b.get(f"{n}.0", f"{n}.end") for n in range(first, last + 1)]
        sep_at = core_tables.separator_index(block)
        sep_cols = (core_tables.parse_separator(block[sep_at])
                    if sep_at is not None else None)
        # Data rows and the separator part ways here: the separator is
        # mechanics and is never drawn, so every grid row index maps back
        # to its text line through row_off.
        row_off = [i for i in range(len(block)) if i != sep_at]
        rows = [core_tables.split_row(block[i]) for i in row_off]
        widths = core_tables.column_widths(rows)
        if not widths:
            return
        merges, covered = core_tables.merge_map(rows)
        aligns_matrix = [core_tables.cell_alignments(block[i])
                         for i in row_off]
        header_font, cell_font = self._grid_fonts()
        pad_x = 10
        row_h = self._grid_row_height()
        char_px = cell_font.measure("0")
        floor = char_px * core_tables.MIN_COLUMN
        col_w = [floor] * len(widths)
        hidden_cols = set()
        for c in range(len(widths)):
            column = sep_cols[c] if sep_cols and c < len(sep_cols) else None
            if column and column.get("hidden"):
                # A hidden column is a sliver, not an absence: wide enough
                # to right-click for Unhide, too thin to read.
                hidden_cols.add(c)
                col_w[c] = self.px(14)
                continue
            if column and column.get("width"):
                # The dash count is the width exactly, narrower clipping to an
                # ellipsis; a paste's separators are spelled at the minimum,
                # "no width opinion" (_foreign_plain), and never reach here.
                col_w[c] = char_px * column["width"] + 2 * pad_x
                continue
            for r, row in enumerate(rows):
                span = merges.get((r, c))
                if (r, c) in covered or (span and span[1] > 1):
                    continue
                font = header_font if r == 0 else cell_font
                value = row[c] if c < len(row) else ""
                # A multi-line cell is as wide as its WIDEST line, not as
                # wide as its raw text with the break markers in it.
                col_w[c] = max(col_w[c], max(
                    (self._measure_text(font, seg)
                     for seg in core_tables.cell_display_lines(value)),
                    default=0) + 2 * pad_x)
        col_x = [0]
        for width in col_w:
            col_x.append(col_x[-1] + width)
        natural = col_x[-1]
        # A row is as tall as its tallest cell's line count.
        row_lines = []
        for r, row in enumerate(rows):
            n = 1
            for c in range(len(widths)):
                if (r, c) in covered or c in hidden_cols:
                    continue
                value = row[c] if c < len(row) else ""
                n = max(n, len(core_tables.cell_display_lines(value)))
            row_lines.append(n)
        row_y = [0]
        for n in row_lines:
            row_y.append(row_y[-1] + n * row_h)
        height = row_y[-1]

        host = tk.Frame(b, bg=self.colors["card"], cursor="arrow")
        canvas = tk.Canvas(host, highlightthickness=0, bd=0, cursor="arrow",
                           bg=self.colors["card"], height=height + 1,
                           scrollregion=(0, 0, natural + 1, height + 1))
        canvas.pack(side="top", anchor="w")
        cells = {}
        slivers = []   # a hidden column's rectangles, kept for a repaint
        rule = hairline(self.colors)

        def wash(line_no, line, c, styles):
            """The highlight a cell's rectangle is washed with -- the tag on
            its first character, or on its padding when it is empty: the
            same question _grid_cell_paint asks of a grid already built."""
            if styles:
                return styles[0]["bg"]
            pipes = core_tables.pipe_positions(line)
            if c + 1 >= len(pipes) or pipes[c] + 1 >= pipes[c + 1]:
                return None
            try:
                tags = self.body_text.tag_names(
                    f"{line_no}.{self._tk_col(line, pipes[c] + 1)}")
            except tk.TclError:
                return None
            bg = None
            for t in tags:
                if t.startswith("highlight_"):
                    bg = "#" + t[len("highlight_"):]
            return bg

        # Each cell drawn ONCE, with its styles (a second pass was half of
        # opening a big table): rectangles first, then text.
        texts = []
        for r, row in enumerate(rows):
            for c in range(len(widths)):
                if (r, c) in covered:
                    continue
                row_span, col_span = merges.get((r, c), (1, 1))
                x, y = col_x[c], row_y[r]
                w = col_x[min(c + col_span, len(col_w))] - x
                h = row_y[min(r + row_span, len(rows))] - y
                value = row[c] if c < len(row) else ""
                surface = (inset_surface(self.colors) if r == 0
                           else self.colors["card"])
                if c in hidden_cols:
                    slivers.append((canvas.create_rectangle(
                        x, y, x + w, y + h, fill=surface, outline=rule), r))
                    continue
                line_no = first + row_off[r]
                line = block[row_off[r]]
                # Base 0: read before this grid's window lands at column 0,
                # on lines no other grid starts on (as wash() assumes).
                styles = self._cell_value_styles(line_no, line, c, base=0)
                bg = wash(line_no, line, c, styles)
                # The saved colour stays pure; only the DRAWING blends it
                # toward the cell's surface (see _grid_restyle).
                rect = canvas.create_rectangle(
                    x, y, x + w, y + h,
                    fill=(self._blend_hex(bg, surface, 0.45) if bg
                          else surface),
                    outline=rule)
                align = (aligns_matrix[r][c]
                         if r < len(aligns_matrix)
                         and c < len(aligns_matrix[r])
                         else core_tables.ALIGN_LEFT)
                cell = {"value": value, "rect": rect, "texts": [],
                        "x": x, "y": y, "w": w, "h": h,
                        "rs": row_span, "cs": col_span}
                cells[(r, c)] = cell
                texts.append((cell, value, styles, align, r == 0))
        for cell, value, styles, align, header in texts:
            cell["texts"] = self._grid_draw_cell_text(
                canvas, cell, value, styles, align, header, pad_x, row_h)
        mark = f"table_grid_{id(host)}"
        b.mark_set(mark, f"{first}.0")
        b.mark_gravity(mark, "left")
        info = {"frame": host, "canvas": canvas, "hbar": None,
                "natural": natural, "cells": cells, "slivers": slivers,
                "mark": mark,
                "nrows": len(block), "data_rows": len(rows),
                "row_off": row_off, "sep_cols": sep_cols,
                "hidden_cols": hidden_cols,
                "ncols": len(widths), "row_h": row_h, "col_x": col_x,
                "row_y": row_y, "widths_chars": list(widths)}
        self._fit_grid(info)
        canvas.bind("<Button-1>", lambda e, i=info: self._grid_press(i, e))
        canvas.bind("<B1-Motion>", lambda e, i=info: self._grid_drag(i, e))
        canvas.bind("<ButtonRelease-1>",
                    lambda e, i=info: self._grid_release(i, e))
        canvas.bind("<Button-3>", lambda e, i=info: self._grid_menu(i, e))
        canvas.bind("<Motion>", lambda e, i=info: self._grid_motion(i, e))
        canvas.bind("<Double-Button-1>",
                    lambda e, i=info: self._grid_double(i, e))
        # Saved formatting is already on the text as tags by the time a
        # grid is built (load applies formatting first), so the one pass
        # above painted it from the first frame.
        for widget in (host, canvas):
            widget.bind("<MouseWheel>", self._forward_grid_wheel)
            widget.bind("<Shift-MouseWheel>",
                        lambda ev, cv=canvas: self._grid_wheel_x(cv, ev))
        b.window_create(f"{first}.0", window=host, padx=1, pady=6,
                        align="bottom")
        b.tag_add(self.TABLE_HIDE_TAG, f"{first}.1", f"{last}.end")
        # Tk justifies a line by its FIRST character's tags: the window, at
        # column 0, carries the place, or a centred table snapped left.
        table_align = self._grid_table_align_of(first)
        if table_align in ("center", "right"):
            b.tag_add(f"align_{table_align}", f"{first}.0", f"{first}.1")
        self._table_grids = getattr(self, "_table_grids", [])
        self._table_grids.append(info)

    def _grid_clear_selection(self):
        sel = getattr(self, "_grid_sel", None)
        self._grid_sel = None
        if not sel:
            return
        info = sel["info"]
        rule = hairline(self.colors)
        for key in sel["cells"]:
            cell = info["cells"].get(key)
            if cell is None:
                continue
            try:
                info["canvas"].itemconfigure(cell["rect"],
                                             outline=rule, width=1)
            except tk.TclError:
                pass

    @staticmethod
    def _grid_grown_box(info, a, b):
        """The rectangle spanned by two cells, as ``(r0, c0, r1, c1)``,
        grown until it swallows every merge it touches -- half a merged
        cell is not a thing a selection, or a merge, can hold."""
        r0, r1 = sorted((a[0], b[0]))
        c0, c1 = sorted((a[1], b[1]))
        grew = True
        while grew:
            grew = False
            for (r, c), cell in info["cells"].items():
                if r + cell["rs"] - 1 < r0 or r > r1:
                    continue
                if c + cell["cs"] - 1 < c0 or c > c1:
                    continue
                lo_r, hi_r = min(r0, r), max(r1, r + cell["rs"] - 1)
                lo_c, hi_c = min(c0, c), max(c1, c + cell["cs"] - 1)
                if (lo_r, hi_r, lo_c, hi_c) != (r0, r1, c0, c1):
                    r0, r1, c0, c1 = lo_r, hi_r, lo_c, hi_c
                    grew = True
        return r0, c0, r1, c1

    def _grid_select_range(self, info, a, b):
        """Highlight the rectangle spanned by two cells (_grid_grown_box)."""
        r0, c0, r1, c1 = self._grid_grown_box(info, a, b)
        self._grid_clear_selection()
        chosen = [key for key, cell in info["cells"].items()
                  if r0 <= key[0] <= r1 and c0 <= key[1] <= c1]
        for key in chosen:
            try:
                info["canvas"].itemconfigure(info["cells"][key]["rect"],
                                             outline=self.colors["accent"],
                                             width=2)
            except tk.TclError:
                pass
        self._grid_sel = {"info": info, "cells": chosen,
                          "box": (r0, c0, r1, c1)}

    def _grid_press(self, info, event):
        # Canvas coordinates are read while the canvas is certainly alive:
        # the commit below can destroy it, and a scrolled table would
        # otherwise aim the click at the wrong cell.
        self._grid_autoscroll_stop()
        press_x = info["canvas"].canvasx(event.x)
        press_y = info["canvas"].canvasy(event.y)
        if getattr(self, "_cell_editor", None) is not None:
            # The press takes the keyboard back from the open editor, or Ctrl+C
            # copied the editor's word, not the cells selected.
            anchor_line = self._grid_first_line(info)
            self._commit_cell_editor()
            self.body_text.focus_set()
            if not int(info["canvas"].winfo_exists()):
                # The commit's rebuild took this canvas, so no release follows:
                # the cell aimed at, by the geometry seen, opens at the press.
                self._grid_pressed = None
                hit = self._grid_cell_at_xy(info, press_x, press_y)
                fresh = (self._grid_at_line(anchor_line)
                         if anchor_line is not None else None)
                if fresh is not None and hit is not None:
                    self._open_cell_editor(fresh, *hit)
                return "break"
        canvas = info["canvas"]
        x = press_x
        boundary = self._grid_boundary_at(info, x)
        if boundary is not None:
            # Grabbing a rule resizes its column instead of selecting.
            self._grid_resizing = {"info": info, "col": boundary, "x": x}
            self._grid_pressed = None
            return "break"
        row_boundary = self._grid_row_boundary_at(info, press_y)
        if row_boundary is not None:
            # The horizontal rule resizes its row, the vertical twin of
            # dragging a column wider.
            self._grid_row_resizing = {"info": info, "row": row_boundary,
                                       "y": press_y}
            self._grid_pressed = None
            return "break"
        hit = self._grid_cell_at_xy(info, x, press_y)
        self._grid_clear_selection()
        self._grid_pressed = (info, hit, x, press_y) if hit else None
        return "break"

    def _grid_drag_autoscroll(self, info):
        """While a cell drag runs, the view follows the pointer: the
        grid pans sideways past its own viewport, and the NOTE scrolls
        when the pointer crosses the editor's top or bottom edge -- so a
        selection can reach cells that were not on screen when the drag
        began, the way any spreadsheet allows. The selection is then
        re-stretched to whatever sits under the pointer now."""
        self._grid_view_restore = None
        canvas = info.get("canvas")
        try:
            if canvas is None or not int(canvas.winfo_exists()):
                return
            px, py = self.winfo_pointerxy()
            wx = px - canvas.winfo_rootx()
            wy = py - canvas.winfo_rooty()
            try:
                shown = int(float(canvas.cget("width")))
            except (tk.TclError, ValueError):
                shown = canvas.winfo_width()
            natural = max(1, info.get("natural", 1))
            if wx > shown - 24 and canvas.xview()[1] < 1.0:
                canvas.xview_moveto(min(1.0, canvas.xview()[0]
                                        + 24.0 / natural))
            elif wx < 24 and canvas.xview()[0] > 0.0:
                canvas.xview_moveto(max(0.0, canvas.xview()[0]
                                        - 24.0 / natural))
            body = self.body_text
            top = body.winfo_rooty()
            bottom = top + body.winfo_height()
            if py > bottom - 16:
                body.yview_scroll(24, "pixels")
            elif py < top + 16:
                body.yview_scroll(-24, "pixels")
            pressed = getattr(self, "_grid_pressed", None)
            if pressed and pressed[0] is info:
                hit = self._grid_cell_at_xy(info, canvas.canvasx(wx),
                                            canvas.canvasy(wy))
                if hit and hit != pressed[1]:
                    self._grid_select_range(info, pressed[1], hit)
        except tk.TclError:
            pass

    def _grid_autoscroll_tick(self):
        self._grid_autoscroll_job = None
        info = getattr(self, "_grid_drag_hold", None)
        if info is None:
            return
        self._grid_drag_autoscroll(info)
        self._grid_autoscroll_job = self.after(
            60, self._grid_autoscroll_tick)

    def _grid_autoscroll_stop(self):
        self._grid_drag_hold = None
        job = getattr(self, "_grid_autoscroll_job", None)
        self._grid_autoscroll_job = None
        if job is not None:
            try:
                self.after_cancel(job)
            except (tk.TclError, ValueError):
                pass

    def _grid_drag(self, info, event):
        if (getattr(self, "_grid_resizing", None)
                or getattr(self, "_grid_row_resizing", None)):
            return "break"
        pressed = getattr(self, "_grid_pressed", None)
        if not pressed or pressed[0] is not info:
            return "break"
        # A held pointer at an edge produces no more motion events; the
        # timer keeps the view (and the selection) moving until release.
        self._grid_drag_hold = info
        if getattr(self, "_grid_autoscroll_job", None) is None:
            self._grid_autoscroll_job = self.after(
                60, self._grid_autoscroll_tick)
        canvas = info["canvas"]
        hit = self._grid_cell_at_xy(info, canvas.canvasx(event.x),
                                    canvas.canvasy(event.y))
        if hit and hit != pressed[1]:
            self._grid_select_range(info, pressed[1], hit)
        return "break"

    def _grid_release(self, info, event):
        """A plain click opens the editor; a drag leaves its selection."""
        self._grid_autoscroll_stop()
        self.after_idle(self._refresh_list_buttons)
        resizing = getattr(self, "_grid_resizing", None)
        self._grid_resizing = None
        if resizing is not None and resizing["info"] is info:
            canvas = info["canvas"]
            # A press beside a rule that never moved is a click, not a
            # drag -- applying it would nudge the width by a rounding
            # error every time someone clicks near a boundary.
            if abs(canvas.canvasx(event.x) - resizing["x"]) < 3:
                return "break"
            col = resizing["col"]
            left = info["col_x"][col]
            new_px = canvas.canvasx(event.x) - left
            _hf, cell_font = self._grid_fonts()
            char_px = max(1, cell_font.measure("0"))
            self._grid_set_col_width(
                info, col, max(2, round((new_px - 20) / char_px)))
            return "break"
        row_resizing = getattr(self, "_grid_row_resizing", None)
        self._grid_row_resizing = None
        if row_resizing is not None and row_resizing["info"] is info:
            canvas = info["canvas"]
            if abs(canvas.canvasy(event.y) - row_resizing["y"]) < 3:
                return "break"
            row = row_resizing["row"]
            top = info.get("row_y", [0])[row] if row < len(
                info.get("row_y", [])) else 0
            new_px = canvas.canvasy(event.y) - top
            self._grid_set_row_lines(
                info, row, max(1, round(new_px / info["row_h"])))
            return "break"
        pressed = getattr(self, "_grid_pressed", None)
        self._grid_pressed = None
        if pressed is None or pressed[0] is not info:
            return "break"
        if getattr(self, "_grid_sel", None) is None and pressed[1]:
            # A drag inside one cell selects THAT cell whole (one took two); a
            # short click still opens the editor.
            canvas = info["canvas"]
            moved = max(abs(canvas.canvasx(event.x) - pressed[2]),
                        abs(canvas.canvasy(event.y) - pressed[3]))
            if moved >= 10:
                self._grid_select_range(info, pressed[1], pressed[1])
                self.body_text.focus_set()
            elif not self._grid_toggle_checkbox(info, *pressed[1]):
                # A checkbox cell toggles on click; every other cell
                # opens for typing, as always. Editing a checkbox AS
                # TEXT stays available from its right-click menu.
                self._open_cell_editor(info, *pressed[1])
        else:
            # A finished drag leaves a selection; the keyboard belongs to
            # it now, so Delete and Ctrl+C/V land on the cells no matter
            # where focus wandered before the drag.
            self.body_text.focus_set()
        return "break"

    @staticmethod
    def _tk_units(text):
        """How many index steps *text* is wide in a Tk Entry: UTF-16 units,
        an emoji two, or the caret parked inside it. By the codec, not
        character by character (131,000 walked to open a 60-row table).
        """
        return len(text.encode("utf-16-le", "surrogatepass")) // 2

    @classmethod
    def _tk_col(cls, line, char_col):
        """A Python character offset into *line*, as a Tk Text column.

        Tk counts UTF-16 units, so every astral character before the offset
        widens it by one. Addressing the text with raw character offsets cut
        into the wrong place the moment a cell held an emoji -- and every
        flush re-cut at the drifted position, multiplying the damage.
        """
        return cls._tk_units(line[:char_col])

    @staticmethod
    def _py_col(line, tk_col):
        """A Tk Text column into *line*, as a Python character offset —
        the inverse of _tk_col. A unit index landing inside an astral
        pair resolves past that character (never mid-character), and
        anything beyond the line clamps to its length. Without this, a
        Tk column read from an index was used to slice Python strings
        directly, drifting one place per emoji to its left."""
        u = 0
        for i, ch in enumerate(line):
            if u >= tk_col:
                return i
            u += 2 if ord(ch) > 0xFFFF else 1
        return len(line)

    @staticmethod
    def _astral_span_at(s, iu, before):
        """The character whose UTF-16 span contains unit index *iu*
        (``before=False``), or ends at / straddles it (``before=True``).

        Returns ``(start_unit, unit_width)``, or ``(None, None)`` past
        either end of the string.
        """
        u = 0
        for ch in s:
            w = 2 if ord(ch) > 0xFFFF else 1
            if (before and u < iu <= u + w) or (not before and u <= iu < u + w):
                return u, w
            u += w
        return None, None

    def _entry_backspace_astral(self, event):
        """BackSpace in a tk.Entry deletes one UTF-16 unit, half an emoji,
        which saved as question marks (field report): the whole character
        goes instead; elsewhere None, stock behaviour. A tk.Text deletes
        whole characters itself."""
        w = event.widget
        try:
            if w.select_present():
                return None  # Tk deletes the whole selection; no tearing
            s = w.get()
            iu = w.index("insert")
        except tk.TclError:
            return None
        start, width = self._astral_span_at(s, iu, before=True)
        if width == 2:
            w.delete(start, start + width)
            return "break"
        return None

    def _entry_delete_astral(self, event):
        """The Delete-key twin of _entry_backspace_astral."""
        w = event.widget
        try:
            if w.select_present():
                return None
            s = w.get()
            iu = w.index("insert")
        except tk.TclError:
            return None
        start, width = self._astral_span_at(s, iu, before=False)
        if width == 2:
            w.delete(start, start + width)
            return "break"
        return None

    def _guard_entry_astral(self, entry):
        """Arm a free-text tk.Entry against tearing astral characters —
        bound on every Entry that accepts arbitrary text (title, searches,
        checklist items, category and template names, the username)."""
        entry.bind("<BackSpace>", self._entry_backspace_astral)
        entry.bind("<Delete>", self._entry_delete_astral)

    def _restore_editor_view(self, at):
        try:
            self.editor_canvas.yview_moveto(at)
        except tk.TclError:
            pass

    def _restore_views_idle(self, page, body, explicit=False):
        # After a paste the view follows the caret, honoured here: a see() in
        # the paste handler ran before this restore, which undid it.
        follow = getattr(self, "_body_follow_caret", False)
        self._body_follow_caret = False
        if follow:
            self._grid_view_restore = None
            try:
                self.body_text.see("insert")
            except tk.TclError:
                pass
        elif body is not None or page is not None:
            if body is not None:
                try:
                    self.body_text.yview_moveto(body)
                except tk.TclError:
                    pass
            if page is not None:
                self._restore_editor_view(page)
            # An op that PROMISES the view stays (explicit capture) holds it
            # briefly on timers, as the windows map late ("the scroll jumps to
            # the table's start"); an ambient render applies it once.
            if explicit:
                self._grid_view_restore = {
                    "page": page, "body": body,
                    "until": time.monotonic() + 0.5}
                for delay in (60, 160, 360):
                    self.after(delay, self._reapply_grid_view_restore)
            else:
                self._grid_view_restore = None
        if page is None and body is None and not follow:
            self._grid_view_restore = None

    def _editor_scrollbar_moved(self, *args):
        self._grid_view_restore = None
        try:
            self.editor_canvas.yview(*args)
        except tk.TclError:
            pass

    def _body_scrollbar_moved(self, *args):
        self._grid_view_restore = None
        try:
            self.body_text.yview(*args)
        except tk.TclError:
            pass

    def _reapply_grid_view_restore(self):
        """One timed beat of a still-in-force grid-rebuild restore."""
        pend = getattr(self, "_grid_view_restore", None)
        if not pend or not self._still_alive():
            return
        if time.monotonic() > pend["until"]:
            self._grid_view_restore = None
            return
        if pend["body"] is not None:
            try:
                self.body_text.yview_moveto(pend["body"])
            except tk.TclError:
                pass
        if pend["page"] is not None:
            self._restore_editor_view(pend["page"])

    def _flush_table_grids(self):
        """Anything still in the open cell editor reaches the text, the
        editor left open. With none open there is nothing to flush and no
        undo unit is opened -- only the undo boundary it always left, which
        makes Ctrl+Z take typing back a pause at a time.
        """
        if not getattr(self, "_cell_editor", None):
            # A run of deletes of styled text ends here too, or Ctrl+Z after a
            # pause mid-BackSpace gave a bold word back plain.
            self._close_styled_delete_run()
            try:
                self.body_text.edit_separator()
            except (tk.TclError, AttributeError):
                pass
            return False
        return self._commit_cell_editor(close=False)

    @_undo_atom
    def _grid_add_row(self, info):
        """Tab at the last cell: make somewhere to go, as the text path does."""
        first = self._grid_first_line(info)
        if first is None:
            return "break"
        self._commit_cell_editor()
        again = self._grid_at_line(first)
        if again is not None:
            info = again
        last = first + info["nrows"] - 1
        self.body_text.insert(
            f"{last}.end",
            "\n" + core_tables.blank_table(1, info["ncols"])[0])
        self._align_table_block(first)
        self._resync_list_tags()
        self._render_table_grids()
        fresh = self._grid_at_line(first)
        if fresh is not None:
            # Cells are keyed by data row: nrows counts the separator too,
            # and with one no cell was found and the keyboard fell to nothing.
            bottom = fresh["data_rows"] - 1
            for c in range(fresh["ncols"]):
                if (bottom, c) in fresh["cells"]:
                    self._open_cell_editor(fresh, bottom, c)
                    break
        else:
            self._keyboard_to_kept_table(first, info["data_rows"], 0)
        self._schedule_autosave()
        return "break"

    def _extend_word_styles_on_typing(self, event=None):
        """Letters glued onto a styled word wear the word's styles: Tk extends
        a tag only between two carriers ("the new letters don't get the
        colour"). A space typed first leaves them behind, as the field report
        asked.
        """
        self._spread_typed_run()

    # Two marks around what a key types (see _spread_typed_run): text
    # inserted at the caret goes after the first and before the second.
    _TYPED_FROM = "typedFrom"
    _TYPED_TO = "typedTo"

    def _note_key_down(self, _event=None):
        """Any key going down in the body, noted first (a bindtag ahead of
        the body's; Cut, Clear and Paste by their virtual events, which
        outrank <KeyPress>): what the key before typed is settled now, so a
        paste stays out of its Ctrl's run, and fast typing goes on from the
        style just given."""
        self._spread_typed_run()

    def _note_typing_key(self, event=None):
        """A key that types, going down (one with a binding of its own never
        gets here): two marks at the caret, between which what it types
        lands, settled at its release or the next press (_spread_typed_run).
        Control without Alt types nothing (Ctrl+T's swap took the style);
        Control with Alt is AltGr, which types; Insert is a paste."""
        state = getattr(event, "state", 0)
        if ((state & 0x4 and not state & 0x20000)
                or getattr(event, "keysym", "") == "Insert"):
            return
        b = self.body_text
        try:
            b.mark_set(self._TYPED_FROM, "insert")
            b.mark_gravity(self._TYPED_FROM, "left")
            b.mark_set(self._TYPED_TO, "insert")
            b.mark_gravity(self._TYPED_TO, "right")
        except tk.TclError:
            return
        self._typed_run_open = True

    def _spread_typed_run(self):
        """Settle what the last typing key put in: letters glued onto a
        styled character wear its styles, up to a space typed with them --
        only what went in between the marks, from the buffer, not the event
        (a synthetic key carries none). Read at the caret, an arrow key made
        a plain ":" bold, and a table's padding passed styles on."""
        if not getattr(self, "_typed_run_open", False):
            return
        self._typed_run_open = False
        b = self.body_text
        try:
            start = b.index(self._TYPED_FROM)
            end = b.index(self._TYPED_TO)
            if not (b.compare(start, "<", end)
                    and b.compare(start, ">", "1.0")):
                return
            prev = b.index(f"{start} -1c")
            self._take_run_between(start, end)
            if not b.get(prev).strip():
                return
            # The first space among the letters typed, found in Python: Tk's
            # search read the whole line for it, a quarter of a second a key
            # with the find bar open on a long paragraph (round 10).
            typed = b.get(start, end)
            cut = next((i for i, ch in enumerate(typed) if ch.isspace()), None)
            stop = end if cut is None else b.index(f"{start}+{cut}c")
            if not b.compare(start, "<", stop):
                return
            for tag in b.tag_names(prev):
                if is_format_tag(tag, fonts=False):
                    b.tag_add(tag, start, stop)
            # ...its size and font too, drawn with the weight they now wear.
            self._fit_font_tags(start, stop, like=prev)
        except tk.TclError:
            pass

    def _take_run_between(self, start, end):
        """Text put between two pieces of one size or font differing only in
        weight (by a bold word in a bigger heading) takes the run's size and
        font with its own weight -- it came out at the base size, splitting
        the heading. Every road in asks: typed, pasted, the emoji picker,
        the calculator. True when it did."""
        b = self.body_text
        try:
            if not b.compare(start, ">", "1.0"):
                return False
            prev = b.index(f"{start} -1c")
            sides = [[parse_font_tag(t) for t in b.tag_names(i)
                      if parse_font_tag(t)] for i in (prev, end)]
            if not (all(sides) and sides[0][-1][2:] == sides[1][-1][2:]):
                return False
            self._fit_font_tags(start, end, like=prev)
        except tk.TclError:
            return False
        return True

    # Two marks around what Tk's own paste puts in (see _on_body_paste),
    # as _TYPED_FROM and _TYPED_TO are around what a key types.
    _PASTE_FROM = "pasteFrom"
    _PASTE_TO = "pasteTo"

    def _settle_tk_paste(self):
        """What Tk's own Ctrl+V put in, between the marks set before it ran,
        takes the run it landed in (_take_run_between)."""
        b = self.body_text
        try:
            start, end = b.index(self._PASTE_FROM), b.index(self._PASTE_TO)
            b.mark_unset(self._PASTE_FROM, self._PASTE_TO)
        except tk.TclError:
            return
        if b.compare(start, "<", end):
            self._take_run_between(start, end)

    def _reassert_line_alignment(self, _event=None):
        """Keep the caret's line wearing its own alignment while typed into:
        Tk justifies by the FIRST character's tag, and a letter typed at a
        centred line's start lands untagged and yanked it left. The whole
        line is dressed in what its characters, its newline among them, keep.
        """
        b = self.body_text
        try:
            ln = int(b.index("insert").split(".")[0])
            for align in ("center", "right"):
                tag = f"align_{align}"
                # Anywhere on the line counts, the newline included: an empty
                # centred line keeps it only there.
                if b.tag_nextrange(tag, f"{ln}.0", f"{ln}.end+1c"):
                    b.tag_add(tag, f"{ln}.0", f"{ln}.end")
                    break
        except (tk.TclError, ValueError):
            pass

    def _selection_end_at_table(self, first, nrows, event):
        """The moving end of a selection landed on a drawn table: the caret
        stays with it at the table's near edge, a next press carrying both
        past it -- a table is never taken in without a second press, and a
        drag stops at the edge it came from. Walked under alone, the caret
        left the selection behind, and the next letter deleted the table.
        True when placed here; False leaves it to the caret guard."""
        b = self.body_text
        try:
            sel_first, sel_last = b.index("sel.first"), b.index("sel.last")
        except tk.TclError:
            return False
        top = f"{first}.0"
        above = b.index(f"{top} -1c")
        below = b.index(f"{first + nrows}.0")
        if (getattr(self, "_sel_crossed_table", None) == (first, "up")
                and b.compare(sel_first, "<=", top)
                and b.compare(sel_last, ">=", below)):
            # Just crossed up over a table on the first line, the caret stays;
            # read as a first press, a letter kept the table and Delete took it.
            return True
        # Which end moved, by the ends against the table, not the caret: a
        # table redrawn there pushes the caret a column on.
        if b.compare(sel_first, "<", top) and b.compare(sel_last, ">=", top):
            direction, edge, past = "down", above, below
        elif (b.compare(sel_last, ">=", below)
                and b.compare(sel_first, "<", below)):
            direction, edge, past = "up", below, above
        else:
            if (b.compare(top, "<=", sel_first)
                    and b.compare(sel_last, "<", below)):
                # Both ends on the table's hidden text: nothing anyone could
                # see choosing, and a cut would have taken rows apart.
                b.tag_remove("sel", sel_first, sel_last)
            return False
        keyed = getattr(event, "type", None) in (tk.EventType.KeyPress,
                                                 tk.EventType.KeyRelease)
        held = getattr(self, "_sel_held_at_table", None)
        try:
            if keyed and held is not None and held[:2] == (first, direction):
                if direction == "down":
                    b.tag_add("sel", sel_first, past)
                else:
                    b.tag_add("sel", past, sel_last)
                b.mark_set("insert", past)
                self._sel_held_at_table = None
                self._sel_crossed_table = (first, direction)
                return True
            if direction == "down":
                b.tag_remove("sel", edge, sel_last)
            else:
                b.tag_remove("sel", sel_first, edge)
            b.mark_set("insert", edge)
        except tk.TclError:
            return False
        self._sel_held_at_table = ((first, direction, edge) if keyed
                                   else None)
        return True

    def _selection_ends_off_tables(self):
        """A selection end left on a drawn table's hidden text, the caret
        elsewhere, goes to the table's edge facing the other end: a press
        right of a grid lands in its last row, and the next key glued the
        row onto the paragraph under it ("| Tea | 2 |er")."""
        b = self.body_text
        for info in getattr(self, "_table_grids", []):
            first = self._grid_first_line(info)
            if first is None:
                continue
            try:
                start, end = b.index("sel.first"), b.index("sel.last")
            except tk.TclError:
                return
            top = f"{first}.0"
            below = b.index(f"{first + info['nrows']}.0")
            # A start at the table's top is its edge (Ctrl+A in a note opening
            # with a table was cut short); an END there is on it, holding the
            # line break above.
            start_on = (b.compare(top, "<", start)
                        and b.compare(start, "<", below))
            end_on = (b.compare(top, "<=", end)
                      and b.compare(end, "<", below))
            try:
                if start_on and not end_on:
                    b.tag_remove("sel", start, below)
                elif end_on and not start_on:
                    b.tag_remove("sel", b.index(f"{top} -1c"), end)
            except tk.TclError:
                return

    def _caret_past_marker(self, _event=None):
        """A click on a list's marker -- "3." or "•" -- puts the caret after
        it, at the item's words. Before it, a letter typed made "x3. ham",
        a line that is no item any more (the owner's call, 2026-10-22, on
        both apps). A click that selects is left as it is."""
        b = self.body_text
        try:
            if b.tag_ranges("sel"):
                return None
            line_no, col = (int(p) for p in b.index("insert").split("."))
            line = b.get(f"{line_no}.0", f"{line_no}.end")
        except (tk.TclError, ValueError):
            return None
        kind, marker, _rest = parse_list_marker(line)
        # The marker's characters are all in the Basic Multilingual Plane,
        # so Tk's columns and Python's agree inside it.
        if kind and col < len(marker):
            b.mark_set("insert", f"{line_no}.{len(marker)}")
            self._resync_pending_style_anchor()
            self._refresh_format_buttons()
        return None

    def _caret_out_of_hidden(self, _event=None):
        """Keep the caret off a drawn table's lines entirely -- there, typing
        edits hidden text or floats beside the grid -- walking it to the line
        under the table. On a key press it also holds the edges against Tk's
        own line-joining Ctrl+H and Ctrl+K, which pulled a row onto the
        prose; Delete and BackSpace ask in their own handlers.
        """
        b = self.body_text
        try:
            line_no = int(b.index("insert").split(".")[0])
        except (tk.TclError, ValueError):
            return None
        held = getattr(self, "_sel_held_at_table", None)
        met = False
        for info in getattr(self, "_table_grids", []):
            first = self._grid_first_line(info)
            if first is not None and first <= line_no < first + info["nrows"]:
                met = True
                if not self._selection_end_at_table(first, info["nrows"],
                                                    _event):
                    try:
                        b.mark_set("insert", f"{first + info['nrows']}.0")
                    except tk.TclError:
                        pass
                break
        # Every time: a drag between two tables left its start on the first's
        # hidden text, and Delete or a paste merged them.
        self._selection_ends_off_tables()
        if met:
            # The caret was where this left it, not on the table: noted there,
            # the next key "left" the table and padded it outside its undo unit
            # -- two Ctrl+Z for one letter.
            try:
                self._last_caret_line = int(b.index("insert").split(".")[0])
            except (tk.TclError, ValueError):
                pass
        if not met:
            self._sel_crossed_table = None
        if not met and held is not None:
            # The stop at a table's edge is remembered only while the caret
            # stays there; any other move forgets it.
            try:
                if b.compare("insert", "!=", held[2]):
                    self._sel_held_at_table = None
            except tk.TclError:
                self._sel_held_at_table = None
        if (getattr(_event, "type", None) == tk.EventType.KeyPress
                and getattr(_event, "state", 0) & 0x4):
            keysym = getattr(_event, "keysym", "")
            try:
                at_line_end = b.compare("insert", "==", "insert lineend")
            except tk.TclError:
                at_line_end = False
            if ((keysym == "h"
                 and self._deletion_joins_table(False, selection_wins=False))
                    or (keysym == "k" and at_line_end
                        and self._deletion_joins_table(
                            True, selection_wins=False))):
                return "break"
            if keysym == "t":
                # Tk's Ctrl+T swaps the characters around the caret: at a
                # table's edge one is its line break ("| Eggs | 12 |r"). Any
                # character the edge holds stops it, empty line or not.
                at = "insert" if at_line_end else "insert+1c"
                try:
                    pair = (b.index(f"{at}-2c"), b.index(f"{at}-1c"))
                    if any(_table_edge_holds(self, i) for i in pair):
                        return "break"
                except tk.TclError:
                    pass
        return None

    def _deletion_joins_table(self, forward, selection_wins=True):
        """Would a one-character deletion at the caret break a drawn table --
        take its edge (the line breaks above and below, or anything between),
        gluing a line onto a row? An EMPTY line of the caret's own may go,
        unless that merges two tables or takes the line kept under a
        note-ending table. *selection_wins*: a caret inside a selection
        deletes the selection instead, as Tk does.
        """
        b = self.body_text
        try:
            if selection_wins and _selection_holds_caret(b):
                return False
            if not forward and b.compare("insert", "==", "1.0"):
                return False
            at = b.index("insert" if forward else "insert-1c")
            if not _table_edge_holds(self, at):
                return False
            if b.compare("insert linestart", "==", "insert lineend"):
                line = int(b.index("insert").split(".")[0])
                far = line - 1 if forward else line + 1
                total = int(b.index("end-1c").split(".")[0])
                if far < 1:
                    return False
                if far <= total and not is_table_row(
                        b.get(f"{far}.0", f"{far}.end")):
                    return False
            return True
        except (tk.TclError, ValueError):
            return False

    # ---------- The table's own right-click menu ----------

    def _capture_grid_views(self):
        """The page scroll, the body's own scroll, and each wide table's
        sideways position -- everything a rebuild has to put back."""
        try:
            page = self.editor_canvas.yview()[0]
        except (tk.TclError, AttributeError, IndexError):
            page = None
        try:
            body = self.body_text.yview()[0]
        except (tk.TclError, IndexError):
            body = None
        sideways = {}
        for info in getattr(self, "_table_grids", []):
            line = self._grid_first_line(info)
            if line is not None and info.get("canvas") is not None:
                try:
                    sideways[line] = info["canvas"].xview()[0]
                except (tk.TclError, IndexError):
                    pass
        return page, body, sideways

    def _grid_op_context(self, info):
        """(first, nrows, ncols) with the editor committed and grids down.

        Structural edits move real characters around the window's own
        column; the simplest correct order is grids down, text edited
        plain, grids back up.
        """
        first = self._grid_first_line(info)
        if first is None:
            return None
        self._commit_cell_editor()
        again = self._grid_at_line(first)
        if again is not None:
            info = again
            first = self._grid_first_line(info) or first
        shape = (first, info["nrows"], info["ncols"])
        self._grid_saved_view = self._capture_grid_views()
        self._teardown_table_grids()
        return shape

    def _grid_after_op(self, first):
        self._align_table_block(first)
        self._resync_list_tags()
        self._render_table_grids()
        self._schedule_autosave()
        self._refresh_list_buttons()

    def _grid_block_parts(self, first, text_rows):
        """(data_rows, data_aligns, sep_cols, sep_at) for one block.

        Every structural operation transforms the data and carries the
        separator's columns alongside, so a hand-dragged width or a hidden
        column survives inserts, deletes, merges and fills.
        """
        block = [self.body_text.get(f"{n}.0", f"{n}.end")
                 for n in range(first, first + text_rows)]
        sep_at = core_tables.separator_index(block)
        sep_cols = (core_tables.parse_separator(block[sep_at])
                    if sep_at is not None else None)
        rows, aligns = [], []
        for i, line in enumerate(block):
            if i == sep_at:
                continue
            rows.append(core_tables.split_row(line))
            aligns.append(core_tables.cell_alignments(line))
        return rows, aligns, sep_cols, sep_at

    def _grid_replace_block(self, first, old_nrows, rows, aligns=None,
                            sep_cols=None, source=None, extra=None):
        """Wholesale rewrite for the ops that reshape a table, no cell they
        did not touch changing: styles read off first and laid back (a bold
        word died for an edit three cells away). *source* maps a new (row,
        column) to its old one for ops that move cells; *extra* gives cells
        pasted from our own copy their styles. See _grid_lay_cell_styles.
        """
        b = self.body_text
        # The rewrite deletes the tagged text, and the table's position on
        # the page would go with it -- read it first, put it back after.
        table_align = self._grid_table_align_of(first)
        carried = self._grid_read_cell_styles(first, old_nrows)
        carried.update(extra or {})
        b.delete(f"{first}.0", f"{first + old_nrows - 1}.end")
        lines = core_tables.format_table(rows, aligns)
        if sep_cols is not None and lines:
            sep_line = self._grid_separator_line(sep_cols, rows)
            lines = [lines[0], sep_line] + lines[1:]
        b.insert(f"{first}.0", "\n".join(lines))
        self._grid_lay_cell_styles(first, lines, carried, source)
        if table_align in ("center", "right"):
            for n in range(first, first + len(lines)):
                b.tag_add(f"align_{table_align}", f"{n}.0", f"{n}.end")

    def _grid_read_cell_styles(self, first, nrows):
        """Every data cell's styles, read before a rewrite deletes them:
        ``{(row, col): {"value", "runs", "pad_bg", "paint_bg"}}`` -- *runs*
        its text's format tags as ``(tag, start, end)``, *pad_bg* a
        CELL-level highlight, *paint_bg* the colour the drawing washes it
        with (_grid_cell_paint). Read range by range: a few dozen Tk calls.
        """
        b = self.body_text
        block = [b.get(f"{n}.0", f"{n}.end")
                 for n in range(first, first + nrows)]
        sep_at = core_tables.separator_index(block)
        data = [i for i in range(len(block)) if i != sep_at]
        runs = {i: [] for i in data}
        top, bottom = f"{first}.0", f"{first + nrows - 1}.end"
        # A drawn table's window sits at column 0 of its first line, counted
        # by the indices and not by get(): the copy reads with grids up.
        first_base = self._col_base(first)
        for tag in b.tag_names():
            if not is_format_tag(tag):
                continue
            ranges = b.tag_ranges(tag)
            for k in range(0, len(ranges) - 1, 2):
                s, e = str(ranges[k]), str(ranges[k + 1])
                if b.compare(e, "<=", top) or b.compare(s, ">=", bottom):
                    continue
                s_line, s_col = (int(p) for p in s.split("."))
                e_line, e_col = (int(p) for p in e.split("."))
                for n in range(max(s_line, first),
                               min(e_line, first + nrows - 1) + 1):
                    i = n - first
                    if i not in runs:
                        continue
                    line = block[i]
                    base = first_base if n == first else 0
                    a = (self._py_col(line, max(0, s_col - base))
                         if n == s_line else 0)
                    z = (self._py_col(line, max(0, e_col - base))
                         if n == e_line else len(line))
                    if z > a:
                        runs[i].append((tag, a, z))
        cells = {}
        for r, i in enumerate(data):
            line = block[i]
            pipes = core_tables.pipe_positions(line)
            for c, (s, e) in enumerate(core_tables.cell_bounds(line)):
                lo = pipes[c] + 1 if c < len(pipes) else s
                hi = pipes[c + 1] if c + 1 < len(pipes) else e
                paint_at = s if e > s else lo
                rec = {"value": line[s:e], "runs": [], "pad_bg": None,
                       "paint_bg": None}
                for tag, a, z in runs[i]:
                    if not (a < hi and z > lo):
                        continue
                    if a < e and z > s:
                        rec["runs"].append((tag, max(a, s) - s,
                                            min(z, e) - s))
                    if tag.startswith("highlight_"):
                        if a < s or z > e or s == e:
                            rec["pad_bg"] = tag
                        if a <= paint_at < z:
                            rec["paint_bg"] = tag
                cells[(r, c)] = rec
        return cells

    def _grid_lay_cell_styles(self, first, lines, carried, source=None):
        """Lay the styles _grid_read_cell_styles read back on the cells of
        the freshly written *lines*: an unchanged cell gets all of them; one
        the operation CHANGED keeps only its colour, over the whole cell. A
        merge's cell, given as ``(anchor, joined)``, gives each piece's
        styles back while it reads as their texts joined by a space.
        """
        b = self.body_text
        sep_at = core_tables.separator_index(lines)
        r = -1
        for i, line in enumerate(lines):
            if i == sep_at:
                continue
            r += 1
            line_no = first + i
            pipes = core_tables.pipe_positions(line)
            for c, (s, e) in enumerate(core_tables.cell_bounds(line)):
                src = source(r, c) if source is not None else (r, c)
                joined = ()
                if src is not None and isinstance(src[0], tuple):
                    src, joined = src
                rec = carried.get(src) if src is not None else None
                if rec is None:
                    continue
                same = line[s:e] == rec["value"]
                wash = rec["pad_bg"] if same else rec["paint_bg"]
                if wash and c + 1 < len(pipes):
                    b.tag_add(wash,
                              f"{line_no}.{self._tk_col(line, pipes[c] + 1)}",
                              f"{line_no}.{self._tk_col(line, pipes[c + 1])}")
                if not same:
                    parts = [carried.get(k) for k in joined]
                    if not (parts and all(parts) and line[s:e] == " ".join(
                            p["value"] for p in parts)):
                        continue
                    offset = 0
                    for part in parts:
                        for tag, a, z in part["runs"]:
                            lo = self._tk_col(line, s + offset + a)
                            hi = self._tk_col(line, s + offset + z)
                            b.tag_add(tag, f"{line_no}.{lo}",
                                      f"{line_no}.{hi}")
                        offset += len(part["value"]) + 1
                    continue
                for tag, a, z in rec["runs"]:
                    b.tag_add(tag,
                              f"{line_no}.{self._tk_col(line, s + a)}",
                              f"{line_no}.{self._tk_col(line, s + z)}")

    def _dissolve_orphan_markers(self, rows):
        _spans, covered = core_tables.merge_map(rows)
        for r, row in enumerate(rows):
            for c, value in enumerate(row):
                if (value in (core_tables.MERGE_LEFT, core_tables.MERGE_UP)
                        and (r, c) not in covered):
                    rows[r][c] = ""
        return rows

    @_undo_atom
    def _grid_insert_row(self, info, at):
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, ncols = context
        rows, _aligns, _sep, sep_at = self._grid_block_parts(first, nrows)
        data_off = [i for i in range(nrows) if i != sep_at]
        if sep_at is not None and at < sep_at:
            # Insert row above, on the header, goes under it: above, the
            # separator moves to the third line, where it is no separator.
            at = sep_at
        blank = core_tables.blank_table(1, ncols)[0]
        if at >= len(data_off):
            self.body_text.insert(f"{first + nrows - 1}.end", "\n" + blank)
        else:
            # *at* is a data-row index; the separator shifts the line it
            # maps to. A new first row still goes above the separator only
            # when there is no header to keep -- above everything.
            self.body_text.insert(f"{first + data_off[at]}.0", blank + "\n")
        self._grid_after_op(first)

    @_undo_atom
    def _grid_insert_col(self, info, at):
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, _ncols = context
        rows, aligns, sep_cols, _sep_at = self._grid_block_parts(first, nrows)
        for row in rows:
            row.insert(min(at, len(row)), "")
        for row_aligns in aligns:
            row_aligns.insert(min(at, len(row_aligns)),
                              core_tables.ALIGN_LEFT)
        if sep_cols is not None:
            sep_cols.insert(min(at, len(sep_cols)),
                            {"width": None, "align": None, "hidden": False})
        self._grid_replace_block(
            first, nrows, rows, aligns, sep_cols,
            source=lambda r, c: ((r, c) if c < at
                                 else (r, c - 1) if c > at else None))
        self._grid_after_op(first)

    @_undo_atom
    def _grid_delete_row(self, info, r):
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, _ncols = context
        if nrows <= 1:
            self._grid_after_op(first)
            return
        rows, aligns, sep_cols, _sep_at = self._grid_block_parts(first, nrows)
        if r >= len(rows):
            self._grid_after_op(first)
            return
        del rows[r]
        del aligns[r]
        rows = self._dissolve_orphan_markers(rows)
        gone = r
        self._grid_replace_block(
            first, nrows, rows, aligns, sep_cols,
            source=lambda rr, c: (rr if rr < gone else rr + 1, c))
        self._grid_after_op(first)

    @_undo_atom
    def _grid_delete_col(self, info, c):
        """At two columns, deleting empties the chosen column instead.

        A one-column row reads as prose, not as a table -- "| just one |"
        is deliberately not a row, or quoting something between pipes would
        redraw it as a grid -- so two columns is the floor. Removing the
        table outright is its own menu entry.
        """
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, ncols = context
        rows, aligns, sep_cols, _sep_at = self._grid_block_parts(first, nrows)
        source = None
        if ncols <= 2:
            for row in rows:
                if c < len(row):
                    row[c] = ""
            rows = self._dissolve_orphan_markers(rows)
        else:
            source = (lambda r, cc: (r, cc if cc < c else cc + 1))
            spans, _covered = core_tables.merge_map(rows)
            for (ar, ac), (rs, cs) in spans.items():
                if ac <= c < ac + cs:
                    for rr in range(ar, ar + rs):
                        for cc in range(ac, ac + cs):
                            if (rr, cc) != (ar, ac) and cc < len(rows[rr]):
                                rows[rr][cc] = ""
            for row in rows:
                if c < len(row):
                    del row[c]
            for row_aligns in aligns:
                if c < len(row_aligns):
                    del row_aligns[c]
            if sep_cols is not None and c < len(sep_cols):
                del sep_cols[c]
            rows = self._dissolve_orphan_markers(rows)
        self._grid_replace_block(first, nrows, rows, aligns, sep_cols,
                                 source=source)
        self._grid_after_op(first)

    # No person's action calls this any more (the menus merge through
    # _grid_merge_selection); qa1 and mutant TM01 still write a marker by it.
    @_undo_atom
    def _grid_set_marker(self, info, r, c, marker):
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, _ncols = context
        rows, aligns, sep_cols, _sep_at = self._grid_block_parts(first, nrows)
        if r < len(rows) and c < len(rows[r]):
            rows[r][c] = marker
        self._grid_replace_block(first, nrows, rows, aligns, sep_cols)
        self._grid_after_op(first)

    @_undo_atom
    def _grid_split(self, info, r, c):
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, _ncols = context
        rows, aligns, sep_cols, _sep_at = self._grid_block_parts(first, nrows)
        spans, _covered = core_tables.merge_map(rows)
        for (ar, ac), (rs, cs) in spans.items():
            if ar <= r < ar + rs and ac <= c < ac + cs:
                for rr in range(ar, ar + rs):
                    for cc in range(ac, ac + cs):
                        if (rr, cc) != (ar, ac) and cc < len(rows[rr]):
                            rows[rr][cc] = ""
                break
        self._grid_replace_block(first, nrows, rows, aligns, sep_cols)
        self._grid_after_op(first)

    def _grid_column_mechanics(self, info, mutate):
        """Shared body for width, hide and autofit: parts, a separator
        conjured if the table has none yet, *mutate* applied, written back."""
        first = self._grid_first_line(info)
        if first is None:
            return
        self._commit_cell_editor()
        again = self._grid_at_line(first)
        if again is not None:
            info = again
            first = self._grid_first_line(info) or first
        nrows = info["nrows"]
        self._grid_saved_view = self._capture_grid_views()
        self._teardown_table_grids()
        rows, aligns, sep_cols, sep_at = self._grid_block_parts(first, nrows)
        if sep_cols is None:
            widths = core_tables.layout_widths(rows, aligns)
            sep_cols = [{"width": width, "align": None, "hidden": False}
                        for width in widths]
        mutate(sep_cols, rows, aligns)
        # These change ONLY the separator line, written alone: rewritten whole,
        # a column drag took every style (colour a cell, resize, colour gone).
        self._grid_write_separator(first, rows, sep_cols, sep_at)
        self._grid_after_op(first)

    @staticmethod
    def _grid_separator_line(sep_cols, rows):
        """The separator line a rewrite writes for *rows*: *sep_cols*, given
        the columns the rows have grown (in place), as text. One writer for
        the rewrite, the separator-only write and a paste weighing itself.
        The columns counted once: counted again for every column added, a
        row of 30,000 pasted cells walked the table 30,000 times."""
        columns = len(core_tables.column_widths(rows))
        while len(sep_cols) < columns:
            sep_cols.append({"width": None, "align": None,
                             "hidden": False})
        return core_tables.CELL + core_tables.CELL.join(
            " " + cell + " "
            for cell in core_tables.make_separator(sep_cols)
        ) + core_tables.CELL

    def _grid_write_separator(self, first, rows, sep_cols, sep_at):
        """Write the block's separator line surgically: replace it in
        place when it exists, insert one under the header when it does
        not. Tags elsewhere in the block are never touched -- an insert
        shifts them along, a same-line replace never reaches them (the
        separator itself holds only mechanics, never user styling)."""
        b = self.body_text
        sep_line = self._grid_separator_line(sep_cols, rows)
        table_align = self._grid_table_align_of(first)
        if sep_at is not None:
            line_no = first + sep_at
            b.delete(f"{line_no}.0", f"{line_no}.end")
            b.insert(f"{line_no}.0", sep_line)
        else:
            line_no = first + 1
            b.insert(f"{first}.end", "\n" + sep_line)
        if table_align in ("center", "right"):
            b.tag_add(f"align_{table_align}",
                      f"{line_no}.0", f"{line_no}.end")

    @_undo_atom
    def _grid_set_col_width(self, info, c, width):
        def mutate(sep_cols, rows, aligns):
            if c < len(sep_cols):
                # Floor 4: three dashes read as "no width opinion", so 4 is
                # the narrowest hand-set width that round-trips.
                sep_cols[c]["width"] = max(4, int(width))
                sep_cols[c]["hidden"] = False
        self._grid_column_mechanics(info, mutate)

    @_undo_atom
    def _grid_autofit_col(self, info, c):
        def mutate(sep_cols, rows, aligns):
            widths = core_tables.layout_widths(rows, aligns)
            if c < len(sep_cols) and c < len(widths):
                sep_cols[c]["width"] = widths[c]
                sep_cols[c]["hidden"] = False
        self._grid_column_mechanics(info, mutate)

    @_undo_atom
    def _grid_autofit_cols(self, info, c0, c1):
        """Autofit every column a selection touches, in ONE pass -- the
        per-column call exists on the single-cell menu, and running it
        once per selected column would tear the grid down that many
        times for one gesture."""
        def mutate(sep_cols, rows, aligns):
            widths = core_tables.layout_widths(rows, aligns)
            for c in range(c0, min(c1 + 1, len(sep_cols))):
                if c < len(widths):
                    sep_cols[c]["width"] = widths[c]
                    sep_cols[c]["hidden"] = False
        self._grid_column_mechanics(info, mutate)

    @_undo_atom
    def _grid_hide_col(self, info, c, hidden=True):
        def mutate(sep_cols, rows, aligns):
            if c < len(sep_cols):
                sep_cols[c]["hidden"] = hidden
        self._grid_column_mechanics(info, mutate)

    @_undo_atom
    def _grid_hide_span(self, info, c0, c1):
        def mutate(sep_cols, rows, aligns):
            for c in range(c0, min(c1 + 1, len(sep_cols))):
                sep_cols[c]["hidden"] = True
        self._grid_column_mechanics(info, mutate)

    @_undo_atom
    def _grid_append_cols(self, info, c0, c1):
        """The selected columns joined again to the table's right edge --
        text and all, exactly as written, empty cells staying empty."""
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, _ncols = context
        rows, aligns, sep_cols, _sep_at = self._grid_block_parts(first, nrows)
        # The copies carry their originals' styles: "text and all".
        old_len = [len(row) for row in rows]

        def source(r, c):
            if c < old_len[r]:
                return (r, c)
            k = c - old_len[r]
            return (r, c0 + k) if k <= c1 - c0 else None

        for row in rows:
            copied = [row[c] if c < len(row) else ""
                      for c in range(c0, c1 + 1)]
            # A merge reaching in from the LEFT of the copied span points
            # at a cell that did not travel; it lands as an empty cell.
            if copied and copied[0] == core_tables.MERGE_LEFT:
                copied[0] = ""
            row.extend(copied)
        for row_aligns in aligns:
            row_aligns.extend([row_aligns[c] if c < len(row_aligns)
                               else core_tables.ALIGN_LEFT
                               for c in range(c0, c1 + 1)])
        if sep_cols is not None:
            sep_cols.extend(dict(sep_cols[c]) if c < len(sep_cols)
                            else {"width": None, "align": None,
                                  "hidden": False}
                            for c in range(c0, c1 + 1))
        rows = self._dissolve_orphan_markers(rows)
        self._grid_replace_block(first, nrows, rows, aligns, sep_cols,
                                 source=source)
        self._grid_after_op(first)

    @_undo_atom
    def _grid_append_rows(self, info, r0, r1):
        """The selected rows joined again to the table's bottom edge --
        the vertical twin of copying columns to the end. A merge
        reaching DOWN into the copied span from above points at a row
        that did not travel; it lands as an empty cell."""
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, _ncols = context
        rows, aligns, sep_cols, _sep_at = self._grid_block_parts(first, nrows)
        copied_rows, copied_aligns = [], []
        for r in range(r0, min(r1 + 1, len(rows))):
            copied_rows.append(list(rows[r]))
            copied_aligns.append(list(aligns[r]) if r < len(aligns)
                                 else [core_tables.ALIGN_LEFT] * len(rows[r]))
        if copied_rows:
            copied_rows[0] = ["" if v == core_tables.MERGE_UP else v
                              for v in copied_rows[0]]
        n_old = len(rows)
        rows.extend(copied_rows)
        aligns.extend(copied_aligns)
        rows = self._dissolve_orphan_markers(rows)
        # The copies carry their originals' styles, as the columns' do.
        self._grid_replace_block(
            first, nrows, rows, aligns, sep_cols,
            source=lambda r, c: (r, c) if r < n_old else (r0 + r - n_old, c))
        self._grid_after_op(first)

    @_undo_atom
    def _grid_unhide_all(self, info):
        def mutate(sep_cols, rows, aligns):
            for column in sep_cols:
                column["hidden"] = False
        self._grid_column_mechanics(info, mutate)

    def _grid_double(self, info, event):
        """A double-click on a rule autofits its column. On a checkbox
        cell it toggles AGAIN: Tk turns the second of two fast clicks
        into a double-click instead of a plain one, and without this a
        quick tick-untick only ticked."""
        canvas = info["canvas"]
        boundary = self._grid_boundary_at(info, canvas.canvasx(event.x))
        if boundary is not None:
            self._grid_resizing = None
            self._grid_autofit_col(info, boundary)
            return "break"
        hit = self._grid_cell_at_xy(info, canvas.canvasx(event.x),
                                    canvas.canvasy(event.y))
        if hit is not None and self._grid_toggle_checkbox(info, *hit):
            self._grid_pressed = None
            return "break"
        return None

    def _grid_motion(self, info, event):
        """The cursor telegraphs a grabbable rule -- vertical or
        horizontal."""
        canvas = info["canvas"]
        near = self._grid_boundary_at(info, canvas.canvasx(event.x))
        near_row = (None if near is not None
                    else self._grid_row_boundary_at(
                        info, canvas.canvasy(event.y)))
        try:
            canvas.configure(cursor=(
                "sb_h_double_arrow" if near is not None
                else "sb_v_double_arrow" if near_row is not None
                else "arrow"))
        except tk.TclError:
            pass

    _TABLE_ALIGN_TAGS = ("align_center", "align_right")

    @_undo_atom
    def _grid_add_line_above(self, info):
        """A blank line above the table -- the menu twin of pressing
        Enter under a leading table, working for any table and needing
        no gesture knowledge at all."""
        first = self._grid_first_line(info)
        if first is None:
            return
        self._commit_cell_editor()
        again = self._grid_at_line(first)
        if again is not None:
            first = self._grid_first_line(again) or first
        # Like the Enter gesture: no view snapshot -- the insert lands at
        # the note's top, the Text keeps the view on its content, and a
        # restore against estimated grid heights measurably yanks it.
        self._teardown_table_grids()
        self.body_text.insert(f"{first}.0", "\n")
        self.body_text.mark_set("insert", f"{first}.0")
        # Noted for the same reason as the Enter gesture: unnoted, the
        # first letter typed on the new line read as leaving the table and
        # rebuilt every table again.
        self._last_caret_line = first
        self._resync_list_tags()
        self._render_table_grids()
        self._schedule_autosave()

    @_undo_atom
    def _grid_set_table_align(self, info, align):
        """The whole table sits left, centred or right on the page, by an
        ordinary alignment tag on its lines, which places the window and
        the paragraphs save; a paste scrubs it, landing flush left.
        """
        first = self._grid_first_line(info)
        if first is None:
            return
        for n in range(first, first + info["nrows"]):
            for stray in self._TABLE_ALIGN_TAGS:
                self.body_text.tag_remove(stray, f"{n}.0", f"{n}.end")
            if align in ("center", "right"):
                self.body_text.tag_add(f"align_{align}",
                                       f"{n}.0", f"{n}.end")
        # Its caption goes with it: on the page the two are one block.
        self._align_lines(self._caption_lines_of(info), align)
        self._schedule_autosave()

    def _caption_lines_of(self, info):
        """The caption right under a drawn table, as line numbers: its
        "Table N:" line and the "Source:" line after it. Empty when the
        line under the table is not a caption -- only one touching its
        table belongs to it."""
        first = self._grid_first_line(info)
        if first is None:
            return []
        below = first + info["nrows"]
        b = self.body_text
        if not core_tables.is_caption_line(b.get(f"{below}.0", f"{below}.end")):
            return []
        lines = [below]
        if core_tables.is_source_line(
                b.get(f"{below + 1}.0", f"{below + 1}.end")):
            lines.append(below + 1)
        return lines

    def _grid_table_align_of(self, first):
        """Which position the block's window line carries.

        Read off the line's LAST character: the first may be the embedded
        window, whose character arrives untagged on every rebuild.
        """
        for tag in self.body_text.tag_names(f"{first}.end-1c"):
            if tag == "align_center":
                return "center"
            if tag == "align_right":
                return "right"
        return "left"

    @_undo_atom
    def _grid_add_caption(self, info):
        """A system-managed caption under the table: a numbered label line
        plus a source line, both placed like the table -- ordinary body
        text after that, editable like anything else. Exists so nobody has
        to hand-build a caption above or below a table and fight its
        alignment (the field request: "the system should insert an editable
        label")."""
        first = self._grid_first_line(info)
        if first is None:
            return
        below = first + info["nrows"] - 1
        b = self.body_text
        # Only caption-shaped lines ("Table 3:"), older "Tab. N:" ones too, so
        # an older note's numbering carries on.
        n = 1 + sum(1 for ln in b.get("1.0", "end-1c").split("\n")
                    if core_tables.is_caption_line(ln))
        caption_text = f"Table {n}: description"
        b.insert(f"{below}.end", "\n" + caption_text + "\nSource: ")
        cap_line = below + 1
        # SCRUB, then dress: the caption came wearing the table's cell
        # highlight (field-tested); it starts from zero.
        for tag in b.tag_names():
            if is_format_tag(tag) or tag.startswith("align_"):
                b.tag_remove(tag, f"{cap_line}.0", f"{cap_line + 2}.0")
        # Both lines follow the TABLE's place, never two alignments (field
        # request).
        place = self._grid_table_align_of(first)
        if place in ("center", "right"):
            b.tag_add(f"align_{place}", f"{cap_line}.0", f"{cap_line}.end")
            b.tag_add(f"align_{place}",
                      f"{cap_line + 1}.0", f"{cap_line + 1}.end")
        # The placeholder comes selected, so typing replaces it at once.
        start = f"{cap_line}.{len(caption_text) - len('description')}"
        b.tag_remove("sel", "1.0", "end")
        b.tag_add("sel", start, f"{cap_line}.end")
        b.mark_set("insert", f"{cap_line}.end")
        b.focus_set()
        self._resync_list_tags()
        self._schedule_autosave()

    @_undo_atom
    def _grid_delete_table(self, info):
        first = self._grid_first_line(info)
        if first is None:
            return
        nrows = info["nrows"]
        self._commit_cell_editor()
        # Captured BEFORE the teardown, as every grid op: deleting a table
        # yanked the page.
        self._grid_saved_view = self._capture_grid_views()
        self._teardown_table_grids()
        self.body_text.delete(f"{first}.0", f"{first + nrows - 1}.end +1c")
        self._resync_list_tags()
        self._render_table_grids()
        self._schedule_autosave()

    def _grid_selection_matrix(self, sel):
        info = sel["info"]
        r0, c0, r1, c1 = sel["box"]
        first = self._grid_first_line(info)
        if first is None:
            return None
        # DATA rows: reading raw text rows shifted every copy one row up
        # in a table with a separator -- the user copied what they saw,
        # and got the line above it.
        rows, _aligns, _sep, _at = self._grid_block_parts(
            first, info["nrows"])
        return [[rows[r][c] if r < len(rows) and c < len(rows[r]) else ""
                 for c in range(c0, c1 + 1)]
                for r in range(r0, r1 + 1)]

    def _grid_copy_selection(self, sel):
        """Cells leave three ways at once: tab-separated text (what a
        spreadsheet reads), an HTML table (what Word and mail clients
        read -- pasted outside the app, the cells used to arrive as one
        line of raw tabs), and an internal note of the copied columns'
        set widths, so pasting the table back into a note rebuilds it
        at the SAME widths instead of shrinking to the default."""
        matrix = self._grid_selection_matrix(sel)
        if matrix is None:
            return
        self._grid_cell_clip = [list(row) for row in matrix]
        tsv = "\n".join("\t".join(row) for row in matrix)
        self._grid_cell_clip_text = tsv
        self._grid_cell_clip_widths = None
        self._grid_cell_clip_styles = {}
        self._grid_cell_clip_aligns = None
        info, (r0, c0, r1, c1) = sel["info"], sel["box"]
        first = self._grid_first_line(info)
        if first is not None:
            _rows, row_aligns, sep_cols, _sep_at = self._grid_block_parts(
                first, info["nrows"])
            if sep_cols is not None:
                self._grid_cell_clip_widths = [
                    dict(sep_cols[c]) if c < len(sep_cols)
                    else {"width": None, "align": None, "hidden": False}
                    for c in range(c0, c1 + 1)]
            # The table's place on the page travels with the cells
            # too, so a duplicated centred table comes back centred.
            self._grid_cell_clip_place = self._grid_table_align_of(first)
            # And each cell's own styles and alignment, so a pasted copy --
            # in the app or in Word -- is the cells as they were drawn.
            self._grid_cell_clip_styles = {
                (r - r0, c - c0): rec for (r, c), rec in
                self._grid_read_cell_styles(first, info["nrows"]).items()
                if r0 <= r <= r1 and c0 <= c <= c1}
            self._grid_cell_clip_aligns = [
                [row_aligns[r][c] if c < len(row_aligns[r])
                 else core_tables.ALIGN_LEFT for c in range(c0, c1 + 1)]
                for r in range(r0, min(r1 + 1, len(row_aligns)))]
        # The HTML follows the export's rules (<th>, colspan, hidden columns);
        # the TSV keeps every value verbatim, for a paste back here.
        m_spans, m_covered = core_tables.merge_map(matrix)
        hidden = {i for i, col in enumerate(self._grid_cell_clip_widths or [])
                  if col.get("hidden")}
        parts = []
        for ri, mrow in enumerate(matrix):
            cells = []
            for ci, v in enumerate(mrow):
                if (ri, ci) in m_covered or ci in hidden:
                    continue
                rs, cs = m_spans.get((ri, ci), (1, 1))
                cs -= len([h for h in hidden if ci < h < ci + cs])
                attr = ((f' colspan="{cs}"' if cs > 1 else "")
                        + (f' rowspan="{rs}"' if rs > 1 else ""))
                # The cell as the file export writes it: its styles inside,
                # its colour on the cell, its alignment; a checkbox leaves
                # as its glyph, centred, in its colour.
                rec = self._grid_cell_clip_styles.get((ri, ci))
                spans = [s for tag, a, z in (rec["runs"] if rec else ())
                         for s in tag_to_spans(tag, a, z)]
                state = core_tables.checkbox_state(v)
                css = ""
                if state is not None:
                    inner = "☑" if state else "☐"
                    tint = next((s["value"] for s in spans
                                 if s["style"] == "text_color"), None)
                    if tint:
                        inner = f'<span style="color:{tint};">{inner}</span>'
                    css += "text-align:center;"
                else:
                    inner = (cell_html(rec["value"], spans) if rec else
                             escape(v).replace(escape(core_tables.LINE_BREAK), "<br>"))
                    aligns = self._grid_cell_clip_aligns or []
                    align = (aligns[ri][ci] if ri < len(aligns)
                             and ci < len(aligns[ri]) else core_tables.ALIGN_LEFT)
                    if align != core_tables.ALIGN_LEFT:
                        css += f"text-align:{align};"
                if rec and rec["paint_bg"]:
                    css += f"background-color:#{rec['paint_bg'][len('highlight_'):]};"
                tag = "th" if r0 + ri == 0 else "td"
                # Without inline borders Word paints nothing: the pasted
                # table was a selectable phantom (round-8 field report).
                css += "border:1px solid #999;padding:4px 10px;"
                cells.append(f'<{tag}{attr} style="{css}">{inner}</{tag}>')
            parts.append("<tr>" + "".join(cells) + "</tr>")
        html_rows = "".join(parts)
        if not clipboard.write(
                tsv, html=('<table style="border-collapse:collapse;">'
                           f"{html_rows}</table>")):
            # Off Windows (the CI runners included) the CF_HTML writer
            # does nothing at all -- the plain text still has to land.
            try:
                self.clipboard_clear()
                self.clipboard_append(tsv)
            except tk.TclError:
                pass

    @_undo_atom
    def _grid_fill_selection(self, sel, value, align=None):
        info = sel["info"]
        r0, c0, r1, c1 = sel["box"]
        # The rewrite keeps every other cell exactly as it was and a
        # filled cell's colour -- a CELL-level highlight describes the
        # cell, not the text (see _grid_lay_cell_styles).
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, _ncols = context
        rows, aligns, sep_cols, _sep_at = self._grid_block_parts(first, nrows)
        for r in range(r0, min(r1 + 1, len(rows))):
            for c in range(c0, min(c1 + 1, len(rows[r]))):
                if rows[r][c] not in (core_tables.MERGE_LEFT,
                                      core_tables.MERGE_UP):
                    rows[r][c] = value
                    if align is not None and c < len(aligns[r]):
                        aligns[r][c] = align
        self._grid_replace_block(first, nrows, rows, aligns, sep_cols)
        self._grid_after_op(first)

    @_undo_atom
    def _grid_toggle_checkbox(self, info, r, c):
        """One click on a checkbox cell flips it. The colour spans on the
        marker characters are re-laid after the write, so a coloured box
        keeps its colour through every toggle."""
        cell = info["cells"].get((r, c))
        if cell is None:
            return False
        state = core_tables.checkbox_state(cell["value"])
        if state is None:
            return False
        line_no = self._grid_line_of_row(info, r)
        if line_no is None:
            return False
        line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
        styles = self._cell_value_styles(line_no, line, c)
        new_value = (core_tables.CHECKBOX_EMPTY if state
                     else core_tables.CHECKBOX_DONE)
        self._write_cell(info, r, c, new_value)
        cell["value"] = new_value
        # Same length either way, so the styles land where they were.
        self._apply_styles_to_cell(info, r, c, new_value,
                                   styles[:len(new_value)])
        self._grid_redraw_cell_text(info, r, c)
        self._schedule_autosave()
        return True

    def _grid_checkmark_popup(self, info, box, x_root, y_root):
        """The checkbox palette: an UNCHECKED box lands in the cell(s),
        already wearing the picked colour -- ready to be ticked with a
        click once its condition is met. Same swatches ordinary text
        offers, plus the theme's own ink for a plain one."""
        self._dismiss_mini_popup()
        popup = tk.Toplevel(self)
        self._mini_popup = popup
        popup.wm_overrideredirect(True)
        popup.configure(bg=self.colors["accent"])
        outer = tk.Frame(popup, bg=self.colors["card"], padx=1, pady=1)
        outer.pack()
        grid_frame = tk.Frame(outer, bg=self.colors["card"])
        grid_frame.pack(padx=10, pady=(8, 0))
        anchor_line = self._grid_first_line(info)

        def choose(color):
            self._dismiss_mini_popup()
            # Surgical writes, as an emoji's, NOT the fill's block rewrite:
            # "the cursor lands outside the table and the scroll jumps".
            fresh = (self._grid_at_line(anchor_line)
                     if anchor_line is not None else None)
            if fresh is None:
                return
            # One palette gesture = one undo unit, however many cells it
            # dresses (a closure cannot wear the @_undo_atom decorator).
            self._undo_atom_begin()
            try:
                r0, c0, r1, c1 = box
                for r in range(r0, r1 + 1):
                    for c in range(c0, c1 + 1):
                        cell = fresh["cells"].get((r, c))
                        if cell is None:
                            continue
                        self._write_cell(fresh, r, c,
                                         core_tables.CHECKBOX_EMPTY)
                        cell["value"] = core_tables.CHECKBOX_EMPTY
                        self._grid_redraw_cell_text(fresh, r, c)
                # No forced centring (the table flickered): the box keeps the
                # cell's alignment, redrawn in place as a toggle is.
                if color:
                    self._grid_apply_style(fresh, box, "text_color", color)
            finally:
                self._undo_atom_end()
            self._schedule_autosave()

        for i, hex_color in enumerate(PRESET_NOTE_COLORS):
            swatch = tk.Button(
                grid_frame, bg=hex_color, activebackground=hex_color,
                width=3, height=1, relief="flat", cursor="hand2",
                command=lambda h=hex_color: choose(h))
            swatch.grid(row=i // 5, column=i % 5, padx=4, pady=4)
            self._button_choice(swatch)
        plain = tk.Button(
            outer, text="Theme color", relief="flat", cursor="hand2",
            bg=self.colors["card"], fg=self.colors["text"],
            command=lambda: choose(None))
        plain.pack(pady=(4, 8))
        self._button_choice(plain)
        self._place_grid_palette(popup, x_root, y_root)

    def _place_grid_palette(self, popup, x_root, y_root):
        """A table's colour palette placed as every popup is: a click outside
        or Escape closes it, the arrows walk it. A <FocusOut> on the window
        closed it at the first Tab, its own buttons' too, leaving the
        keyboard nowhere. Opened from the cell's menu by key, it takes it."""
        self._place_mini_popup(popup, anchor_xy=(x_root, y_root))
        if getattr(self, "_grid_menu_keys", False):
            choices = self._walk_choices(popup, drawn=False)
            if choices:
                choices[0].focus_set()

    def _grid_merge_with(self, info, r, c, toward):
        """The right-click "Merge with cell to the left" (*toward* "left")
        or "above" ("up"): the clicked cell and that neighbour merged the
        way a selection of both is, every text kept. It used to write a
        merge marker over the clicked cell, and its text was gone; a
        neighbour that is itself merged is swallowed whole."""
        cell = info["cells"].get((r, c))
        if cell is None:
            return
        near = (r, c - 1) if toward == "left" else (r - 1, c)
        if near[0] < 0 or near[1] < 0:
            return
        box = self._grid_grown_box(
            info, near, (r + cell["rs"] - 1, c + cell["cs"] - 1))
        self._grid_merge_selection({"info": info, "box": box})

    @_undo_atom
    def _grid_merge_selection(self, sel):
        """The selected rectangle becomes one cell, anchored top-left.

        Merges it touches are dissolved first -- the selection already grew
        to swallow them whole, so nothing is half-merged afterwards.
        """
        info = sel["info"]
        r0, c0, r1, c1 = sel["box"]
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, _ncols = context
        rows, aligns, sep_cols, _sep_at = self._grid_block_parts(first, nrows)
        spans, _covered = core_tables.merge_map(rows)
        for (ar, ac), (rs, cs) in spans.items():
            if ar <= r1 and ar + rs - 1 >= r0 and ac <= c1 and ac + cs - 1 >= c0:
                for rr in range(ar, ar + rs):
                    for cc in range(ac, ac + cs):
                        if (rr, cc) != (ar, ac) and cc < len(rows[rr]):
                            rows[rr][cc] = ""
        # Every swallowed cell's text moves into the merge, in reading order:
        # an empty anchor lost its neighbour's "A".
        pieces, piece_cells = [], []
        for r in range(r0, min(r1 + 1, len(rows))):
            for c in range(c0, min(c1 + 1, len(rows[r]))):
                value = rows[r][c]
                if value and value not in (core_tables.MERGE_LEFT,
                                           core_tables.MERGE_UP):
                    pieces.append(value)
                    piece_cells.append((r, c))
        rows[r0][c0] = " ".join(pieces)
        for r in range(r0, min(r1 + 1, len(rows))):
            for c in range(c0, min(c1 + 1, len(rows[r]))):
                if (r, c) == (r0, c0):
                    continue
                rows[r][c] = (core_tables.MERGE_LEFT if r == r0
                              else (core_tables.MERGE_UP if c == c0
                                    else core_tables.MERGE_LEFT))
        # Nor their styles: the merged cell names the cells it joined, so
        # each piece's bold and colours land on that piece inside it (see
        # _grid_lay_cell_styles). A merged cell used to come out plain.
        merged = ((r0, c0), tuple(piece_cells))
        self._grid_replace_block(
            first, nrows, rows, aligns, sep_cols,
            source=lambda r, c: merged if (r, c) == (r0, c0) else (r, c))
        self._grid_after_op(first)

    @_undo_atom
    def _grid_paste_cells(self, info, r, c):
        """Copied cells land as a block starting at the clicked cell,
        growing the table downward when they need more rows, and
        rightward when they need more columns."""
        matrix = getattr(self, "_grid_cell_clip", None)
        try:
            raw = self.clipboard_get()
        except tk.TclError:
            raw = None
        # Within the ceiling every paste keeps (_cap_paste).
        raw, cut = self._cap_paste(raw) if raw is not None else (None, False)
        # The system clipboard is the truth: the remembered matrix only while
        # it MATCHES it, or a newer copy was shadowed.
        if matrix is not None and raw is not None:
            remembered = "\n".join("\t".join(row) for row in matrix)
            if raw != remembered:
                matrix = None
        own = bool(matrix)          # still our own copy, styles and all
        if not matrix:
            # A browser's cells stack in the plain text ("A\nB" side by side);
            # the shape is read from the HTML, by the whole-table parser.
            html = clipboard.read_html()
            if html and "<table" in html.lower():
                try:
                    html_text, _spans, _paras = html_to_note(html)
                    blocks = core_tables.find_blocks(html_text)
                    if blocks:
                        lines = html_text.split("\n")
                        block = lines[blocks[0][0]:blocks[0][1] + 1]
                        sep_at = core_tables.separator_index(block)
                        matrix = [
                            ["" if value in (core_tables.MERGE_LEFT,
                                             core_tables.MERGE_UP)
                             else value
                             for value in core_tables.split_row(line)]
                            for i, line in enumerate(block) if i != sep_at]
                    # The plain text decides FRESHNESS: the HTML's shape only
                    # when its cells are the plain text's, one copy.
                    if matrix is not None and raw is not None:
                        html_cells = [v.strip() for row in matrix
                                      for v in row if v.strip()]
                        raw_cells = [t.strip() for line in raw.split("\n")
                                     for t in line.split("\t")
                                     if t.strip()]
                        if html_cells != raw_cells:
                            matrix = None
                except Exception:
                    matrix = None
        if not matrix and raw:
            matrix = [line.split("\t") for line in raw.split("\n") if line]
        if not matrix:
            return
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, ncols = context
        old_rows, old_aligns, sep_cols, sep_at = self._grid_block_parts(first, nrows)
        clip_styles = getattr(self, "_grid_cell_clip_styles", None) if own else None
        clip_aligns = (getattr(self, "_grid_cell_clip_aligns", None) or []) if own else []

        def build(block):
            """The table's rows and alignments with *block* laid in, and the
            styles its cells bring."""
            rows = [list(row) for row in old_rows]
            aligns = [list(row) for row in old_aligns]
            # Columns grow as rows do: four into a two-column table lost two
            # without a word.
            width = max([ncols] + [c + len(line) for line in block])
            for row in rows:
                row.extend([""] * (width - len(row)))
            # The alignments grow with them, or a copied cell landing in a
            # new column has nowhere to keep its own.
            for row_aligns in aligns:
                row_aligns.extend(
                    [core_tables.ALIGN_LEFT] * (width - len(row_aligns)))
            while r + len(block) > len(rows):
                rows.append([""] * width)
                aligns.append([core_tables.ALIGN_LEFT] * width)
            extra = {}
            for dr, source_row in enumerate(block):
                for dc, value in enumerate(source_row):
                    if c + dc < len(rows[r + dr]):
                        rows[r + dr][c + dc] = value.replace(
                            core_tables.CELL, "/").strip()
                        if c + dc < len(aligns[r + dr]):
                            aligns[r + dr][c + dc] = (
                                clip_aligns[dr][dc] if dr < len(clip_aligns)
                                and dc < len(clip_aligns[dr])
                                else core_tables.ALIGN_LEFT)
                        if clip_styles and (dr, dc) in clip_styles:
                            extra[(r + dr, c + dc)] = clip_styles[(dr, dc)]
            return rows, aligns, extra

        # Grown no more than every paste's ceiling (30,000 cells gave every
        # row 30,000 more): what fits found first -- rows, cells, characters --
        # and the cut said.
        before = len(self.body_text.get(f"{first}.0",
                                        f"{first + nrows - 1}.end"))

        def growth(block):
            # As written by the rewrite and then tidied (_grid_after_op).
            rows, aligns, _extra = build(block)
            lines = core_tables.format_table(rows, aligns)
            if sep_cols is not None and lines:
                lines.insert(1, self._grid_separator_line(
                    [dict(col) for col in sep_cols], rows))
            return core_tables.tidied_length(lines) - before

        if growth(matrix) > MAX_PASTE_CHARS:
            cut = True
            kept = core_tables.longest_fitting(
                len(matrix), lambda k: growth(matrix[:k]), MAX_PASTE_CHARS)
            if kept:
                matrix = matrix[:kept]
            else:
                row0 = matrix[0]
                kept = core_tables.longest_fitting(
                    len(row0), lambda k: growth([row0[:k]]), MAX_PASTE_CHARS)
                if kept:
                    matrix = [row0[:kept]]
                else:
                    cell0 = row0[0]
                    kept = core_tables.longest_fitting(
                        len(cell0), lambda k: growth([[cell0[:k]]]),
                        MAX_PASTE_CHARS)
                    matrix = [[cell0[:kept]]]
        rows, aligns, extra = build(matrix)
        # The block may have grown; rewrite against its original height and
        # let format_table emit the extra rows, the separator restored
        # after the header. Our own copy brings its cells' styles along.
        self._grid_replace_block(first, nrows, rows, aligns, sep_cols,
                                 extra=extra)
        self._grid_after_op(first)
        if cut:
            self._say_if_paste_was_cut({"text_cut": True}, in_body=True)

    def _grid_copy_cell(self, info, r, c):
        cell = info["cells"].get((r, c))
        if cell is None:
            return
        # Remembered as a multi-cell copy is, or an OLDER copy's matrix and
        # styles were pasted instead.
        self._grid_cell_clip = [[cell["value"]]]
        self._grid_cell_clip_styles = {}
        self._grid_cell_clip_aligns = None
        try:
            self.clipboard_clear()
            self.clipboard_append(cell["value"])
        except tk.TclError:
            pass

    def _grow_cell_editor(self, win, canvas):
        """The editor widens over its neighbours as its content grows.

        A spreadsheet does exactly this: the cell itself resizes on commit,
        but while typing, the overlay simply spreads -- hiding the overflow
        until click-away read as the emoji not arriving at all.
        """
        self._schedule_autosave()
        editor = getattr(self, "_cell_editor", None)
        if editor is None:
            return
        header_font, cell_font = self._grid_fonts()
        font = header_font if editor["r"] == 0 else cell_font
        try:
            content = editor["entry"].get("1.0", "end-1c")
            # Typing an emoji gets its face live, per character -- the
            # whole-box font switch went with the Entry.
            self._editor_retag_emoji(editor["entry"])
            emoji_font = self._measuring_font(
                ("Segoe UI Emoji", self.editor_font_size))
            needed = 24 + max(
                (max(font.measure(seg), emoji_font.measure(seg))
                 if any(self._char_is_emoji(ch) for ch in seg)
                 else font.measure(seg)
                 for seg in content.split("\n")), default=0)
            # No wider than a drawn table may be tall: one pasted line of
            # 5,000 letters asked X for a window past its 32,767 pixels.
            needed = min(needed, self.MAX_DRAWN_TABLE_PX)
            if needed > int(float(canvas.itemcget(win, "width"))):
                canvas.itemconfigure(win, width=needed)
            self._editor_fit_window()
        except tk.TclError:
            pass

    def _editor_paste(self, info):
        """Ctrl+V in a cell: a copied block of cells spreads from here.

        Only when the clipboard actually holds a block -- several cells, or
        the remembered matrix -- so pasting a plain word into a cell still
        behaves like typing it: Tk's own paste, within the ceiling every
        paste keeps (_cap_paste).
        """
        editor = getattr(self, "_cell_editor", None)
        if editor is None:
            return None
        try:
            raw = self.clipboard_get()
        except tk.TclError:
            raw = None
        remembered = getattr(self, "_grid_cell_clip", None)
        block = ("\t" in (raw or "") or "\n" in (raw or "").strip()
                 or (remembered is not None and raw is not None
                     and raw == "\n".join("\t".join(r) for r in remembered)))
        if not block:
            kept, cut = self._cap_paste(raw or "")
            if not cut:
                return None
            entry = editor["entry"]
            try:
                entry.delete("sel.first", "sel.last")
            except tk.TclError:
                pass
            entry.insert("insert", kept)
            self._say_if_paste_was_cut({"text_cut": True}, in_body=True)
            return "break"
        r, c = editor["r"], editor["c"]
        anchor_line = self._grid_first_line(info)
        self._commit_cell_editor()
        fresh = (self._grid_at_line(anchor_line)
                 if anchor_line is not None else None)
        if fresh is not None:
            self._grid_paste_cells(fresh, r, c)
        # The keyboard back in the cell the paste began at (or the table's
        # text, past what is drawn), or the next typing went nowhere.
        self._grid_keyboard_back(anchor_line, r, c)
        return "break"

    def _grid_menu_from_keys(self, info):
        """Shift+F10 or the menu key in a cell: its menu at the cell, as a
        right-click opens it at the pointer; and once the menu, or a palette
        it opened, has gone, the keyboard back in the table."""
        editor = getattr(self, "_cell_editor", None)
        if editor is None:
            return "break"
        r, c, canvas = editor["r"], editor["c"], info["canvas"]
        cell = info["cells"].get((r, c))
        try:
            x = canvas.winfo_rootx() + int(cell["x"] - canvas.canvasx(0)) + 8
            y = canvas.winfo_rooty() + int(cell["y"] - canvas.canvasy(0)
                                           + cell["h"] // 2)
        except (tk.TclError, TypeError, KeyError):
            return "break"
        anchor_line = self._grid_first_line(info)
        self._editor_context_menu(info, SimpleNamespace(
            widget=editor["entry"], x=8, y=cell["h"] // 2, x_root=x, y_root=y,
            keys=True))
        self.after(100, lambda: self._grid_keyboard_back(anchor_line, r, c))
        return "break"

    def _grid_keyboard_back(self, anchor_line, r, c, tries=0):
        """Into the cell the menu was opened from -- or the nearest one left,
        after a row or column went -- once nothing asks or floats over the
        table any more, and only if the keyboard is on nothing."""
        menu = getattr(self, "_context_menu", None)
        try:
            posted = menu is not None and bool(menu.winfo_ismapped())
        except tk.TclError:
            posted = False
        if (posted or self._a_dialog_is_asking()
                or getattr(self, "_mini_popup", None) is not None):
            if tries < 3000:            # five minutes of a menu left open
                self.after(100, lambda: self._grid_keyboard_back(
                    anchor_line, r, c, tries + 1))
            return
        self._grid_menu_keys = False
        if not self._keyboard_nowhere():
            return
        info = (self._grid_at_line(anchor_line)
                if anchor_line is not None else None)
        if info is None:
            self._keyboard_to_kept_table(anchor_line, r, c)
            return
        r = max(0, min(r, info["data_rows"] - 1))
        c = max(0, min(c, info["ncols"] - 1))
        while (r, c) not in info["cells"] and c > 0:
            c -= 1                       # covered by a merge: its anchor
        while (r, c) not in info["cells"] and r > 0:
            r -= 1
        if (r, c) in info["cells"]:
            self._open_cell_editor(info, r, c, select=False)
        else:
            self._keyboard_to(self.body_text)

    def _keyboard_to_kept_table(self, first, r, c, typed=None):
        """The keyboard into the text of the table on line *first*, at the
        end of row *r*'s cell *c* (past a row's last, the next row's first):
        a commit past what is drawn leaves it as text, and the next keys
        went nowhere. *typed*: the text before the editor's caret, when
        Enter broke a cell -- the caret goes after that break."""
        if not self._keyboard_nowhere():
            return
        b = self.body_text
        span = self._table_block_at(first) if first is not None else None
        block = ([b.get(f"{n}.0", f"{n}.end")
                  for n in range(span[0], span[1] + 1)] if span else [])
        sep_at = core_tables.separator_index(block) if block else None
        rows = [i for i in range(len(block)) if i != sep_at]
        if rows:
            def row_line(n):
                return rows[min(max(n, 0), len(rows) - 1)]
            if c >= len(core_tables.cell_bounds(block[row_line(r)])):
                r, c = r + 1, 0
            i = row_line(r)
            bounds = core_tables.cell_bounds(block[i])
            start, end = bounds[min(max(c, 0), len(bounds) - 1)] if bounds else (0, 0)
            if typed is not None:
                # As the commit stores it: ends of spaces trimmed, each line
                # break written <br>, a pipe written "/".
                stored = typed.lstrip(" \t").replace(core_tables.CELL, "/")
                end = min(end, start + len(stored.replace(
                    "\n", core_tables.LINE_BREAK)))
            b.mark_set("insert", f"{span[0] + i}.{self._tk_col(block[i], end)}")
            b.see("insert")
        self._keyboard_to(b)

    def _editor_context_menu(self, info, event):
        editor = getattr(self, "_cell_editor", None)
        if editor is None:
            return "break"
        r, c = editor["r"], editor["c"]
        anchor_line = self._grid_first_line(info)
        self._commit_cell_editor()
        fresh = (self._grid_at_line(anchor_line)
                 if anchor_line is not None else None)
        if fresh is not None:
            self._grid_menu(fresh, event, at=(r, c))
        return "break"

    @_undo_atom
    def _grid_set_alignment(self, info, box, align):
        """Alignment is the cell's padding, so setting it edits ONLY the
        padding -- through the same space-level ops the block aligner
        uses, because Tk carries a tag along with the text around it. The
        old wholesale-rewrite path silently dropped the bold (and every
        other character style) from the very cells being aligned."""
        r0, c0, r1, c1 = box
        context = self._grid_op_context(info)
        if not context:
            return
        first, nrows, _ncols = context
        b = self.body_text
        lines = [b.get(f"{n}.0", f"{n}.end")
                 for n in range(first, first + nrows)]
        aligns = [core_tables.cell_alignments(line) for line in lines]
        rows = [core_tables.split_row(line) for line in lines]
        # The grid numbers its rows with the separator skipped; the block
        # lines include it.
        sep_at = core_tables.separator_index(lines)
        for r in range(r0, r1 + 1):
            off = r if sep_at is None or r < sep_at else r + 1
            if off >= len(lines):
                continue
            for c in range(c0, c1 + 1):
                if (c < len(rows[off])
                        and rows[off][c] not in (core_tables.MERGE_LEFT,
                                                 core_tables.MERGE_UP)
                        and c < len(aligns[off])):
                    aligns[off][c] = align
        per_row = core_tables.row_widths(
            rows, core_tables.layout_widths(rows, aligns), aligns)
        for offset, line in enumerate(lines):
            row = first + offset
            base = self._col_base(row)
            for at, delta in core_tables.pad_ops(
                    line, per_row[offset],
                    aligns[offset] if offset < len(aligns) else None):
                t_at = base + self._tk_col(line, at)
                if delta > 0:
                    b.insert(f"{row}.{t_at}", " " * delta)
                else:
                    b.delete(f"{row}.{t_at}", f"{row}.{t_at + (-delta)}")
        self._grid_after_op(first)

    def _highlight_swatch_column(self, popup, choose):
        """The one way a highlight palette looks anywhere in the app:
        full-width swatches parted by true one-pixel hairlines in the
        theme's rule colour, with Clear underneath. The table popup's
        pattern, shared so the toolbar and the context menu cannot
        drift away from it again."""
        outer = tk.Frame(popup, bg=self.colors["card"], padx=1, pady=1)
        outer.pack()
        # The header the text-colour popup carries, here in the shared function
        # (at a call site, the highlight palette drew none) for both routes.
        header = tk.Label(outer, text="Pick a highlight color",
                          font=("Segoe UI", 10, "bold"),
                          bg=self.colors["card"], fg=self.colors["text"])
        header.pack(padx=15, pady=(12, 8))
        # The hairline between swatches is the column's background: the accent
        # softened toward the card, in every theme.
        column = tk.Frame(outer, bg=self._blend_hex(
            self.colors["accent"], self.colors["card"], 0.35))
        column.pack(padx=8, pady=8)
        for i, hex_color in enumerate(HIGHLIGHT_COLOR_PALETTE):
            swatch = tk.Button(
                column, bg=hex_color, activebackground=hex_color,
                width=14, height=1, relief="flat", bd=0, cursor="hand2",
                command=lambda h=hex_color: choose(h))
            swatch.pack(pady=(0 if i == 0 else 1, 0))
            self._button_choice(swatch)
        clear = tk.Button(
            outer, text="Clear highlight", relief="flat", cursor="hand2",
            bg=self.colors["card"], fg=self.colors["text"],
            command=lambda: choose(None))
        clear.pack(pady=(0, 8))
        self._button_choice(clear)
        return outer

    def _grid_highlight_popup(self, info, box, x_root, y_root):
        """The highlight palette as the app's own themed popup -- a
        tk.Menu cannot draw the hairlines, its separators are the OS's."""
        self._dismiss_mini_popup()
        popup = tk.Toplevel(self)
        self._mini_popup = popup
        popup.wm_overrideredirect(True)
        popup.configure(bg=self.colors["accent"])

        def choose(color):
            self._dismiss_mini_popup()
            self._grid_apply_style(info, box, "highlight", color)

        self._highlight_swatch_column(popup, choose)
        self._place_grid_palette(popup, x_root, y_root)

    def _grid_align_context(self):
        """The alignment of the cell the user is in -- the open editor's,
        or the selection's anchor -- or None outside any table."""
        editor = getattr(self, "_cell_editor", None)
        sel = getattr(self, "_grid_sel", None)
        if editor is not None:
            info, r, c = editor["info"], editor["r"], editor["c"]
        elif sel is not None:
            info, r, c = sel["info"], sel["box"][0], sel["box"][1]
        else:
            return None
        line_no = self._grid_line_of_row(info, r)
        if line_no is None:
            return None
        aligns = core_tables.cell_alignments(
            self.body_text.get(f"{line_no}.0", f"{line_no}.end"))
        return aligns[c] if c < len(aligns) else core_tables.ALIGN_LEFT

    def _grid_cell_text_range(self, info, r, c, pad_ok=False, full=False):
        """The body-text indices of one cell's content, or None when empty --
        padding carries no formatting, except a highlight (*pad_ok*) on an
        empty cell's. *full* takes the whole pipe-to-pipe region, where a
        cell-level highlight lives so whatever goes in later inherits it: on
        the text alone, 'drag the column and the colour is gone'."""
        line_no = self._grid_line_of_row(info, r)
        first = self._grid_first_line(info)
        if line_no is None or first is None:
            return None
        base = 1 if line_no == first else 0
        line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
        bounds = core_tables.cell_bounds(line)
        if c >= len(bounds):
            return None
        start, end = bounds[c]
        if full or start >= end:
            if not (pad_ok or full):
                return None
            pipes = core_tables.pipe_positions(line)
            if c + 1 >= len(pipes) or pipes[c] + 1 >= pipes[c + 1]:
                return None
            start, end = pipes[c] + 1, pipes[c + 1]
        return (f"{line_no}.{base + self._tk_col(line, start)}",
                f"{line_no}.{base + self._tk_col(line, end)}")

    def _grid_style_target(self):
        """Where toolbar formatting should land instead of the body: the
        selected cells, or the one open in the editor. None means the
        toolbar keeps its ordinary meaning."""
        sel = getattr(self, "_grid_sel", None)
        if (sel is not None
                and self._grid_first_line(sel["info"]) is not None):
            return sel["info"], sel["box"]
        editor = getattr(self, "_cell_editor", None)
        if editor is not None:
            return editor["info"], (editor["r"], editor["c"],
                                    editor["r"], editor["c"])
        return None

    @_undo_atom(tags_only=True)
    def _grid_apply_style(self, info, box, kind, value=None, through_editor=True):
        """One toolbar action over every selected cell's text, decided once
        (a mixed selection turns it ON, as the body's does), the grid
        repainted in place. `through_editor=False` styles the body under an
        open editor, as its commit lays a cell's highlight.
        """
        r0, c0, r1, c1 = box
        editor = getattr(self, "_cell_editor", None)
        if (through_editor and editor is not None and editor.get("info") is info
                and (r0, c0, r1, c1) == (editor["r"], editor["c"],
                                         editor["r"], editor["c"])):
            # The cell is OPEN: style the selection inside the editor --
            # a single letter or emoji, not the whole cell -- and let the
            # commit carry it to the body.
            self._editor_apply_style(kind, value)
            return
        ranges = []
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                span = self._grid_cell_text_range(
                    info, r, c, pad_ok=(kind == "highlight"),
                    full=(kind == "highlight"))
                if span:
                    ranges.append(span)
        if not ranges:
            return
        b = self.body_text
        if kind in ("bold", "italic"):
            # On unless every cell has it; each keeps its own other style.
            on = not all(self._selection_has_style(
                b, {kind, "bold_italic"}, s, e) for s, e in ranges)
            self._set_weight_by_stretch(ranges, kind, on)
        elif kind in ("underline", "strike"):
            on = all(self._selection_has_style(b, {kind}, s, e)
                     for s, e in ranges)
            for s, e in ranges:
                if on:
                    b.tag_remove(kind, s, e)
                else:
                    b.tag_add(kind, s, e)
        else:
            for s, e in ranges:
                for tag_name in b.tag_names():
                    if tag_name.startswith(kind + "_"):
                        b.tag_remove(tag_name, s, e)
                if value:
                    tag = self._ensure_color_tag(b, kind, value)
                    b.tag_add(tag, s, e)
        self._grid_restyle(info)
        self._schedule_autosave()

    def _grid_cell_paint(self, info, r, c):
        """What the cell's text tags ask the drawing to look like."""
        paint = {"bg": None, "fg": None, "bold": False, "italic": False,
                 "underline": False, "strike": False}
        # pad_ok so an empty cell's padding-borne highlight still paints.
        span = self._grid_cell_text_range(info, r, c, pad_ok=True)
        if not span:
            return paint
        tags = set(self.body_text.tag_names(span[0]))
        for t in tags:
            if t.startswith("highlight_"):
                paint["bg"] = "#" + t[len("highlight_"):]
            elif t.startswith("text_color_"):
                paint["fg"] = "#" + t[len("text_color_"):]
        paint["bold"] = bool(tags & {"bold", "bold_italic"})
        paint["italic"] = bool(tags & {"italic", "bold_italic"})
        paint["underline"] = "underline" in tags
        paint["strike"] = "strike" in tags
        return paint

    @staticmethod
    def _blend_hex(top, base, opacity):
        """Fake transparency on a canvas that has none: *top* at *opacity*
        over *base*, channel by channel."""
        try:
            tr, tg, tb = (int(top.lstrip("#")[i:i + 2], 16)
                          for i in (0, 2, 4))
            br, bg_, bb = (int(base.lstrip("#")[i:i + 2], 16)
                           for i in (0, 2, 4))
        except (ValueError, AttributeError):
            return top
        return "#%02x%02x%02x" % tuple(
            round(t * opacity + b * (1 - opacity))
            for t, b in ((tr, br), (tg, bg_), (tb, bb)))

    def _grid_restyle(self, info):
        """Repaint every drawn cell from its text tags, in place.

        The text is redrawn as runs, so a single coloured letter shows as
        itself; the highlight stays a whole-cell wash -- a background is
        the one style the drawing paints cell-wide."""
        for (r, c) in info["cells"]:
            self._grid_redraw_cell_text(info, r, c)

    def _recolor_table_grids(self):
        """Repaint every drawn table in the current palette, in place -- a
        rebuild's new windows map late, and a theme switch flickered. Their
        colours are canvas items. False, nothing painted, when a grid is
        gone or stale: only a rebuild will do."""
        grids = list(getattr(self, "_table_grids", []))
        if any(info.get("stale") or self._grid_first_line(info) is None
               for info in grids):
            return False
        rule = hairline(self.colors)
        for info in grids:
            canvas = info["canvas"]
            try:
                info["frame"].configure(bg=self.colors["card"])
                canvas.configure(bg=self.colors["card"])
                for rect, r in info.get("slivers", ()):
                    canvas.itemconfigure(rect, outline=rule, fill=(
                        inset_surface(self.colors) if r == 0
                        else self.colors["card"]))
                for cell in info["cells"].values():
                    canvas.itemconfigure(cell["rect"], outline=rule, width=1)
            except tk.TclError:
                return False
            self._grid_restyle(info)
        sel = getattr(self, "_grid_sel", None)
        if sel and any(sel["info"] is info for info in grids):
            for key in sel["cells"]:
                cell = sel["info"]["cells"].get(key)
                if cell is not None:
                    sel["info"]["canvas"].itemconfigure(
                        cell["rect"], outline=self.colors["accent"], width=2)
        return True

    def _grid_stub_menu(self, info, event, c):
        """The only menu a hidden column can offer: bring it back."""
        menu = self._new_context_menu(tearoff=0, bg=self.colors["card"],
                       fg=self.colors["text"],
                       activebackground=self.colors["accent"],
                       activeforeground=self._on_fill("accent"))
        menu.add_command(label="Unhide column",
                         command=lambda: self._grid_hide_col(info, c, False))
        menu.add_command(label="Unhide all columns",
                         command=lambda: self._grid_unhide_all(info))
        try:
            self._while_native(lambda: menu.tk_popup(event.x_root, event.y_root))
        finally:
            menu.grab_release()
        return "break"

    def _grid_menu(self, info, event, at=None):
        # Opened from the keyboard, its palettes take the keyboard too.
        self._grid_menu_keys = bool(getattr(event, "keys", False))
        canvas = info["canvas"]
        hit = at if at is not None else self._grid_cell_at_xy(
            info, canvas.canvasx(event.x), canvas.canvasy(event.y))
        if hit is None or hit not in info["cells"]:
            # A hidden column's sliver has no cells; without a menu of its
            # own, hiding every column would lock Unhide away for good.
            x = canvas.canvasx(event.x)
            for c in info.get("hidden_cols", ()):
                if info["col_x"][c] <= x < info["col_x"][c + 1]:
                    return self._grid_stub_menu(info, event, c)
            return "break"
        r, c = hit
        cell = info["cells"][(r, c)]
        menu = self._new_context_menu(tearoff=0, bg=self.colors["card"],
                       fg=self.colors["text"],
                       activebackground=self.colors["accent"],
                       activeforeground=self._on_fill("accent"))
        sel = getattr(self, "_grid_sel", None)
        if (sel and sel["info"] is info
                and sel["box"][0] <= r <= sel["box"][2]
                and sel["box"][1] <= c <= sel["box"][3]):
            menu.add_command(label="Copy cells",
                             command=lambda: self._grid_copy_selection(sel))
            menu.add_command(label="Paste cells here",
                             command=lambda: self._grid_paste_cells(
                                 info, sel["box"][0], sel["box"][1]))
            menu.add_command(label="Insert checkboxes\u2026",
                             command=lambda xr=event.x_root,
                             yr=event.y_root: self._grid_checkmark_popup(
                                 info, sel["box"], xr, yr))
            menu.add_command(label="Clear cells",
                             command=lambda: self._grid_fill_selection(
                                 sel, ""))
            menu.add_command(label="Merge cells",
                             command=lambda: self._grid_merge_selection(sel))
            menu.add_command(
                label=("Autofit column width"
                       if sel["box"][1] == sel["box"][3]
                       else "Autofit column widths"),
                command=lambda: self._grid_autofit_cols(
                    info, sel["box"][1], sel["box"][3]))
            # Hide asks for a whole column selected top to bottom -- the
            # user can SEE what is about to disappear. Anything less and
            # the option stays away, on purpose.
            if (sel["box"][0] == 0
                    and sel["box"][2] >= info["data_rows"] - 1):
                menu.add_command(
                    label=("Hide column" if sel["box"][1] == sel["box"][3]
                           else "Hide columns"),
                    command=lambda: self._grid_hide_span(
                        info, sel["box"][1], sel["box"][3]))
                span_cols = sel["box"][3] - sel["box"][1] + 1
                menu.add_command(
                    label=("Copy column to the end" if span_cols == 1
                           else f"Copy {span_cols} columns to the end"),
                    command=lambda box=sel["box"]:
                        self._grid_append_cols(info, box[1], box[3]))
            # The vertical twin: whole ROWS selected edge to edge can be
            # duplicated downward.
            if (sel["box"][1] == 0
                    and sel["box"][3] >= info["ncols"] - 1):
                span_rows = sel["box"][2] - sel["box"][0] + 1
                menu.add_command(
                    label=("Copy row to the end" if span_rows == 1
                           else f"Copy {span_rows} rows to the end"),
                    command=lambda box=sel["box"]:
                        self._grid_append_rows(info, box[0], box[2]))
            menu.add_separator()
            menu.add_command(
                label="Highlight cells\u2026",
                command=lambda box=sel["box"], xr=event.x_root,
                               yr=event.y_root:
                    self._grid_highlight_popup(info, box, xr, yr))
            menu.add_separator()
            for label, align_value in (
                    ("Align left", core_tables.ALIGN_LEFT),
                    ("Center text", core_tables.ALIGN_CENTER),
                    ("Align right", core_tables.ALIGN_RIGHT)):
                menu.add_command(
                    label=label,
                    command=lambda a=align_value, box=sel["box"]:
                        self._grid_set_alignment(info, box, a))
            try:
                self._while_native(lambda: menu.tk_popup(event.x_root, event.y_root))
            finally:
                menu.grab_release()
            return "break"

        def emoji_here():
            self._open_cell_editor(info, r, c, select=False)
            editor = getattr(self, "_cell_editor", None)
            if editor:
                self._show_emoji_picker(editor["entry"])

        menu.add_command(label="Copy cell",
                         command=lambda: self._grid_copy_cell(info, r, c))
        menu.add_command(label="Paste cells here",
                         command=lambda: self._grid_paste_cells(info, r, c))
        menu.add_command(label="Insert checkbox\u2026",
                         command=lambda xr=event.x_root,
                         yr=event.y_root: self._grid_checkmark_popup(
                             info, (r, c, r, c), xr, yr))
        if core_tables.checkbox_state(
                info["cells"].get((r, c), {}).get("value")) is not None:
            # A click on a checkbox toggles it, so the way into its text
            # lives here: it opens empty, and what is typed takes the box's
            # place (left empty, the box stays).
            menu.add_command(label="Edit cell as text",
                             command=lambda: self._open_cell_editor(
                                 info, r, c))
        menu.add_command(label="Insert emoji…", command=emoji_here)
        menu.add_command(label="Clear cell",
                         command=lambda: self._grid_fill_selection(
                             {"info": info, "box": (r, c, r, c)}, ""))
        menu.add_command(
            label="Highlight cell\u2026",
            command=lambda xr=event.x_root, yr=event.y_root:
                self._grid_highlight_popup(info, (r, c, r, c), xr, yr))
        menu.add_separator()
        # Grouped ("finding the one you need takes minutes", field report): the
        # everyday cell actions on top, the rest a hover away under its word.

        def _sub():
            m = tk.Menu(menu, tearoff=0, bg=self.colors["card"],
                        fg=self.colors["text"],
                        activebackground=self.colors["accent"],
                        activeforeground=self._on_fill("accent"),
                        relief="flat", bd=0, font=("Segoe UI", 9))
            return m

        align_menu = _sub()
        for label, align_value in (
                ("Align left", core_tables.ALIGN_LEFT),
                ("Center text", core_tables.ALIGN_CENTER),
                ("Align right", core_tables.ALIGN_RIGHT)):
            align_menu.add_command(
                label=label,
                command=lambda a=align_value: self._grid_set_alignment(
                    info, (r, c, r, c), a))
        menu.add_cascade(label="Align cell", menu=align_menu)

        rows_menu = _sub()
        rows_menu.add_command(label="Insert row above",
                              command=lambda: self._grid_insert_row(info, r))
        rows_menu.add_command(
            label="Insert row below",
            command=lambda: self._grid_insert_row(info, r + 1))
        rows_menu.add_command(
            label="Delete row",
            state=("normal" if info["data_rows"] > 1 else "disabled"),
            command=lambda: self._grid_delete_row(info, r))
        menu.add_cascade(label="Rows", menu=rows_menu)

        cols_menu = _sub()
        cols_menu.add_command(label="Insert column left",
                              command=lambda: self._grid_insert_col(info, c))
        cols_menu.add_command(
            label="Insert column right",
            command=lambda: self._grid_insert_col(info, c + 1))
        cols_menu.add_command(label="Autofit column width",
                              command=lambda: self._grid_autofit_col(info, c))
        cols_menu.add_command(
            label="Unhide all columns",
            state=("normal" if info.get("hidden_cols") else "disabled"),
            command=lambda: self._grid_unhide_all(info))
        cols_menu.add_command(label="Delete column",
                              command=lambda: self._grid_delete_col(info, c))
        menu.add_cascade(label="Columns", menu=cols_menu)

        merged = cell["rs"] > 1 or cell["cs"] > 1
        merge_menu = _sub()
        merge_menu.add_command(label="Merge with cell to the left",
                               state="normal" if c > 0 else "disabled",
                               command=lambda: self._grid_merge_with(
                                   info, r, c, "left"))
        merge_menu.add_command(label="Merge with cell above",
                               state="normal" if r > 0 else "disabled",
                               command=lambda: self._grid_merge_with(
                                   info, r, c, "up"))
        merge_menu.add_command(label="Split merged cell",
                               state="normal" if merged else "disabled",
                               command=lambda: self._grid_split(info, r, c))
        menu.add_cascade(label="Merge", menu=merge_menu)

        table_menu = _sub()
        for pos_label, pos in (("Table left on page", "left"),
                               ("Center table on page", "center"),
                               ("Table right on page", "right")):
            table_menu.add_command(
                label=pos_label,
                command=lambda p=pos: self._grid_set_table_align(info, p))
        table_menu.add_separator()
        table_menu.add_command(
            label="Add caption below…",
            command=lambda: self._grid_add_caption(info))
        table_menu.add_command(
            label="Add a line above the table",
            command=lambda: self._grid_add_line_above(info))
        table_menu.add_separator()
        table_menu.add_command(
            label="Delete table",
            command=lambda: self._grid_delete_table(info))
        menu.add_cascade(label="Table", menu=table_menu)
        try:
            self._while_native(lambda: menu.tk_popup(event.x_root, event.y_root))
        finally:
            menu.grab_release()
        return "break"


    def _configure_table_tag(self, text_widget):
        """Draw table rows in a monospace face, at the editor's own size --
        derived from the pipes, as the list margins are, never in
        ``formatting``, so a table exported or shared carries no font.
        """
        available = set(tkfont.families())
        family = next((f for f in MONOSPACE_FAMILIES if f in available),
                      self.editor_font_family)
        # A table's rows sit closer together than prose wants to, because
        # each one is a single line. The extra space above and below is what
        # turns a run of bordered lines into cells with something in them.
        text_widget.tag_configure(self.TABLE_TAG,
                                  font=(family, self.editor_font_size),
                                  spacing1=4, spacing3=4)

    def _configure_paragraph_tag(self, text_widget, name):
        """Set one margin tag's options.

        Split out from _paragraph_tag so the tags can be rebuilt when the
        editor's font size changes: the margins are in pixels and the marker
        they leave room for is not.
        """
        kind, indent = self._paragraph_tags[name]
        left = indent * self.INDENT_STEP
        options = {}
        if kind:
            options["lmargin1"] = self.px(18) + left
            options["lmargin2"] = self.px(18) + left + self._marker_room(kind)
        else:
            options["lmargin1"] = options["lmargin2"] = left
        text_widget.tag_configure(name, **options)

    def _clear_paragraph_tags(self, text_widget, line_no):
        """Strip every margin tag from a line, whatever kind or depth."""
        for name in text_widget.tag_names(f"{line_no}.0"):
            if name.startswith("para_"):
                text_widget.tag_remove(name, f"{line_no}.0", f"{line_no}.end+1c")

    def _paragraph_indent_of(self, text_widget, line_no, line=None):
        """How deep this line is pushed.

        Read from the margin tag, with one fallback: a bullet's glyph also
        says which level it is at, so a bullet whose tag was lost -- pasted
        in from elsewhere, say -- still comes back at the right depth.
        *line* is the line's text when its caller has read it already.
        """
        for name in text_widget.tag_names(f"{line_no}.0"):
            if name.startswith("para_"):
                # Looked up rather than parsed out of the name, which is
                # a format this does not need to know.
                return self._paragraph_tags.get(name, (None, 0))[1]
        if line is None:
            line = text_widget.get(f"{line_no}.0", f"{line_no}.end")
        return self._bullet_depth(line)

    @staticmethod
    def _bullet_depth(line):
        """The level a bullet's glyph says *line* is at, or 0."""
        kind, marker, _ = parse_list_marker(line)
        return bullet_level_of(marker) if kind == "bullet" else 0

    def _paragraph_align_of(self, text_widget, line_no):
        """The alignment of this line: "left", "center" or "right".

        Read from the tag rather than the text, because unlike a list marker
        alignment leaves nothing behind in the body to read back.
        """
        tags = text_widget.tag_names(f"{line_no}.0")
        for align in ("center", "right"):
            if f"align_{align}" in tags:
                return align
        return "left"

    @_undo_atom(tags_only=True)
    def _set_paragraph_align(self, align):
        """Align the selected lines left, centre or right.

        Clicking the alignment a line already has puts it back to left, the
        same way clicking a list button again turns the list off -- a button
        that is already pressed should undo itself rather than do nothing.
        """
        # With cells selected, the toolbar buttons mean those cells: the
        # paragraph path would apply an alignment the table lines shed at
        # once, which read as "it snaps back to the left".
        sel = getattr(self, "_grid_sel", None)
        if (sel is not None
                and self._grid_first_line(sel["info"]) is not None):
            info, box = sel["info"], sel["box"]
            whole = (box[0] == 0 and box[1] == 0
                     and box[2] >= info["data_rows"] - 1
                     and box[3] >= info["ncols"] - 1)
            self._grid_set_alignment(info, box, {
                "center": core_tables.ALIGN_CENTER,
                "right": core_tables.ALIGN_RIGHT,
            }.get(align, core_tables.ALIGN_LEFT))
            if whole:
                # Every cell selected reads as "the table", but this is the
                # cells' text. Said in a dialog that waits to be read, once
                # this step is done (a banner went before it was read).
                self.after_idle(self._explain_cells_not_table)
            return
        # With a table cell open, the toolbar buttons mean that cell --
        # reaching for the same button that aligns a paragraph is exactly
        # what someone centring a cell will try first.
        editor = getattr(self, "_cell_editor", None)
        if editor is not None:
            info, r, c = editor["info"], editor["r"], editor["c"]
            anchor_line = self._grid_first_line(info)
            self._grid_set_alignment(info, (r, c, r, c), {
                "center": core_tables.ALIGN_CENTER,
                "right": core_tables.ALIGN_RIGHT,
            }.get(align, core_tables.ALIGN_LEFT))
            fresh = (self._grid_at_line(anchor_line)
                     if anchor_line is not None else None)
            if fresh is not None and (r, c) in fresh["cells"]:
                self._open_cell_editor(fresh, r, c, select=False)
            return
        first, last = self._selected_line_range()
        if all(self._paragraph_align_of(self.body_text, n) == align
               for n in range(first, last + 1)):
            align = "left"
        self._align_lines(range(first, last + 1), align)
        # A caption carries its table along, and the table its caption
        # (field pass: centring the label left the table where it was).
        lines = set(range(first, last + 1))
        for info in list(getattr(self, "_table_grids", [])):
            if lines & set(self._caption_lines_of(info)):
                self._grid_set_table_align(info, align)
        self._refresh_list_buttons()
        self._schedule_autosave()

    def _explain_cells_not_table(self):
        """Say how a table moves, after every one of its cells was aligned."""
        self.show_info(
            "The cells moved, not the table",
            "That lined up the text inside every cell. The table itself "
            "stayed where it was.\n\n"
            "To move the whole table across the page, right-click it and "
            "choose Table → Center table on page (or Table left on page, "
            "Table right on page).\n\n"
            "If the table has a caption, a line such as “Table 1: …” right "
            "under it, aligning that line moves the table too.")

    def _align_lines(self, line_numbers, align):
        """Give whole lines one alignment; "left" takes it away."""
        for line_no in line_numbers:
            for name in ("center", "right"):
                self.body_text.tag_remove(f"align_{name}",
                                          f"{line_no}.0", f"{line_no}.end+1c")
            if align != "left":
                # The newline too: stopping at .end, an empty centred line's
                # caret jumped left at Enter.
                self.body_text.tag_add(f"align_{align}",
                                       f"{line_no}.0", f"{line_no}.end+1c")

    def _list_kind_of(self, text_widget, line_no, line=None):
        """Which kind of list line this is, or None -- by the saved marker,
        not the tag, which Tk passes on (a pasted line came back a bullet
        without one). *line* is the line's text when its caller has it.
        """
        if line is None:
            line = text_widget.get(f"{line_no}.0", f"{line_no}.end")
        return parse_list_marker(line)[0]

    # How much of a line its list marker and its being a table row are read
    # from, unless its start leaves either open (_line_head).
    _LINE_HEAD = 64

    def _line_head(self, line_no):
        """The body's line *line_no* as far as a list marker or a table row
        is told from it: the whole line when short, or when its start is
        blank, a pipe or a run of digits; else its first characters. Tk's
        get of a whole long line costs the square of the tags on it, and
        every key and click read one (final audit, round 10)."""
        b = self.body_text
        head = b.get(f"{line_no}.0", f"{line_no}.0+{self._LINE_HEAD}c")
        if "\n" in head:
            return head.split("\n", 1)[0]
        lead = head.lstrip()
        if (len(head) >= self._LINE_HEAD
                and (not lead or lead.startswith(core_tables.CELL)
                     or lead.rstrip(".").isdecimal())):
            return b.get(f"{line_no}.0", f"{line_no}.end")
        return head

    @staticmethod
    def _lines_starting_in(text_widget, tag):
        """The lines whose first character wears *tag* -- what
        ``tag_names(f"{line}.0")`` answers line by line, from one question."""
        found = set()
        ranges = text_widget.tag_ranges(tag)
        for first, last in zip(ranges[::2], ranges[1::2]):
            (l1, c1), (l2, c2) = _index_key(first), _index_key(last)
            found.update(range(l1 if c1 == 0 else l1 + 1, l2 + 1 if c2 > 0 else l2))
        return found

    def _extract_paragraphs(self, text_widget, text=None):
        """Read the list tags back out as plain data, for saving, by line
        number: a list applies to a whole line, which survives a different
        width. *text* is the widget's text as its caller read it.
        """
        paragraphs = []
        if text is None:
            text = text_widget.get("1.0", "end-1c")
        lines = text.split("\n")
        # The lowest-priority margin tag on a line is the one its depth is
        # read from, as tag_names lists them (_paragraph_indent_of).
        depth = {}
        for name in text_widget.tag_names():
            if name.startswith("para_"):
                level = self._paragraph_tags.get(name, (None, 0))[1]
                for line_no in self._lines_starting_in(text_widget, name):
                    depth.setdefault(line_no, level)
        centred = self._lines_starting_in(text_widget, "align_center")
        right = self._lines_starting_in(text_widget, "align_right")
        for line_no, line in enumerate(lines, start=1):
            kind = parse_list_marker(line)[0]
            align = ("center" if line_no in centred
                     else "right" if line_no in right else "left")
            indent = depth.get(line_no)
            if indent is None:
                indent = self._bullet_depth(line)
            if not kind and align == "left" and not indent:
                continue            # an ordinary paragraph records nothing
            entry = {"line": line_no - 1}
            if kind:
                entry["kind"] = kind
            if indent:
                entry["indent"] = indent
            if align != "left":
                entry["align"] = align
            paragraphs.append(entry)
        return paragraphs

    def _resync_list_tags(self, line_no=None, line=None):
        """Redraw the indent tags from the markers in the text: typed at an
        item's end, text arrives untagged and its wrap lost the hanging
        indent. The caret's line only by default, as typing is one line at a
        time; the whole body for a paste. *line* is line *line_no*'s text
        when its caller has read it already.
        """
        # Each line read once, the note in one get: three readers asked Tk
        # for the same line, and Tk's cost for each is about the square of
        # the toggles on it (final audit, round 10).
        if line_no is None:
            lines = self.body_text.get("1.0", "end-1c").split("\n")
            first = 1
        else:
            if line is None:
                line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
            lines, first = [line], line_no
        for n, line in enumerate(lines, start=first):
            # A table row's monospace face, asked with the list margins; taken
            # off with its newline, so it is not passed on.
            if is_table_row(line):
                self.body_text.tag_add(self.TABLE_TAG, f"{n}.0", f"{n}.end")
                # An alignment tag places the table's window, on purpose (a
                # paste's is scrubbed in _apply_paragraphs); only its spill over
                # the newline is trimmed, so a line under it does not inherit.
                for tag in ("align_center", "align_right"):
                    self.body_text.tag_remove(tag, f"{n}.end", f"{n}.end+1c")
            else:
                self.body_text.tag_remove(self.TABLE_TAG, f"{n}.0", f"{n}.end+1c")
            kind = self._list_kind_of(self.body_text, n, line)
            indent = self._paragraph_indent_of(self.body_text, n, line)
            wanted = (self._paragraph_tag(self.body_text, kind, indent)
                      if (kind or indent) else None)
            for name in self.body_text.tag_names(f"{n}.0"):
                if name.startswith("para_") and name != wanted:
                    self.body_text.tag_remove(name, f"{n}.0", f"{n}.end+1c")
            if wanted:
                self.body_text.tag_add(wanted, f"{n}.0", f"{n}.end")

    def _on_comments_paste(self, event=None):
        """Keep tables OUT of the comments box, plain text with no grids: a
        paste's table rows are stripped, the prose kept and a note said. One
        with none falls through to Tk (None) -- unless the paste ceiling cut
        it (_clipboard_text), when what is kept is pasted here."""
        raw, cut = self._clipboard_text(self.comments_text)
        if not raw:
            return None
        lines = raw.replace("\r\n", "\n").replace("\r", "\n").split("\n")
        table = any(core_tables.is_table_row(ln) for ln in lines)
        if not table and not cut:
            return None                      # no table -- let Tk paste it
        if table:
            kept = [ln for ln in lines if not core_tables.is_table_row(ln)]
            # Collapse the blank runs a removed table leaves behind, so the
            # prose does not arrive with a gap where the grid was.
            cleaned = re.sub(r"\n{3,}", "\n\n", "\n".join(kept)).strip("\n")
        else:
            cleaned = "\n".join(lines)
        try:
            self.comments_text.delete("sel.first", "sel.last")
        except tk.TclError:
            pass
        if cleaned:
            self.comments_text.insert("insert", cleaned)
        self._schedule_autosave()
        if table:
            self._show_toast("Comments keep text only — the table wasn't added")
        if cut:
            self._say_if_paste_was_cut({"text_cut": True})
        return "break"

    def _on_body_paste(self, event=None):
        """Paste, keeping the source's formatting where there is any.

        Falls through to Tk's own plain-text paste when the clipboard holds
        nothing rich, when this is not Windows, or when anything at all goes
        wrong reading it -- returning None leaves the default handler to
        run, which is exactly what happened before this existed.
        """
        # With cells selected, Ctrl+V means those cells -- it used to
        # paste into the body beside the table.
        sel = getattr(self, "_grid_sel", None)
        if sel is not None:
            first = self._grid_first_line(sel["info"])
            if first is not None:
                self._grid_paste_cells(sel["info"],
                                       sel["box"][0], sel["box"][1])
                return "break"
        # A paste's key release is not the person leaving a table: read as one,
        # it padded tables outside the paste's unit, and the first Ctrl+Z did
        # nothing. A table the paste leaves is tidied inside it.
        self._last_caret_line = None
        self._paste_from_table = self._note_raw_table_at_caret()
        # Our own cell copy goes the TSV route, which carries all it knew: by
        # its HTML (for Word) it lost widths and glued a row ("Source: | fff
        # |..."). Read off the system clipboard, which also holds the plain text.
        own = getattr(self, "_grid_cell_clip_text", None)
        own_copy = bool(own) and clipboard.read_text() == own
        # The delete run opened for this paste over a styled selection: each
        # route's own unit ended it empty, and Ctrl+Z gave the selection plain.
        run = getattr(self, "_styled_delete_run", None)
        if own_copy:
            if self._paste_tsv_as_table():
                return "break"
            # A single copied cell has no tabs: it pastes as the plain
            # text it is, never as a one-cell table the HTML would make.
        elif self._paste_formatted():
            return "break"
        if not own_copy and self._paste_tsv_as_table():
            return "break"
        if self._paste_pipe_text_on_own_lines():
            return "break"
        # In a table being typed the plain paste is made here, so the table
        # it leaves is tidied inside the same unit (Tk's own lands after this
        # returns, outside any unit of the app's).
        if (getattr(self, "_paste_from_table", None)
                and self._paste_text_leaving_table()):
            return "break"
        if self._paste_text_forgetting_widths():
            return "break"
        # None of them took it, and Tk's paste is the delete the run was
        # opened for -- given back while the text is still what the run
        # noted.
        if run is not None:
            try:
                if self._fmt_state()[0] == run["before"][0]:
                    self._styled_delete_run = run
            except (tk.TclError, ValueError):
                pass
        # Plain paste: Tk inserts the text after this returns, so the list
        # tags can only be brought back into step once that has happened.
        self._body_follow_caret = True
        self.after_idle(self._resync_list_tags)
        self.after_idle(self._render_table_grids)
        # ...and so can the run it lands in: two marks where it goes in, the
        # first staying put, the second carried past it (_settle_tk_paste).
        b = self.body_text
        try:
            b.mark_set(self._PASTE_FROM, "insert")
            b.mark_gravity(self._PASTE_FROM, "left")
            b.mark_set(self._PASTE_TO, "insert")
            b.mark_gravity(self._PASTE_TO, "right")
            self.after_idle(self._settle_tk_paste)
        except tk.TclError:
            pass
        return None

    @_undo_atom
    def _paste_pipe_text_on_own_lines(self):
        """Plain text whose edge lines are table rows lands on its own
        lines, never glued into the caret's ('|   | [x] |fig2...', field
        report), with a blank line from a table it would touch (_rows_gap).
        """
        raw, cut = self._clipboard_text(self.body_text)
        if raw is None:
            return False
        if not raw or "\n" not in raw.strip():
            single = raw or ""
            if not core_tables.is_table_row(single.strip("\n")):
                return False
        raw = self._foreign_plain(raw)
        lines = raw.strip("\n").split("\n")
        if not (core_tables.is_table_row(lines[0])
                or core_tables.is_table_row(lines[-1])):
            return False
        b = self.body_text
        # The grids down before anything is written (see
        # _paste_tsv_as_table): torn down by the drawing below, inside this
        # unit, they split it, and the first Ctrl+Z changed nothing.
        self._teardown_table_grids()
        if b.tag_ranges("sel"):
            # Over a selection the rows take its place, as cells do; left to
            # Tk, a line selected above a table was replaced by rows that
            # then joined that table.
            try:
                b.delete("sel.first", "sel.last")
            except tk.TclError:
                pass
        text = raw.strip("\n")
        lead, trail = self._rows_gap(text)
        b.insert("insert", lead + text + trail)
        kept = self._tidy_table_paste_left()
        self._body_follow_caret = True
        self._resync_list_tags()
        self._render_table_grids(keep_typed=kept)
        self._schedule_autosave()
        if cut:
            self._say_if_paste_was_cut({"text_cut": True}, in_body=True)
        return True

    def _foreign_plain(self, raw):
        """*raw*, pasted as text, with every table's separator spelled at
        markdown's minimum: dashes typed in another program are not widths
        set here, and read as them a pasted "---:" drew its column four
        characters wide (core_tables.forget_widths). This app's own copy
        from a note (_copy_formatted) keeps its dashes, which are. Line
        endings come back as the note's."""
        text = raw.replace("\r\n", "\n").replace("\r", "\n")
        mine = getattr(self, "_formatted_clip", None)
        if mine and text == mine[0].replace("\r\n", "\n"):
            return text
        return core_tables.forget_widths(text)[0]

    @_undo_atom
    def _paste_text_forgetting_widths(self):
        """Plain text with a mid-text table whose separator spells widths,
        pasted by the app so the separator goes in at the minimum
        (_foreign_plain), in the paste's unit. Anything else stays Tk's --
        unless the ceiling cut it, when the app pastes what it keeps."""
        raw, cut = self._clipboard_text(self.body_text)
        if not raw:
            return False
        text = self._foreign_plain(raw)
        if not cut and text == raw.replace("\r\n", "\n").replace("\r", "\n"):
            return False
        # The grids down before anything is written (see
        # _paste_tsv_as_table): the drawing at the end would split the unit.
        self._teardown_table_grids()
        self._replace_selection_with(text)
        kept = self._tidy_table_paste_left()
        self._body_follow_caret = True
        self._resync_list_tags()
        self._render_table_grids(keep_typed=kept)
        self._schedule_autosave()
        if cut:
            self._say_if_paste_was_cut({"text_cut": True}, in_body=True)
        return True

    # Where a table being typed began when a paste started (see
    # _tidy_table_paste_left).
    _PASTE_FROM_TABLE = "pasteFromTable"

    def _row_being_typed(self):
        """The caret's line when it is a row of a table not yet drawn there
        -- a table being typed -- else None. Asked of the caret's own row: a
        table typed by hand is drawn row by row as the caret leaves each, so
        the row being typed sits under a drawn header, and asking whether
        the table's first line was drawn found none being typed past its
        first row."""
        try:
            here = int(self.body_text.index("insert").split(".")[0])
        except (tk.TclError, ValueError, AttributeError):
            return None
        if self._table_block_at(here) is None or any(
                first is not None and first <= here < first + info["nrows"]
                for info in getattr(self, "_table_grids", [])
                for first in (self._grid_first_line(info),)):
            return None
        return here

    def _note_raw_table_at_caret(self):
        """The table being typed that the caret stands in (_row_being_typed),
        as a mark at its first line; None when there is none."""
        b = self.body_text
        here = self._row_being_typed()
        if here is None:
            return None
        block = self._table_block_at(here)
        b.mark_set(self._PASTE_FROM_TABLE, f"{block[0]}.0")
        b.mark_gravity(self._PASTE_FROM_TABLE, "right")
        self._paste_caret_line = here
        # Recorded with no window on the table's line, drawn later: replayed
        # with it, Ctrl+Z took letters out of the header. Marked so.
        self._mark_unit_window_free()
        return self._PASTE_FROM_TABLE

    def _tidy_table_paste_left(self):
        """Tidy the table being typed that a paste took the caret out of,
        inside the paste's unit, as leaving by a key tidies it -- or it was
        saved with ragged columns. Returns the line of a table still being
        typed that the paste left the caret on, for the drawing to leave
        alone (_render_table_grids), or None."""
        mark = getattr(self, "_paste_from_table", None)
        self._paste_from_table = None
        if not mark:
            return None
        b = self.body_text
        try:
            first = int(b.index(mark).split(".")[0])
            b.mark_unset(mark)
            here = int(b.index("insert").split(".")[0])
        except (tk.TclError, ValueError):
            return None
        if here == getattr(self, "_paste_caret_line", None):
            # Still on its line, as after a letter typed there: tidied and drawn
            # once the caret leaves -- unnamed, a menu paste never was.
            self._last_caret_line = here
            return here
        block = self._table_block_at(first)
        if block is not None and not block[0] <= here <= block[1]:
            self._align_table_block(block[0])
        return None

    @_undo_atom
    def _paste_text_leaving_table(self):
        """Tk's plain paste, made by the app when the caret stands in a
        table being typed, so the table the paste takes the caret out of is
        tidied in the same undo unit (_tidy_table_paste_left)."""
        text, cut = self._clipboard_text(self.body_text)
        if text is None:
            self._paste_from_table = None
            return False
        b = self.body_text
        # The grids down before anything is written (see
        # _paste_tsv_as_table): the drawing at the end would split the unit.
        self._teardown_table_grids()
        try:
            b.delete("sel.first", "sel.last")
        except tk.TclError:
            pass
        b.insert("insert", self._foreign_plain(text))
        kept = self._tidy_table_paste_left()
        self._body_follow_caret = True
        self._resync_list_tags()
        self._render_table_grids(keep_typed=kept)
        self._schedule_autosave()
        if cut:
            self._say_if_paste_was_cut({"text_cut": True}, in_body=True)
        return True

    @_undo_atom
    def _paste_tsv_as_table(self, raw=None, plain=False):
        """Tab-separated clipboard text pasted into the body becomes a real
        table -- copied cells, or a spreadsheet's ("<br> <br> appears", field
        report); a single cell stays text. *plain* (Ctrl+Shift+V): without
        the cells' styles or the table's place. A *raw* given was read by
        the caller (_paste_plain), ceiling and all.
        """
        cut = False
        if raw is None:
            raw, cut = self._clipboard_text(self.body_text)
            if raw is None:
                return False
        if not raw or "\t" not in raw:
            return False
        raw = raw.replace("\r\n", "\n").replace("\r", "\n")
        b = self.body_text
        try:
            selected = b.index("sel.first")
            # A selection ending where a table begins keeps that table's line
            # break: deleted, the rows went under its header, cutting it off.
            last = b.index("sel.last")
            if (b.compare(last, "==", f"{last} linestart")
                    and b.compare(selected, "<", last)
                    and core_tables.is_table_row(
                        b.get(last, f"{last} lineend"))):
                b.tag_remove("sel", f"{last} -1c", last)
                if not b.tag_ranges("sel"):
                    # Only the break was selected: paste where it stood.
                    b.mark_set("insert", f"{last} -1c")
                    selected = None
        except tk.TclError:
            selected = None
        try:
            here = b.get(f"{selected or 'insert'} linestart",
                         f"{selected or 'insert'} lineend")
            # Over a selection, on what is left of its lines: off the first
            # line alone, Ctrl+A read as "inside a table", raw tabs going in.
            remains = (here if selected is None else
                       b.get("sel.first linestart", "sel.first")
                       + b.get("sel.last", "sel.last lineend"))
        except tk.TclError:
            return False
        if (core_tables.is_table_row(here)
                and core_tables.is_table_row(remains)):
            # Inside a table, pasting cells is the grid's business (the
            # cell-selection branch above); don't nest pipes into pipes.
            return False
        rows = [line.split("\t") for line in raw.strip("\n").split("\n")]
        ncols = max(len(row) for row in rows)
        rows = [row + [""] * (ncols - len(row)) for row in rows]
        # Our own copy remembers the source columns' set widths -- a
        # duplicated table comes back at the SAME widths, not shrunk
        # to the default. Text from elsewhere gets the plain rule.
        own = raw == getattr(self, "_grid_cell_clip_text", None)
        clip_widths = None
        if own and getattr(self, "_grid_cell_clip_widths", None):
            clip_widths = list(self._grid_cell_clip_widths)
            while len(clip_widths) < ncols:
                clip_widths.append({"width": None, "align": None,
                                    "hidden": False})
        # The separator laid out as the tidy would (_align_table_block), its
        # dashes the set widths, padded with spaces: narrower, the tidy padded
        # it later, an edit the first Ctrl+Z spent.
        separator = (core_tables.make_separator(clip_widths) if clip_widths
                     else ["---"] * ncols)
        # Our own copy keeps each cell's alignment; anything else is left.
        clip_aligns = (getattr(self, "_grid_cell_clip_aligns", None) or []) if own else []
        aligns = [(list(clip_aligns[i]) if i < len(clip_aligns) else [])
                  + [core_tables.ALIGN_LEFT] * ncols for i in range(len(rows))]
        aligns = [row[:ncols] for row in aligns]
        rows = [rows[0], separator] + rows[1:]
        aligns = [aligns[0], [core_tables.ALIGN_LEFT] * ncols] + aligns[1:]
        # The ceiling holds padding included (16 KB became two million
        # characters): rows past it left out first; no header fitting, text.
        def laid_out(kept):
            return core_tables.table_length(rows[:kept + 1], aligns[:kept + 1])
        source_rows = len(rows) - 1
        if laid_out(source_rows) > MAX_PASTE_CHARS:
            kept = core_tables.longest_fitting(source_rows, laid_out,
                                               MAX_PASTE_CHARS)
            if kept == 0:
                return False
            rows, aligns, cut = rows[:kept + 1], aligns[:kept + 1], True
        lines = core_tables.format_table(rows, aligns)
        clip_place = getattr(self, "_grid_cell_clip_place", None) if own and not plain else None
        # The grids come down before anything is written: torn down at the
        # end, they split the unit, and the first Ctrl+Z did nothing.
        self._teardown_table_grids()
        if selected is not None:
            # Over a selection, the table takes its place, in this unit, so one
            # Ctrl+Z brings it back styled (it stayed, the table under it).
            try:
                start = b.index("sel.first")
                b.delete("sel.first", "sel.last")
                b.mark_set("insert", start)
                here = b.get("insert linestart", "insert lineend")
            except tk.TclError:
                pass
        prefix = "" if not here.strip() else "\n"
        if not here.strip():
            # Pasting ONTO an empty line directly under a table would
            # glue the new rows to that block and merge the two tables
            # into one misshapen grid -- keep the empty line as the gap.
            try:
                ln = int(b.index("insert").split(".")[0])
                above = b.get(f"{ln - 1}.0", f"{ln - 1}.end") if ln > 1 else ""
            except (tk.TclError, ValueError):
                above = ""
            if core_tables.is_table_row(above):
                prefix = "\n"
        ins_line = int(b.index("insert").split(".")[0])
        b.insert("insert lineend", prefix + "\n".join(lines) + "\n")
        first_new = ins_line + (1 if prefix else 0)
        if own and not plain and getattr(self, "_grid_cell_clip_styles", None):
            # The copied cells' own styles, on the same cells again.
            self._grid_lay_cell_styles(first_new, lines, self._grid_cell_clip_styles)
        if clip_place in ("center", "right"):
            for n in range(first_new, first_new + len(lines)):
                b.tag_add(f"align_{clip_place}", f"{n}.0", f"{n}.end")
        kept = self._tidy_table_paste_left()
        self._body_follow_caret = True
        self._resync_list_tags()
        self._render_table_grids(keep_typed=kept)
        self._schedule_autosave()
        # The paste's key release is not a leaving (see _body_undo_redo); a row
        # it left the caret on stays the caret's line (_tidy_table_paste_left).
        self._last_caret_line = kept
        if cut:
            self._say_if_paste_was_cut({"text_cut": True}, in_body=True)
        return True

    @_undo_atom
    def _spell_replace_body(self, start, end, new):
        """A spelling suggestion taken in the note: *new* replaces the text
        from *start* to *end* in that text's own formatting -- a bold
        misspelling stays bold, corrected -- as one step Ctrl+Z takes back
        whole, formatting and all."""
        b = self.body_text
        tags = tuple(t for t in b.tag_names(start)
                     if t not in ("sel", self.SPELL_TAG))
        b.delete(start, end)
        b.insert(start, new, tags)
        self.update_word_count()

    @_undo_atom
    def _paste_plain(self, event=None):
        """Paste the clipboard's text with none of its formatting, a web
        page's styling left behind -- in one undo unit, or Ctrl+Z took two
        steps and gave the selection back plain.
        """
        # The formatted paste's ceiling, here too: one line of 600,000
        # characters took ten seconds to lay out at every key (ISSUES_LOG:
        # "The plain paste with no ceiling").
        text, cut = self._clipboard_text(self.body_text)
        if text is None:
            return "break"
        # This app's own copy of table cells is a table: its plain text is
        # tabs, for a spreadsheet, and pasted as that the boxes read "[x]"
        # where Ctrl+V rebuilt the table (2026-10-24, test case 693).
        own_cells = getattr(self, "_grid_cell_clip_text", None)
        if (own_cells and "\t" in own_cells
                and text.replace("\r\n", "\n").replace("\r", "\n") == own_cells
                and self._paste_tsv_as_table(raw=text, plain=True)):
            return "break"
        # A source's own bullets are stripped, or the list came back; a PDF's
        # column breaks are rejoined first, as that reads the lines and
        # leaves a list alone.
        self._paste_from_table = self._note_raw_table_at_caret()
        self._replace_selection_with(
            strip_list_markers(reflow_wrapped(self._foreign_plain(text))))
        if cut:
            self._say_if_paste_was_cut({"text_cut": True}, in_body=True)
        kept = self._tidy_table_paste_left()
        self._body_follow_caret = True
        self.after_idle(self._resync_list_tags)
        self.after_idle(lambda: self._render_table_grids(keep_typed=kept))
        self._schedule_autosave()
        # Not the person leaving a table, either (see _on_body_paste); a row
        # it left the caret on stays the caret's line.
        self._last_caret_line = kept
        return "break"

    @staticmethod
    def _cap_paste(text):
        """*text* as a paste may put it in -- each line break one character,
        as the note keeps it, then its first MAX_PASTE_CHARS characters, the
        formatted paste's ceiling -- and whether it was cut. The one ceiling
        every paste route keeps (_clipboard_text, and the routes that read
        the clipboard or the selection some other way)."""
        # Before it is weighed: Windows' clipboard keeps CR LF, and a paste
        # that fitted, weighed at two characters a line, lost its end.
        text = text.replace("\r\n", "\n").replace("\r", "\n")
        if len(text) > MAX_PASTE_CHARS:
            return text[:MAX_PASTE_CHARS], True
        return text, False

    def _clipboard_text(self, widget):
        """The clipboard's text as a paste puts it in, and whether it was
        cut (_cap_paste) -- every route pasted all of it, a second a key
        after (ISSUES_LOG: "Limits that held at the door but not after it").

        Returns:
            ``(text, cut)``, or ``(None, False)`` when the clipboard holds
            no text.
        """
        text = clipboard.read_text()
        if text is None:
            try:
                text = widget.clipboard_get()
            except tk.TclError:
                return None, False
        return self._cap_paste(text)

    def _paste_selection_capped(self, event, in_body=False):
        """A middle-click paste -- the selection, where the pointer is, as
        Tk's own binding makes it -- within the ceiling every paste keeps.
        Under it Tk pastes as ever (None); past it the first
        MAX_PASTE_CHARS characters go in instead, and that is said."""
        widget = event.widget
        try:
            text = widget.selection_get(selection="PRIMARY")
        except tk.TclError:
            return None
        text, cut = self._cap_paste(text)
        if not cut:
            return None
        try:
            # Tk's own pastes nothing after a drag with the middle button,
            # which scrolled the view instead.
            if self.tk.eval("expr {[info exists ::tk::Priv(mouseMoved)]"
                            " && $::tk::Priv(mouseMoved)}") == "1":
                return "break"
            widget.mark_set("insert", f"@{event.x},{event.y}")
            widget.edit_separator()
            widget.insert("insert", text)
            widget.edit_separator()
            widget.focus_set()
        except tk.TclError:
            return "break"
        if widget in (getattr(self, "body_text", None),
                      self.comments_text):
            self._schedule_autosave()
        self._say_if_paste_was_cut({"text_cut": True}, in_body=in_body)
        return "break"

    def _replace_selection_with(self, text):
        """Drop the selection, if any, and put *text* where the cursor is --
        over a list, the next item keeping its number (see
        _delete_selection_reaching_list), and the lists renumbered."""
        self._caret_out_of_hidden()
        listed = self._delete_selection_reaching_list(text)
        if not listed:
            try:
                self.body_text.delete("sel.first", "sel.last")
            except tk.TclError:
                pass
        lead, trail = self._rows_gap(text)
        at = self.body_text.index("insert")
        self.body_text.insert("insert", lead + text + trail)
        self._take_run_between(at, self.body_text.index("insert"))
        if listed:
            self._resync_list_tags()
            self._renumber_lists()

    def _rows_gap(self, text):
        """What *text*, going in at the caret, needs before and after so
        table rows at its edges stay a table of their own: lines of their
        own, a blank line from a table beside -- or they joined it, its
        header read as data, or glued onto a caption. Every paste asks."""
        b = self.body_text
        lines = text.split("\n")
        lead = trail = ""
        try:
            before = b.get("insert linestart", "insert")
            after = b.get("insert", "insert lineend")
            here = int(b.index("insert").split(".")[0])
            above = b.get(f"{here - 1}.0", f"{here - 1}.end") if here > 1 else ""
            below = b.get(f"{here + 1}.0", f"{here + 1}.end")
        except (tk.TclError, ValueError):
            return lead, trail
        if core_tables.is_table_row(lines[-1]):
            if after.strip() or core_tables.is_table_row(below):
                trail = "\n"
        if core_tables.is_table_row(lines[0]):
            if before.strip() or core_tables.is_table_row(above):
                lead = "\n"
        return lead, trail

    @_undo_atom
    def _paste_formatted(self):
        """Paste rich clipboard content. True if that actually happened."""
        markup = clipboard.read_html()
        if not markup:
            return False
        cut = {}
        text, spans, paragraphs = html_to_note(markup, report=cut)
        mine = getattr(self, "_formatted_clip", None)
        own = (bool(mine) and not any(cut.values())
               and markup == mine[3])
        if own:
            # Our own copy, from a note: everything it carried comes back,
            # its sizes and typefaces included.
            text = mine[0]
            spans = [dict(s) for s in mine[1]]
            # A plain paragraph's indent stays home, as the HTML has always
            # left it: one word copied from an indented line must not indent
            # the paragraph it is pasted into.
            paragraphs = []
            for p in mine[2]:
                p = dict(p)
                if not p.get("kind"):
                    p.pop("indent", None)
                if len(p) > 1:
                    paragraphs.append(p)
        if not text:
            return False
        # Only a source with no formatting, as a PDF's: reflowing moves every
        # offset, and a formatted source's bold would slide (it sent real
        # paragraphs anyway).
        if not spans and not paragraphs and not own:
            text = reflow_wrapped(text)

        # The grids down before anything is written (see
        # _paste_tsv_as_table): the drawing at the end of this unit would
        # split it, and the first Ctrl+Z would change nothing.
        self._teardown_table_grids()
        try:
            self.body_text.delete("sel.first", "sel.last")
        except tk.TclError:
            pass
        # A blank line between table rows it brings and a table it would
        # touch (_rows_gap) -- the one before goes in first, so the offsets
        # below still count from where the text itself begins.
        lead, trail = self._rows_gap(text)
        if lead:
            self.body_text.insert("insert", lead)
        # Where it lands, before inserting: everything after this point
        # shifts, and Tk moves its own tags along with the text, so only
        # what arrives needs placing.
        at = self._char_offset(self.body_text, self.body_text.index("insert"))
        line = int(self.body_text.index("insert").split(".")[0]) - 1
        pasted_from = self.body_text.index("insert")
        self.body_text.insert("insert", text + trail)

        self._apply_formatting(
            self.body_text,
            [dict(s, start=s["start"] + at, end=s["end"] + at) for s in spans])
        self._apply_paragraphs(
            self.body_text,
            [dict(p, line=p["line"] + line) for p in paragraphs],
            scrub_table_align=True)
        # Pasted into a run with a size or a font, the text took the run's
        # composite tag, weight and all, which outranks the bold it brought;
        # pasted at a weight's edge inside one, it took none.
        here = self.body_text.index("insert")
        if not self._take_run_between(pasted_from, here):
            self._fit_font_tags(pasted_from, here)
        # A pasted list starts its own numbering at one; renumbering makes
        # it continue whatever it was dropped into.
        self._renumber_lists()
        kept = self._tidy_table_paste_left()
        # A whole-body pass: a paste brings many lines, whose derived tags
        # (margins, a table's face) the text does not carry.
        self._body_follow_caret = True
        self._resync_list_tags()
        self._render_table_grids(keep_typed=kept)
        self._refresh_format_buttons()
        self._schedule_autosave()
        self._say_if_paste_was_cut(cut, in_body=True)
        return True

    def _say_if_paste_was_cut(self, cut, in_body=False):
        """Say what a paste's caps left out (html_to_note's report), once
        missing without a word -- after idle, so no question sits inside the
        paste's undo unit with an autosave running in its middle. *in_body*:
        only the body keeps formatting, so only there is its cut news."""
        if cut.get("text_cut"):
            msg = (f"Only the first {MAX_PASTE_CHARS:,} characters of what you "
                   "copied were pasted; the rest was left out.")
            if in_body:
                msg += ("\n\nA note longer than that is slow to edit: paste "
                        "the rest into a note of its own.")
        elif in_body and cut.get("styles_cut"):
            msg = ("All of the text was pasted, but its formatting stops after "
                   f"the first {MAX_PASTE_SPANS:,} styled pieces.")
        else:
            return
        self.after_idle(lambda: self.show_info("Pasted in part", msg))

    def _copy_formatted(self, event=None):
        """Copy the selection so it arrives elsewhere still formatted, the
        plain text alongside for what cannot read markup. With cells
        selected, Ctrl+C means the cells -- the empty text selection left
        last week's copy on the clipboard.
        """
        sel = getattr(self, "_grid_sel", None)
        if sel is not None:
            self._grid_copy_selection(sel)
            return "break"
        try:
            start = self.body_text.index("sel.first")
            end = self.body_text.index("sel.last")
        except tk.TclError:
            return None                      # nothing selected; let Tk decide
        text = self.body_text.get(start, end)
        if not text:
            return None
        # The note read once, for the selection's place, its styles and its
        # lines (_char_offsets): each read of a long styled line is dear.
        whole = self.body_text.get("1.0", "end-1c")
        where = self._char_offsets(self.body_text, [start, end], whole)
        first, last = where[str(start)], where[str(end)]
        first_line = int(start.split(".")[0]) - 1

        clipped = []
        for span in self._extract_formatting(self.body_text, whole):
            lo, hi = max(span["start"], first), min(span["end"], last)
            if hi > lo:
                clipped.append(dict(span, start=lo - first, end=hi - first))
        # A line's looks travel with its start: a word copied out of a nested
        # item set the level of the item it was pasted into (lows wave).
        line_count = text.count("\n") + (0 if text.endswith("\n") else 1)
        skipped = 1 if int(start.split(".")[1]) > 0 else 0
        paragraphs = [
            dict(p, line=p["line"] - first_line)
            for p in self._extract_paragraphs(self.body_text, whole)
            if skipped <= p["line"] - first_line < line_count]

        # inline_tables: a fragment has no stylesheet, and Word drew a bare
        # table borderless, a phantom (round-8 field report).
        html = note_to_html(text, clipped, paragraphs, inline_tables=True)
        if not clipboard.write(text, html):
            return None                      # nothing written; Tk's copy runs
        # Kept for a paste into another note, which reads no size or font
        # back out of HTML (a web page's are left behind by design).
        self._formatted_clip = (text, clipped, paragraphs, html)
        return "break"

    def _cut_formatted(self, event):
        """Cut as Copy copies -- the words, their styles, their lines' looks
        -- then delete, writing nothing more. Tk's own Cut and the list's put
        the words alone over it, so a move by Ctrl+X and Ctrl+V lost its bold,
        its centring and a nested item's level, saved (the lows wave's
        verification, round 6). Cells have no cut of their own: with cells
        selected, the key is left to Tk."""
        if getattr(self, "_grid_sel", None) is not None or self._copy_formatted() != "break":
            return None
        if self._list_aware_delete(event, virtual="clear") == "break":
            return "break"
        self._note_styled_delete(event, virtual=True)
        b = self.body_text
        # Tk's own Cut, less its clipboard: one step of Ctrl+Z.
        auto = b.tk.getboolean(b.cget("autoseparators"))
        if auto:
            b.configure(autoseparators=False)
            b.edit_separator()
        try:
            b.delete("sel.first", "sel.last")
        except tk.TclError:
            pass
        if auto:
            b.edit_separator()
            b.configure(autoseparators=True)
        return "break"

    def _refresh_list_buttons(self, line=None):
        """Show the bullet/number button pressed when the cursor's line --
        not the whole selection, part plain -- is a list of that kind, as
        the style buttons do. *line* is that line's text when its caller
        has just read it.
        """
        if not self._list_buttons:
            return
        line_no = int(self.body_text.index("insert").split(".")[0])
        current = self._list_kind_of(self.body_text, line_no, line)
        for kind, btn in self._list_buttons.items():
            self._set_button_pressed(btn, kind == current)
        current_align = self._grid_align_context()
        if current_align is None:
            current_align = self._paragraph_align_of(self.body_text, line_no)
        for align, btn in self._align_buttons.items():
            self._set_button_pressed(btn, align == current_align)

    def _attach_tooltip(self, widget, title, detail=""):
        """Explain a widget while the cursor rests on it.

        Every button on the formatting toolbar is an icon or a single
        letter, so what each one does is a guess at best. Bound with add="+"
        because several of these widgets already carry their own <Enter> or
        <Button-1> handlers.
        """
        widget.bind("<Enter>",
                    lambda e, w=widget: self._schedule_tooltip(w, title, detail),
                    add="+")
        widget.bind("<Leave>", lambda e: self._hide_tooltip(), add="+")
        # A click hides the tip, through ONE command on the window: a widget's
        # own lambda died with a bin that redrew its row, still queued
        # ("invalid command name").
        hide = getattr(self, "_hide_tooltip_command", None)
        if hide is None:
            hide = self._hide_tooltip_command = self.register(self._hide_tooltip)
        # The "+" is spelled into the script: given a string, tkinter's
        # bind ignores add="+" and REPLACES the widget's other click
        # handlers -- measured, it took every icon's own action with it.
        widget.bind("<Button-1>", "+" + hide)

    def _schedule_tooltip(self, widget, title, detail):
        """Wait a moment before showing, so sweeping across the toolbar on
        the way somewhere else doesn't flash a row of labels."""
        self._hide_tooltip()
        self._tooltip_after = self.after(
            450, lambda: self._show_tooltip(widget, title, detail))

    def _hide_tooltip(self, event=None):
        """Take the tooltip down, and cancel one that has not appeared yet."""
        pending = getattr(self, "_tooltip_after", None)
        if pending is not None:
            try:
                self.after_cancel(pending)
            except (tk.TclError, ValueError):
                pass
            self._tooltip_after = None
        tip = getattr(self, "_tooltip", None)
        if tip is not None:
            try:
                if tip.winfo_exists():
                    tip.destroy()
            except tk.TclError:
                pass
            self._tooltip = None

    def _show_tooltip(self, widget, title, detail):
        self._tooltip_after = None
        try:
            if not widget.winfo_exists() or not widget.winfo_ismapped():
                return
        except tk.TclError:
            return

        tip = tk.Toplevel(self)
        tip.overrideredirect(True)
        tip.attributes("-topmost", True)
        self._tooltip = tip

        outer = tk.Frame(tip, bg=self.colors["accent"], padx=1, pady=1)
        outer.pack()
        box = tk.Frame(outer, bg=self.colors["card"], padx=10, pady=7)
        box.pack()
        tk.Label(box, text=title, bg=self.colors["card"],
                 fg=self.colors["text"], font=("Segoe UI", 9, "bold"),
                 justify="left").pack(anchor="w")
        if detail:
            tk.Label(box, text=detail, bg=self.colors["card"],
                     fg=self.colors["subtext"], font=("Segoe UI", 8),
                     justify="left").pack(anchor="w", pady=(2, 0))

        # Under the button, measured against the app window, never the screen
        # (ISSUES_LOG: "The dropdown that opened on the wrong monitor").
        tip.update_idletasks()
        x = widget.winfo_rootx()
        y = widget.winfo_rooty() + widget.winfo_height() + 6
        right_edge = self.winfo_rootx() + self.winfo_width() - 8
        if x + tip.winfo_width() > right_edge:
            x = max(self.winfo_rootx() + 8, right_edge - tip.winfo_width())
        tip.geometry(f"+{x}+{y}")

    def _add_fmt_item(self, widget, padx=(0, 2), ipady=0, fill=None, pady=0):
        """Record a formatting control, in the order it should appear.

        Not packed here: which row it lands on depends on how much room
        there is, which is not known until the editor has a width.
        """
        self._fmt_bar_items.append((widget, padx, ipady, fill, pady))

    def _on_format_bar_resize(self, event):
        """Reflow, but only when the width the controls have actually changed.

        Packing widgets changes the frame's size, which fires <Configure>
        again -- so reacting to every one of them is a loop.
        """
        if event.width == getattr(self, "_fmt_bar_width", None):
            return
        self._fmt_bar_width = event.width
        self._reflow_format_bar(event.width)

    def _reflow_format_bar(self, available=None):
        """Deal the controls into rows, breaking when one would not fit: one
        row at the usual sizes, a second for a narrow window, another scale
        or another font -- 577 px here, 827 on CI.
        """
        if not self._fmt_bar_items:
            return
        if available is None:
            available = self._fmt_bar.winfo_width()
        if available <= 1:                   # not laid out yet
            return

        measured = [(w.winfo_reqwidth() + px[0] + px[1], fl == "y")
                    for w, px, _ip, fl, _py in self._fmt_bar_items]
        # The arithmetic lives in core/formatting.py so it can be tested
        # against made-up widths rather than against whatever font this
        # machine happens to have -- see split_toolbar_rows.
        rows = [[self._fmt_bar_items[i] for i in row]
                for row in split_toolbar_rows(measured, available,
                                              len(self._fmt_bar_rows))]

        # The rows' packing tracked here, not read from winfo_ismapped(), which
        # lags: under Xvfb an empty row was kept.
        used = getattr(self, "_fmt_rows_used",
                       [False] * len(self._fmt_bar_rows))
        for widget, _padx, _ipady, _fill, _pady in self._fmt_bar_items:
            widget.pack_forget()
        for n, row_items in enumerate(rows):
            row = self._fmt_bar_rows[n]
            if row_items and not used[n]:
                row.pack(side="top", fill="x")
            elif not row_items and used[n]:
                row.pack_forget()
            for widget, padx, ipady, fill, pady in row_items:
                opts = {"side": "left", "padx": padx, "in_": row}
                if ipady:
                    opts["ipady"] = ipady
                if fill:
                    opts["fill"] = fill
                if pady:
                    opts["pady"] = pady
                widget.pack(**opts)
        for n in range(len(rows), len(self._fmt_bar_rows)):
            if used[n]:
                self._fmt_bar_rows[n].pack_forget()
        self._fmt_rows_used = [
            n < len(rows) and bool(rows[n])
            for n in range(len(self._fmt_bar_rows))]

    def _make_align_button(self, parent, align):
        """One alignment button, drawn as four bars on a small canvas.

        The ragged edge is the whole icon: bars flush left, centred, or
        flush right. Drawn rather than written because nothing in a normal
        font says "align right", and because canvas items can be recoloured
        on a theme switch.
        """
        # Two pixels less: the keyboard's ring is the outermost pixel, resting
        # in the canvas's own fill, where no bar is drawn.
        canvas = tk.Canvas(parent, width=self.px(24) - 2, height=self.px(20) - 2,
                           highlightthickness=0, bd=0, cursor="hand2",
                           relief="flat")
        self._ring_round(canvas)
        for row, width in enumerate((15, 9, 15, 9)):
            y = 5 + row * 3.5
            if align == "left":
                x0 = 5
            elif align == "right":
                x0 = 19 - width
            else:
                x0 = 12 - width / 2
            canvas.create_line(x0, y, x0 + width, y, width=2, tags="bar")
        self._scale_drawing(canvas, "bar")
        canvas.bind("<Button-1>",
                    lambda e, a=align: self._set_paragraph_align(a))
        self._pressable(canvas, lambda a=align: self._set_paragraph_align(a))
        return canvas

    def _set_button_pressed(self, btn, active):
        """The pressed/unpressed look shared by the paragraph buttons.

        Handles both real Buttons and the drawn alignment canvases: a canvas
        has no foreground of its own, so the bars are recoloured instead.
        """
        bg = self.colors["accent"] if active else self.colors["sidebar"]
        fg = self._on_fill("accent") if active else self.colors["text"]
        btn.configure(relief="sunken" if active else "flat")
        self._fill(btn, bg)
        if isinstance(btn, tk.Canvas):
            btn.itemconfigure("bar", fill=fg)
        else:
            btn.configure(fg=fg)

    def _apply_paragraphs(self, text_widget, paragraphs,
                          scrub_table_align=False):
        """Re-apply saved list lines as live tags, for loading -- only where
        the line still starts with a marker of that kind. *scrub_table_align*
        is the paste's: a source's alignment on its table rows re-centred
        pasted tables "for no reason"; a saved note keeps its placement.
        """
        if not paragraphs:
            return
        # The text read once: only tags change below.
        lines = text_widget.get("1.0", "end-1c").split("\n")
        total = len(lines)
        for paragraph in normalize_paragraphs(paragraphs, total):
            line_no = paragraph["line"] + 1
            if line_no > total:
                continue
            align = paragraph.get("align", "left")
            line_text = lines[line_no - 1]
            if (align != "left" and scrub_table_align
                    and is_table_row(line_text)):
                align = "left"
            if align != "left":
                # On a table row, not over the newline: the line kept under a
                # table was born centred, and the note read as unsaved for ever.
                end_index = (f"{line_no}.end" if is_table_row(line_text)
                             else f"{line_no}.end+1c")
                text_widget.tag_add(f"align_{align}",
                                    f"{line_no}.0", end_index)
            kind = paragraph.get("kind")
            indent = paragraph.get("indent", 0)
            if kind and parse_list_marker(line_text)[0] != kind:
                continue
            if not kind and not indent:
                continue
            # One margin a line: beside the one it had -- a paste's line -- the
            # depth was the tag Tk had made first that session (the lows
            # wave's verification, round 9).
            self._clear_paragraph_tags(text_widget, line_no)
            text_widget.tag_add(
                self._paragraph_tag(text_widget, kind, indent),
                f"{line_no}.0", f"{line_no}.end")

    def _set_paragraph_indent(self, line_no, indent, line=None):
        """Put one line at a given depth, rewriting its marker if it has one.

        A bullet's glyph changes with depth, so the marker in the text has to
        be replaced, not just the tag -- otherwise a demoted item keeps the
        parent's bullet and the two levels look identical. *line* is the
        line's text when its caller has read it already.
        """
        if line is None:
            line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
        kind = self._list_kind_of(self.body_text, line_no, line)
        self._clear_paragraph_tags(self.body_text, line_no)
        if kind == "bullet":
            _, marker, _rest = parse_list_marker(line)
            new_marker = marker_for("bullet", 1, indent)
            if marker != new_marker:
                self.body_text.delete(f"{line_no}.0",
                                      f"{line_no}.0+{len(marker)}c")
                self.body_text.insert(f"{line_no}.0", new_marker)
        if kind or indent:
            self.body_text.tag_add(
                self._paragraph_tag(self.body_text, kind, indent),
                f"{line_no}.0", f"{line_no}.end")

    @_undo_atom
    def _change_paragraph_indent(self, delta):
        """Push the selected lines one step deeper, or pull them back out --
        any paragraph, not only items; each clamped on its own, so one line
        at the margin does not stop the rest.
        """
        first, last = self._selected_line_range()
        # The lines read once: each pass changes its own line alone.
        lines = self.body_text.get(f"{first}.0", f"{last}.end").split("\n")
        for line_no, line in enumerate(lines, start=first):
            current = self._paragraph_indent_of(self.body_text, line_no, line)
            self._set_paragraph_indent(
                line_no, max(0, min(MAX_INDENT, current + delta)), line)
        self._renumber_lists()
        self._refresh_list_buttons()
        self._schedule_autosave()

    def _cell_at(self, line_no, column):
        """Which cell of this row the given column falls in, and where it is.

        Returns ``(index, start, end)`` for the cell containing *column*, or
        the nearest one when the column sits on a pipe or in the padding.
        None if the line is not a row.
        """
        line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
        bounds = core_tables.cell_bounds(line)
        if not bounds:
            return None
        # `column` arrives as a Tk column (UTF-16 units); `bounds` are
        # Python character offsets. Convert once so an emoji in an earlier
        # cell can't shift which cell the caret is judged to be in.
        column = self._py_col(line, column)
        for i, (start, end) in enumerate(bounds):
            # The cell owns everything up to the pipe that closes it, so a
            # caret sitting in the padding after a short cell counts as being
            # in that cell rather than in nothing.
            closing = line.index(core_tables.CELL, end)
            if column <= closing:
                return i, start, end
        last = len(bounds) - 1
        return last, bounds[last][0], bounds[last][1]

    def _move_to_cell(self, line_no, index):
        """Put the caret at the start of one cell's text, selecting it.

        Selecting is what makes tabbing through a table useful: the next
        thing typed replaces the cell rather than being appended to it,
        which is what every other table does.
        """
        line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
        bounds = core_tables.cell_bounds(line)
        if not bounds or index >= len(bounds):
            return False
        start, end = bounds[index]
        # bounds are Python character offsets; Tk indices count UTF-16
        # units, so an emoji in an earlier cell used to land the caret —
        # and the selection — one place short per emoji.
        tk_start = self._tk_col(line, start)
        tk_end = self._tk_col(line, end)
        self.body_text.tag_remove("sel", "1.0", "end")
        self.body_text.mark_set("insert", f"{line_no}.{tk_start}")
        if end > start:
            self.body_text.tag_add("sel", f"{line_no}.{tk_start}",
                                   f"{line_no}.{tk_end}")
        self.body_text.see("insert")
        return True

    def _tab_in_table(self, delta):
        """Move to the next or previous cell; True if that happened. Past the
        last row a new one is added, as word processors do; backwards from
        the first cell nothing happens rather than leaving the table.
        """
        line_no = int(self.body_text.index("insert").split(".")[0])
        column = int(self.body_text.index("insert").split(".")[1])
        # A rendered table is entered through its grid, not its text.
        rendered = self._table_block_at(line_no)
        if rendered:
            grid = self._grid_at_line(rendered[0])
            if grid is not None:
                if delta > 0 and grid["cells"]:
                    self._open_cell_editor(grid, *sorted(grid["cells"])[0])
                return True
        here = self._cell_at(line_no, column)
        if here is None:
            return False
        index, _start, _end = here
        block = self._table_block_at(line_no)
        if not block:
            return False
        first, last = block
        count = len(core_tables.cell_bounds(
            self.body_text.get(f"{line_no}.0", f"{line_no}.end")))

        if delta > 0:
            if index + 1 < count:
                return self._move_to_cell(line_no, index + 1)
            if line_no < last:
                return self._move_to_cell(line_no + 1, 0)
            # The last cell of the last row: make somewhere to go.
            self.body_text.insert(f"{line_no}.end", "\n"
                                  + core_tables.blank_table(1, count)[0])
            self._align_table_block(line_no)
            self._resync_list_tags()
            return self._move_to_cell(line_no + 1, 0)

        if index > 0:
            return self._move_to_cell(line_no, index - 1)
        if line_no > first:
            above = len(core_tables.cell_bounds(
                self.body_text.get(f"{line_no - 1}.0", f"{line_no - 1}.end")))
            return self._move_to_cell(line_no - 1, above - 1)
        return True

    TABLE_GRID_ROWS = 6
    TABLE_GRID_COLUMNS = 8

    @_undo_atom
    def _insert_table(self, rows, columns):
        """Put a blank table at the caret, on lines of its own.

        A table is lines, so it cannot share one with anything else: a
        newline is added before it when the caret sits in the middle of
        something, and after it so there is somewhere to carry on writing.
        """
        rows = max(1, min(self.TABLE_GRID_ROWS * 4, int(rows)))
        # Never fewer than two columns: is_table_row needs two cells to
        # tell a row from prose containing a pipe, so a one-column table
        # would insert as dead pipe text that never becomes a grid.
        columns = max(2, min(self.TABLE_GRID_COLUMNS, int(columns)))
        line_no = int(self.body_text.index("insert").split(".")[0])
        line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
        # Adjacent pipe rows read as ONE block: an empty line above (and below,
        # by a table) keeps a new table from fusing with its neighbour.
        above = (self.body_text.get(f"{line_no - 1}.0", f"{line_no - 1}.end")
                 if line_no > 1 else "")
        below = self.body_text.get(f"{line_no + 1}.0", f"{line_no + 1}.end")
        before = ("\n" if (line.strip()
                           or core_tables.is_table_row(above)) else "")
        after = "\n" + ("\n" if core_tables.is_table_row(below) else "")
        block = "\n".join(core_tables.blank_table(rows, columns))
        self.body_text.insert("insert", before + block + after)
        first = line_no + (1 if before else 0)
        self._align_table_block(first)
        self._resync_list_tags()
        self._render_table_grids()
        made = self._grid_at_line(first)
        if made is not None and made["cells"]:
            self._open_cell_editor(made, *sorted(made["cells"])[0])
        self._schedule_autosave()
        return first

    def _open_table_size_popup(self):
        """Choose the size by pointing at it, the way a word processor does.

        A grid rather than two number fields: the shape of a table is the
        thing being chosen, and a grid shows it. Reuses the same anchored
        mini-popup the colour swatches use.
        """
        self._dismiss_mini_popup()
        popup = tk.Toplevel(self)
        self._mini_popup = popup
        popup.wm_overrideredirect(True)
        popup.configure(bg=self.colors["accent"])
        outer = tk.Frame(popup, bg=self.colors["card"], padx=1, pady=1)
        outer.pack()
        body = tk.Frame(outer, bg=self.colors["card"])
        body.pack()

        caption = tk.Label(body, text="Insert table", font=("Segoe UI", 10, "bold"),
                           bg=self.colors["card"], fg=self.colors["text"])
        caption.pack(padx=15, pady=(12, 6))

        grid = tk.Frame(body, bg=self.colors["card"])
        grid.pack(padx=15)
        cells = {}

        def highlight(rows, columns):
            for (r, c), cell in cells.items():
                inside = r <= rows and c <= columns
                cell.configure(bg=self.colors["accent"] if inside
                               else inset_surface(self.colors))
            caption.configure(text=f"{rows} x {columns} table")

        def leave(_event=None):
            highlight(0, 0)
            caption.configure(text="Insert table")

        # Columns start at two: a one-column run of pipes is not
        # recognisable as a table row (| x | in prose would be one), so
        # the picker never offers a shape that cannot exist.
        for r in range(1, self.TABLE_GRID_ROWS + 1):
            for c in range(2, self.TABLE_GRID_COLUMNS + 1):
                cell = tk.Frame(grid, width=self.px(14), height=self.px(14),
                                cursor="hand2",
                                bg=inset_surface(self.colors))
                cell.grid(row=r, column=c, padx=1, pady=1)
                cell.bind("<Enter>", lambda e, r=r, c=c: highlight(r, c))
                # "break": this destroys the popup the cell is in (see
                # _show_inline_rename).
                cell.bind("<Button-1>", lambda e, r=r, c=c: (
                    self._dismiss_mini_popup(), self._insert_table(r, c),
                    "break")[2])
                # From the keyboard the shape follows the keyboard, as it
                # follows the pointer: that block is where the keyboard is.
                self._pressable(cell, lambda r=r, c=c: (
                    self._dismiss_mini_popup(), self._insert_table(r, c)),
                    walk=True)
                cell.bind("<FocusIn>", lambda e, r=r, c=c: highlight(r, c))
                cells[(r, c)] = cell
        grid.bind("<Leave>", leave)

        hint = tk.Label(body, text="Tab moves between cells",
                        font=("Segoe UI", 8), bg=self.colors["card"],
                        fg=self.colors["subtext"])
        hint.pack(padx=15, pady=(6, 12))

        self._place_mini_popup(popup, self.table_btn)
        return popup

    def _on_body_tab(self, event, delta):
        """Tab and Shift+Tab move between table cells, or change list depth;
        in prose Tab types a tab (None, to Tk), and Shift+Tab stops here
        rather than leave the editor. Ctrl+Tab and Ctrl+Shift+Tab, matched
        to these bindings first, leave the note as the shortcuts page says.
        """
        if getattr(event, "state", 0) & 0x4:      # Control held
            return self._leave_note_by_keys(delta)
        if self._tab_in_table(delta):
            return "break"
        first, last = self._selected_line_range()
        # The selected lines in one read, not one a line (final audit, round 10).
        lines = self.body_text.get(f"{first}.0", f"{last}.end").split("\n")
        in_list = any(parse_list_marker(line)[0] for line in lines)
        if not in_list:
            return "break" if delta < 0 else None
        self._change_paragraph_indent(delta)
        return "break"

    def _leave_note_by_keys(self, delta):
        """Ctrl+Tab (*delta* 1) or Ctrl+Shift+Tab: the keyboard to the control
        after or before the note's text, by Tk's own Tab traversal -- so what
        it lands on is ringed and scrolled into sight as after any Tab
        (_tab_target_into_sight). Focus set by hand skipped both."""
        self.body_text.event_generate(
            "<<NextWindow>>" if delta > 0 else "<<PrevWindow>>")
        return "break"

    def _selected_line_range(self):
        """The line numbers the cursor or selection covers."""
        try:
            first = int(self.body_text.index("sel.first").split(".")[0])
            last = int(self.body_text.index("sel.last").split(".")[0])
        except tk.TclError:
            first = last = int(self.body_text.index("insert").split(".")[0])
        return first, last

    @_undo_atom
    def _toggle_list(self, kind):
        """Turn the selected lines into a list, or back into plain lines.

        Toggling off is deliberate: pressing the same button twice should undo
        itself rather than stack a second marker onto the line.
        """
        # A table is not a list (a marker dissolved the grid): with cells
        # selected the buttons decline, and table lines are left out below.
        if getattr(self, "_grid_sel", None) is not None:
            self.set_status("A table cannot be a list")
            return
        first, last = self._selected_line_range()
        # The lines read once, not four times a line: each pass below
        # changes its own line alone (final audit, round 10).
        texts = self.body_text.get(f"{first}.0", f"{last}.end").split("\n")

        def blank(line_no):
            line = texts[line_no - first]
            return (core_tables.is_table_row(line)
                    or not parse_list_marker(line)[2].strip())

        # An empty line is no item (a list read 1, 3, 5); still visited when
        # turning a list off, as one may carry an older marker.
        items = [n for n in range(first, last + 1) if not blank(n)]
        if not items:
            if first != last or core_tables.is_table_row(texts[0]):
                return
            # A single empty line is not a gap between items -- it is the
            # user asking to START a list here, marker first, text after.
            items = [first]
        turning_off = all(self._list_kind_of(self.body_text, n, texts[n - first]) == kind
                          for n in items)
        for line_no in range(first, last + 1):
            if not turning_off and line_no not in items:
                continue
            line = texts[line_no - first]
            existing, marker, rest = parse_list_marker(line)
            # Depth is read before the tags go, and put back after: turning a
            # nested item into a bullet should leave it where it sits rather
            # than snapping it back to the left margin.
            indent = self._paragraph_indent_of(self.body_text, line_no, line)
            if marker:
                self.body_text.delete(f"{line_no}.0", f"{line_no}.0+{len(marker)}c")
            self._clear_paragraph_tags(self.body_text, line_no)
            if turning_off:
                if indent:
                    self.body_text.tag_add(
                        self._paragraph_tag(self.body_text, None, indent),
                        f"{line_no}.0", f"{line_no}.end")
                continue
            self.body_text.insert(f"{line_no}.0", marker_for(kind, 1, indent))
            # Stops at .end, deliberately: a tag that covered the newline
            # too would be inherited by whatever gets typed or pasted on
            # the next line.
            self.body_text.tag_add(
                self._paragraph_tag(self.body_text, kind, indent),
                f"{line_no}.0", f"{line_no}.end")
        self._renumber_lists()
        self._refresh_list_buttons()
        self._schedule_autosave()
        self.update_word_count()

    def _renumber_lists(self):
        """Make every numbered run read 1, 2, 3 again after any change,
        writing only the markers' changed characters (the arithmetic is in
        core/formatting.py), so styles, view and tables stay put (ISSUES_LOG:
        "The list that rewrote the whole note").
        """
        b = self.body_text
        body = b.get("1.0", "end-1c")
        new_body, _shifts = renumber(body, self._extract_paragraphs(b, body))
        if new_body == body:
            return
        # Several edits, one Ctrl+Z; after the no-change return, so a
        # keystroke that renumbers nothing leaves typing's undo untouched.
        self._undo_atom_begin()
        # A caret at a marker's start stays there rather than ride past it.
        gravity = b.mark_gravity("insert")
        b.mark_gravity("insert", "left")
        try:
            for n, (old, new) in enumerate(
                    zip(body.split("\n"), new_body.split("\n")), start=1):
                if old == new:
                    continue
                p, room = 0, min(len(old), len(new))
                while p < room and old[p] == new[p]:
                    p += 1
                s = 0
                while s < room - p and old[-1 - s] == new[-1 - s]:
                    s += 1
                at = f"{n}.{self._tk_col(old, p)}"
                # Every tag of the character replaced, the selection's
                # included: a selection across the list stays one piece.
                tags = tuple(b.tag_names(at))
                b.delete(at, f"{n}.{self._tk_col(old, len(old) - s)}")
                b.insert(at, new[p:len(new) - s], tags)
        finally:
            b.mark_gravity("insert", gravity)
            self._undo_atom_end()

    def _on_body_return(self, event):
        """Enter inside a list continues it, or ends it on an empty item.

        Pressing Enter on an item you have not typed anything into is how
        people leave a list, so that removes the marker instead of adding
        another one.
        """
        # A specific binding beats the general <KeyPress> the caret guard
        # rides on, so Enter beside a table used to write into the hidden
        # text and surface the caret at the table's right edge.
        self._caret_out_of_hidden()
        line_no = int(self.body_text.index("insert").split(".")[0])
        # A note BEGINNING with a table: Enter at the start of the line below
        # it pushes the table down, the caret on the fresh first line.
        first_block = (self._table_block_at(1)
                       if is_table_row(self.body_text.get("1.0", "1.end"))
                       else None)
        if (first_block is not None
                and line_no == first_block[1] + 1
                and self.body_text.index("insert") == f"{line_no}.0"
                # ...unless a SECOND table follows right after: Enter on
                # the separating line then means space between tables,
                # as it always did.
                and not is_table_row(self.body_text.get(
                    f"{line_no + 1}.0", f"{line_no + 1}.end"))):
            # No snapshot: at line 1 the Text keeps the view itself, and one
            # restored on guessed grid heights yanked it nine lines up.
            self._teardown_table_grids()
            self.body_text.insert("1.0", "\n")
            self.body_text.mark_set("insert", "1.0")
            # The table moved under the caret; the caret did not leave it,
            # as the paste's rule says (_on_body_paste). ISSUES_LOG,
            # smaller lessons: the push-down's caret line.
            self._last_caret_line = 1
            self._resync_list_tags()
            self._render_table_grids()
            self._schedule_autosave()
            return "break"
        if _selection_holds_caret(self.body_text):
            return self._list_return_over_selection()
        kind = self._list_kind_of(self.body_text, line_no)
        if not kind:
            return None
        return self._continue_list(line_no, kind)

    def _list_return_over_selection(self):
        """Enter with words selected on a list line: the selection deleted
        first, as Tk's Enter would (the new item was cut into it), then the
        list goes on, one Ctrl+Z. All an item's words selected keeps its
        marker, the new item under it.
        """
        b = self.body_text
        line_no = int(b.index("sel.first").split(".")[0])
        if not self._list_kind_of(b, line_no):
            return None
        self._undo_atom_begin()
        try:
            first = b.index("sel.first")
            b.delete("sel.first", "sel.last")
            b.mark_set("insert", first)
            # A selection over several lines leaves pieces of their tags.
            self._resync_list_tags(line_no)
            kind = self._list_kind_of(b, line_no)
            if kind:
                return self._continue_list(line_no, kind, leave_if_empty=False)
            # The marker went with the words: a plain line break, Tk's own.
            b.insert("insert", "\n")
            self._resync_list_tags(line_no + 1)
            self._renumber_lists()
            b.see("insert")
            self._schedule_autosave()
            return "break"
        finally:
            self._undo_atom_end()

    def _continue_list(self, line_no, kind, leave_if_empty=True):
        """Enter on list line *line_no*: a new item, or -- on an item with
        no words, unless *leave_if_empty* is False -- out of the list."""
        line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
        _, marker, rest = parse_list_marker(line)
        indent = self._paragraph_indent_of(self.body_text, line_no)
        if leave_if_empty and not rest.strip():
            # An empty nested item steps out one level first, climbing out as
            # other editors do rather than dropping to a paragraph.
            if indent:
                self._set_paragraph_indent(line_no, indent - 1)
                self._renumber_lists()
                return "break"
            self.body_text.delete(f"{line_no}.0", f"{line_no}.end")
            self._clear_paragraph_tags(self.body_text, line_no)
            self._renumber_lists()
            return "break"
        # Before the marker's end (Home, then Enter) the new marker went in
        # front of the old one: "• • milk". From its end the same Enter
        # leaves an empty item above, the words below, as Word does.
        col = int(self.body_text.index("insert").split(".")[1])
        if col < len(marker):
            self.body_text.mark_set("insert", f"{line_no}.{len(marker)}")
        self.body_text.insert("insert", "\n" + marker_for(kind, 1, indent))
        new_line = line_no + 1
        self.body_text.tag_add(
            self._paragraph_tag(self.body_text, kind, indent),
            f"{new_line}.0", f"{new_line}.end")
        self._renumber_lists()
        # Tk's own Enter keeps the new line in sight; this one replaces it.
        self.body_text.see("insert")
        self._schedule_autosave()
        return "break"

    def _on_body_delete_key(self, event=None):
        """Delete (and BackSpace) with cells selected clears them, as a
        spreadsheet does. Without, Delete at the end of the line above a
        drawn table does nothing (_deletion_joins_table); BackSpace asks
        about its own direction in _on_body_backspace."""
        sel = getattr(self, "_grid_sel", None)
        if sel is not None and self._grid_first_line(sel["info"]) is not None:
            self._grid_fill_selection(sel, "")
            return "break"
        if self._deletion_joins_table(True):
            return "break"
        return None

    def _on_body_backspace(self, event):
        """Backspace just after a marker removes the marker, not a character.

        Otherwise the only way out of a list is to delete the bullet one
        character at a time, which reads as the app fighting you.
        """
        sel = getattr(self, "_grid_sel", None)
        if sel is not None and self._grid_first_line(sel["info"]) is not None:
            return self._on_body_delete_key(event)
        self._caret_out_of_hidden()
        # At the start of the line under a drawn table, the character
        # before the caret is the table's own line break: nothing to take.
        if self._deletion_joins_table(False):
            return "break"
        # Words selected: Tk deletes them, as everywhere else. The marker
        # shortcut below asked only where the caret stood, so a selection
        # ending just after a marker lost the marker and kept the words.
        if _selection_holds_caret(self.body_text):
            return None
        index = self.body_text.index("insert")
        line_no, col = (int(p) for p in index.split("."))
        kind = self._list_kind_of(self.body_text, line_no)
        if not kind:
            return None
        line = self.body_text.get(f"{line_no}.0", f"{line_no}.end")
        _, marker, _rest = parse_list_marker(line)
        if not marker or col != len(marker):
            return None
        # Nested, BackSpace at the marker climbs out a level, removing it only
        # at the margin, or the text was stranded at a depth.
        indent = self._paragraph_indent_of(self.body_text, line_no)
        # One unit with the renumbering it causes: apart, Ctrl+Z took back
        # the new numbers first and left the marker gone.
        self._undo_atom_begin()
        try:
            if indent:
                self._set_paragraph_indent(line_no, indent - 1)
                self._renumber_lists()
                self._refresh_list_buttons()
                self._schedule_autosave()
                return "break"
            self.body_text.delete(f"{line_no}.0", f"{line_no}.0+{len(marker)}c")
            for tag in ("list_bullet", "list_number"):
                self.body_text.tag_remove(tag, f"{line_no}.0", f"{line_no}.end+1c")
            self._renumber_lists()
        finally:
            self._undo_atom_end()
        self._schedule_autosave()
        return "break"

    def _list_aware_delete(self, event=None, virtual=None):
        """Tk's own deletes, when they reach a list: done as list_deletion_range
        says, then renumbered, one Ctrl+Z ("2. two3. three" left to Tk). In
        the styled-delete bindtag, so it sees every deleting key and virtual
        cut or clear first; cells, a drawn table, BackSpace after a marker,
        Enter and Tab over a selection and pastes are their own handlers'.
        """
        b = self.body_text
        self._lines_before_key = int(b.index("end-1c").split(".")[0])
        if getattr(self, "_grid_sel", None) is not None:
            return None
        holds = _selection_holds_caret(b)
        keysym = getattr(event, "keysym", "") if virtual is None else ""
        state = getattr(event, "state", 0) if virtual is None else 0
        if not isinstance(state, int):
            state = 0
        control, alt = bool(state & 0x4), bool(state & 0x20000)
        char = (getattr(event, "char", "") or "") if virtual is None else ""
        typing = False
        try:
            if virtual is not None:
                if not b.tag_ranges("sel"):
                    return None
                doomed = (b.index("sel.first"), b.index("sel.last"))
            elif keysym in ("BackSpace", "Delete") and holds:
                doomed = (b.index("sel.first"), b.index("sel.last"))
            elif keysym == "Delete":
                doomed = (None if b.compare("insert", ">=", "end-1c")
                          else (b.index("insert"), b.index("insert+1c")))
            elif keysym == "BackSpace" or (control and not alt and keysym == "h"):
                ln, col = (int(p) for p in b.index("insert").split("."))
                marker = parse_list_marker(b.get(f"{ln}.0", f"{ln}.end"))[1]
                if keysym == "BackSpace" and marker and col == len(marker):
                    # BackSpace just after a marker is the body's own: it
                    # climbs a nested item out a level first.
                    return None
                doomed = (None if b.compare("insert", "==", "1.0")
                          else (b.index("insert-1c"), b.index("insert")))
            elif control and not alt and keysym == "k":
                doomed = self._tk_control_delete_range("k")[0]
            elif holds and char and char.isprintable() and (not control or alt):
                doomed, typing = (b.index("sel.first"), b.index("sel.last")), True
            else:
                return None
        except tk.TclError:
            return None
        if not doomed:
            return None
        span = self._list_range_for(doomed, typing)
        if span is None:
            return None
        start, end = span
        self._undo_atom_begin()
        try:
            if virtual == "cut":
                # What Tk's own Cut puts on the clipboard: the selection.
                b.clipboard_clear()
                b.clipboard_append(b.get("sel.first", "sel.last"))
            b.tag_remove("sel", "1.0", "end")
            if b.compare(start, "<", end):
                b.delete(start, end)
            b.mark_set("insert", start)
            if typing:
                # Typed here, in the same unit, as Tk's own typing over a
                # selection is one Ctrl+Z; the marks first, so the letter
                # is settled as typing (_note_typing_key).
                self._note_typing_key(event)
                b.insert("insert", char)
            self._resync_list_tags(int(start.split(".")[0]))
            self._renumber_lists()
            b.see("insert")
        finally:
            self._undo_atom_end()
        # Renumbered already: the net at the key's release has nothing to do.
        self._lines_before_key = None
        self._schedule_autosave()
        self.update_word_count()
        return "break"

    def _list_range_for(self, doomed, typing, pasted=None):
        """The body's ``(start, end)`` to delete instead of *doomed* when it
        reaches a list (core/formatting's list_deletion_range; *pasted*, what
        a paste brings), or None: no list reached, or a table's row among
        its lines, which the table's own guards answer for."""
        b = self.body_text
        (l1, t1), (l2, t2) = (tuple(int(p) for p in b.index(i).split("."))
                              for i in doomed)
        lines = b.get(f"{l1}.0", f"{l2}.end").split("\n")
        if any(is_table_row(line) for line in lines):
            return None
        plan = list_deletion_range(
            lines, (0, self._py_col(lines[0], t1)),
            (l2 - l1, self._py_col(lines[-1], t2)), typing=typing, pasted=pasted)
        if plan is None:
            return None
        (p1, q1), (p2, q2) = plan
        return (f"{l1 + p1}.{self._tk_col(lines[p1], q1)}",
                f"{l1 + p2}.{self._tk_col(lines[p2], q2)}")

    def _delete_selection_reaching_list(self, pasted=None):
        """For *pasted*, text about to take the selection's place, the
        selection deleted as typing over it is, when it reaches a list: the
        next item keeps its number, and no marker lands among the words.
        True when it did, the caret then where the text goes; the caller
        renumbers once the text is in."""
        b = self.body_text
        if getattr(self, "_grid_sel", None) is not None or not b.tag_ranges("sel"):
            return False
        span = self._list_range_for((b.index("sel.first"), b.index("sel.last")), True, pasted)
        if span is None:
            return False
        start, end = span
        b.tag_remove("sel", "1.0", "end")
        if b.compare(start, "<", end):
            b.delete(start, end)
        b.mark_set("insert", start)
        return True

    def _paste_brings(self):
        """The text Ctrl+V is about to put in, read as its routes read the
        clipboard, and whether the rich route takes it; (None, False) for no
        text. Off the plain text alone, a line break the rich route drops
        took the next item's ("2. Hello world3. three")."""
        markup = clipboard.read_html()
        if markup:
            cut = {}
            text, spans, paragraphs = html_to_note(markup, report=cut)
            mine = getattr(self, "_formatted_clip", None)
            if mine and not any(cut.values()) and markup == mine[3]:
                return mine[0], True
            if text:
                return (text if spans or paragraphs else reflow_wrapped(text)), True
        try:
            return self.body_text.clipboard_get(), False
        except tk.TclError:
            return None, False

    def _paste_reaching_list(self):
        """Ctrl+V over a selection that reaches a list, as one unit: the
        selection deleted as _delete_selection_reaching_list says, then the
        paste -- the app's own (_on_body_paste) or, where that leaves it to
        Tk, the clipboard's text as Tk's own paste puts it in -- and the
        lists renumbered. Left to Tk, "zz" over items 2 and 3 gave
        "zz4. four". With nothing selected, _paste_at_marker."""
        b = self.body_text
        if getattr(self, "_grid_sel", None) is not None:
            return None
        if not b.tag_ranges("sel"):
            return self._paste_at_marker()
        sel = (b.index("sel.first"), b.index("sel.last"))
        # Begun at an item's marker, the selection is the list's even within
        # its line: a paste bringing its own marker takes that one's place.
        kind, marker, _ = parse_list_marker(b.get(f"{sel[0]} linestart", f"{sel[0]} lineend"))
        at_marker = bool(kind) and len(b.get(f"{sel[0]} linestart", sel[0])) <= len(marker)
        if self._list_range_for(sel, True) is None and not at_marker:
            return None
        brings, rich = self._paste_brings()
        if not brings:
            # Nothing to paste -- a picture, a file: the selection stays, as
            # under Tk's own paste (the lows wave's verification, round 7).
            return "break"
        # A table route's paste keeps the typing rule; any other's first line
        # goes in first, marker and all (rows kept it: "2. 3. three").
        pasted = None if (("\t" in brings and not rich)
                          or is_table_row(brings.split("\n", 1)[0])) else brings
        if self._list_range_for(sel, True, pasted) is None:
            return None
        self._undo_atom_begin()
        try:
            self._delete_selection_reaching_list(pasted)
            self._paste_renumbered()
        finally:
            self._undo_atom_end()
        self._schedule_autosave()
        self.update_word_count()
        return "break"

    def _paste_renumbered(self, then=None):
        """The paste made at the caret -- the app's own (_on_body_paste) or,
        where that leaves it to Tk, the clipboard's text as Tk's own paste
        puts it in -- *then* run, and the lists renumbered: inside the
        caller's unit."""
        b = self.body_text
        if self._on_body_paste() != "break":
            try:
                text, cut = self._cap_paste(b.clipboard_get())
                b.insert("insert", text)
                if cut:
                    self._say_if_paste_was_cut({"text_cut": True}, in_body=True)
            except tk.TclError:
                pass
        if then is not None:
            then()
        self._resync_list_tags()
        self._renumber_lists()
        b.see("insert")

    def _paste_at_marker(self):
        """Ctrl+V with nothing selected at an item's marker end -- where Enter
        in a list leaves the caret -- of a paste bringing its own marker: the
        item's marker stays and the paste's goes, so the line keeps its tags
        and its depth; with words after the caret and a line break of its own,
        the paste goes in before the item. Kept, a copied item pasted into a
        new one read "3. 1. Kiwi" (the lows wave's verification, round 8)."""
        b = self.body_text
        kind, marker, rest = parse_list_marker(b.get("insert linestart", "insert lineend"))
        if not kind or len(b.get("insert linestart", "insert")) != len(marker):
            return None
        brings, rich = self._paste_brings()
        head = (brings or "").split("\n", 1)[0]
        own = parse_list_marker(head)[1]
        if not own or ("\t" in brings and not rich) or is_table_row(head):
            return None
        at = b.index("insert")
        depth = self._paragraph_indent_of(b, int(at.split(".")[0]))
        # Carried through the paste's own renumbering, which can change the
        # item's marker's length ("10." to "3.").
        b.mark_set("marker_paste", at)
        b.mark_gravity("marker_paste", "left")

        def keep_item():
            # The item keeps its marker, its kind and its depth, as Word
            # keeps a paragraph's list when a paste brings no paragraph mark:
            # the paste's own marker goes (round 9).
            where = b.index("marker_paste")
            if b.get(where, f"{where}+{len(own)}c") == own:
                b.delete(where, f"{where}+{len(own)}c")
            self._set_paragraph_indent(int(where.split(".")[0]), depth)

        before = bool(rest.strip()) and brings.endswith("\n")
        self._undo_atom_begin()
        try:
            if before:
                b.mark_set("insert", f"{at} linestart")
            self._paste_renumbered(None if before else keep_item)
        finally:
            b.mark_unset("marker_paste")
            self._undo_atom_end()
        self._schedule_autosave()
        self.update_word_count()
        return "break"

    def _on_styled_virtual(self, event, name):
        """Cut, Clear and Paste in the styled-delete bindtag: the key noted;
        a cut or clear reaching a list done as _list_aware_delete says, a
        paste over one as _paste_reaching_list does; anything else's
        formatting noted for Ctrl+Z (_note_styled_delete). A cut carries its
        formatting (_cut_formatted)."""
        self._note_key_down()
        if name == "cut" and self._cut_formatted(event) == "break":
            return "break"
        if name and self._list_aware_delete(event, virtual=name) == "break":
            return "break"
        if name is None and self._paste_reaching_list() == "break":
            return "break"
        return self._note_styled_delete(event, virtual=True)

    def _renumber_if_lines_fell(self, _event=None):
        """A key that took away lines renumbers what follows, whatever took
        them (Tk's own Ctrl+K at a line's end, a key bound nowhere here):
        the routes _list_aware_delete knows end lists well, and this is the
        net under the rest. Only when lines fell, so typing costs nothing."""
        before = getattr(self, "_lines_before_key", None)
        if before is None:
            return
        self._lines_before_key = None
        if int(self.body_text.index("end-1c").split(".")[0]) < before:
            self._renumber_lists()

    def _renumber_after_paste(self, _event=None):
        """Tk's own paste over a selection -- the plain path _on_body_paste
        falls through to -- joins lines like any delete; renumber once it
        has run. The rich path returned "break" and renumbered itself."""
        self.after_idle(self._renumber_lists)

    def _setup_body_formatting_tags(self, text_widget):
        """Define the Tkinter tags the formatting toolbar/menu apply. Font
        objects are kept on self so they aren't garbage-collected (Tkinter
        needs a live Python reference to keep using them)."""
        base = tkfont.Font(font=text_widget["font"])
        family, size = base.actual("family"), base.actual("size")
        # Kept for the composite font tags: a span that sets only a size
        # still needs a family to build a Font from, and vice versa.
        self._body_base_family, self._body_base_size = family, size
        # Live references to those tags' Font objects, keyed by tag name.
        # Tkinter drops a font nothing holds, and the tag then silently
        # stops applying -- the same reason the three below sit on self.
        self._font_tag_fonts = {}
        self._fmt_bold_font = tkfont.Font(family=family, size=size, weight="bold")
        self._fmt_italic_font = tkfont.Font(family=family, size=size, slant="italic")
        self._fmt_bold_italic_font = tkfont.Font(
            family=family, size=size, weight="bold", slant="italic")
        text_widget.tag_configure("bold", font=self._fmt_bold_font)
        text_widget.tag_configure("italic", font=self._fmt_italic_font)
        text_widget.tag_configure("bold_italic", font=self._fmt_bold_italic_font)
        text_widget.tag_configure("underline", underline=True)
        text_widget.tag_configure("strike", overstrike=True)
        # Find's highlights: background ONLY, names no saved style has, blended
        # from the palette (apply_theme re-tints them).
        self._retint_find_tags(text_widget)
        # A later tag paints over "sel", and selected highlighted text looked
        # unselected: raised, as _ensure_color_tag raises it again.
        text_widget.tag_raise("sel")

    @staticmethod
    def _char_offset(w, index):
        # PYTHON characters, the saved body's: count("chars") gives UTF-16
        # units, and each emoji shifted a span one right, re-saved at every
        # start. Both skip a drawn table's window character.
        return len(w.get("1.0", index))


    @classmethod
    def _char_class(cls, ch):
        """Which of three classes a character belongs to (see core.formatting)."""
        return core_char_class(ch)

    @staticmethod
    def _color_tag_name(style, hex_color):
        return core_color_tag_name(style, hex_color)

    def _ensure_color_tag(self, text_widget, style, hex_color):
        tag = self._color_tag_name(style, hex_color)
        if style == "text_color":
            text_widget.tag_configure(tag, foreground=hex_color)
        else:
            # The saved colour stays pure (in the tag's NAME); the paint blends
            # toward the page, as the cells do (_retint_highlight_tags).
            text_widget.tag_configure(tag, background=self._blend_hex(
                hex_color, self.colors["card"], 0.45))
        # A new tag would bury "sel" (see _setup_body_formatting_tags).
        text_widget.tag_raise("sel")
        # Same trap for the find highlights: a colour applied from the
        # toolbar fires no KeyRelease, so the edit-rescan that normally
        # re-raises them wouldn't run. Lift them back over the new tag now.
        if getattr(self, "_find_open", False) and text_widget is getattr(self, "body_text", None):
            self._find_raise_tags()
        return tag

    def _retint_highlight_tags(self, text_widget):
        """Re-blend every highlight tag's paint toward the CURRENT
        theme's surface. The tag names carry the pure colour, so the
        stored data never changes -- only the ink follows the theme."""
        for tag in text_widget.tag_names():
            if tag.startswith("highlight_"):
                try:
                    text_widget.tag_configure(
                        tag, background=self._blend_hex(
                            "#" + tag[len("highlight_"):],
                            self.colors["card"], 0.45))
                except (tk.TclError, ValueError):
                    pass

    @staticmethod
    def _tag_add_no_newline(text_widget, tag, start, end):
        """tag_add over [start, end), per line, never over a line's newline:
        a background over it painted a full-width bar past the words.
        """
        first = int(str(text_widget.index(start)).split(".")[0])
        last = int(str(text_widget.index(end)).split(".")[0])
        for line in range(first, last + 1):
            seg_start = start if line == first else f"{line}.0"
            seg_end = end if line == last else f"{line}.end"
            if text_widget.compare(seg_start, "<", seg_end):
                text_widget.tag_add(tag, seg_start, seg_end)

    def _ensure_font_tag(self, text_widget, is_bold, is_italic, size, family):
        """The tag carrying one whole font combination, made on demand (all
        192 cost 193 ms at start), its Font held on self -- collected, the
        tag quietly stops applying.
        """
        name = core_font_tag_for(is_bold, is_italic, size, family)
        if name is None or name in KNOWN_FORMAT_STYLES:
            return name          # plain bold/italic/bold_italic, set up already
        if name not in self._font_tag_fonts:
            self._font_tag_fonts[name] = tkfont.Font(
                family=family or self._body_base_family,
                size=size or self._body_base_size,
                weight="bold" if is_bold else "normal",
                slant="italic" if is_italic else "roman",
            )
            # Configured now, so it lands later in Tk's tag order than bold
            # and italic and therefore wins the font option -- which is the
            # whole point, since those two set it as well.
            text_widget.tag_configure(name, font=self._font_tag_fonts[name])
        return name

    def _apply_font_runs(self, text_widget, spans):
        """Lay composite font tags over the ranges that need one.

        Runs alongside the plain style tags rather than instead of them: a
        bold run inside a resized paragraph keeps its "bold" tag, which is
        what the toolbar reads, while the composite on top decides what the
        text actually looks like.
        """
        # No size and no font, no run (resolve_font_runs): nor a read of the
        # whole text for its length, at every opening of a styled note.
        if not any(span["style"] in FONT_VALUE_STYLES
                   for span in normalize_formatting(spans)):
            return
        length = len(text_widget.get("1.0", "end-1c"))
        runs = resolve_font_runs(spans, length)
        where = self._offset_indices(
            text_widget, [offset for run in runs for offset in run[:2]])
        for start, end, is_bold, is_italic, size, family in runs:
            tag = self._ensure_font_tag(text_widget, is_bold, is_italic,
                                        size, family)
            if not tag:
                continue
            try:
                text_widget.tag_add(tag, where[start], where[end])
            except tk.TclError:
                pass

    def _set_weight_by_stretch(self, ranges, style, on):
        """Bold or italic (*style*) turned *on* or off over *ranges*, each
        stretch keeping its own other one (Ctrl+B over "one *two* three"
        leaves "two" italic) -- by stretches, as _fit_font_tags goes, which
        gives a stretch under a size or font the composite it now needs."""
        b = self.body_text
        for start, end in ranges:
            start, end = b.index(start), b.index(end)
            points = [start]
            for _key, tag, index in b.dump(start, end, tag=True):
                if tag in self._FONT_STYLES and b.compare(index, ">", points[-1]):
                    points.append(index)
            if b.compare(points[-1], "<", end):
                points.append(end)
            for lo, hi in zip(points, points[1:]):
                plain = [t for t in b.tag_names(lo) if t in self._FONT_STYLES]
                is_bold = "bold" in plain or "bold_italic" in plain
                is_italic = "italic" in plain or "bold_italic" in plain
                if style == "bold":
                    is_bold = on
                else:
                    is_italic = on
                for t in plain:
                    b.tag_remove(t, lo, hi)
                tag = self._font_tag_for(is_bold, is_italic)
                if tag:
                    b.tag_add(tag, lo, hi)
            self._fit_font_tags(start, end)

    def _fit_font_tags(self, start, end, like=None, size=None, family=None):
        """Give the characters from *start* to *end*, just typed or pasted,
        the composite font tag their bold and italic call for, with the size
        and family they wear or *like*'s (the character typed onto); a
        *size* or *family* picked before typing replaces that one. Bold and
        italic over the same letters become bold_italic, as the two do not
        compose. By stretches, not a character at a time (2-3x slower)."""
        b = self.body_text
        source = None
        if like is not None:
            source = next((parse_font_tag(t) for t in b.tag_names(like)
                           if parse_font_tag(t)), None)
        start, end = b.index(start), b.index(end)
        if not b.compare(start, "<", end):
            return
        # In the order the text holds them, so the stretches come out in it.
        points = [start]
        for _key, tag, index in b.dump(start, end, tag=True):
            if ((tag in self._FONT_STYLES or parse_font_tag(tag))
                    and index != points[-1]):
                points.append(index)
        if points[-1] != end:
            points.append(end)
        for lo, hi in zip(points, points[1:]):
            names = b.tag_names(lo)
            plain = [t for t in names if t in self._FONT_STYLES]
            is_bold = "bold" in plain or "bold_italic" in plain
            is_italic = "italic" in plain or "bold_italic" in plain
            one = self._font_tag_for(is_bold, is_italic)
            if plain != ([one] if one else []):
                for t in plain:
                    if t != one:
                        b.tag_remove(t, lo, hi)
                if one:
                    b.tag_add(one, lo, hi)
            worn = [t for t in names if parse_font_tag(t)]
            # The last wears the highest priority: the one Tk draws.
            found = parse_font_tag(worn[-1]) if worn else source
            if found is None and (size is not None or family is not None):
                found = (False, False, None, None)
            if found is None:
                continue
            tag = self._ensure_font_tag(
                b, is_bold, is_italic,
                size if size is not None else found[2],
                family if family is not None else found[3])
            for t in worn:
                if t != tag:
                    b.tag_remove(t, lo, hi)
            if tag and parse_font_tag(tag):
                b.tag_add(tag, lo, hi)

    @staticmethod
    def _char_offsets(text_widget, indices, text=None):
        """What :meth:`_char_offset` answers -- ``len(get("1.0", index))`` --
        for many indices, counted in Python on *text*, the widget's
        ``get("1.0", "end-1c")`` (read here when not given). A get per index
        paid Tk's cost for every toggle on its line each time (final audit,
        round 10). A column counts UTF-16 units and a window as one, so a
        line holding either is walked once, for all its indices."""
        wanted = {str(index) for index in indices}
        if not wanted:
            return {}
        if text is None:
            text = text_widget.get("1.0", "end-1c")
        lines = text.split("\n")
        starts = [0]
        for line in lines:
            starts.append(starts[-1] + len(line) + 1)
        by_line = {}
        for index in wanted:
            line_no, column = _index_key(index)
            by_line.setdefault(line_no, []).append((column, index))
        windows = {}
        if any(line_no <= len(lines) for line_no in by_line):
            for _kind, _name, at in text_widget.dump("1.0", "end", window=True,
                                                     image=True):
                line_no, column = _index_key(at)
                windows.setdefault(line_no, []).append(column)
        offsets = {}
        for line_no, asked in by_line.items():
            if line_no > len(lines):
                # Past the last line is "end": the note and Tk's own newline.
                for _column, index in asked:
                    offsets[index] = starts[-1]
                continue
            line, base = lines[line_no - 1], starts[line_no - 1]
            held = sorted(windows.get(line_no, ()))
            if not held and len(line.encode("utf-16-le", "surrogatepass")) == 2 * len(line):
                for column, index in asked:
                    offsets[index] = base + min(column, len(line))
                continue
            unit = at = window = 0
            for column, index in sorted(asked):
                while True:
                    if window < len(held) and held[window] == unit:
                        if unit >= column:
                            break
                        unit, window = unit + 1, window + 1
                        continue
                    if unit >= column or at >= len(line):
                        break
                    unit += 2 if ord(line[at]) > 0xFFFF else 1
                    at += 1
                offsets[index] = base + at
        return offsets

    @staticmethod
    def _offset_indices(text_widget, offsets):
        """The way back from :meth:`_char_offsets`: {offset: Tk index} for
        many saved offsets, in one walk, each reached from the one before
        ("1.0+Nc" each froze Enter for 3.6 s). A saved offset skips a drawn
        table's window and "+Nc" counts it, so the windows a hop passes are
        hopped again; at a window, the index stands before it.
        """
        wanted = sorted(set(offsets))
        if not wanted:
            return {}

        def position(index):
            line, _, column = str(index).partition(".")
            return int(line), int(column)

        windows = sorted(position(index) for _kind, _name, index
                         in text_widget.dump("1.0", "end", window=True,
                                             image=True))
        out, here, at = {}, "1.0", 0
        for offset in wanted:
            need = offset - at
            while need > 0:
                there = text_widget.index(f"{here}+{need}c")
                # Each window passed was counted as a character.
                need = (bisect.bisect_left(windows, position(there))
                        - bisect.bisect_left(windows, position(here)))
                here = there
            at = offset
            out[offset] = here
        return out

    def _extract_formatting(self, text_widget, text=None):
        """Read the widget's tags back out as a span list of character
        offsets, for saving, every range worked out in one pass on *text* --
        as its caller read it, or read once here (:meth:`_char_offsets`).
        """
        plain, fonts, colors = [], [], []
        for style in KNOWN_FORMAT_STYLES:
            ranges = text_widget.tag_ranges(style)
            for i in range(0, len(ranges), 2):
                plain.append((style, ranges[i], ranges[i + 1]))
        # Composite font tags give size and family only; weight and slant come
        # from their own tags above, or a run was saved twice.
        for tag_name in text_widget.tag_names():
            parsed = parse_font_tag(tag_name)
            if not parsed:
                continue
            _is_bold, _is_italic, size, family = parsed
            ranges = text_widget.tag_ranges(tag_name)
            for i in range(0, len(ranges), 2):
                fonts.append((size, family, ranges[i], ranges[i + 1]))

        for tag_name in text_widget.tag_names():
            for style in COLOR_FORMAT_STYLES:
                prefix = style + "_"
                if not tag_name.startswith(prefix):
                    continue
                hex_color = "#" + tag_name[len(prefix):]
                if not _is_valid_hex_color(hex_color):
                    continue
                ranges = text_widget.tag_ranges(tag_name)
                for i in range(0, len(ranges), 2):
                    colors.append((style, hex_color, ranges[i], ranges[i + 1]))

        offsets = self._char_offsets(text_widget, [
            index
            for group in (plain, fonts, colors)
            for entry in group
            for index in entry[-2:]
        ], text)

        # Built in the same order the three loops used to append in, so the
        # list handed to merge_spans is byte-for-byte what it always was.
        spans = []
        for style, first, last in plain:
            start, end = offsets[str(first)], offsets[str(last)]
            if end > start:
                spans.append({"start": start, "end": end, "style": style})
        for size, family, first, last in fonts:
            start, end = offsets[str(first)], offsets[str(last)]
            if end <= start:
                continue
            if size is not None:
                spans.append({"start": start, "end": end,
                              "style": "font_size", "value": size})
            if family is not None:
                spans.append({"start": start, "end": end,
                              "style": "font_family", "value": family})
        for style, hex_color, first, last in colors:
            start, end = offsets[str(first)], offsets[str(last)]
            if end > start:
                spans.append({"start": start, "end": end, "style": style,
                              "value": hex_color})
        # Merged: a composite reads back in pieces at every bold or italic
        # boundary, saved so and split again at each save.
        return merge_spans(spans)

    def _apply_formatting(self, text_widget, spans):
        """Re-apply a saved span list as live Tkinter tags, for loading."""
        # Size and family wait for the whole list: merged with bold and italic
        # into one tag each by _apply_font_runs.
        laid = [span for span in normalize_formatting(spans)
                if span["style"] not in FONT_VALUE_STYLES]
        where = self._offset_indices(
            text_widget,
            [offset for span in laid for offset in (span["start"], span["end"])])
        for span in laid:
            try:
                start_idx = where[span["start"]]
                end_idx = where[span["end"]]
                if span["style"] in COLOR_FORMAT_STYLES:
                    tag = self._ensure_color_tag(text_widget, span["style"], span["value"])
                else:
                    tag = span["style"]
                if span["style"] == "highlight":
                    # An older note's highlight across lines is laid the
                    # corrected way too, without a newline.
                    self._tag_add_no_newline(text_widget, tag, start_idx, end_idx)
                else:
                    text_widget.tag_add(tag, start_idx, end_idx)
            except tk.TclError:
                pass
        self._apply_font_runs(text_widget, spans)

    def _selection_has_style(self, text_widget, style_set, start, end):
        """True only if EVERY character in [start, end) carries a tag from
        style_set: a toggle turns off a style applied throughout, else on, as
        editors treat a mixed selection. Asked of the tags' ranges
        (_stretches_over), not a character at a time (seconds a key)."""
        for _first, _last, wearing in self._stretches_over(
                text_widget, sorted(style_set), start, end):
            if wearing is None:
                return False
        return True

    @staticmethod
    def _tag_ranges_over(text_widget, tag, start, end):
        """*tag*'s ranges over [*start*, *end*) -- normalized indices --
        clipped to it, in order, as ((line, col), (line, col)): asked of Tk
        a range at a time, as far as the caller reads."""
        s, e = _index_key(start), _index_key(end)
        at = start
        before = text_widget.tag_prevrange(tag, start)
        if before and _index_key(before[1]) > s:
            yield s, min(_index_key(before[1]), e)
            at = str(before[1])
        while _index_key(at) < e:
            found = text_widget.tag_nextrange(tag, at, end)
            if not found:
                return
            yield _index_key(found[0]), min(_index_key(found[1]), e)
            at = str(found[1])

    def _stretches_over(self, text_widget, tags, start, end,
                        skip_line_breaks=False):
        """Walk [*start*, *end*) in stretches where none of *tags* starts or
        stops, yielding (first, last, wearing): the first of *tags* -- in the
        order given, lowest priority first -- covering the stretch, or None.
        A stretch of line breaks alone is passed over when asked to."""
        start, end = text_widget.index(start), text_widget.index(end)
        pos, e = _index_key(start), _index_key(end)
        walks = [self._tag_ranges_over(text_widget, tag, start, end) for tag in tags]
        heads = [next(walk, None) for walk in walks]
        while pos < e:
            reach, wearing = e, None
            for i, walk in enumerate(walks):
                while heads[i] is not None and heads[i][1] <= pos:
                    heads[i] = next(walk, None)
                head = heads[i]
                if head is None:
                    continue
                if head[0] <= pos:
                    wearing = tags[i] if wearing is None else wearing
                    reach = min(reach, head[1])
                else:
                    reach = min(reach, head[0])
            if not (skip_line_breaks
                    and self._only_line_breaks(text_widget, pos, reach)):
                yield pos, reach, wearing
            pos = reach

    @staticmethod
    def _only_line_breaks(text_widget, first, last):
        """Whether every character from *first* to *last* ((line, col), last
        excluded) is a line break: *first* at its line's end, *last* at a
        line's start, and only empty lines between."""
        if last[0] == first[0] or last[1] != 0:
            return False
        if text_widget.index(f"{first[0]}.end") != "%d.%d" % first:
            return False
        return all(text_widget.index(f"{line}.end") == f"{line}.0"
                   for line in range(first[0] + 1, last[0]))

    @staticmethod
    def _font_tag_for(is_bold, is_italic):
        """The single font tag for this bold/italic pair, or None.

        Two Tk tags that both set the font option do not compose, which is
        why bold+italic is one compound tag -- see core.formatting.
        """
        return core_font_tag_for(is_bold, is_italic)

    @staticmethod
    def _contrasting_fg(hex_color):
        """Black or near-white, whichever reads better against hex_color."""
        return core_contrasting_fg(hex_color)

    def _on_fill(self, role):
        """The words on a control filled with the theme's *role* colour
        (accent, accent_hover, danger or success): see letters_on."""
        return letters_on(self.colors[role])

    @_undo_atom(tags_only=True)
    def _toggle_body_style(self, style):
        """Bold/Italic/Underline/Strikethrough, from the toolbar and the menu:
        over a selection, toggles it there; with none, toggles a "pending"
        style every character typed from now on wears, until toggled off
        (_apply_pending_style_to_typed_char)."""
        target = self._grid_style_target()
        if target:
            # Cells are selected, or one is open in the editor: the button
            # means THOSE, not a pending style for the body.
            self._flush_table_grids()
            self._grid_apply_style(target[0], target[1], style)
            return
        try:
            start = self.body_text.index("sel.first")
            end = self.body_text.index("sel.last")
            has_selection = self.body_text.compare(start, "<", end)
        except tk.TclError:
            has_selection = False

        if not has_selection:
            if style in self._pending_styles:
                self._pending_styles.discard(style)
                self.set_status(f"{style.capitalize()} off")
            else:
                self._pending_styles.add(style)
                self.set_status(f"{style.capitalize()} on — applies to what you type next")
            if self._has_any_pending_style():
                # Left gravity: the mark stays where the pending run started as
                # typing pushes the cursor on (_apply_pending_style_to_typed_char).
                self.body_text.mark_set(self._PENDING_STYLE_ANCHOR, tk.INSERT)
                self.body_text.mark_gravity(self._PENDING_STYLE_ANCHOR, "left")
                self._pending_style_last_length = self._pending_style_text_length()
            self._refresh_format_buttons()
            return

        if style in ("bold", "italic"):
            # Bold and italic share Tk's font option, so they are one of four
            # exclusive tags; on unless all of it has the style, the other one
            # each stretch's own (_set_weight_by_stretch).
            on = not self._selection_has_style(
                self.body_text, {style, "bold_italic"}, start, end)
            self._set_weight_by_stretch([(start, end)], style, on)
        else:
            already_on = self._selection_has_style(self.body_text, {style}, start, end)
            if already_on:
                self.body_text.tag_remove(style, start, end)
            else:
                self.body_text.tag_add(style, start, end)

        self._refresh_format_buttons()
        self._schedule_autosave()

    @_undo_atom(tags_only=True)
    def _apply_body_color(self, kind, hex_color):
        """The text colour or highlight picked (*kind*), *hex_color* or None
        to clear: a swatch sets its colour over the selection, replacing any
        of its kind; with no selection, the PENDING colour, as
        _toggle_body_style does for the on/off styles."""
        target = self._grid_style_target()
        if target:
            self._flush_table_grids()
            self._grid_apply_style(target[0], target[1], kind, hex_color)
            return
        try:
            start = self.body_text.index("sel.first")
            end = self.body_text.index("sel.last")
            has_selection = self.body_text.compare(start, "<", end)
        except tk.TclError:
            has_selection = False

        label = "Highlight" if kind == "highlight" else "Text color"

        if not has_selection:
            if kind == "text_color":
                self._pending_text_color = hex_color
            else:
                self._pending_highlight_color = hex_color
            self.set_status(f"{label} on — applies to what you type next" if hex_color
                             else f"{label} off")
            if self._has_any_pending_style():
                self.body_text.mark_set(self._PENDING_STYLE_ANCHOR, tk.INSERT)
                self.body_text.mark_gravity(self._PENDING_STYLE_ANCHOR, "left")
                self._pending_style_last_length = self._pending_style_text_length()
            self._refresh_format_buttons()
            return

        # One colour of each kind at a time: the old tag goes before the new,
        # not layered under it to win or lose by priority.
        for tag_name in self.body_text.tag_names():
            if tag_name.startswith(kind + "_"):
                self.body_text.tag_remove(tag_name, start, end)
        if hex_color:
            tag = self._ensure_color_tag(self.body_text, kind, hex_color)
            if kind == "highlight":
                self._tag_add_no_newline(self.body_text, tag, start, end)
            else:
                self.body_text.tag_add(tag, start, end)

        self._refresh_format_buttons()
        self._schedule_autosave()

    @_undo_atom(tags_only=True)
    def _apply_body_font(self, style, value):
        """Font size / family picker handler.

        Closer to a colour than to Bold: "one of a list, or nothing" rather
        than on/off. With no selection it becomes a pending choice for
        whatever gets typed next, through the same anchor-tracking machinery
        the boolean styles and colours already use.
        """
        try:
            start = self.body_text.index("sel.first")
            end = self.body_text.index("sel.last")
            has_selection = self.body_text.compare(start, "<", end)
        except tk.TclError:
            has_selection = False

        label = "Font size" if style == "font_size" else "Font"
        if not has_selection:
            if style == "font_size":
                self._pending_font_size = value
            else:
                self._pending_font_family = value
            self.set_status(f"{label} set — applies to what you type next"
                            if value else f"{label} back to the default")
            if self._has_any_pending_style():
                self.body_text.mark_set(self._PENDING_STYLE_ANCHOR, tk.INSERT)
                self.body_text.mark_gravity(self._PENDING_STYLE_ANCHOR, "left")
                self._pending_style_last_length = self._pending_style_text_length()
            self._refresh_format_buttons()
            return

        # Size and family depend on the bold and italic around them: edited as
        # spans -- clipped out, the new value laid over -- and resolved again
        # by _apply_font_runs, from one read.
        whole = self.body_text.get("1.0", "end-1c")
        where = self._char_offsets(self.body_text, [start, end], whole)
        first, last = where[str(start)], where[str(end)]
        spans = []
        for span in self._extract_formatting(self.body_text, whole):
            if span["style"] != style or span["end"] <= first or span["start"] >= last:
                spans.append(span)
                continue
            if span["start"] < first:
                spans.append({**span, "end": first})
            if span["end"] > last:
                spans.append({**span, "start": last})
        if value is not None:
            spans.append({"start": first, "end": last, "style": style,
                          "value": value})

        for name in self.body_text.tag_names():
            if parse_font_tag(name):
                self.body_text.tag_remove(name, "1.0", "end")
        self._apply_font_runs(self.body_text, spans)
        self._refresh_format_buttons()
        self._schedule_autosave()

    def _open_color_swatch_popup(self, kind):
        """The text colour or highlight popup: swatches and a Clear, anchored
        to its toolbar button, as open_color_picker() is for the note's
        colour. No hex entry: most people do not think in hex."""
        self._dismiss_mini_popup()
        palette = PRESET_NOTE_COLORS if kind == "text_color" else HIGHLIGHT_COLOR_PALETTE
        anchor_btn = self.text_color_btn if kind == "text_color" else self.highlight_btn

        popup = tk.Toplevel(self)
        self._mini_popup = popup
        popup.wm_overrideredirect(True)
        popup.configure(bg=self.colors["accent"])

        def _choose(color):
            self._apply_body_color(kind, color)
            self._dismiss_mini_popup()

        if kind == "highlight":
            # The same column the table's highlight popup shows -- flat
            # full-width swatches parted by theme-coloured hairlines --
            # so every road to a highlight looks like every other.
            self._highlight_swatch_column(popup, _choose)
        else:
            outer = tk.Frame(popup, bg=self.colors["card"], padx=1, pady=1)
            outer.pack()
            body = tk.Frame(outer, bg=self.colors["card"])
            body.pack()

            # Only text_color reaches this header; the highlight's branch above
            # carries its own.
            label = tk.Label(body, text="Pick a text color",
                             font=("Segoe UI", 10, "bold"),
                             bg=self.colors["card"], fg=self.colors["text"])
            label.pack(padx=15, pady=(12, 8))

            swatch_grid = tk.Frame(body, bg=self.colors["card"])
            swatch_grid.pack(padx=15)

            for i, hex_color in enumerate(palette):
                swatch = tk.Button(
                    swatch_grid, bg=hex_color, activebackground=hex_color, width=3, height=1,
                    relief="flat", cursor="hand2", command=lambda c=hex_color: _choose(c)
                )
                swatch.grid(row=i // 5, column=i % 5, padx=4, pady=4)
                self._button_choice(swatch)

            button_row = tk.Frame(body, bg=self.colors["card"])
            button_row.pack(fill="x", padx=15, pady=(8, 14))
            clear_btn = tk.Button(
                button_row, text="Clear", command=lambda: _choose(None), relief="flat",
                bg=self.colors["sidebar"], fg=self.colors["text"], cursor="hand2", font=("Segoe UI", 9)
            )
            clear_btn.pack(fill="x", ipady=5)
            self._button_choice(clear_btn)

        self._place_dropdown_popup(popup, anchor_btn)

    def _pending_style_text_length(self):
        result = self.body_text.count("1.0", "end-1c", "chars")
        return result[0] if result else 0

    def _has_any_pending_style(self):
        """True if there's anything queued for the next typed character —
        a boolean style (bold/italic/underline/strike) or a color. Colors
        aren't members of _pending_styles (a color isn't on/off, it's a
        value, or nothing), so this is the one place that needs to know
        about both kinds together — anywhere that used to just check
        "is _pending_styles non-empty" now goes through this instead."""
        return bool(self._pending_styles) or bool(self._pending_text_color) \
            or bool(self._pending_highlight_color) \
            or bool(self._pending_font_size) or bool(self._pending_font_family)

    def _apply_pending_style_to_typed_char(self, event=None):
        """Tag everything from _PENDING_STYLE_ANCHOR to the cursor, not one
        character -- a fast burst runs several inserts before their
        KeyReleases -- when the note's length grew, a fact of the content,
        not of event.char, which CI's Tk filled otherwise; a paste is left
        out by its own binding. Bound to <KeyRelease> (ISSUES_LOG: "The
        fast-typing fix that took three tries to land safely")."""
        if not self._has_any_pending_style():
            return
        if self._PENDING_STYLE_ANCHOR not in self.body_text.mark_names():
            return
        current_length = self._pending_style_text_length()
        if current_length <= self._pending_style_last_length:
            # No growth (a shortcut key's release, arrow keys, Home/End) or
            # the text shrank (Backspace/Delete) -- nothing new to tag.
            self._resync_pending_style_anchor()
            return
        start_idx = self.body_text.index(self._PENDING_STYLE_ANCHOR)
        end_idx = self.body_text.index(tk.INSERT)
        if self.body_text.compare(start_idx, "<", end_idx):
            # The typing settled first (_spread_typed_run), so the letters wear
            # the run's composite before a pick replaces one property; after,
            # they took the base's font with the pick.
            self._spread_typed_run()
            is_bold = "bold" in self._pending_styles
            is_italic = "italic" in self._pending_styles
            tag = self._font_tag_for(is_bold, is_italic)
            if tag:
                self.body_text.tag_add(tag, start_idx, end_idx)
            # The plain tag is what the toolbar reads, the composite how it
            # looks: refitted to the letters' weight, a pick replacing its one
            # property; a run's later letters go on from the one before.
            size, family = self._pending_font_size, self._pending_font_family
            before = self.body_text.index(f"{start_idx} -1c")
            went = next((parse_font_tag(t)
                         for t in self.body_text.tag_names(before)
                         if parse_font_tag(t)), None)
            same_pick = went is not None and (
                (size and went[2] == size) or (family and went[3] == family))
            self._fit_font_tags(start_idx, end_idx,
                                like=before if same_pick else None,
                                size=size, family=family)
            if "underline" in self._pending_styles:
                self.body_text.tag_add("underline", start_idx, end_idx)
            if "strike" in self._pending_styles:
                self.body_text.tag_add("strike", start_idx, end_idx)
            if self._pending_text_color:
                color_tag = self._ensure_color_tag(self.body_text, "text_color", self._pending_text_color)
                self.body_text.tag_add(color_tag, start_idx, end_idx)
            if self._pending_highlight_color:
                color_tag = self._ensure_color_tag(self.body_text, "highlight", self._pending_highlight_color)
                # Typing past the end of a line (pressing Enter with a
                # highlight still "stuck" on) would otherwise sweep the
                # newline into the tag and bleed the bar full-width.
                self._tag_add_no_newline(self.body_text, color_tag, start_idx, end_idx)
        self.body_text.mark_set(self._PENDING_STYLE_ANCHOR, end_idx)
        self._pending_style_last_length = current_length

    def _resync_pending_style_anchor(self, event=None):
        """Move the pending-style anchor to the cursor, tagging nothing, and
        reset the length baseline -- when the cursor moves without typing,
        and after a paste -- so only new typing is ever tagged."""
        if self._has_any_pending_style() and self._PENDING_STYLE_ANCHOR in self.body_text.mark_names():
            self.body_text.mark_set(self._PENDING_STYLE_ANCHOR, tk.INSERT)
            self._pending_style_last_length = self._pending_style_text_length()

    def _select_word_at_click(self, event):
        """Double-click selects a word by _char_class, never across "." --
        "something" of "something.else" -- and nothing on an EMPTY line (Tk
        took its newline, a full-width bar). From event.widget, for the body
        and the comments alike."""
        w = event.widget
        index = w.index(f"@{event.x},{event.y}")
        line, col = index.split(".")
        line_text = w.get(f"{line}.0", f"{line}.0 lineend")
        # Tk columns are UTF-16 units, the walk Python characters: converted
        # both ways, or an emoji before shifted the word selected.
        col = min(self._py_col(line_text, int(col)), len(line_text) - 1)
        if col < 0:
            return "break"
        char_cls = self._char_class(line_text[col])
        if char_cls is None:
            return "break"
        start = col
        while start > 0 and self._char_class(line_text[start - 1]) == char_cls:
            start -= 1
        end = col + 1
        while end < len(line_text) and self._char_class(line_text[end]) == char_cls:
            end += 1
        w.tag_remove("sel", "1.0", "end")
        w.tag_add("sel", f"{line}.{self._tk_col(line_text, start)}",
                  f"{line}.{self._tk_col(line_text, end)}")
        w.mark_set("insert", f"{line}.{self._tk_col(line_text, end)}")
        return "break"

    def _select_line_no_newline(self, event):
        """Triple-click selects the line without its newline: Tk's took it,
        and a copy carried it along. From event.widget, for the body and
        the comments alike."""
        w = event.widget
        index = w.index(f"@{event.x},{event.y}")
        line = index.split(".")[0]
        line_start, line_end = f"{line}.0", f"{line}.0 lineend"
        w.tag_remove("sel", "1.0", "end")
        w.tag_add("sel", line_start, line_end)
        w.mark_set("insert", line_end)
        return "break"

    def _bind_text_selection_fixes(self, text_widget):
        """Apply the double-click (word boundary / empty line) and
        triple-click (no trailing newline) selection fixes to a Text
        widget. Used for every multi-line text field the user types real
        prose into, so selection behaves the same way in all of them."""
        text_widget.bind("<Double-Button-1>", self._select_word_at_click)
        text_widget.bind("<Triple-Button-1>", self._select_line_no_newline)

    # The formatting four, as the shortcuts page lists them: the note's text
    # and an open table cell style with them; the other text boxes swallow
    # them, and a one-line box takes Ctrl+D as nothing (see bind_class "Entry").
    FORMAT_KEYS = (
        ("<Control-b>", "bold"), ("<Control-B>", "bold"),
        ("<Control-i>", "italic"), ("<Control-I>", "italic"),
        ("<Control-u>", "underline"), ("<Control-U>", "underline"),
        ("<Control-d>", "strike"), ("<Control-D>", "strike"),
    )

    def _swallow_format_keys(self, text_widget):
        """The formatting keys do nothing in a box of plain text -- the
        comments, a template's boxes, the import box. Left to Tk's own Text
        bindings they edited it: Ctrl+I typed a tab over the selected words,
        Ctrl+D deleted the next letter (the final audit's wave 3)."""
        for key, _style in self.FORMAT_KEYS:
            text_widget.bind(key, lambda _e: "break")

    def _uniform_font_in_selection(self, style, start, end):
        """The one size (or family) covering the WHOLE range, or None -- also
        "a mix", the honest answer for a dropdown. A character takes the
        lowest-priority font tag it wears, as tag_names lists them.
        """
        fonts = [n for n in self.body_text.tag_names() if parse_font_tag(n)]
        wanted = None
        for _first, _last, name in self._stretches_over(self.body_text, fonts,
                                                         start, end):
            parsed = parse_font_tag(name) if name else None
            found = (parsed[2] if style == "font_size" else parsed[3]) if parsed else None
            if found is None:
                return None
            if wanted is None:
                wanted = found
            elif wanted != found:
                return None
        return wanted

    def _uniform_color_in_selection(self, kind, start, end):
        """The single hex color of the given kind ("text_color" or
        "highlight") that covers the ENTIRE [start, end) range, or None if
        the range is empty, uncolored, or a mix of more than one color —
        the color-preview equivalent of _selection_has_style."""
        prefix = kind + "_"
        tags = [n for n in self.body_text.tag_names() if n.startswith(prefix)]
        color = None
        # Newlines deliberately never carry a highlight tag (see
        # _tag_add_no_newline), so line breaks are passed over: judged
        # "uncolored", every multi-line selection would read as a mix.
        for _first, _last, name in self._stretches_over(
                self.body_text, tags, start, end, skip_line_breaks=True):
            if name is None:
                return None
            this_hex = "#" + name[len(prefix):]
            if color is None:
                color = this_hex
            elif color != this_hex:
                return None
        return color

    def _refresh_format_buttons(self, event=None):
        """Reflect the current selection's styles — or, with no selection,
        the pending styles queued up for the next typed character — in the
        toolbar buttons' pressed/unpressed look. Called on selection/cursor
        changes and whenever a pending style is toggled."""
        # The caret's line read once, for both, and only as far as they read
        # it (_line_head): every key and click runs this.
        line_no = int(self.body_text.index("insert").split(".")[0])
        line = self._line_head(line_no)
        self._resync_list_tags(line_no, line)
        self._refresh_list_buttons(line)
        try:
            start = self.body_text.index("sel.first")
            end = self.body_text.index("sel.last")
            has_selection = self.body_text.compare(start, "<", end)
        except tk.TclError:
            has_selection = False
        for style, btn in self._fmt_buttons.items():
            if has_selection:
                check = {"bold_italic", style} if style in ("bold", "italic") else {style}
                active = self._selection_has_style(self.body_text, check, start, end)
            else:
                active = style in self._pending_styles
            btn.configure(
                relief="sunken" if active else "flat",
                bg=self.colors["accent"] if active else self.colors["sidebar"],
                fg=self._on_fill("accent") if active else self.colors["text"],
            )

        if has_selection:
            size = self._uniform_font_in_selection("font_size", start, end)
            family = self._uniform_font_in_selection("font_family", start, end)
        else:
            size = self._pending_font_size
            family = self._pending_font_family
        # A mix across the selection reads as "Default" rather than as
        # the first run's value, which would claim the whole selection
        # is that size.
        self.font_size_var.set(str(size) if size else self.DEFAULT_FONT_LABEL)
        self.font_family_var.set(family or self.DEFAULT_FONT_LABEL)

        if has_selection:
            text_color = self._uniform_color_in_selection("text_color", start, end)
            highlight_color = self._uniform_color_in_selection("highlight", start, end)
        else:
            text_color = self._pending_text_color
            highlight_color = self._pending_highlight_color
        # Each button wears its active colour as a swatch, as the note's own
        # does, its letter's contrast read off whatever background shows.
        tc_bg = text_color or self.colors["sidebar"]
        hl_bg = highlight_color or self.colors["sidebar"]
        self.text_color_btn.configure(
            bg=tc_bg, activebackground=tc_bg,
            fg=self._contrasting_fg(tc_bg) if text_color else self.colors["text"],
        )
        self.highlight_btn.configure(
            bg=hl_bg, activebackground=hl_bg,
            fg=self._contrasting_fg(hl_bg) if highlight_color else self.colors["text"],
        )

    # A curated set by theme, not all of Unicode. Each group has a chip colour:
    # Tk draws emoji as monochrome outlines on Windows, and a coloured chip
    # makes them look styled, not broken.
    EMOJI_GROUPS = [
        ("Faces", ["😀", "😄", "😂", "🙂", "😉", "😍", "🤔", "😅", "😢", "😮",
                  "😴", "🥳", "😎", "🙄", "😬", "🤯"], "#FFD166"),
        ("Gestures", ["👍", "👎", "👏", "🙌", "🤝", "✌", "🤞", "👌", "💪", "🙏",
                      "👋", "✍"], "#6EC6CA"),
        ("Hearts & stars", ["❤", "💜", "💙", "💚", "🧡", "💛", "⭐", "✨", "🌟", "💯"], "#FF8FA3"),
        ("Checks & flags", ["✅", "❌", "☑", "⚠", "🚩", "🔴", "🟡", "🟢", "🔵", "⏰",
                            "ℹ", "❗"], "#A0C4FF"),
        ("Objects", ["📌", "📎", "📅", "📝", "💡", "🔥", "🎯", "🎉", "🚀", "📦",
                    "🔑", "📞", "💬", "🔗", "🏆", "🗂", "🔒", "🛡", "🎨",
                    "🎂", "🎁", "🔔", "💰", "🩺", "✈", "🚗"], "#FFB4A2"),
        ("Nature", ["☀", "🌙", "⛅", "🌧", "🌈", "🌸", "🍀", "🌳", "☕", "🍕",
                    "🍽"], "#B9FBC0"),
    ]

    def _show_emoji_picker(self, text_widget, anchor=None):
        """A small themed popup inserting an emoji at the cursor of whichever
        field opened it, anchored to it. A field INSIDE a popup gets it as a
        popup within that one -- closing the host first destroyed it and
        its typing."""
        host = getattr(self, "_mini_popup", None)
        nested = host is not None and self._is_inside_popup(text_widget, host)
        if nested:
            self._close_nested_popup()
        elif not self._dismiss_mini_popup_asking():
            return
        pop = tk.Toplevel(self)
        if nested:
            # Remembered where Escape and the host's own closing look.
            self._nested_dropdown = pop
        else:
            self._mini_popup = pop
        pop.wm_overrideredirect(True)
        pop.configure(bg=self.colors["accent"])
        outer = tk.Frame(pop, bg=self.colors["card"], padx=8, pady=8)
        outer.pack(padx=1, pady=1)

        head = tk.Frame(outer, bg=self.colors["card"])
        head.pack(fill="x", pady=(0, 6))
        tk.Label(head, text="Insert emoji", bg=self.colors["card"],
                 fg=self.colors["subtext"], font=("Segoe UI", 8, "bold")).pack(side="left")
        tk.Button(head, text="✕",
                  command=pop.destroy if nested else self._dismiss_mini_popup,
                  relief="flat",
                  cursor="hand2", bg=self.colors["card"], fg=self.colors["subtext"],
                  font=("Segoe UI", 9, "bold"), bd=0).pack(side="right")
        if nested:
            # Its own Escape closes just it, as a nested dropdown's does.
            pop.bind("<Escape>", lambda e: pop.destroy())

        wrap = tk.Frame(outer, bg=self.colors["card"], height=self.px(220),
                        width=self.px(260))
        wrap.pack()
        wrap.pack_propagate(False)
        canvas = tk.Canvas(wrap, bg=self.colors["card"], highlightthickness=0)
        sb = ttk.Scrollbar(wrap, orient="vertical", command=canvas.yview)
        inner = tk.Frame(canvas, bg=self.colors["card"])
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.create_window((0, 0), window=inner, anchor="nw", width=self.px(240))
        canvas.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)

        def insert_emoji(emoji, from_keys=False):
            try:
                # Not refocused if focused already; focus_get raises KeyError in
                # this popup (the second emoji died). From the keyboard, it
                # stays on the emoji for the next one.
                try:
                    has_focus = self.focus_get() is text_widget
                except KeyError:
                    has_focus = False
                if not has_focus and not from_keys:
                    text_widget.focus_set()
                # A field showing its grey hint takes the emoji in its place.
                getattr(text_widget, "clear_placeholder", lambda: None)()
                if isinstance(text_widget, tk.Text):
                    at = text_widget.index(tk.INSERT)
                    text_widget.insert(tk.INSERT, emoji)
                    if text_widget is getattr(self, "body_text", None):
                        # Between two pieces of one run, the run's size and
                        # font, as typed text takes them.
                        self._take_run_between(
                            at, text_widget.index(tk.INSERT))
                else:
                    pos = text_widget.index(tk.INSERT)
                    text_widget.insert(pos, emoji)
                    # An Entry counts UTF-16 units: by len(), the caret sat
                    # inside the emoji and the next one split it into diamonds.
                    text_widget.icursor(pos + self._tk_units(emoji))
                # The autosave nudged, skipping the word count (fast clicks
                # lagged); a popup's field is its popup's to save.
                if not nested:
                    self._schedule_autosave(skip_word_count=True)
            except (tk.TclError, KeyError):
                pass
            # Left open on purpose — inserting a few emojis in a row is common.
            return "break"

        for group_name, emojis, group_color in self.EMOJI_GROUPS:
            tk.Label(inner, text=group_name, bg=self.colors["card"],
                     fg=self.colors["subtext"], font=("Segoe UI", 8, "bold"),
                     anchor="w").pack(fill="x", pady=(4, 2))
            grid = tk.Frame(inner, bg=self.colors["card"])
            grid.pack(fill="x")
            cols = 8
            # The group's chip colour (see EMOJI_GROUPS).
            chip_bg = group_color
            chip_hover = _darken_hex(group_color)
            for i, em in enumerate(emojis):
                r, c = divmod(i, cols)
                cell = tk.Label(grid, text=em, font=("Segoe UI Emoji", 14),
                                bg=chip_bg, cursor="hand2", bd=0,
                                width=2, height=1)
                # Padding 1, not 2: the keyboard's ring, resting in the
                # grid's own colour, is the other pixel.
                self._ring_round(cell, self.colors["card"])
                cell.grid(row=r, column=c, padx=1, pady=1, ipadx=1, ipady=1)
                cell.bind("<Button-1>", lambda e, em=em: insert_emoji(em))
                self._pressable(cell, lambda em=em: insert_emoji(em, from_keys=True),
                                walk=True)
                cell.bind("<Enter>", lambda e, w=cell, h=chip_hover: w.configure(bg=h))
                cell.bind("<Leave>", lambda e, w=cell, b=chip_bg: w.configure(bg=b))

        # The wheel bound once every cell exists; earlier, it reached none.
        self._bind_mousewheel_recursive(inner, canvas)

        self._place_dropdown_popup(pop, anchor or text_widget)

    def _build_import_panel(self):
        """The inline import panel: a paste box + Import/close, shown under the
        sidebar button instead of a pop-up window."""
        p = self.import_panel
        tk.Label(p, text="Paste a share code:", font=("Segoe UI", 8, "bold"),
                 anchor="w", bg=self.colors["sidebar"], fg=self.colors["text"]
                 ).pack(fill="x", padx=6, pady=(6, 2))
        self.import_box = tk.Text(p, height=4, wrap="char", font=("Consolas", 8),
                                  relief="flat", bg=self.colors["card"], fg=self.colors["text"],
                                  insertbackground=self.colors["text"], padx=6, pady=6)
        self.track_theme(self.import_box, bg="card", fg="text", insertbackground="text")
        self.import_box.pack(fill="x", padx=6)
        self._add_paste_menu(self.import_box)
        self._swallow_format_keys(self.import_box)
        self.import_status = tk.Label(p, text="", font=("Segoe UI", 7), anchor="w",
                                      wraplength=self.px(200), justify="left",
                                      bg=self.colors["sidebar"], fg=self.colors["danger_text"])
        self.import_status.pack(fill="x", padx=6, pady=(2, 0))
        row = tk.Frame(p, bg=self.colors["sidebar"])
        self.track_theme(row, bg="sidebar")
        row.pack(fill="x", padx=6, pady=6)
        import_btn = tk.Button(row, text="Import", command=self._do_inline_import,
                               bg=self.colors["accent"], fg=self._on_fill("accent"), relief="flat",
                               font=("Segoe UI", 9, "bold"), cursor="hand2")
        import_btn.pack(side="left", fill="x", expand=True, padx=(0, 3), ipady=3)
        # A double-click's second press found the box the first had emptied, and
        # said in red that no code was pasted (wave 2, round 9).
        import_btn.bind(
            "<ButtonPress-1>",
            lambda e: "break" if self._second_press_of_double_click(e) else None,
            add="+")
        tk.Button(row, text="Clear", command=self._clear_import_box,
                  bg=self.colors["card"], fg=self.colors["text"], relief="flat",
                  font=("Segoe UI", 9), cursor="hand2"
                  ).pack(side="left", fill="x", expand=True, padx=3, ipady=3)
        tk.Button(row, text="Close", command=self.toggle_import_panel,
                  bg=self.colors["card"], fg=self.colors["text"], relief="flat",
                  font=("Segoe UI", 9), cursor="hand2"
                  ).pack(side="left", fill="x", expand=True, padx=(3, 0), ipady=3)

    def _clear_import_box(self):
        """Wipe the pasted code and any leftover status message, so a long
        code can be replaced without manually selecting and deleting it."""
        self.import_box.delete("1.0", "end")
        self.import_status.config(text="")
        self.import_box.focus()

    def toggle_import_panel(self):
        if self._is_placed(self.import_panel):
            self.import_panel.pack_forget()
        else:
            if self._is_placed(self.share_panel):
                self.share_panel.pack_forget()
            self.import_panel.pack(fill="x", padx=8, pady=(0, 8))
            self.import_box.focus()
        self._fit_sidebar_panel()

    # How far an open panel's middle gives in a short window: (natural,
    # comfortable, least) -- Share's list in pixels (its search row taken
    # out of it), Import's paste box in lines.
    SIDEBAR_PANEL_BODY = {"share": (105, 56, 28), "import": (4, 2, 1)}

    def _fit_sidebar_panel(self, _event=None):
        """Keep the open panel's own buttons, and a generated code, on screen
        in a short window -- pack cut them off the zone's bottom, and
        "Generate code" seemed to do nothing. As room runs out: the middle
        gives rows, the zone's other buttons step aside, the middle goes to
        one row, then the panel's own button (Close still closes). From the
        sizes asked, all back when it closes or the window grows."""
        zone = self._sidebar_bottom
        buttons = self._sidebar_zone_buttons
        if zone is None or not buttons or getattr(self, "_fitting_sidebar", False):
            return
        if self._is_placed(self.share_panel):
            panel, which = self.share_panel, "share"
        elif self._is_placed(self.import_panel):
            panel, which = self.import_panel, "import"
        else:
            panel, which = None, None
        wrap = getattr(self, "_share_list_wrap", None)
        try:
            natural_state = (
                all(self._is_placed(b) for b, _kw in buttons)
                and int(self.import_box.cget("height")) == self.SIDEBAR_PANEL_BODY["import"][0]
                and (wrap is None or not wrap.winfo_exists()
                     or int(wrap.cget("height")) == self.SIDEBAR_PANEL_BODY["share"][0]))
        except tk.TclError:
            return
        if panel is None and natural_state:
            return                      # the everyday case: nothing to do
        self._fitting_sidebar = True
        try:
            self._fit_sidebar_panel_now(zone, buttons, panel, which, wrap)
        except tk.TclError:
            pass
        finally:
            self._fitting_sidebar = False

    def _fit_sidebar_panel_now(self, zone, buttons, panel, which, wrap):
        def height(w, kw):
            pady = kw.get("pady", 0)
            pad = sum(pady) if isinstance(pady, (tuple, list)) else 2 * int(pady)
            return w.winfo_reqheight() + 2 * int(kw.get("ipady", 0)) + pad

        hidden = set()
        body = {"share": self.SIDEBAR_PANEL_BODY["share"][0],
                "import": self.SIDEBAR_PANEL_BODY["import"][0]}
        room = self.sidebar.winfo_height()
        if panel is not None and room > 1:
            self.update_idletasks()
            unit = (1 if which == "share" else tkfont.Font(
                font=self.import_box.cget("font")).metrics("linespace"))
            natural, comfortable, least = self.SIDEBAR_PANEL_BODY[which]
            now = int((wrap if which == "share" else self.import_box).cget("height"))
            list_host = self.canvas.master
            top = sum(height(s, s.pack_info()) for s in self.sidebar.pack_slaves()
                      if s is not zone and s is not list_host)
            want = (sum(height(b, kw) for b, kw in buttons)
                    + panel.winfo_reqheight() + (natural - now) * unit
                    + height(panel, panel.pack_info()) - panel.winfo_reqheight())
            over = top + want - room

            def give(to):
                nonlocal over
                units = min(max(0, -(-over // unit)), body[which] - to)
                body[which] -= units
                over -= units * unit

            if over > 0:
                give(comfortable)
            new_b, import_b, share_b, settings_b = (b for b, _kw in buttons)
            own = import_b if which == "import" else share_b
            other = share_b if which == "import" else import_b
            for b in (settings_b, other, new_b):
                if over <= 0:
                    break
                hidden.add(b)
                over -= height(b, dict(buttons)[b])
            if over > 0:
                give(least)
            if over > 0:
                # The very last resort: the panel's own button. Its Close
                # still closes it (measured: the selection bar open above
                # Share with a code, at 1366x690 in the Linux fonts).
                hidden.add(own)
                over -= height(own, dict(buttons)[own])
        # Apply only what changes, the zone's order kept: a button coming
        # back goes in front of the next one still packed.
        order = [b for b, _kw in buttons] + ([panel] if panel is not None else [])
        for i, (b, kw) in enumerate(buttons):
            if b in hidden:
                if self._is_placed(b):
                    b.pack_forget()
            elif not self._is_placed(b):
                nxt = next((w for w in order[i + 1:] if self._is_placed(w)), None)
                if nxt is not None:
                    b.pack(before=nxt, **kw)
                else:
                    b.pack(**kw)
        if int(self.import_box.cget("height")) != body["import"]:
            self.import_box.configure(height=body["import"])
        if wrap is not None and wrap.winfo_exists() \
                and int(wrap.cget("height")) != body["share"]:
            wrap.configure(height=body["share"])

    def _take_known_notes(self, incoming, source):
        """Ask once -- not a hundred times -- about a batch's notes we already
        have by identity (the same note edited elsewhere, which text matching
        reads as new); both bulk routes come here. Returns ``(proceed,
        remaining, updates, unchanged, copies)``. The updates are applied by
        the caller once its last question is answered (_apply_known_updates):
        here, a Cancel after left them replaced, saved by the next save.
        """
        known, fresh = split_by_identity(self.notes, incoming)
        # A note that arrives exactly as it is here needs no update (see
        # shared_update_changes for what that used to cost); a second copy
        # of it is the person's to ask for.
        differing, same = [], []
        for mine, theirs in known:
            (differing if self._known_note_differs(mine, theirs, source)
             else same).append((mine, theirs))
        unchanged = len(same)
        known = differing

        def finish(remaining, updates, added=()):
            copies = self._unchanged_copies(same, len(incoming), source)
            return True, remaining, updates, unchanged - len(copies), list(added) + copies

        if not known:
            return finish(fresh, [])
        count = len(known)
        plural = "" if count == 1 else "s"
        # "All" only when it is all: the unchanged notes are counted in the
        # batch too, and are asked about straight after this question.
        if fresh or same:
            message = (
                f"{count} of the {len(incoming)} note{'' if len(incoming) == 1 else 's'} "
                f"in this {source} {'is' if count == 1 else 'are'} already here, "
                f"edited elsewhere.\n\n"
                f"Updating replaces this device's copies; each one can be "
                f"undone with \u201c\u21a9 Restore previous\u201d.\n"
                f"Adding leaves both versions, so you can compare them."
            )
        else:
            message = (
                f"All {count} note{plural} in this {source} {'is' if count == 1 else 'are'} "
                f"already here, edited elsewhere.\n\n"
                f"Updating replaces this device's copies; each one can be "
                f"undone with \u201c\u21a9 Restore previous\u201d.\n"
                f"Adding leaves both versions, so you can compare them."
            )
        # A backup's older notes are said as older: updating trades newer text
        # for them (a share code carries no saved time).
        older = 0 if source != "backup" else sum(
            1 for mine, theirs in known
            if str(theirs.get("updated") or "") < str(mine.get("updated") or ""))
        if older:
            who = "It is" if count == 1 else f"{older} of them are"
            message += f"\n\n{who} OLDER than the copy on this device."
        # One rescue copy per note: an update's takes the place of one the
        # note still needs, so that is said rather than done in silence.
        rescued = sum(1 for mine, _theirs in known if self._holds_unspent_rescue(mine))
        if rescued:
            who = "One of them holds" if count > 1 and rescued == 1 else (
                "It holds" if count == 1 else f"{rescued} of them hold")
            message += (f"\n\n{who} an earlier version that “↩ Restore "
                        f"previous” can bring back; updating replaces it with "
                        f"the version from before this update.")
        choice = self._themed_dialog(
            f"{count} note{plural} you already have",
            message,
            kind="question",
            # One note said as one: "Update the 1" and "Add it as new notes"
            # came of counting it.
            buttons=[("Cancel", "cancel"),
                     ("Add it as a new note" if count == 1 else "Add them as new notes", "add"),
                     ("Update it" if count == 1 else f"Update the {count}", "update")],
            # Asked from a timer once a backup is unpacked, while the person
            # may be typing: a stray Space or Enter replaced their notes.
            default="Cancel",
        )
        if choice is None or choice == "cancel":
            return False, [], [], unchanged, []
        if choice == "update":
            # The editor's work saved before anything replaces it; going back
            # to fix an unstorable date cancels the import.
            if self._flush_autosave(leaving=self.selected_note_id in {
                    mine.get("id") for mine, _theirs in known}) is False:
                return False, [], [], unchanged, []
            return finish(fresh, known)
        # "add": new notes without the identity they came with (one uid on two
        # notes), as copies asked for: put to the look-alike question again,
        # its Cancel undid the Add (wave 2, round 10).
        return finish(fresh, [], self._without_identity(known))

    @staticmethod
    def _without_identity(pairs):
        """The arriving side of (mine, theirs) pairs, each without its uid:
        a copy that keeps it would be two notes wearing one identity."""
        copies = []
        for _mine, theirs in pairs:
            copy = dict(theirs)
            copy.pop("uid", None)
            copies.append(copy)
        return copies

    def _unchanged_copies(self, same, total, source):
        """Ask whether the notes of an import that are already here, exactly
        as they arrived, should be added again as copies. Skipping is the
        answer Enter and Escape give; the copies come back without their
        identity. Re-importing a backup used to skip them without asking,
        and the person had wanted the choice (field pass)."""
        if not same:
            return []
        count = len(same)
        one = count == 1
        if count == total:
            lead = (f"The note in this {source} is" if one
                    else f"All {count} notes in this {source} are")
        else:
            lead = (f"{count} of the {total} notes in this {source} "
                    f"{'is' if one else 'are'}")
        skip = "Skip it" if one else f"Skip the {count}"
        # Said as what was compared: everything the import holds, which for
        # a code is not everything a note has (its skipped days, its files).
        choice = self._themed_dialog(
            "Already here, unchanged",
            f"{lead} already here: the {source} holds nothing about "
            f"{'it' if one else 'them'} that this device lacks.\n\n"
            "Skipping changes nothing. A copy is a second, separate note, "
            f"made from what the {source} holds.",
            kind="question",
            buttons=[(skip, "skip"),
                     ("Add a copy anyway" if one else "Add copies anyway",
                      "copies")],
            default=skip)
        return self._without_identity(same) if choice == "copies" else []

    def _apply_known_updates(self, updates, source):
        """Apply what "Update" agreed to in _take_known_notes; returns how
        many notes changed. The editor is then brought onto the new
        version of any note it holds -- or its next save puts the old
        version straight back."""
        fields = (UPDATABLE_FROM_BACKUP if source == "backup"
                  else UPDATABLE_FROM_SHARED)
        for mine, theirs in updates:
            apply_shared_update(mine, theirs, fields)
            if source == "backup":
                self._adopt_backup_attachments(mine, theirs)
        if updates:
            self._editor_follows_external_change(
                {n.get("id") for n, _ in updates})
        return len(updates)

    def _dup_keys_after(self, updates):
        """The duplicate-check keys of the notebook as it will be once
        *updates* (from _take_known_notes) are applied. They are applied
        only after the duplicate question is answered, but that question
        is about the notebook the import will leave behind."""
        replaced = {id(mine) for mine, _ in updates}
        return ({_dup_key(n) for n in self.notes if id(n) not in replaced}
                | {_dup_key(normalize_note(theirs)) for _, theirs in updates})

    def _all_lookalike_choice(self, count, other, where, pending):
        """The question when every note left in a code or a backup (*where*)
        looks like one already here. With the rest of the import *pending* --
        an Update agreed to, copies kept -- it can skip them and go on:
        Cancel, its only no, dropped those unsaid (wave 2, round 9)."""
        said = (f"All {count}{other} note(s) in this {where} look identical "
                "to notes you already have")
        if not pending:
            return self._themed_dialog(
                "All notes already imported",
                said + ". Import them anyway as new copies?", kind="question",
                buttons=[("Cancel", "cancel"), ("Import anyway", "all")], default="Cancel")
        return self._themed_dialog(
            "Possible duplicates",
            f"{said} ({SAME_AS}). Skipped, the rest of this import still happens.",
            kind="question",
            buttons=[("Cancel the import", "cancel"), ("Import anyway", "all"),
                     ("Skip them", "skip")],
            default="Skip them")

    def _backup_brings_more(self, state, added_names):
        """Whether a backup brings anything beside its notes -- a category, a
        template or a Trash entry not here, a day's marks: what Skip goes on
        with. Unseen, its look-alike question's default Cancel dropped them
        all (wave 2, round 10)."""
        if added_names:
            return True
        names = {t.get("name") for t in self.templates}
        if any(isinstance(t, dict) and t.get("name") and t.get("name") not in names
               for t in state.get("imported_templates") or []):
            return True
        here = {content_signature(normalize_note(e)) for e in self.trash if isinstance(e, dict)}
        if any(isinstance(e, dict) and content_signature(normalize_note(e)) not in here
               for e in state.get("imported_trash") or []):
            return True
        return any(isinstance(state.get(key), dict)
                   and any(day not in (getattr(self, attr, None) or {}) for day in state.get(key))
                   for key, attr in (("imported_day_colors", "day_colors"),
                                     ("imported_day_emoji", "day_emoji")))

    def _known_note_differs(self, mine, theirs, source):
        """Whether importing *theirs* over *mine* would change anything: a
        field the route may update, or -- from a backup, whose files are
        added and never swapped -- a file this device's copy lacks."""
        fields = (UPDATABLE_FROM_BACKUP if source == "backup"
                  else UPDATABLE_FROM_SHARED)
        if shared_update_changes(mine, theirs, fields):
            return True
        return source == "backup" and bool(self._files_to_adopt(mine, theirs))

    def _files_to_adopt(self, mine, theirs):
        """The attachments a backup's copy of a note has and *mine* lacks."""
        have = {a.get("stored_as") for a in mine.get("attachments") or []
                if isinstance(a, dict)}
        return [att for att in normalize_note(dict(theirs)).get("attachments") or []
                if att.get("stored_as") and att.get("stored_as") not in have]

    def _adopt_backup_attachments(self, mine, theirs):
        """Add the files a backup's copy of a note has and this one lacks --
        never swapping, so an update only brings files in; a file another
        note or a Trash entry owns gets a copy of its own, as the import's
        claimed files do.
        """
        have = {a.get("stored_as") for a in mine.get("attachments") or []
                if isinstance(a, dict)}
        # Trash entries are as the file held them: read through
        # attachments_of, as every reader of their files is.
        claimed = attachment_names_in(n for n in self.notes + self.trash
                                      if n is not mine)
        for att in self._files_to_adopt(mine, theirs):
            name = att.get("stored_as")
            if name in have:
                continue
            if len(mine.setdefault("attachments", [])) >= MAX_ATTACHMENTS:
                break
            att = dict(att)
            if name in claimed:
                new_name = copy_attachment_file(name)
                if not new_name:
                    continue
                att["stored_as"] = new_name
            mine["attachments"].append(att)
            have.add(att["stored_as"])

    def _do_inline_import(self):
        code = self.import_box.get("1.0", "end")
        try:
            shared = decode_share_code(code)
        except ValueError as e:
            self.import_status.config(text=str(e), fg=self.colors["danger_text"])
            return
        valid = [sn for sn in shared if isinstance(sn, dict)]
        if not valid:
            self.import_status.config(text="No valid notes in that code.",
                                      fg=self.colors["danger_text"])
            return
        # Trimmed at normalize, and SAID (19,000 items went in silence):
        # measured on the raw decode, the last sight of the sizes.
        def _ln(v):
            return len(v) if isinstance(v, (list, tuple)) else 0
        def _line_trimmed(sn):
            spans = sn.get("formatting")
            if not isinstance(spans, list) or len(spans) <= MAX_SPANS_PER_LINE:
                return False
            body = sn.get("body")
            clean = normalize_formatting(spans)
            return len(clamp_spans_per_line(
                body if isinstance(body, str) else "", clean)) < len(clean)

        oversized = sum(
            1 for sn in valid
            if _ln(sn.get("checklist")) > MAX_CHECKLIST_ITEMS
            or _ln(sn.get("attachments")) > MAX_ATTACHMENTS
            or _ln(sn.get("formatting")) > MAX_FORMATTING_SPANS
            or _line_trimmed(sn))
        if len(valid) == 1:
            incoming = valid[0]
            # Identity first: a note with a uid here IS that note, edited and
            # sent back; by its text it read as new, two copies left.
            mine = find_by_uid(self.notes, normalize_note(incoming).get("uid"))
            asked = False
            if mine is not None and not self._known_note_differs(
                    mine, incoming, "code"):
                # Exactly as it is here: nothing to update ("they differ" was
                # said unchecked), a copy only if asked for.
                copies = self._unchanged_copies([(mine, incoming)], 1, "code")
                if not copies:
                    self.import_status.config(
                        text="This note is already here, exactly as in the code.",
                        fg=self.colors["success_text"])
                    return
                incoming, asked = copies[0], True
                valid = [incoming]
            elif mine is not None:
                choice = self._themed_dialog(
                    "Same note, a different version",
                    "This note is already here, and the two differ.\n\n"
                    "Updating replaces what is on this device; you can undo "
                    "it with “↩ Restore previous”."
                    + (self._REPLACES_EARLIER_RESCUE
                       if self._holds_unspent_rescue(mine) else "")
                    + "\nAdding leaves both, so you can compare them and "
                    "delete one.",
                    kind="question",
                    buttons=[("Cancel", "cancel"),
                             ("Add as a new note", "add"),
                             ("Update this note", "update")],
                    default="Cancel",
                )
                if choice is None or choice == "cancel":
                    return
                if choice == "update":
                    # The editor's unsaved edits saved FIRST, for the rescue
                    # copy "↩ Restore previous" gives back; Cancel on a day's
                    # question stops here, nothing replaced.
                    if self._flush_autosave() is False:
                        return
                    apply_shared_update(mine, incoming)
                    self.save_notes()
                    self.import_box.delete("1.0", "end")
                    self.toggle_import_panel()
                    self.refresh_note_list()
                    self.render_calendar()
                    # flush=False, or the old version was saved over it; held
                    # already, it is read back as the other routes read it,
                    # its day and way back kept (wave 2, round 11).
                    if self.selected_note_id == mine.get("id"):
                        self._editor_follows_external_change({mine.get("id")})
                    else:
                        self.open_note_in_tab(mine, flush=False)
                    self.set_status("Note updated from the code "
                                    "— ↩ Restore previous undoes it")
                    return
                # "add" falls through to the import below, as a new note; its
                # uid dropped here, where the intent is (the review editor
                # would mint a fresh one anyway).
                incoming = dict(incoming)
                incoming.pop("uid", None)
                valid = [incoming]
                # Answered: not asked again as a look-alike of the note it is.
                asked = True
            existing_keys = {_dup_key(n) for n in self.notes}
            if not asked and _dup_key(normalize_note(incoming)) in existing_keys:
                choice = self._themed_dialog(
                    "Possible duplicate",
                    "This note looks identical to one you already have "
                    "(%s)." % SAME_AS,
                    kind="question",
                    # "Add": it is saved as a new note at once, as every
                    # other route that brings in a copy says.
                    buttons=[("Cancel", "cancel"), ("Add it anyway", "open")],
                    default="Add it anyway",
                )
                if choice is None or choice == "cancel":
                    return
            # Passed DOWN: _open_imported_note_in_editor sets its own status,
            # which overwrote one set here.
            if self._open_imported_note_in_editor(
                    incoming, trimmed=bool(oversized)) is False:
                # The person went back to the note in the editor, to fix a
                # date it could not save: the code stays in the box to try
                # again.
                return
            self.import_box.delete("1.0", "end")
            self.toggle_import_panel()
            return
        # Identity first: notes this batch says we already have.
        arrived = len(valid)
        proceed, valid, updates, unchanged, copies = self._take_known_notes(
            valid, "code")
        # The look-alike question counts what is left once the notes known
        # by identity are out; it says so, after a question that counted all.
        other = " other" if len(valid) < arrived else ""
        if not proceed:
            return
        if not valid and not copies:
            updated = self._apply_known_updates(updates, "code")
            if updated:
                self.save_notes()
            self.import_box.delete("1.0", "end")
            self.toggle_import_panel()
            self.refresh_note_list()
            self.render_calendar()
            self.set_status("Notes updated from the code "
                            "— ↩ Restore previous undoes each one" if updated
                            else "Everything in this code is already here, unchanged")
            return
        # Each note checked against what is here, by Find duplicates' rule: a
        # code imported twice made duplicates in silence.
        existing_keys = self._dup_keys_after(updates)
        fresh = [sn for sn in valid if _dup_key(normalize_note(sn)) not in existing_keys]
        dupe_count = len(valid) - len(fresh)
        to_import = valid
        if dupe_count > 0:
            if fresh:
                choice = self._themed_dialog(
                    "Possible duplicates",
                    f"{dupe_count} of the{other} {len(valid)} note(s) in this code "
                    f"look identical to notes you already have ({SAME_AS}).",
                    kind="question",
                    buttons=[("Cancel", "cancel"),
                             ("Import all anyway", "all"),
                             (f"Skip the {dupe_count} duplicate(s)", "skip")],
                    default=f"Skip the {dupe_count} duplicate(s)",
                )
            else:
                choice = self._all_lookalike_choice(len(valid), other, "code",
                                                    bool(updates or copies))
            if choice is None or choice == "cancel":
                return
            if choice == "skip":
                to_import = fresh
        # Every question is answered: only now do the updates happen.
        updated = self._apply_known_updates(updates, "code")
        # Counted once the questions are answered: a note saved while one
        # waited -- a new one's autosave -- took the id counted before it.
        next_id = max([n["id"] for n in self.notes], default=0) + 1
        added = 0
        arrived = []
        for sn in list(to_import) + copies:
            note = normalize_note(sn)
            note["id"] = next_id
            next_id += 1
            self.notes.append(note)
            arrived.append(note)
            added += 1
        self.save_notes()
        self.refresh_note_list()
        self.render_calendar()
        notes_word = "note" if added == 1 else "notes"
        self._say_hidden_arrivals(arrived, f"Added {added} {notes_word}")
        self.import_box.delete("1.0", "end")
        skipped_note = f" ({dupe_count} duplicate(s) skipped)" if dupe_count and to_import is not valid else ""
        oversize_note = (f" — {oversized} oversized note(s) trimmed to safe limits"
                         if oversized else "")
        known_note = ((f", updated {updated}" if updated else "")
                      + (f", {unchanged} already here" if unchanged else ""))
        self.import_status.config(
            text=f"Added {added} {notes_word}{known_note} ✓{skipped_note}{oversize_note}",
            fg=self.colors["success_text"])

    def toggle_share_panel(self):
        if self._is_placed(self.share_panel):
            self.share_panel.pack_forget()
            self._cancel_share_search()
        else:
            if self._is_placed(self.import_panel):
                self.import_panel.pack_forget()
            self._build_share_panel()
            self.share_panel.pack(fill="x", padx=8, pady=(0, 8))
        self._fit_sidebar_panel()

    def _build_share_panel(self):
        """Inline multi-note share: checkboxes to pick notes, then a generated
        code shown right here with a Copy button."""
        self._cancel_share_search()
        for w in self.share_panel.winfo_children():
            w.destroy()
        p = self.share_panel
        if not self.notes:
            tk.Label(p, text="No notes to share yet.", font=("Segoe UI", 8),
                     bg=self.colors["sidebar"], fg=self.colors["subtext"]
                     ).pack(padx=6, pady=6)
            return
        # The heading shares a row with "Select all", as the selection bar
        # above has: here a whole notebook meant a hundred clicks.
        head_row = tk.Frame(p, bg=self.colors["sidebar"])
        head_row.pack(fill="x", padx=6, pady=(6, 2))
        tk.Label(head_row, text="Pick notes to share:",
                 font=("Segoe UI", 8, "bold"), anchor="w",
                 bg=self.colors["sidebar"], fg=self.colors["text"]
                 ).pack(side="left")
        select_all_btn = tk.Button(
            head_row, text="Select all", command=lambda: toggle_select_all(),
            relief="flat", font=("Segoe UI", 8), cursor="hand2",
            bg=self.colors["card"], fg=self.colors["text"], bd=0)
        select_all_btn.pack(side="right", ipadx=4)

        # A search of its own, by the sidebar search's rule: a notebook of
        # hundreds of notes was a long scroll to the few wanted. No hint text
        # in the box, so there is no hint to be mistaken for a query.
        search_row = tk.Frame(p, bg=self.colors["card"])
        search_row.pack(fill="x", padx=6, pady=(0, 3))
        tk.Label(search_row, text="🔍", font=("Segoe UI", 8),
                 bg=self.colors["card"], fg=self.colors["subtext"]
                 ).pack(side="left", padx=(5, 0))
        query_var = self.share_search_var = tk.StringVar()
        search = tk.Entry(search_row, textvariable=query_var, relief="flat",
                          width=1, font=("Segoe UI", 9), bg=self.colors["card"],
                          fg=self.colors["text"],
                          insertbackground=self.colors["text"])
        # The caret, laid again by a theme switched while this is open.
        search.palette_keys = {"insertbackground": "text"}
        self._guard_entry_astral(search)
        self._add_paste_menu(search)
        search.pack(side="left", fill="x", expand=True, ipady=2, padx=(3, 0))
        clear = tk.Button(search_row, text="✕", command=lambda: query_var.set(""),
                          relief="flat", bd=0, cursor="hand2",
                          highlightthickness=0, font=("Segoe UI", 8, "bold"),
                          bg=self.colors["card"], fg=self.colors["subtext"],
                          activebackground=self.colors["card"],
                          activeforeground=self.colors["text"])
        clear.palette_keys = {"activebackground": "card",
                              "activeforeground": "text"}
        self.share_search_entry, self.share_search_clear = search, clear

        # Scrollable checklist (a notebook can have many notes). Fixed height so
        # it never grows the whole panel off-screen; the scrollbar handles the
        # overflow.
        list_wrap = tk.Frame(p, bg=self.colors["sidebar"],
                             height=self.SIDEBAR_PANEL_BODY["share"][0])
        list_wrap.pack(fill="x", padx=6, pady=(0, 2))
        list_wrap.pack_propagate(False)
        # What gives up rows first when the window is short (_fit_sidebar_panel).
        self._share_list_wrap = list_wrap
        canvas = tk.Canvas(list_wrap, bg=self.colors["sidebar"], highlightthickness=0)
        sb = ttk.Scrollbar(list_wrap, orient="vertical", command=canvas.yview)
        # Pages go in under the boxes already drawn, past what one frame can
        # scroll through (RowStack); each chunk spans the canvas.
        inner = self._row_stack(canvas, scrolled=sb.set).group(bg="sidebar",
                                                               every=32)
        # Pack scrollbar FIRST so it always keeps its width, then the canvas.
        sb.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)
        self._share_checklist_canvas = canvas

        # Plain colours, not track_theme(): rebuilt at every opening. Paged, as
        # the Trash is: a tick box per note slows with the notebook.
        self._share_vars = getattr(self, "_share_vars", {}) or {}
        SHARE_PAGE_SIZE = 100
        shown = {"n": SHARE_PAGE_SIZE}

        # What render_checkboxes drew: "Select all" ticks what is ON SCREEN,
        # not self.notes[:n] -- the list is paged and not live, and reading
        # the notes ticked ids with no tick box.
        rendered = {"ids": []}
        wheeled = set()     # the chunks given the wheel

        def _revealed():
            """The ids the panel is actually showing right now."""
            return list(rendered["ids"])

        def _all_revealed_ticked():
            ids = _revealed()
            return bool(ids) and all(
                self._share_vars.get(i) and self._share_vars[i].get()
                for i in ids)

        def toggle_select_all():
            want = not _all_revealed_ticked()
            for i in _revealed():
                if i in self._share_vars:
                    self._share_vars[i].set(want)
            refresh_select_all_label()

        def refresh_select_all_label():
            all_on = _all_revealed_ticked()
            try:
                select_all_btn.configure(
                    text="Unselect all" if all_on else "Select all")
            except tk.TclError:
                pass

        def offered():
            """The notes the panel offers: in the note list's order, pins
            first -- they came in the order they entered the notebook -- and
            narrowed by the search box, with the sidebar search's own rule."""
            notes = list(self.notes)
            self._sort_notes(notes)
            query = fold_for_search(query_var.get())
            if query:
                notes = [n for n in notes if self._query_in_texts(
                    query, self._cached_search_texts(n))]
            return notes

        offer = {"notes": []}

        def above_the_boxes(notes):
            """That the search hides some of what is picked -- Generate code
            shares those too -- or that it found nothing."""
            showing = {n["id"] for n in notes}
            hidden = sum(1 for n in self.notes if n["id"] not in showing
                         and self._share_vars.get(n["id"]) is not None
                         and self._share_vars[n["id"]].get())
            lines = []
            if hidden:
                lines.append(f"{hidden} picked note"
                             f"{' is' if hidden == 1 else 's are'} hidden by "
                             "this search")
            if not notes:
                lines.append("No notes match.")
            made = []
            for text in lines:
                line = tk.Label(inner.add(), text=text, font=("Segoe UI", 8),
                                anchor="w", justify="left",
                                wraplength=self.px(200),
                                bg=self.colors["sidebar"],
                                fg=self.colors["subtext"])
                line.pack(fill="x", pady=2)
                made.append(line)
            return made

        def render_checkboxes(first=0):
            """The tick boxes from *first* to the page's end, under any
            already drawn, and the button for the rest."""
            if first == 0:
                offer["notes"] = offered()
            notes = offer["notes"]
            visible_notes = notes[first:shown["n"]]
            rendered["ids"] = rendered["ids"][:first] + [
                n["id"] for n in visible_notes]
            made = above_the_boxes(notes) if first == 0 else []
            for n in visible_notes:
                if n["id"] not in self._share_vars:
                    self._share_vars[n["id"]] = tk.BooleanVar(value=False)
                var = self._share_vars[n["id"]]
                title = (n["title"].strip() or "(untitled)")[:24]
                extra = " 📎" if n.get("attachments") else ""
                cb = tk.Checkbutton(inner.add(), text=title + extra, variable=var,
                                    command=refresh_select_all_label,
                                    font=("Segoe UI", 8), anchor="w")
                self._drawn_tick_box(cb, "sidebar", "text", track=False)
                cb.pack(fill="x", anchor="w")
                made.append(cb)
            remaining = len(notes) - min(len(notes), shown["n"])
            if remaining > 0:
                more = tk.Button(inner.add(), text=f"Show {min(remaining, SHARE_PAGE_SIZE)} more "
                                                   f"({remaining} not shown)",
                                 relief="flat", cursor="hand2",
                                 bg=self.colors["card"], fg=self.colors["text"],
                                 font=("Segoe UI", 8))
                more.configure(command=lambda: show_more(more))
                more.pack(fill="x", pady=(4, 2))
                made.append(more)
            # The wheel, so scrolling works with the cursor anywhere over the
            # list: a new chunk and all in it once, then what a page adds.
            for w in [c for c in inner.chunks if c not in wheeled] + [
                    w for w in made if w.master in wheeled]:
                self._bind_mousewheel_recursive(w, self._share_checklist_canvas)
            wheeled.update(inner.chunks)
            # "Show 100 more" reveals notes that are not ticked, so a button
            # reading "Unselect all" would be wrong the moment the page grows.
            refresh_select_all_label()

        def redraw():
            inner.clear()
            wheeled.clear()
            rendered["ids"] = []
            render_checkboxes()

        def show_more(button):
            # Added under the boxes already drawn: drawing them all again
            # flickered, and grew with every page.
            first = shown["n"]
            shown["n"] += SHARE_PAGE_SIZE
            fresh = offered()
            if [n["id"] for n in fresh[:first]] != rendered["ids"]:
                # The notebook changed under the boxes on screen (a note
                # deleted, or saved to a new place in the order, while this
                # is open): all drawn again, or a note would have no box.
                redraw()
                return
            offer["notes"] = fresh
            button.destroy()
            render_checkboxes(first)

        def refilter():
            """Draw the list for the search as it stands now."""
            self._cancel_share_search()
            try:
                if not canvas.winfo_exists():
                    return
            except tk.TclError:
                return
            shown["n"] = SHARE_PAGE_SIZE
            redraw()
            canvas.yview_moveto(0)

        def follow_order():
            """Draw again when the list's order moved under the panel."""
            if [n["id"] for n in offered()][:shown["n"]] != rendered["ids"]:
                refilter()

        self._share_follow_order = follow_order

        def on_query(*_args):
            # The ✕ at once; the list after a pause in typing, as the
            # sidebar search does -- each draw is up to a page of boxes.
            try:
                if query_var.get():
                    if not self._is_placed(clear):
                        clear.pack(side="right", padx=(0, 4), before=search)
                elif self._is_placed(clear):
                    clear.pack_forget()
            except tk.TclError:
                return
            self._cancel_share_search()
            self._share_search_job = self.after(180, refilter)

        query_trace = query_var.trace_add("write", on_query)

        def drop_trace(_event=None):
            # Gone with the box: the trace held the variable, this closure and
            # every widget it names alive after each closing of the panel.
            try:
                query_var.trace_remove("write", query_trace)
            except tk.TclError:
                pass
        search.bind("<Destroy>", drop_trace, add="+")
        self._share_refilter = refilter
        render_checkboxes()

        gen_row = tk.Frame(p, bg=self.colors["sidebar"])
        gen_row.pack(fill="x", padx=6, pady=(4, 2))
        tk.Button(gen_row, text="Generate code", command=self._generate_inline_share,
                  bg=self.colors["accent"], fg=self._on_fill("accent"), relief="flat",
                  font=("Segoe UI", 9, "bold"), cursor="hand2"
                  ).pack(side="left", fill="x", expand=True, padx=(0, 3), ipady=3)
        tk.Button(gen_row, text="Close", command=self.toggle_share_panel,
                  bg=self.colors["card"], fg=self.colors["text"], relief="flat",
                  font=("Segoe UI", 9), cursor="hand2"
                  ).pack(side="left", fill="x", expand=True, padx=(3, 0), ipady=3)

        # The generated code appears here after "Generate code".
        self.share_code_area = tk.Frame(p, bg=self.colors["sidebar"])
        self.share_code_area.pack(fill="x", padx=6, pady=(0, 6))

    def _share_panel_follows(self):
        """Keep an open Share panel in the note list's order: a new sort, a
        pin or a move shows there at once (her re-test, case 594)."""
        follow = getattr(self, "_share_follow_order", None)
        if follow is not None and self._is_placed(self.share_panel):
            follow()

    def _cancel_share_search(self):
        """Call off the Share panel's search waiting for a pause in typing:
        it is about to draw now, or its panel is closing or drawn anew."""
        job = getattr(self, "_share_search_job", None)
        self._share_search_job = None
        if job is not None:
            try:
                self.after_cancel(job)
            except (tk.TclError, ValueError):
                pass

    def _generate_inline_share(self):
        chosen = [n for n in self.notes if self._share_vars.get(n["id"]) and self._share_vars[n["id"]].get()]
        for w in self.share_code_area.winfo_children():
            w.destroy()
        if not chosen:
            tk.Label(self.share_code_area, text="Pick at least one note.",
                     font=("Segoe UI", 8), bg=self.colors["sidebar"],
                     fg=self.colors["danger_text"]).pack(anchor="w")
            return
        had_attachments = any(n.get("attachments") for n in chosen)
        try:
            code = encode_share_code(chosen)
        except ShareCodeTooLarge as exc:
            tk.Label(self.share_code_area, text=str(exc), font=("Segoe UI", 8),
                     bg=self.colors["sidebar"], fg=self.colors["danger_text"],
                     justify="left", wraplength=self.px(200)).pack(anchor="w")
            self._fit_sidebar_panel()
            return
        self._render_inline_code(self.share_code_area, code, len(chosen), had_attachments)
        # The code needs room of its own; in a short window it is made here.
        self._fit_sidebar_panel()

    def _clear_inline_code(self, area):
        """Take a generated share code off the panel: its children destroyed,
        the frame kept in the layout, as _generate_inline_share does --
        deferred, as the ✕ calling this lives inside it (a documented Tk
        hazard, which a test could not press to show).
        """
        def clear():
            for w in area.winfo_children():
                w.destroy()
            # The room the code took is given back (_fit_sidebar_panel).
            self._fit_sidebar_panel()
        self.after_idle(clear)

    def _render_inline_code(self, parent, code, count, had_attachments):
        """Show a generated code inline with a Copy button (used by share)."""
        noun = "note" if count == 1 else "notes"
        head = tk.Frame(parent, bg=self.colors["sidebar"])
        head.pack(fill="x", pady=(4, 2))
        # "chars": a 250px sidebar at font 8 clips the editor's wording; the
        # count is this panel's own, as it shares several notes.
        tk.Label(head, text=f"Code for {count} {noun} ({len(code)} chars):",
                 font=("Segoe UI", 8, "bold"), anchor="w",
                 bg=self.colors["sidebar"], fg=self.colors["text"]
                 ).pack(side="left")
        # The editor's code area has always had an ✕; this one could only be
        # dismissed by closing the whole Share panel.
        tk.Button(head, text="✕", command=lambda p=parent: self._clear_inline_code(p),
                  bg=self.colors["sidebar"], fg=self.colors["subtext"],
                  relief="flat", font=("Segoe UI", 9, "bold"),
                  cursor="hand2", bd=0).pack(side="right")
        if had_attachments:
            tk.Label(parent, text=self.SHARE_ATTACHMENT_WARNING,
                     font=("Segoe UI", 7), anchor="w", wraplength=self.px(200),
                     justify="left",
                     bg=self.colors["sidebar"], fg=self.colors["danger_text"]
                     ).pack(fill="x", pady=(0, 2))
        box = tk.Text(parent, height=3, wrap="char", font=("Consolas", 7),
                      relief="flat", bg=self.colors["card"], fg=self.colors["text"],
                      padx=6, pady=6)
        box.insert("1.0", code)
        box.config(state="disabled")
        box.pack(fill="x")
        status = tk.Label(parent, text="", font=("Segoe UI", 7), anchor="w",
                          bg=self.colors["sidebar"], fg=self.colors["success_text"])
        status.pack(fill="x")

        def copy():
            try:
                self.clipboard_clear()
                self.clipboard_append(code)
                self.update()
                status.config(text="Copied to clipboard ✓", fg=self.colors["success_text"])
            except tk.TclError:
                status.config(text="Select the code and copy manually.",
                              fg=self.colors["danger_text"])
        tk.Button(parent, text="📋 Copy code", command=copy, bg=self.colors["accent"],
                  fg=self._on_fill("accent"), relief="flat", font=("Segoe UI", 9, "bold"),
                  cursor="hand2"
                  ).pack(fill="x", pady=(4, 0), ipady=3)

    def export_note_as_file(self, note, fmt):
        """Write one note to a standalone file the rest of the world reads:
        HTML with everything it has -- the road to PDF (Ctrl+P) and Word --
        or plain text, the body as stored. Files travel only in a Backup.
        """
        title = (note.get("title") or "").strip() or "Untitled note"
        kinds = {"html": ("HTML file", ".html"),
                 "txt": ("Text file", ".txt")}
        label, ext = kinds[fmt]
        # A title is prose; a filename is not. Strip what Windows forbids.
        path = self._while_native(lambda: filedialog.asksaveasfilename(
            title=f"Export “{title}” as a {label.lower()}",
            defaultextension=ext,
            initialfile=export_file_stem(title) + ext,
            filetypes=[(label, "*" + ext), ("All files", "*.*")]))
        if not path:
            return
        content = self._note_export_content(note, fmt, title)
        # tmp-then-replace, like the backup zip: re-exporting over an
        # existing file plus a mid-write failure used to destroy it.
        tmp_path = path + ".tmp"
        try:
            with open(tmp_path, "w", encoding="utf-8") as f:
                f.write(content)
                # On the disk before it replaces a file of that name.
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_path, path)
        except (IOError, OSError) as exc:
            try:
                os.remove(tmp_path)
            except OSError:
                pass
            self.show_error("Export failed",
                            f"Couldn't write the file:\n{exc}")
            return
        self._show_toast(f"Exported to {os.path.basename(path)}")
        if note.get("attachments"):
            self.set_status(
                "Attached files aren't part of a note export — "
                "use Settings → Backup → Export for those.")
        # The file is the only honest preview, in the browser's fonts: offered
        # at once, for a tight adjust-and-export loop.
        if self.ask_yes_no(
                "Open it now?",
                f"“{os.path.basename(path)}” was saved.\n\n"
                "Open it to see how the note lays out on the page?",
                icon="question"):
            try:
                os.startfile(path)
            except OSError:
                self.set_status(f"Saved to {path}")

    def _note_export_content(self, note, fmt, title):
        """One note rendered for one export format -- shared by the
        single-note export and the bulk export, so the two can never
        drift apart."""
        body = note.get("body", "")
        comments = (note.get("comments") or "").strip()
        # The checklist is its own section beside the body, like the
        # comments -- content, not chrome, so it exports with the note.
        checklist = note.get("checklist") or []
        if fmt == "html":
            fragment = note_to_html(body, note.get("formatting"),
                                    note.get("paragraphs"))
            if checklist:
                # Glyphs, not <input> boxes: a disabled form control is
                # at Word's mercy; a character renders everywhere.
                items = "\n".join(
                    "<div>{} {}</div>".format(
                        "☑" if it.get("done") else "☐",
                        escape(it.get("text", "")))
                    for it in checklist)
                fragment += ("<hr>\n<div><i>Checklist</i></div>\n" + items)
            if comments:
                fragment += ("<hr>\n<div><i>Comments</i></div>\n"
                             + note_to_html(comments))
            content = html_document(title, fragment)
        else:
            content = title + "\n\n" + body
            if checklist:
                content += "\n\nChecklist:\n" + "\n".join(
                    "[{}] {}".format("x" if it.get("done") else " ",
                                     it.get("text", ""))
                    for it in checklist)
            if comments:
                content += "\n\nComments:\n" + comments
            content += "\n"
        # A just-typed emoji arrives as lone surrogates, which a utf-8 write
        # refused with an error no guard caught: mended at this one choke
        # point, as the code and disk writes are.
        return mend_surrogates(content)

    def share_current_note_as_code(self, copy=False):
        """Generate a share code for the note currently open and show it inline
        in the editor (no pop-up), with a Copy button -- which makes it again
        from the note as it is then (*copy*): an edit made after Generate was
        missing from the code that went out, with nothing on screen to say so."""
        made = self._code_for_open_note()
        if made is None:
            return
        code, had_attachments = made
        # Render inline in the editor's code area.
        for w in self.editor_code_area.winfo_children():
            w.destroy()
        if not self._is_placed(self.editor_code_area):
            self.editor_code_area.pack(fill="x", padx=30, pady=(0, 20))
        self._render_editor_code(code, had_attachments, copy=copy)

    def _code_for_open_note(self):
        """The share code of the note in the editor, and whether it has files
        a code does not carry -- or None, the reason said on the status line.
        One day of a series (day mode) travels as a note of that date: the
        series' identity and repeat went with the day's words, and an Update
        on the other device wrote that one day over the whole series."""
        # Asking for a code is finishing with the fields: a date typed short
        # is settled first (17.10 -> 17.10.2026), so the code carries it.
        self._settle_date_fields()
        st = self.capture_editor_state()
        # The shared content test less attachments, which a code cannot carry:
        # a hand-rolled one refused a checklist-only note.
        shareable = {k: v for k, v in st.items() if k != "attachments"}
        if not self._editor_state_has_content(shareable):
            self.set_status(
                "Nothing to share yet — a code carries a note's title, "
                "text, comments, checklist and repeat rule.")
            return None
        # From SHAREABLE_FIELDS, never by hand: seven fields named here lost
        # the formatting and checklist added later.
        note = {k: st.get(k) for k in SHAREABLE_FIELDS if st.get(k) is not None}
        # The date and repeat a save would store, not the raw field: a code
        # that carried "30.09.2026" delivered a date no save could keep,
        # and every edit to the note that arrived was lost on the far end.
        note["date"], note["recurrence"], _left_out = self._date_and_repeat_to_store()
        # The identity is the open note's, not the snapshot's: dropped, the far
        # end could not recognise its copy and added a second. A note never
        # saved has none yet.
        open_note = (self.find_note(st.get("selected_note_id"))
                     if st.get("selected_note_id") is not None else None)
        if self._day_mode():
            note["date"] = self.current_occurrence_date
            note["recurrence"] = dict(RECURRENCE_DEFAULTS)
        elif open_note and str(open_note.get("uid") or "").strip():
            note["uid"] = open_note["uid"]
        try:
            return encode_share_code(note), bool(st["attachments"])
        except ShareCodeTooLarge as exc:
            self.set_status(str(exc))
            return None

    def _editor_follows_external_change(self, changed_ids):
        """Make the editor agree with notes rewritten behind it, or its next
        save put the old version back (field report: the note sent out is
        the one open when its code returns). Callers flush first, so the
        typing is in the rescue copy.
        """
        if self.selected_note_id is None or self.selected_note_id not in changed_ids:
            return
        note = self.find_note(self.selected_note_id)
        if note is not None:
            # Read back, the note keeps its way back to the calendar, as a move
            # does (_relocate_day): opening cleared it.
            pending = getattr(self, "_pending_calendar_return", None)
            self.open_note_in_tab(note, self.current_occurrence_date, flush=False)
            if pending is not None:
                self._pending_calendar_return = pending
                self._update_calendar_return_button()

    def _share_code_on_context_switch(self):
        """Another note is in the editor, so the code under it is cleared --
        it read as the new note's, and was shared as the wrong one (field
        report). Cleared where the find bar's matches are
        (_find_on_context_switch).
        """
        area = self.editor_code_area
        if area is None:
            return
        try:
            if self._is_placed(area):
                area.pack_forget()
            for w in area.winfo_children():
                w.destroy()
        except tk.TclError:
            # Teardown: the editor is going away and the code with it.
            pass

    def _render_editor_code(self, code, had_attachments, copy=False):
        # Plain colours, not track_theme(): rebuilt at every "Copy code".
        parent = self.editor_code_area
        header = tk.Frame(parent, bg=self.colors["bg"])
        header.pack(fill="x")
        tk.Label(header, text=f"Share code ({len(code)} characters):",
                 font=("Segoe UI", 9, "bold"), anchor="w",
                 bg=self.colors["bg"], fg=self.colors["text"]).pack(side="left")
        tk.Button(header, text="✕", command=lambda: self.editor_code_area.pack_forget(),
                  bg=self.colors["bg"], fg=self.colors["subtext"], relief="flat",
                  font=("Segoe UI", 10, "bold"), cursor="hand2").pack(side="right")
        if had_attachments:
            tk.Label(parent, text=self.SHARE_ATTACHMENT_WARNING,
                     font=("Segoe UI", 8), anchor="w", wraplength=self.px(600),
                     justify="left",
                     bg=self.colors["bg"], fg=self.colors["danger_text"]
                     ).pack(fill="x", pady=(2, 2))
        box = tk.Text(parent, height=3, wrap="char", font=("Consolas", 9),
                      relief="flat", bg=self.colors["card"], fg=self.colors["text"],
                      padx=10, pady=8)
        box.insert("1.0", code)
        box.config(state="disabled")
        box.pack(fill="x", pady=(2, 4))
        status = tk.Label(parent, text="", font=("Segoe UI", 8), anchor="w",
                          bg=self.colors["bg"], fg=self.colors["success_text"])
        status.pack(fill="x")

        if copy:
            try:
                self.clipboard_clear()
                self.clipboard_append(code)
                self.update()
                status.config(text="Copied to clipboard ✓", fg=self.colors["success_text"])
            except tk.TclError:
                status.config(text="Select the code above and copy it manually (Ctrl+C).",
                              fg=self.colors["danger_text"])
        tk.Button(parent, text="📋 Copy code",
                  command=lambda: self.share_current_note_as_code(copy=True), bg=self.colors["accent"],
                  fg=self._on_fill("accent"), relief="flat", font=("Segoe UI", 10, "bold"),
                  cursor="hand2"
                  ).pack(fill="x", pady=(2, 0), ipady=5)

    def _open_imported_note_in_editor(self, shared_note, trimmed=False):
        """Load an imported single note into a fresh editor tab as a NEW note
        (no selected_note_id), where the person reviews it. The autosave keeps
        it as it keeps any note typed there, half a second on."""
        note = normalize_note(shared_note)
        self.notebook.select(self.TAB_NOTES)
        # A clean new-note editor -- unless the person chose to stay on a
        # repeating day's edit, and then nothing here may touch the editor.
        if self.open_blank_tab() is False:
            return False
        # The arriving identity goes into its first save, unless a note here
        # wears it (dropped, it came back a stranger) -- read from what
        # arrived, as normalize_note mints one.
        uid = str(shared_note.get("uid") or "").strip()
        self._arrived_uid = (uid if uid and find_by_uid(self.notes, uid) is None
                             else "")

        self.title_entry.delete(0, "end")
        title = note.get("title", "")
        if title:
            self._insert_title(title)
            self.title_entry.config(fg=self.colors["text"])

        self.body_text.delete("1.0", "end")
        self.body_text.insert("1.0", note.get("body", ""))
        self._apply_formatting(self.body_text, note.get("formatting", []))
        self._apply_paragraphs(self.body_text, note.get("paragraphs", []))
        self._render_table_grids()
        self.comments_text.delete("1.0", "end")
        self.comments_text.insert("1.0", note.get("comments", ""))

        self._show_date_in_field(note.get("date"))

        cat = note.get("category", "General")
        self.category_var.set(cat if cat in CATEGORY_COLORS else "General")

        self.current_note_color = note.get("color", "")
        self._update_color_swatch()

        self.write_recurrence_to_ui(note.get("recurrence"))

        # Bring the imported note's checklist along -- the one field this
        # loader used to skip, so a shared checklist vanished on import
        # even when the code carried it. Same idiom as loading a template.
        self._working_checklist = [
            {"text": it.get("text", ""), "done": bool(it.get("done"))}
            for it in note.get("checklist", []) if isinstance(it, dict)
        ]
        if hasattr(self, "_checklist_rows"):
            self._render_checklist_items()
        if self._working_checklist and not self._checklist_open:
            self.toggle_checklist_section()
        else:
            self._sync_checklist_open_state()

        self.update_word_count()
        # Ctrl+Z starts from the note as it arrived: the import was Tk's first
        # step, and Ctrl+Z emptied the note, saved so.
        self._reset_text_undo()
        self.set_status(
            "Imported from code — trimmed to the app's size limits; saved as "
            "a new note, review it here" if trimmed
            else "Imported from code — saved as a new note, review it here")
        if trimmed:
            # A note arriving SHORTER than sent is said in a dialog, as the
            # backup's report is: the autosave overwrote the status line.
            self.show_info(
                "Part of this note was left out",
                "The note in that code was larger than one note can hold, "
                "so it arrived trimmed to the app's limits "
                f"({MAX_CHECKLIST_ITEMS} checklist items, "
                f"{MAX_ATTACHMENTS} files, "
                f"{MAX_FORMATTING_SPANS} styled spans, "
                f"{MAX_SPANS_PER_LINE} of them on any one line).\n\n"
                "Nothing of yours was touched — this is only about what "
                "arrived. It is saved as a new note: review it, and delete "
                "it if you do not want it.")
        return True

    def import_data(self):
        """Import a previously exported .zip, MERGED into the notes here, never
        over them. The slow parts run on a background thread, as the export
        does (it froze the app)."""
        # Same one-at-a-time guard as export_data (audit Z05-F05).
        if self._export_state is not None or self._import_state is not None:
            self.set_status("An export or import is already running — "
                            "let it finish first.")
            return
        # A run that saves no notes took the backup's Trash and templates and
        # said "Import complete", its notes in no file (round 4 of the audit).
        if _core_paths.writes_held(DATA_FILE):
            self.show_warning(
                "Import after reopening",
                "When Note Organizer started it could not open your notes, so "
                "nothing is saved in this session, and an import now would be "
                "lost when the app closes. Close Note Organizer, open it "
                "again, and import then.")
            return
        zip_path = self._while_native(lambda: filedialog.askopenfilename(
            title="Choose a notes backup (.zip) to import",
            filetypes=[("Zip files", "*.zip")]
        ))
        if not zip_path:
            return

        confirm = self.ask_yes_no(
            "Import notes",
            "This will ADD the notes from that backup to your current list. "
            "Nothing you have is removed, and a note you already have is "
            "only replaced if you choose to update it.\n\n"
            "Continue?"
        )
        if not confirm:
            return

        # "copied": the files the worker put in the attachments folder, so
        # an import the window closes on can take them back out again (see
        # _settle_background_work_at_close).
        self._import_state = {"phase": "extracting", "current": 0, "total": 1,
                              "done": False, "error": None,
                              "temp_dir": None, "imported_notes": None,
                              "copied": [], "zip": zip_path}
        self.export_progress_bar.configure(maximum=1, value=0)
        self.export_progress_lbl.config(text="Importing… reading backup")
        self.export_progress_frame.place(relx=0.5, rely=1.0, anchor="s", y=-14)
        self.export_progress_frame.lift()

        def worker():
            state = self._import_state

            def stop():
                return state.get("stop")   # asked by the close, at once
            try:
                temp_dir = tempfile.mkdtemp(prefix="notes_import_")
                state["temp_dir"] = temp_dir
                try:
                    with open(zip_path, "rb") as raw, \
                            zipfile.ZipFile(StoppableFile(raw, stop), "r") as zf:
                        _safe_extract_zip(zf, temp_dir, ATTACHMENTS_DIR)
                except (zipfile.BadZipFile, IOError, OSError, ValueError) as e:
                    state["error"] = f"That file couldn't be read as a backup:\n{e}"
                    state["done"] = True
                    return

                imported_notes_path = os.path.join(temp_dir, "notes_data.json")
                if not os.path.exists(imported_notes_path):
                    state["error"] = "This .zip doesn't look like a Note Organizer backup."
                    state["done"] = True
                    return

                try:
                    with open(imported_notes_path, "r", encoding="utf-8") as f:
                        imported_notes = json_from_text(f.read())
                except (*_core_paths.JSON_UNREADABLE, IOError) as e:
                    state["error"] = f"Couldn't read the notes in that backup:\n{e}"
                    state["done"] = True
                    return
                if not isinstance(imported_notes, list):
                    # null or a number raised on the main thread after the
                    # import's state was cleared, so its cleanup never ran.
                    state["error"] = "This .zip doesn't look like a Note Organizer backup."
                    state["done"] = True
                    return
                state["imported_notes"] = imported_notes
                # Templates and trash ride along when the backup has them
                # (older backups don't — both stay optional, and a bad
                # file skips quietly: the notes are the payload).
                for extra, key in (("templates.json", "imported_templates"),
                                   ("trash.json", "imported_trash")):
                    extra_path = os.path.join(temp_dir, extra)
                    if os.path.exists(extra_path):
                        try:
                            with open(extra_path, "r", encoding="utf-8") as f:
                                loaded = json_from_text(f.read())
                            if isinstance(loaded, list):
                                state[key] = loaded
                        except (*_core_paths.JSON_UNREADABLE, IOError, OSError):
                            pass
                # The backup's settings.json, never read back, re-filed every
                # unknown category under General. Its categories, calendar
                # marks and Trash window are taken; the rest is this device's.
                settings_path = os.path.join(temp_dir, "settings.json")
                if os.path.exists(settings_path):
                    try:
                        with open(settings_path, "r", encoding="utf-8") as f:
                            loaded = json_from_text(f.read())
                        cats = loaded.get("categories") if isinstance(loaded, dict) else None
                        if isinstance(cats, dict):
                            state["imported_categories"] = cats
                        # The day colours and markers came back bare, too.
                        # Raw dicts here (worker thread); the merge on the
                        # main thread validates them.
                        if isinstance(loaded, dict):
                            for decor_key in ("day_colors", "day_emoji"):
                                decor = loaded.get(decor_key)
                                if isinstance(decor, dict):
                                    state["imported_" + decor_key] = decor
                            if "trash_retention_days" in loaded:
                                state["imported_trash_window"] = loaded["trash_retention_days"]
                    except (*_core_paths.JSON_UNREADABLE, IOError, OSError):
                        pass

                # Copy any attached files from the backup into our attachments
                # folder — the slowest part for a backup with a lot of them.
                imported_attachments_dir = os.path.join(temp_dir, "attachments")
                state["phase"] = "copying"
                # A backup downloaded from the internet is marked so by
                # Windows; each file taken out of it carries the same mark,
                # or SmartScreen and Office's Protected View never see it.
                zone_mark = zone_mark_of(zip_path)
                if os.path.isdir(imported_attachments_dir):
                    files = os.listdir(imported_attachments_dir)
                    state["total"] = max(len(files), 1)
                    for i, filename in enumerate(files, start=1):
                        dest = os.path.join(ATTACHMENTS_DIR, filename)
                        if not os.path.exists(dest):
                            # Copy beside, replace whole: a copy cut short
                            # left a truncated file this guard then kept.
                            part = dest + ".part"
                            try:
                                copy_file_until_stopped(
                                    os.path.join(imported_attachments_dir, filename),
                                    part, stop)
                                # Marked before it is in place, so it is never
                                # there unmarked; the rename keeps the mark.
                                put_zone_mark(part, zone_mark)
                                os.replace(part, dest)
                                state["copied"].append(filename)
                            except (IOError, OSError):
                                try:
                                    os.remove(part)
                                except OSError:
                                    pass
                                # non-critical — the note metadata still gets imported
                        state["current"] = i
            except Exception as e:
                # Last resort: an uncaught error kills the thread silently and
                # the bar polls forever for a "done" that never comes.
                state["error"] = f"Import failed unexpectedly:\n{e}"
            state["done"] = True

        self._start_io_worker(worker)
        self._poll_import_progress()

    def _poll_import_progress(self):
        """Runs on the main thread only, on a timer — mirrors
        _poll_export_progress. Reads the plain dict the background import
        thread updates; once the slow I/O is done, hands off to the
        (fast, in-memory) duplicate-check dialog and the actual merge."""
        if not self._still_alive():
            return
        state = self._import_state
        if state is None:
            return
        if state["phase"] == "extracting":
            self.export_progress_lbl.config(text="Importing… reading backup")
        elif state["done"] and (self._a_dialog_is_asking() or getattr(self, "_natives_open", 0)):
            # Said as what it is: "0 / 1 attachments" stood for a backup with
            # none, waiting on another question (wave 2, round 12).
            self.export_progress_bar.configure(maximum=1, value=1)
            self.export_progress_lbl.config(text="Import ready — waiting for your answer above")
        else:
            self.export_progress_bar.configure(maximum=state["total"], value=state["current"])
            self.export_progress_lbl.config(
                text=f"Importing… {state['current']} / {state['total']} attachments")

        # Its merge waits for a question already open: run inside a share
        # code's, the backup's notes took the ids that import had counted
        # before it asked, and the two wore one id (wave 2, round 11).
        if not state["done"] or self._a_dialog_is_asking() or getattr(self, "_natives_open", 0):
            self._export_poll_job = self.after(100, self._poll_import_progress)
            return

        self.export_progress_frame.place_forget()
        self._import_state = None
        # Its questions wait on the person with the files already copied: the
        # end of a Windows session meets it here too (round 7 of the audit).
        self._import_asking = state
        try:
            self._merge_finished_import(state)
        finally:
            # Answered: the line a session end left for the next start, in
            # case it ended, is untrue now (_settle_backups_at_session_end).
            if state.get("asked_at_session_end"):
                self._take_back_cut_short("import")
            self._import_asking = None

    def _merge_finished_import(self, state):
        """The main thread's half of an import whose worker is done: its
        questions, then the merge, or the files it copied taken back out."""
        temp_dir = state["temp_dir"]

        if state["error"]:
            # A worker that failed partway may have copied files already.
            self._drop_unclaimed_import_files(state)
            # Settled before it is said: a session that ends with the
            # failure on screen leaves no word of an import cut short -- nor
            # its unpacked folder, which no later start would know of (round 9).
            self._import_asking = None
            if temp_dir:
                shutil.rmtree(temp_dir, ignore_errors=True)
            if state.get("stop"):
                # Stopped by the end of a Windows session that went on after
                # all (_settle_backups_at_session_end): not a failure.
                self.set_status(self._IMPORT_STOPPED_AT_SESSION_END)
            else:
                self.show_error("Import failed", state["error"])
            return

        imported_notes = state["imported_notes"]
        # Merged with new local ids, after the duplicate check "Import code"
        # makes: notes already here were merged in again unasked.
        valid_notes = [n for n in imported_notes if isinstance(n, dict)]

        # The categories come in before the duplicate scan (re-filed, a note
        # read as a duplicate), additive, sanitized, in MEMORY until the
        # dialog's answer: this list is rolled back on Cancel.
        added_names = []
        refused_categories = 0
        for name, color in list(
                (state.get("imported_categories") or {}).items())[:MAX_CATEGORIES]:
            color = sanitize_color(color)
            name = name.strip() if isinstance(name, str) else ""
            if not (name and color) or name in CATEGORY_COLORS:
                continue
            # Skipped whole, never cut short (its notes would match nothing,
            # as load_categories records): the door refuses what the loader
            # will not keep, and the dialog says so.
            if category_name_refusal(name) is not None:
                refused_categories += 1
                continue
            CATEGORY_COLORS[name] = color
            added_names.append(name)
        added_categories = len(added_names)

        def _undo_category_merge():
            """Take back what was never agreed to."""
            for _n in added_names:
                CATEGORY_COLORS.pop(_n, None)
            added_names.clear()

        # Identity first, exactly as the share-code route asks it.
        arrived = len(valid_notes)
        proceed, valid_notes, updates, unchanged, copies = self._take_known_notes(
            valid_notes, "backup")
        # Counted as what is left once the notes known by identity are out.
        other = " other" if len(valid_notes) < arrived else ""
        if not proceed:
            _undo_category_merge()
            # The unpacked backup goes, as on Cancel below (it stayed in the
            # temp folder), and the files copied: no note owns them.
            shutil.rmtree(temp_dir, ignore_errors=True)
            self._drop_unclaimed_import_files(state)
            self._say_import_cancelled()
            return
        existing_keys = self._dup_keys_after(updates)
        fresh = [n for n in valid_notes if _dup_key(normalize_note(n)) not in existing_keys]
        dupe_count = len(valid_notes) - len(fresh)
        to_import = valid_notes
        if dupe_count > 0:
            if fresh:
                choice = self._themed_dialog(
                    "Possible duplicates",
                    f"{dupe_count} of the{other} {len(valid_notes)} note(s) in this "
                    f"backup look identical to notes you already have ({SAME_AS}).",
                    kind="question",
                    buttons=[("Cancel", "cancel"),
                             ("Import all anyway", "all"),
                             (f"Skip the {dupe_count} duplicate(s)", "skip")],
                    default=f"Skip the {dupe_count} duplicate(s)",
                )
            else:
                choice = self._all_lookalike_choice(
                    len(valid_notes), other, "backup",
                    bool(updates or copies) or self._backup_brings_more(state, added_names))
            if choice is None or choice == "cancel":
                _undo_category_merge()
                shutil.rmtree(temp_dir, ignore_errors=True)
                self._drop_unclaimed_import_files(state)
                self._say_import_cancelled()
                return
            if choice == "skip":
                to_import = fresh
                # A look-alike's files go to the note it looks like: skipped
                # whole, they were deleted with it (wave 2, round 14).
                twins = {_dup_key(n): n for n in self.notes}
                for n in valid_notes:
                    twin = twins.get(_dup_key(normalize_note(n)))
                    if twin is not None and not any(n is f for f in fresh):
                        self._adopt_backup_attachments(twin, n)

        # Agreed to: only now do the categories reach disk and the sidebar.
        if added_categories:
            persist_categories()
            self.refresh_category_widgets()
        # ...then the updates, before the file scan (they bring files). Files
        # alone make no rescue copy, so are counted apart, as the phone does.
        files_only = sum(
            1 for mine, theirs in updates
            if not shared_update_changes(mine, theirs, UPDATABLE_FROM_BACKUP)
            and self._files_to_adopt(mine, theirs))
        updated = self._apply_known_updates(updates, "backup") - files_only

        # Day colours and markers, additive (a day decorated here keeps its
        # own) and validated as the start's are (_take_day_decorations).
        restored_decor = self._take_day_decorations(
            state.get("imported_day_colors"), state.get("imported_day_emoji"))
        if restored_decor:
            save_setting("day_colors", dict(self.day_colors))
            save_setting("day_emoji", dict(self.day_emoji))

        # The Trash's window comes along where none was chosen here, never
        # shorter than the default (ISSUES_LOG: "The Trash restored under a
        # window it never had"); a chosen one stays.
        window = state.get("imported_trash_window")
        if (isinstance(window, int) and not isinstance(window, bool)
                and TRASH_RETENTION_DAYS < window <= 365
                and state.get("imported_trash")
                and "trash_retention_days" not in load_settings()
                and not get_setting(TRASH_WINDOW_UNKNOWN)):
            choose_trash_window(window)

        # A file already claimed (note, Trash, this import) gets its own copy,
        # as in duplicate_note; read through attachments_of (a 7 stopped it).
        claimed = attachment_names_in(self.notes + self.trash)
        next_id = max([n["id"] for n in self.notes], default=0) + 1
        # With the copies asked for of notes already here, past the
        # look-alike question: they were just asked about, by name.
        arrived = []
        for note in list(to_import) + copies:
            note = normalize_note(note)
            for a in note.get("attachments", []):
                if not isinstance(a, dict):
                    continue
                name = a.get("stored_as")
                if name in claimed:
                    new_name = copy_attachment_file(name)
                    if new_name:
                        a["stored_as"] = new_name
                        claimed.add(new_name)
                elif name:
                    claimed.add(name)
            note["id"] = next_id
            next_id += 1
            self.notes.append(note)
            arrived.append(note)

        # Templates and Trash merge ADDITIVELY. Names in a set, MAX_TEMPLATES
        # in all: 20,000 checked pairwise took fourteen seconds.
        added_templates = 0
        template_names = {t.get("name") for t in self.templates}
        for tpl in (state.get("imported_templates") or []):
            if len(self.templates) >= MAX_TEMPLATES:
                break
            if not isinstance(tpl, dict):
                continue
            tpl = normalize_template(tpl)
            if tpl.get("name") and tpl["name"] not in template_names:
                self.templates.append(tpl)
                template_names.add(tpl["name"])
                added_templates += 1
        if added_templates:
            save_templates(self.templates)
        added_trash = 0
        # Skipped unasked, so the test is identity (content_signature), not
        # _dup_key's resemblance: a trashed note differing only in its date
        # or files was dropped, its only copy.
        existing_trash_keys = {content_signature(normalize_note(e))
                               for e in self.trash if isinstance(e, dict)}
        for entry in (state.get("imported_trash") or []):
            if not isinstance(entry, dict):
                continue
            raw_deleted = entry.get("deleted_at")
            # Through normalize_note (a deleted_at=5 crashed the Trash's
            # sort); deleted_at, which it drops, comes back as a str only.
            entry = normalize_note(entry)
            entry["deleted_at"] = (raw_deleted
                                   if isinstance(raw_deleted, str) else "")
            key = content_signature(entry)
            if key in existing_trash_keys:
                # Re-importing your own backup must not double the trash.
                continue
            existing_trash_keys.add(key)
            # Same claimed-file discipline as the notes above: a trashed
            # entry pointing at a file an ACTIVE note owns would, on its
            # later purge, delete that file out from under the note.
            atts = []
            for a in (entry.get("attachments") or []):
                if not isinstance(a, dict):
                    continue
                a = dict(a)
                name = a.get("stored_as")
                if name in claimed:
                    new_name = copy_attachment_file(name)
                    if new_name:
                        a["stored_as"] = new_name
                        claimed.add(new_name)
                elif name:
                    claimed.add(name)
                atts.append(a)
            entry["attachments"] = atts
            self.trash.append(entry)
            added_trash += 1
        if added_trash:
            save_trash(self.trash)

        # The save makes notes '(earlier text)' of what a series' copy kept
        # (_set_aside_days); its banner goes under this dialog, so the
        # dialog says them too (the phone's twenty-third round).
        before = len(self.notes)
        self.save_notes()
        earlier = len(self.notes) - before
        self.refresh_note_list()
        self.render_calendar()
        shutil.rmtree(temp_dir, ignore_errors=True)
        # The skipped duplicates' files were copied too, and nothing owns
        # them now.
        self._drop_unclaimed_import_files(state)

        skipped_note = f" ({dupe_count} duplicate(s) skipped)" if dupe_count and to_import is not valid_notes else ""
        extras_note = ""
        parts = []
        if added_categories:
            parts.append(f"{added_categories} category/categories")
        if restored_decor:
            parts.append(f"{restored_decor} calendar day marking(s)")
        if added_templates:
            parts.append(f"{added_templates} template(s)")
        if added_trash:
            parts.append(f"{added_trash} trashed note(s)")
        if parts:
            extras_note = " Also restored " + " and ".join(parts) + "."
        if earlier > 0:
            extras_note += (f" Earlier text of {earlier} day{'s' if earlier != 1 else ''} "
                            "of a repeating note kept as notes of their own.")
        if refused_categories:
            extras_note += (
                f"\n\n{refused_categories} of the backup's categories could "
                f"not be added (a name over {MAX_CATEGORY_NAME} characters, "
                f"or more than {MAX_CATEGORIES} categories in all), so the "
                "notes filed under them are in General.")
        # Updated and unchanged notes are counted: "Added 0" read as nothing
        # done, and invited a second import over newer text.
        known_note = ""
        if updated:
            known_note += (f" Updated {updated} note(s) you already had "
                           "(“↩ Restore previous” undoes each one).")
        if files_only:
            known_note += (f" {files_only} note(s) you already had took "
                           "attached files this computer lacked.")
        if unchanged:
            known_note += (f" {unchanged} note(s) were already here, "
                           "unchanged, and were skipped.")
        # A sign-out's word for the next start is no longer true: this import
        # finished, its merge saved -- and a session that ends with "Import
        # complete" on screen leaves none (round 8 of the final audit).
        self._take_back_cut_short("import")
        self._import_asking = None
        self.show_info("Import complete",
                       f"Added {len(to_import) + len(copies)} note(s) from the backup."
                       f"{known_note}{skipped_note}{extras_note}")
        self._say_hidden_arrivals(arrived, f"Added {len(arrived)} note(s) from the backup")

    # ---------- Theme helpers ----------
    def get_note_color(self, note):
        """A note's custom color if it has one, otherwise its category's default.
        Uses .get() throughout so a note with a missing/None category (from older
        or partial data) can't crash the list or calendar render."""
        color = note.get("color")
        if isinstance(color, str) and color:
            return color
        category = note.get("category")
        if not isinstance(category, str):
            category = "General"
        return CATEGORY_COLORS.get(category, self.colors["accent"])

    # Tk's own rule for when two presses make one double-click (tkBind.c,
    # NEARBY_MS and NEARBY_PIXELS). Kept here rather than asked of Tk,
    # because Tk pairs two presses only when both land on the SAME widget.
    _DOUBLE_CLICK_MS = 500
    _DOUBLE_CLICK_PX = 5

    def _second_press_of_double_click(self, event):
        """True when *event*, a press on a row-removing button, is a
        double-click's second half (the row below slid up and went too), by
        Tk's rule (500 ms, 5 px) across buttons; a generated event's time is
        the clock's. Bound to <ButtonPress-1>, "break" when true.
        """
        stamp = getattr(event, "time", 0) or int(time.monotonic() * 1000)
        here = (stamp, getattr(event, "x_root", 0), getattr(event, "y_root", 0))
        last = getattr(self, "_row_removal_press", None)
        self._row_removal_press = here
        if last is None:
            return False
        # Event times are milliseconds on a 32-bit clock that wraps.
        elapsed = (here[0] - last[0]) & 0xFFFFFFFF
        return (elapsed <= self._DOUBLE_CLICK_MS
                and abs(here[1] - last[1]) <= self._DOUBLE_CLICK_PX
                and abs(here[2] - last[2]) <= self._DOUBLE_CLICK_PX)

    # ---------- Checklist ----------
    def toggle_checklist_section(self):
        """Show or hide the checklist section under the note body."""
        if self._checklist_open:
            self.checklist_section.pack_forget()
            self._checklist_open = False
            # Through the one writer of the button's words: written here by
            # hand, closing the list dropped its count, and in day mode that
            # it is the whole series'.
            self._update_checklist_progress()
        else:
            # After the button, no padx: its column (build_notes_tab) holds
            # the margin. Sized to the calculator before it shows.
            self._match_checklist_to_calculator()
            self.checklist_section.pack(fill="x", pady=(0, 8),
                                        after=self.checklist_btn)
            self._checklist_open = True
            self._update_checklist_progress()
            # The rows are built on opening (see _render_checklist_items);
            # rows already drawn from this very list need no rebuild.
            if self._checklist_in_step(self._get_checklist()):
                self._update_checklist_progress()
            else:
                self._render_checklist_items()

    def _match_checklist_to_calculator(self):
        """Size the checklist's list so the box matches the calculator beside
        it, measured at RUNTIME (winfo_reqheight): fonts differ, and a tuned
        number was 14px short on CI. Compact = the calculator closed less
        the checklist's other parts; expanded adds the calculator's history.
        """
        try:
            self.update_idletasks()
            calc_h = self.calculator_section.winfo_reqheight()
            non_list = (self.checklist_section.winfo_reqheight()
                        - int(self._checklist_list_wrap.cget("height")))
            hist_delta = self.calculator_history_section.winfo_reqheight()
            # Guard against a not-yet-realised layout reporting a stub 1px:
            # keep the fallback constants until the real numbers arrive.
            if calc_h > 50 and non_list > 0:
                self._checklist_list_compact = max(120, calc_h - non_list)
                self._checklist_list_expanded = (
                    self._checklist_list_compact + max(40, hist_delta))
            self._checklist_list_wrap.configure(
                height=(self._checklist_list_expanded if self._checklist_expanded
                        else self._checklist_list_compact))
        except (tk.TclError, AttributeError, ValueError):
            pass

    def _toggle_checklist_expand(self):
        """Grow or shrink the checklist list area. Expanded, the whole box
        matches the calculator with its history open; compact, it matches
        the calculator closed. The scroll works in both — this is extra
        reach when the list is long, not a replacement for scrolling."""
        self._checklist_expanded = not getattr(self, "_checklist_expanded", False)
        self._checklist_list_wrap.configure(
            height=(self._checklist_list_expanded if self._checklist_expanded
                    else self._checklist_list_compact))
        self.checklist_expand_btn.config(
            text="Collapse ⌃" if self._checklist_expanded else "Expand ⌄")

    # Until _match_checklist_to_calculator measures: the development
    # machine's (calculator 359px closed, 459px open; ~94px of other parts).
    CHECKLIST_LIST_COMPACT = 265
    CHECKLIST_LIST_EXPANDED = 365

    def _build_checklist_section(self):
        """Build the (initially hidden) checklist UI: a scrollable list of items
        plus an entry to add new ones and Save/Close buttons."""
        sec = self.checklist_section
        self._checklist_expanded = False
        # Runtime-measured sizes start at the fallback constants; the first
        # open recomputes them from the calculator's actual height.
        self._checklist_list_compact = self.CHECKLIST_LIST_COMPACT
        self._checklist_list_expanded = self.CHECKLIST_LIST_EXPANDED
        # Header: just the progress label. No in-panel Close button -- the
        # "☑ Checklist ▲" bar above already toggles it shut.
        head = tk.Frame(sec, bg=self.colors["card"])
        head.pack(fill="x", padx=10, pady=(8, 4))
        self.checklist_progress_lbl = tk.Label(
            head, text="Checklist", bg=self.colors["card"], fg=self.colors["subtext"],
            font=("Segoe UI", 9, "bold"), anchor="w")
        self.checklist_progress_lbl.pack(side="left")

        # Scrollable list of items.
        wrap = tk.Frame(sec, bg=self.colors["card"],
                        height=self.CHECKLIST_LIST_COMPACT)
        wrap.pack(fill="x", padx=10, pady=(0, 4))
        wrap.pack_propagate(False)
        self._checklist_list_wrap = wrap
        canvas = tk.Canvas(wrap, bg=self.colors["card"], highlightthickness=0)
        sb = ttk.Scrollbar(wrap, orient="vertical", command=canvas.yview)
        wheel = lambda e: self._panel_or_page_wheel(canvas, e)  # noqa: E731
        # 32 short items a chunk, fewer past RowStack.TALLEST (one item can
        # stand 10,662 px): every chunk in sight moves per scroll step, and
        # four a chunk cost 12 ms a step, 32 cost 7.
        self._checklist_rows = self._row_stack(
            canvas, scrolled=sb.set,
            on_chunk=lambda chunk: chunk.bind("<MouseWheel>", wheel)
        ).group(every=32)
        self._checklist_rows.rebuild = self._chunk_checklist_again
        sb.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)
        self._checklist_canvas = canvas
        # Bound once, on tags every row's widgets carry: a binding per
        # widget is one more Tcl command for every row drawn.
        self.bind_class("ChecklistRowButton", "<ButtonPress-1>",
                        self._checklist_button_press)
        self.bind_class("ChecklistBox", "<Alt-Up>",
                        lambda e: self._move_checklist_by_key(e.widget, -1))
        self.bind_class("ChecklistBox", "<Alt-Down>",
                        lambda e: self._move_checklist_by_key(e.widget, 1))
        self.bind_class("ChecklistText", "<Configure>",
                        lambda e: self._wrap_to_width(e.widget, e.width))
        self.bind_class("ChecklistArrows", "<ButtonPress-1>",
                        self._checklist_arrow_press)
        self.bind_class("ChecklistArrows", "<Enter>",
                        lambda e: self._light_arrows(e.widget, True))
        self.bind_class("ChecklistArrows", "<Leave>",
                        lambda e: self._light_arrows(e.widget, False))
        # The ring that shows which item the keyboard is on, in a note's
        # checklist and a template's -- and which Trash row, its box having
        # no words to draw Windows' dotted ring round.
        for tag in ("ChecklistBox", "TemplateChecklistBox", "TrashTickBox"):
            self.bind_class(tag, "<FocusIn>",
                            lambda e: self._ring_checklist_row(e.widget, True))
            self.bind_class(tag, "<FocusOut>",
                            lambda e: self._ring_checklist_row(e.widget, False))

        # Expand/Collapse bar, the same full-width flat bar the note body and
        # comments boxes carry (_add_text_resize_toggle), so the three read
        # the same. Directly under the list, like those sit under their box.
        self.checklist_expand_btn = tk.Button(
            sec, text="Expand ⌄", command=self._toggle_checklist_expand,
            relief="flat", cursor="hand2", font=("Segoe UI", 8, "bold"), bd=0)
        self.track_theme(self.checklist_expand_btn, bg="card", fg="subtext",
                         activebackground="card", activeforeground="text")
        self.checklist_expand_btn.pack(fill="x", padx=10, pady=(0, 2))

        # Add-item row.
        add_row = tk.Frame(sec, bg=self.colors["card"])
        add_row.pack(fill="x", padx=10, pady=(2, 4))
        self.checklist_add_var = tk.StringVar()
        entry = tk.Entry(add_row, textvariable=self.checklist_add_var, relief="flat",
                         font=("Segoe UI", 10), bg=self.colors["sidebar"],
                         fg=self.colors["text"], insertbackground=self.colors["text"])
        self._guard_entry_astral(entry)
        # A paste of a whole page became one item, drawn as one label as
        # tall as its text: the same limit every route to an item keeps.
        self._limit_entry(entry, MAX_CHECKLIST_ITEM_CHARS, "A checklist item")
        entry.pack(side="left", fill="x", expand=True, ipady=4)
        # Pressed, not held: held over a full list, a repeat answered its
        # "Checklist full" and the next asked it again (_enter_repeats).
        entry.bind("<Return>", lambda e: (
            None if self._enter_repeats(e) else self._add_checklist_item()))
        self._add_paste_menu(entry)
        self.checklist_add_entry = entry
        # Long-lived: without tracking, the caret (insertbackground) froze
        # on the build-time palette — invisible after a dark<->light switch.
        self.track_theme(entry, bg="sidebar", fg="text",
                         insertbackground="text")
        # ASCII "+", like every other add-button in the app. A fullwidth
        # U+FF0B renders noticeably wider, and this one sits a few
        # centimetres from the attachments panel's "+ Add file".
        tk.Button(add_row, text="+ Add", command=self._add_checklist_item,
                  bg=self.colors["accent"], fg=self._on_fill("accent"), relief="flat",
                  font=("Segoe UI", 9, "bold"), cursor="hand2"
                  ).pack(side="left", padx=(6, 0), ipadx=8, ipady=2)

    def _get_checklist(self):
        """The working checklist for the note being edited, held in memory until
        the note is saved."""
        if not hasattr(self, "_working_checklist"):
            self._working_checklist = []
        return self._working_checklist

    def _render_checklist_items(self):
        """Redraw the checklist rows -- only while the section is OPEN (five
        widgets a row: a 50-item note paid ~250 at every open);
        toggle_checklist_section builds them. The rows drawn are recorded
        (_checklist_rows_current), so a change touches its own row.
        """
        if not hasattr(self, "_checklist_rows"):
            return
        self._update_checklist_progress()
        if not self._checklist_open:
            # What stands in the closed frame no longer matches the list;
            # the next open redraws it.
            self._checklist_drawn = None
            return
        self._checklist_rows.clear()
        items = self._get_checklist()
        if not items:
            tk.Label(self._checklist_rows.add(), text="No items yet — add one below.",
                     bg=self.colors["card"], fg=self.colors["subtext"],
                     font=("Segoe UI", 9), anchor="w").pack(fill="x", padx=4, pady=6)
        self._checklist_drawn = {
            "items": items, "theme": self.theme_name,
            "rows": [self._build_checklist_row(idx, item)
                     for idx, item in enumerate(items)]}

    def _build_checklist_row(self, idx, item, into=None, before=None):
        """One row, packed at the end -- of the chunk *into*, if given -- or,
        with *before*, in that row's place. Returns its record for the drawn
        list: ``[item, row frame, (text, done) as drawn]``."""
        if before is not None:
            into = before.master
        # The border is the ring of the item the keyboard is on, card-
        # coloured until then (_ring_checklist_row).
        row = tk.Frame(into if into is not None else self._checklist_rows.add(),
                       bg=self.colors["card"], highlightthickness=1,
                       highlightbackground=self.colors["card"],
                       highlightcolor=self.colors["card"])
        row.palette_keys = {"highlightbackground": "card",
                            "highlightcolor": "card"}
        if before is None:
            row.pack(fill="x", pady=1)
        else:
            # Tab walks the stacking order, which packing leaves alone.
            row.pack(fill="x", pady=1, before=before)
            row.lower(before)
        record = [item, row, (item.get("text", ""), bool(item.get("done")))]
        var = tk.IntVar(value=1 if item.get("done") else 0)

        def on_toggle():
            item["done"] = bool(var.get())
            record[2] = (item.get("text", ""), item["done"])
            self._update_checklist_progress()
            self._restyle_checklist_label(lbl, item["done"])
            self._schedule_autosave()

        # ▲ over ▼ at the left, as one element: each element of a row is a
        # window Windows makes when the list opens (_checklist_arrow_press).
        arrows = tk.Label(row, text="▲\n▼", font=("Segoe UI", 7), padx=3,
                          pady=0, cursor="hand2", bg=self.colors["card"],
                          fg=self.colors["subtext"])
        arrows.bindtags(("ChecklistArrows",) + arrows.bindtags())
        arrows.pack(side="left")
        cb = tk.Checkbutton(row, variable=var, command=on_toggle,
                            bg=self.colors["card"], activebackground=self.colors["card"],
                            selectcolor=self.colors["check_well"], bd=0,
                            highlightthickness=0)
        cb.pack(side="left")
        # Alt+Up/Down moves it (_build_checklist_section binds the tag).
        cb.bindtags(("ChecklistBox",) + cb.bindtags())

        def delete():
            items = self._get_checklist()
            # Its place IN THIS LIST now, for the undo, found by IDENTITY:
            # index() finds the first equal item, and two alike are two.
            index = next((i for i, it in enumerate(items) if it is item),
                         None)
            if index is None:
                return
            drawn = getattr(self, "_checklist_drawn", None)
            in_step = self._checklist_in_step(items)
            items.pop(index)
            if in_step and items:
                # This row goes, the others stay: rebuilding every row
                # took over two seconds at 200 items.
                drawn["rows"].pop(index)
                self._checklist_rows.discard(row)
                self._update_checklist_progress()
            else:
                self._render_checklist_items()
            self._schedule_autosave()
            # Ctrl+Z cannot reach a checklist (dicts beside the Text), so an
            # Undo toast: a question before every tidy-up costs more than
            # the risk, and confirmation follows how recoverable a loss is.
            label = _truncate(item.get("text", ""), 40)
            self._show_toast(
                f"Removed “{label}”" if label else "Checklist item removed",
                action=lambda: self._undo_checklist_delete(items, index, item))

        bin_btn = tk.Button(row, text="🗑", command=delete, relief="flat",
                            cursor="hand2", bg=self.colors["card"],
                            fg=self.colors["danger_text"], font=("Segoe UI", 9),
                            bd=0)
        # Packed before the text, so a long item cannot squeeze it out; and
        # ahead of the Button class, a double-click's second press is
        # stopped before it arms the button (_checklist_button_press).
        bin_btn.pack(side="right")
        bin_btn.bindtags(("ChecklistRowButton",) + bin_btn.bindtags())

        # Drawn cut past the limit: a share code's 60,000 characters made a
        # label past the 32,767 pixels X can draw, and the app died.
        lbl = tk.Label(row, text=checklist_shown(item.get("text", "")),
                       bg=self.colors["card"],
                       fg=self.colors["text"], font=("Segoe UI", 10), anchor="w",
                       justify="left", wraplength=self.CHECKLIST_WRAP)
        lbl.pack(side="left", fill="x", expand=True, padx=(2, 4))
        self._restyle_checklist_label(lbl, item.get("done"))
        # Click the text to toggle too.
        lbl.bind("<Button-1>", lambda e: (var.set(0 if var.get() else 1), on_toggle()))
        # Wrapped at the width it is given (_wrap_to_width), when it is long
        # enough that a row could ever be too narrow for it.
        if lbl.winfo_reqwidth() > self.CHECKLIST_SHORT:
            lbl.bindtags(("ChecklistText",) + lbl.bindtags())
            self._wrap_as_its_rows(lbl, self._checklist_rows)
        return record

    def _wrap_as_its_rows(self, label, block):
        """*label*, a row's long text just made, wrapped where its *block*'s
        rows were last wrapped (_wrap_to_width), so the row is measured as it
        will stand: made at CHECKLIST_WRAP in a narrow window and wrapped
        narrower later, a chunk of long items stood 2.7 times what it was
        taken for, past what X and Windows can place."""
        if block.wrap and block.wrap != int(str(label.cget("wraplength"))):
            label.configure(wraplength=block.wrap)

    def _checklist_button_press(self, event):
        """A press on a row's bin. A double-click's second press lands on
        the NEXT row's bin, slid up into this one's place: it must not
        remove that row too."""
        return "break" if self._second_press_of_double_click(event) else None

    def _checklist_arrow_press(self, event):
        """A press on a row's ▲ over ▼: the top half moves its item up, the
        bottom half down, and the keyboard goes to the item, so Alt+Up and
        Alt+Down carry on moving it. A double-click's second press lands on
        the arrows of the row slid into this one's place: it moves nothing."""
        if self._second_press_of_double_click(event):
            return "break"
        arrows = event.widget
        box = next((w for w in arrows.master.winfo_children()
                    if isinstance(w, tk.Checkbutton)), None)
        if box is not None:
            step = -1 if event.y < arrows.winfo_height() / 2 else 1
            self._move_checklist_by_key(box, step)
        return None

    def _light_arrows(self, arrows, on):
        """A row's ▲ ▼ brighten under the pointer, as a button would."""
        try:
            arrows.configure(fg=self.colors["text" if on else "subtext"])
        except tk.TclError:
            pass

    def _ring_checklist_row(self, box, on):
        """The ring round the checklist row whose tick box has the keyboard,
        in a note or a template, or round a Trash row: without it Tab and
        Alt+Up/Down went to an item nobody could see was chosen (her re-test,
        case 591)."""
        try:
            row = box.master
            color = self._focus_ring() if on else row.cget("bg")
            # Both: Tk draws the border in highlightcolor while the focus
            # is anywhere inside the row, and the box is inside it.
            row.configure(highlightbackground=color, highlightcolor=color)
        except tk.TclError:
            pass

    # A checklist item's text no wider than this fits even the narrowest
    # row, so it is never watched for wrapping (159 px at 640x600).
    CHECKLIST_SHORT = 150

    # Where a checklist item's text wraps, unless its row is narrower.
    CHECKLIST_WRAP = 380

    def _wrap_to_width(self, label, width):
        """Make *label* wrap its text inside *width* pixels, its own -- only
        when its text is cut off, or has room again: rewrapping every row
        doubled the time a long checklist took to open."""
        if width <= 1:
            return
        edge = 2 * sum(int(str(label.cget(option)))
                       for option in ("bd", "padx", "highlightthickness"))
        wrap = min(self.CHECKLIST_WRAP, max(self.px(40), width - edge))
        now = int(str(label.cget("wraplength")))
        # The block of a row stack its row stands in (RowStack): told, so a
        # chunk's height is read as its rows now stand, and the next row is
        # made at this wrap.
        block = self._block_of(label.master)
        told = getattr(block, "rewrapped", None)
        if told is not None:
            block.wrap = wrap
        if now != wrap and (label.winfo_reqwidth() > width or now < wrap):
            label.configure(wraplength=wrap)
            if told is not None:
                told(label.master)

    def _restyle_checklist_label(self, lbl, done):
        """Dim + strike-through style for completed items (overstrike font).

        Two fonts shared by every row, made once from the first label's
        font -- a new Font per call was one more Tk font object for every
        row built and every tick."""
        fg = self.colors["subtext"] if done else self.colors["text"]
        try:
            fonts = getattr(self, "_checklist_fonts", None)
            if fonts is None:
                plain = tkfont.Font(font=lbl.cget("font"))
                plain.configure(overstrike=0)
                struck = tkfont.Font(font=lbl.cget("font"))
                struck.configure(overstrike=1)
                fonts = self._checklist_fonts = (plain, struck)
            lbl.configure(font=fonts[1] if done else fonts[0], fg=fg)
        except Exception:
            lbl.configure(fg=fg)

    def _take_pending_checklist_item(self):
        """Add what sits typed in the checklist's add box to this note's list,
        as leaving the note requires (see _flush_autosave). Unlike the Add
        button it leaves the keyboard where it is: the person is on their
        way somewhere else."""
        var = getattr(self, "checklist_add_var", None)
        text = var.get().strip()[:MAX_CHECKLIST_ITEM_CHARS] if var is not None else ""
        uid = self._open_note_uid()
        if uid:
            # What waits is what the box holds now: emptied, nothing does.
            self._add_box_waiting.pop(uid, None)
        if not text:
            self._waiting_said.pop(uid, None)
            return
        items = self._get_checklist()
        if len(items) >= MAX_CHECKLIST_ITEMS:
            # Full: the words wait for this note, back in its Add box when it
            # is opened again. Leaving cleared the box, and "Delete an item to
            # make room" could no longer be done (round 7 of the audit).
            if uid:
                self._add_box_waiting[uid] = text
                # Said once for these words in this note: back in its box at
                # every opening, they raised "Checklist full" on every way
                # out (round 8 of the audit). The close still asks.
                if self._waiting_said.get(uid) == text:
                    return
            self._checklist_full(items, text, waits=uid)
            return
        self._append_checklist_item(text)
        var.set("")
        # Added, they are no longer the words that were said: typed again
        # into a full list, they kept waiting in silence (round 9).
        self._waiting_said.pop(uid, None)

    def _open_note_uid(self):
        """The identity of the note the editor holds, or None (a new note)."""
        note = (self.find_note(self.selected_note_id)
                if self.selected_note_id is not None else None)
        return (note.get("uid") or None) if note is not None else None

    def _checklist_in_step(self, items):
        """Whether the checklist is open with its rows drawn from exactly
        *items*, in this theme: only then may a change touch one row
        (_checklist_rows_current)."""
        return (self._checklist_open
                and _checklist_rows_current(getattr(self, "_checklist_drawn", None),
                                            items, self.theme_name))

    def _append_checklist_item(self, text):
        """*text* as the list's last item: one new row when the rows on screen
        are this list's, the whole list drawn otherwise. The Add box taken on
        a save rebuilt every row, 2.2 s at 1,000 (round 6 of the audit)."""
        items = self._get_checklist()
        drawn = getattr(self, "_checklist_drawn", None)
        in_step = self._checklist_in_step(items)
        item = {"text": text, "done": False}
        items.append(item)
        if in_step:
            # One new row, not the whole list again: rebuilding every row
            # took over two seconds per add at 200 items.
            if not drawn["rows"]:
                self._checklist_rows.clear()     # the "No items yet" line
            drawn["rows"].append(self._build_checklist_row(len(items) - 1,
                                                           item))
            self._update_checklist_progress()
        elif hasattr(self, "_checklist_rows"):
            self._render_checklist_items()

    def _add_checklist_item(self):
        text = self.checklist_add_var.get().strip()[:MAX_CHECKLIST_ITEM_CHARS]
        if not text:
            return
        if self._checklist_full(self._get_checklist(), text):
            return  # the words stay in the box
        self._append_checklist_item(text)
        self.checklist_add_var.set("")
        uid = self._open_note_uid()
        self._add_box_waiting.pop(uid, None)    # added: none waits
        self._waiting_said.pop(uid, None)       # ...and none was said
        self._schedule_autosave()
        try:
            self.checklist_add_entry.focus_set()
        except tk.TclError:
            pass

    def _move_checklist_item(self, item, step):
        """Move *item* one place up (step -1) or down (+1); at either end,
        nothing. Returns whether it moved. With this list's rows on screen,
        only the two rows trade, and the record of drawn rows with them --
        the delete's Undo puts a row back by that record."""
        items = self._get_checklist()
        at = next((i for i, it in enumerate(items) if it is item), None)
        if at is None or not 0 <= at + step < len(items):
            return False
        drawn = getattr(self, "_checklist_drawn", None)
        in_step = self._checklist_in_step(items)
        to = at + step
        items[at], items[to] = items[to], items[at]
        if in_step:
            rows = drawn["rows"]
            rows[at], rows[to] = rows[to], rows[at]
            upper, lower = rows[min(at, to)][1], rows[max(at, to)][1]
            if upper.master is lower.master:
                upper.pack_configure(before=lower)
                # Tab walks the stacking order, which packing leaves alone.
                upper.lower(lower)
            else:
                group, chunks = self._checklist_rows, (upper.master, lower.master)
                self._trade_checklist_chunks(rows, min(at, to))
                # A long item traded into a chunk makes it taller, and long
                # items moved there one by one passed what X and Windows can
                # place. Far past RowStack.TALLEST, the rows are chunked again.
                if any(group.too_tall(c) for c in chunks):
                    self._render_checklist_items()
        else:
            self._render_checklist_items()
        self._schedule_autosave()
        self._show_checklist_row(item)
        return True

    def _trade_checklist_chunks(self, rows, i):
        """Rows *i* and *i* + 1 of the drawn list, already traded in it,
        trade places on screen across two chunks (RowStack), which a row
        cannot leave: each is made again in the other's place."""
        going_up, going_down = rows[i][1], rows[i + 1][1]
        above, below = going_down.master, going_up.master
        rest = below.pack_slaves()[1:2]
        going_up.destroy()
        going_down.destroy()
        rows[i] = self._build_checklist_row(i, rows[i][0], into=above)
        rows[i + 1] = (self._build_checklist_row(i + 1, rows[i + 1][0], before=rest[0])
                       if rest else
                       self._build_checklist_row(i + 1, rows[i + 1][0], into=below))

    def _move_checklist_by_key(self, box, step):
        """Alt+Up/Down on an item's tick box, or its arrows: the item moves,
        and the keyboard goes with it -- to its box even at either end,
        where an arrow pressed still chooses the item."""
        drawn = getattr(self, "_checklist_drawn", None) or {}
        item = next((r[0] for r in drawn.get("rows", ())
                     if r[1] is box.master), None)
        if item is None:
            return "break"
        if self._move_checklist_item(item, step):
            box = self._show_checklist_row(item)
        if box is not None:
            try:
                box.focus_set()
            except tk.TclError:
                pass
        return "break"

    def _show_checklist_row(self, item):
        """Scroll the list so *item*'s row is in view; returns its tick box,
        or None when no row stands for it."""
        drawn = getattr(self, "_checklist_drawn", None) or {}
        rec = next((r for r in drawn.get("rows", ()) if r[0] is item), None)
        if rec is None:
            return None
        row, canvas = rec[1], self._checklist_canvas
        try:
            self.update_idletasks()
            stack = self._checklist_rows.stack
            total, y = max(1, stack.total), stack.y_of(row)
            if y is None:
                return None
            top = y / total
            bottom = (y + row.winfo_height()) / total
            first, last = canvas.yview()
            if top < first:
                canvas.yview_moveto(top)
            elif bottom > last:
                canvas.yview_moveto(bottom - (last - first))
            return next((w for w in row.winfo_children()
                         if isinstance(w, tk.Checkbutton)), None)
        except tk.TclError:
            return None

    def _chunk_checklist_again(self):
        """The note's checklist drawn again, chunked as its rows now stand
        (RowStack._rechunk_too_tall): items that grew since they were chunked
        -- a narrower window wraps long ones again -- made a chunk taller than
        X and Windows can place, and past 32,767 px into it the list was blank
        while Space still ticked the items there. The view stays where it
        was, and the keyboard on the item, and the part of its row, it held."""
        if not self._checklist_open:
            return
        drawn = getattr(self, "_checklist_drawn", None) or {}
        canvas = self._checklist_canvas
        on = None
        try:
            # The window's own record: it holds while another program has the
            # foreground, where "focus" answers nothing.
            held = str(self.tk.call("focus", "-lastfor", self))
            for rec in drawn.get("rows", ()):
                if held.startswith(str(rec[1]) + "."):
                    names = [str(w) for w in rec[1].winfo_children()]
                    on = (rec[0], names.index(held) if held in names else 0)
                    break
            top = canvas.canvasy(0)
        except tk.TclError:
            return
        self._render_checklist_items()
        try:
            self.update_idletasks()
            stack = self._checklist_rows.stack
            stack.size()
            canvas.yview_moveto(top / max(1, stack.total))
            # Back where it was -- unless it has gone on somewhere since, a
            # popup's box: the row it was in is gone, so it is on nothing.
            if on is not None and self._keyboard_nowhere():
                rec = next((r for r in self._checklist_drawn["rows"]
                            if r[0] is on[0]), None)
                kids = rec[1].winfo_children() if rec is not None else []
                if kids:
                    kids[min(on[1], len(kids) - 1)].focus_set()
        except (tk.TclError, TypeError, KeyError):
            pass

    def _update_checklist_progress(self):
        """The checklist's count on its button and its header -- and, in day
        mode, that it is the whole series' (_series_owned_mark). The one
        writer of both, so the toggle that opens and closes the list says
        the same as a tick does."""
        if not hasattr(self, "checklist_progress_lbl"):
            return
        items = self._get_checklist()
        whole = self._series_owned_mark()
        if not items:
            self.checklist_progress_lbl.config(text="Checklist" + whole)
            self.checklist_btn.config(
                text="☑ Checklist" + whole
                + ("  ▲" if self._checklist_open else ""))
            return
        done = sum(1 for it in items if it.get("done"))
        self.checklist_progress_lbl.config(
            text=f"Checklist — {done}/{len(items)} done{whole}")
        # Reflect the count on the toggle button too, so it's visible when closed.
        badge = f"☑ Checklist ({done}/{len(items)}){whole}"
        self.checklist_btn.config(text=badge + ("  ▲" if self._checklist_open else ""))

    def _sync_checklist_open_state(self):
        """After loading a note, keep the checklist collapsed by default but
        refresh the button badge so the item count shows even when closed."""
        # Collapse on note switch to keep the editor tidy; the badge still shows
        # how many items exist.
        if self._checklist_open:
            self.checklist_section.pack_forget()
            self._checklist_open = False
        # Also drop the expand back to compact — the expanded height is a
        # transient view choice, not part of the note, so it shouldn't
        # carry from one note into the next.
        if getattr(self, "_checklist_expanded", False):
            self._checklist_expanded = False
            if hasattr(self, "_checklist_list_wrap"):
                self._checklist_list_wrap.configure(
                    height=self._checklist_list_compact)
            if hasattr(self, "checklist_expand_btn"):
                self.checklist_expand_btn.config(text="Expand ⌄")
        self._update_checklist_progress()

    # ---------- In-note calculator ----------

    def update_word_count(self, text=None):
        """Refresh the words · characters readout for the note body.

        Tables are counted by what the user wrote in them, not by their
        plumbing: every pipe used to count as a "word", so an empty 3x3
        table claimed twelve words and inflated the reading time. *text*
        is the body as its caller has just read it.
        """
        if text is None:
            text = self.body_text.get("1.0", "end-1c")
        self._word_count_due = False
        if core_tables.CELL in text:
            text = core_tables.content_text(text)
        chars = len(text)
        words = len(text.split())
        if chars == 0:
            self.word_count_lbl.config(text="")
        else:
            w = "word" if words == 1 else "words"
            c = "character" if chars == 1 else "characters"
            # The reading time on its own line: "have I got time for this?",
            # an aside, not more of "how much have I written?".
            line = f"{words} {w} · {chars} {c}"
            estimate = reading_time(words)
            self.word_count_lbl.config(
                text=f"{line}\n{estimate}" if estimate else line)

    def _reset_editor_scroll(self):
        """Called after loading a note into the editor: snap back to the top and
        recompute whether scrolling is even needed, so switching from a long
        note to a short one never leaves the short one scrolled down."""
        self.editor_canvas.yview_moveto(0)
        self.after_idle(self._sync_editor_scroll)

    def _canvas_width_sync(self, canvas, item):
        """Return a <Configure> handler that resizes the canvas's inner window to
        the canvas width, but ONLY when the width actually changed. During a
        vertical resize the width stays the same, so this avoids relaying-out all
        the rows on every height change — which was causing the drag flicker."""
        last = {"w": -1}

        def handler(event):
            if event.width != last["w"]:
                last["w"] = event.width
                try:
                    canvas.itemconfig(item, width=event.width)
                except tk.TclError:
                    pass
        return handler

    def _add_text_resize_toggle(self, host, text_widget, compact, expanded,
                                pack_kwargs=None, remember_key=None):
        """Add an Expand/Collapse toggle under a Text box: one click, one
        height in rows. Dragging the edge was abandoned -- the scrolling
        canvas fell behind dozens of resizes a second. *remember_key* keeps
        the choice in settings; without it the box opens compact.
        """
        # The packing is left alone: an expand=False here, meant for the
        # height, acts sideways with side="left" and held the box at 80
        # characters. The row count sets the frame's height.
        text_widget.configure(height=compact)

        start = False
        if remember_key:
            start = bool(get_setting(remember_key, False, bool))
        state = {"expanded": start}
        btn = tk.Button(host, relief="flat", font=("Segoe UI", 8, "bold"),
                        cursor="hand2", bd=0)
        self.track_theme(btn, bg="bg", fg="subtext",
                         activebackground="bg", activeforeground="text")

        def apply():
            try:
                text_widget.configure(height=expanded if state["expanded"] else compact)
            except tk.TclError:
                pass
            btn.configure(text=("Collapse ⌃" if state["expanded"] else "Expand ⌄"))

        def toggle():
            state["expanded"] = not state["expanded"]
            apply()
            if remember_key:
                save_setting(remember_key, state["expanded"])

        btn.configure(command=toggle)
        apply()
        pk = pack_kwargs or {}
        btn.pack(fill="x", **pk)
        return btn

    def _add_resize_handle(self, target, min_h=80, max_h=1000, host=None):
        """Add an Expand/Collapse toggle below `target`. One click switches the
        panel between its compact height (the default) and an expanded height —
        no dragging, so it's flicker-free and dead simple. `target` must have a
        fixed height with pack_propagate(False). Height not persisted."""
        host = host or target.master
        try:
            compact_h = int(target.cget("height"))
        except tk.TclError:
            compact_h = min_h
        expanded_h = min(max_h, max(compact_h + 260, compact_h * 2))
        state = {"expanded": False}

        btn = tk.Button(host, relief="flat", font=("Segoe UI", 8, "bold"),
                        cursor="hand2", bd=0)
        self.track_theme(btn, bg="sidebar", fg="subtext",
                         activebackground="sidebar", activeforeground="text")

        def apply():
            h = expanded_h if state["expanded"] else compact_h
            try:
                target.configure(height=h)
            except tk.TclError:
                pass
            btn.configure(text=("Collapse ⌃" if state["expanded"] else "Expand ⌄"))

        def toggle():
            state["expanded"] = not state["expanded"]
            apply()

        btn.configure(command=toggle)
        apply()
        return btn



    def _bind_wheel_tree_if_unbound(self, root, handler):
        """Bind a wheel handler to a widget subtree, but skip widgets that
        already have a MouseWheel binding (their own scroll list keeps priority)."""
        if not root.bind("<MouseWheel>"):
            root.bind("<MouseWheel>", handler)
        for child in root.winfo_children():
            self._bind_wheel_tree_if_unbound(child, handler)


    def _show_inline_rename(self, anchor_widget, current, on_save, limit=None):
        """Small inline rename box near `anchor_widget`: an entry pre-filled with
        `current`, a Save and an ✕. on_save(new_text) returns True to close or
        False to keep it open. No grab_set() — that can freeze the app.
        *limit* is (characters, "What it names") for _limit_entry."""
        self._dismiss_mini_popup()
        pop = tk.Toplevel(self)
        self._mini_popup = pop
        pop.wm_overrideredirect(True)
        pop.configure(bg=self.colors["accent"])
        frame = tk.Frame(pop, bg=self.colors["card"], padx=8, pady=8)
        frame.pack(padx=1, pady=1)

        var = tk.StringVar(value=current)
        entry = tk.Entry(frame, textvariable=var, relief="flat", font=("Segoe UI", 10),
                         bg=self.colors["sidebar"], fg=self.colors["text"],
                         insertbackground=self.colors["text"], width=18)
        self._guard_entry_astral(entry)
        entry.pack(side="left", ipady=3, padx=(0, 6))
        entry.select_range(0, "end")
        self._add_paste_menu(entry)
        if limit is not None:
            self._limit_entry(entry, *limit)

        def save():
            if on_save(var.get()):
                self._dismiss_mini_popup()

        tk.Button(frame, text="Save", command=save, relief="flat", cursor="hand2",
                  bg=self.colors["accent"], fg=self._on_fill("accent"),
                  font=("Segoe UI", 8, "bold")
                  ).pack(side="left", ipadx=6, ipady=2, padx=(0, 3))
        tk.Button(frame, text="✕", command=self._dismiss_mini_popup, relief="flat",
                  cursor="hand2", bg=self.colors["sidebar"], fg=self.colors["text"],
                  font=("Segoe UI", 8, "bold")).pack(side="left", ipadx=4, ipady=2)

        # "break": each can destroy the box, and its own <Escape> then ran
        # dead (_place_dropdown_popup). Pressed, not held (_enter_repeats):
        # a repeat pressed whatever the keyboard went back to.
        entry.bind("<Return>", lambda e: (
            None if self._enter_repeats(e) else save(), "break")[1])
        entry.bind("<Escape>", lambda e: (self._dismiss_mini_popup(), "break")[1])

        self._place_mini_popup(pop, anchor_widget)
        # Focus the entry after placing (safe now — no grab).
        entry.focus_set()
        return pop

    def _show_color_palette(self, anchor_widget, current, on_pick, allow_reset=True,
                            anchor_xy=None, reset_label="Default (theme color)",
                            keyboard_from=None):
        """Show a small inline color palette near `anchor_widget` (or at
        `anchor_xy` root coordinates, for callers with no persistent widget to
        anchor to — e.g. a calendar day reached via right-click). Clicking a
        swatch calls on_pick(hex) and closes. An ✕ closes without changing.
        Deliberately does NOT use grab_set() — a grabbed borderless window can
        fail to get focus on Windows and freeze the whole app."""
        # Only one of these open at a time.
        self._dismiss_mini_popup()
        pop = tk.Toplevel(self)
        self._mini_popup = pop
        pop.wm_overrideredirect(True)
        pop.configure(bg=self.colors["accent"])
        frame = tk.Frame(pop, bg=self.colors["card"], padx=8, pady=8)
        frame.pack(padx=1, pady=1)

        # Header with a close ✕.
        head = tk.Frame(frame, bg=self.colors["card"])
        head.pack(fill="x", pady=(0, 4))
        tk.Label(head, text="Pick a color", bg=self.colors["card"],
                 fg=self.colors["subtext"], font=("Segoe UI", 8, "bold")).pack(side="left")
        tk.Button(head, text="✕", command=self._dismiss_mini_popup, relief="flat",
                  cursor="hand2", bg=self.colors["card"], fg=self.colors["subtext"],
                  font=("Segoe UI", 9, "bold"), bd=0).pack(side="right")

        def pick(color):
            self._dismiss_mini_popup()
            on_pick(color)

        grid = tk.Frame(frame, bg=self.colors["card"])
        grid.pack()
        per_row = 5
        for i, color in enumerate(PALETTE_COLORS):
            r, c = divmod(i, per_row)
            # Two pixels narrower: the keyboard's ring is the third, on the
            # canvas's edge, which the swatch drawn inside never reaches.
            cell = tk.Canvas(grid, width=self.px(26) - 2, height=self.px(26) - 2,
                             bg=self.colors["card"], cursor="hand2")
            self._ring_round(cell, self.colors["card"])
            self._pressable(cell, lambda col=color: pick(col), walk=True,
                            current=color == current)
            self._rounded_rect(cell, 2, 2, 24, 24, 7, fill=color, outline=color)
            if color == current:
                # The tick is the only sign of the colour in use, and two
                # swatches can look alike to a colour-blind eye: it must read.
                cell.create_text(13, 13, text="✓", fill=letters_on(color),
                                 font=("Segoe UI", 11, "bold"), tags="tick")
            self._scale_drawing(cell)
            cell.grid(row=r, column=c, padx=3, pady=3)
            # "break": the pick destroys this popup (see _show_inline_rename).
            cell.bind("<Button-1>", lambda e, col=color: (pick(col), "break")[1])

        if allow_reset:
            reset = tk.Button(frame, text=reset_label,
                              command=lambda: pick(""), relief="flat", cursor="hand2",
                              bg=self.colors["sidebar"], fg=self.colors["text"],
                              font=("Segoe UI", 8))
            reset.pack(fill="x", pady=(6, 0), ipady=2)
            self._button_choice(reset)

        self._place_mini_popup(pop, anchor_widget, anchor_xy=anchor_xy,
                               keyboard_from=keyboard_from)
        return pop

    # ---------- Themed dialogs (replace OS messagebox) ----------







    def _refresh_category_button(self):
        """Update the category button's colour dot + label to the current pick."""
        cat = self.category_var.get()
        color = CATEGORY_COLORS.get(cat, self.colors["accent"])
        try:
            self._cat_dot.configure(bg=self.colors["sidebar"], fg=color)
        except tk.TclError:
            pass


    def _open_category_dropdown(self):
        """Open an in-theme dropdown list of categories, each with its colour
        dot. Replaces the OS-white ttk popup."""
        self._dismiss_mini_popup()
        pop = tk.Toplevel(self)
        self._mini_popup = pop
        pop.wm_overrideredirect(True)
        pop.configure(bg=self.colors["accent"])
        # padx 3, rows packed with no pady: each row's ring takes the pixel.
        frame = tk.Frame(pop, bg=self.colors["card"], padx=3, pady=4)
        frame.pack(padx=1, pady=1)

        current = self.category_var.get()
        for cat in CATEGORY_COLORS.keys():
            color = CATEGORY_COLORS.get(cat, self.colors["accent"])
            is_cur = (cat == current)
            row = tk.Frame(frame, bg=self.colors["sidebar"] if is_cur else self.colors["card"],
                           cursor="hand2")
            self._ring_round(row, self.colors["card"])
            row.pack(fill="x")
            dot = tk.Label(row, text="●", bg=row.cget("bg"), fg=color,
                          font=("Segoe UI", 11), cursor="hand2")
            dot.pack(side="left", padx=(10, 6), pady=4)
            lbl = tk.Label(row, text=cat, bg=row.cget("bg"),
                           fg=self.colors["accent_text"] if is_cur else self.colors["text"],
                           font=("Segoe UI", 10, "bold" if is_cur else "normal"),
                           anchor="w", width=13)
            lbl.pack(side="left", padx=(0, 10))

            def pick(c=cat):
                self.category_var.set(c)
                self._refresh_category_button()
                self._update_color_swatch()
                self._schedule_autosave()
                self._dismiss_mini_popup()

            self._pressable(row, pick, walk=True, current=is_cur)
            for w in (row, dot, lbl):
                # "break": the pick destroys this popup (see
                # _show_inline_rename).
                w.bind("<Button-1>", lambda e, c=cat: (pick(c), "break")[1])
                w.bind("<Enter>", lambda e, r=row, d=dot, l=lbl:
                       (r.configure(bg=self.colors["sidebar"]),
                        d.configure(bg=self.colors["sidebar"]),
                        l.configure(bg=self.colors["sidebar"])))
                if not is_cur:
                    w.bind("<Leave>", lambda e, r=row, d=dot, l=lbl:
                           (r.configure(bg=self.colors["card"]),
                            d.configure(bg=self.colors["card"]),
                            l.configure(bg=self.colors["card"])))

        self._place_dropdown_popup(pop, self.category_menu)

    def _refresh_category_button_safe(self):
        try:
            self._refresh_category_button()
        except tk.TclError:
            pass





    def _rounded_rect(self, canvas, x1, y1, x2, y2, r, **kwargs):
        """Draw a rounded rectangle on a canvas and return the polygon id."""
        r = min(r, (x2 - x1) / 2, (y2 - y1) / 2)
        points = [
            x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r, x2, y2 - r, x2, y2,
            x2 - r, y2, x1 + r, y2, x1, y2, x1, y2 - r, x1, y1 + r, x1, y1,
        ]
        return canvas.create_polygon(points, smooth=True, **kwargs)








    @staticmethod
    def _widget_alive(widget):
        try:
            return bool(widget.winfo_exists())
        except tk.TclError:
            return False

    def track_theme(self, widget, **option_map):
        self.themed_widgets.append((widget, option_map))
        # Sections rebuilt per visit re-register, and only a theme switch
        # pruned (339 -> 809 entries over 175 visits): pruned whenever it
        # doubles, a constant cost per call, averaged.
        if len(self.themed_widgets) >= 2 * getattr(self, "_themed_pruned_at", 256):
            self._prune_themed_widgets()
        widget.configure(**{opt: palette_value(self.colors, key)
                            for opt, key in option_map.items()})
        return widget

    def _prune_themed_widgets(self):
        """Drop the registry's entries for widgets that no longer exist."""
        self.themed_widgets = [
            (w, m) for w, m in self.themed_widgets
            if self._widget_alive(w)]
        self._themed_pruned_at = max(256, len(self.themed_widgets))

    # Tk paints a tick box's mark in its text colour, so a box with words
    # draws its own: light well, dark mark, on every theme. ISSUES_LOG:
    # "The tick that took the colour of its words".
    TICK_BOX = 13

    def _paint_tick_images(self):
        """The empty and the ticked box, (re)drawn in the current theme."""
        images = getattr(self, "_tick_images", None)
        if images is None:
            images = self._tick_images = tuple(
                tk.PhotoImage(master=self, width=self.TICK_BOX + self.px(4),
                              height=self.TICK_BOX) for _ in range(2))
        # TICK_BOX is already this screen's size (_SIZES_AT_100); the mark
        # inside it is drawn at 100% and stretched the same way.
        size, rim, pen = self.TICK_BOX, self.px(1), self.px(2)
        s = self._ui_scale
        for image, ticked in zip(images, (False, True)):
            image.blank()
            image.put(self.colors["subtext"], to=(0, 0, size, size))
            image.put(self.colors["check_well"], to=(rim, rim, size - rim, size - rim))
            if ticked:
                for (x0, y0), (x1, y1) in (((2, 6), (5, 9)), ((5, 9), (10, 3))):
                    x0, y0, x1, y1 = x0 * s, y0 * s, x1 * s, y1 * s
                    steps = max(1, round(max(abs(x1 - x0), abs(y1 - y0))))
                    for k in range(steps + 1):
                        x = round(x0 + (x1 - x0) * k / steps)
                        y = round(y0 + (y1 - y0) * k / steps)
                        image.put(self.CARD_CHECK_MARK, to=(x, y, x + pen, y + pen))
        return images

    def _drawn_tick_box(self, box, bg, fg, track):
        """Give a tick box that carries words a drawn box. `bg` and `fg`
        are palette keys; `track` for a box that lives as long as the app
        (one rebuilt with its panel takes the colours as they are)."""
        # Painted once; a theme switch paints them again. Painted for every
        # box, each paint redrew every box made before: 2,500 took 150 s.
        empty, ticked = (getattr(self, "_tick_images", None)
                         or self._paint_tick_images())
        box.configure(indicatoron=False, image=empty, selectimage=ticked,
                      compound="left", relief="flat", offrelief="flat",
                      overrelief="flat", bd=0, highlightthickness=0,
                      cursor="hand2")
        # selectcolor floods a drawn box's whole button when ticked; it
        # matches the surface, so only the drawn mark changes.
        colours = dict(bg=bg, fg=fg, selectcolor=bg, activebackground=bg,
                       activeforeground=fg)
        if track:
            self.track_theme(box, **colours)
        else:
            box.configure(**{opt: self.colors[key] for opt, key in colours.items()})
            # Its panel is not rebuilt by a theme switch while it is open:
            # _recolor_stragglers lays these keys again from the new palette.
            box.palette_keys = colours
        return box


    def toggle_theme(self):
        """Quick toggle between the last dark and last light theme. Kept for the
        existing 'Switch to Light/Dark mode' button."""
        if self.theme_name in DARK_THEMES:
            self.set_theme(self._last_light_theme)
        else:
            self.set_theme(self._last_dark_theme)

    def set_theme(self, name):
        """Switch to any named theme variant and persist the choice."""
        if name not in THEMES:
            return
        self.theme_name = name
        self.colors = THEMES[name]
        # Remember the last dark/light pick so the quick toggle feels natural.
        if name in DARK_THEMES:
            self._last_dark_theme = name
        elif name in LIGHT_THEMES:
            self._last_light_theme = name
        self.save_theme_setting()
        self.apply_theme()
        # Refresh the theme picker if it's open.
        refresh = getattr(self, "_refresh_theme_picker", None)
        if callable(refresh):
            try:
                refresh()
            except tk.TclError:
                self._refresh_theme_picker = None

    def apply_theme(self):
        self.configure(bg=self.colors["bg"])
        # The window's frame last: changed first, the switch looked like it
        # happened twice (field report).
        self.after_idle(self._paint_title_bar)
        self.after_idle(self._set_window_icon)
        # Dead entries first: each cost a caught TclError per switch.
        self._prune_themed_widgets()
        for widget, option_map in self.themed_widgets:
            try:
                widget.configure(**{opt: palette_value(self.colors, key)
                                    for opt, key in option_map.items()})
            except tk.TclError:
                pass
        self._refresh_placeholder_colors()
        # The drawn tick boxes share two images; redrawn, every box follows.
        if getattr(self, "_tick_images", None) is not None:
            self._paint_tick_images()
        # Tables are repainted in place (rebuilt, they flickered); a grid gone
        # or stale is rebuilt. The cell is committed first, or its typing
        # went with the canvas; a row being typed stays text.
        self._commit_cell_editor()
        if not self._recolor_table_grids():
            self._render_table_grids(keep_typed=self._row_being_typed())
        # Text highlights are painted blended toward the theme surface
        # (the cells' own recipe); the new surface needs a re-blend.
        if hasattr(self, "body_text"):
            self._retint_highlight_tags(self.body_text)
        # The spelling underline is a tag's colour, which no tracked widget
        # option reaches.
        self._spell_recolor()
        # The editor's quick toggle shows where a press would take you.
        try:
            self.editor_theme_btn.configure(
                text="☀" if self.theme_name in DARK_THEMES else "🌙")
        except tk.TclError:
            pass
        self.refresh_weekday_buttons()
        self._paint_end_fields()
        self.style_notebook()
        # Statistics is not re-rendered: a theme changes no figure, and its
        # rebuild churned on the very page the switch is made from. The
        # calendar skips itself when unseen (in render_calendar).
        self.render_calendar()
        # Safety net: catch any widget that slipped through the registered list
        # (e.g. built once and never rebuilt) by swapping known theme colors from
        # the OTHER theme to the current one. This guarantees a clean flip.
        self._recolor_stragglers()
        # The Settings nav glyphs are canvas items, which track_theme does
        # not reach: repainted, as the theme picker's cards are.
        self._recolor_settings_nav_icons()
        # The alignment icons are canvas-drawn for the same reason and need
        # the same treatment; this repaints their bars along with restoring
        # every paragraph button's pressed state in the new palette.
        self._refresh_list_buttons()
        # The cards recoloured in place: a rebuild was ~85ms of ~121ms and
        # the list flickered. AFTER the stragglers, so a note's own colour
        # that matches a palette entry (#4cd9a3) is not swapped.
        self._recolor_note_cards()
        # Checklist rows are untracked, and the stragglers' bg/fg leaves the
        # tick wells (selectcolor) old: recoloured as the cards are.
        self._recolor_checklist_boxes()
        # The find colours re-tinted, and the cell flash redrawn in the new
        # accent (a rebuild tears it off; nothing if find is closed).
        if hasattr(self, "body_text"):
            self._retint_find_tags(self.body_text)
        self._find_reflash()
        self._find_paint_entry()
        # (The History register's rebuilt rows need no hook here: the
        # straggler pass above recolors them — qa7's theme-while-open
        # check guards that promise regardless of mechanism.)

    def _recolor_checklist_boxes(self):
        """Repaint the live checklist rows' Checkbutton wells for the
        current palette. The rows rebuild on every note load, so tracking
        them would leak (the note-card lesson); the straggler net covers
        their bg/fg but not selectcolor/activebackground."""
        rows = getattr(self, "_checklist_rows", None)
        if rows is None:
            return

        def walk(w):
            for c in w.winfo_children():
                if isinstance(c, tk.Checkbutton):
                    try:
                        c.configure(selectcolor=self.colors["check_well"],
                                    activebackground=self.colors["card"])
                    except tk.TclError:
                        pass
                walk(c)

        try:
            for chunk in rows.chunks:
                walk(chunk)
            # The straggler pass laid every row's border to the new card;
            # the row the keyboard is on keeps its ring.
            held = self.focus_get()
            if isinstance(held, tk.Checkbutton) and held.master.master in rows.chunks:
                self._ring_checklist_row(held, True)
        except (tk.TclError, KeyError):
            pass

    def _calendar_is_showing(self):
        """True only if the Calendar tab is the one currently selected AND
        the notebook itself is visible (Settings replaces it). Uses the
        notebook's own selection rather than winfo_ismapped(), which
        pack()/pack_forget() don't update synchronously."""
        tab = self._calendar_tab
        if tab is None:
            return True  # unknown layout: rebuild rather than risk staleness
        # Settings is told by the flag its two swap methods set, not by
        # winfo_ismapped(), which lags until idle: leaving Settings rebuilt
        # nothing, the notebook still read as hidden.
        if getattr(self, "_settings_open", False):
            return False
        try:
            return str(self.notebook.select()) == str(tab)
        except tk.TclError:
            return True

    def _recolor_stragglers(self):
        """Walk the whole widget tree and fix any bg/fg still set to a color from
        a DIFFERENT theme. With several themes, a widget could carry a color from
        any of them, so we remap from every other theme to the current one. This
        keeps each theme clean no matter which one you switch from."""
        cur = self.colors
        remap = {}
        for name, palette in THEMES.items():
            if name == self.theme_name:
                continue
            for key, val in palette.items():
                if key in cur and isinstance(val, str) and val.startswith("#"):
                    # Don't overwrite a color that's also valid in the current
                    # theme (same hex used by both) — only remap true mismatches.
                    if val.lower() != cur[key].lower():
                        remap[val.lower()] = cur[key]
        # Surfaces BLENDED from a palette (Settings' wells and hairlines) are
        # in none, so the loop above missed them: the information bars stayed
        # dark, and unreadable, on a light theme.
        for name, palette in THEMES.items():
            if name == self.theme_name:
                continue
            for derive in (inset_surface, hairline):
                was, now = derive(palette), derive(cur)
                if was.lower() != now.lower():
                    remap[was.lower()] = now

        # Current theme's own colors must never be remapped away.
        for key, val in cur.items():
            if isinstance(val, str) and val.startswith("#"):
                remap.pop(val.lower(), None)
        for derive in (inset_surface, hairline):
            remap.pop(derive(cur).lower(), None)
        # Words on a fill follow the fill, not the remap: white is also a
        # light theme's card, and the new fill may want near-black instead.
        fills = {cur[role].lower()
                 for role in ("accent", "accent_hover", "danger", "success")}
        letters = {"white", LETTERS_LIGHT, LETTERS_DARK}

        def walk(w):
            try:
                words = str(w.cget("fg")).lower()
            except tk.TclError:
                words = None
            for opt in ("bg", "fg"):
                if opt == "fg" and words in letters:
                    continue
                try:
                    val = str(w.cget(opt)).lower()
                except tk.TclError:
                    continue
                if val in remap:
                    try:
                        w.configure(**{opt: remap[val]})
                    except tk.TclError:
                        pass
            if words in letters:
                try:
                    ground = str(w.cget("bg")).lower()
                    if ground in fills:
                        w.configure(fg=letters_on(ground))
                    elif words in remap:
                        w.configure(fg=remap[words])
                except tk.TclError:
                    pass
            # Colours this walk cannot see -- a ticked box's fill, a caret, a
            # pressed button -- on a widget no theme switch rebuilds: it
            # names their palette keys (_drawn_tick_box sets them too).
            keys = getattr(w, "palette_keys", None)
            if keys:
                try:
                    w.configure(**{opt: palette_value(cur, key)
                                   for opt, key in keys.items()})
                except tk.TclError:
                    pass
            if hasattr(w, "_ring_rest"):
                self._recolor_ring(w, remap, letters, held)
            for child in w.winfo_children():
                walk(child)

        try:
            held = str(self.tk.call("focus"))
            walk(self)
        except tk.TclError:
            pass
        # An open day's stripes are the notes' own colours, which the walk
        # above swapped (#4cd9a3 is a palette's too): drawn again from the
        # notes, as _recolor_note_cards does, even under Settings.
        if self._day_panel_mode == "list":
            self.show_day_list()

    def _recolor_ring(self, w, remap, letters, held):
        """The keyboard's ring keeps its two colours on the widget, for its
        coming and going (_ring_shown), where the walk above cannot see them:
        the reminder bar's kept an old theme's accent and words. They follow
        as the walk's own colours do -- words on a fill follow the fill."""
        rest, on = w._ring_rest, w._ring_on
        if rest is not None and str(rest).lower() in remap:
            w._ring_rest = remap[str(rest).lower()]
        if on is not None:
            on = str(on).lower()
            try:
                if on in letters:
                    w._ring_on = letters_on(str(w.cget("bg")))
                elif on in remap:
                    w._ring_on = remap[on]
            except tk.TclError:
                pass
        self._ring_shown(w, held == str(w))

    def _refresh_placeholder_colors(self):
        # self._placeholders only grows, and a colour picker's hex box dies
        # with its popup: the next switch crashed reading it. Dead entries
        # are dropped the first time they are found.
        alive = []
        for entry, placeholder in self._placeholders:
            try:
                if entry.get() == placeholder:
                    entry.config(fg=self.colors["subtext"])
                else:
                    entry.config(fg=self.colors["text"])
                alive.append((entry, placeholder))
            except tk.TclError:
                pass
        self._placeholders = alive

    def style_notebook(self):
        self.style_ttk()

    def style_ttk(self):
        """Theme the notebook tabs and the scrollbars, two of the three ttk
        widgets the app uses, so they follow the theme; ttk widgets ignore
        normal bg/fg, so this goes through ttk.Style. The third, the export
        and import progress bar, keeps the clam theme's own colours."""
        style = ttk.Style()
        try:
            style.theme_use("clam")
        except tk.TclError:
            pass

        c = self.colors

        # --- Notebook tabs ---
        style.configure("TNotebook", background=c["bg"], borderwidth=0)
        style.configure(
            "TNotebook.Tab", background=c["sidebar"], foreground=c["text"],
            padding=self.TAB_PADDING, font=("Segoe UI", 10, "bold"),
            focuscolor=self._tab_ring_colour()
        )
        # clam maps its own padding for the selected tab, which beat the one
        # above and drew the open tab SMALLER than the others. Restated here,
        # it stands taller instead: a raised tab, readable without its colour.
        style.map(
            "TNotebook.Tab",
            background=[("selected", c["accent"])],
            foreground=[("selected", self._on_fill("accent"))],
            padding=[("selected", self.TAB_PADDING_SELECTED)],
        )

        # --- Scrollbars (every ttk.Scrollbar in the app uses these default
        # style names, so styling them here re-themes all of them at once). ---
        for orient in ("Vertical", "Horizontal"):
            name = f"{orient}.TScrollbar"
            style.configure(
                name,
                background=c["card"],       # the draggable thumb
                troughcolor=c["sidebar"],   # the track behind it
                bordercolor=c["sidebar"],
                arrowcolor=c["subtext"],
                relief="flat",
                borderwidth=0,
                arrowsize=12,
            )
            style.map(
                name,
                background=[("active", c["accent"]), ("pressed", c["accent"])],
                arrowcolor=[("active", self._on_fill("accent")),
                            ("pressed", self._on_fill("accent"))],
            )

    @staticmethod
    def _blend(hex_a, hex_b, t):
        """Mix two #rrggbb colors. t=0 -> hex_a, t=1 -> hex_b."""
        return core_blend(hex_a, hex_b, t)

    # ---------- Resizing the window by its edge ----------
    # A layout cost 70-260 ms a step, in Tk, and the edge crawled: while
    # the button holds it, the content waits for a pause or the release.
    RESIZE_PAUSE_MS = 120   # a held drag this still is laid out anyway
    RESIZE_WATCH_MS = 40    # how often a held drag looks for the release

    def _on_main_canvas_configure(self, event):
        self._show_page_scrollbar(event.width < self._main_min_width)
        self._main_size_wanted = (max(event.width, self._main_min_width),
                                  event.height)
        if self._pointer_button_held() and not self._page_follows_the_drag():
            self._wait_for_resize_to_settle()
            return
        self._lay_out_at_window_size()

    def _show_page_scrollbar(self, needed):
        """The window's horizontal scrollbar, only while the window is
        narrower than the sidebar and the editor side by side, as a table's
        own bar is shown only when the table is wider than the editor
        (_fit_grid). Packed for good, it sat under every window wide enough
        not to need it. Its showing changes the window's height, never its
        width, so the answer cannot flip back and forth."""
        bar = self._main_hscroll
        if bar is None or needed == self._is_placed(bar):
            return
        if needed:
            bar.pack(side="bottom", fill="x", before=self.main_canvas)
        else:
            bar.pack_forget()

    def _page_follows_the_drag(self):
        """Whether the page is laid out at every step of a held drag: the
        month alone, one canvas, under 40 ms a step. Widget pages cost 70 ms
        and more and wait -- History, and an open day's panel (60-150 ms a
        step, measured), among them."""
        return (self._calendar_is_showing()
                and not self._history_visible
                and self._day_panel_mode == "empty")

    def _lay_out_at_window_size(self):
        """Give the window's content the window's size: the one place it
        happens, whether at once or when a drag settles."""
        for name in ("_resize_pause_job", "_resize_watch_job"):
            job = getattr(self, name, None)
            if job is not None:
                try:
                    self.after_cancel(job)
                except (tk.TclError, ValueError):
                    pass
                setattr(self, name, None)
        size = getattr(self, "_main_size_wanted", None)
        if size is None or size == getattr(self, "_main_size_laid_out", None):
            return
        try:
            self.main_canvas.itemconfig(self._main_window_item,
                                        width=size[0], height=size[1])
        except tk.TclError:
            return
        self._main_size_laid_out = size

    def _wait_for_resize_to_settle(self):
        """A held drag of the edge: lay out after a pause in it, or at the
        release, whichever comes first."""
        job = getattr(self, "_resize_pause_job", None)
        if job is not None:
            try:
                self.after_cancel(job)
            except (tk.TclError, ValueError):
                pass
        self._resize_pause_job = self.after(self.RESIZE_PAUSE_MS,
                                            self._lay_out_at_window_size)
        if getattr(self, "_resize_watch_job", None) is None:
            self._resize_watch_job = self.after(self.RESIZE_WATCH_MS,
                                                self._watch_resize_release)

    def _watch_resize_release(self):
        """One look at the mouse button during a held drag: still down,
        look again shortly; let go, lay the window out now."""
        self._resize_watch_job = None
        if not self._still_alive():
            return
        if self._pointer_button_held():
            self._resize_watch_job = self.after(self.RESIZE_WATCH_MS,
                                                self._watch_resize_release)
            return
        self._lay_out_at_window_size()

    def _pointer_button_held(self):
        """Whether the mouse's primary button is down, asked of Windows (the
        edge is the system's; Tk hears only sizes), swapped buttons allowed
        for. Elsewhere, or if asking fails, no: the behaviour from before."""
        if not sys.platform.startswith("win"):
            return False
        try:
            import ctypes
            user32 = ctypes.windll.user32
            swapped = user32.GetSystemMetrics(23)       # SM_SWAPBUTTON
            key = 0x02 if swapped else 0x01              # VK_RBUTTON, VK_LBUTTON
            return bool(user32.GetAsyncKeyState(key) & 0x8000)
        except Exception:                                # noqa: BLE001
            return False

    # ---------- UI construction ----------
    def build_ui(self):
        self._placeholders = []

        self.style_notebook()

        # --- Outer horizontal-scroll wrapper ---
        self.main_canvas = tk.Canvas(self, highlightthickness=0)
        self.track_theme(self.main_canvas, bg="bg")
        # Packed only while the window is too narrow (_show_page_scrollbar).
        self._main_hscroll = ttk.Scrollbar(self, orient="horizontal",
                                           command=self.main_canvas.xview)

        self.main_canvas.pack(side="top", fill="both", expand=True)
        self.main_canvas.configure(xscrollcommand=self._main_hscroll.set)

        self.main_inner = tk.Frame(self.main_canvas)
        self.track_theme(self.main_inner, bg="bg")
        main_window = self.main_canvas.create_window((0, 0), window=self.main_inner, anchor="nw")

        def _on_inner_configure(event):
            self.main_canvas.configure(scrollregion=self.main_canvas.bbox("all"))

        # Read by _on_main_canvas_configure, which gives the content the
        # window's size -- at once, or when a drag of the edge settles.
        self._main_window_item = main_window
        self._main_min_width = self.px(SIDEBAR_WIDTH + EDITOR_MIN_WIDTH)

        self.main_inner.bind("<Configure>", _on_inner_configure)
        self.main_canvas.bind("<Configure>", self._on_main_canvas_configure)

        def _on_shift_wheel(event):
            self.main_canvas.xview_scroll(int(-1 * (event.delta / 120)), "units")
        self.main_canvas.bind("<Shift-MouseWheel>", _on_shift_wheel)

        # --- Reminder bar (subtle, dismissable, shown once per day) ---
        # Sits above the tabs. Hidden unless there are notes due today AND it
        # hasn't already been shown/dismissed today.
        self.reminder_bar = tk.Frame(self.main_inner)
        self.track_theme(self.reminder_bar, bg="accent")
        # packed on demand by maybe_show_reminder()

        # --- Autosave toast: a small floating banner, always near the top of
        # the window regardless of scroll position or which tab is active, so
        # "auto-saved" feedback is never missed inside a long note. ---
        self.toast_frame = tk.Frame(self, bg=self.colors["success"])
        self.toast_lbl = tk.Label(
            self.toast_frame, font=("Segoe UI", 9, "bold"),
            bg=self.colors["success"], fg=self._on_fill("success"), padx=14, pady=6)
        self.toast_lbl.pack(side="left")
        # The toast's one action ("Undo"), packed on demand; coloured at each
        # showing in _show_toast(), not tracked, as nobody sees it between.
        self.toast_action_lbl = tk.Label(
            self.toast_frame, font=("Segoe UI", 9, "bold", "underline"),
            bg=self.colors["success"], fg=self._on_fill("success"), padx=0, pady=5,
            cursor="hand2")
        self._toast_action = None
        self.toast_action_lbl.bind(
            "<Button-1>", lambda _e: self._run_toast_action())
        # A Tab stop (its ring the pixel of padding it gave up), and Ctrl+Z
        # outside a text box while it is offered (_toast_undo_key).
        self._ring_round(self.toast_action_lbl)
        self._pressable(self.toast_action_lbl, self._run_toast_action_by_key)
        for _key in ("<Control-z>", "<Control-Z>"):
            self.bind_all(_key, self._toast_undo_key, add="+")
        self._toast_hide_job = None
        # Not placed yet — shown on demand by _show_toast().

        # --- Export progress bar: an overlay like the toast, seen from any
        # tab while the export runs. Placed on demand. ---
        self.export_progress_frame = tk.Frame(self, bg=self.colors["card"],
                                              highlightthickness=1,
                                              highlightbackground=self.colors["accent"])
        export_inner = tk.Frame(self.export_progress_frame, bg=self.colors["card"])
        export_inner.pack(padx=14, pady=10)
        self.export_progress_lbl = tk.Label(
            export_inner, text="Exporting…", font=("Segoe UI", 9, "bold"),
            bg=self.colors["card"], fg=self.colors["text"])
        self.export_progress_lbl.pack(anchor="w")
        # Long-lived and shown on demand: untracked, a theme switched
        # before the next export left the bar's frame painted in the old
        # palette (audit Z07-F03's class — track every colour option).
        self.track_theme(self.export_progress_frame, bg="card",
                         highlightbackground="accent")
        self.track_theme(export_inner, bg="card")
        self.track_theme(self.export_progress_lbl, bg="card", fg="text")
        self.export_progress_bar = ttk.Progressbar(
            export_inner, orient="horizontal", length=240, mode="determinate")
        self.export_progress_bar.pack(pady=(6, 0))
        self._export_state = None  # dict shared with the background thread
        self._import_state = None  # same idea, for import
        self._export_poll_job = None

        # --- Notebook: Notes and Calendar. Settings is a page instead
        # (show_settings_page): as a tab it read as just another tab. ---
        self.notebook = ttk.Notebook(self.main_inner)
        self.notebook.pack(fill="both", expand=True)
        # Its focus ring is for the keyboard (_tab_ring_colour): a click
        # hides it, a key on the tabs or a Tab that lands on them shows it.
        self.notebook.bind("<ButtonPress-1>",
                           lambda e: self._set_tab_ring(False), add="+")
        for _key in ("<Left>", "<Right>"):   # the keys that walk the tabs
            self.notebook.bind(_key, lambda e: self._set_tab_ring(True), add="+")
        # Tk walks the keyboard on these virtual events, not on <Tab> itself;
        # "+" runs this after its own traversal, which it must never replace.
        self.bind_all("<<NextWindow>>", self._tab_ring_if_tabbed_to, add="+")
        self.bind_all("<<PrevWindow>>",
                      lambda e: self._tab_ring_if_tabbed_to(e, backwards=True),
                      add="+")
        # And what a Tab lands on is scrolled into sight (_bring_into_sight).
        self.bind_all("<<NextWindow>>", self._tab_target_into_sight, add="+")
        self.bind_all("<<PrevWindow>>",
                      lambda e: self._tab_target_into_sight(e, backwards=True),
                      add="+")
        self._bind_keyboard_tags()
        # Tk's Entry edits no Windows box has (Ctrl+D, Ctrl+K, Ctrl+T) changed
        # a title saved at once, with no Undo.
        for seq in ("<Control-d>", "<Control-D>", "<Control-k>", "<Control-K>",
                    "<Control-t>", "<Control-T>"):
            self.bind_class("Entry", seq, lambda _e: "break")
        self._watch_parts_put_away()

        notes_tab = tk.Frame(self.notebook)
        self.track_theme(notes_tab, bg="bg")
        calendar_tab = tk.Frame(self.notebook)
        self.track_theme(calendar_tab, bg="bg")

        self.notebook.add(notes_tab, text="📝 Notes")
        self.notebook.add(calendar_tab, text="📅 Calendar")
        # Kept so a theme switch can tell whether the calendar is actually
        # on screen, and skip rebuilding it if not — see apply_theme.
        self._calendar_tab = calendar_tab

        # Looked up from the notebook itself rather than hardcoded — stays
        # correct even if a tab is ever added, removed, or reordered again.
        self.TAB_NOTES = self.notebook.index(notes_tab)
        self.TAB_CALENDAR = self.notebook.index(calendar_tab)

        # Settings page: a sibling of the notebook (not inside it), in the
        # same parent, so showing it is a simple pack-forget/pack swap.
        self.settings_page = tk.Frame(self.main_inner)
        self.track_theme(self.settings_page, bg="bg")
        # Not packed yet — hidden until show_settings_page() is called.

        self.build_notes_tab(notes_tab)
        self.build_calendar_tab(calendar_tab)
        self.build_settings_tab(self.settings_page)

        def _on_tab_changed(event):
            try:
                shown = self.notebook.index(self.notebook.select())
            except tk.TclError:
                return
            self._catch_up_deferred_refresh()
            # The find bar belongs to the note: leaving for the Calendar
            # puts it away (her re-test, case 600). Ctrl+F from there
            # comes back to Notes first, so it is not closed on arrival.
            if shown != self.TAB_NOTES:
                self._hide_find()
            # The tab's home is the month: leaving it resets History, which
            # reopened two tab switches later (field report).
            if self._history_visible:
                self._hide_calendar_history()
            # Focus parked on the notebook: some platforms hand it to the
            # tab's first Entry, and the hidden note list kept it -- Alt+Up
            # reordered notes nobody could see.
            try:
                focused = self.focus_get()
                held = self._keyboard_inside(self.notebook)
                if isinstance(focused, (tk.Entry, tk.Text)) or (
                        held is not None and held is not self.notebook
                        and not held.winfo_viewable()):
                    self.notebook.focus_set()
            except (tk.TclError, KeyError):
                pass
        self.notebook.bind("<<NotebookTabChanged>>", _on_tab_changed, add="+")
        # Notes <-> Calendar: same rule -- a popup belongs to the page it
        # was opened on.
        self.notebook.bind("<<NotebookTabChanged>>",
                           lambda e: self._dismiss_mini_popup(), add="+")



    def toggle_sidebar(self):
        """Hide or show the left sidebar (note list + New Note / Import / Share)
        so the editor can use the full width. The thin toggle strip stays put so
        the sidebar can always be brought back."""
        if self._sidebar_hidden:
            # Show it again — re-pack before the toggle strip to keep the order
            # sidebar → toggle → editor.
            self.sidebar.pack(side="left", fill="y", before=self.sidebar_toggle)
            self.sidebar_toggle_lbl.config(text="‹")
            self._sidebar_hidden = False
        else:
            self.sidebar.pack_forget()
            self.sidebar_toggle_lbl.config(text="›")
            self._sidebar_hidden = True
            # The keyboard on the list hidden by a click on the arrow: its keys
            # (Alt+arrows move a note) still acted on a list out of sight.
            if self._keyboard_inside(self.sidebar) is not None:
                self._keyboard_to(self.sidebar_toggle)

    def build_notes_tab(self, parent):
        """The Notes page: the list on the left, the editor on the right,
        built top to bottom in the order they are drawn."""
        self._build_note_sidebar(parent)
        self._build_editor_frame(parent)
        self._build_editor_banners()
        self._build_title_and_meta_rows()
        self._build_format_bar()
        self._build_body_text()
        self._build_editor_tools()
        self._build_editor_actions()

    def _build_note_sidebar(self, parent):
        """The list's side: search, Sort and Show and the grouping above;
        the selection bar, the list and its buttons below."""
        # --- Sidebar (note list) ---
        self.sidebar = tk.Frame(parent, width=self.px(SIDEBAR_WIDTH))
        self.track_theme(self.sidebar, bg="sidebar")
        self.sidebar.pack(side="left", fill="y")
        self.sidebar.pack_propagate(False)

        title_lbl = tk.Label(self.sidebar, text="📝 My Notes", font=("Segoe UI", 16, "bold"))
        self.track_theme(title_lbl, bg="sidebar", fg="text")
        title_lbl.pack(pady=(20, 0), padx=15, anchor="w")

        self.greeting_lbl = tk.Label(
            self.sidebar, font=("Segoe UI", 9),
            # Wraps instead of overflowing past the sidebar's fixed width —
            # a safety net independent of the username length cap, in case a
            # name ever ends up longer than expected some other way.
            wraplength=self.px(SIDEBAR_WIDTH - 30), justify="left"
        )
        self.track_theme(self.greeting_lbl, bg="sidebar", fg="subtext")
        self.greeting_lbl.pack(pady=(2, 12), padx=15, anchor="w")
        self._refresh_greeting()

        self.search_var = tk.StringVar()
        self._search_debounce_job = None

        def _debounced_search_refresh(*args):
            # The ✕ first, and NOT on the timer: whether the box holds a real
            # query is known now, and a clear button that appeared a fifth of
            # a second after the typing would read as a glitch.
            self._refresh_search_clear()
            # Filtering reads every note, so it waits for a pause in typing,
            # as autosave does: per keystroke, a big notebook lagged.
            if self._search_debounce_job is not None:
                try:
                    self.after_cancel(self._search_debounce_job)
                except (tk.TclError, ValueError):
                    pass
            self._search_debounce_job = self.after(180, self.refresh_note_list)

        self.search_var.trace_add("write", _debounced_search_refresh)
        # The entry and its ✕ share a frame wearing the entry's own fill, so
        # the button reads as sitting inside the box rather than beside it.
        # The row carries the padding the entry used to carry itself.
        search_row = tk.Frame(self.sidebar)
        self.track_theme(search_row, bg="card")
        search_row.pack(fill="x", padx=15, pady=(0, 10))
        self.search_entry = search_entry = tk.Entry(
            search_row, textvariable=self.search_var,
            insertbackground=self.colors["text"], relief="flat", font=("Segoe UI", 11)
        )
        self.track_theme(search_entry, bg="card", fg="text", insertbackground="text")
        self._guard_entry_astral(search_entry)
        search_entry.pack(side="left", fill="x", expand=True, ipady=6)
        # The most-used field in the app was the only text field without one.
        self._add_paste_menu(search_entry)
        # Built once, so track_theme, every colour option: an untracked
        # activebackground kept the old accent.
        self.search_clear_btn = tk.Button(
            search_row, text="✕", command=self._clear_search,
            relief="flat", bd=0, cursor="hand2", font=("Segoe UI", 9, "bold"),
            highlightthickness=0)
        self.track_theme(self.search_clear_btn, bg="card", fg="subtext",
                         activebackground="card", activeforeground="text",
                         highlightbackground="card")
        self.add_placeholder(search_entry, "Search notes...")
        # The trace has settled the ✕ already; called anyway, so reordering
        # these lines cannot break it.
        self._refresh_search_clear()
        # ...and it scheduled a list rebuild for a search nobody typed: a
        # second full rebuild at every startup, on top of the one the
        # launch runs anyway (~55 ms at 5,000 notes, measured).
        if self._search_debounce_job is not None:
            try:
                self.after_cancel(self._search_debounce_job)
            except (tk.TclError, ValueError):
                pass
            self._search_debounce_job = None

        # Sort + category filter row, captioned: both show their VALUE, and
        # "All" read as a state. The captions sit ABOVE the 250px row, which
        # has no width to spare, each over its control's edge.
        caption_row = tk.Frame(self.sidebar)
        self.track_theme(caption_row, bg="sidebar")
        caption_row.pack(fill="x", padx=15, pady=(0, 1))
        sort_caption = tk.Label(caption_row, text="Sort", font=("Segoe UI", 8),
                                anchor="w")
        self.track_theme(sort_caption, bg="sidebar", fg="subtext")
        sort_caption.pack(side="left")
        show_caption = tk.Label(caption_row, text="Show", font=("Segoe UI", 8),
                                anchor="e")
        self.track_theme(show_caption, bg="sidebar", fg="subtext")
        show_caption.pack(side="right")

        filter_row = tk.Frame(self.sidebar)
        self.track_theme(filter_row, bg="sidebar")
        filter_row.pack(fill="x", padx=15, pady=(0, 8))

        # Human label -> (key function description) handled in refresh_note_list
        self.SORT_OPTIONS = [
            "Recently updated",
            "Oldest updated",
            "Title A–Z",
            "Title Z–A",
            "Category",
            "Calendar: soonest",
            "Calendar: oldest",
            self.SORT_CUSTOM,
        ]
        # Remembered, as "Group by category" below is, and validated on the
        # way IN: a settings file may name a sort this version lacks.
        _stored_sort = load_settings().get("note_sort")
        self.sort_var = tk.StringVar(
            value=_stored_sort if _stored_sort in self.SORT_OPTIONS
            else self.SORT_OPTIONS[0])
        self.sort_var.trace_add(
            "write", lambda *a: save_setting("note_sort", self.sort_var.get()))
        # width_chars=0: this control FLEXES. 18 chars fit the label, but the
        # row asked 260px of 250 and lost this arrow; no fixed number fits
        # both Segoe UI and DejaVu Sans.
        sort_menu = self._build_themed_dropdown(
            filter_row, self.sort_var, self.SORT_OPTIONS,
            on_change=self._on_sort_chosen, width_chars=0)

        # As the sort; a stored filter may name a category gone, so
        # _keep_filter_valid asks the dropdown's own vocabulary, below.
        self.filter_var = tk.StringVar(
            value=load_settings().get("note_filter", "All"))
        self.filter_var.trace_add(
            "write",
            lambda *a: save_setting("note_filter", self.filter_var.get()))
        self.filter_menu = self._build_themed_dropdown(
            filter_row, self.filter_var, self._filter_options,
            on_change=lambda v: self.refresh_note_list(),
            # Content-sized too, anchored right: the sort absorbs the rest,
            # a long category name included.
            dot_color_fn=lambda v: CATEGORY_COLORS.get(v), width_chars=0)
        # Packed FIRST so pack honours its width — packed last on a full
        # row, the button was squeezed to a bare "🔁 R…" (seen in a
        # screenshot, not guessed). The sort button flexes instead.
        self.filter_menu.pack(side="right")
        sort_menu.pack(side="left", fill="x", expand=True, padx=(0, 4))
        # After the dropdown exists (the guard's hasattr): an unknown filter
        # falls back to All before anything reads it.
        self._keep_filter_valid()

        # Group by category — an independent toggle. When on, notes are
        # clustered under collapsible category headers instead of one flat
        # list; sorting still applies within each group.
        self.group_by_category = tk.BooleanVar(
            value=bool(load_settings().get("group_by_category", False)))
        # Category names only, no more than there can be categories: a list
        # in a hand-edited settings.json holding a dict stopped the app
        # starting, and one of a million names rode every settings write.
        saved_groups = load_settings().get("collapsed_groups")
        self.collapsed_groups = (
            {g for g in saved_groups[:MAX_CATEGORIES] if isinstance(g, str)}
            if isinstance(saved_groups, list) else set())
        group_row = tk.Frame(self.sidebar)
        self.track_theme(group_row, bg="sidebar")
        group_row.pack(fill="x", padx=15, pady=(0, 8))
        group_cb = tk.Checkbutton(
            group_row, text="Group by category", variable=self.group_by_category,
            command=self._on_toggle_group_by_category,
            font=("Segoe UI", 8), anchor="w")
        # Built ONCE and kept for the whole session, so its colours are
        # tracked live, unlike the boxes in panels rebuilt on every visit.
        self._drawn_tick_box(group_cb, "sidebar", "subtext", track=True)
        group_cb.pack(side="left")

        # Multi-select: pick several notes at once for a bulk action (move to
        # trash, change category), instead of doing each one individually.
        self.selection_mode = False
        self.selected_note_ids = set()
        self.select_toggle_btn = tk.Button(
            group_row, text="☑ Select", command=self._toggle_selection_mode,
            relief="flat", font=("Segoe UI", 8, "bold"), cursor="hand2"
        )
        self.track_theme(self.select_toggle_btn, bg="card", fg="subtext")
        self.select_toggle_btn.pack(side="right", ipadx=6, ipady=2)
        self._build_bulk_action_bar()
        self._build_note_list_and_buttons(parent)

    def _build_bulk_action_bar(self):
        """The bar a selection acts through, built hidden."""
        # Bulk-action bar, hidden until selection mode; built once, tracked.
        self.bulk_action_bar = tk.Frame(self.sidebar)
        self.track_theme(self.bulk_action_bar, bg="sidebar")
        # The count, then the actions two by two: in one line the last got
        # what was left (Export ONE pixel on Linux). Two a row need 180px at
        # most, each filling its half.
        self.bulk_selected_lbl = tk.Label(
            self.bulk_action_bar, text="0 selected", font=("Segoe UI", 8, "bold"))
        self.track_theme(self.bulk_selected_lbl, bg="sidebar", fg="text")
        self.bulk_selected_lbl.pack(anchor="w", pady=(0, 3))

        def _bulk_row():
            row = tk.Frame(self.bulk_action_bar)
            self.track_theme(row, bg="sidebar")
            row.pack(fill="x", pady=1)
            return row

        def _bulk_pack(button):
            button.pack(side="left", expand=True, fill="x", padx=1, ipady=3)

        top_row = _bulk_row()
        bulk_select_all_btn = tk.Button(
            top_row, text="Select all", command=self._bulk_select_all,
            relief="flat", font=("Segoe UI", 8), cursor="hand2")
        self.track_theme(bulk_select_all_btn, bg="card", fg="text")
        _bulk_pack(bulk_select_all_btn)
        # Kept, because its label is not fixed: it becomes "Unselect all"
        # once everything on screen is selected.
        self._bulk_select_all_btn = bulk_select_all_btn
        bulk_trash_btn = tk.Button(
            top_row, text="🗑 Trash", command=self._bulk_move_to_trash,
            relief="flat", font=("Segoe UI", 8, "bold"), cursor="hand2")
        # Quiet, in the warning's words: the notes go to the Trash. The dark
        # red fill is kept for what cannot be undone.
        self.track_theme(bulk_trash_btn, bg="card", fg="danger_text")
        _bulk_pack(bulk_trash_btn)

        bottom_row = _bulk_row()
        bulk_category_btn = tk.Button(
            bottom_row, text="🗂 Category ▾",
            relief="flat", font=("Segoe UI", 8), cursor="hand2")
        self._toggles_its_popup(bulk_category_btn, self._bulk_change_category)
        # Quiet, as Export beside it: a menu, not the bar's main action,
        # and a fill here read as "already chosen".
        self.track_theme(bulk_category_btn, bg="card", fg="text")
        _bulk_pack(bulk_category_btn)
        self._bulk_category_btn = bulk_category_btn
        bulk_export_btn = tk.Button(
            bottom_row, text="Export ▾",
            relief="flat", font=("Segoe UI", 8), cursor="hand2")
        self._toggles_its_popup(bulk_export_btn, self._bulk_export)
        self.track_theme(bulk_export_btn, bg="card", fg="text")
        _bulk_pack(bulk_export_btn)
        self._bulk_export_btn = bulk_export_btn

        # Pin for everything ticked (the menu pinned one at a time), on a
        # THIRD row: two a row is the invariant above, and this bar's height
        # costs nothing while notes are ticked.
        pin_row = _bulk_row()
        self._bulk_pin_btn = tk.Button(
            pin_row, text="📌 Pin", command=self._bulk_toggle_pin,
            relief="flat", font=("Segoe UI", 8), cursor="hand2")
        self.track_theme(self._bulk_pin_btn, bg="card", fg="text")
        _bulk_pack(self._bulk_pin_btn)
        # Not packed yet — shown by _toggle_selection_mode() when active.

    def _build_note_list_and_buttons(self, parent):
        """The list's canvas, New Note / Import / Share / Settings under it,
        and the toggle that hides the sidebar."""
        # The action zone, packed BEFORE the list, keeps its space in a short
        # window; the list fills what is left and scrolls.
        bottom_zone = tk.Frame(self.sidebar)
        self.track_theme(bottom_zone, bg="sidebar")
        bottom_zone.pack(side="bottom", fill="x")
        self._sidebar_bottom = bottom_zone

        list_container = tk.Frame(self.sidebar)
        self.track_theme(list_container, bg="sidebar")
        list_container.pack(fill="both", expand=True, padx=10)

        # The note list is DRAWN on this canvas -- every card is rectangles
        # and text, not widgets (see _draw_note_card). takefocus: the list
        # is one stop for Tab, and walks with Down and Up from there.
        self.canvas = tk.Canvas(list_container, highlightthickness=0,
                                takefocus=1)
        self.track_theme(self.canvas, bg="sidebar")
        scrollbar = ttk.Scrollbar(list_container, orient="vertical",
                                  command=self._list_scrollbar_moved)
        # The same guard the editor page has carried since 0.32.x: when
        # the content fits (or the origin drifts above the first card),
        # the list pins back to the top instead of sitting displaced.
        self.canvas.bind("<Configure>",
                         lambda e: self._sync_list_scroll(), add="+")
        # Through _list_view_changed rather than straight to the scrollbar:
        # it is also what draws the rest of the list as the view nears it.
        self._list_scrollbar = scrollbar
        self.canvas.configure(yscrollcommand=self._list_view_changed)
        self._bind_list_input()

        # The scrollbar FIRST, or the expanding canvas squeezed it to nothing.
        scrollbar.pack(side="right", fill="y")
        self.canvas.pack(side="left", fill="both", expand=True)

        self._bind_mousewheel_recursive(self.sidebar, self.canvas)

        new_btn = tk.Button(
            bottom_zone, text="+ New Note", command=self.open_blank_tab,
            relief="flat", font=("Segoe UI", 11, "bold"), cursor="hand2"
        )
        self.track_theme(new_btn, bg="accent", fg="on_accent",
                         activebackground="accent_hover",
                         activeforeground="on_accent")
        # Each button's packing is kept (_fit_sidebar_panel packs a button
        # back exactly as it was after it stepped aside for an open panel).
        new_kw = dict(fill="x", padx=15, pady=(10, 4), ipady=8)
        new_btn.pack(**new_kw)

        import_btn = tk.Button(
            bottom_zone, text="📥 Import code", command=self.toggle_import_panel,
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self.track_theme(import_btn, bg="card", fg="text")
        import_kw = dict(fill="x", padx=15, pady=(0, 4), ipady=5)
        import_btn.pack(**import_kw)

        # Inline import panel — expands under the button instead of a pop-up.
        self.import_panel = tk.Frame(bottom_zone)
        self.track_theme(self.import_panel, bg="sidebar")
        # not packed until the button is pressed
        self._build_import_panel()

        share_multi_btn = tk.Button(
            bottom_zone, text="🔗 Share notes", command=self.toggle_share_panel,
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self.track_theme(share_multi_btn, bg="card", fg="text")
        share_kw = dict(fill="x", padx=15, pady=(0, 12), ipady=5)
        share_multi_btn.pack(**share_kw)

        # Inline share panel — pick notes, get a code, all without a pop-up.
        self.share_panel = tk.Frame(bottom_zone)
        self.track_theme(self.share_panel, bg="sidebar")

        settings_btn = tk.Button(
            bottom_zone, text="⚙ Settings", command=self.show_settings_page,
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self.track_theme(settings_btn, bg="card", fg="text")
        settings_kw = dict(fill="x", padx=15, pady=(0, 12), ipady=5)
        settings_btn.pack(**settings_kw)
        self._sidebar_zone_buttons = [(new_btn, new_kw), (import_btn, import_kw),
                                      (share_multi_btn, share_kw),
                                      (settings_btn, settings_kw)]
        # A window made shorter (or taller) with a panel open fits it again --
        # and so does the zone given less room by something above it, like
        # the selection bar appearing, which leaves the sidebar's size alone.
        self.sidebar.bind("<Configure>", self._fit_sidebar_panel, add="+")
        bottom_zone.bind("<Configure>", self._fit_sidebar_panel, add="+")

        # --- Sidebar collapse toggle (thin strip on the sidebar's edge) ---
        # Stays visible whether the sidebar is shown or hidden, so the user can
        # always bring the note list back.
        self._sidebar_hidden = False
        self.sidebar_toggle = tk.Frame(parent, width=self.px(16), cursor="hand2")
        self.track_theme(self.sidebar_toggle, bg="card")
        # A Tab stop, its ring resting in its own fill (its width holds it).
        self._ring_round(self.sidebar_toggle)
        self.track_theme(self.sidebar_toggle, highlightbackground="card")
        self.sidebar_toggle.pack(side="left", fill="y")
        self.sidebar_toggle.pack_propagate(False)
        self.sidebar_toggle_lbl = tk.Label(
            self.sidebar_toggle, text="‹", font=("Segoe UI", 12, "bold"),
            cursor="hand2")
        self.track_theme(self.sidebar_toggle_lbl, bg="card", fg="subtext")
        self.sidebar_toggle_lbl.pack(expand=True)
        for w in (self.sidebar_toggle, self.sidebar_toggle_lbl):
            w.bind("<Button-1>", lambda e: self.toggle_sidebar())
        self._pressable(self.sidebar_toggle, self.toggle_sidebar)

    def _build_editor_frame(self, parent):
        """The editor's side: the open-note tabs, and the scrolling frame
        (self.editor) every editor row is built in."""
        # --- Right side: open-note tab strip + editor panel ---
        right_side = tk.Frame(parent)
        self.track_theme(right_side, bg="bg")
        right_side.pack(side="left", fill="both", expand=True)

        self.editor_outer = tk.Frame(right_side)
        self.track_theme(self.editor_outer, bg="bg")
        self.editor_outer.pack(side="top", fill="both", expand=True)

        self.editor_canvas = tk.Canvas(self.editor_outer, highlightthickness=0)
        self.track_theme(self.editor_canvas, bg="bg")
        # The scrollbar, like the wheel, is a deliberate gesture: it
        # cancels any grid rebuild's still-pending view restore.
        editor_scrollbar = ttk.Scrollbar(
            self.editor_outer, orient="vertical",
            command=self._editor_scrollbar_moved)
        self.editor = tk.Frame(self.editor_canvas)
        self.track_theme(self.editor, bg="bg")

        editor_window = self.editor_canvas.create_window((0, 0), window=self.editor, anchor="nw")
        self._editor_window = editor_window

        def _sync_editor_scroll():
            """Keep the scrollregion correct and prevent the content from
            drifting away from the top when it's shorter than the visible area.
            Without this, scrolling up on a short note (common when the window
            is maximized) leaves a blank gap above the title."""
            if not self._still_alive():
                return
            self.editor_canvas.configure(scrollregion=self.editor_canvas.bbox("all"))
            bbox = self.editor_canvas.bbox(editor_window)
            if not bbox:
                return
            content_h = bbox[3] - bbox[1]
            canvas_h = self.editor_canvas.winfo_height()
            if content_h <= canvas_h:
                self.editor_canvas.yview_moveto(0)

        self._sync_editor_scroll = _sync_editor_scroll

        def _on_editor_configure(event):
            _sync_editor_scroll()

        def _on_editor_canvas_resize(event):
            # Make the inner window at least as tall as the canvas, so short
            # notes fill the height and there's never dead space above them.
            self.editor_canvas.itemconfig(editor_window, width=event.width)
            _sync_editor_scroll()

        self.editor.bind("<Configure>", _on_editor_configure)
        self.editor_canvas.bind("<Configure>", _on_editor_canvas_resize)
        self.editor_canvas.configure(yscrollcommand=editor_scrollbar.set)

        self.editor_canvas.pack(side="left", fill="both", expand=True)
        editor_scrollbar.pack(side="right", fill="y")

    def _build_editor_banners(self):
        """The lines over a note that only some notes show: from an empty
        calendar day, one day of a series, its days off the schedule, and
        the day strip of day mode."""
        # Back to the calendar day a note was started from; packed whole by
        # _update_calendar_return_button(), so it leaves no gap when off.
        self.calendar_return_btn = tk.Button(
            self.editor, text="← Back to Calendar",
            command=self._return_to_calendar, relief="flat", cursor="hand2",
            font=("Segoe UI", 9, "bold")
        )
        self.track_theme(self.calendar_return_btn, bg="bg", fg="accent_text")

        # Which DAY of a series is open, as the date field shows the start
        # (field request); packed whole by _update_occurrence_banner().
        self.occurrence_banner = tk.Label(
            self.editor, text="", font=("Segoe UI", 9, "bold"),
            anchor="center"
        )
        self.track_theme(self.occurrence_banner, bg="bg", fg="accent_text")
        # The one way to a day's edit on a date the series no longer has
        # (_update_occurrence_banner); long-lived, every colour tracked.
        self.offschedule_btn = tk.Button(
            self.editor, text="", relief="flat", cursor="hand2", bd=0,
            font=("Segoe UI", 9, "bold"), command=self._show_off_schedule_days)
        self.track_theme(self.offschedule_btn, bg="bg", fg="accent_text",
                         activebackground="bg", activeforeground="accent_text",
                         highlightbackground="bg", highlightcolor="focus_ring")
        # Both wrap to their width: the series line runs long, and centred
        # wider than the editor it lost the 🔁 and the "(✎)".
        for line in (self.occurrence_banner, self.offschedule_btn):
            line.bind("<Configure>", lambda e, w=line: w.configure(
                wraplength=max(120, e.width - 8)), add="+")

        # Day mode (_show_day_mode): the strip says which day, that changes
        # stay on it, and holds the way to the series -- a field test found
        # no way to edit one day. Long-lived, every colour tracked.
        self.day_strip = tk.Frame(self.editor)
        self.track_theme(self.day_strip, bg="card")
        day_strip_bar = tk.Frame(self.day_strip, width=4)
        self.track_theme(day_strip_bar, bg="accent")
        day_strip_bar.pack(side="left", fill="y")
        self.day_series_btn = tk.Button(
            self.day_strip, text="🔁 Edit the whole series",
            command=self._edit_whole_series, relief="flat", cursor="hand2",
            font=("Segoe UI", 9, "bold"))
        self.track_theme(self.day_series_btn, bg="accent", fg="on_accent",
                         activebackground="accent_hover",
                         activeforeground="on_accent",
                         highlightbackground="card", highlightcolor="focus_ring")
        self.day_series_btn.pack(side="right", padx=(8, 10), pady=8,
                                 ipadx=6, ipady=2)
        self.day_strip_lbl = tk.Label(
            self.day_strip, text="", font=("Segoe UI", 10, "bold"),
            anchor="w", justify="left")
        self.track_theme(self.day_strip_lbl, bg="card", fg="text")
        self.day_strip_lbl.pack(side="left", fill="x", expand=True,
                                padx=(10, 0), pady=8)
        self.day_strip_lbl.bind("<Configure>", lambda e: self.day_strip_lbl.configure(
            wraplength=max(120, e.width - 8)), add="+")

    def _build_title_and_meta_rows(self):
        """The title and category, then the date and colour, then Repeat."""
        top_row = tk.Frame(self.editor)
        self.track_theme(top_row, bg="bg")
        top_row.pack(fill="x", padx=30, pady=(25, 5))
        self.editor_top_row = top_row

        # width=1, and expand gives the rest: at twenty characters it took
        # them first, and the counter beside it got 8 px of its 46.
        self.title_entry = tk.Entry(
            top_row, insertbackground=self.colors["text"],
            relief="flat", font=("Segoe UI", 20, "bold"), width=1,
            validate="key",
            validatecommand=(self.register(self._title_within_limit), "%P", "%s")
        )
        self.track_theme(self.title_entry, bg="bg", fg="text", insertbackground="text")
        self.title_entry.pack(side="left", fill="x", expand=True)
        self.add_placeholder(self.title_entry, "Note title...")
        self._add_paste_menu(self.title_entry)
        # How much title is left, shown once it matters: a warning before the
        # field stops accepting, not a score.
        self.title_count_lbl = tk.Label(top_row, text="", font=("Segoe UI", 8))
        self.track_theme(self.title_count_lbl, bg="bg", fg="subtext")
        self.title_entry.bind("<KeyRelease>", self._schedule_autosave)
        self.title_entry.bind("<KeyRelease>", self._refresh_title_count, add="+")
        self._after_edits_without_a_key(
            self.title_entry,
            lambda: (self._schedule_autosave(), self._refresh_title_count()))
        # add="+" keeps the placeholder's clear, which runs first (replaced,
        # a paste read "Note title...X"); then the length cap measures.
        self.title_entry.bind("<<Paste>>", self._on_title_paste, add="+")
        # A middle-click is a paste too (Tk binds it on Windows as well).
        self.title_entry.bind("<<PasteSelection>>", self._on_title_paste_selection,
                              add="+")
        self._guard_entry_astral(self.title_entry)

        self.category_var = tk.StringVar(value="General")
        # Keep the button's dot/label in sync whenever the category changes,
        # however it's set (load, template, restore, etc.).
        self.category_var.trace_add(
            "write", lambda *a: self._refresh_category_button_safe())
        # A themed dropdown (ttk.Combobox's list stays OS-white): the category
        # with its bullet, in plain Labels, consistent across DPI settings.
        self.category_menu = tk.Frame(top_row, bg=self.colors["sidebar"],
                                      highlightthickness=1,
                                      highlightbackground=self.colors["card"])
        self.category_menu.pack(side="right", padx=(10, 0), ipady=4)
        self._cat_dot = tk.Label(self.category_menu, text="●",
                                 bg=self.colors["sidebar"],
                                 fg=CATEGORY_COLORS.get("General", self.colors["accent"]),
                                 font=("Segoe UI", 11))
        self._cat_dot.pack(side="left", padx=(10, 6))
        self._cat_btn_lbl = tk.Label(self.category_menu, textvariable=self.category_var,
                                     bg=self.colors["sidebar"], fg=self.colors["text"],
                                     font=("Segoe UI", 10), anchor="w")
        self._cat_btn_lbl.pack(side="left")
        self._cat_caret = tk.Label(self.category_menu, text=" ▾", bg=self.colors["sidebar"],
                                   fg=self.colors["subtext"], font=("Segoe UI", 9))
        self._cat_caret.pack(side="left", padx=(4, 10))
        self.track_theme(self.category_menu, bg="sidebar",
                         highlightbackground="card", highlightcolor="focus_ring")
        self.track_theme(self._cat_btn_lbl, bg="sidebar", fg="text")
        self.track_theme(self._cat_caret, bg="sidebar", fg="subtext")
        for w in (self.category_menu, self._cat_dot, self._cat_btn_lbl, self._cat_caret):
            w.configure(cursor="hand2")
            w.bind("<Button-1>", lambda e: self._open_category_dropdown())
        self._opens_list_from_keyboard(self.category_menu,
                                       self._open_category_dropdown)
        self._refresh_category_button()
        # Beside the category in day mode (_show_day_mode): the category a day
        # is given is that day's, and the series' card keeps its own.
        self.day_cat_lbl = tk.Label(top_row, text="This day:",
                                    font=("Segoe UI", 9, "bold"))
        self.track_theme(self.day_cat_lbl, bg="bg", fg="accent_text")

        # --- Metadata row 1: Date + Note color, side by side ---
        # These are short controls, so pairing them on one line keeps the
        # note's properties compact instead of four sparse stacked rows.
        meta_row = tk.Frame(self.editor)
        self.track_theme(meta_row, bg="bg")
        meta_row.pack(fill="x", padx=30, pady=(0, 8))

        date_label = tk.Label(meta_row, text="📅 Date:", font=("Segoe UI", 9, "bold"))
        self.track_theme(date_label, bg="bg", fg="subtext")
        date_label.pack(side="left")

        self.date_entry = tk.Entry(
            meta_row, insertbackground=self.colors["text"],
            relief="flat", font=("Segoe UI", 10), width=11
        )
        self.track_theme(self.date_entry, bg="card", fg="text", insertbackground="text")
        self.date_entry.pack(side="left", padx=(6, 4), ipady=3)
        # The empty field shows its form: the order a typed date is read in.
        self.add_placeholder(self.date_entry, DATE_FORM)
        # Finishing settles the date into its form (_settle_date_fields), and
        # only then: mid-typing, "17.10.20" would be stored as 2020. Wired
        # once, for this field and the repeat's end alike.
        self._watch_date_field(self.date_entry)
        # Typing a date directly (as opposed to using the picker popup, which
        # already autosaves via _pick()) previously had no autosave binding
        # at all, so a typed date change could be silently lost.
        self.date_entry.bind("<KeyRelease>", self._schedule_autosave)
        # A PASTED date has no key release and scheduled no save. add="+"
        # keeps the placeholder's clear, first, so it does not land on the
        # field's form (DATE_FORM).
        self.date_entry.bind("<<Paste>>", self._schedule_autosave, add="+")
        # The repeat's summary reads this date, so every route changing it
        # redraws it (it said "needs a start date" after one was typed); a
        # paste lands later, so its redraw waits for idle.
        self.date_entry.bind("<KeyRelease>",
                             lambda _e: self.update_recurrence_summary(),
                             add="+")
        self.date_entry.bind(
            "<<Paste>>",
            lambda _e: self.after_idle(self.update_recurrence_summary),
            add="+")
        # ...and the menu's Cut, or a middle-click, the same.
        self._after_edits_without_a_key(
            self.date_entry,
            lambda: (self._schedule_autosave(), self.update_recurrence_summary()))
        # Pasting a date copied out of an email is an ordinary thing to want,
        # and this was the field that most invited it and refused.
        self._add_paste_menu(self.date_entry)

        pick_date_btn = tk.Button(
            meta_row, text="📅",
            relief="flat", font=("Segoe UI", 9), cursor="hand2"
        )
        self._toggles_its_popup(pick_date_btn, self.open_date_picker)
        self.track_theme(pick_date_btn, bg="sidebar", fg="text")
        pick_date_btn.pack(side="left", padx=(0, 2), ipadx=2)
        self.pick_date_btn = pick_date_btn

        clear_date_btn = tk.Button(
            meta_row, text="✕", command=self.clear_note_date,
            relief="flat", font=("Segoe UI", 8), cursor="hand2"
        )
        self.track_theme(clear_date_btn, bg="sidebar", fg="subtext")
        clear_date_btn.pack(side="left", padx=(0, 20))
        # Day mode puts these back exactly as packed here (_show_day_mode).
        self._date_field_packing = [
            (self.date_entry, dict(side="left", padx=(6, 4), ipady=3)),
            (pick_date_btn, dict(side="left", padx=(0, 2), ipadx=2)),
            (clear_date_btn, dict(side="left", padx=(0, 20)))]
        # In day mode, in their place: the day's own date, as words. The
        # field holds the series' start, which is no day's to change.
        self.day_date_lbl = tk.Label(meta_row, text="", font=("Segoe UI", 10))
        self.track_theme(self.day_date_lbl, bg="bg", fg="text")
        self._date_row_label = date_label
        # ...beside it, moving the one day (_move_this_day), tracked; its frame
        # with Reset goes under the date when the row is short.
        self.day_btns = tk.Frame(meta_row)
        self.track_theme(self.day_btns, bg="bg")
        self._day_btns_wrapped = None
        meta_row.bind("<Configure>", self._place_day_buttons, add="+")
        self.day_move_btn = tk.Button(self.day_btns, text="📅 Move this day…",
                                      relief="flat", cursor="hand2",
                                      font=("Segoe UI", 9))
        self._toggles_its_popup(self.day_move_btn, self._open_move_day_picker)
        self.track_theme(self.day_move_btn, bg="sidebar", fg="text",
                         activebackground="card", activeforeground="text",
                         highlightbackground="bg", highlightcolor="focus_ring")
        # ...and, with a move or text to reset, the menu's Reset from the day
        # itself: in the menu alone it was not found (field request).
        self.day_reset_btn = tk.Button(self.day_btns, text="↺ Reset this day…",
                                       relief="flat", cursor="hand2",
                                       font=("Segoe UI", 9),
                                       command=self._reset_this_day)
        self.track_theme(self.day_reset_btn, bg="sidebar", fg="text",
                         activebackground="card", activeforeground="text",
                         highlightbackground="bg", highlightcolor="focus_ring")

        # Note color, on the same row, pushed a bit right of the date controls.
        color_label = tk.Label(meta_row, text="🎨 Color:", font=("Segoe UI", 9, "bold"))
        self.track_theme(color_label, bg="bg", fg="subtext")
        color_label.pack(side="left")
        self._color_label = color_label

        self.current_note_color = ""  # "" means "use the category's default color"

        self.color_swatch_btn = tk.Button(
            meta_row, text="", width=3, relief="flat", cursor="hand2")
        self._toggles_its_popup(self.color_swatch_btn, self.open_color_picker)
        self.color_swatch_btn.pack(side="left", padx=(6, 6))

        self._update_color_swatch()

        # --- Metadata row 2: Repeat (own line — it expands when active) ---
        self.build_recurrence_section(self.editor)

    def _build_format_bar(self):
        """The text's heading with its word count, and the format bar."""
        body_header = tk.Frame(self.editor)
        self.body_header = body_header
        self.track_theme(body_header, bg="bg")
        body_header.pack(fill="x", padx=30, pady=(5, 2))

        body_label = tk.Label(body_header, text="Note", font=("Segoe UI", 9, "bold"), anchor="w")
        self.track_theme(body_label, bg="bg", fg="subtext")
        body_label.pack(side="left")

        # Two lines tall even when empty: the row took its height from the
        # readout, so the toolbar and the note jumped 11px whenever the
        # editor went from empty to written (a first letter, a delete).
        self.word_count_lbl = tk.Label(body_header, text="", font=("Segoe UI", 8),
                                       anchor="e", justify="right", height=2)
        self.track_theme(self.word_count_lbl, bg="bg", fg="subtext")
        self.word_count_lbl.pack(side="right")

        # --- Formatting toolbar: the style toggles (_toggle_body_style), each
        # labelled in its own style. ---
        format_bar = tk.Frame(self.editor)
        self.track_theme(format_bar, bg="bg")
        format_bar.pack(fill="x", padx=30, pady=(0, 4))

        # Controls dealt into rows by width (_reflow_format_bar): one row
        # usually, more so no window, font or scale puts one out of reach.
        self._fmt_bar = format_bar
        self._fmt_bar_items = []
        self._fmt_bar_rows = []
        # Three: a much wider substitute font could want one; unused rows
        # are never packed.
        for _ in range(3):
            row = tk.Frame(format_bar)
            self.track_theme(row, bg="bg")
            self._fmt_bar_rows.append(row)
        self._fmt_bar_rows[0].pack(side="top", fill="x")
        format_bar.bind("<Configure>", self._on_format_bar_resize)

        self._fmt_buttons = {}
        # List buttons apart from _fmt_buttons, which asks the *selection*
        # for a character style: a list belongs to a line, never "pressed".
        self._list_buttons = {}
        self._align_buttons = {}
        self._pending_styles = set()  # styles queued up for the next typed char
        self._pending_text_color = None  # hex, or None
        self._pending_font_size = None    # a size from FONT_SIZES, or None
        self._pending_font_family = None  # a family from FONT_FAMILIES
        self._pending_highlight_color = None  # hex, or None
        self._pending_style_last_length = 0  # baseline for detecting growth
        # No group captions. They cost 182px of a bar that did not fit, and
        # every button now says what it is on hover, which is what they were
        # for. The dividers still separate the groups.
        for style, label, label_font, tip, tip_detail in (
            ("bold", "B", ("Segoe UI", 10, "bold"), "Bold",
             "Ctrl+B \u2014 the selected text, or whatever you type next"),
            ("italic", "I", ("Segoe UI", 10, "italic"), "Italic", "Ctrl+I"),
            ("underline", "U", ("Segoe UI", 10, "underline"), "Underline",
             "Ctrl+U"),
            ("strike", "S", ("Segoe UI", 10, "overstrike"), "Strikethrough",
             "Ctrl+D"),
        ):
            btn = tk.Button(
                format_bar, text=label, font=label_font, width=2,
                relief="flat", cursor="hand2",
                command=lambda s=style: self._toggle_body_style(s)
            )
            self.track_theme(btn, bg="sidebar", fg="text")
            self._add_fmt_item(btn, padx=(0, 2), ipady=2)
            self._attach_tooltip(btn, tip, tip_detail)
            self._fmt_buttons[style] = btn

        # Font: family and size as dropdowns (no toggle, no three letters),
        # before Colors as the coarsest thing here.
        font_divider = tk.Frame(format_bar, width=1)
        self.track_theme(font_divider, bg="card")
        self._add_fmt_item(font_divider, padx=(5, 5), fill="y", pady=3)
        # "Default" is the app's own font, i.e. no span at all — which is
        # what makes the note follow the Settings default rather than being
        # pinned to whatever that happened to be on the day it was written.
        self.font_family_var = tk.StringVar(value=self.DEFAULT_FONT_LABEL)
        family_dd = self._build_themed_dropdown(
            format_bar, self.font_family_var,
            [self.DEFAULT_FONT_LABEL] + list(FONT_FAMILIES),
            lambda v: self._apply_body_font(
                "font_family", None if v == self.DEFAULT_FONT_LABEL else v),
            width_chars=11)
        self._add_fmt_item(family_dd, padx=(0, 4))
        self._attach_tooltip(family_dd, "Font",
                             "The selected text, or whatever you type next")

        self.font_size_var = tk.StringVar(value=self.DEFAULT_FONT_LABEL)
        size_dd = self._build_themed_dropdown(
            format_bar, self.font_size_var,
            [self.DEFAULT_FONT_LABEL] + [str(s) for s in FONT_SIZES],
            lambda v: self._apply_body_font(
                "font_size", None if v == self.DEFAULT_FONT_LABEL else int(v)),
            width_chars=7)
        self._add_fmt_item(size_dd, padx=(0, 4))
        self._attach_tooltip(size_dd, "Font size",
                             "Default follows the size set in Settings")

        # A divider and label make the colour pickers their own group: they
        # open a picker, and should not read as two more toggles.
        divider = tk.Frame(format_bar, width=1)
        self.track_theme(divider, bg="card")
        self._add_fmt_item(divider, padx=(5, 5), fill="y", pady=3)
        # Text color / Highlight open a swatch picker, and each button is a
        # swatch of the colour set, its letter kept legible (_contrasting_fg);
        # with none, the theme's button.
        self.text_color_btn = tk.Button(
            format_bar, text="A", font=("Segoe UI", 10, "bold"), width=2,
            relief="flat", cursor="hand2")
        # A second click closes the palette instead of blinking it.
        self._toggles_its_popup(
            self.text_color_btn,
            lambda: self._open_color_swatch_popup("text_color"))
        self._add_fmt_item(self.text_color_btn, padx=(0, 2), ipady=2)
        self._attach_tooltip(self.text_color_btn, "Text colour",
                             "Colours the letters themselves")
        self.highlight_btn = tk.Button(
            format_bar, text="H", font=("Segoe UI", 10, "bold"), width=2,
            relief="flat", cursor="hand2")
        self._toggles_its_popup(
            self.highlight_btn,
            lambda: self._open_color_swatch_popup("highlight"))
        self._add_fmt_item(self.highlight_btn, padx=(0, 2), ipady=2)
        self._attach_tooltip(self.highlight_btn, "Highlight",
                             "Colours the background behind the letters")

        # Paragraph -- a whole line -- apart from Style, the characters; not
        # "Lists", beside the Checklist below.
        para_divider = tk.Frame(format_bar, width=1)
        self.track_theme(para_divider, bg="card")
        self._add_fmt_item(para_divider, padx=(5, 5), fill="y", pady=3)
        for kind, label, tip, tip_detail in (
            ("bullet", "\u2022", "Bullet list",
             "Whole lines \u2014 click again to turn the list off"),
            ("number", "1.", "Numbered list",
             "Numbers itself; a nested list restarts at 1"),
        ):
            btn = tk.Button(
                format_bar, text=label, font=("Segoe UI", 10, "bold"), width=2,
                relief="flat", cursor="hand2",
                command=lambda k=kind: self._toggle_list(k)
            )
            self.track_theme(btn, bg="sidebar", fg="text")
            self._add_fmt_item(btn, padx=(0, 2), ipady=2)
            self._attach_tooltip(btn, tip, tip_detail)
            self._list_buttons[kind] = btn

        # Alignment belongs to the line too. Its icons are drawn, as the
        # Settings glyphs are: no icon font or image, and they recolour.
        for align, tip in (("left", "Align left"), ("center", "Centre"),
                           ("right", "Align right")):
            btn = self._make_align_button(format_bar, align)
            self.track_theme(btn, bg="sidebar", highlightbackground="sidebar")
            self._add_fmt_item(btn, padx=(0, 4))
            self._attach_tooltip(
                btn, tip,
                "Applies to whole paragraphs, not to part of one")
            self._align_buttons[align] = btn

        # Indent and outdent. Arrows rather than drawn bars: these do
        # something rather than describe a state, so they never show a
        # pressed look and do not belong in the registries above.
        for delta, glyph, tip, tip_detail in (
            (-1, "⇤", "Outdent", "Shift+Tab inside a list"),
            (+1, "⇥", "Indent", "Tab inside a list — works on any paragraph"),
        ):
            btn = tk.Button(
                format_bar, text=glyph, font=("Segoe UI", 11), width=2,
                relief="flat", cursor="hand2",
                command=lambda d=delta: self._change_paragraph_indent(d)
            )
            self.track_theme(btn, bg="sidebar", fg="text")
            self._add_fmt_item(btn, padx=(0, 2), ipady=2)
            self._attach_tooltip(btn, tip, tip_detail)

        table_divider = tk.Frame(format_bar, width=1)
        self.track_theme(table_divider, bg="card")
        self._add_fmt_item(table_divider, padx=(5, 5), fill="y", pady=3)

        self.table_btn = tk.Button(
            format_bar, text="\u25a6", font=("Segoe UI", 11), width=2,
            relief="flat", cursor="hand2")
        self._toggles_its_popup(self.table_btn, self._open_table_size_popup)
        self.track_theme(self.table_btn, bg="sidebar", fg="text")
        self._add_fmt_item(self.table_btn, padx=(0, 2), ipady=2)
        self._attach_tooltip(
            self.table_btn, "Table",
            "Rows live in the note's own text, so a table survives being "
            "exported, shared as a code, or pasted anywhere else")

        self.emoji_btn = tk.Button(
            format_bar, text="\U0001f600", font=("Segoe UI Emoji", 10),
            width=2, relief="flat", cursor="hand2")
        self._toggles_its_popup(self.emoji_btn, self._insert_emoji_from_toolbar)
        self.track_theme(self.emoji_btn, bg="sidebar", fg="text")
        self._add_fmt_item(self.emoji_btn, padx=(0, 2), ipady=2)
        self._attach_tooltip(
            self.emoji_btn, "Emoji",
            "Lands in the open table cell if there is one, otherwise at "
            "the cursor in the note")

        # The quick light/dark flip, right where the writing happens --
        # the full theme picker stays in Settings; this only swaps
        # between the last light and last dark choice.
        self.editor_theme_btn = tk.Button(
            self.emoji_btn.master,
            text="☀" if self.theme_name in DARK_THEMES else "🌙",
            relief="flat", cursor="hand2", bd=0,
            font=("Segoe UI", 10),
            command=self.toggle_theme)
        self.track_theme(self.editor_theme_btn, bg="sidebar", fg="text")
        self._add_fmt_item(self.editor_theme_btn, padx=(6, 2), ipady=2)
        self._attach_tooltip(
            self.editor_theme_btn, "Light / Dark",
            "Switches between your last light and last dark theme; the "
            "full theme picker stays in Settings")

    def _build_body_text(self):
        """The note's text box and every binding it carries."""
        text_frame = tk.Frame(self.editor)
        self.track_theme(text_frame, bg="card")
        text_frame.pack(fill="both", expand=True, padx=30, pady=(0, 10))

        body_sb = ttk.Scrollbar(text_frame, orient="vertical")
        self.body_text = tk.Text(
            text_frame, insertbackground=self.colors["text"],
            relief="flat", wrap="word", padx=15, pady=15, height=12,
            font=(self.editor_font_family, self.editor_font_size),
            yscrollcommand=body_sb.set, undo=True, autoseparators=True, maxundo=-1
        )
        body_sb.config(command=self._body_scrollbar_moved)
        self.track_theme(self.body_text, bg="card", fg="text", insertbackground="text")
        body_sb.pack(side="right", fill="y")
        self.body_text.pack(side="left", fill="both", expand=True)
        self._setup_body_formatting_tags(self.body_text)
        self._setup_list_tags(self.body_text)
        self._configure_table_tag(self.body_text)
        self.body_text.bind("<Return>", self._on_body_return)
        self.body_text.bind("<BackSpace>", self._on_body_backspace)
        self.body_text.bind("<Delete>", self._on_body_delete_key)
        # First of all: Tk's deletes left no tag on the undo stack, so this
        # notes the formatting (_note_styled_delete), and settles the key
        # before (_note_key_down); <KeyPress> speaks for the typing keys.
        self.bind_class(self._STYLED_DELETE_TAG, "<KeyPress>",
                        self._note_key_down)
        # A delete that reaches a list is the app's own, in one undo unit
        # that notes the formatting itself (see _list_aware_delete).
        self.bind_class(self._STYLED_DELETE_TAG, "<KeyPress>",
                        self._list_aware_delete, add="+")
        self.bind_class(self._STYLED_DELETE_TAG, "<KeyPress>",
                        self._note_styled_delete, add="+")
        # Each virtual binding says what it is: read as keys, Ctrl+X cut bold
        # that Ctrl+Z gave back plain, and a paste wore the word's style.
        for virtual, name in (("<<Cut>>", "cut"), ("<<Clear>>", "clear"),
                              ("<<Paste>>", None)):
            self.bind_class(self._STYLED_DELETE_TAG, virtual,
                            lambda e, name=name: self._on_styled_virtual(e, name))
        self.body_text.bindtags(
            (self._STYLED_DELETE_TAG,) + tuple(self.body_text.bindtags()))
        self._after_edits_without_a_key(self.body_text, self._schedule_autosave)
        self.body_text.bind("<<Paste>>", self._on_body_paste, add="+")
        self.body_text.bind("<<Paste>>", self._renumber_after_paste, add="+")
        self.body_text.bind("<<Copy>>", self._copy_formatted, add="+")
        # Ctrl+Shift+V is the usual way to ask for the text without its
        # styling; Ctrl+V keeps it, the way every other editor does.
        self.body_text.bind("<Control-Shift-V>", self._paste_plain)
        self.body_text.bind("<Control-Shift-v>", self._paste_plain)
        # The middle button pastes the selection, past every route above.
        self.body_text.bind(
            "<<PasteSelection>>",
            lambda e: self._paste_selection_capped(e, in_body=True), add="+")
        self.body_text.bind("<Tab>", lambda e: self._on_body_tab(e, +1))
        self.body_text.bind("<Shift-Tab>", lambda e: self._on_body_tab(e, -1))
        # X11's own Shift+Tab keysym, an error to bind on Windows (where it is
        # not needed): allowed to fail.
        try:
            self.body_text.bind("<ISO_Left_Tab>",
                                lambda e: self._on_body_tab(e, -1))
        except tk.TclError:
            pass
        self.body_text.bind("<KeyRelease>", self._schedule_autosave)
        self.body_text.bind("<KeyRelease>", self._renumber_if_lines_fell, add="+")
        self.body_text.bind("<KeyRelease>", self._apply_pending_style_to_typed_char, add="+")
        self.body_text.bind("<KeyRelease>", self._refresh_format_buttons, add="+")
        self.body_text.bind("<KeyRelease>", self._align_table_on_leaving, add="+")
        # A click in the body means the user has LEFT the table: a cell
        # selection lingering from an earlier drag would silently catch
        # the next toolbar colour meant for the body text.
        self.body_text.bind("<Button-1>",
                            lambda _e: self._grid_clear_selection(), add="+")
        self.body_text.bind("<ButtonRelease-1>", self._resync_pending_style_anchor, add="+")
        self.body_text.bind("<ButtonRelease-1>", self._refresh_format_buttons, add="+")
        self.body_text.bind("<ButtonRelease-1>", self._align_table_on_leaving, add="+")
        # The text of a rendered table is elided, but Tk still lets the
        # caret wander into it -- and typing there would edit characters
        # nobody can see.
        self.body_text.bind("<KeyPress>", self._caret_out_of_hidden, add="+")
        self.body_text.bind("<Configure>", self._on_body_resize_grids, add="+")
        self.body_text.bind("<KeyRelease>", self._caret_out_of_hidden, add="+")
        self.body_text.bind("<KeyRelease>", self._reassert_line_alignment,
                            add="+")
        self.body_text.bind("<KeyRelease>", self._extend_word_styles_on_typing,
                            add="+")
        # A typing key sets two marks at the caret; what lands between is
        # settled at its release or the next press (_spread_typed_run).
        self.body_text.bind("<KeyPress>", self._note_typing_key, add="+")
        # At KeyRelease the line re-centred a frame LATE; idle from KeyPress
        # runs after the insert and before the repaint.
        self.body_text.bind(
            "<KeyPress>",
            lambda e: self.after_idle(self._reassert_line_alignment),
            add="+")
        self.body_text.bind("<ButtonRelease-1>", self._caret_out_of_hidden, add="+")
        self.body_text.bind("<ButtonRelease-1>", self._caret_past_marker, add="+")
        # Double-click words break at punctuation, an empty line selects
        # nothing, and triple-click stops before the newline (comments too).
        self._bind_text_selection_fixes(self.body_text)
        # A paste never takes a pending style: resynced as it lands, the
        # growth check in _apply_pending_style_to_typed_char sees none.
        self.body_text.bind("<<Paste>>", self._resync_pending_style_anchor, add="+")
        # The toggles' shortcuts, on the body only; "break" stops Tk's own
        # Ctrl+letter behaviour on builds that have one.
        for key, style in self.FORMAT_KEYS:
            self.body_text.bind(key, lambda e, s=style: (self._toggle_body_style(s), "break")[1])
        # Let the mousewheel scroll the text box's own content when it overflows,
        # instead of bubbling up to the editor's outer scroll.
        self._bind_text_wheel(self.body_text)
        # Plain labels: styled glyph prefixes had their own widths, and the
        # words lined up with nothing.
        self._add_paste_menu(self.body_text, extra_items=[
            ("Bold", lambda: self._toggle_body_style("bold"), "Ctrl+B"),
            ("Italic", lambda: self._toggle_body_style("italic"), "Ctrl+I"),
            ("Underline", lambda: self._toggle_body_style("underline"), "Ctrl+U"),
            ("Strikethrough", lambda: self._toggle_body_style("strike"), "Ctrl+D"),
            ("Text color…", lambda: self._open_color_swatch_popup("text_color")),
            ("Highlight…", lambda: self._open_color_swatch_popup("highlight")),
        ])
        self._spell_setup(self.body_text)
        self.update_word_count()

        # The writing area's height is remembered, as the comments' is: a
        # long-note writer wants it every launch. The editor scrolls, so the
        # buttons below stay reachable.
        self.body_resize_btn = self._add_text_resize_toggle(
            self.editor, self.body_text, compact=12, expanded=26,
            pack_kwargs={"padx": 30, "pady": (0, 8)},
            remember_key="editor_body_expanded")

    def _build_editor_tools(self):
        """The checklist and the calculator side by side, the comments and
        the attached files."""
        # --- Checklist and Calculator side by side, each its own section, in
        # a uniform grid: pack shares only the leftover space, and the wider
        # keypad left the columns unequal. ---
        tools_row = tk.Frame(self.editor)
        self.track_theme(tools_row, bg="bg")
        tools_row.pack(fill="x", padx=30, pady=(4, 2))
        tools_row.grid_columnconfigure(0, weight=1, uniform="tools_col")
        tools_row.grid_columnconfigure(1, weight=1, uniform="tools_col")

        checklist_col = tk.Frame(tools_row)
        self.track_theme(checklist_col, bg="bg")
        checklist_col.grid(row=0, column=0, sticky="nsew", padx=(0, 4))

        calculator_col = tk.Frame(tools_row)
        self.track_theme(calculator_col, bg="bg")
        calculator_col.grid(row=0, column=1, sticky="nsew", padx=(4, 0))

        self.checklist_btn = tk.Button(
            checklist_col, text="☑ Checklist", command=self.toggle_checklist_section,
            relief="flat", font=("Segoe UI", 9, "bold"), cursor="hand2", anchor="w"
        )
        self.track_theme(self.checklist_btn, bg="sidebar", fg="text")
        self.checklist_btn.pack(fill="x", ipady=3)

        self.checklist_section = tk.Frame(checklist_col)
        self.track_theme(self.checklist_section, bg="card")
        # Not packed yet — toggled open by the button.
        self._checklist_open = False
        self._build_checklist_section()

        self.calculator_btn = tk.Button(
            calculator_col, text="🧮 Calculator", command=self.toggle_calculator_section,
            relief="flat", font=("Segoe UI", 9, "bold"), cursor="hand2", anchor="w"
        )
        self.track_theme(self.calculator_btn, bg="sidebar", fg="text")
        self.calculator_btn.pack(fill="x", ipady=3)

        self.calculator_section = tk.Frame(calculator_col)
        self.track_theme(self.calculator_section, bg="card")
        # Not packed yet — toggled open by the button.
        self._calculator_open = False
        self._build_calculator_section()

        comments_label = tk.Label(
            self.editor, text="💬 Comments / additional notes",
            font=("Segoe UI", 9, "bold"), anchor="w"
        )
        self.track_theme(comments_label, bg="bg", fg="subtext")
        comments_label.pack(fill="x", padx=30, pady=(5, 2))

        comments_frame = tk.Frame(self.editor)
        self.track_theme(comments_frame, bg="card")
        comments_frame.pack(fill="x", padx=30, pady=(0, 10))

        comments_sb = ttk.Scrollbar(comments_frame, orient="vertical")
        self.comments_text = tk.Text(
            comments_frame, insertbackground=self.colors["text"],
            relief="flat", font=("Segoe UI", 11), wrap="word", padx=15, pady=10, height=4,
            yscrollcommand=comments_sb.set, undo=True, autoseparators=True, maxundo=-1
        )
        comments_sb.config(command=self.comments_text.yview)
        self.track_theme(self.comments_text, bg="card", fg="text", insertbackground="text")
        comments_sb.pack(side="right", fill="y")
        self.comments_text.pack(side="left", fill="both", expand=True)
        self._bind_text_wheel(self.comments_text)
        self._add_paste_menu(self.comments_text)
        self._swallow_format_keys(self.comments_text)
        self._spell_setup(self.comments_text)
        self._bind_text_selection_fixes(self.comments_text)
        # Comments never render tables (only the body does), so a pasted
        # table used to land as raw pipe soup. Strip table rows out of a
        # paste here and say so, rather than leaving broken-looking pipes.
        self.comments_text.bind("<<Paste>>", self._on_comments_paste, add="+")
        self.comments_text.bind("<<PasteSelection>>",
                                self._paste_selection_capped, add="+")
        self.comments_text.bind("<KeyRelease>", self._schedule_autosave)
        self._after_edits_without_a_key(self.comments_text, self._schedule_autosave)
        # The comments box's toggle (4 rows <-> 12), remembered as the body's
        # is: a box someone expanded is a size they chose.
        self._add_text_resize_toggle(self.editor, self.comments_text,
                                     compact=4, expanded=12,
                                     pack_kwargs={"padx": 30, "pady": (0, 8)},
                                     remember_key="editor_comments_expanded")

        # Undo/redo on both boxes; the body's (_body_undo_redo) also redraws
        # its tables, the comments' walks the plain stack.
        self.body_text.bind("<Control-z>",
                            lambda e: self._body_undo_redo("undo", e))
        self.body_text.bind("<Control-y>",
                            lambda e: self._body_undo_redo("redo"))
        self.body_text.bind("<Control-Shift-Z>",
                            lambda e: self._body_undo_redo("redo"))
        # Caps Lock turns the letter over, and Tk's own <<Undo>> ran behind
        # the journal's back: the body answers the virtual events too, the
        # letters where they lack one. One binding a tag runs, so once.
        self.body_text.bind("<Control-Shift-z>",
                            lambda e: self._body_undo_redo("redo"))
        self.body_text.bind("<<Undo>>",
                            lambda e: self._body_undo_redo("undo", e))
        self.body_text.bind("<<Redo>>",
                            lambda e: self._body_undo_redo("redo"))
        _tw = self.comments_text
        # With nothing of its own to take back, the toast's Undo (as the body).
        _tw.bind("<Control-z>", lambda e, w=_tw: (w.edit_undo(), "break")[1]
                 if self._can_edit_undo(w) else (self._toast_undo_key(e) or "break"))
        _tw.bind("<Control-y>", lambda e, w=_tw: (w.edit_redo(), "break")[1]
                 if self._can_edit_redo(w) else "break")
        _tw.bind("<Control-Shift-Z>", lambda e, w=_tw: (w.edit_redo(), "break")[1]
                 if self._can_edit_redo(w) else "break")
        # Caps Lock turns the letter over here too: Ctrl+Shift+Z arrives as
        # a lower-case z and undid instead of redoing, as in the body.
        _tw.bind("<Control-Shift-z>", lambda e, w=_tw: (w.edit_redo(), "break")[1]
                 if self._can_edit_redo(w) else "break")

        # Attachments section
        attach_header = tk.Frame(self.editor)
        self.track_theme(attach_header, bg="bg")
        attach_header.pack(fill="x", padx=30, pady=(5, 2))

        attach_label = tk.Label(attach_header, text="📎 Attachments", font=("Segoe UI", 9, "bold"), anchor="w")
        self.track_theme(attach_label, bg="bg", fg="subtext")
        attach_label.pack(side="left")
        # Its words change in day mode (_show_day_mode).
        self.attach_label = attach_label

        add_attach_btn = tk.Button(
            attach_header, text="+ Add file", command=self.add_attachment,
            relief="flat", font=("Segoe UI", 8, "bold"), cursor="hand2"
        )
        self.track_theme(add_attach_btn, bg="accent", fg="on_accent")
        add_attach_btn.pack(side="right")

        self.current_attachments = []  # list of {"filename": original name, "stored_as": name on disk}

        self.attachments_frame = tk.Frame(self.editor)
        self.track_theme(self.attachments_frame, bg="bg")
        self.attachments_frame.pack(fill="x", padx=30, pady=(0, 10))
        self.refresh_attachments_list()

    def _build_editor_actions(self):
        """The note's buttons, the status line, and the share code's area."""
        action_row = tk.Frame(self.editor)
        self.track_theme(action_row, bg="bg")
        action_row.pack(fill="x", padx=30, pady=(0, 8))

        # Each names its pressed colours too: left out, Tk pressed them in
        # the system's grey with black words, whatever the theme.
        save_btn = tk.Button(
            action_row, text="💾 Save", command=self.save_current_note,
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self.track_theme(save_btn, bg="success", fg="on_success",
                         activebackground="success_pressed",
                         activeforeground="on_success")

        share_btn = tk.Button(
            action_row, text="📋 Generate code", command=self.share_current_note_as_code,
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self.track_theme(share_btn, bg="sidebar", fg="text",
                         activebackground="card", activeforeground="text")

        # Quiet, the warning colour in its words: it goes to the Trash, and
        # filled red was the loudest thing on a light theme.
        delete_btn = tk.Button(
            action_row, text="🗑 Delete", command=self.delete_current_note,
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self.track_theme(delete_btn, bg="sidebar", fg="danger_text",
                         activebackground="card", activeforeground="danger_text")

        duplicate_btn = tk.Button(
            action_row, text="📄 Duplicate", command=self.duplicate_current_note,
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self.track_theme(duplicate_btn, bg="sidebar", fg="text",
                         activebackground="card", activeforeground="text")

        template_btn = tk.Button(
            action_row, text="🧩 Save as template",
            command=self.save_current_as_template,
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self.track_theme(template_btn, bg="sidebar", fg="text",
                         activebackground="card", activeforeground="text")

        use_template_btn = tk.Button(
            action_row, text="📎 Use template",
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self._toggles_its_popup(use_template_btn, self.show_template_picker)
        self.track_theme(use_template_btn, bg="sidebar", fg="text",
                         activebackground="card", activeforeground="text")
        self.use_template_btn = use_template_btn

        # Two rows of three, equal columns, built in Tab's order. With no room
        # for three ("Save as template" lost its ends), three rows of two or
        # one column (_reflow_action_buttons).
        grid_buttons = [save_btn, share_btn, delete_btn,
                        duplicate_btn, template_btn, use_template_btn]
        self._action_row = action_row
        self._action_buttons = grid_buttons
        self._action_cols = None
        for btn in grid_buttons:
            btn.configure(anchor="center")
        self._grid_action_buttons(3)
        action_row.bind("<Configure>", self._reflow_action_buttons, add="+")

        # Appears only when the current note has a recoverable previous version
        # (e.g. after text was accidentally deleted and auto-saved).
        self.restore_prev_btn = tk.Button(
            action_row, text="↩ Restore previous", command=self.restore_previous_version,
            relief="flat", font=("Segoe UI", 10, "bold"), cursor="hand2"
        )
        self.track_theme(self.restore_prev_btn, bg="card", fg="text")
        # Not packed yet — shown by _update_restore_button() when relevant.

        # Status (Created / Last updated) sits on its OWN row below the buttons,
        # so it can never be overlapped when the window is narrow.
        status_row = tk.Frame(self.editor)
        self.track_theme(status_row, bg="bg")
        status_row.pack(fill="x", padx=30, pady=(0, 25))
        self.status_lbl = tk.Label(status_row, text="", font=("Segoe UI", 9), anchor="w")
        self.track_theme(self.status_lbl, bg="bg", fg="subtext")
        self.status_lbl.pack(side="left", fill="x")

        # Inline area where a generated "Copy code" appears (replaces the pop-up).
        self.editor_code_area = tk.Frame(self.editor)
        self.track_theme(self.editor_code_area, bg="bg")
        # packed on demand by share_current_note_as_code()

        self._bind_mousewheel_recursive(
            self.editor, self.editor_canvas,
            skip={self.body_text, self.comments_text})


    # ---------- Calendar tab ----------





    def open_month_jump(self):
        """Pick any month/year directly, for destinations that are years away.
        Renders as an in-app dropdown anchored to the month title, not a
        separate window."""
        self._dismiss_mini_popup()
        popup = tk.Toplevel(self)
        self._mini_popup = popup
        popup.wm_overrideredirect(True)
        popup.configure(bg=self.colors["accent"])
        outer = tk.Frame(popup, bg=self.colors["card"], padx=1, pady=1)
        outer.pack()
        frame = tk.Frame(outer, bg=self.colors["card"])
        frame.pack()

        head = tk.Frame(frame, bg=self.colors["card"])
        head.pack(fill="x", padx=16, pady=(12, 8))
        tk.Label(
            head, text="Jump to month and year", font=("Segoe UI", 10, "bold"),
            bg=self.colors["card"], fg=self.colors["text"]
        ).pack(side="left")
        tk.Button(head, text="✕", command=self._dismiss_mini_popup, relief="flat",
                  cursor="hand2", bg=self.colors["card"], fg=self.colors["subtext"],
                  font=("Segoe UI", 9, "bold"), bd=0).pack(side="right")

        row = tk.Frame(frame, bg=self.colors["card"])
        row.pack(padx=16)

        month_names = list(cal_module.month_name)[1:]
        month_var = tk.StringVar(value=cal_module.month_name[self.cal_month])
        month_menu = self._build_themed_dropdown(
            row, month_var, month_names, on_change=lambda v: None, width_chars=10,
            nested=True)
        month_menu.pack(side="left", padx=(0, 8))

        year_var = tk.StringVar(value=str(self.cal_year))
        year_entry = tk.Entry(
            row, textvariable=year_var, width=6, relief="flat",
            font=("Segoe UI", 10), justify="center",
            bg=self.colors["sidebar"], fg=self.colors["text"],
            insertbackground=self.colors["text"]
        )
        year_entry.pack(side="left", ipady=3)
        year_entry.select_range(0, "end")
        year_entry.focus()

        error_lbl = tk.Label(
            frame, text="", font=("Segoe UI", 8),
            bg=self.colors["card"], fg=self.colors["danger_text"]
        )
        error_lbl.pack(pady=(6, 0))

        def _go(event=None):
            raw = year_var.get().strip()
            # isdecimal() is what int() reads ("٢٠٢٦" too); isdigit() passed
            # "2026²", which int() refused (as core/calculator.py learned).
            if not raw.isdecimal() or not 1 <= int(raw) <= 9999:
                error_lbl.config(text="Enter a year between 1 and 9999")
                return
            self.cal_year = int(raw)
            self.cal_month = month_names.index(month_var.get()) + 1
            self.render_calendar()
            self._dismiss_mini_popup()

        # "break": a good year destroys this popup (see _show_inline_rename).
        # Pressed, not held: a repeat pressed the month title it went back
        # to, and the popup opened again (_enter_repeats).
        year_entry.bind("<Return>", lambda e: (
            None if self._enter_repeats(e) else _go(), "break")[1])

        btn_row = tk.Frame(frame, bg=self.colors["card"])
        btn_row.pack(fill="x", padx=16, pady=(10, 14))

        tk.Button(
            btn_row, text="Go", command=_go, bg=self.colors["accent"], fg=self._on_fill("accent"),
            relief="flat", font=("Segoe UI", 9, "bold"), cursor="hand2"
        ).pack(side="left", fill="x", expand=True, padx=(0, 4), ipady=5)

        tk.Button(
            btn_row, text="Cancel", command=self._dismiss_mini_popup, bg=self.colors["sidebar"],
            fg=self.colors["text"], relief="flat", font=("Segoe UI", 9), cursor="hand2"
        ).pack(side="left", fill="x", expand=True, padx=(4, 0), ipady=5)

        self._place_dropdown_popup(popup, self.cal_month_lbl)





    # ---------- Daily reminder bar ----------




    def notes_on_date(self, date_str):
        """Every note that lands on this date, recurring ones included."""
        return core_notes_on_date(self.notes, date_str)



    def hide_day_tooltip(self):
        tip = getattr(self, "_day_tooltip", None)
        if tip is not None:
            try:
                if tip.winfo_exists():
                    tip.destroy()
            except tk.TclError:
                pass
            self._day_tooltip = None

    def open_day_popup(self, date_str):
        """Kept name for existing callers, but now shows the day in the inline
        panel (which appears only when a day is selected)."""
        self.hide_day_tooltip()
        self.selected_day = date_str
        self._show_day_panel()
        self.show_day_list()
        self._update_selected_day_outline()

    def _show_day_panel(self):
        """Make the panel visible below the grid. Deliberately does NOT
        auto-scroll down to it — clicking a date used to yank the view down
        every time, which was disruptive if you were just glancing at the
        month. Scroll down yourself when you're ready to see it."""
        if not self._is_placed(self.day_panel):
            self.day_panel.pack(side="bottom", fill="x", padx=30, pady=(0, 20))

    def close_day_panel(self):
        """Hide the panel and give the calendar its full height back."""
        self.selected_day = None
        self._day_panel_mode = "empty"
        self.day_panel.pack_forget()
        self._update_selected_day_outline()





    def _delete_note_from_calendar(self, note, date_str):
        """Delete a note from within the calendar day panel (list or detail
        view). Only refreshes the panel if the note actually stopped
        occurring on this date — if the user cancels the confirmation (or,
        for a recurring note, cancels the occurrence-scope prompt), the
        current view is left exactly as it was, rather than always bouncing
        back to the list regardless of what was chosen."""
        self._context_delete_note(note, date_str)
        still_here = any(n["id"] == note["id"] for n in self.notes_on_date(date_str))
        if not still_here:
            self.refresh_day_panel()

    def refresh_day_panel(self):
        """Re-render whatever the panel is currently showing (after edits/deletes)."""
        # Off screen it waits, as render_calendar does (each autosave walked
        # every note); the way back redraws it (_redraw_open_day).
        if not self._calendar_is_showing():
            self._calendar_needs_render = True
            return
        if self._day_panel_mode == "list":
            self.show_day_list()
        elif self._day_panel_mode == "note":
            # Fall back to the list — the note may have changed or been deleted.
            self.show_day_list()



    def _return_to_calendar(self):
        """Jump back to the exact month/day the user was viewing before they
        started creating a note from the calendar."""
        # Save first — leaving a dirty day behind rendered the day panel
        # from the store, which still held the OLD content: the edit
        # looked lost.
        self._flush_autosave()
        # STILL dirty, the flush did not finish (a date to fix): the day panel
        # would show the old content, and load it over the edit. Stay put;
        # the way back stays armed.
        try:
            st = self.capture_editor_state()
            # An emptied SAVED note counts as dirty, but only what a flush
            # could save blocks: a new note holding only a repeat rule (the
            # junk guard refuses it) left Back dead forever.
            _blockable = (self._editing_saved_note()
                          or self._editor_state_has_content(
                              {k: v for k, v in st.items()
                               if k != "recurrence"}))
            if _blockable and not self.editor_state_matches_saved(st):
                self.set_status(
                    "Not saved yet — fix the date to go back to the calendar")
                return
        except Exception:  # noqa: BLE001 -- a guard that fails must not trap Back
            self._log_swallowed("return to calendar: unsaved check")
        info = getattr(self, "_pending_calendar_return", None)
        self._pending_calendar_return = None
        self.calendar_return_btn.pack_forget()
        if not info:
            self.notebook.select(self.TAB_CALENDAR)
            return
        self.cal_year, self.cal_month = info["year"], info["month"]
        self.notebook.select(self.TAB_CALENDAR)
        self.render_calendar()
        if info.get("date_str"):
            self.open_day_popup(info["date_str"])

    def _update_calendar_return_button(self):
        """Show/hide the small 'Back to Calendar' link in the editor, only
        while there's a pending calendar-originated note to return to."""
        if getattr(self, "_pending_calendar_return", None):
            if not self._is_placed(self.calendar_return_btn):
                self.calendar_return_btn.pack(fill="x", padx=30, pady=(14, 0),
                                              anchor="w", before=self.editor_top_row)
        else:
            self.calendar_return_btn.pack_forget()

    def _update_occurrence_banner(self):
        """Show which day of a repeating series the editor holds, or hide
        the line entirely for plain notes and series views. Called wherever
        current_occurrence_date changes (load, new, tab restore)."""
        occ = self.current_occurrence_date
        text = ""
        off = []
        if occ:
            # The day strip says which day (_show_day_mode, below).
            pass
        elif self.selected_note_id is not None:
            # The series' line names the days that keep their own edits: a
            # series edit there looked failed (field report).
            note = self.find_note(self.selected_note_id)
            if note is not None and is_recurring(note):
                text = (f"🔁 This note repeats ({describe_recurrence(note)}) "
                        "— edits here apply to every day")
                # A day off the schedule is counted apart, with its way in
                # below; not while turning the repeat off waits.
                if not self._repeat_off_waits():
                    off = off_schedule_days(note)
                n_over = len(note.get("overrides") or {}) - len(off)
                if n_over == 1:
                    text += " · 1 day keeps its own edits (✎)"
                elif n_over > 1:
                    text += f" · {n_over} days keep their own edits (✎)"
                # Moved days, judged at once: one at a time, 5,000 took a
                # minute and a half to open.
                n_moved = len(drawn_moves(note))
                if n_moved == 1:
                    text += " · 1 day moved (↷)"
                elif n_moved > 1:
                    text += f" · {n_moved} days moved (↷)"
        if text:
            self.occurrence_banner.config(text=text)
            if not self._is_placed(self.occurrence_banner):
                self.occurrence_banner.pack(fill="x", padx=30, pady=(6, 0),
                                            before=self.editor_top_row)
        else:
            self.occurrence_banner.pack_forget()
        if off:
            self.offschedule_btn.config(text=(
                "✎ 1 day's own edits are off the schedule — Show it"
                if len(off) == 1 else
                f"✎ {len(off)} days' own edits are off the schedule — Show them"))
            if not self._is_placed(self.offschedule_btn):
                self.offschedule_btn.pack(fill="x", padx=30, pady=(2, 0),
                                          before=self.editor_top_row)
        else:
            self.offschedule_btn.pack_forget()
        self._show_day_mode()

    def _day_mode(self):
        """Whether the editor holds one day of a repeating series, opened on
        its own (from the calendar): what it saves is that day's."""
        if not self.current_occurrence_date \
                or self.selected_note_id is None:
            return False
        note = self.find_note(self.selected_note_id)
        return note is not None and is_recurring(note)

    def _series_owned_mark(self):
        """What the checklist and the attachments add to their names in day
        mode: they are the series', whichever day shows them, and a tick or a
        file added on one day is there on every day."""
        return " · whole series" if self._day_mode() else ""

    def _show_day_mode(self):
        """Lay the editor out for one day of a series (_day_mode), or back:
        its date in words, its repeat as a line, the strip, "This day:". The
        series' date and repeat stay filled, hidden, so a day's save cannot
        move or stop the series. Idempotent, called through
        _update_occurrence_banner."""
        on = self._day_mode()
        note = self.find_note(self.selected_note_id) if on else None
        day = self.current_occurrence_date if on else None
        when = parse_date(day) if day else None
        if on:
            origin = moved_from(note, day)
            origin_day = parse_date(origin) if origin else None
            self.day_strip_lbl.config(text=(
                f"📅 Only this day: {show_day(when) if when else day}"
                + (f" — moved from {show_day(origin_day, year=False)}"
                   if origin_day else "")
                + " — what you change here stays on this day"))
            if not self._is_placed(self.day_strip):
                self.day_strip.pack(fill="x", padx=30, pady=(12, 0),
                                    before=self.editor_top_row)
            for widget, _packing in self._date_field_packing:
                widget.pack_forget()
            # The date alone; the rest is the strip's (here too, the row
            # asked 690 px of 527).
            self.day_date_lbl.config(text=show_date(day))
            if not self._is_placed(self.day_date_lbl):
                self.day_date_lbl.pack(side="left", padx=(6, 8),
                                       before=self._color_label)
            resettable = bool(origin) or day in (note.get("overrides") or {})
            if not self._is_placed(self.day_move_btn):
                self.day_move_btn.pack(side="left", ipadx=4)
            if resettable and not self._is_placed(self.day_reset_btn):
                self.day_reset_btn.pack(side="left", padx=(6, 0), ipadx=4)
            elif not resettable:
                self.day_reset_btn.pack_forget()
            self._place_day_buttons()
            for widget, _packing in self._repeat_field_packing:
                widget.pack_forget()
            self.rec_details.pack_forget()
            start = show_date(note.get("date") or "")
            self.day_repeat_lbl.config(text=(
                describe_recurrence(note)
                + (f", starting {start}" if start else "")
                + " — change it in the whole series"))
            if not self._is_placed(self.day_repeat_lbl):
                self.day_repeat_lbl.pack(side="left", padx=(8, 0))
            if not self._is_placed(self.day_cat_lbl):
                self.day_cat_lbl.pack(side="right", padx=(10, 0),
                                      after=self.category_menu)
        else:
            self.day_strip.pack_forget()
            self.day_cat_lbl.pack_forget()
            self.day_btns.pack_forget()
            self._day_btns_wrapped = None
            self.day_move_btn.pack_forget()
            self.day_reset_btn.pack_forget()
            if self._is_placed(self.day_date_lbl):
                self.day_date_lbl.pack_forget()
                for widget, packing in self._date_field_packing:
                    widget.pack(before=self._color_label, **packing)
            if self._is_placed(self.day_repeat_lbl):
                self.day_repeat_lbl.pack_forget()
                for widget, packing in self._repeat_field_packing:
                    widget.pack(**packing)
                # The repeat's own rows come back with its frequency.
                self.on_recurrence_changed()
        self.attach_label.config(text="📎 Attachments" + self._series_owned_mark())
        self._update_checklist_progress()

    def _edit_whole_series(self):
        """The day strip's way to the whole series: the day is saved to the
        day first, as leaving it saves it, then the series opens in its
        place. The way back to the calendar stays as it was -- it is the way
        back to that day."""
        note = self.find_note(self.selected_note_id) \
            if self.selected_note_id is not None else None
        if note is None:
            return
        pending = getattr(self, "_pending_calendar_return", None)
        if not self.open_note_in_tab(note):
            return
        if pending is not None:
            self._pending_calendar_return = pending
            self._update_calendar_return_button()

    def _place_day_buttons(self, event=None):
        """Day mode's Move and Reset (day_btns): beside the date with room,
        under it without (a short row dropped the swatch). Counted from the
        widths asked, which do not change with where they go, so moving them
        cannot undo itself. From _show_day_mode and the row's <Configure>."""
        if event is not None and self._day_btns_wrapped is None:
            return

        def width(w):
            kw = w.pack_info()
            padx = kw.get("padx", 0)
            pad = sum(padx) if isinstance(padx, (tuple, list)) else 2 * int(padx)
            return w.winfo_reqwidth() + 2 * int(kw.get("ipadx", 0)) + pad

        row = self.day_btns.master
        try:
            room = row.winfo_width()
            # 20: the space the frame keeps before the colour, packed below.
            need = 20 + sum(width(w) for w in self.day_btns.pack_slaves()) + sum(
                width(w) for w in row.pack_slaves() if w is not self.day_btns)
        except (tk.TclError, ValueError):
            return
        wrap = room > 1 and need > room
        if wrap == self._day_btns_wrapped:
            return
        self._day_btns_wrapped = wrap
        if wrap:
            self.day_btns.pack(side="bottom", anchor="w", padx=0, pady=(6, 0),
                               before=self._date_row_label)
        else:
            self.day_btns.pack(side="left", anchor="center", padx=(0, 20),
                               pady=0, before=self._color_label)

    def _reset_this_day(self):
        """Day mode's "↺ Reset this day…": the calendar menu's Reset, for
        the day on screen (_reset_occurrence_override)."""
        if not self._day_mode():
            return
        note = self.find_note(self.selected_note_id)
        if note is not None:
            self._reset_occurrence_override(note, self.current_occurrence_date)

    def _open_move_day_picker(self):
        """Day mode's "📅 Move this day…": the date picker, opened on the
        day, whose pick moves it (_move_this_day)."""
        if not self._day_mode():
            return
        self.open_date_picker(anchor_widget=self.day_move_btn,
                              on_pick=self._move_this_day,
                              marked=self.current_occurrence_date)

    def _day_is_free(self, note, day, to):
        """Whether *note*'s day now on *day* may be held on *to*: a date no
        other day is on, nor one it keeps an edit for and draws no day on --
        the move wrote over its words. Its own date too: another day may
        have moved there meanwhile (the phone refused it as well)."""
        target = parse_date(to)
        return target is not None and (to == day or (
            expand_occurrences(note, target, target) != [to]
            and to not in (note.get("overrides") or {})))

    def _move_this_day(self, to):
        """Hold the day on screen on *to*, still one day of its series
        ("📅 Move this day…", field request 2026-10-13: a weekly meeting held
        on another day one week). What was typed is saved to the day first,
        and its own edit goes with it; the editor opens the day where it is
        now, and an Undo puts it back."""
        note = self.find_note(self.selected_note_id) if self._day_mode() else None
        day = self.current_occurrence_date
        if note is None or not day or parse_date(to) is None or to == day:
            return
        if not self._day_is_free(note, day, to):
            when = parse_date(to)
            self.show_info(
                "That day is taken",
                f"This series already has a day on {show_day(when)}. "
                "A day can move only to a date the series does not have."
                if expand_occurrences(note, when, when) == [to] else
                f"This series still keeps text or a colour of its own for a day on "
                f"{show_day(when)}, which its calendar no longer shows. A day can move "
                "only to a date the series holds nothing for.")
            return
        # Saved to the day first, as leaving it saves it: the typing goes
        # with the day.
        if self._flush_autosave(leaving=False) is False:
            return
        note = self.find_note(note["id"])
        if (note is None or not is_recurring(note)
                or self.current_occurrence_date != day):
            return
        origin = self._relocate_day(note, day, to)
        self.set_status(f"Moved to {show_day(parse_date(to))}")
        self._show_toast("Day moved", action=(
            lambda nid=note["id"], uid=note.get("uid"):
            self._undo_day_move(nid, uid, origin, to, day)))

    def _relocate_day(self, note, day, to):
        """Hold *note*'s day now on *day* on *to* (move_day), and bring every
        surface along: the file, the list, the calendar and its day panel,
        and the editor -- which, holding that day, opens it where it is now,
        the way back to the calendar following it there. Returns the date
        the rule gives the day."""
        origin = move_day(note, day, to)
        note["updated"] = now_stamp()
        self.save_notes()
        if (self.selected_note_id == note["id"]
                and self.current_occurrence_date == day):
            pending = getattr(self, "_pending_calendar_return", None)
            self.open_note_in_tab(note, occurrence_date=to, flush=False)
            when = parse_date(to)
            if pending is not None and when is not None:
                self._pending_calendar_return = dict(
                    pending, date_str=to, year=when.year, month=when.month)
                self._update_calendar_return_button()
        elif self.selected_note_id == note["id"]:
            self._update_occurrence_banner()
        self.refresh_note_list()
        self.render_calendar()
        self.refresh_day_panel()
        return origin

    def _undo_day_move(self, note_id, uid, origin, now_on, back_to):
        """The Undo a move offers: the day back on *back_to* -- if it is
        still the day of *origin*, still on *now_on*, and *back_to* is free.
        The editor holding it saves first, as for the move itself."""
        note = self._note_for_undo(note_id, uid)
        if note is None:
            self._show_toast("That note is no longer here", kind="info")
            return
        on = parse_date(now_on)
        if (not is_recurring(note) or on is None
                or (moved_from(note, now_on) or now_on) != origin
                or expand_occurrences(note, on, on) != [now_on]):
            self._show_toast("That day has moved on since, so it stays where "
                             "it is", kind="info")
            return
        if not self._day_is_free(note, now_on, back_to):
            self._show_toast("Another day of this series is there now, so "
                             "this one stays where it is", kind="info")
            return
        if (self.selected_note_id == note["id"]
                and self.current_occurrence_date == now_on
                and self._flush_autosave(leaving=False) is False):
            return
        note = self.find_note(note["id"])
        if note is None:
            return
        self._relocate_day(note, now_on, back_to)
        self.set_status(f"Moved back to {show_day(parse_date(back_to))}")

    def _show_off_schedule_days(self, note=None):
        """Walk a series' edited days off its schedule (off_schedule_days),
        one question each in the app's question box (its keyboard, theme and
        safe Escape): a note of its own, the Trash, or leave it -- which
        changes nothing."""
        if note is None:
            note = self.find_note(self.selected_note_id)
        if note is None:
            return
        days = off_schedule_days(note)
        # What the editor holds is saved first, as every route that writes a
        # note behind the editor saves it (_editor_follows_external_change) --
        # as left only when it is this note: another's leaves it open.
        leaving = note.get("id") == self.selected_note_id
        if not days or self._flush_autosave(leaving=leaving) is False:
            self._update_occurrence_banner()
            return
        made = trashed = 0
        for index, day in enumerate(days, start=1):
            # Asked again each time: the question waits, and a timer's save
            # can have changed the note under it.
            if not any(n is note for n in self.notes) or \
                    day not in (note.get("overrides") or {}):
                continue
            shown = effective_note(note, day)
            when = parse_date(day)
            title = (shown.get("title") or "").strip() or "Untitled"
            text, _tables = core_tables.preview_text(shown.get("body") or "")
            text = " ".join(text.split())
            if len(text) > 160:
                text = text[:160].rstrip() + "…"
            choice = self._themed_dialog(
                f"Day {index} of {len(days)} off the schedule",
                f"{show_day(when) if when else day} — “{one_line(title, 200)}”"
                + (f"\n{text}" if text else "")
                + f"\n\nThis day keeps its own edits, but the repeat "
                f"({describe_recurrence(note)}) no longer lands on it, so the "
                "calendar does not show it.\n\nA note of its own puts it back "
                "on the calendar, on its day. The Trash keeps it"
                f"{trash_window_words('for')}.",
                kind="question",
                buttons=[("Leave it", "keep"), ("Move to the Trash", "trash"),
                         ("Make it a note", "note")],
                default="Make it a note")
            if choice in ("note", "trash"):
                if not self._settle_off_schedule_day(note, day, choice):
                    break   # the Trash could not be written, and that was said
                made += choice == "note"
                trashed += choice == "trash"
        if made or trashed:
            note["updated"] = now_stamp()
            self.save_notes()
            self._editor_follows_external_change({note.get("id")})
            self.refresh_note_list()
            self.render_calendar()
            said = []
            if made:
                said.append(f"{made} made a note of its own" if made == 1
                            else f"{made} made notes of their own")
            if trashed:
                said.append(f"{trashed} moved to the Trash")
            self.set_status("Days off the schedule: " + ", ".join(said))
        self._update_occurrence_banner()

    def _day_as_shown(self, note, day):
        """A copy of *note* as one *day* of it shows, for a file made of that
        day: the day's own words and looks (the series' formatting only on
        the series' own text, as below), on its date, with no repeat."""
        shown = effective_note(note, day)
        out = copy.deepcopy(note)
        out.update(title=shown.get("title") or "", body=shown.get("body") or "",
                   formatting=(copy.deepcopy(note.get("formatting") or [])
                               if shown.get("body") == note.get("body") else []),
                   paragraphs=day_paragraphs_shown(note, day),
                   comments=shown.get("comments") or "",
                   category=shown.get("category") or note.get("category"),
                   color=shown.get("color") or "", date=day,
                   recurrence=dict(RECURRENCE_DEFAULTS))
        return out

    def _settle_off_schedule_day(self, note, day, how):
        """One day off *note*'s schedule made a note of its own (*how* is
        "note") or put in the Trash as one ("trash"), out of the series,
        holding what the day showed. The formatting comes only on the
        series' own text (its offsets fit no other); checklist and files
        stay with the series."""
        shown = effective_note(note, day)
        same_body = shown.get("body") == note.get("body")
        stamp = now_stamp()
        fresh = normalize_note({
            "id": max([n["id"] for n in self.notes], default=0) + 1,
            "title": shown.get("title") or "",
            "body": shown.get("body") or "",
            "formatting": copy.deepcopy(note.get("formatting") or []) if same_body else [],
            # ...and the lines' looks the day view shows (day_paragraphs_shown).
            "paragraphs": day_paragraphs_shown(note, day),
            "comments": shown.get("comments") or "",
            "category": shown.get("category") or note.get("category"),
            "color": shown.get("color") or "",
            "date": day,
            "created": stamp,
            "updated": stamp,
        })
        # Into the Trash before the day leaves the series: if trash.json
        # cannot be written, the day's own words stay where they were.
        if how == "trash" and self._move_notes_to_trash([fresh]) is None:
            return False
        note["overrides"].pop(day, None)
        # A day moved here whose own day the rule no longer gives: the move
        # goes with it, or it would draw the day again if the rule came back.
        origin = moved_from(note, day)
        if origin is not None:
            note["moved"].pop(origin, None)
        if how != "trash":
            self.notes.append(fresh)
        return True



    # Kinds that open with the stronger warning (core/model.py); every kind
    # off the short unasked list asks first (how_to_open; ISSUES_LOG: "The
    # photo that was a remote connection").
    DANGEROUS_EXTENSIONS = DANGEROUS_EXTENSIONS





    def _update_color_swatch(self):
        """Show the note's colour on the swatch, and nothing else.

        No words beside it. The swatch already shows the colour, and the
        picker is one click away -- naming the state ("custom colour")
        told the user something they could see, in exchange for a second
        thing to read on a row that is mostly labels already.
        """
        color = self.current_note_color or CATEGORY_COLORS.get(
            self.category_var.get(), self.colors["accent"])
        self.color_swatch_btn.config(bg=color, activebackground=color)

    def open_color_picker(self):
        """Pick this note's own color from a curated palette. Renders as an
        in-app dropdown anchored to the color swatch button, not a separate
        window. Swatches only, no hex-code entry -- most users don't think
        in hex, so the palette is the whole picker."""
        self._dismiss_mini_popup()
        popup = tk.Toplevel(self)
        self._mini_popup = popup
        popup.wm_overrideredirect(True)
        popup.configure(bg=self.colors["accent"])
        outer = tk.Frame(popup, bg=self.colors["card"], padx=1, pady=1)
        outer.pack()
        body = tk.Frame(outer, bg=self.colors["card"])
        body.pack()

        label = tk.Label(body, text="Pick a color for this note", font=("Segoe UI", 10, "bold"),
                          bg=self.colors["card"], fg=self.colors["text"])
        label.pack(padx=15, pady=(12, 8))

        swatch_grid = tk.Frame(body, bg=self.colors["card"])
        swatch_grid.pack(padx=15)

        def _choose(color):
            self.current_note_color = color
            self._update_color_swatch()
            self._schedule_autosave()
            self._dismiss_mini_popup()

        for i, hex_color in enumerate(PRESET_NOTE_COLORS):
            swatch = tk.Button(
                swatch_grid, bg=hex_color, activebackground=hex_color, width=3, height=1,
                relief="flat", cursor="hand2", command=lambda c=hex_color: _choose(c)
            )
            swatch.grid(row=i // 5, column=i % 5, padx=4, pady=4)
            self._button_choice(swatch,
                                current=hex_color == self.current_note_color)

        button_row = tk.Frame(body, bg=self.colors["card"])
        button_row.pack(fill="x", padx=15, pady=(8, 14))

        reset_btn = tk.Button(
            button_row, text="Reset to category", command=lambda: _choose(""), relief="flat",
            bg=self.colors["sidebar"], fg=self.colors["text"], cursor="hand2", font=("Segoe UI", 9)
        )
        reset_btn.pack(fill="x", ipady=5)
        self._button_choice(reset_btn)

        self._place_dropdown_popup(popup, self.color_swatch_btn)

    def clear_note_date(self):
        self._show_date_in_field("")
        # The summary reads the date from the field (see the date field's
        # bindings): emptied, a series still starts on its stored date.
        self.update_recurrence_summary()

    def _show_date_in_field(self, value):
        """Put a date in the note's date field, the way the app shows dates
        (show_date: a stored 2026-10-17 reads 17.10.2026, and text it cannot
        read stays as it was typed) -- or, for none, the grey form
        DD.MM.YYYY. The one way the editor fills that field, so the text
        and its colour cannot come apart between the routes that load,
        restore, import or put back a note's date."""
        self.date_entry.delete(0, "end")
        if value:
            self.date_entry.insert(0, show_date(value))
            self.date_entry.config(fg=self.colors["text"])
        else:
            self.date_entry.insert(0, DATE_FORM)
            self.date_entry.config(fg=self.colors["subtext"])

    def _typed_date(self):
        """What the date field holds as typed: its text, or "" while it shows
        its form. The one reader of the field -- the form compared by hand
        in five places was five places to forget the day it changed, and a
        rule in tools/check_one_definition.py now keeps it to one."""
        typed = self.date_entry.get().strip()
        return "" if typed == DATE_FORM else typed

    def _settle_date_fields(self, redraw=False):
        """Finishing with the date fields: a readable date is written in the
        form shown, its year completed (17.10 -> 17.10.2026; read_date,
        settled); the unreadable stays, for the save to name. Run on leaving
        a field (*redraw* redraws the repeat's summary) and before a chosen
        save -- never mid-typing, a wrong year. Returns whether one changed."""
        changed = False
        typed = self._typed_date()
        if typed:
            day = read_date(typed, settled=True)
            if day is not None and show_date(format_date(day)) != typed:
                self._show_date_in_field(format_date(day))
                changed = True
        end_typed = self.rec_end_date_var.get().strip()
        if end_typed:
            day = read_date(end_typed, settled=True)
            if day is not None and show_date(format_date(day)) != end_typed:
                # Its trace redraws the summary, as every change to it does.
                self.rec_end_date_var.set(show_date(format_date(day)))
                changed = True
        if changed and redraw:
            self.update_recurrence_summary()
        return changed

    def _watch_date_field(self, entry):
        """Wire finishing with a date field to *entry*: leaving it, Enter --
        and a click anywhere else, which moves no focus, so 17.10 was left
        unsaved (field report). The field's own focus events note it; the
        click's work goes on. add="+": the placeholder's handlers run first.
        """
        def arrived(_event):
            self._date_field_in_use = entry

        def left(_event):
            if getattr(self, "_date_field_in_use", None) is entry:
                self._date_field_in_use = None
            self._settle_date_fields(redraw=True)

        def enter(event):
            if not self._enter_repeats(event):      # pressed, not held
                self._settle_date_fields(redraw=True)

        entry.bind("<FocusIn>", arrived, add="+")
        entry.bind("<FocusOut>", left, add="+")
        for sequence in ("<Return>", "<KP_Enter>"):
            entry.bind(sequence, enter, add="+")
        if not getattr(self, "_watching_clicks_for_dates", False):
            self.bind_all("<ButtonPress-1>",
                          self._settle_dates_on_click_elsewhere, add="+")
            self._watching_clicks_for_dates = True

    def _settle_dates_on_click_elsewhere(self, event):
        """A click anywhere but the date field that holds the keyboard
        settles it, as leaving it would (see _watch_date_field)."""
        entry = getattr(self, "_date_field_in_use", None)
        if entry is not None and getattr(event, "widget", None) is not entry:
            self._settle_date_fields(redraw=True)

    def open_date_picker(self, target_entry=None, anchor_widget=None,
                         on_pick=None, marked=None):
        """A calendar dropdown anchored to the button that opened it, for any
        date field (target_entry/anchor_widget; none: the note's Date). With
        *on_pick* the 'YYYY-MM-DD' goes there once it closes, no field
        written; *marked* is the day it opens on ("Move this day")."""
        target_entry = target_entry or self.date_entry
        anchor_widget = anchor_widget or self.pick_date_btn

        # Read as the field would be once left: the picker opens on the date
        # typed there, in whatever form it was typed, and marks that day.
        current_day = (parse_date(marked) if on_pick is not None
                       else read_date(target_entry.get(), settled=True))
        start_date = current_day or datetime.now().date()

        self._dismiss_mini_popup()
        picker = tk.Toplevel(self)
        self._mini_popup = picker
        picker.wm_overrideredirect(True)
        picker.configure(bg=self.colors["accent"])
        outer = tk.Frame(picker, bg=self.colors["card"], padx=1, pady=1)
        outer.pack()
        pop_body = tk.Frame(outer, bg=self.colors["card"])
        pop_body.pack()

        state = {"year": start_date.year, "month": start_date.month}

        header = tk.Frame(pop_body, bg=self.colors["card"])
        header.pack(fill="x", padx=10, pady=(10, 5))

        prev_btn = tk.Button(header, text="◀", relief="flat", font=("Segoe UI", 10, "bold"),
                              bg=self.colors["sidebar"], fg=self.colors["text"], cursor="hand2", width=3)
        prev_btn.pack(side="left")

        month_lbl = tk.Label(header, text="", font=("Segoe UI", 12, "bold"),
                              bg=self.colors["card"], fg=self.colors["text"])
        month_lbl.pack(side="left", expand=True)

        next_btn = tk.Button(header, text="▶", relief="flat", font=("Segoe UI", 10, "bold"),
                              bg=self.colors["sidebar"], fg=self.colors["text"], cursor="hand2", width=3)
        next_btn.pack(side="right")

        grid_frame = tk.Frame(pop_body, bg=self.colors["card"])
        grid_frame.pack(padx=10, pady=(0, 10))

        def _pick(date_str):
            if on_pick is not None:
                # Closed first: what the callback does may ask a question,
                # which must not open under a picker still on screen.
                self._dismiss_mini_popup()
                on_pick(date_str)
                return
            target_entry.delete(0, "end")
            target_entry.insert(0, show_date(date_str))
            target_entry.config(fg=self.colors["text"])
            # Redraws the repeat's summary, which reads both date fields, and
            # schedules the autosave.
            self.update_recurrence_summary()
            self._dismiss_mini_popup()

        def _render():
            for w in grid_frame.winfo_children():
                w.destroy()
            month_lbl.config(text=f"{cal_module.month_name[state['month']]} {state['year']}")

            for col, wd in enumerate(["Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"]):
                lbl = tk.Label(grid_frame, text=wd, font=("Segoe UI", 8, "bold"),
                                bg=self.colors["card"], fg=self.colors["subtext"], width=4)
                lbl.grid(row=0, column=col, pady=(0, 4))

            weeks = cal_module.monthcalendar(state["year"], state["month"])
            for r, week in enumerate(weeks, start=1):
                for c, day in enumerate(week):
                    if day == 0:
                        continue
                    date_str = f"{state['year']:04d}-{state['month']:02d}-{day:02d}"
                    is_selected = (current_day is not None
                                   and format_date(current_day) == date_str)
                    btn = tk.Button(
                        grid_frame, text=str(day), width=4, relief="flat",
                        font=("Segoe UI", 9, "bold" if is_selected else "normal"),
                        bg=(self.colors["accent"] if is_selected else self.colors["sidebar"]),
                        fg=(self._on_fill("accent") if is_selected
                            else self.colors["text"]),
                        cursor="hand2", command=lambda d=date_str: _pick(d)
                    )
                    btn.grid(row=r, column=c, padx=1, pady=1)
                    # The keyboard starts on the marked day, else today.
                    self._button_choice(btn, current=is_selected or (
                        current_day is None and date_str == today_str))

        def _prev():
            state["month"] -= 1
            if state["month"] < 1:
                state["month"] = 12
                state["year"] -= 1
            _render()

        def _next():
            state["month"] += 1
            if state["month"] > 12:
                state["month"] = 1
                state["year"] += 1
            _render()

        prev_btn.config(command=_prev)
        next_btn.config(command=_next)
        for arrow in (prev_btn, next_btn):
            self._button_choice(arrow)
        today_str = format_date(datetime.now().date())
        _render()
        self._place_dropdown_popup(picker, anchor_widget)

    # ---------- Recurrence editor ----------
    def build_recurrence_section(self, parent):
        """The repeat controls. Sub-rows appear only when they're relevant to
        the chosen frequency, so the panel stays readable."""
        self.rec_weekday_state = [False] * 7

        freq_row = tk.Frame(parent)
        self.track_theme(freq_row, bg="bg")
        freq_row.pack(fill="x", padx=30, pady=(0, 6))

        freq_label = tk.Label(freq_row, text="🔁 Repeat:", font=("Segoe UI", 9, "bold"))
        self.track_theme(freq_label, bg="bg", fg="subtext")
        freq_label.pack(side="left")

        self.rec_freq_var = tk.StringVar(value=FREQ_LABELS[""])
        freq_menu = self._build_themed_dropdown(
            freq_row, self.rec_freq_var,
            [FREQ_LABELS[k] for k in ("", "daily", "weekly", "monthly", "yearly")],
            # A frequency picked is saved: "Does not repeat" draws no summary,
            # whose redraw asked the save, so turning off waited.
            on_change=lambda v: (self.on_recurrence_changed(),
                                 self._schedule_autosave(skip_word_count=True)),
            width_chars=14)
        freq_menu.pack(side="left", padx=(8, 10))
        self.rec_freq_menu = freq_menu

        self.rec_summary_lbl = tk.Label(freq_row, text="", font=("Segoe UI", 8, "italic"),
                                        justify="left")
        self.track_theme(self.rec_summary_lbl, bg="bg", fg="accent_text")
        self.rec_summary_lbl.pack(side="left")
        # Day mode puts these two back exactly as packed here, and shows the
        # repeat as words in their place: a day does not change the series'
        # repeat (_show_day_mode).
        self._repeat_field_packing = [
            (freq_menu, dict(side="left", padx=(8, 10))),
            (self.rec_summary_lbl, dict(side="left"))]
        self.day_repeat_lbl = tk.Label(freq_row, text="", font=("Segoe UI", 9),
                                       justify="left", anchor="w")
        self.track_theme(self.day_repeat_lbl, bg="bg", fg="text")

        def _wrap_summary(_event=None):
            # The summary wraps in what the row leaves (a long rule was cut),
            # counted from the others' asked widths less its own padding.
            lbl = self.rec_summary_lbl
            try:
                inner = 2 * sum(int(str(lbl.cget(o))) for o in
                                ("padx", "borderwidth", "highlightthickness"))
                room = (freq_row.winfo_width() - freq_label.winfo_reqwidth()
                        - freq_menu.winfo_reqwidth() - 18 - inner)
                lbl.configure(wraplength=max(room, 120))
                # The day's line has the room the dropdown leaves, less its
                # own 8 px of padding.
                self.day_repeat_lbl.configure(wraplength=max(
                    freq_row.winfo_width() - freq_label.winfo_reqwidth()
                    - 8 - inner, 120))
            except (tk.TclError, ValueError):
                pass
        freq_row.bind("<Configure>", _wrap_summary, add="+")

        # --- Below: only with a frequency chosen (on_recurrence_changed).
        # Its CHILDREN are packed and unpacked, so it keeps its slot; packed
        # empty, it left a gap above the body. ---
        self.rec_details = tk.Frame(parent)
        self.track_theme(self.rec_details, bg="bg")

        # Interval
        self.rec_interval_row = tk.Frame(self.rec_details)
        self.track_theme(self.rec_interval_row, bg="bg")
        interval_row = self.rec_interval_row

        every_lbl = tk.Label(interval_row, text="Every", font=("Segoe UI", 9))
        self.track_theme(every_lbl, bg="bg", fg="subtext")
        every_lbl.pack(side="left")

        self.rec_interval_var = tk.StringVar(value="1")
        interval_entry = tk.Entry(
            interval_row, textvariable=self.rec_interval_var, width=4,
            relief="flat", font=("Segoe UI", 9), justify="center",
            insertbackground=self.colors["text"]
        )
        self.track_theme(interval_entry, bg="card", fg="text", insertbackground="text")
        interval_entry.pack(side="left", padx=6, ipady=2)
        # Every Repeat box gets the paste menu (the end date and "1,15"
        # invite one); their traces schedule the autosave, so a paste saves
        # with no binding of its own.
        self._add_paste_menu(interval_entry)
        self.rec_interval_var.trace_add("write", lambda *a: self.update_recurrence_summary())

        self.rec_unit_lbl = tk.Label(interval_row, text="day(s)", font=("Segoe UI", 9))
        self.track_theme(self.rec_unit_lbl, bg="bg", fg="subtext")
        self.rec_unit_lbl.pack(side="left")

        # Weekly: which weekdays
        self.rec_weekday_row = tk.Frame(self.rec_details)
        self.track_theme(self.rec_weekday_row, bg="bg")

        on_lbl = tk.Label(self.rec_weekday_row, text="On:", font=("Segoe UI", 9))
        self.track_theme(on_lbl, bg="bg", fg="subtext")
        on_lbl.pack(side="left", padx=(0, 6))

        self.rec_weekday_btns = []
        for index, name in enumerate(WEEKDAY_NAMES):
            btn = tk.Button(
                self.rec_weekday_row, text=name, width=4, relief="flat",
                font=("Segoe UI", 8, "bold"), cursor="hand2",
                command=lambda i=index: self.toggle_weekday(i)
            )
            btn.pack(side="left", padx=1)
            self.rec_weekday_btns.append(btn)

        # Monthly: which days of the month
        self.rec_monthday_row = tk.Frame(self.rec_details)
        self.track_theme(self.rec_monthday_row, bg="bg")

        md_lbl = tk.Label(self.rec_monthday_row, text="On day(s):", font=("Segoe UI", 9))
        self.track_theme(md_lbl, bg="bg", fg="subtext")
        md_lbl.pack(side="left", padx=(0, 6))

        self.rec_monthdays_var = tk.StringVar(value="")
        monthdays_entry = tk.Entry(
            self.rec_monthday_row, textvariable=self.rec_monthdays_var, width=14,
            relief="flat", font=("Segoe UI", 9), insertbackground=self.colors["text"]
        )
        self.track_theme(monthdays_entry, bg="card", fg="text", insertbackground="text")
        monthdays_entry.pack(side="left", ipady=2)
        # A list like "1,15", not a single digit -- the one of these four the
        # row's reasoning fits least.
        self._add_paste_menu(monthdays_entry)
        self.rec_monthdays_var.trace_add("write", lambda *a: self.update_recurrence_summary())

        md_hint = tk.Label(
            self.rec_monthday_row, text="e.g. 1, 15   (blank = same day as the start date)",
            font=("Segoe UI", 8)
        )
        self.track_theme(md_hint, bg="bg", fg="subtext")
        md_hint.pack(side="left", padx=(8, 0))

        # Short-month policy (monthly + yearly)
        self.rec_policy_row = tk.Frame(self.rec_details)
        self.track_theme(self.rec_policy_row, bg="bg")

        policy_lbl = tk.Label(self.rec_policy_row, text="If the month is too short:", font=("Segoe UI", 9))
        self.track_theme(policy_lbl, bg="bg", fg="subtext")
        policy_lbl.pack(side="left", padx=(0, 6))

        self.rec_policy_var = tk.StringVar(value="Use the last day")
        policy_menu = self._build_themed_dropdown(
            self.rec_policy_row, self.rec_policy_var,
            ["Use the last day", "Skip that month"],
            on_change=lambda v: self.update_recurrence_summary(), width_chars=16)
        policy_menu.pack(side="left")

        # End condition
        self.rec_end_row = tk.Frame(self.rec_details)
        self.track_theme(self.rec_end_row, bg="bg")
        end_row = self.rec_end_row

        ends_lbl = tk.Label(end_row, text="Ends:", font=("Segoe UI", 9))
        self.track_theme(ends_lbl, bg="bg", fg="subtext")
        ends_lbl.pack(side="left", padx=(0, 6))

        self.rec_end_mode_var = tk.StringVar(value="never")

        def _end_radio(value, text):
            # The well is CARD: Windows paints the dot in the text colour,
            # invisible on the light check_well (all three looked unchosen);
            # card stands apart from the text on every theme.
            rb = tk.Radiobutton(
                end_row, text=text, value=value, variable=self.rec_end_mode_var,
                font=("Segoe UI", 9), relief="flat", cursor="hand2",
                command=self.on_end_mode_changed,
                selectcolor=self.colors["card"]
            )
            self.track_theme(rb, bg="bg", fg="text", activebackground="bg", activeforeground="text", selectcolor="card")
            rb.pack(side="left", padx=2)
            return rb

        # Each input is packed immediately after the radio it belongs to,
        # so "On date [____]" and "After [__] times" read correctly.
        _end_radio("never", "Never")

        _end_radio("on", "On date")
        self.rec_end_date_var = tk.StringVar(value="")
        self.rec_end_date_entry = tk.Entry(
            end_row, textvariable=self.rec_end_date_var, width=11,
            relief="flat", font=("Segoe UI", 9), insertbackground=self.colors["text"]
        )
        self.track_theme(self.rec_end_date_entry, bg="card", fg="text", insertbackground="text")
        self.rec_end_date_entry.pack(side="left", padx=(4, 2), ipady=2)
        # A date, exactly like the note's own date field, and just as likely
        # to be pasted from somewhere else.
        self._add_paste_menu(self.rec_end_date_entry)
        self.rec_end_date_var.trace_add("write", lambda *a: self.update_recurrence_summary())
        # Read like the note's own date, and settled the same way when you
        # finish with it: 31.12 becomes 31.12.2026 (_watch_date_field).
        self._watch_date_field(self.rec_end_date_entry)

        self.rec_end_date_pick_btn = tk.Button(
            end_row, text="📅",
            relief="flat", font=("Segoe UI", 9), cursor="hand2"
        )
        self._toggles_its_popup(
            self.rec_end_date_pick_btn,
            lambda: self.open_date_picker(self.rec_end_date_entry,
                                          self.rec_end_date_pick_btn))
        self.track_theme(self.rec_end_date_pick_btn, bg="sidebar", fg="text")
        self.rec_end_date_pick_btn.pack(side="left", padx=(0, 8), ipadx=2)

        _end_radio("after", "After")
        self.rec_count_var = tk.StringVar(value="10")
        self.rec_count_entry = tk.Entry(
            end_row, textvariable=self.rec_count_var, width=4,
            relief="flat", font=("Segoe UI", 9), justify="center",
            insertbackground=self.colors["text"]
        )
        self.track_theme(self.rec_count_entry, bg="card", fg="text", insertbackground="text")
        self.rec_count_entry.pack(side="left", padx=(4, 2), ipady=2)
        self._add_paste_menu(self.rec_count_entry)
        self.rec_count_var.trace_add("write", lambda *a: self.update_recurrence_summary())

        times_lbl = tk.Label(end_row, text="times", font=("Segoe UI", 9))
        self.track_theme(times_lbl, bg="bg", fg="subtext")
        times_lbl.pack(side="left")

        self.refresh_weekday_buttons()
        self.on_end_mode_changed()
        self.on_recurrence_changed()

    def on_end_mode_changed(self):
        """Grey out the inputs that don't apply, so the panel can't imply an
        end condition that won't actually be saved."""
        self._paint_end_fields()
        self.update_recurrence_summary()

    def _paint_end_fields(self):
        """The end-condition fields' state and colours, and nothing else: a
        theme switch repaints them, and a repaint is no reason to save."""
        mode = self.rec_end_mode_var.get()
        for entry, active in ((self.rec_end_date_entry, mode == "on"),
                              (self.rec_count_entry, mode == "after")):
            if active:
                entry.configure(state="normal", fg=self.colors["text"],
                                bg=self.colors["card"])
            else:
                # Muted, but still clearly a field. Using the panel background
                # here would make the box disappear into the layout.
                entry.configure(state="disabled",
                                disabledbackground=self.colors["sidebar"],
                                disabledforeground=self.colors["subtext"])
        self.rec_end_date_pick_btn.configure(
            state="normal" if mode == "on" else "disabled")

    def toggle_weekday(self, index):
        self.rec_weekday_state[index] = not self.rec_weekday_state[index]
        self.refresh_weekday_buttons()
        self.update_recurrence_summary()

    def refresh_weekday_buttons(self):
        for index, btn in enumerate(self.rec_weekday_btns):
            if self.rec_weekday_state[index]:
                btn.configure(bg=self.colors["accent"], fg=self._on_fill("accent"),
                              activebackground=self.colors["accent_hover"])
            else:
                btn.configure(bg=self.colors["card"], fg=self.colors["subtext"],
                              activebackground=self.colors["card"])

    def selected_freq_key(self):
        label = self.rec_freq_var.get()
        for key, text in FREQ_LABELS.items():
            if text == label:
                return key
        return ""

    def on_recurrence_changed(self):
        """Show only the controls that apply to the chosen frequency. All rows
        are re-packed in a fixed order so nothing drifts to the bottom."""
        freq = self.selected_freq_key()
        if freq:
            # A repeat picked again ends its turn-off's wait: a later turn-off
            # copies the note as it stands (_turn_off_rescue_copy).
            self._held_text_rescue = None

        rows = (self.rec_interval_row, self.rec_weekday_row, self.rec_monthday_row,
                self.rec_policy_row, self.rec_end_row)
        for widget in rows:
            widget.pack_forget()

        if not freq:
            # Collapse the whole details block so the Note body sits right
            # under Repeat with no reserved gap.
            self.rec_details.pack_forget()
            self.rec_summary_lbl.config(text="")
            return
        if self._day_mode():
            # One day of a series shows its repeat as words, not as boxes to
            # change: the repeat is the whole series' (_show_day_mode).
            self.rec_details.pack_forget()
            return

        # Show the details block, positioned just above the Note body section
        # (where the Tags section used to sit, before it was removed).
        if self.body_header.winfo_manager():
            self.rec_details.pack(fill="x", padx=30, pady=(0, 4),
                                  before=self.body_header)
        else:
            self.rec_details.pack(fill="x", padx=30, pady=(0, 4))

        self.rec_interval_row.pack(fill="x", pady=(0, 6))
        self.rec_unit_lbl.config(
            text={"daily": "day(s)", "weekly": "week(s)",
                  "monthly": "month(s)", "yearly": "year(s)"}[freq]
        )

        if freq == "weekly":
            self.rec_weekday_row.pack(fill="x", pady=(0, 6))
        elif freq == "monthly":
            self.rec_monthday_row.pack(fill="x", pady=(0, 6))
            self.rec_policy_row.pack(fill="x", pady=(0, 6))
        elif freq == "yearly":
            self.rec_policy_row.pack(fill="x", pady=(0, 6))

        self.rec_end_row.pack(fill="x", pady=(0, 12))
        self.update_recurrence_summary()

    def read_recurrence_from_ui(self):
        """Turn the widgets into a rule dict. Invalid entries fall back to
        sane defaults rather than blocking the save."""
        freq = self.selected_freq_key()
        if not freq:
            return normalize_recurrence({})

        try:
            interval = max(1, int(self.rec_interval_var.get().strip()))
        except ValueError:
            interval = 1

        weekdays = [i for i, on in enumerate(self.rec_weekday_state) if on] if freq == "weekly" else []

        month_days = []
        if freq == "monthly":
            for chunk in self.rec_monthdays_var.get().replace(";", ",").split(","):
                chunk = chunk.strip()
                # _is_month_day's isdecimal(): "3²" passed isdigit() and
                # crashed int() on every read of the rule, saves included.
                if _is_month_day(chunk):
                    month_days.append(int(chunk))

        policy = "clamp" if self.rec_policy_var.get() == "Use the last day" else "skip"

        end, count = "", 0
        mode = self.rec_end_mode_var.get()
        if mode == "on":
            end = self.rec_end_date_var.get().strip()
        elif mode == "after":
            try:
                count = max(1, int(self.rec_count_var.get().strip()))
            except ValueError:
                count = 1

        return normalize_recurrence({
            "freq": freq, "interval": interval, "weekdays": weekdays,
            "month_days": month_days, "month_day_policy": policy,
            "end": end, "count": count,
        })

    def write_recurrence_to_ui(self, rec):
        rec = normalize_recurrence(rec)
        self.rec_freq_var.set(FREQ_LABELS[rec["freq"]])
        self.rec_interval_var.set(str(rec["interval"]))
        self.rec_weekday_state = [i in rec["weekdays"] for i in range(7)]
        self.rec_monthdays_var.set(", ".join(str(d) for d in rec["month_days"]))
        self.rec_policy_var.set("Use the last day" if rec["month_day_policy"] == "clamp" else "Skip that month")

        if rec["count"]:
            self.rec_end_mode_var.set("after")
            self.rec_count_var.set(str(rec["count"]))
            self.rec_end_date_var.set("")
        elif rec["end"]:
            self.rec_end_mode_var.set("on")
            self.rec_end_date_var.set(show_date(rec["end"]))
        else:
            self.rec_end_mode_var.set("never")
            self.rec_end_date_var.set("")

        self.refresh_weekday_buttons()
        self.on_end_mode_changed()
        self.on_recurrence_changed()

    def update_recurrence_summary(self):
        rec = self.read_recurrence_from_ui()
        if not rec["freq"]:
            self.rec_summary_lbl.config(text="")
            self._schedule_autosave(skip_word_count=True)
            return
        problems = self._unreadable_repeat_fields(rec["freq"])
        anchor = self._typed_date()
        kept_date = ""
        kept_repeat = True
        if problems or not read_date(anchor):
            # What the save would keep: read from the boxes, unreadable ones
            # previewed a rule neither typed nor stored.
            kept_date, kept, _left_out = self._date_and_repeat_to_store()
            # With no start date to hang it on, the save keeps no repeat.
            kept_repeat = bool(kept["freq"])
            if problems and kept_repeat:
                rec = kept
        # The boxes read with one not understood describe a rule neither
        # typed nor stored: with nothing kept either, no rule is shown.
        preview = ("" if problems and not kept_repeat
                   else describe_recurrence({"recurrence": rec}))
        unread = [{"end": "the end date “%s”",
                   "every": "“Every %s”",
                   "after": "“After %s times”",
                   "days": "day(s) “%s”"}[field] % _truncate(typed, 16)
                  for field, typed in problems]
        warnings = []
        if not read_date(anchor):
            if not parse_date(kept_date or ""):
                if anchor:
                    # Typed, but not as a date: named, as the save names it.
                    unread.insert(0, "the date “%s”" % _truncate(anchor, 16))
                warnings.append("needs a start date, so the repeat is not "
                                "saved")
            elif anchor:
                # The series keeps the start it has; "needs a start date"
                # said it had none.
                unread.insert(0, "the date “%s”" % _truncate(anchor, 16))
            else:
                # Emptied, most often on the way to a new date: the save
                # keeps the start, as its own words say.
                warnings.append("needs a start date, so it still starts %s"
                                % show_date(kept_date))
        if unread:
            # One warning, however many boxes it names: one per box ran
            # past the end of the row.
            warnings.append(("Not understood, so kept as saved: "
                             if kept_repeat else "Not understood: ")
                            + ", ".join(unread))
        preview = "   ".join(([preview] if preview else [])
                             + ["⚠ " + w for w in warnings])
        self.rec_summary_lbl.config(text=preview)
        # Every repeat change passes here, so here it autosaves -- without the
        # word count: none changes the body, and each date key read it twice.
        self._schedule_autosave(skip_word_count=True)

    # ---------- Occurrence scope prompt ----------
    def ask_occurrence_scope(self, action_word, occurrence_date):
        """This day or the series? Returns 'occurrence', 'series' or None, in
        the themed dialog. Asked by Delete alone -- it destroys; a day saves
        to itself unasked (save_current_note). Worded as the day strip is."""
        return self._themed_dialog(
            f"{action_word} repeating note",
            f"This note repeats. What should '{action_word}' apply to?\n"
            f"The day: {show_date(occurrence_date)}",
            kind="question",
            buttons=[("Cancel", None), ("The whole series", "series"),
                     ("Only this day", "occurrence")],
            # A delete: Enter and Space keep everything.
            default="Cancel",
        )

    def _reset_text_undo(self):
        """Clear undo history on both editors — called after loading a note so
        Ctrl+Z can't undo back into a previous note's content. The body's
        formatting journal goes with it (see _body_undo_redo): it is only
        ever read beside the stack it was written next to."""
        for w in (getattr(self, "body_text", None), self.comments_text):
            if w is not None:
                try:
                    w.edit_reset()
                except tk.TclError:
                    pass
        self._fmt_undo, self._fmt_redo = [], []
        self._styled_delete_run = None
        self._fmt_last_state = None
        # A line the drawing put under the last table is part of the note as
        # loaded now: there is no step left that could replay around it.
        self._undo_tail = None

    # The formatting journal's reach: a step costs about what it changed
    # (_fmt_state shares the rest), and past it Ctrl+Z walks Tk's stack.
    _FMT_JOURNAL_DEPTH = 100

    def _trim_fmt_journal(self, journal):
        """Keep *journal* to _FMT_JOURNAL_DEPTH full steps. A text step past
        it stays as a stub (its signatures, and whether recorded with the
        grids down) -- dropped, it replayed as typing, a column off -- and
        stubs are uncapped, as Tk's stack is. A formatting step past it goes.
        """
        full = [i for i, s in enumerate(journal) if not s.get("stub")]
        over = len(full) - self._FMT_JOURNAL_DEPTH
        if over > 0:
            for i in full[:over]:
                s = journal[i]
                journal[i] = self._fmt_stub(s) if s["text"] else None
            journal[:] = [s for s in journal if s is not None]

    @staticmethod
    def _fmt_stub(step):
        """A text step of the journal kept as a stub: its text's signature
        on each side and whether it was recorded with the grids down --
        what Ctrl+Z and Ctrl+Y need to replay it as Tk recorded it -- and
        no formatting to lay back."""
        return {"text": True, "stub": True,
                "grids_down": bool(step.get("grids_down")),
                "before": (step["before"][0],), "after": (step["after"][0],)}

    def _fmt_state(self):
        """The body as undo must know it: the text's signature, the windows'
        places, every tag's ranges -- what Tk's stack never records. One
        line.col string per tag (5.7 ms, not 64, at 8,000 styled words), an
        unchanged one shared with the last snapshot: full copies grew the app
        60 MB over 100 cell edits."""
        b = self.body_text
        text = b.get("1.0", "end-1c")
        sig = (len(text), hash(text))
        if self._undo_tail_held():
            # The line the drawing put under the last table, not changed
            # since: not on Tk's stack, so not counted (see
            # _add_line_under_last_table).
            sig = self._undo_tail
            text = text[:-1]
        # The text this state names, for a side counted with line breaks
        # settled at its end (_undo_sig_is).
        self._fmt_last_text = text
        tags = sorted(t for t in b.tag_names() if _fmt_journal_tag(t))
        if not getattr(self, "_fmt_ranges_proc", False):
            b.tk.eval(_FMT_RANGES_TCL)
            self._fmt_ranges_proc = True
        lines = str(b.tk.call("::noteorg_fmt_ranges", b._w,
                              tuple(tags))).split("\n")
        state = (sig, tuple(lines[0].split()),
                 tuple((t, s) for t, s in zip(tags, lines[1:]) if s))
        last = getattr(self, "_fmt_last_state", None)
        if last is not None:
            if last == state:
                return last
            old = dict(last[2])
            state = (state[0], state[1],
                     tuple((t, old[t] if old.get(t) == s else s)
                           for t, s in state[2]))
        self._fmt_last_state = state
        return state

    def _fmt_restore(self, state, current=None):
        """Lay a snapshot's formatting back on its text (the caller matched
        the signature): tags only, and only the ranges that differ -- all of
        them took seconds for one bold. Ranges move first where the windows
        moved (_fmt_move_ranges). Returns the (start, end) pairs touched."""
        if current is None:
            current = self._fmt_state()
        _sig, windows, ranges = state
        if current[1:] == (windows, ranges):
            return []
        want = dict(ranges)
        if windows != current[1]:
            want = {t: _fmt_move_ranges(s, windows, current[1])
                    for t, s in want.items()}
        have = dict(current[2])
        b = self.body_text
        touched = []
        for tag in set(want) | set(have):
            wanted, held = want.get(tag, ""), have.get(tag, "")
            if wanted == held:
                continue
            wanted, held = _fmt_pairs(wanted), _fmt_pairs(held)
            drop = [i for pair in held - wanted for i in pair]
            put = [i for pair in wanted - held for i in pair]
            if drop:
                b.tk.call(b._w, "tag", "remove", tag, *drop)
            if put:
                b.tk.call(b._w, "tag", "add", tag, *put)
            touched.extend(held ^ wanted)
        return touched

    def _can_edit_undo(self, widget):
        try:
            return bool(widget.edit("canundo"))
        except tk.TclError:
            return False

    def _can_edit_redo(self, widget):
        try:
            return bool(widget.edit("canredo"))
        except tk.TclError:
            return False

    def _undo_atom_begin(self):
        """Open one undo unit on the body (see the _undo_atom decorator).
        Re-entrant: nested opens keep the outermost unit. The outermost
        open also notes the body's formatting, so the unit's Ctrl+Z can
        put back what Tk's text-only stack cannot (see _body_undo_redo)."""
        depth = getattr(self, "_undo_atom_depth", 0)
        # A tags-only open (the decorator's flag) is for this call alone.
        tags_only = getattr(self, "_undo_atom_tags_only", False)
        self._undo_atom_tags_only = False
        if depth == 0:
            # A run of Tk's own deletes ends where an operation of the
            # app's begins, as Tk's own unit does at the separator below.
            self._close_styled_delete_run()
        self._undo_atom_depth = depth + 1
        if not hasattr(self, "body_text"):
            return
        if depth == 0:
            # Recorded with the tables drawn until it takes them down
            # (_undo_atom_grids_coming_down); with none drawn, down from the
            # start -- a table drawn at its end cost Ctrl+Z letters.
            self._atom_part_grids_down = not any(
                self._grid_first_line(info) is not None
                for info in getattr(self, "_table_grids", []))
            # Whether it has edited a drawn table's first line with the
            # grid's window there (see _mark_unit_window_free).
            self._atom_edited_with_window = False
            self._undo_atom_grouping = False
            try:
                self.body_text.edit_separator()
            except tk.TclError:
                pass
            self._fmt_atom_before = None
            try:
                # Only while the body records undo: an edit made inside
                # _undo_hidden leaves no step on Tk's stack to pair with.
                if self.body_text.tk.getboolean(
                        self.body_text.cget("undo")):
                    self._fmt_atom_before = self._fmt_state()
            except (tk.TclError, ValueError):
                pass
        # Grouping costs a configure (the whole note re-laid out): once per
        # unit, and a tags-only unit only when text opens inside it.
        if not tags_only and not getattr(self, "_undo_atom_grouping", False):
            try:
                self.body_text.configure(autoseparators=False)
                self._undo_atom_grouping = True
            except tk.TclError:
                pass

    def _undo_atom_end(self):
        depth = max(0, getattr(self, "_undo_atom_depth", 1) - 1)
        self._undo_atom_depth = depth
        if depth == 0 and hasattr(self, "body_text"):
            try:
                if getattr(self, "_undo_atom_grouping", False):
                    self.body_text.configure(autoseparators=True)
                self.body_text.edit_separator()
            except tk.TclError:
                pass
            self._undo_atom_grouping = False
            if getattr(self, "_fmt_atom_before", None) is None:
                return
            try:
                after = self._fmt_state()
            except (tk.TclError, ValueError):
                self._fmt_atom_before = None
                return
            # Read after the snapshot: a line the drawing held under the last
            # table, which this unit's edits made the note's, was counted
            # into it just now (_settle_undo_tail).
            before = self._fmt_atom_before
            self._fmt_atom_before = None
            if after == before:
                return
            # A unit that changed the text is a step on Tk's stack as well;
            # one that changed only formatting is a step on this one alone.
            self._push_atom_step(before, after)

    def _push_atom_step(self, before, after):
        """One journal step for (the part of) a unit from *before* to
        *after*, marked with whether recorded with the tables down. A part
        where only the tables moved is none (Ctrl+Z changed nothing on it):
        compared without the windows (_fmt_window_free), as a moved centred
        line still read as a change, each costing one of the 100."""
        journal = getattr(self, "_fmt_undo", None)
        if journal is None:
            journal = self._fmt_undo = []
        text = after[0] != before[0]
        if (not text and before[1] != after[1]
                and len(before) > 2 and len(after) > 2
                and _fmt_window_free(before) == _fmt_window_free(after)):
            return
        journal.append({"text": text,
                        "before": before, "after": after,
                        "grids_down": getattr(self, "_atom_part_grids_down", False)})
        self._trim_fmt_journal(journal)
        # A text step empties Tk's redo, so this one; a formatting-only step
        # leaves Tk's, so the redo stays as stubs -- emptied, Ctrl+Y replayed
        # a header cell's edit as typing, a column off.
        self._fmt_redo = ([] if text else
                          [self._fmt_stub(s)
                           for s in getattr(self, "_fmt_redo", None) or []
                           if s["text"]])

    def _undo_atom_grids_coming_down(self):
        """An open unit is about to take the drawn tables down. A grid's
        window is column 0 of its first line, so an edit recorded without it
        replayed a column off ("| Ite  | Qt  |"); _body_undo_redo takes them
        down first for a step marked so. What the unit did with them drawn
        becomes its own step, ended by a separator."""
        if getattr(self, "_fmt_atom_before", None) is not None:
            try:
                now = self._fmt_state()
            except (tk.TclError, ValueError):
                now = None
            # Read after the snapshot counts the drawing's held line
            # (_settle_undo_tail); before, Ctrl+Z matched nothing.
            before = self._fmt_atom_before
            if now is not None and now[0] != before[0]:
                self._push_atom_step(before, now)
                try:
                    self.body_text.edit_separator()
                except tk.TclError:
                    pass
                self._fmt_atom_before = now
        self._atom_part_grids_down = True
        self._atom_edited_with_window = False

    def _mark_unit_window_free(self):
        """The open unit is about to edit a table not drawn (typed, tidied):
        recorded with no window, replayed with one, the header lost a letter
        -- so it is marked grids-down. A unit that edited a drawn first line
        is split, as _undo_atom_grids_coming_down does; else marked whole."""
        if getattr(self, "_undo_atom_depth", 0) <= 0:
            return
        if getattr(self, "_atom_part_grids_down", False):
            return
        if not getattr(self, "_atom_edited_with_window", False):
            self._atom_part_grids_down = True
            return
        self._undo_atom_grids_coming_down()

    def _note_edit_with_window(self):
        """An edit of a drawn table's first line, its grid's window there,
        inside an open unit (see _mark_unit_window_free). A part of the unit
        marked as recorded with the grids down ends here: what it did so far
        becomes a step of its own, and what follows is recorded, and
        replayed, with the grids up."""
        if getattr(self, "_undo_atom_depth", 0) <= 0:
            return
        if getattr(self, "_atom_part_grids_down", False):
            if getattr(self, "_fmt_atom_before", None) is not None:
                try:
                    now = self._fmt_state()
                except (tk.TclError, ValueError):
                    now = None
                # Read after the snapshot, which counts a line the drawing
                # held into it (_settle_undo_tail).
                before = self._fmt_atom_before
                if now is not None and now[0] != before[0]:
                    self._push_atom_step(before, now)
                    try:
                        self.body_text.edit_separator()
                    except tk.TclError:
                        pass
                    self._fmt_atom_before = now
            self._atom_part_grids_down = False
        self._atom_edited_with_window = True

    # The bindtag put first on the note body, so it sees every key and
    # every Cut, Clear and Paste before the body's own bindings do.
    _STYLED_DELETE_TAG = "NoteBodyStyledDelete"

    def _note_styled_delete(self, event, virtual=False):
        """Note the formatting before Tk's own deletes (Delete, BackSpace,
        typing over, Cut), which Ctrl+Z gave back plain: a step of its own,
        journalled at the next other key (_close_styled_delete_run). A run
        of BackSpaces stays ONE step, as Tk merges them; unformatted text is
        left to Tk.
        """
        b = self.body_text
        if (not virtual and getattr(event, "keysym", "") == "Insert"
                and not (getattr(event, "state", 0) & 0x5)):
            # Tk's Insert pastes the selection over itself, less a table's
            # hidden rows: over a table it does nothing.
            try:
                if (_selection_holds_caret(b)
                        and b.tag_nextrange(self.TABLE_HIDE_TAG,
                                            "sel.first", "sel.last")):
                    return "break"
            except tk.TclError:
                pass
        try:
            if not b.tk.getboolean(b.cget("undo")):
                return None
        except (tk.TclError, ValueError):
            return None
        doomed, kind = self._native_delete_range(event, virtual)
        styled = (doomed is not None
                  and self._range_carries_formatting(*doomed))
        run = getattr(self, "_styled_delete_run", None)
        if run is not None:
            if (styled and kind in ("back", "del") and kind == run["kind"]
                    and b.compare("insert", "==", run["at"])):
                run["at"] = doomed[0]
                return None
            self._close_styled_delete_run()
        if styled:
            try:
                b.edit_separator()
                self._styled_delete_run = {"before": self._fmt_state(),
                                           "kind": kind, "at": doomed[0]}
            except (tk.TclError, ValueError):
                self._styled_delete_run = None
        return None

    def _native_delete_range(self, event, virtual=False):
        """(start, end) of what Tk's own binding for `event` will delete
        from the body, and which kind of delete it is -- or (None, None).
        Selected cells are the app's own path (_on_body_delete_key).
        *virtual*: the event is Cut, Clear or Paste, by whatever key."""
        b = self.body_text
        if getattr(self, "_grid_sel", None) is not None:
            return None, None
        try:
            sel = (b.index("sel.first"), b.index("sel.last"))
        except tk.TclError:
            sel = None
        if virtual or getattr(event.type, "name", str(event.type)) == "VirtualEvent":
            return (sel, "replace") if sel else (None, None)
        keysym = getattr(event, "keysym", "")
        state = getattr(event, "state", 0)
        if not isinstance(state, int):
            state = 0
        control, alt = bool(state & 0x4), bool(state & 0x20000)
        try:
            if control and not alt and keysym in ("h", "k", "t"):
                # Tk's Ctrl+H, Ctrl+K and Ctrl+T ignore a selection, and
                # their bold came back plain.
                return self._tk_control_delete_range(keysym)
            if keysym == "BackSpace":
                if sel:
                    return sel, "back"
                if b.compare("insert", "==", "1.0"):
                    return None, None
                return (b.index("insert-1c"), b.index("insert")), "back"
            if keysym == "Delete":
                if sel:
                    return sel, "del"
                if b.compare("insert", ">=", "end-1c"):
                    return None, None
                return (b.index("insert"), b.index("insert+1c")), "del"
        except tk.TclError:
            return None, None
        if not sel:
            return None, None
        if keysym == "Insert" and not (state & 0x1) and not control:
            # Tk's own Insert pastes the selection, deleting it first when
            # the caret is in it (tk::TextInsert): a replace, as typing over
            # it is. Its style came back plain, and Ctrl+Z left it so.
            if _selection_holds_caret(b):
                return sel, "replace"
            return None, None
        char = getattr(event, "char", "") or ""
        # Control+Alt is AltGr on Windows, which types a character.
        typed = (char.isprintable() and char != ""
                 and (not control or alt))
        if typed or keysym in ("Return", "KP_Enter", "Tab"):
            return sel, "replace"
        return None, None

    def _tk_control_delete_range(self, keysym):
        """What Tk's own Ctrl+H, Ctrl+K or Ctrl+T will take from the body
        (text.tcl's bindings, on every platform), and which kind of delete
        it is: a run of Ctrl+H is a run of BackSpaces, of Ctrl+K a run of
        Deletes, and a swap replaces the two characters it moves."""
        b = self.body_text
        if keysym == "h":
            if b.compare("insert", "==", "1.0"):
                return None, None
            return (b.index("insert-1c"), b.index("insert")), "back"
        if keysym == "k":
            if b.compare("insert", "==", "insert lineend"):
                if b.compare("insert", ">=", "end-1c"):
                    return None, None
                return (b.index("insert"), b.index("insert+1c")), "del"
            return (b.index("insert"), b.index("insert lineend")), "del"
        pos = ("insert" if b.compare("insert", "==", "insert lineend")
               else "insert+1c")
        if b.compare(f"{pos}-1c", "==", "1.0"):
            return None, None
        return (b.index(f"{pos}-2c"), b.index(pos)), "replace"

    def _range_carries_formatting(self, start, end):
        """Does any character formatting or paragraph formatting touch the
        text from `start` to `end`? The tags at its first character, and
        any that begin inside it."""
        b = self.body_text
        try:
            if any(_fmt_journal_tag(t) for t in b.tag_names(start)):
                return True
            # One character -- every BackSpace and Delete -- is answered by
            # its own tags; only a selection pays for a look at them all.
            if b.compare(end, "<=", f"{start}+1c"):
                return False
            return any(b.tag_nextrange(t, start, end)
                       for t in b.tag_names() if _fmt_journal_tag(t))
        except tk.TclError:
            return False

    def _close_styled_delete_run(self):
        """Turn an open run of Tk's own deletes into a journal step: the
        formatting before it and after it, with a separator after it on
        Tk's stack too, so the step and Tk's unit end in the same place.
        A run that deleted nothing (a guard broke the key) leaves no step."""
        run = getattr(self, "_styled_delete_run", None)
        if run is None or not hasattr(self, "body_text"):
            self._styled_delete_run = None
            return
        try:
            self.body_text.edit_separator()
            # Taken with the run still open: its deletes may have made a
            # line the drawing held the note's, counted into the run's first
            # snapshot as into every other (_settle_undo_tail).
            after = self._fmt_state()
        except (tk.TclError, ValueError):
            self._styled_delete_run = None
            return
        self._styled_delete_run = None
        # Nothing changed: no step. The same words put back bare (a paste of
        # themselves) changed formatting, and are one.
        if after == run["before"]:
            return
        journal = getattr(self, "_fmt_undo", None)
        if journal is None:
            journal = self._fmt_undo = []
        # Tk's own deletes, like every step of Tk's: never on a drawn table's
        # line, so replayed with the tables down (see _body_undo_redo).
        journal.append({"text": True, "before": run["before"], "after": after,
                        "grids_down": True})
        self._trim_fmt_journal(journal)
        self._fmt_redo = []

    def _body_undo_redo(self, action, event=None):
        """Ctrl+Z / Ctrl+Y on the body (*event*, the key's, if one): Tk walks
        its stack of TEXT, then the grids are redrawn. A journal of each
        _undo_atom's formatting takes back a formatting-only step itself and
        lays a text step's once Tk lands on its text -- matched on the text,
        never a count. Typing is noted on the way back, for Ctrl+Y.
        """
        b = self.body_text
        # The caret undo moves is not "leaving" a table: tidied as a new
        # edit (_align_table_on_leaving), it wiped Ctrl+Y's history.
        self._last_caret_line = None
        # A still-open cell editor holds uncommitted text; commit it so
        # the undo works against what the note actually says.
        if getattr(self, "_cell_editor", None):
            self._commit_cell_editor()
        # A run of Tk's own deletes still open is a step now, so this
        # press can take it back with its formatting.
        self._close_styled_delete_run()
        undo = action == "undo"
        if getattr(self, "_fmt_undo", None) is None:
            self._fmt_undo = []
        if getattr(self, "_fmt_redo", None) is None:
            self._fmt_redo = []
        mine, other = ((self._fmt_undo, self._fmt_redo) if undo
                       else (self._fmt_redo, self._fmt_undo))
        now = self._fmt_state()
        now_text = self._fmt_last_text
        top = mine[-1] if mine else None
        redraw = True
        if (top is not None and not top["text"]
                and self._undo_sig_is(top["before"][0], now[0], now_text)):
            # A formatting-only step, taken on exactly this text: it is
            # this whole key press, and Tk's stack is not touched.
            mine.pop()
            other.append(top)
            target = top["before"] if undo else top["after"]
            touched = self._fmt_restore(target, now)
            # The drawn tables only need drawing again when the step
            # restyled one of their cells (or the windows had moved): a
            # bold taken back in the prose redrew every table in the note.
            redraw = target[1] != now[1]
            for info in getattr(self, "_table_grids", []):
                first = self._grid_first_line(info)
                last = None if first is None else first + info["nrows"] - 1
                if redraw or first is None or any(
                        int(lo.split(".")[0]) <= last
                        and int(hi.split(".")[0]) >= first
                        for lo, hi in touched):
                    redraw = True
                    break
        else:
            can = (self._can_edit_undo if undo else self._can_edit_redo)(b)
            if not can:
                # Nothing of its own to take back: Ctrl+Z is the toast's
                # Undo, when it offers one. A delete leaves a blank note
                # open, and the press there did nothing at all.
                return (self._toast_undo_key(event) if undo and event is not None
                        else None) or "break"
            came, went = ("after", "before") if undo else ("before", "after")
            # A step is replayed as recorded: tables down if so
            # (_undo_atom_grids_coming_down), redrawn below.
            pending = next((s for s in reversed(mine) if s["text"]
                            and self._undo_sig_is(s[came][0], now[0],
                                                  now_text)), None)
            # Typing never touches a drawn table, but a table typed then
            # drawn SINCE replayed a column off: such a step is replayed
            # with the tables down.
            if pending is None or pending.get("grids_down"):
                self._teardown_table_grids()
            # Tk replays on the text it recorded: a line the drawing put under
            # the last table since the text last changed goes first, and the
            # redraw below puts it back if it is still needed.
            self._drop_undo_tail()
            try:
                (b.edit_undo if undo else b.edit_redo)()
            except tk.TclError:
                return "break"
            text = b.get("1.0", "end-1c")
            landed = (len(text), hash(text))
            step = None
            for i in range(len(mine) - 1, -1, -1):
                if (mine[i]["text"]
                        and self._undo_sig_is(mine[i][came][0], now[0],
                                              now_text)
                        and self._undo_sig_is(mine[i][went][0], landed,
                                              text)):
                    step = mine.pop(i)
                    break
            if step is None:
                # Replayed with the tables down (above), and so replayed
                # back the other way.
                step = {"text": True, came: now, went: self._fmt_state(),
                        "grids_down": pending is None or bool(
                            pending.get("grids_down"))}
            else:
                # The side left behind is noted as it really was, for the
                # press that comes back to it.
                step[came] = now
                # A stub's side is its signature alone (see
                # _trim_fmt_journal): no formatting to lay back.
                if len(step[went]) > 1:
                    self._fmt_restore(step[went])
            other.append(step)
            self._trim_fmt_journal(other)
        self._body_follow_caret = True
        self._resync_list_tags()
        grids = getattr(self, "_table_grids", None)
        if ((grids and redraw) or (not grids and core_tables.find_blocks(
                b.get("1.0", "end-1c")))):
            self._render_table_grids()
        self._refresh_format_buttons()
        self._schedule_autosave()
        return "break"

    def _bind_text_wheel(self, text_widget, fallback_canvas=None):
        """The wheel over a text box scrolls its content when it overflows
        (in pixels, _text_wheel_scroll), else the editor page; "break" both
        ways, or Tk's own Text handling swallows it."""
        text_widget.bind(
            "<MouseWheel>",
            lambda e: self._text_wheel_scroll(text_widget, e,
                                              fallback_canvas))

    def _bind_mousewheel_recursive(self, widget, canvas, skip=None):
        # `skip` is a set of widgets that manage their own wheel scrolling
        # (e.g. the Note/Comments text boxes) — don't override them.
        skip_set = skip if isinstance(skip, (set, list, tuple)) else ()
        if widget in skip_set:
            return

        def _on_wheel(event):
            # Don't scroll if the content already fits — otherwise the wheel
            # can drag short content down and open a gap at the top.
            try:
                first, last = canvas.yview()
                if first <= 0.0 and last >= 1.0:
                    return "break"
            except (tk.TclError, ValueError):
                pass
            # A deliberate scroll beats a rebuild's still-pending restore,
            # and the list hears that the person scrolled it: the keyboard
            # coming back then starts in view, not back at the ring.
            if canvas is self.canvas:
                self._list_scrolled_by_hand()
            canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")
            return "break"

        widget.bind("<MouseWheel>", _on_wheel)
        for child in widget.winfo_children():
            self._bind_mousewheel_recursive(child, canvas, skip=skip)

    def add_placeholder(self, entry, placeholder):
        entry.insert(0, placeholder)
        entry.config(fg=self.colors["subtext"])
        self._placeholders.append((entry, placeholder))

        def clear_if_placeholder():
            if entry.get() == placeholder:
                entry.delete(0, "end")
                entry.config(fg=self.colors["text"])

        # Kept on the field, and gone with it, for what puts text in with
        # no key and no paste: the emoji picker took the focus away, the
        # hint came back, and the emoji landed after it.
        entry.clear_placeholder = clear_if_placeholder

        def on_focus_in(e):
            clear_if_placeholder()

        def on_key(e):
            # Clear BEFORE the keystroke lands — <FocusIn> alone can lose this
            # race if the user starts typing immediately after clicking in.
            clear_if_placeholder()

        def on_paste(e):
            # A paste is no keystroke (the menu's, or Ctrl+V outranked by a
            # field's own <<Paste>>), and landed glued to the placeholder:
            # cleared here, for every placeholder field.
            clear_if_placeholder()

        def on_paste_selection(e):
            # A middle-click pastes as well, unless the button was dragged.
            if self.tk.eval("expr {[info exists ::tk::Priv(mouseMoved)]"
                            " && $::tk::Priv(mouseMoved)}") != "1":
                clear_if_placeholder()

        def on_focus_out(e):
            if not entry.get():
                entry.insert(0, placeholder)
                entry.config(fg=self.colors["subtext"])

        entry.bind("<FocusIn>", on_focus_in)
        entry.bind("<KeyPress>", on_key)
        # add="+" both ways: this must not displace a field's own <<Paste>>
        # handler, and a field's own handler must not displace this. The
        # title binds one at its call site and is bound the same way.
        entry.bind("<<Paste>>", on_paste, add="+")
        entry.bind("<<PasteSelection>>", on_paste_selection, add="+")
        entry.bind("<FocusOut>", on_focus_out)

    def _series_warning(self, notes):
        """One sentence saying how many of `notes` are whole repeating
        series, or "" when none are: a series counts as ONE note and takes
        every day with it, and no route acting on a selection said so
        (field report). Written once, for all four.
        """
        count = sum(1 for n in notes if isinstance(n, dict) and is_recurring(n))
        if not count:
            return ""
        if count == 1:
            if len(notes) == 1:
                return ("\n\nThis is a repeating series — every occurrence "
                        "goes with it.")
            return ("\n\n1 of them is a repeating series — every occurrence "
                    "goes with it.")
        return (f"\n\n{count} of them are repeating series — every occurrence "
                "goes with them.")

    def _category_override_warning(self, notes):
        """Name the notes a category change will not reach all the way into:
        a series' days filed by hand keep their own (OVERRIDABLE_FIELDS), as
        they should -- said out loud, as the Trash's question names files.
        """
        count = 0
        for note in notes:
            if not isinstance(note, dict):
                continue
            patches = note.get("overrides") or {}
            if not isinstance(patches, dict):
                continue
            if any(isinstance(p, dict) and p.get("category")
                   for p in patches.values()):
                count += 1
        if not count:
            return ""
        if count == 1:
            return ("\n\nOne of them has a day with its own category, and "
                    "that day keeps it.")
        return (f"\n\n{count} of them have days with their own category, and "
                "those days keep them.")

    def _bulk_move_to_trash(self):
        if not self.selected_note_ids:
            self.show_info("Nothing selected", "Tick one or more notes first.")
            return
        # Saved first, as a single delete is: the open note's typing belongs
        # in its Trash copy. Going back to a date stops here; a repeat's
        # turn-off waits for the question (_context_delete_note).
        if self._flush_autosave(
                leaving=self.selected_note_id in self.selected_note_ids,
                hold_repeat_off=True) is False:
            return
        to_trash = [n for n in self.notes if n["id"] in self.selected_note_ids]
        # Counted from the notes that will move, not from the ticks: the
        # two agree now that a deleted note leaves the selection, and the
        # question should never name more notes than it moves.
        count = len(to_trash)
        attachment_count = sum(len(n.get("attachments") or []) for n in to_trash)
        warning = self._series_warning(to_trash)
        if attachment_count:
            plural = "s" if attachment_count != 1 else ""
            warning += f"\n\n{attachment_count} attached file{plural} will go to trash with them."
        noun = "note" if count == 1 else "notes"
        if not self.ask_yes_no(
            "Move to trash",
            f"Move {count} selected {noun} to the trash? "
            f"You can restore {'it' if count == 1 else 'them'}"
            f"{trash_window_words('within')}.{warning}",
            # Enter answers a question now, and a reflexive Enter must not
            # be the one that deletes.
            icon="question", default="no"
        ):
            return
        # Yes acts on the notes the question named: ticks read after it lost
        # a note with no Trash copy. One gone meanwhile is not trashed twice.
        named = {n["id"] for n in to_trash}
        to_trash = [n for n in self.notes if n["id"] in named]
        count = len(to_trash)
        moved = self._move_notes_to_trash(to_trash)
        if moved is None:
            return   # trash.json refused them: they stay, and that was said
        marks = [(e.get("id"), e.get("deleted_at")) for e in moved]
        self.notes = [n for n in self.notes if n["id"] not in named]
        self.save_notes()
        # An open note trashed leaves the editor and tabs pointing at nothing
        # ("Note missing" at the next save): cleaned as delete_current_note.
        self.open_tabs = [t for t in self.open_tabs
                          if t["state"]["selected_note_id"] not in named]
        if not self.open_tabs:
            self.active_tab_index = None
            self.new_note()
        # Otherwise the editor holds a note that was not trashed, and it
        # stays as it is -- see _delete_note for what "switching" to it
        # from its stored copy used to cost.
        self._sync_editor_snapshot()
        self._exit_selection_mode_after_bulk_action()
        self.render_calendar()
        self.set_status(f"Moved {count} note(s) to trash")
        # The bulk route is the easiest one to regret: a tick box, a
        # confirm, and a list that was filtered by whatever was typed in
        # the search box at the time.
        self._show_toast(
            f"Moved {count} {'note' if count == 1 else 'notes'} to Trash",
            action=lambda: self._undo_trash(marks))

    def _bulk_change_category(self):
        if not self.selected_note_ids:
            self.show_info("Nothing selected", "Tick one or more notes first.")
            return
        self._dismiss_mini_popup()
        pop = tk.Toplevel(self)
        self._mini_popup = pop
        pop.wm_overrideredirect(True)
        pop.configure(bg=self.colors["accent"])
        # A pixel less padding all round, which each row's ring takes back.
        frame = tk.Frame(pop, bg=self.colors["card"], padx=3, pady=4)
        frame.pack(padx=1, pady=1)
        tk.Label(frame, text=f"Move {len(self.selected_note_ids)} note(s) to:",
                 bg=self.colors["card"], fg=self.colors["subtext"],
                 font=("Segoe UI", 8, "bold")).pack(anchor="w", padx=7, pady=(4, 2))

        def apply_category(cat):
            # The popup first: never focused, it floated over the question.
            self._dismiss_mini_popup()
            # The editor's dropdown would save the old category back: flushed
            # FIRST, before the question counts categories, then changed, then
            # the editor brought onto the result.
            touched = set(self.selected_note_ids)
            # Leaving only if the note on screen is one of those moving.
            if self._flush_autosave(
                    leaving=self.selected_note_id in touched) is False:
                return  # gone back to fix a date: nothing moves
            to_move = [n for n in self.notes if n["id"] in touched]
            if not to_move:
                # The ticked notes are gone. A dialog naming a count it
                # cannot deliver is worse than saying so plainly.
                self.show_info("Nothing to move", "Those notes are no longer here.")
                return
            count = len(to_move)
            noun = "note" if count == 1 else "notes"
            from_count = len({n.get("category") for n in to_move})
            spread = ("" if from_count < 2
                      else f" They sit in {from_count} different categories today.")
            if not self.ask_yes_no(
                "Change category",
                f"Move {count} selected {noun} to \u201c{cat}\u201d?{spread} "
                f"This replaces the category on "
                f"{'it' if count == 1 else 'each of them'}."
                f"{self._category_override_warning(to_move)}",
                icon="question"
            ):
                return
            # A mark per note: one old category for the batch would undo a
            # mixed selection all into the first.
            marks = [(n["id"], n.get("category"), n.get("updated"),
                      n.get("uid")) for n in to_move]
            stamp = now_stamp()
            for n in to_move:
                n["category"] = cat
                n["updated"] = stamp
            self.save_notes()
            self._editor_follows_external_change(touched)
            self._exit_selection_mode_after_bulk_action()
            # The calendar draws a note with no colour of its own in its
            # category's -- its dots, and an open day's stripes.
            self.render_calendar()
            self.set_status(f"Moved {count} note(s) to \u201c{cat}\u201d")
            # A way back: it had neither question nor Undo.
            self._offer_category_undo({"marks": marks, "applied": cat})

        for cat in CATEGORY_COLORS.keys():
            row = tk.Frame(frame, bg=self.colors["card"], cursor="hand2")
            self._ring_round(row, self.colors["card"])
            row.pack(fill="x")
            self._pressable(row, lambda c=cat: apply_category(c), walk=True)
            dot = tk.Canvas(row, width=self.px(10), height=self.px(10),
                            highlightthickness=0, bg=self.colors["card"])
            dot.create_oval(1, 1, 9, 9, fill=CATEGORY_COLORS[cat], outline=CATEGORY_COLORS[cat])
            self._scale_drawing(dot)
            dot.pack(side="left", padx=(8, 6), pady=4)
            lbl = tk.Label(row, text=cat, bg=self.colors["card"], fg=self.colors["text"],
                          font=("Segoe UI", 9), anchor="w")
            lbl.pack(side="left", fill="x", expand=True, padx=(0, 10), pady=4)
            for w in (row, dot, lbl):
                # "break": this destroys the popup the row is in (see
                # _show_inline_rename).
                w.bind("<Button-1>",
                       lambda e, c=cat: (apply_category(c), "break")[1])

        # A way out that says so: every row refiles every ticked note.
        self._bulk_popup_cancel(frame)
        self._place_dropdown_popup(pop, self._bulk_category_btn)

    def _bulk_export(self):
        """Format picker for exporting every ticked note, one file each."""
        if not self.selected_note_ids:
            self.show_info("Nothing selected", "Tick one or more notes first.")
            return
        self._dismiss_mini_popup()
        pop = tk.Toplevel(self)
        self._mini_popup = pop
        pop.wm_overrideredirect(True)
        pop.configure(bg=self.colors["accent"])
        frame = tk.Frame(pop, bg=self.colors["card"], padx=3, pady=4)
        frame.pack(padx=1, pady=1)
        tk.Label(frame,
                 text=f"Export {len(self.selected_note_ids)} note(s) as:",
                 bg=self.colors["card"], fg=self.colors["subtext"],
                 font=("Segoe UI", 8, "bold")).pack(anchor="w", padx=7,
                                                    pady=(4, 2))
        for fmt, fmt_label in (("html", "Web pages (.html)"),
                               ("txt", "Plain text (.txt)")):
            row = tk.Frame(frame, bg=self.colors["card"], cursor="hand2")
            self._ring_round(row, self.colors["card"])
            row.pack(fill="x")
            self._pressable(row, lambda f=fmt: (self._dismiss_mini_popup(),
                                                self._bulk_export_run(f)),
                            walk=True)
            lbl = tk.Label(row, text=fmt_label, bg=self.colors["card"],
                           fg=self.colors["text"], font=("Segoe UI", 9),
                           anchor="w")
            lbl.pack(side="left", fill="x", expand=True, padx=10, pady=4)
            for w in (row, lbl):
                # "break": this destroys the popup the row is in (see
                # _show_inline_rename).
                w.bind("<Button-1>",
                       lambda e, f=fmt: (self._dismiss_mini_popup(),
                                         self._bulk_export_run(f), "break")[2])
        self._bulk_popup_cancel(frame)
        self._place_dropdown_popup(pop, self._bulk_export_btn)

    def _bulk_popup_cancel(self, frame):
        """A worded way out of a bulk popup whose every other row acts, as
        Import and Share have: Escape works too, but is not on the screen.
        """
        tk.Button(frame, text="Cancel", command=self._dismiss_mini_popup,
                  relief="flat", cursor="hand2", bd=0,
                  bg=self.colors["sidebar"], fg=self.colors["text"],
                  font=("Segoe UI", 8)).pack(fill="x", padx=7, pady=(6, 4),
                                             ipady=2)

    def _bulk_export_run(self, fmt):
        """Write every ticked note into a chosen folder, one file per
        note, through the same rendering the single-note export uses.
        Same-title notes get " (2)", " (3)" -- never an overwrite."""
        ext = {"html": ".html", "txt": ".txt"}[fmt]
        folder = self._while_native(lambda: filedialog.askdirectory(
            title=f"Export {len(self.selected_note_ids)} note(s) into…"))
        if not folder:
            return
        written, failed, used = 0, [], set()
        for note in self.notes:
            if note["id"] not in self.selected_note_ids:
                continue
            title = (note.get("title") or "").strip() or "Untitled note"
            safe = export_file_stem(title)
            name, n = safe, 1
            while (name.lower() in used
                   or os.path.exists(os.path.join(folder, name + ext))):
                n += 1
                name = f"{safe} ({n})"
            used.add(name.lower())
            try:
                with open(os.path.join(folder, name + ext), "w",
                          encoding="utf-8") as f:
                    f.write(self._note_export_content(note, fmt, title))
                written += 1
            except (IOError, OSError):
                failed.append(title)
        if failed:
            # Which notes, not only how many: the person has to find them.
            named = "\n".join(
                f"• {HIDDEN_IN_NAMES.sub('', t)[:60]}" for t in failed[:5])
            more = f"\n…and {len(failed) - 5} more" if len(failed) > 5 else ""
            self.show_error(
                "Export incomplete",
                f"{written} note(s) exported, {len(failed)} failed to write:"
                f"\n\n{named}{more}")
        else:
            self._show_toast(f"Exported {written} note(s)")
        self._exit_selection_mode_after_bulk_action()
        if written and not failed and self.ask_yes_no(
                "Open the folder?",
                f"{written} file(s) were saved.\n\nOpen the folder now?",
                icon="question"):
            try:
                os.startfile(folder)
            except OSError:
                self.set_status(f"Saved to {folder}")

    # ---------- Note actions ----------
    # ---------- Editor state snapshot (for multi-note tabs) ----------
    def capture_editor_state(self):
        """Snapshot everything the editor currently holds, so a note tab can be
        set aside and restored later exactly as the user left it — including
        unsaved edits. This is the backbone of having several notes open."""
        return self._capture_and_read()[0]

    def _capture_and_read(self):
        """capture_editor_state's snapshot, and the body's text it was read
        from: a save made right after it, with nothing run in between, works
        from that one read (save_current_note's *body_read*)."""
        # Grid cells buffer their edits in Entry widgets; anything captured
        # here -- autosave, tab switching, the dirty poll -- must see them
        # in the text, or a keystroke still sitting in a cell would be lost.
        self._flush_table_grids()
        title = self.title_entry.get()
        if title == "Note title...":
            title = ""
        date_raw = self._typed_date()
        # The body read once, after the flush; its formatting and lines are
        # worked out from that read rather than asked of Tk line by line.
        text = self.body_text.get("1.0", "end-1c")
        return {
            "selected_note_id": self.selected_note_id,
            "occurrence_date": self.current_occurrence_date,
            "title": title,
            # Canonical, matching what the save stores -- see
            # with_caret_line. Without it, the dirty comparison reads a
            # table-ending note as changed forever.
            "body": with_caret_line(text),
            "formatting": self._extract_formatting(self.body_text, text),
            "paragraphs": self._extract_paragraphs(self.body_text, text),
            "pending_styles": sorted(self._pending_styles),
            "pending_text_color": self._pending_text_color,
            "pending_font_size": self._pending_font_size,
            "pending_font_family": self._pending_font_family,
            "pending_highlight_color": self._pending_highlight_color,
            "comments": self.comments_text.get("1.0", "end-1c"),
            "category": self.category_var.get(),
            "date": date_raw,
            "color": self.current_note_color,
            "attachments": list(self.current_attachments),
            "recurrence": self.read_recurrence_from_ui(),
            "checklist": [dict(it) for it in self._get_checklist()],
        }, text

    def restore_editor_state(self, st):
        """Load a previously captured editor state back into the live editor."""
        self.selected_note_id = st["selected_note_id"]
        self.current_occurrence_date = st.get("occurrence_date")

        self.title_entry.delete(0, "end")
        if st["title"]:
            self._insert_title(st["title"])
            self.title_entry.config(fg=self.colors["text"])
        else:
            self._insert_title("Note title...")
            self.title_entry.config(fg=self.colors["subtext"])

        # Restore this tab's own pending style (if any) before inserting
        # its body — set after the insert instead, a leftover pending style
        # from whatever tab was open a moment ago could tag this one's text.
        self._pending_styles = set(st.get("pending_styles") or [])
        self._pending_text_color = st.get("pending_text_color")
        self._pending_font_size = st.get("pending_font_size")
        self._pending_font_family = st.get("pending_font_family")
        self._pending_highlight_color = st.get("pending_highlight_color")
        self.body_text.delete("1.0", "end")
        self.body_text.insert("1.0", st["body"])
        self._apply_formatting(self.body_text, st.get("formatting", []))
        self._apply_paragraphs(self.body_text, st.get("paragraphs", []))
        self._render_table_grids()
        self.comments_text.delete("1.0", "end")
        self.comments_text.insert("1.0", st["comments"])
        self.category_var.set(st["category"])

        self._show_date_in_field(st["date"])

        self.current_note_color = st["color"]
        self._update_color_swatch()
        self.current_attachments = list(st["attachments"])
        self.refresh_attachments_list()
        self._working_checklist = [dict(it) for it in st.get("checklist", [])]
        if hasattr(self, "_checklist_rows"):
            self._render_checklist_items()
        self._sync_checklist_open_state()
        self._sync_calculator_open_state()

        self.write_recurrence_to_ui(st.get("recurrence") or {})

        self.update_word_count()
        self._refresh_format_buttons()

        self._reset_editor_scroll()
        self._reset_text_undo()
        self._update_restore_button()
        self._find_on_context_switch()
        self._share_code_on_context_switch()
        self._update_occurrence_banner()
        # A tab carries no calendar trip: a stale return made a later Save
        # jump to an unrelated day.
        self._pending_calendar_return = None
        self._update_calendar_return_button()

    def _editor_state_has_content(self, st):
        """The ONE answer to "does the editor hold anything worth keeping?":
        six gates' own field lists lost a comments-only note. The date does
        NOT count (the calendar prefills it, and an abandoned editor saved
        junk); Save adds it, as pressing Save makes a dated reminder meant."""
        recurrence = st.get("recurrence") or {}
        freq = recurrence.get("freq") if isinstance(recurrence, dict) else ""
        return bool((st.get("title") or "").strip()
                    or (st.get("body") or "").strip()
                    or (st.get("comments") or "").strip()
                    or st.get("attachments")
                    or st.get("checklist")
                    or freq)

    def _editor_holds_typing(self):
        """Whether the editor as it is holds anything typed: its content as
        above, or an item waiting in the checklist's Add box, which no
        capture reads. The blank editor's flush asks this, and a template
        about to replace an unsaved note (round 6 of the final audit)."""
        pending = getattr(self, "checklist_add_var", None)
        return bool(self._editor_state_has_content(self.capture_editor_state())
                    or (pending is not None and pending.get().strip()))

    def _editing_saved_note(self):
        """True when the editor points at a note that exists on disk — the
        exemption that lets a saved note be deliberately emptied (an
        ordinary edit) while a blank never-saved editor stays junk-proof."""
        return (self.selected_note_id is not None
                and self.find_note(self.selected_note_id) is not None)

    def editor_state_matches_saved(self, st):
        """True if the captured state equals what's on disk for its note — i.e.
        there are no unsaved changes. A brand-new note (no id) counts as unsaved
        the moment it has any content."""
        note_id = st["selected_note_id"]
        if note_id is None:
            # A new note is clean only if empty -- its date counts here, for
            # the dirty machinery; the gates still refuse a date alone.
            return not (self._editor_state_has_content(st)
                        or (st.get("date") or "").strip())
        note = self.find_note(note_id)
        if note is None:
            return False  # underlying note deleted -> treat as dirty/gone

        # Compare against the effective (occurrence-aware) content.
        occ = st.get("occurrence_date")
        if occ and is_recurring(note):
            # A day's override holds ONLY the overridable fields, plain text:
            # compared with the series' formatting it read dirty FOREVER, and
            # Back to Calendar refused to go (field report).
            shown = effective_note(note, occ)
            # Body and comments compare unstripped, as stored (stripped, a
            # whitespace edit read as none); titles are stored stripped.
            if not (st["title"].strip() == shown["title"].strip()
                    and st["body"] == shown["body"]
                    and st["comments"] == (shown.get("comments") or "")
                    and st["category"] == shown["category"]
                    and st["color"] == shown.get("color", "")
                    # ...and its lists' structure, which a day keeps of its
                    # looks (the owner's choice, the lows wave).
                    and list_lines(st.get("paragraphs"), st["body"])
                    == list_lines(day_paragraphs_shown(note, occ), shown["body"])):
                return False
            # ...and the SERIES' fields against the base, where load_note read
            # them (left out, a tick on a day never saved); formatting stays
            # OUT, as above. The date by its day (same_date).
            return (st.get("checklist", []) == note.get("checklist", [])
                    and st.get("attachments", []) == note.get("attachments", [])
                    and same_date(st["date"], note.get("date", ""))
                    and st["recurrence"]
                    == normalize_recurrence(note.get("recurrence")))
        shown = note
        if (st["title"].strip() != shown["title"].strip()
                or st["body"] != shown["body"]
                or st.get("formatting", []) != note.get("formatting", [])
                # Paragraphs (indents, alignment, a table's place): left out,
                # a tag-only change was skipped.
                or st.get("paragraphs", []) != note.get("paragraphs", [])
                or st["comments"] != (shown.get("comments") or "")
                or st["category"] != shown["category"]
                or st["color"] != shown.get("color", "")
                or st.get("checklist", []) != note.get("checklist", [])):
            return False
        # Date and repeat are the series'. The date by its day: as text,
        # 17.10.2026 against 2026-10-17 read every dated note unsaved.
        if not same_date(st["date"], note.get("date", "")):
            return False
        if st["recurrence"] != normalize_recurrence(note.get("recurrence")):
            return False
        if st["attachments"] != note.get("attachments", []):
            return False
        return True

    # ---------- Open-note tabs (multiple notes at once) ----------
    def _sync_active_tab(self):
        """Save the live editor back into the active tab's stored state."""
        if self.active_tab_index is not None and 0 <= self.active_tab_index < len(self.open_tabs):
            self.open_tabs[self.active_tab_index]["state"] = self.capture_editor_state()

    def _catch_up_deferred_refresh(self):
        """If a note-list/calendar rebuild was skipped earlier (see
        save_current_note) because a popup was open during autosave, run it
        now. Called at natural transition points — switching notes, changing
        tabs — where an extra rebuild blends into a change that was already
        happening, rather than standing out as an isolated glitch against an
        otherwise static screen."""
        if getattr(self, "_note_list_needs_refresh", False):
            self._note_list_needs_refresh = False
            self._calendar_needs_render = False
            self.refresh_note_list()
            self.render_calendar()
        elif getattr(self, "_calendar_needs_render", False):
            # A theme switch happened while the calendar was off screen, so
            # its rebuild was skipped (see apply_theme). Catch it up now,
            # before it becomes visible.
            self._calendar_needs_render = False
            self.render_calendar()

    def _update_open_highlight(self):
        """Move the 'open' ring to the cards that changed, no rebuild; its
        colour from _card_ring_color (the keyboard's ring wins). Every card
        painted as open is unringed but this one (_ring_to_paint): one
        outlined by a first save stayed, two "open" notes."""
        current = self.selected_note_id
        painted = getattr(self, "_open_ring_ids", None) or set()
        for note_id in [n for n in painted if n != current]:
            self._paint_ring(note_id)
        if current not in painted:
            self._paint_ring(current)

    def open_note_in_tab(self, note, occurrence_date=None, flush=True):
        """Open a saved note in the editor, the current one saved first.
        ``flush=False`` when the note was just rewritten from outside: the
        editor's old version would save over it, so such callers flush
        BEFORE their change.
        """
        # Popups close FIRST (one left open kept the list stale); the
        # template editor asks, and keeping it keeps this note shut. A
        # reload (flush=False) is not asked: Cancel saved the stale editor.
        if flush and not self._dismiss_mini_popup_asking():
            return False
        # On a reload the rest still close: a palette or a picker aimed at
        # the old text wrote into the new (wave 2, round 13).
        pop = getattr(self, "_mini_popup", None)
        if not flush and pop is not None and not callable(getattr(pop, "_confirm_dismiss", None)):
            self._dismiss_mini_popup()
        # Cleared BEFORE the flush, whose save would jump to the calendar.
        pending_return = getattr(self, "_pending_calendar_return", None)
        self._pending_calendar_return = None
        self._update_calendar_return_button()
        self._catch_up_deferred_refresh()
        # Saved before switching; going back to a date stays, the calendar's
        # way back armed again.
        if flush and self._flush_autosave() is False:
            self._pending_calendar_return = pending_return
            self._update_calendar_return_button()
            return False
        # Looked up again after that save, which can take the very note
        # being opened away (_take_back_aside): loaded anyway, it took typing
        # that no save would ever store, and said nothing (wave 2, round 7).
        here = (find_by_uid(self.notes, note.get("uid")) if note.get("uid")
                else next((n for n in self.notes if n is note), None))
        if here is None:
            self._pending_calendar_return = pending_return
            self._update_calendar_return_button()
            self._show_toast("That note is no longer here", kind="info")
            return False
        note = here
        self.load_note(note, occurrence_date)
        self._remember_last_open_note(note["id"])
        # Keep a single-entry tab list so the save/flush machinery still works.
        # Its snapshot is taken here, once (it was taken again at once).
        self._tab_counter += 1
        self.open_tabs = [{"key": self._tab_counter, "state": self.capture_editor_state()}]
        self.active_tab_index = 0
        # The ring moves without a rebuild: switching is constant, and a
        # refresh here flickered.
        self._update_open_highlight()
        return True

    def _open_unless_shown(self, note, occurrence_date=None):
        """open_note_in_tab for a person's open -- a card clicked, Enter on
        it, the menu's Open -- left alone when the editor already shows that
        note on that day: loaded again, it jumped to its top and Ctrl+Z lost
        all it held (wave 2, round 8). Asked of the day load_note would open:
        a one-off note opened from its calendar day is the note (round 9)."""
        if (self.selected_note_id is not None and note.get("id") == self.selected_note_id
                and self._day_to_open(note, occurrence_date) == self.current_occurrence_date):
            return True
        return self.open_note_in_tab(note, occurrence_date=occurrence_date)

    @staticmethod
    def _day_to_open(note, occurrence_date):
        """The day of *note* the editor opens for *occurrence_date*: that day
        where the series still draws it, else None -- the whole note."""
        when = parse_date(occurrence_date) if occurrence_date else None
        return (occurrence_date if is_recurring(note) and when is not None
                and expand_occurrences(note, when, when) == [occurrence_date]
                else None)

    def open_blank_tab(self):
        """Start a new empty note, the open one saved first. False when the
        person stayed (a date to fix): a caller filling the editor must stop
        -- the import loaded a recipe into a series, saved over it all."""
        # A popup holding typed work asks first, as in open_note_in_tab.
        if not self._dismiss_mini_popup_asking():
            return False
        pending_return = getattr(self, "_pending_calendar_return", None)
        self._pending_calendar_return = None
        self._update_calendar_return_button()
        self._catch_up_deferred_refresh()
        if self._flush_autosave() is False:
            # Going back means stay, exactly as in open_note_in_tab.
            self._pending_calendar_return = pending_return
            self._update_calendar_return_button()
            return False
        self.new_note()
        self._tab_counter += 1
        # The snapshot, taken once (see open_note_in_tab).
        self.open_tabs = [{"key": self._tab_counter, "state": self.capture_editor_state()}]
        self.active_tab_index = 0
        # Clears any previously-highlighted card's border — a blank new note
        # isn't "the" open note in the list. Same surgical update as
        # open_note_in_tab, not a full rebuild.
        self._update_open_highlight()

    def _flush_autosave(self, leaving=True, hold_repeat_off=None):
        """Cancel the pending autosave and save real changes now, so a late
        timer cannot hit the wrong note. False when the person went back to
        a date or repeat: callers stop, on ``is False`` only. ``leaving``
        False (a route changing something ELSE) leaves the question to the
        way out; that save, or a delete's (*hold_repeat_off*), holds a
        repeat's turn-off back (_date_and_repeat_to_store)."""
        self._cancel_pending_autosave()
        if self.selected_note_id is None and not self.open_tabs:
            # A blank editor still takes typing (the Add box's too), which a
            # click away within the autosave's half second lost.
            try:
                if not self._editor_holds_typing():
                    return True
            except Exception:  # noqa: BLE001 -- not knowing tries the save, never skips it
                self._log_swallowed("flush: blank editor")
        # Between a delete and the editor's repointing the id names nothing:
        # skipped quietly, as an automatic save raised "Note missing".
        if self.selected_note_id is not None and self.find_note(self.selected_note_id) is None:
            return True
        # A checklist item typed but not yet added is typing like any other:
        # it goes into the note it was typed for, before that note is left.
        # It used to stay in the box and be added to whichever note came next.
        self._take_pending_checklist_item()
        # A short date settles on leaving the note, as on leaving the field:
        # leaving the note may never move the keyboard out of it.
        if leaving:
            self._settle_date_fields()
        try:
            st, body_read = self._capture_and_read()
        except Exception:
            self._log_swallowed("flush: capture_editor_state")
            return True
        # The gate _autosave_now uses: an emptied SAVED note flushes too.
        if not self._editor_state_has_content(st) and not self._editing_saved_note():
            return True
        try:
            if not self.editor_state_matches_saved(st):
                # Not leaving, a repeat's turn-off is held, as the autosave
                # holds it (_date_and_repeat_to_store).
                held = getattr(self, "_holding_repeat_off", False)
                self._holding_repeat_off = held or (
                    not leaving if hold_repeat_off is None else hold_repeat_off)
                try:
                    self.save_current_note(auto=True, body_read=body_read)
                finally:
                    self._holding_repeat_off = held
        except Exception:
            # THE silent spot the audit named: a save failing here, at
            # note-switch or close, is exactly "stopped saving in
            # complete silence" — leave the trace.
            self._log_swallowed("flush: save_current_note")
        # A date not stored lives only on screen, which leaving replaces:
        # asked, going back the safe answer -- not at a session's end.
        if not leaving or getattr(self, "_ending_session", False):
            return True
        try:
            left_out = self._date_and_repeat_to_store()[2]
        except Exception:
            self._log_swallowed("flush: date and repeat check")
            left_out = []
        if left_out and hold_repeat_off and self._repeat_off_waits():
            # "Continue" drops the turn-off this save held too, so it is
            # named; not asked for alone, or every delete would ask.
            held = getattr(self, "_holding_repeat_off", False)
            self._holding_repeat_off = True
            try:
                left_out = [item[:-len(self._HELD_TAIL)]
                            if item.endswith(self._HELD_TAIL) else item
                            for item in self._date_and_repeat_to_store()[2]]
            except Exception:
                self._log_swallowed("flush: held date and repeat check")
            finally:
                self._holding_repeat_off = held
        if left_out:
            if not self._themed_dialog(
                    "Part of this note isn't saved",
                    self._left_out_message(left_out),
                    kind="warning",
                    buttons=[("Go back and fix it", False),
                             ("Continue without it", True)],
                    default="Go back and fix it"):
                return False
            self._put_back_stored_date_and_repeat()
            # Putting the repeat back writes its fields, and their traces
            # schedule an autosave; this method's promise is that no late
            # timer is left to fire into whatever replaces the editor.
            self._cancel_pending_autosave()
        return True

    def switch_to_tab(self, index):
        if index == self.active_tab_index:
            return
        if not (0 <= index < len(self.open_tabs)):
            return
        if self._flush_autosave() is False:
            return
        self._sync_active_tab()
        self.active_tab_index = index
        self.restore_editor_state(self.open_tabs[index]["state"])
        self._sync_editor_snapshot()

    def _sync_editor_snapshot(self):
        """Write the live editor back into the stored state of the note it
        belongs to. The dirty comparison and the restore after a bulk delete
        both read that snapshot. ISSUES_LOG, smaller lessons:
        _sync_editor_snapshot."""
        self._sync_active_tab()

    def _bind_global_shortcuts(self):
        """App-wide shortcuts (bind_all) -- Ctrl+N, Ctrl+S, Ctrl+F for find
        in the note -- in both letter cases for Caps Lock, each returning
        'break' so the combo is never typed."""
        for lower, upper, handler in (
                ("<Control-n>", "<Control-N>", self._shortcut_new_note),
                ("<Control-f>", "<Control-F>", self._shortcut_find),
                ("<Control-s>", "<Control-S>", self._shortcut_save_now)):
            self.bind_all(lower, handler, add="+")
            self.bind_all(upper, handler, add="+")

    # Where a click is on nothing: these classes take no click of their own.
    _EMPTY_CLICK_CLASSES = frozenset(
        ("Frame", "Label", "Canvas", "Labelframe", "TFrame", "TLabel", "Tk"))
    # Every class Tk types into, the ones this app builds or not: a box
    # added later is a typing box without anyone remembering this list.
    _TYPING_CLASSES = frozenset(
        ("Entry", "Text", "Spinbox", "TEntry", "TSpinbox", "TCombobox"))
    _CLICK_SEQUENCES = ("<Button-1>", "<ButtonRelease-1>",
                        "<Double-Button-1>", "<B1-Motion>")

    def _release_caret_on_empty_click(self, event):
        """A click on empty space takes the keyboard out of its box, as other
        programs do (the caret kept blinking; field pass). Left alone: a
        popup's clicks, and a widget with a click binding of its own or on a
        tag besides the window's and "all"."""
        w = event.widget
        if not isinstance(w, tk.Misc):
            return
        try:
            top = w.winfo_toplevel()
            if top is not self or w.winfo_class() not in self._EMPTY_CLICK_CLASSES:
                return
            for tag in w.bindtags():
                if tag in ("all", str(top)):
                    continue
                if any(w.bind_class(tag, seq) for seq in self._CLICK_SEQUENCES):
                    return
            held = self.focus_get()
        except (tk.TclError, KeyError):
            return
        if held is not None and held.winfo_class() in self._TYPING_CLASSES:
            # An open table cell is left the way any click elsewhere leaves
            # it, committed and closed: with the focus on the window its own
            # FocusOut reads the move as passing and keeps it open.
            editor = getattr(self, "_cell_editor", None)
            if editor is not None and held is editor["entry"]:
                self._commit_cell_editor()
            self.focus_set()

    def _leave_settings_for_the_editor(self):
        """What a shortcut needing the editor does first: a popup holding
        typed work asks (Cancel keeps editing, No discards, Yes saves) and
        one with nothing to lose closes; then Settings is left as Back
        leaves it -- under it, the shortcut worked on a hidden editor.
        Returns False when the person has to stay.
        """
        if not self._dismiss_mini_popup_asking():
            return False
        if getattr(self, "_settings_open", False):
            return self.hide_settings_page() is not False
        return True

    def _shortcut_new_note(self, event=None):
        """Ctrl+N: a fresh note. Switches to the Notes tab first, since the
        editor lives there and the shortcut can fire from the Calendar."""
        if self._a_dialog_is_asking() or not self._leave_settings_for_the_editor():
            return "break"
        self.notebook.select(self.TAB_NOTES)
        # Flushed before clearing, or the debounce's typing went; going
        # back to fix a date keeps the note.
        if self._flush_autosave() is False:
            return "break"
        self.new_note()
        return "break"

    def _shortcut_save_now(self, event=None):
        """Ctrl+S: save the note being edited. Stays silent when there is
        genuinely nothing to save, rather than popping the "write something"
        warning a global shortcut would otherwise trigger from anywhere
        (same emptiness test the autosave uses)."""
        if self._a_dialog_is_asking():
            return "break"
        # In the template editor Ctrl+S is its Save (it saved the hidden
        # note), asked of the key's own widget.
        pop = getattr(self, "_mini_popup", None)
        save_popup = (getattr(pop, "_save_from_keyboard", None)
                      if pop is not None else None)
        if (save_popup is not None and event is not None
                and self._is_inside_popup(getattr(event, "widget", None), pop)):
            save_popup()
            return "break"
        try:
            st = self.capture_editor_state()
        except Exception:  # noqa: BLE001 -- logged, as the autosave's is
            self._log_swallowed("Ctrl+S: capture_editor_state")
            return "break"
        # Ctrl+S takes what the Save button takes: an emptied saved note,
        # and a bare dated reminder -- both explicit asks.
        deliberate = (self._editor_state_has_content(st)
                      or (st.get("date") or "").strip()
                      or self._editing_saved_note())
        if deliberate:
            self.save_current_note(auto=False)
        return "break"

    # ---------- Find in the current note (Ctrl+F) ----------
    # Read-only: its two tags and one canvas flash (re-resolved live, as a
    # cell commit may rebuild grids). No text, caret or saved tag touched.
    FIND_MATCH_CAP = 2000

    def _shortcut_find(self, event=None):
        """Ctrl+F: open the in-note find bar (on the Notes tab)."""
        if self._a_dialog_is_asking() or not self._leave_settings_for_the_editor():
            return "break"
        try:
            self.notebook.select(self.TAB_NOTES)
        except tk.TclError:
            pass
        self._open_find()
        return "break"

    def _build_find_bar(self):
        """The find bar is a Frame place()'d INTO editor_outer (the
        non-scrolling viewport frame), so it lives inside the app window,
        never scrolls away, and -- because place() is outside pack -- never
        reflows the editor or churns the scrollregion."""
        # highlightcolor as well: Tk draws the border in it while the
        # keyboard is in the bar's box, which is all the time it is used.
        bar = tk.Frame(self.editor_outer, bg=self.colors["card"],
                       highlightthickness=1,
                       highlightbackground=self.colors["accent"],
                       highlightcolor=self.colors["accent"])
        # The accent border tracked too, or it kept the old accent.
        self.track_theme(bar, bg="card", highlightbackground="accent",
                         highlightcolor="accent")
        self._find_var = tk.StringVar()
        entry = tk.Entry(bar, textvariable=self._find_var, relief="flat",
                         width=22, font=("Segoe UI", 10),
                         bg=self.colors["sidebar"], fg=self.colors["text"],
                         insertbackground=self.colors["text"])
        self.track_theme(entry, bg="sidebar", fg="text", insertbackground="text")
        entry.pack(side="left", padx=(6, 4), pady=4, ipady=2)
        self._find_entry = entry
        self._add_paste_menu(entry)
        self._guard_entry_astral(entry)
        self._find_var.trace_add("write", lambda *a: self._find_on_query_change())
        entry.bind("<Return>", lambda e: (self._find_nav(1), "break")[1])
        entry.bind("<Shift-Return>", lambda e: (self._find_nav(-1), "break")[1])
        entry.bind("<Escape>", lambda e: (self._close_find(), "break")[1])
        self._find_count_lbl = tk.Label(
            bar, text="", bg=self.colors["card"], fg=self.colors["subtext"],
            font=("Segoe UI", 8), width=8, anchor="w")
        self.track_theme(self._find_count_lbl, bg="card", fg="subtext")
        self._find_count_lbl.pack(side="left", padx=(0, 4))
        for txt, delta in (("▴", -1), ("▾", 1)):
            b = tk.Button(bar, text=txt, command=lambda d=delta: self._find_nav(d),
                          relief="flat", cursor="hand2", bd=0,
                          font=("Segoe UI", 9, "bold"),
                          bg=self.colors["card"], fg=self.colors["text"])
            self.track_theme(b, bg="card", fg="text")
            b.pack(side="left", padx=1)
        self._find_case = tk.BooleanVar(value=False)
        cb = tk.Checkbutton(bar, text="Aa", variable=self._find_case,
                            command=lambda: self._find_rescan(reveal=False),
                            font=("Segoe UI", 8, "bold"))
        # Built once with the bar and long-lived, so its colours are tracked
        # live; left off the map they stay at the theme it was built in.
        self._drawn_tick_box(cb, "card", "subtext", track=True)
        self._find_case_cb = cb
        cb.pack(side="left", padx=(2, 2))
        close = tk.Button(bar, text="✕", command=self._close_find,
                          relief="flat", cursor="hand2", bd=0,
                          font=("Segoe UI", 9, "bold"),
                          bg=self.colors["card"], fg=self.colors["subtext"])
        self.track_theme(close, bg="card", fg="subtext")
        close.pack(side="left", padx=(2, 6))
        self._find_bar = bar

    def _open_find(self):
        if not hasattr(self, "body_text"):
            return
        if getattr(self, "_find_bar", None) is None:
            self._build_find_bar()
        # Prefill from the current selection, if any.
        try:
            sel = self.body_text.get("sel.first", "sel.last")
        except tk.TclError:
            sel = ""
        if sel and "\n" not in sel:
            self._find_var.set(sel)
        self._find_bar.place(relx=1.0, x=-8, y=6, anchor="ne")
        self._find_bar.lift()
        self._find_open = True
        self._find_entry.focus_set()
        self._find_entry.select_range(0, "end")
        self._find_rescan(reveal=True)

    def _close_find(self, event=None):
        self._hide_find()
        try:
            self.body_text.focus_set()
        except tk.TclError:
            pass

    def _hide_find(self):
        """Put the bar away as the person leaves the note -- for another
        note, the Calendar or Settings. Its words stay for the next Ctrl+F;
        the keyboard is moved only off the bar's own box, never taken from
        where it went (a note card clicked in the list keeps it)."""
        bar = getattr(self, "_find_bar", None)
        if bar is not None:
            # focus_get() answers None while another program is in front;
            # the window's own record is where the keyboard will return.
            try:
                held = str(self.focus_get() or self.tk.call(
                    "focus", "-lastfor", self._w))
            except (KeyError, tk.TclError):
                held = ""
            if held.startswith(str(bar) + "."):
                self.focus_set()
            bar.place_forget()
        self._find_open = False
        self._find_missed = False
        self._find_clear()
        # A count the keys left for the pause, now the hits are gone.
        if getattr(self, "_word_count_due", False):
            try:
                self.update_word_count()
            except Exception:
                self._log_swallowed("find: word count on closing")

    def _find_clear(self):
        """Remove ONLY the find tags and the throwaway flash. No existing
        tag is ever in scope."""
        for tag in ("find_all", "find_current"):
            try:
                self.body_text.tag_remove(tag, "1.0", "end")
            except tk.TclError:
                pass
        self._find_delete_flash()
        self._find_matches = []
        self._find_index = -1
        self._find_model_on = None

    def _find_delete_flash(self):
        """Delete the current cell flash by RE-RESOLVING the live grid --
        never through a cached canvas, which a rebuild may have destroyed."""
        cur = getattr(self, "_find_flash", None)
        if not cur:
            return
        line = cur.get("line")
        info = self._grid_at_line(line) if line is not None else None
        if info is not None:
            try:
                info["canvas"].delete("find_flash")
            except tk.TclError:
                pass
        self._find_flash = None

    def _find_on_query_change(self):
        # Typing in the find box: debounce a rescan that DOES reveal the
        # first hit (this is a search gesture, not a note edit).
        job = getattr(self, "_find_debounce", None)
        if job is not None:
            try:
                self.after_cancel(job)
            except (tk.TclError, ValueError):
                pass
        self._find_debounce = self.after(180, self._find_debounce_fire, True)

    def _find_on_body_edit(self):
        # The body may have changed while the bar is open (every edit's
        # autosave tells it): gate navigation until a rescan completes, and
        # rescan WITHOUT revealing, which would twitch the view at each key.
        if not getattr(self, "_find_open", False):
            return
        self._find_model_dirty = True
        job = getattr(self, "_find_debounce", None)
        if job is not None:
            try:
                self.after_cancel(job)
            except (tk.TclError, ValueError):
                pass
        self._find_debounce = self.after(180, self._find_debounce_fire, False)

    def _find_on_context_switch(self, leaving=True):
        """Note/tab switch or load: the old note's match model is invalid.
        Clear synchronously and cancel any pending debounce so no navigation
        runs against stale indices. Leaving the note closes the bar (her
        re-test, case 600); the same note loaded again over itself is the
        same search, rescanned."""
        job = getattr(self, "_find_debounce", None)
        if job is not None:
            try:
                self.after_cancel(job)
            except (tk.TclError, ValueError):
                pass
            self._find_debounce = None
        self._find_clear()
        self._find_model_dirty = False
        if leaving:
            self._hide_find()
        elif getattr(self, "_find_open", False) and getattr(self, "_find_bar", None):
            self._find_rescan(reveal=False)

    def _find_norm_cell(self, value):
        """A cell's searchable text, exactly as the sidebar search sees it
        (core_tables.content_text): the <br> marker becomes a space; merge
        markers and checkboxes are not words."""
        if value in (core_tables.MERGE_LEFT, core_tables.MERGE_UP):
            return None
        if core_tables.checkbox_state(value) is not None:
            return None
        return value.replace(core_tables.LINE_BREAK, " ")

    def _find_scan_model(self, query):
        """Build the ordered match list for `query`. Prose matches are Tk
        ranges (skipping any that cross an elided table); table-cell matches
        are (live_line, data_row, col), located via core/tables and keyed
        the way info['cells'] is (separator excluded). The spaces at its ends
        are not part of it unless it is nothing else, as in the list's
        search; a line break there is, to find the words that end a line."""
        query = query.strip(" ") or query
        nocase = not self._find_case.get()
        needle = fold_for_search(query) if nocase else query
        b = self.body_text
        text = b.get("1.0", "end-1c")
        self._find_model_text = text
        matches = self._find_prose(query, nocase, text)
        # Table cells: read the plain text, walk each block's DATA rows. The
        # note split, and each grid's line asked, once: per block, both grew
        # with the tables times the note (round 9).
        lines = text.split("\n")
        grids = {}
        for info in getattr(self, "_table_grids", []):
            grids.setdefault(self._grid_first_line(info), info)
        for first0, last0 in core_tables.find_blocks(text):
            info = grids.get(first0 + 1)
            if info is None:
                continue  # typed pipes not yet a grid -> already prose above
            live_first = first0 + 1
            block = lines[first0:last0 + 1]
            sep_at = core_tables.separator_index(block)
            data_r = 0
            for i, line_text in enumerate(block):
                if i == sep_at:
                    continue
                for c, raw in enumerate(core_tables.split_row(line_text)):
                    val = self._find_norm_cell(raw)
                    if val is None:
                        continue
                    hay = fold_for_search(val) if nocase else val
                    if needle and needle in hay and (data_r, c) in info["cells"]:
                        matches.append({"kind": "cell", "line": live_first,
                                        "row": data_r, "col": c,
                                        "sortcol": 10000 + c})
                        if len(matches) >= self.FIND_MATCH_CAP:
                            break
                data_r += 1
        # Order top-to-bottom; cell matches sort after prose on the same
        # (table window) line via the large sortcol.
        matches.sort(key=lambda m: (m["line"], m.get("sortcol", m.get("col", 0))))
        return matches

    def _find_prose(self, query, nocase, text):
        """The prose matches of *query* in the body (*text*, as read), top
        to bottom, no more than FIND_MATCH_CAP: Tk ranges, as Tk's own search
        gives them -- the shown text of each line, folded as every search
        folds it, overlapping hits each one -- found in Python, each line read
        once. Tk's search measured a line from its start for each hit (15 s
        a rescan, round 9), and its -nocase search ends the app on Linux."""
        b = self.body_text
        cap = self.FIND_MATCH_CAP
        matches = []
        hidden = b.tag_ranges(self.TABLE_HIDE_TAG)
        starts = sorted(_index_key(at) for at in hidden[::2])

        def hit(line, col, end, end_line=None):
            # A hidden table begins inside the hit: tag_nextrange's answer.
            end_line = line if end_line is None else end_line
            at = bisect.bisect_left(starts, (line, col))
            if not (at < len(starts) and starts[at] < (end_line, end)):
                matches.append({"kind": "prose", "start": f"{line}.{col}",
                                "end": f"{end_line}.{end}", "line": line, "col": col})
            return len(matches) >= cap

        if not query:
            return matches
        # One fold for every query, letter for letter, so a hit's place in
        # the folded line is its place on screen: str.lower() made two
        # characters of "İ", and the hits after one landed one place late.
        fold = fold_for_search if nocase else str
        needle = fold(query)
        windows = {}
        for _kind, _name, index in b.dump("1.0", "end", window=True):
            line, col = _index_key(index)
            windows.setdefault(line, set()).add(col)
        hides = {}
        for first, last in zip(hidden[::2], hidden[1::2]):
            (l1, c1), (l2, c2) = _index_key(first), _index_key(last)
            for line in range(l1, l2 + 1):
                hides.setdefault(line, []).append(
                    (c1 if line == l1 else 0, c2 if line == l2 else None))
        if "\n" in needle:
            # Tk's -nocase search crashed the process on Linux whenever the
            # line held an emoji (Tk 8.6.16, round 10): read here too.
            for found in self._find_across_lines(text.split("\n"), needle, fold,
                                                 windows, hides):
                if hit(*found):
                    return matches
            return matches
        for li, line in enumerate(text.split("\n"), start=1):
            cols = None
            if li in windows or li in hides:
                line, cols = self._find_shown(line, windows.get(li, ()), hides.get(li, ()))
            hay = fold(line)
            at, seen, col = hay.find(needle), 0, 0
            while at != -1:
                last = at + len(needle) - 1
                if cols is None:
                    col += self._tk_units(line[seen:at])
                    seen = at
                    end = col + self._tk_units(line[at:last + 1])
                else:
                    col, end = cols[at], cols[last] + self._tk_units(line[last])
                if hit(li, col, end):
                    return matches
                at = hay.find(needle, at + 1)
        return matches

    @staticmethod
    def _find_shown(line, windows, hides):
        """What Tk's search reads of a line holding a drawn table's window
        or hidden text: the characters shown, and each one's Tk column."""
        shown, cols, col = [], [], 0
        for ch in line:
            while col in windows:
                col += 1
            if not any(lo <= col and (hi is None or col < hi) for lo, hi in hides):
                shown.append(ch)
                cols.append(col)
            col += 2 if ord(ch) > 0xFFFF else 1
        return "".join(shown), cols

    def _find_across_lines(self, lines, needle, fold, windows, hides):
        """Where *needle*, which holds a line break, is in *lines*, as Tk's
        search joins them: the shown text of each line and its break, one a
        drawn table hides never inside a hit. Yields (line, col, end, end
        line) in Tk columns. A hit's first break is a line's own, so a line
        is measured at most once where a hit starts and once where one ends."""
        shown, at = [], 0
        starts, hidden_before = [], [0]
        for li, raw in enumerate(lines, start=1):
            line, cols = raw, None
            if li in windows or li in hides:
                line, cols = self._find_shown(raw, windows.get(li, ()), hides.get(li, ()))
            shown.append((line, cols, raw))
            starts.append(at)
            at += len(line) + 1
            broken = any(hi is None for _lo, hi in hides.get(li, ()))
            hidden_before.append(hidden_before[-1] + broken)
        # Tk's text ends in a break of its own, and its search reads it.
        starts.append(at)
        hay = "".join(fold(line) + "\n" for line, _cols, _raw in shown)
        breaks = needle.count("\n")

        def column(i, off):
            line, cols, raw = shown[i]
            if off == len(line):            # at the line's own break
                return self._tk_units(raw) + len(windows.get(i + 1, ()))
            return self._tk_units(line[:off]) if cols is None else cols[off]

        def column_after(i, off):
            if not off:
                return 0
            line, cols, _raw = shown[i]
            if cols is None:
                return self._tk_units(line[:off])
            return cols[off - 1] + self._tk_units(line[off - 1])

        found = hay.find(needle)
        while found != -1:
            i = bisect.bisect_right(starts, found) - 1
            j = i + breaks
            if hidden_before[j] == hidden_before[i]:
                yield (i + 1, column(i, found - starts[i]),
                       column_after(j, found + len(needle) - starts[j]), j + 1)
            found = hay.find(needle, found + 1)

    def _find_debounce_fire(self, reveal):
        """The debounced rescan, run by its own timer -- the only place
        its job is cleared. A rescan run directly (the Aa box, opening the
        bar) leaves a waiting one tracked, since it may carry a reveal the
        direct one does not; clearing the job there left that timer
        scheduled with nothing tracking it -- see _autosave_now."""
        self._find_debounce = None
        if not reveal and not self._find_stale():
            # Told of an edit elsewhere -- the title, an arrow key: the
            # model still stands on the body as it is.
            self._find_model_dirty = False
            return
        self._find_rescan(reveal=reveal)

    def _find_standing(self, text=None):
        """What the find model stands on: the query, the case, the body's
        text (*text*, when just read), the drawn tables' hidden ranges and
        the hits as painted. All the same, a rescan makes the same model."""
        b = self.body_text
        return (self._find_var.get(), bool(self._find_case.get()),
                b.get("1.0", "end-1c") if text is None else text,
                tuple(map(str, b.tag_ranges(self.TABLE_HIDE_TAG))),
                tuple(map(str, b.tag_ranges("find_all"))))

    def _find_stale(self):
        """Whether the body, or the search, has changed since the model was
        read -- by any route, told to the bar or not."""
        try:
            return getattr(self, "_find_model_on", None) != self._find_standing()
        except (tk.TclError, AttributeError):
            return True

    def _find_paint_entry(self):
        """The find box's ground: the theme's warning tint while its words
        are found nowhere, the plain field otherwise. Asked again by a theme
        switch, which lays the plain field back on a tracked box."""
        entry = getattr(self, "_find_entry", None)
        if entry is None:
            return
        missed = (getattr(self, "_find_open", False)
                  and getattr(self, "_find_missed", False))
        try:
            entry.configure(bg=miss_surface(self.colors) if missed
                            else self.colors["sidebar"])
        except tk.TclError:
            pass

    def _find_rescan(self, reveal=False):
        if not getattr(self, "_find_open", False):
            return
        query = self._find_var.get()
        prev = None
        if 0 <= self._find_index < len(getattr(self, "_find_matches", [])):
            prev = self._find_matches[self._find_index]
        # Clear old tags/flash before re-tagging.
        for tag in ("find_all", "find_current"):
            try:
                self.body_text.tag_remove(tag, "1.0", "end")
            except tk.TclError:
                pass
        self._find_delete_flash()
        if not query:
            self._find_matches = []
            self._find_index = -1
            self._find_model_dirty = False
            self._find_model_on = None
            self._find_count_lbl.config(text="")
            self._find_missed = False
            self._find_paint_entry()
            return
        self._find_matches = self._find_scan_model(query)
        self._find_model_dirty = False
        n = len(self._find_matches)
        # Tag the prose matches with the field tag -- at most FIND_LINE_PAINT
        # a line, around the hit that is current once this rescan is done.
        if n:
            self._find_paint_around(self._find_matches[
                0 if reveal else min(max(self._find_index, 0), n - 1)])
        self._find_raise_tags()
        self._find_model_on = self._find_standing(self._find_model_text)
        if not n:
            self._find_index = -1
            self._find_count_lbl.config(text="0/0")
            self._find_missed = True
            self._find_paint_entry()
            return
        self._find_missed = False
        self._find_paint_entry()
        capped = n >= self.FIND_MATCH_CAP
        if reveal:
            self._find_index = 0
            self._find_reveal(self._find_matches[0])
        else:
            # Keep the current position across an edit rescan: clamp to a
            # near match, DO NOT reveal (that would twitch the view).
            self._find_index = min(
                self._find_index if self._find_index >= 0 else 0, n - 1)
            self._find_mark_current(scroll=False)
        self._find_count_lbl.config(
            text=f"{self._find_index + 1}/{n}{'+' if capped else ''}")

    # Painted hits a line holds: 2,000 in a paragraph held each key up to
    # 1.4 s. The model keeps every hit, for the count and Enter.
    FIND_LINE_PAINT = 200

    def _find_painted(self, matches, anchor):
        """The prose hits of *matches* to paint: on a line holding more than
        FIND_LINE_PAINT, those around *anchor* ("line.col")."""
        at = tuple(int(part) for part in str(anchor).split("."))
        lines = {}
        for m in matches:
            if m["kind"] == "prose":
                lines.setdefault(m["line"], []).append(m)
        painted = []
        for hits in lines.values():
            if len(hits) > self.FIND_LINE_PAINT:
                mid = bisect.bisect_left([(h["line"], h["col"]) for h in hits], at)
                first = max(0, min(mid - self.FIND_LINE_PAINT // 2,
                                   len(hits) - self.FIND_LINE_PAINT))
                hits = hits[first:first + self.FIND_LINE_PAINT]
            painted.extend(hits)
        return painted

    def _find_paint_around(self, current):
        """Paint the hits around *current* (_find_painted) -- the cursor
        standing in for a cell's match, which has no place in the text.
        Laid around the hit current before a reveal, or not moved by Enter,
        the paint left the current hit's neighbours bare (round 13)."""
        try:
            anchor = (current["start"] if current.get("kind") == "prose"
                      else self.body_text.index("insert"))
            self.body_text.tag_remove("find_all", "1.0", "end")
        except tk.TclError:
            anchor = "1.0"
        for m in self._find_painted(self._find_matches, anchor):
            try:
                self.body_text.tag_add("find_all", m["start"], m["end"])
            except tk.TclError:
                pass

    def _find_raise_tags(self):
        # find tags win over highlight_* backgrounds; sel stays on top.
        for tag in ("find_all", "find_current", "sel"):
            try:
                self.body_text.tag_raise(tag)
            except tk.TclError:
                pass

    def _find_nav(self, delta):
        if getattr(self, "_find_model_dirty", False):
            return
        if self._find_var.get() and self._find_stale():
            # An edit no route told the bar of: never a stale place.
            self._find_rescan(reveal=False)
        matches = getattr(self, "_find_matches", [])
        if not matches:
            return
        self._find_index = (self._find_index + delta) % len(matches)
        here = matches[self._find_index]
        try:
            unpainted = (here["kind"] == "prose"
                         and "find_all" not in self.body_text.tag_names(here["start"]))
        except tk.TclError:
            unpainted = False
        if unpainted:
            # Walked past the painted ones: the paint follows (_find_painted).
            self._find_paint_around(here)
            self._find_raise_tags()
            self._find_model_on = self._find_standing(self._find_model_text)
        self._find_reveal(here)
        self._find_count_lbl.config(
            text=f"{self._find_index + 1}/{len(matches)}"
                 f"{'+' if len(matches) >= self.FIND_MATCH_CAP else ''}")

    def _find_mark_current(self, scroll=True):
        matches = getattr(self, "_find_matches", [])
        if not (0 <= self._find_index < len(matches)):
            return
        if scroll:
            self._find_reveal(matches[self._find_index])
        else:
            m = matches[self._find_index]
            try:
                self.body_text.tag_remove("find_current", "1.0", "end")
                if m["kind"] == "prose":
                    self.body_text.tag_add("find_current", m["start"], m["end"])
            except tk.TclError:
                pass
            self._find_raise_tags()

    def _find_reveal(self, m):
        self._grid_view_restore = None
        try:
            self.body_text.tag_remove("find_current", "1.0", "end")
        except tk.TclError:
            pass
        self._find_delete_flash()
        if m["kind"] == "prose":
            try:
                self.body_text.tag_add("find_current", m["start"], m["end"])
                self.body_text.see(m["start"])
            except tk.TclError:
                pass
        else:
            self._find_flash_cell(m)
        self._find_raise_tags()
        self._find_ensure_visible()
        # Win the race against a grid rebuild's own after_idle restore and
        # its 60/160/360ms re-pin timers: re-assert the reveal after them.
        self.after_idle(self._find_reassert_reveal)
        self.after(220, self._find_reassert_reveal)

    def _find_reassert_reveal(self):
        if not getattr(self, "_find_open", False):
            return
        matches = getattr(self, "_find_matches", [])
        if not (0 <= self._find_index < len(matches)):
            return
        self._grid_view_restore = None
        m = matches[self._find_index]
        try:
            if m["kind"] == "prose":
                self.body_text.see(m["start"])
            else:
                info = self._grid_at_line(m["line"])
                if info is not None:
                    self._see_cell(info, m["row"], m["col"])
        except tk.TclError:
            pass
        self._find_ensure_visible()

    def _find_flash_cell(self, m):
        """Draw a throwaway rectangle on the LIVE grid canvas (re-resolved),
        never a cached one. Bail to a see()-only reveal if the grid is gone."""
        info = self._grid_at_line(m["line"])
        if info is None:
            return
        first = self._grid_first_line(info)
        if first is None:
            return
        cell = info["cells"].get((m["row"], m["col"]))
        canvas = info.get("canvas")
        if cell is None or canvas is None:
            # The table's line only: a cell in sight is _see_cell's, which a
            # see() first made the note jump at every step (round 8).
            try:
                self.body_text.see(f"{first}.0")
            except tk.TclError:
                return
            self._find_flash = {"line": m["line"]}  # counted, no box (hidden col)
            return
        try:
            x, y = cell["x"], cell["y"]
            w, h = cell["w"], cell.get("h", info.get("row_h", 24))
            canvas.delete("find_flash")
            canvas.create_rectangle(x + 1, y + 1, x + w - 1, y + h - 1,
                                    outline=self.colors["accent"], width=2,
                                    tags="find_flash")
            # Bring a horizontally off-screen cell into view.
            total = canvas.bbox("all")
            if total and total[2] > canvas.winfo_width():
                canvas.xview_moveto(max(0.0, x / total[2]))
        except tk.TclError:
            pass
        self._see_cell(info, m["row"], m["col"])
        self._find_flash = {"line": m["line"]}

    def _retint_find_tags(self, text_widget):
        """(Re)apply the find colours, blended from the theme. The current
        match is the full accent, its words letters_on (the text colour fell
        below 4.5:1), and boxed as a cell's is: by fill alone it was one
        shade of three to a colour-blind eye."""
        try:
            text_widget.tag_configure("find_all",
                                      background=find_all_surface(self.colors))
            text_widget.tag_configure("find_current",
                                      background=self.colors["accent"],
                                      foreground=self._on_fill("accent"),
                                      relief="solid", borderwidth=1)
        except tk.TclError:
            pass

    def _find_reflash(self):
        """Re-draw the current cell flash after a theme switch (in the new
        accent) or a rebuild (which tore the canvas down)."""
        if not getattr(self, "_find_open", False):
            return
        matches = getattr(self, "_find_matches", [])
        if 0 <= self._find_index < len(matches):
            m = matches[self._find_index]
            if m["kind"] == "cell":
                self._find_flash_cell(m)
        self._find_raise_tags()

    def _find_ensure_visible(self):
        """Scroll the editor PAGE (editor_canvas) so the body's own 12-line
        viewport is on screen -- body_text.see() only drives the body's
        inner scroll, not the page it sits inside."""
        try:
            self.editor_canvas.update_idletasks()
            bbox = self.editor_canvas.bbox(self._editor_window)
            if not bbox:
                return
            total = bbox[3] - bbox[1]
            if total <= 0:
                return
            y = self.body_text.winfo_rooty() - self.editor.winfo_rooty()
            h = self.body_text.winfo_height()
            canvas_h = self.editor_canvas.winfo_height()
            cur = self.editor_canvas.yview()[0] * total
            if y < cur:
                self.editor_canvas.yview_moveto(max(0.0, y) / total)
            elif y + h > cur + canvas_h:
                self.editor_canvas.yview_moveto(
                    max(0.0, y + h - canvas_h) / total)
        except (tk.TclError, ZeroDivisionError):
            pass

    def new_note(self):
        self.selected_note_id = None
        self.current_occurrence_date = None
        # Whatever was under review from a share code is no longer here.
        self._arrived_uid = ""
        self.title_entry.delete(0, "end")
        self.title_entry.config(fg=self.colors["text"])
        # Clearing the field does not go through _insert_title, so the
        # counter would otherwise still be showing the last note's length.
        self._refresh_title_count()
        self.body_text.delete("1.0", "end")
        self.comments_text.delete("1.0", "end")
        self.category_var.set("General")
        self.clear_note_date()
        self.current_note_color = ""
        self._update_color_swatch()
        self.current_attachments = []
        self.refresh_attachments_list()
        self.write_recurrence_to_ui({})
        self._working_checklist = []
        # The add box belongs to the note that was open; what was typed in
        # it was saved there on the way out, or dropped with that note.
        if hasattr(self, "checklist_add_var"):
            self.checklist_add_var.set("")
        if hasattr(self, "_checklist_rows"):
            self._render_checklist_items()
        self._sync_checklist_open_state()
        self._sync_calculator_open_state()
        self.title_entry.focus()
        self.set_status("New note — not yet saved")
        self._status_names_left_out = None
        self.update_word_count()
        self._pending_styles = set()
        self._pending_text_color = None
        self._pending_font_size = None
        self._pending_font_family = None
        self._pending_highlight_color = None
        self._refresh_format_buttons()
        self._reset_editor_scroll()
        self._reset_text_undo()
        self._update_restore_button()
        self._find_on_context_switch()
        self._share_code_on_context_switch()
        self._update_occurrence_banner()
        # A fresh editor ends any calendar trip (_add_note_for_date re-arms
        # its own): one surviving a delete jumped a later Save.
        self._pending_calendar_return = None
        self._update_calendar_return_button()
        # No note is open now, so no card wears the "open" outline: Ctrl+N,
        # a calendar day's "Add note" and Use template came through here
        # and left it on the card they left until the new note's first save.
        self._update_open_highlight()

    def load_note(self, note, occurrence_date=None):
        """Open a note. If occurrence_date is given, the note is being opened
        from one specific day of a repeating series, and any per-occurrence
        override for that day is shown instead of the base content."""
        # A reload of the checklist held keeps the list, for a delete's Undo;
        # another starts a new one. A day only where the series draws one
        # (ISSUES_LOG: "Round twenty-three: the day the editor stayed on").
        day = self._day_to_open(note, occurrence_date)
        same_session = (self.selected_note_id == note.get("id")
                        and self.current_occurrence_date == day)
        kept_checklist = (getattr(self, "_working_checklist", None)
                          if same_session else None)
        self.selected_note_id = note["id"]
        self.current_occurrence_date = day
        # A new note's status line names nothing left out (see
        # _say_nothing_is_left_out).
        self._status_names_left_out = None
        # A saved note has its own identity; one that was under review from
        # a share code is no longer in the editor.
        self._arrived_uid = ""

        # The day worked out above: a one-off opened from its calendar date
        # showed a kept day's words, and the save wrote them over the note.
        shown = effective_note(note, day) if day else note

        # A pending style cleared BEFORE the body goes in: the insert hook
        # would take the load for typing and style it.
        self._pending_styles = set()
        self._pending_text_color = None
        self._pending_font_size = None
        self._pending_font_family = None
        self._pending_highlight_color = None
        self.title_entry.delete(0, "end")
        self._insert_title(shown["title"])
        self.title_entry.config(fg=self.colors["text"])
        self.body_text.delete("1.0", "end")
        self.body_text.insert("1.0", shown["body"])
        # Spans belong to the base note (save_current_note): laid only on
        # its own text, or bold lands on the wrong characters.
        if shown.get("body") == note.get("body"):
            self._apply_formatting(self.body_text, note.get("formatting", []))
        # The lines' looks: all on the series' words, a day's own list lines
        # on its own text (day_paragraphs_shown, the phone's the same).
        self._apply_paragraphs(self.body_text, day_paragraphs_shown(note, day)
                               if day else note.get("paragraphs", []))
        self._render_table_grids()
        self.comments_text.delete("1.0", "end")
        self.comments_text.insert("1.0", shown.get("comments", ""))
        self.category_var.set(shown["category"])

        self._show_date_in_field(note.get("date"))

        self.current_note_color = shown.get("color", "")
        self._update_color_swatch()
        self.current_attachments = list(note.get("attachments", []))
        self.refresh_attachments_list()
        # Checklist: work on a copy so edits aren't committed until save.
        fresh = [
            {"text": it.get("text", ""), "done": bool(it.get("done"))}
            for it in note.get("checklist", []) if isinstance(it, dict)
        ]
        if kept_checklist is not None and kept_checklist == fresh:
            kept_checklist[:] = fresh
            self._working_checklist = kept_checklist
        else:
            self._working_checklist = fresh
        # An item half-typed for the note that was open does not follow it
        # here (see new_note); one this note's full list could not take
        # waits for it (_take_pending_checklist_item).
        if hasattr(self, "checklist_add_var"):
            self.checklist_add_var.set(
                self._add_box_waiting.pop(note.get("uid"), ""))
        if hasattr(self, "_checklist_rows"):
            self._render_checklist_items()
        self._sync_checklist_open_state()
        self._sync_calculator_open_state()
        self.write_recurrence_to_ui(note.get("recurrence"))

        if self.current_occurrence_date:
            has_override = self.current_occurrence_date in (note.get("overrides") or {})
            suffix = " — it keeps edits of its own" if has_override else ""
            self.set_status(
                f"Only this day: {show_date(self.current_occurrence_date)}{suffix}")
        else:
            created = note.get("created", "")
            if created:
                self.set_status(f"Created: {show_stamp(created)}   ·   "
                                f"Last updated: {show_stamp(note['updated'])}")
            else:
                self.set_status(f"Last updated: {show_stamp(note['updated'])}")
        self.update_word_count()
        self._refresh_format_buttons()
        self._reset_editor_scroll()
        self._reset_text_undo()
        self._update_restore_button()
        self._find_on_context_switch(leaving=not same_session)
        self._share_code_on_context_switch()
        self._update_occurrence_banner()
        self._spell_schedule_all()

    # ---------- Right-click context menu ----------
    def duplicate_note(self, note):
        """Make a full copy of a note as a new, separate note. The copy's title
        gets a '(copy)' suffix so the two are distinguishable in the list. A
        recurring note is copied whole, recurrence included."""
        if note is None:
            return
        import copy as _copy
        clone = _copy.deepcopy(note)
        clone["id"] = max([n["id"] for n in self.notes], default=0) + 1
        # A duplicate is a different note: the copied uid is dropped, and
        # normalize_note mints a fresh one.
        clone.pop("uid", None)
        base_title = (note.get("title") or "").strip()
        clone["title"] = f"{base_title} (copy)" if base_title else "(copy)"
        clone["updated"] = now_stamp()
        # A duplicate is its own note, its series' own days (deleted, edited,
        # moved) copied with it, so it reads as the original does.
        clone = normalize_note(clone)
        # The copy gets its OWN files (shared, deleting either took the
        # other's); a failed copy keeps the old reference.
        new_atts = []
        for att in clone.get("attachments", []):
            fresh = copy_attachment_file(att.get("stored_as", "")) if isinstance(att, dict) else None
            new_atts.append(dict(att, stored_as=fresh) if fresh else att)
        clone["attachments"] = new_atts
        self.notes.append(clone)
        self.save_notes()
        self.refresh_note_list()
        self.render_calendar()
        self.set_status(f"Duplicated as “{clone['title']}”")
        return clone





    # A small curated set for flagging a day — not the full emoji picker,
    # just quick, common markers (star, alert, celebration, etc.).
    DAY_MARKER_EMOJIS = [
        ("⭐", "#FFD166"), ("❤", "#FF6B6B"), ("❗", "#E63946"), ("🎉", "#FF8FA3"),
        ("✅", "#6BCB77"), ("🔴", "#E63946"), ("🟡", "#FFD166"), ("🟢", "#6BCB77"),
        ("💡", "#FFC145"), ("🎂", "#FF8FA3"), ("✈", "#A0C4FF"), ("📌", "#FFB4A2"),
        ("🔔", "#FFA630"), ("🎁", "#FF8FA3"), ("💰", "#6BCB77"), ("🩺", "#A0C4FF"),
        ("🍽", "#FFB4A2"), ("🚗", "#A0C4FF"),
    ]

    @staticmethod
    def _clean_day_markers(value):
        """A day's markers as kept: up to three non-empty strings, each
        without the emoji variation selector -- older pickers wrote it, Tk
        draws it as a gap, and the picker would not know its own heart --
        and each an emoji's length (MAX_DAY_MARKER_CHARS): a backup's
        markers 100,000 characters long were drawn into the day cells."""
        if isinstance(value, str):
            value = [value]           # the one-marker format older files carry
        if not isinstance(value, list):
            return []
        kept = [without_variation_selector(e) for e in value[:64]
                if isinstance(e, str) and len(e) <= MAX_DAY_MARKER_CHARS]
        return [e for e in kept if e][:3]

    def _load_day_decorations(self):
        """This device's day colours and markers, read at the start through
        _take_day_decorations: settings.json is hand-editable and rides
        inside backups, and one garbage colour reached render_calendar's
        configure() on every launch. What is not kept leaves the file too:
        every settings write carries the whole file, and a million day
        colours made each one take seconds, at every note opened."""
        self.day_colors, self.day_emoji = {}, {}
        saved = load_settings()
        raw_colors, raw_markers = saved.get("day_colors"), saved.get("day_emoji")
        self._take_day_decorations(raw_colors, raw_markers)
        for key, raw, kept in (("day_colors", raw_colors, self.day_colors),
                               ("day_emoji", raw_markers, self.day_emoji)):
            if isinstance(raw, dict) and len(raw) != len(kept):
                save_setting(key, dict(kept))

    def _take_day_decorations(self, colors, markers):
        """Day colours and markers from a settings file -- this device's at
        the start, a backup's on import -- each taken for a day that has
        none yet: a real day (is_calendar_day), a colour sanitize_color
        keeps, markers as _clean_day_markers keeps them, and no more than
        MAX_DAY_DECORATIONS of either.

        Returns:
            How many were taken.
        """
        taken = 0
        for store, raw, clean in ((self.day_colors, colors, sanitize_color),
                                  (self.day_emoji, markers,
                                   self._clean_day_markers)):
            if not isinstance(raw, dict):
                continue
            for day, value in raw.items():
                if len(store) >= MAX_DAY_DECORATIONS:
                    break
                if day in store or not is_calendar_day(day):
                    continue
                kept = clean(value)
                if kept:
                    store[day] = kept
                    taken += 1
        return taken



    def _new_context_menu(self, **options):
        """A fresh right-click menu, and the end of the previous one: none
        was destroyed, and a thousand clicks slowed a theme switch from 80
        ms to 400. Not at tk_popup's return -- on Linux the menu is still
        open then -- but at the next, as only one is ever open.
        """
        old = getattr(self, "_context_menu", None)
        if old is not None:
            try:
                old.destroy()
            except tk.TclError:
                pass
        menu = self._context_menu = tk.Menu(self, **options)
        return menu

    def show_note_context_menu(self, event, note, occurrence_date=None,
                               click_opens=False):
        """A note's right-click menu; from a calendar day (occurrence_date)
        with the repeat's own actions too. ``click_opens``: a click there
        already opens the note (the list), so "Open / Edit" goes; on the
        calendar and History it is the one step to the editor.
        """
        if note is None:
            return
        menu = self._new_context_menu(tearoff=0)
        menu.configure(
            bg=self.colors["card"], fg=self.colors["text"],
            activebackground=self.colors["accent"], activeforeground=self._on_fill("accent"),
            relief="flat", bd=0, font=("Segoe UI", 9)
        )

        # Redundant twice (field reports): a series' day has the two scopes
        # below, and the list's click already opens.
        redundant = (click_opens
                     or (occurrence_date is not None and is_recurring(note)))
        if not redundant:
            menu.add_command(
                label="✏  Open / Edit",
                command=lambda: self._ctx_open(note, occurrence_date,
                                               return_day=occurrence_date)
            )
        pin_label = "📌  Unpin from top" if note.get("pinned") else "📌  Pin to top"
        menu.add_command(label=pin_label, command=lambda: self.toggle_pin(note))

        # One note out as a file: HTML is the complete export, the road to PDF
        # (a browser's Ctrl+P) and to Word; plain text is the body as stored.
        # ISSUES_LOG, smaller lessons: the export menu's comment.
        export_menu = tk.Menu(menu, tearoff=0)
        export_menu.configure(
            bg=self.colors["card"], fg=self.colors["text"],
            activebackground=self.colors["accent"], activeforeground=self._on_fill("accent"),
            relief="flat", bd=0, font=("Segoe UI", 9)
        )
        # From one day of a series, that day as it shows: the series' text
        # went out, none of the day's own words (wave 2, round 4).
        exported = (self._day_as_shown(note, occurrence_date)
                    if occurrence_date and is_recurring(note) else note)
        for fmt, fmt_label in (
                ("html", "Web page (.html) — full formatting; opens in a browser or Word"),
                ("txt", "Plain text (.txt)")):
            export_menu.add_command(
                label=fmt_label,
                command=lambda f=fmt: self.export_note_as_file(exported, f))
        menu.add_cascade(label="💾  Export as file", menu=export_menu)

        # A category here too: unopened, one note's took ticking it first.
        cat_menu = tk.Menu(menu, tearoff=0)
        cat_menu.configure(
            bg=self.colors["card"], fg=self.colors["text"],
            activebackground=self.colors["accent"], activeforeground=self._on_fill("accent"),
            relief="flat", bd=0, font=("Segoe UI", 9)
        )
        current_cat = (note or {}).get("category")
        for cat_name in CATEGORY_COLORS.keys():
            cat_menu.add_command(
                # A tick beside the one it is already in, so the menu answers
                # "which is this?" as well as offering to change it.
                label=("✓  " if cat_name == current_cat else "     ") + cat_name,
                command=lambda c=cat_name: self._ctx_move_to_category(note, c))
        menu.add_cascade(label="🗂  Move to category", menu=cat_menu)

        # Recurrence-specific actions, only meaningful from the calendar.
        if occurrence_date is not None:
            if is_recurring(note):
                menu.add_separator()
                # The day panel's own two buttons, in the same words.
                menu.add_command(
                    label="✏  Edit this day",
                    command=lambda: self._ctx_open(note, occurrence_date,
                                                   return_day=occurrence_date)
                )
                menu.add_command(
                    label="🔁  Edit the whole series",
                    command=lambda: self._ctx_open(note, None,
                                                   return_day=occurrence_date)
                )
                # A moved day has a way back too, with or without text of its
                # own: its reset puts it on its date and asks about the text.
                if moved_from(note, occurrence_date) is not None:
                    menu.add_command(
                        label="↺  Reset this day to the series…",
                        command=lambda: self._reset_occurrence_override(
                            note, occurrence_date)
                    )
                elif occurrence_date in (note.get("overrides") or {}):
                    menu.add_command(
                        label="↺  Reset this day to the series content",
                        command=lambda: self._reset_occurrence_override(
                            note, occurrence_date)
                    )
            else:
                # A plain dated note: offer to turn it into a repeating series.
                menu.add_separator()
                menu.add_command(
                    label="🔁  Make this repeat…",
                    command=lambda: self._ctx_make_recurring(
                        note, return_day=occurrence_date)
                )

        menu.add_separator()
        menu.add_command(
            label="📄  Duplicate",
            command=lambda: self._duplicate_from_menu(note)
        )
        # Named before the click: with no day, Delete takes the whole series.
        # A day's row keeps the plain word, as the scope is still asked.
        delete_label = ("🗑  Delete the whole series"
                        if occurrence_date is None and is_recurring(note)
                        else "🗑  Delete")
        menu.add_command(
            label=delete_label,
            command=(lambda: self._delete_note_from_calendar(note, occurrence_date))
                    if occurrence_date is not None else
                    (lambda: (self._context_delete_note(note, occurrence_date),
                             self.refresh_day_panel()))
        )

        # tk_popup's nested loop let a hover preview draw over the menu
        # (field report); it BLOCKS until dismissed (measured), so the flag
        # holds exactly while the menu shows.
        self.hide_day_tooltip()
        self._context_menu_open = True
        try:
            self._while_native(lambda: menu.tk_popup(event.x_root, event.y_root))
        finally:
            menu.grab_release()
            self._context_menu_open = False

    def toggle_pin(self, note):
        """Flip a note's pinned state and re-sort the list."""
        real = self.find_note(note["id"])
        if real is None:
            return
        real["pinned"] = not real.get("pinned", False)
        self.save_notes()
        self._show_note_moved(real["id"])
        self.set_status("Pinned to top" if real["pinned"] else "Unpinned")

    def _ctx_move_to_category(self, note, category):
        """Change one note's category from its own menu, unasked, as the
        editor's dropdown does: one field, put back by picking again (bulk
        asks, over a mixed set). The flush and the reconciliation are NOT
        optional: the editor's dropdown would save the old one back.
        """
        real = self.find_note((note or {}).get("id"))
        if real is None:
            self.show_info("Not here any more", "That note is no longer in the list.")
            return
        if real.get("category") == category:
            return
        # The editor stays where it is unless it holds this very note, so
        # its own unreadable date is no question for this move to ask.
        if self._flush_autosave(
                leaving=real["id"] == self.selected_note_id) is False:
            return  # gone back to fix a date: nothing moves
        # Re-read after the flush: the note object above was fetched before
        # anything the editor was holding reached the store.
        real = self.find_note(note["id"])
        if real is None:
            return
        real["category"] = category
        self.save_notes()
        self._editor_follows_external_change({real["id"]})
        self._show_note_moved(real["id"])
        # A note with no colour of its own is drawn in its category's, as
        # a dot on its days and a stripe in an open day's list.
        self.render_calendar()
        title = (real.get("title") or "").strip() or "Untitled note"
        self.set_status("Moved “%s” to “%s”"
                        % (_truncate(title, 30), category))

    def _bulk_toggle_pin(self):
        """Pin every ticked note, or unpin them if all are pinned: one button
        always worded as what it will do, as "Select all" is. A mixed
        selection pins, leaving one clear state.
        """
        chosen = [n for n in self.notes if n["id"] in self.selected_note_ids]
        if not chosen:
            self.show_info("Nothing selected", "Tick one or more notes first.")
            return
        # No question, no undo: the same button undoes it.
        pinning = not all(n.get("pinned", False) for n in chosen)
        for note in chosen:
            note["pinned"] = pinning
        self.save_notes()
        self.refresh_note_list()
        self._refresh_bulk_pin_label()
        word = "Pinned" if pinning else "Unpinned"
        self.set_status("%s %d note%s"
                        % (word, len(chosen), "" if len(chosen) == 1 else "s"))

    def _refresh_bulk_pin_label(self):
        """Say what pressing it will do, given what is ticked right now."""
        btn = self._bulk_pin_btn
        if btn is None:
            return
        chosen = [n for n in self.notes if n["id"] in self.selected_note_ids]
        all_pinned = bool(chosen) and all(n.get("pinned", False)
                                          for n in chosen)
        btn.configure(text="📌 Unpin" if all_pinned else "📌 Pin")

    def _ctx_open(self, note, occurrence_date, return_day=None):
        """Open a note in the editor from the context menu. `return_day`
        (raised on a calendar day) keeps the way back, as the day panel's
        Edit does (field report); origin 'edit' keeps Save in the editor.
        """
        self.notebook.select(self.TAB_NOTES)
        # Not opened -- the person went back to the note still in the
        # editor, to fix a date -- means no way back to arm either: it would
        # point at a note never opened.
        if not self._open_unless_shown(note, occurrence_date=occurrence_date):
            return
        if return_day is not None:
            self._pending_calendar_return = {
                "year": self.cal_year, "month": self.cal_month,
                "date_str": return_day, "origin": "edit",
            }
            self._update_calendar_return_button()

    def _ctx_make_recurring(self, note, return_day=None):
        """Open a plain dated note in the editor and focus the Repeat control so
        the user can turn it into a recurring series."""
        self.notebook.select(self.TAB_NOTES)
        if not self._open_unless_shown(note):
            return  # gone back to the note still in the editor: see _ctx_open
        if return_day is not None:
            # Raised on a calendar day — same way-back memory as _ctx_open.
            self._pending_calendar_return = {
                "year": self.cal_year, "month": self.cal_month,
                "date_str": return_day, "origin": "edit",
            }
            self._update_calendar_return_button()
        # Focus to the repeat dropdown, so what to do is plain.
        try:
            self.rec_freq_menu.focus_set()
        except (AttributeError, tk.TclError):
            pass
        self.set_status("Set a repeat frequency to make this note recurring")

    def _reset_occurrence_override(self, note, occurrence_date):
        """Drop one day's own edits so it follows the series again (without
        it, a day kept them forever; field report). A moved day always goes
        back to its rule's date (the owner's call); whether its text goes
        too is asked -- it may be up to date."""
        note = self.find_note(note["id"])
        if note is None:
            return
        origin = moved_from(note, occurrence_date)
        own_text = occurrence_date in (note.get("overrides") or {})
        if origin is None and not own_text:
            return
        if origin is not None and not self._day_is_free(note, occurrence_date, origin):
            # Home only when nothing else is there now (_day_is_free), as on
            # the phone -- and said as it is: a day there, or an edit alone.
            home = parse_date(origin)
            self.show_info(
                "Reset this day",
                f"Another day of this series is on {show_day(home)} now, so this day "
                "stays where it is." if expand_occurrences(note, home, home) == [origin]
                else f"This series keeps text or a colour of its own on {show_day(home)}, "
                "so this day stays where it is.")
            return
        if origin is None:
            if not self.ask_yes_no(
                    "Reset this day",
                    f"Return {show_date(occurrence_date)} to the series content?\n\n"
                    "The separate edits made for this day will be discarded.",
                    icon="warning", default="no"):
                return
            choice = "text"
        else:
            back = show_day(parse_date(origin))
            if own_text:
                choice = self._themed_dialog(
                    "Reset this day",
                    f"Put this day back on {back}?\n\nIts own text can go "
                    "back to the series' content as well, or stay as it is.",
                    kind="question",
                    buttons=[("Cancel", None), ("Only the date", "date"),
                             ("The date and the text", "text")],
                    # Enter keeps the day's own text: the other answer
                    # discards it with no way back.
                    default="Only the date")
            else:
                choice = "date" if self.ask_yes_no(
                    "Reset this day", f"Put this day back on {back}?") else None
            if choice is None:
                return
        if choice == "date":
            # Only the date: the day's text stays its own, and what was typed
            # on it is saved to it first, as a move saves it.
            if (self.selected_note_id == note["id"]
                    and self.current_occurrence_date == occurrence_date
                    and self._flush_autosave(leaving=False) is False):
                return
            note = self.find_note(note["id"])
            if note is None or moved_from(note, occurrence_date) != origin:
                return
            self._relocate_day(note, occurrence_date, origin)
            self.set_status(f"This day is back on {back}")
            return
        showing = (self.selected_note_id == note["id"]
                   and self.current_occurrence_date == occurrence_date)
        carried = {}
        if showing:
            # The day's own edits go; the files and the checklist on screen
            # are the series', and the reload below would fill the editor
            # from a note that never had them (see restore_previous_version).
            self._take_pending_checklist_item()
            self._write_series_owned(note, None, None, schedule=False)
            # Only what no save can store: the day's own edits go, as the
            # question says (see _schedule_to_carry).
            carried = self._schedule_to_carry(unsaved=False)
        note["overrides"].pop(occurrence_date, None)
        if origin is not None:
            # ...and the date goes back with the text: the day is home.
            note["moved"].pop(origin, None)
            # A dead move onto that date goes too, as move_day drops one: the
            # date was found free above, so no live day is moved there, and
            # left, it was two moves onto one date (the audit's round 19).
            for dead in [other for other, new in note["moved"].items() if new == origin]:
                del note["moved"][dead]
        home = origin or occurrence_date
        note["updated"] = now_stamp()
        self.save_notes()
        # If the editor is showing exactly this day, reload it so the
        # series content replaces the dropped override on screen too --
        # where the day is now, the way back to the calendar following it.
        if showing:
            self.load_note(note, home)
            self._put_back_schedule(carried)
            pending = getattr(self, "_pending_calendar_return", None)
            when = parse_date(home)
            if origin is not None and pending is not None and when is not None:
                self._pending_calendar_return = dict(
                    pending, date_str=home, year=when.year, month=when.month)
                self._update_calendar_return_button()
        elif self.selected_note_id == note["id"]:
            # The series on screen counts its days' own edits in its
            # banner, which went on counting this one.
            self._update_occurrence_banner()
        self.refresh_note_list()
        self.render_calendar()
        self.refresh_day_panel()
        self.set_status(f"This day is back on {back} and follows the series again"
                        if origin is not None else
                        "This day follows the series again")

    def _context_delete_note(self, note, occurrence_date=None):
        """Delete triggered from the right-click menu. Routes through the normal
        delete logic so recurring-series scope prompts still apply."""
        # The editor flushed FIRST (going back to a date stops here). Only
        # the note or day on screen replaces it; a waiting repeat turn-off
        # is not made -- made, the day's question offered the whole note.
        leaving = ((note or {}).get("id") == self.selected_note_id
                   and (occurrence_date is None
                        or occurrence_date == self.current_occurrence_date))
        if self._flush_autosave(leaving=leaving, hold_repeat_off=True) is False:
            return
        # The target is a parameter, never the editor's selection: repointed,
        # a Cancel left the autosave writing over the wrong note.
        self._delete_note(note, occurrence_date)

    def show_template_picker(self):
        """Inline picker listing saved templates. Clicking one fills the current
        editor with its contents. Warns before overwriting a note in progress."""
        if not self.templates:
            self.show_info(
                "No templates yet",
                "You don't have any templates. Write a note and use "
                "“🧩 Save as template”, or create one in Settings → Templates.")
            return

        self._dismiss_mini_popup()
        pop = tk.Toplevel(self)
        self._mini_popup = pop
        pop.wm_overrideredirect(True)
        pop.configure(bg=self.colors["accent"])
        frame = tk.Frame(pop, bg=self.colors["card"], padx=8, pady=8)
        frame.pack(padx=1, pady=1)

        head = tk.Frame(frame, bg=self.colors["card"])
        head.pack(fill="x", pady=(0, 6))
        tk.Label(head, text="Use a template", bg=self.colors["card"],
                 fg=self.colors["subtext"], font=("Segoe UI", 9, "bold")).pack(side="left")
        tk.Button(head, text="✕", command=self._dismiss_mini_popup, relief="flat",
                  cursor="hand2", bg=self.colors["card"], fg=self.colors["subtext"],
                  font=("Segoe UI", 9, "bold"), bd=0).pack(side="right")

        # A name drawn whole sized the popup: 300 letters made it wider than
        # any screen, 5,000 passed X's limit. Kept whole, drawn cut. And the
        # list scrolls once it is taller than the window leaves room for.
        name_font = self._cal_font(("Segoe UI", 10))[0]
        rows = self._scrolling_rows(frame, "card", pop).group(every=32)
        for tpl in self.templates:
            name = self._fit_name(tpl.get("name", "Untitled template"),
                                  name_font, self.px(360))
            b = tk.Button(rows.add(), text=f"🧩  {name}", anchor="w",
                          command=lambda t=tpl: self._apply_template(t),
                          relief="flat", cursor="hand2", bg=self.colors["sidebar"],
                          fg=self.colors["text"], font=("Segoe UI", 10))
            b.pack(fill="x", pady=2, ipady=3)
            self._button_choice(b)

        anchor = self.use_template_btn or getattr(self, "editor", self)
        self._place_dropdown_popup(pop, anchor)

    def _apply_template(self, tpl):
        """Fill the editor from a template. A saved note open is left, saved
        first; a new note's unsaved content is asked about before it is
        replaced."""
        tpl = normalize_template(tpl)
        self._dismiss_mini_popup()
        if self.selected_note_id is not None:
            # A saved note is left, its last words saved, as Ctrl+N does:
            # "Replace current note?" lost them.
            if self._flush_autosave() is False:
                return
            has_content = False
        else:
            try:
                # The shared test, so a checklist, attachments, a repeat rule
                # or an item in the Add box also earn the "replace?" question:
                # the Add box alone was dropped unasked (round 6).
                has_content = self._editor_holds_typing()
            except Exception:  # noqa: BLE001 -- not knowing asks, never replaces
                self._log_swallowed("template: blank editor")
                has_content = True

        if has_content:
            if not self.ask_yes_no(
                "Replace current note?",
                "This will replace what's currently in the editor with the "
                "template. Any unsaved changes here will be lost. Continue?",
                icon="warning", default="no"):
                return

        # Start a fresh note, then fill it from the template -- on the day a
        # new note was started from on the calendar, with its way back: the
        # template threw the day away, and the note never showed on it.
        day, pending = "", None
        if self.selected_note_id is None:
            day = self._typed_date()
            pending = getattr(self, "_pending_calendar_return", None)
        self.new_note()
        self.selected_note_id = None
        if day:
            self._show_date_in_field(day)
        if pending is not None:
            self._pending_calendar_return = pending
            self._update_calendar_return_button()
        if tpl.get("title"):
            self.title_entry.delete(0, "end")
            self._insert_title(tpl["title"])
            self.title_entry.config(fg=self.colors["text"])
        if tpl.get("body"):
            self.body_text.delete("1.0", "end")
            self.body_text.insert("1.0", tpl["body"])
            self._apply_formatting(self.body_text, tpl.get("formatting", []))
            self._apply_paragraphs(self.body_text, tpl.get("paragraphs", []))
            # A template's table is drawn, as an import's is.
            self._render_table_grids()
        if tpl.get("comments"):
            self.comments_text.delete("1.0", "end")
            self.comments_text.insert("1.0", tpl["comments"])
        category = tpl.get("category") or "General"
        if category in CATEGORY_COLORS:
            self.category_var.set(category)
            self._update_color_swatch()
        # Bring the template's checklist along.
        self._working_checklist = [
            {"text": it.get("text", ""), "done": bool(it.get("done"))}
            for it in tpl.get("checklist", []) if isinstance(it, dict)
        ]
        if hasattr(self, "_checklist_rows"):
            self._render_checklist_items()
        # If the template has checklist items, open the section so they're
        # visible right away instead of hidden behind the button.
        if self._working_checklist and not self._checklist_open:
            self.toggle_checklist_section()
        else:
            self._sync_checklist_open_state()
        self._sync_calculator_open_state()
        self.update_word_count()
        self._refresh_format_buttons()
        self.set_status("New note started from template — edits here won't change the template")
        self._reset_text_undo()

    def _paste_table_aware(self, text_widget):
        """Paste for a plain text box that should still understand tables
        (the template editor's): an HTML table becomes pipe text, as in the
        editor; a markdown table's separator goes in at its minimum
        (_foreign_plain); anything else is the normal paste.
        """
        try:
            html = clipboard.read_html()
        except Exception:
            html = None
        if html and "<table" in html.lower():
            cut = {}
            try:
                text, _spans, _paras = html_to_note(html, report=cut)
            except Exception:
                return None
            if core_tables.find_blocks(text):
                try:
                    text_widget.delete("sel.first", "sel.last")
                except tk.TclError:
                    pass
                text_widget.insert("insert", text)
                self._say_if_paste_was_cut(cut)
                return "break"
        # A markdown table's separator at its minimum (_foreign_plain), and
        # the paste ceiling kept: Tk's own would put all of it in.
        raw, cut = self._clipboard_text(text_widget)
        if raw is None:
            return None
        text = self._foreign_plain(raw)
        if not cut and text == raw.replace("\r\n", "\n").replace("\r", "\n"):
            return None
        try:
            text_widget.delete("sel.first", "sel.last")
        except tk.TclError:
            pass
        text_widget.insert("insert", text)
        if cut:
            self._say_if_paste_was_cut({"text_cut": True})
        return "break"

    def _templates_full(self, name, replacing=None):
        """Whether a new template called *name* would pass MAX_TEMPLATES --
        and if so, that is said. One that replaces another of that name, or
        *replacing* itself, adds none. The doors refuse what a start would
        not keep (load_templates)."""
        if len(self.templates) < MAX_TEMPLATES or any(
                t is replacing or t.get("name") == name for t in self.templates):
            return False
        self.show_info(
            "Too many templates",
            f"You already have {MAX_TEMPLATES:,} templates, which is the most "
            "the app keeps. Delete one first.")
        return True

    def _checklist_full(self, items, text, waits=False):
        """Whether *items* already hold MAX_CHECKLIST_ITEMS -- and if so, that
        *text* was not added is said. The doors refuse what a start would
        cut (normalize_note): the 1,001st item was drawn and saved, then gone
        without a word at the next start (round 6 of the final audit).
        *waits*: the uid of the note whose Add box the words were taken from
        on the way out, and wait for (_take_pending_checklist_item)."""
        if len(items) < MAX_CHECKLIST_ITEMS:
            return False
        # The window's close asks once about every item left waiting instead.
        if not (getattr(self, "_ending_session", False)
                or getattr(self, "_closing_window", False)):
            self.show_info(
                "Checklist full",
                f"A checklist can have up to {MAX_CHECKLIST_ITEMS:,} items, and "
                f"this one has them all, so “{one_line(text, 80)}” was not "
                + ("added. It waits in this note's Add box until you delete an "
                   "item to make room, while Note Organizer stays open."
                   if waits else "added. Delete an item to make room."))
            # Remembered as said only once it is: marked before, words a
            # cancelled sign-out took were never said at all (round 9).
            if waits:
                self._waiting_said[waits] = text
        return True

    def save_current_as_template(self):
        """Save the current editor content as a reusable template. Asks for a
        template name inline, then stores title/body/comments/category."""
        try:
            st = self.capture_editor_state()
        except Exception:
            st = {}
        # An item typed in the checklist's Add box and not yet added goes into
        # the template too; the box keeps it for the note, which leaving adds
        # it to (_take_pending_checklist_item).
        var = getattr(self, "checklist_add_var", None)
        pending = var.get().strip()[:MAX_CHECKLIST_ITEM_CHARS] if var is not None else ""
        if pending and not self._checklist_full(st.get("checklist") or [], pending):
            st["checklist"] = list(st.get("checklist") or []) + [
                {"text": pending, "done": False}]
        title = (st.get("title") or "").strip()
        body = (st.get("body") or "").strip()
        comments = (st.get("comments") or "").strip()
        # NARROWER than _editor_state_has_content: a template keeps title,
        # body, comments and checklist only (a checklist alone was refused).
        if not (title or body or comments or st.get("checklist")):
            self.show_info(
                "Nothing to save",
                "A template keeps a note's title, text, comments and "
                "checklist — this note has none of those yet.")
            return

        default_name = title[:30] if title else "My template"

        def do_save(name):
            name = name.strip()
            if not name:
                return False  # keep the box open
            if self._templates_full(name):
                return True
            if any(t.get("name") == name for t in self.templates):
                # Never overwrite silently: the same name may hold
                # entirely different content someone still needs.
                if not self.ask_yes_no(
                        "Template name taken",
                        f"You already have a template named “{one_line(name, 200)}”.\n\n"
                        "Replace the old template with this one?\n"
                        "Choose No to give this one another name.",
                        icon="warning", default="no"):
                    return False  # keep the box open for a new name
            tpl = normalize_template({
                "name": name,
                "title": st.get("title", ""),
                "body": st.get("body", ""),
                "formatting": st.get("formatting", []),
                "paragraphs": st.get("paragraphs", []),
                "comments": st.get("comments", ""),
                "category": st.get("category", "General"),
                "checklist": st.get("checklist", []),
            })
            # If a template with this name exists, overwrite it.
            self.templates = [t for t in self.templates if t.get("name") != name]
            self.templates.append(tpl)
            save_templates(self.templates)
            self.set_status(f"Saved template “{one_line(name, 200)}”")
            refresh = getattr(self, "_refresh_templates_panel", None)
            if callable(refresh):
                try:
                    refresh()
                except tk.TclError:
                    self._refresh_templates_panel = None
            return True

        anchor = getattr(self, "editor", self)
        # The editor's name box keeps the note title's 200; this one took a
        # pasted page, and the picker drawn from it passed X's limit.
        self._show_inline_rename(anchor, default_name, do_save,
                                 limit=(self.TITLE_MAX_LEN, "A template name"))

    def duplicate_current_note(self):
        """Duplicate the note currently open in the editor. Duplicates the SAVED
        version — if there are unsaved edits, offer to save them first so the
        copy reflects what the user sees."""
        if self.selected_note_id is None:
            self.show_info(
                "Save first",
                "This note hasn't been saved yet. Save it, then you can duplicate it."
            )
            return
        note = self.find_note(self.selected_note_id)
        if note is None:
            self.show_info("Nothing to duplicate", "No saved note is open.")
            return
        note = self._note_to_duplicate(note)
        if note is None:
            return
        clone = self.duplicate_note(note)
        # Open the fresh copy so the user can edit it right away.
        if clone is not None:
            self.open_note_in_tab(clone)

    def _note_to_duplicate(self, note):
        """The stored note a duplicate copies -- or None for Cancel. With
        this note open and unsaved, that is said and the person chooses: the
        right-click Duplicate copied the stored one, a new file missing."""
        if note.get("id") != self.selected_note_id:
            return note
        st = self.capture_editor_state()
        if self.editor_state_matches_saved(st):
            return note
        choice = self.ask_yes_no_cancel(
            "Unsaved changes",
            "This note has unsaved changes. Save them before duplicating?\n\n"
            "Yes = save, then duplicate\n"
            "No = duplicate the last saved version\n"
            "Cancel = do nothing"
        )
        if choice is None:
            return None
        if choice:
            self.save_current_note()
            # The note the question was about, saved: not whichever one
            # the editor holds after the answer.
            return self.find_note(note["id"])
        return note

    def _duplicate_from_menu(self, note):
        """A right-click Duplicate: the note as stored, after the same
        question about unsaved changes as the editor's own Duplicate."""
        note = self._note_to_duplicate(note)
        if note is not None:
            self.duplicate_note(note)
            self.refresh_day_panel()

    def find_note(self, note_id):
        """The note with this id, or None."""
        return core_find_note(self.notes, note_id)

    # ---------- Category management ----------
    def count_notes_in_category(self, name):
        """How many notes use this category, per-occurrence overrides included."""
        return core_count_in_category(self.notes, name)

    def rename_category_everywhere(self, old_name, new_name):
        """Rewrite every reference to a category when it is renamed."""
        self._refile_category_everywhere(old_name, new_name, renamed=True)

    def reassign_category_everywhere(self, old_name, new_name):
        """Move every note from one category to another.

        Kept distinct from rename_category_everywhere despite doing the same
        thing: the call sites read very differently -- one is the user
        renaming a category, the other is a category being deleted and its
        notes being kept.
        """
        self._refile_category_everywhere(old_name, new_name, renamed=False)

    def _refile_category_everywhere(self, old_name, new_name, renamed):
        """Every holder of a category's name, moved to another: the editor's
        box, templates, the Trash and the fold kept the old one. A rename
        carries the fold, filter and box with it; a deletion
        (``renamed=False``) only lets go of the old name.
        """
        # The rewrite reaches rescue copies too ("↩ Restore previous" puts a
        # category back), where a Trash entry may hold the name alone.
        core_rename_category(self.notes, old_name, new_name)
        trashed = [e for e in self.trash if isinstance(e, dict)]
        if core_rename_category(trashed, old_name, new_name):
            save_trash(self.trash)
        moved_templates = False
        for tpl in self.templates:
            if isinstance(tpl, dict) and tpl.get("category") == old_name:
                tpl["category"] = new_name
                moved_templates = True
        if moved_templates:
            save_templates(self.templates)
        if old_name in self.collapsed_groups:
            self.collapsed_groups.discard(old_name)
            if renamed:
                self.collapsed_groups.add(new_name)
            save_setting("collapsed_groups", sorted(self.collapsed_groups))
        if renamed:
            if self.category_var.get() == old_name:
                self.category_var.set(new_name)
            var = self.filter_var
            if var is not None and var.get() == old_name:
                var.set(new_name)
        # A category move's Undo is carried by a rename, and withdrawn when
        # the category they went into goes; one they came from it reports.
        offer = getattr(self, "_category_undo_offer", None)
        if offer is not None:
            on_screen = self._toast_action is offer["action"]
            if renamed:
                if offer["applied"] == old_name:
                    offer["applied"] = new_name
                offer["marks"] = [
                    (mark[0], new_name if mark[1] == old_name else mark[1]) + tuple(mark[2:])
                    for mark in offer["marks"]]
                if on_screen:
                    self._offer_category_undo(offer)
            elif offer["applied"] == old_name:
                self._category_undo_offer = None
                if on_screen:
                    self._toast_action = None
                    self._hide_toast()

    def _offer_category_undo(self, offer):
        """Show the banner offering to undo a category move.

        *offer* is one record -- ``marks`` (one per note: id, the category it
        left, its old stamp, its uid) and ``applied``, the category it went
        into -- and the Undo reads it when clicked, so a rename made while
        the banner is up carries it along (_refile_category_everywhere)."""
        if "action" not in offer:
            offer["action"] = lambda: self._undo_bulk_category(
                offer["marks"], offer["applied"])
        self._category_undo_offer = offer
        count = len(offer["marks"])
        self._show_toast(
            f"Moved {count} {'note' if count == 1 else 'notes'} to "
            f"“{offer['applied']}”",
            action=offer["action"])

    def refresh_category_widgets(self):
        """Push the current category set into the editor dropdown and the
        sidebar filter, without disrupting a still-valid selection."""
        # The custom category dropdown reads CATEGORY_COLORS live when opened, so
        # it needs no values push here — just keep the selection valid + refresh
        # the button's dot/label.
        if self.category_var.get() not in CATEGORY_COLORS:
            self.category_var.set(PROTECTED_CATEGORY)
        self._refresh_category_button_safe()

        # The category filter dropdown reads CATEGORY_COLORS live when opened,
        # so no values push is needed — just keep the selection valid.
        self._keep_filter_valid()




    def _update_restore_button(self):
        """Show the Restore-previous button only when the open note has a
        recoverable previous version, on the action grid's row under its
        buttons (_place_restore_button)."""
        if not hasattr(self, "restore_prev_btn"):
            return
        note = self.find_note(self.selected_note_id) if self.selected_note_id else None
        has_prev = bool(note and note.get("_prev"))
        if has_prev and not self._is_placed(self.restore_prev_btn):
            self._place_restore_button()
        elif not has_prev and self._is_placed(self.restore_prev_btn):
            self.restore_prev_btn.grid_forget()

    def _place_restore_button(self):
        """Restore previous, on the first row under the action buttons and
        across all their columns: the row it takes moves with how many
        columns they are dealt into, or it lands on top of one."""
        cols = self._action_cols or 3
        self.restore_prev_btn.grid(
            row=-(-len(self._action_buttons) // cols), column=0, columnspan=cols,
            sticky="w", padx=(0, 8), pady=(0, 6), ipadx=10, ipady=5)

    def _grid_action_buttons(self, cols):
        """Deal the editor's six action buttons into *cols* equal columns,
        in the order Tab walks them, and Restore previous, when it shows,
        under them."""
        row = self._action_row
        for c in range(3):
            row.grid_columnconfigure(c, weight=1 if c < cols else 0,
                                     uniform="editbtn" if c < cols else "")
        for i, btn in enumerate(self._action_buttons):
            r, c = divmod(i, cols)
            btn.grid(row=r, column=c, sticky="ew", padx=(0, 8), pady=(0, 6), ipady=5)
        self._action_cols = cols
        restore = getattr(self, "restore_prev_btn", None)
        if restore is not None and self._is_placed(restore):
            self._place_restore_button()

    def _reflow_action_buttons(self, event=None):
        """Three equal columns while the row has room for three of its widest
        button, else two, else one (see where they are built). Counted from
        the buttons' own widths, which do not change with the columns they
        are in, so the dealing cannot undo itself."""
        row = self._action_row
        room = row.winfo_width()
        if room <= 1:
            return
        # 8: each button's padding on its right, as gridded.
        widest = max(b.winfo_reqwidth() for b in self._action_buttons) + 8
        cols = 3 if 3 * widest <= room else 2 if 2 * widest <= room else 1
        if cols != self._action_cols:
            self._grid_action_buttons(cols)

    # What "↩ Restore previous" brings back beyond the text, worded: the
    # fields an update replaces past PREV_TEXT_FIELDS (test_data_safety).
    _PREV_EXTRA_LABELS = (
        ("checklist", "checklist"), ("date", "date"),
        ("recurrence", "repeat rule"), ("color", "colour"),
        ("category", "category"), ("overrides", "per-day edits"),
        ("exceptions", "skipped days"), ("moved", "moved days"),
        ("pinned", "pin"),
    )

    def restore_previous_version(self):
        """Bring back the rescue copy: the text a drastic shortening
        replaced, or everything an update from a share code or backup
        replaced."""
        # A pending autosave runs first: run under the question, it made a
        # rescue copy the restore then dropped, the words in no file.
        if getattr(self, "_autosave_job", None) is not None:
            self._autosave_now()
        note = self.find_note(self.selected_note_id) if self.selected_note_id else None
        if not (note and note.get("_prev")):
            return
        prev = note["_prev"]
        # Looking at ONE DAY of a series, say so: the rescue copy is of
        # the note itself, so restoring it changes the whole series, and
        # a per-day edit on the day being viewed keeps showing instead.
        viewing_occurrence = bool(self.current_occurrence_date
                                  and is_recurring(note))
        extra = ("\n\nThis note repeats, and the earlier version is of the "
                 "whole note — not just the day you are looking at."
                 if viewing_occurrence else "")
        # A shrink's copy is the text; an update's holds all it replaced
        # (apply_shared_update), and the question names all of it.
        also = [label for key, label in self._PREV_EXTRA_LABELS
                if key in prev]
        if also:
            question = (
                "Bring back this note as it was before it was updated? "
                "Its text comes back, and so do its "
                + ", ".join(also[:-1])
                + (" and " if len(also) > 1 else "") + also[-1]
                + ". What the note holds now will be replaced.")
        else:
            question = ("Bring back the earlier version of this note's text? "
                        "The current text will be replaced.")
        # ...and kept, when it holds anything the earlier version lacks:
        # said only then, as only then is it true.
        if copy_replaced_by_restore(note, prev) is not None:
            question += (" It is kept in its turn, so \u201c\u21a9 Restore "
                         "previous\u201d brings it back.")
        occurrence = self.current_occurrence_date
        if not self.ask_yes_no(
            "Restore previous version", question + extra,
            icon="warning", default="no"
        ):
            return
        # The note named is restored; the editor is filled only if it still
        # holds it, or the text went into ANOTHER note.
        in_editor = self.selected_note_id == note["id"]
        # A date or repeat value the note does not store -- left out, or not
        # saved yet -- is carried across the reload below, unless the
        # rescue copy brings back its own.
        carried = (self._schedule_to_carry(date="date" not in prev,
                                           repeat="recurrence" not in prev)
                   if in_editor else {})
        if in_editor:
            # The editor's files and checklist (an Add box item too) are
            # stored first, or the reload lost a new file; a copy holding
            # them still wins, applied after.
            self._take_pending_checklist_item()
            self._write_series_owned(note, None, None, schedule=False)
            # The previous content back in, a pending style cleared first
            # (the insert hook would take it for typing).
            self._pending_styles = set()
            self._pending_text_color = None
            self._pending_font_size = None
            self._pending_font_family = None
            self._pending_highlight_color = None
            self.title_entry.delete(0, "end")
            self._insert_title(prev.get("title", ""))
            self.title_entry.config(fg=self.colors["text"])
            self.body_text.delete("1.0", "end")
            self.body_text.insert("1.0", prev.get("body", ""))
            self._apply_formatting(self.body_text, prev.get("formatting", []))
            self._apply_paragraphs(self.body_text, prev.get("paragraphs", []))
            # Mirror restore_editor_state's tail: this was the one body-
            # loader that skipped the redraw, so a restored table came back
            # as raw pipe rows and the word count described the old text.
            self._render_table_grids()
            self._refresh_format_buttons()
            self.comments_text.delete("1.0", "end")
            self.comments_text.insert("1.0", prev.get("comments", ""))
        # Written onto the NOTE, not through the editor's save, which puts a
        # day's text on that day: the series stayed shortened, its copy
        # spent. What it replaces becomes the copy (copy_replaced_by_restore).
        replaced = copy_replaced_by_restore(note, prev)
        note["title"] = prev.get("title", "")
        note["body"] = with_caret_line(prev.get("body", ""))
        note["comments"] = prev.get("comments", "")
        note["formatting"] = normalize_formatting(prev.get("formatting", []))
        note["paragraphs"] = normalize_paragraphs(
            prev.get("paragraphs", []), len(note["body"].split("\n")))
        # ...and the rest the update replaced; a category deleted since
        # comes back as General, as normalize_note files it.
        for key, _label in self._PREV_EXTRA_LABELS:
            if key in prev:
                note[key] = copy.deepcopy(prev[key])
        if note.get("category") not in CATEGORY_COLORS:
            note["category"] = "General"
        # The days it brings back follow the same rule: a day filed under
        # a category that is gone came back under that dead name, and the
        # next launch re-created the category from it.
        for patch in (note.get("overrides") or {}).values():
            if (isinstance(patch, dict) and "category" in patch
                    and patch["category"] not in CATEGORY_COLORS):
                patch["category"] = "General"
        # An older rule brought back can give a date a day was moved onto
        # since: that move goes now, not at the next start (round 16).
        drop_hidden_moves(note)
        if replaced is None:
            note.pop("_prev", None)
        else:
            note["_prev"] = replaced
        # Seconds, as save_current_note stamps: by the minute it sorted
        # below notes touched earlier that minute.
        note["updated"] = now_stamp()
        self.save_notes()
        # Reload from the note so the editor and the dirty machinery agree
        # with what is now on disk (the widgets above were filled for the
        # user to see; this makes them the note's official state).
        if in_editor:
            self.load_note(note, occurrence_date=occurrence)
            self._put_back_schedule(carried)
        self.refresh_note_list()
        # The rescue copy can bring back a date, a repeat, a colour, a
        # category and a series' days -- all of them drawn on the calendar,
        # which this was the one note-writing route never to redraw.
        self.render_calendar()
        self.set_status(
            "Restored the previous version of the whole note"
            if viewing_occurrence else "Restored the previous version")
        self.update_word_count()
        self._update_restore_button()

    def _date_and_repeat_to_store(self):
        """What a save can store from the date and repeat fields, and what it
        leaves out: ``(date, rule, left_out)``. An unreadable date (read_date)
        or repeat value (_unreadable_repeat_fields), or a repeat with no
        start, keeps the note's value -- it vetoed the WHOLE save, losing the
        words after it. The save, its question, summary and reloads ask here.
        """
        note = (self.find_note(self.selected_note_id)
                if self.selected_note_id is not None else None)
        kept_date = (note or {}).get("date") or ""
        kept_rule = normalize_recurrence((note or {}).get("recurrence"))
        left_out = []

        typed = self._typed_date()
        day = read_date(typed)
        # Stored in the one form, however it was typed: 17.10.2026 and
        # "17 oct 2026" both reach the note as 2026-10-17.
        date_value = format_date(day) if day else typed
        if typed and day is None:
            # The note's own date, readable or not, is no loss: one arrived
            # unreadable asked at every leaving, untouched.
            if not same_date(typed, kept_date):
                left_out.append(f"the date “{typed}” "
                                "(write dates like 30.09.2026)")
            date_value = kept_date

        rule = self.read_recurrence_from_ui()
        # An unreadable repeat value is left out as a date is: read as 1,
        # "After abc times" dropped every later day off the calendar.
        for field, typed in self._unreadable_repeat_fields(rule["freq"]):
            if field == "end":
                left_out.append(f"the repeat's end date “{typed}” "
                                "(write dates like 31.12.2026)")
                rule = normalize_recurrence(dict(
                    rule, end=kept_rule["end"], count=kept_rule["count"]))
            elif field == "every":
                left_out.append(f"the repeat's “Every {typed}” "
                                "(write a whole number, like 2)")
                rule = normalize_recurrence(dict(
                    rule, interval=kept_rule["interval"]))
            elif field == "after":
                left_out.append(f"the repeat's “After {typed} times” "
                                "(write a whole number, like 10)")
                rule = normalize_recurrence(dict(
                    rule, end=kept_rule["end"], count=kept_rule["count"]))
            else:
                left_out.append(f"the repeat's day(s) “{typed}” "
                                "(write days of the month, like 1, 15)")
                rule = normalize_recurrence(dict(
                    rule, month_days=kept_rule["month_days"]))

        if rule["freq"] and not parse_date(date_value):
            if parse_date(kept_date):
                # Most often the date was cleared on the way to typing a
                # new one: the series keeps the day it already starts on.
                left_out.append("the cleared date (a repeating note needs "
                                "a start date, so it still starts "
                                f"{show_date(kept_date)})")
                date_value = kept_date
            else:
                left_out.append("the repeat (a repeating note needs a "
                                "start date)")
                rule = normalize_recurrence({})
        # A turn-off over days with edits waits for a save someone asked for
        # (_holds_repeat_off): it moves them to the rescue copy. Left out as
        # unreadable is, with its date, which would move the whole series.
        if getattr(self, "_holding_repeat_off", False) and self._repeat_off_waits():
            what = "turning the repeat off"
            if date_value != kept_date:
                what += (f" and the date “{show_date(date_value)}”" if date_value
                         else " and clearing the date")
                date_value = kept_date
            left_out.append(what + self._HELD_TAIL)
            rule = kept_rule
        return date_value, rule, left_out

    # What a held turn-off's words in the status line end with.
    _HELD_TAIL = " (saved when you leave the note or press Save)"

    def _unreadable_repeat_fields(self, freq):
        """The repeat's typed values the app cannot store, as (field, typed):
        "end" (empty: never ends), "every", "after", "days" (blank: the
        start's day). The one judgement the save, the summary and the
        reloads ask (judged apart, the end previewed a series without one)."""
        problems = []
        if not freq:
            return problems
        mode = self.rec_end_mode_var.get()
        if mode == "on":
            end = self.rec_end_date_var.get().strip()
            # Read as normalize_recurrence reads it, so what is named here
            # as not understood and what the rule keeps cannot disagree.
            if end and not read_date(end):
                problems.append(("end", end))
        every = self.rec_interval_var.get().strip()
        if not _whole_number(every):
            problems.append(("every", every))
        if mode == "after":
            times = self.rec_count_var.get().strip()
            if not _whole_number(times):
                problems.append(("after", times))
        if freq == "monthly":
            days = self.rec_monthdays_var.get()
            chunks = [c.strip() for c in days.replace(";", ",").split(",")]
            if any(c and not _is_month_day(c) for c in chunks):
                problems.append(("days", days.strip()))
        return problems

    def _schedule_to_carry(self, date=True, repeat=True, unsaved=True):
        """What the date and repeat fields hold that the note does not, each
        where it differs, carried across a reload ({} when none; Restore
        previous overwrote them). Never asked first (qa7). *date* / *repeat*
        False: the reload brings its own. *unsaved* False: only what no save
        stores (Reset this day's kept date moved the series).
        """
        try:
            date_value, rule, left_out = self._date_and_repeat_to_store()
        except Exception:
            self._log_swallowed("reload: date and repeat check")
            return {}
        note = (self.find_note(self.selected_note_id)
                if self.selected_note_id is not None else None)
        if note is None:
            return {}
        carried = {}
        typed = self._typed_date()
        # By the day the text names: the field shows 17.10.2026 for the
        # 2026-10-17 a save stores, and that is no difference to carry.
        if date and (not same_date(typed, date_value or "")
                     or (unsaved and (date_value or "")
                         != (note.get("date") or ""))):
            carried["date"] = typed
        freq = self.selected_freq_key()
        unreadable = self._unreadable_repeat_fields(freq)
        stored = normalize_recurrence(note.get("recurrence"))
        # A value it cannot read, the whole repeat left out for want of a
        # start date, or (with *unsaved*) a rule not saved yet.
        if repeat and (unreadable or (freq and not rule["freq"])
                       or (unsaved and rule != stored)):
            boxes = {
                "freq": self.rec_freq_var.get(),
                "interval": self.rec_interval_var.get(),
                "weekdays": list(self.rec_weekday_state),
                "month_days": self.rec_monthdays_var.get(),
                "policy": self.rec_policy_var.get(),
                "end_mode": self.rec_end_mode_var.get(),
                "end": self.rec_end_date_var.get(),
                "count": self.rec_count_var.get(),
            }
            if not unsaved:
                # Only unstorable boxes over the note's own rule, none if typed
                # for another: whole, they carried readable changes along.
                ending = ("after" if stored["count"]
                          else "on" if stored["end"] else "never")
                boxes = ({self._REPEAT_BOX[field]: boxes[self._REPEAT_BOX[field]]
                          for field, _typed in unreadable}
                         if freq == stored["freq"]
                         and boxes["end_mode"] == ending else {})
            if boxes:
                carried["repeat"] = boxes
                # A turn-off carries its record of the copy made while it
                # waited (_turn_off_rescue_copy), or its copy replaced that.
                if not freq and getattr(self, "_held_text_rescue", None) is not None:
                    carried["held_rescue"] = self._held_text_rescue
        return carried

    # The box each of _unreadable_repeat_fields' values is typed in, as
    # _schedule_to_carry names it.
    _REPEAT_BOX = {"every": "interval", "after": "count", "end": "end",
                   "days": "month_days"}

    def _put_back_schedule(self, carried):
        """Show again what _schedule_to_carry carried across a reload; the
        summary line then says what is not understood, and leaving asks or
        saves. A repeat carried in part -- the boxes no save can store --
        lands on the rule the reload wrote, the rest of it left as is."""
        if not carried:
            return
        if "date" in carried:
            self._show_date_in_field(carried["date"])
        rep = carried.get("repeat")
        if rep:
            for key, var in (("freq", self.rec_freq_var),
                             ("interval", self.rec_interval_var),
                             ("month_days", self.rec_monthdays_var),
                             ("policy", self.rec_policy_var),
                             ("end_mode", self.rec_end_mode_var),
                             ("end", self.rec_end_date_var),
                             ("count", self.rec_count_var)):
                if key in rep:
                    var.set(rep[key])
            if "weekdays" in rep:
                self.rec_weekday_state = list(rep["weekdays"])
            self.refresh_weekday_buttons()
            self.on_end_mode_changed()
            self.on_recurrence_changed()
        else:
            self.update_recurrence_summary()
        if "held_rescue" in carried:
            self._held_text_rescue = carried["held_rescue"]

    def _left_out_message(self, left_out,
                          lead="Everything else in this note is saved, but not:"):
        """The words for what a save could not store (see
        _date_and_repeat_to_store) -- one list, whoever is asking."""
        return lead + "\n\n" + "\n".join(f"• {item}" for item in left_out)

    def _put_back_stored_date_and_repeat(self):
        """Show the date and repeat the note has on disk, over whatever the
        save had to leave out -- what "Continue without it" means, so the
        editor agrees with the note again and nothing reads as unsaved."""
        note = (self.find_note(self.selected_note_id)
                if self.selected_note_id is not None else None)
        self._show_date_in_field((note or {}).get("date"))
        self.write_recurrence_to_ui((note or {}).get("recurrence"))
        # Nothing left out: the status line drops it now, as a route that
        # stays cancels the next autosave tick.
        self._say_nothing_is_left_out()

    # Said when a turn-off's rescue copy takes the days' text, and by an
    # update replacing a copy still needed: one copy a note.
    _REPLACES_EARLIER_RESCUE = (
        "\nThe earlier version “↩ Restore previous” holds for this note now is "
        "replaced by the one from before this update.")

    @staticmethod
    def _holds_unspent_rescue(note):
        """Whether *note* holds a rescue copy with something the note lacks."""
        return isinstance(note.get("_prev"), dict) and not rescue_copy_spent(note)

    _REPEAT_OFF_KEPT = (" — the repeat is off; ↩ Restore previous brings it "
                        "back with every day's own text")
    _REPEAT_OFF_UPDATE_KEPT = (" — the repeat is off; ↩ Restore previous brings "
                               "back the note as it was before it was updated")
    _REPEAT_OFF_NO_COPY = " — the repeat is off; every day's own text stays in the note"

    def _repeat_off_line(self, note):
        """What the status line says of a turn-off: the copy it kept is the
        series, or -- after an import's Update -- the note as it was before
        that, which Restore previous then brings back instead (round 9). A
        copy the note holds again in full is dropped by the same save, so no
        Restore previous is promised for it (round 10)."""
        if not self._holds_unspent_rescue(note):
            return self._REPEAT_OFF_NO_COPY
        return (self._REPEAT_OFF_UPDATE_KEPT if update_copy(note.get("_prev"))
                else self._REPEAT_OFF_KEPT)

    def _repeat_off_loses_days(self, note, recurrence):
        """Whether a save writing *recurrence* turns *note*'s repeat off
        while a day of it holds text of its own -- which goes with the
        repeat. A day differing only in its colour or category loses no
        text."""
        if not is_recurring(note) or recurrence.get("freq"):
            return False
        return self._days_hold_own_text(note)

    def _days_kept_off_repeat(self, note):
        """Whether the save that ends *note*'s repeat, or keeps it off, keeps
        its days: when any of them holds text of its own. The rescue copy
        takes a copy of them, but it is one slot, and days only there were
        erased by the next copy made (2026-10-28, the final audit). Kept,
        they also come back if the repeat does."""
        return self._days_hold_own_text(note)

    @staticmethod
    def _days_hold_own_text(note):
        """Whether a day of *note* shows a title, text or comments of its
        own."""
        # A day just deleted is not counted (its Undo says it cannot come
        # back): counted, its copy replaced the note's own. The core's answer
        # (core.model._days_back_from_copy asks it too).
        return days_hold_own_text(note)

    @staticmethod
    def _whole_note_rescue_copy(note):
        """*note* as it is -- its text, and the date, repeat and days a
        save is about to take away -- as the rescue copy "↩ Restore
        previous" puts back whole (_PREV_EXTRA_LABELS)."""
        prev = {
            "title": note.get("title") or "",
            "body": note.get("body") or "",
            "formatting": copy.deepcopy(note.get("formatting") or []),
            "paragraphs": copy.deepcopy(note.get("paragraphs") or []),
            "comments": note.get("comments") or "",
        }
        for key in ("date", "recurrence", "exceptions", "overrides", "moved"):
            prev[key] = copy.deepcopy(note.get(key))
        return prev

    # The text fields a rescue copy of text alone holds.
    _RESCUE_TEXT_KEYS = ("title", "body", "formatting", "paragraphs", "comments")

    def _turn_off_rescue_copy(self, note, takes_text=False):
        """The rescue copy a repeat's turn-off makes: *note* whole, repeat
        and days (_whole_note_rescue_copy). *takes_text*: this save takes
        text too, the note's being the newest. Any copy but an Update's whose
        words the note lost gives its text to it -- a big delete's copy was
        replaced, either order -- so Restore previous brings both back."""
        existing = note.get("_prev")
        # An Update's copy is kept whole even when this save takes text away:
        # that text becomes a note of its own instead (wave 2, round 5).
        if takes_text and update_copy(existing) and not rescue_copy_spent(note):
            self._keep_text_aside(note)
            takes_text = False
        # Another series' copy, replaced here, held its days alone: they are
        # set aside, to be notes of their own (round 15) -- not an Update's
        # copy this turn-off keeps whole (round 17).
        if takes_text or not (update_copy(existing) and not rescue_copy_spent(note)):
            copy_days_set_aside(note)
        prev = self._whole_note_rescue_copy(note)
        held = getattr(self, "_held_text_rescue", None)
        self._held_text_rescue = None
        if takes_text:
            pass                # the newest text, whatever an older copy holds
        elif update_copy(existing) and not rescue_copy_spent(note):
            # An import's Update left the note as it was here before, in no
            # other file: kept whole, given the series where it lacks it --
            # before the held branch, which kept only its words (round 9).
            kept = copy.deepcopy(existing)
            for key in ("date", "recurrence") + DAY_FIELDS:
                if key not in kept:
                    kept[key] = copy.deepcopy(prev.get(key))
            return kept
        elif held is not None and existing is held:
            for key in self._RESCUE_TEXT_KEYS:
                prev[key] = copy.deepcopy(held.get(key))
        elif (isinstance(existing, dict)
              and rescue_copy_due(existing.get("title") or "", existing.get("body") or "",
                                  note.get("title") or "", note.get("body") or "",
                                  existing.get("comments") or "", note.get("comments") or "")):
            # Any other earlier copy whose words the note has LOST (the big
            # delete's test) -- of words, of this series or of one before --
            # gives them; this copy keeps the series as it is now (round 10).
            for key in self._RESCUE_TEXT_KEYS:
                prev[key] = copy.deepcopy(existing.get(key, prev[key]))
        return prev

    def _write_series_owned(self, note, date_value, recurrence, schedule=True):
        """After a save on one day, write the series' own fields the editor
        holds: files and checklist, and with *schedule* date and repeat.
        A turn-off over days with text makes the note as it was the rescue
        copy first (only the day on screen was kept); returns whether it
        did. *schedule* False for "This occurrence only": a day's save moved
        the series, its days' text left on dates it no longer had."""
        rescued = schedule and self._repeat_off_loses_days(note, recurrence)
        if rescued:
            note["_prev"] = self._whole_note_rescue_copy(note)
        if schedule:
            if not recurrence["freq"] and not self._days_kept_off_repeat(note):
                note["exceptions"] = []
                note["overrides"] = {}
                note["moved"] = {}
            note["date"] = date_value
            note["recurrence"] = recurrence
        # A copy: the editor's own list stored made the dirty check compare
        # it with itself, and closing lost the next change.
        note["attachments"] = [dict(a) for a in self.current_attachments]
        note["checklist"] = [dict(it) for it in self._get_checklist()]
        return rescued

    def save_current_note(self, auto=False, body_read=None):
        """Store the editor in its note. *body_read* is the body's text as a
        capture read it just before, nothing run since (_capture_and_read):
        the autosave and the flush save from that read, not a second one."""
        fields = self._editor_fields_to_save(auto, body_read)
        if fields is not None:
            self._write_fields_to_note(auto, *fields)

    def _editor_fields_to_save(self, auto, body_read):
        """What the editor holds, as a save stores it -- or None when there
        is nothing to save, said out loud on an explicit Save."""
        title = self.title_entry.get().strip()
        if title == "Note title...":
            title = ""
        # Only Tk's final newline comes off: a .strip() ate a pasted block's
        # shape. with_caret_line: read before the caret line under a final
        # table, a table-ending note read unsaved forever.
        if body_read is None:
            body_read = self.body_text.get("1.0", "end-1c")
        body = with_caret_line(body_read)
        # `body` IS the widget's content, so spans and lines line up.
        formatting = self._extract_formatting(self.body_text, body_read)
        paragraphs = self._extract_paragraphs(self.body_text, body_read)
        # As typed less Tk's final newline, the body's rule.
        comments = self.comments_text.get("1.0", "end-1c")
        category = self.category_var.get()

        # An unreadable date or repeat is left out, quietly while typing
        # (status line), aloud on Save, asked on leaving (_flush_autosave).
        # A Save means finished, so a short date settles first.
        if not auto:
            self._settle_date_fields()
        date_value, recurrence, left_out = self._date_and_repeat_to_store()

        has_attachments = bool(self.current_attachments)
        has_checklist_items = bool(self._get_checklist())
        # Date and repeat are content ONLY on an explicit Save: counted on
        # every route, closing saved an abandoned day as a blank dated note.
        # The automatic routes ask _editor_state_has_content.
        deliberate_only = (date_value or recurrence["freq"]) and not auto
        if (not title and not body.strip() and not comments.strip()
                and not has_attachments and not has_checklist_items
                and not deliberate_only):
            # Against stray "+ New Note" junk, so for unsaved notes only:
            # emptying a saved note is an edit (it was refused and came back).
            # The fields are _editor_state_has_content's plus the date.
            already_saved = (self.selected_note_id is not None
                             and self.find_note(self.selected_note_id) is not None)
            if not already_saved:
                # An autosave skips quietly; Save warns, naming an unreadable
                # date or repeat when that is the reason.
                if not auto:
                    if left_out:
                        self.show_warning(
                            "Nothing saved yet",
                            self._left_out_message(
                                left_out, lead="This note can't be saved with:"))
                    else:
                        self.show_warning("Empty note", "Write something before saving!")
                return

        if recurrence["freq"] == "weekly" and not recurrence["weekdays"]:
            # Empty selection is legal — it means "the same weekday as the
            # start date" — and the summary label already says so.
            pass
        return (title, body, formatting, paragraphs, comments, category,
                date_value, recurrence, left_out)

    def _write_fields_to_note(self, auto, title, body, formatting, paragraphs,
                              comments, category, date_value, recurrence, left_out):
        """The fields written into a new note or into the open one, then
        everything a save brings after it (_after_note_saved)."""
        now = now_stamp()
        note = None
        reload_from_note = False
        put_back_schedule = False
        repeat_off_kept = False

        if self.selected_note_id is None:
            new_id = max([n["id"] for n in self.notes], default=0) + 1
            # A shared note keeps its arriving identity, checked again: an
            # import meanwhile may have brought it, and two never share one.
            arrived_uid = getattr(self, "_arrived_uid", "") or ""
            if arrived_uid and find_by_uid(self.notes, arrived_uid) is not None:
                arrived_uid = ""
            self._arrived_uid = ""
            self.notes.append(normalize_note({
                "id": new_id,
                "uid": arrived_uid,
                "title": title,
                "body": body,
                "formatting": formatting,
                "paragraphs": paragraphs,
                "comments": comments,
                "category": category,
                "date": date_value,
                "color": self.current_note_color,
                "attachments": self.current_attachments,
                "recurrence": recurrence,
                "exceptions": [],
                "overrides": {},
                "updated": now,
                "created": now,
                "checklist": [dict(it) for it in self._get_checklist()],
            }))
            self.selected_note_id = new_id
            self._remember_last_open_note(new_id)
            self.set_status(("Auto-saved " if auto else "Saved at ") + show_stamp(now),
                            reassurance=auto)
            # Saved where the list does not look -- Show picked once and
            # forgotten, a search left in its box -- the note vanished from
            # the list as it was written, without a word.
            made = self.notes[-1]
            hides = (self._what_hides_notes(made)
                     if new_id not in self._visible_note_ids() else "")
            if hides:
                self._show_toast(f"Saved in {made.get('category') or 'General'}, hidden by {hides}",
                                 kind="info", action=lambda: self._show_all_notes(made),
                                 action_text="Show all")
            elif auto:
                self._show_toast("Note created", yield_to_action=True)
        else:
            note = self.find_note(self.selected_note_id)
            if note is None:
                self.show_error("Note missing", "That note no longer exists.")
                return
            # What the note stores before this save, and its stamp: a save
            # that changes none of it is not an update (see the end).
            stored_before = (_stored_signature(note), note.get("updated"))

            scope = "series"
            # Read once, at the start: nothing that runs while this save
            # works may decide which day it writes to.
            occurrence_date = self.current_occurrence_date
            schedule_changed = False
            if is_recurring(note) and occurrence_date:
                # A day saves to itself unasked (a question on leaving made a
                # day's category seem to do nothing; field report). With no
                # overridable field changed, the edit is the series' (below).
                shown_now = effective_note(note, occurrence_date)
                overridable_changed = (
                    title.strip() != (shown_now.get("title") or "").strip()
                    or body != (shown_now.get("body") or "")
                    or comments != (shown_now.get("comments") or "")
                    or category != shown_now.get("category")
                    or self.current_note_color != (shown_now.get("color") or "")
                    # ...or its lists' structure, the one look a day keeps.
                    or list_lines(paragraphs, body) != list_lines(
                        day_paragraphs_shown(note, occurrence_date), shown_now.get("body") or ""))
                # Date and repeat are the series': whatever reached the hidden
                # fields is put back, never taken -- it moved or stopped it.
                schedule_changed = bool(
                    left_out
                    or date_value != (note.get("date") or "")
                    or normalize_recurrence(recurrence)
                    != normalize_recurrence(note.get("recurrence")))
                if overridable_changed or schedule_changed:
                    scope = "occurrence"
            # The editor holds one day of the series: whatever it saves, the
            # series' text, formatting, date and repeat are not its to write.
            on_a_day = occurrence_date is not None and is_recurring(note)
            # Announced once it is known that something was stored.
            announce = False

            if scope == "occurrence":
                # Content only, plain (OVERRIDABLE_FIELDS), shaped as a load
                # does (clean_override) -- but a colour cleared on a coloured
                # series' day stays empty, or every exit asked.
                from noteorganizer.core.model import clean_override
                patch = clean_override({
                    "title": title,
                    "body": body,
                    "comments": comments,
                    "category": category,
                    "color": self.current_note_color,
                    # Its own list lines (clean_override keeps those alone).
                    "paragraphs": paragraphs,
                })
                if not self.current_note_color and note.get("color"):
                    patch["color"] = ""
                # A day saying what the series says follows it again
                # (day_matches_series) -- a list depth of its own aside.
                follows_again = (day_matches_series(note, patch) and patch.get("paragraphs")
                                 == list_lines(note.get("paragraphs"), note.get("body") or ""))
                if follows_again:
                    follows_again = occurrence_date in (note.get("overrides") or {})
                    (note.get("overrides") or {}).pop(occurrence_date, None)
                else:
                    note.setdefault("overrides", {})[occurrence_date] = patch
                note["updated"] = now
                # A file or tick from this visit is the series' (dropped, a
                # file was left with no note); its date and repeat stay.
                self._write_series_owned(note, date_value, recurrence,
                                         schedule=False)
                put_back_schedule = schedule_changed
                # Nothing of the schedule is stored, so nothing left out: kept
                # on screen "to fix", the next save moved the series.
                left_out = []
                self.set_status(
                    ("Auto-saved" if auto else "Saved")
                    + (f" — {show_date(occurrence_date)} follows the series again"
                       if follows_again else f" {show_date(occurrence_date)} only")
                    + (" — the date and the repeat stay the whole series'"
                       if schedule_changed else ""))
                announce = auto
            elif on_a_day:
                # Only a series field changed (a tick, a file): only that is
                # written -- the whole editor gave one day's words to all.
                self._write_series_owned(note, date_value, recurrence,
                                         schedule=False)
                note["updated"] = now
                self.set_status(("Auto-saved " if auto else "Saved at ") + show_stamp(now),
                                reassurance=auto)
                announce = auto
            else:
                # A one-step copy of the OLD version when much of it is gone,
                # by what is gone (rescue_copy_due); emptied, however short.
                rescue_due = rescue_copy_due(note.get("title", ""), note.get("body", ""),
                                             title, body,
                                             note.get("comments", ""), comments)
                # Due for the comments alone over an unspent copy, that copy
                # takes only the comments -- whole, the body's delete went.
                comments_alone = (rescue_due and self._holds_unspent_rescue(note)
                                  and not rescue_copy_due(note.get("title", ""),
                                                          note.get("body", ""),
                                                          title, body))
                # The repeat going off: the note as it was, repeat and days,
                # becomes the rescue copy, so Restore previous brings the
                # series back; the days' own text stays in the note as well.
                days_lost = repeat_off_kept = self._repeat_off_loses_days(
                    note, recurrence)
                days_kept = self._days_kept_off_repeat(note)
                # Turned back on with another date or rule: the old series'
                # deleted days, which hold nothing, no longer hide the new one's.
                if not kept_days_fit(note, date_value, recurrence):
                    note["exceptions"] = []
                if days_lost:
                    # One save that also clears the text: an older copy's text
                    # in place of it left the newest words in no file (round 4).
                    note["_prev"] = self._turn_off_rescue_copy(
                        note, takes_text=rescue_due and not comments_alone)
                    if comments_alone and update_copy(note["_prev"]):
                        self._keep_text_aside(note, comments_only=True)
                    elif comments_alone:
                        note["_prev"]["comments"] = comments_kept_by_copy(
                            note["_prev"].get("comments", ""), note.get("comments", ""))
                elif (rescue_due and update_copy(note.get("_prev"))
                      and not rescue_copy_spent(note)):
                    # An Update's copy is the note's only old version: kept,
                    # and the words this save takes become their own note.
                    self._keep_text_aside(note, comments_only=comments_alone)
                elif rescue_due:
                    # The copy's own comments too, when theirs is the larger
                    # loss: two letters cleared after a long comment was
                    # deleted wrote over it (round 8 of the final audit).
                    if not comments_alone:
                        copy_days_set_aside(note)
                    note["_prev"] = dict(copy.deepcopy(note["_prev"]), comments=comments_kept_by_copy(
                        note["_prev"].get("comments", ""),
                        note.get("comments", ""))) if comments_alone else {
                        "title": note.get("title", ""),
                        "body": note.get("body", ""),
                        "formatting": note.get("formatting", []),
                        "paragraphs": note.get("paragraphs", []),
                        "comments": note.get("comments", ""),
                    }
                    # Made while a turn-off waits: the turn-off's own copy
                    # keeps this text when it is made (_turn_off_rescue_copy).
                    if (getattr(self, "_holding_repeat_off", False)
                            and self._repeat_off_waits()):
                        self._held_text_rescue = note["_prev"]
                note["title"] = title
                note["body"] = body
                note["formatting"] = formatting
                note["paragraphs"] = paragraphs
                note["comments"] = comments
                note["category"] = category
                note["date"] = date_value
                note["color"] = self.current_note_color
                # A copy, never the editor's own list -- see
                # _write_series_owned.
                note["attachments"] = [dict(a) for a in self.current_attachments]
                note["recurrence"] = recurrence
                # A day moved onto a date the new rule gives loses its move
                # now, not at the next start (drop_hidden_moves). Turned back on
                # as the series its copy holds: the note holds the days again.
                drop_hidden_moves(note)
                spend_series_days(note)
                note["checklist"] = [dict(it) for it in self._get_checklist()]
                note["updated"] = now
                if not recurrence["freq"] and not days_kept:
                    # No longer repeating: days with no text of their own
                    # (a colour, a category) would be invisible clutter, so
                    # they go; a day's own text stays (_days_kept_off_repeat).
                    note["exceptions"] = []
                    note["overrides"] = {}
                    note["moved"] = {}
                self.set_status(("Auto-saved " if auto else "Saved at ") + show_stamp(now)
                                + (self._repeat_off_line(note) if days_lost else ""),
                                reassurance=auto and not days_lost)
                announce = auto
            # The repeat just removed, the day view ends, filled from the
            # note below: the day's text left would save over the series'.
            if self.current_occurrence_date and not is_recurring(note):
                self.current_occurrence_date = None
                reload_from_note = occurrence_date is not None
            if left_out and _stored_signature(note) == stored_before[0]:
                # Only a left-out field differed: the stamp stays, or each way
                # out moved the note up "Recently updated".
                note["updated"] = stored_before[1]
                announce = False
            if announce:
                self._show_toast("Note updated", yield_to_action=True)
            # The note holds again what its rescue copy kept -- Undo after
            # a big deletion -- so the copy is spent, and the button with it.
            if rescue_copy_spent(note):
                note.pop("_prev", None)
            self._take_back_aside(note)
        self._after_note_saved(auto, note, now, left_out, put_back_schedule,
                               reload_from_note, repeat_off_kept)

    def _after_note_saved(self, auto, note, now, left_out, put_back_schedule,
                          reload_from_note, repeat_off_kept):
        """After the write: the banner, the file, the list, the editor's
        snapshot, and what the save had to leave out, said."""
        # Recurrence or override counts may have just changed either way.
        self._update_occurrence_banner()

        self.save_notes()
        # An autosave under a popup skips the list and calendar (delays
        # still tore the sidebar): saved anyway, they catch up later.
        if auto and getattr(self, "_mini_popup", None) is not None:
            # Remember that the sidebar/calendar are now slightly stale, so
            # the next natural transition (switching notes, changing tabs)
            # can catch them up — see _catch_up_deferred_refresh().
            self._note_list_needs_refresh = True
        else:
            # One note changed, so one card is redrawn; the whole list is
            # rebuilt only when that cannot be known to be enough -- or when
            # the save made or took away a note of words kept aside.
            aside = self.__dict__.pop("_asides_changed", False)
            if aside or not self._redraw_saved_card(self.selected_note_id):
                self.refresh_note_list()
            self.render_calendar()
            self._note_list_needs_refresh = False
        # "This occurrence only" left the series' date and repeat as they
        # were: the editor shows them again, so it agrees with the note.
        if put_back_schedule:
            self._put_back_stored_date_and_repeat()
            self._cancel_pending_autosave()
        # The saved note now matches disk; update this tab's snapshot so its
        # dirty dot clears. Once: it was taken twice in a row.
        self._sync_editor_snapshot()
        self._update_restore_button()
        if reload_from_note:
            # Now the note's: an Add box item and left-out values are carried
            # across (_schedule_to_carry), or the load wrote over them; the
            # save's status words, which say where the days went, stay.
            said = str(self.status_lbl.cget("text"))
            pending_item = (self.checklist_add_var.get()
                            if hasattr(self, "checklist_add_var") else "")
            carried = self._schedule_to_carry() if left_out else {}
            self.load_note(self.find_note(self.selected_note_id))
            if pending_item:
                self.checklist_add_var.set(pending_item)
            self._put_back_schedule(carried)
            self.set_status(said)
            # The load's traces asked an autosave, which saved the same again
            # and dropped those words.
            self._cancel_pending_autosave()
        # If the calendar day panel is showing, reflect the edit there too.
        if self._day_panel_mode != "empty":
            self.refresh_day_panel()
        # What was left out waits on screen: said by the status line, aloud
        # on Save (which then sends no one to the calendar). The words less
        # "except" are kept for _say_nothing_is_left_out.
        if left_out:
            self.set_status(("Auto-saved " if auto else "Saved at ") + show_stamp(now)
                            + " — except " + "; ".join(left_out)
                            + (self._repeat_off_line(note) if repeat_off_kept else ""))
        self._status_names_left_out = (
            ("Auto-saved " if auto else "Saved at ") + show_stamp(now)
            + (self._repeat_off_line(note) if repeat_off_kept else "")
            if left_out else None)
        if left_out:
            if not auto:
                self.show_warning("Part of this note isn't saved",
                                  self._left_out_message(left_out))
                return
        # Only Save on a note added for a day goes back; an EXISTING note's
        # Save stays (field feedback), with Back to Calendar.
        _pending = getattr(self, "_pending_calendar_return", None)
        if not auto and _pending and _pending.get("origin") == "add":
            self._return_to_calendar()

    # ---------- Trash / recently deleted ----------
    def _restore_from_trash(self, entry):
        """Bring a trashed note back, then redraw what shows it."""
        self._restore_trash_entries([entry])

    def _restore_trash_entries(self, entries):
        """Bring trashed notes back, one or a batch, in one pass and one
        write a file (restore_many_from_trash; a thousand took half a
        minute); returns them. The notes are written FIRST, so a failure
        leaves a duplicate at worst. None when nothing could be kept, the
        lists in memory put back as the files are.
        """
        if entries and _core_paths.writes_held(DATA_FILE):
            many = len(entries) > 1
            self.show_warning(
                "Restore after reopening",
                "When Note Organizer started it could not open your notes, so "
                "nothing is saved in this session, and a note restored now "
                "would be lost when the app closes. %s in Recently deleted: "
                "close Note Organizer, open it again, and restore %s then."
                % ("They stay" if many else "It stays", "them" if many else "it"))
            return None
        kept_trash = self.trash
        self.notes, self.trash, restored = core_restore_many_from_trash(
            self.notes, self.trash, entries)
        if not restored:
            return restored
        if not self.save_notes():
            # Taken back by identity: a new note's autosave inside the error's
            # wait was appended after them, and a cut by count took it too (round 12).
            back = {id(n) for n in restored}
            self.notes[:] = [n for n in self.notes if id(n) not in back]
            self.trash = kept_trash
            # That autosave may have written them, and the next start showed
            # them in both lists: the file is put back too, or the close tries.
            self._set_aside_days()
            self._notes_unsaved = not core_save_notes(self.notes)[0]
            self.set_status("Not restored — the notes could not be saved; "
                            "it stays in Recently deleted")
            return None
        save_trash(self.trash)
        # A note kept aside, put back from the Trash, is the person's now: the
        # next Ctrl+Z spent it a second time (wave 2, round 8).
        uids = {n.get("uid") for n in restored}
        for held in getattr(self, "_kept_asides", {}).values():
            held[:] = [entry for entry in held if entry[0] not in uids]
        self.refresh_note_list()
        self.render_calendar()
        self._say_hidden_arrivals(restored, "Restored from Recently deleted")
        return restored

    def _refresh_open_trash_panel(self):
        """Redraw Settings -> Recently deleted if it is the section on
        screen: its rows hold the entries they were drawn for, and a
        restore made from outside the panel leaves them stale."""
        redraw = getattr(self, "_trash_panel_redraw", None)
        if (redraw is None or not getattr(self, "_settings_open", False)
                or getattr(self, "_settings_selected_section", None) != "trash"):
            return
        try:
            redraw()
        except tk.TclError:
            # The panel was rebuilt or torn down since this was recorded.
            self._trash_panel_redraw = None

    def _undo_trash(self, marks):
        """Put back the notes the toast's Undo was offered for. `marks` are
        (id, deleted_at) pairs, as the trash list is rebuilt under any held
        object. Through Settings' own core function, which gives a NEW id,
        so what returns is known by where it lands, appended.
        """
        # A set of the marks, looked up in one pass over the trash: finding
        # each one with its own scan made a bulk Undo quadratic as well.
        wanted = set(marks)
        entries = [e for e in self.trash
                   if isinstance(e, dict)
                   and (e.get("id"), e.get("deleted_at")) in wanted]
        restored = self._restore_trash_entries(entries)
        if restored is None:
            return  # could not be kept, and said so; still in the Trash

        if not restored:
            # Emptied, purged, or already put back -- a second click on a
            # toast that had not yet faded. Nothing to apologise for: the
            # note is simply not where the click expected it.
            self._show_toast("Nothing left to put back", kind="info")
            return
        # The toast floats over Settings too, and the Trash's rows are the
        # one view of the trash that does not redraw itself.
        self._refresh_open_trash_panel()

        if len(restored) == 1:
            # Opened again, as the click meant; a bulk undo opens nothing.
            self.open_note_in_tab(restored[0])
            title = (restored[0].get("title") or "").strip() or "Untitled note"
            self.set_status(f"Put back: {title}")
        else:
            self.set_status(f"Put back {len(restored)} notes")

    def _note_for_undo(self, note_id, uid):
        """The note an Undo was offered for, known by its identity when it
        has one -- not by its number. An id freed by a delete goes to the
        next new note, and a note restored from the Trash comes back under a
        new one: looked up by number and then checked, the Undo said "That
        note is no longer here" with the note in the list."""
        return find_by_uid(self.notes, uid) if uid else self.find_note(note_id)

    def _undo_bulk_category(self, marks, applied):
        """Put each note back in the category it was moved out of. `marks`
        hold (id, category, updated, uid) per note, as a selection mixes
        categories. Only notes still under this undo's category are touched
        (a second click, a hand change), as _undo_trash matches its pairs;
        `updated` goes back too, so they do not jump up the list.
        """
        # Each note by its identity when the mark has it (_note_for_undo).
        notes = [self._note_for_undo(mark[0], mark[3] if len(mark) > 3 else None)
                 for mark in marks]
        # Typing under the toast is saved first, then the move, then the
        # editor follows -- the change's own order.
        if self._flush_autosave(leaving=self.selected_note_id in {
                note["id"] for note in notes if note is not None}) is False:
            # Going back to fix a date means stay -- and the offer stays
            # with it: where each note came from is kept nowhere else.
            self._offer_category_undo({"marks": marks, "applied": applied})
            return
        restored = []
        homeless = 0
        for mark, note in zip(marks, notes):
            old_category, old_updated = mark[1:3]
            if note is None or note.get("category") != applied:
                continue
            if old_category not in CATEGORY_COLORS:
                # Its old category went meanwhile: left where it is, and
                # said, rather than a destination invented.
                homeless += 1
                continue
            note["category"] = old_category
            if isinstance(old_updated, str) and old_updated:
                note["updated"] = old_updated
            restored.append(note)

        if not restored:
            # Already put back, refiled, or gone: nothing to apologise for.
            self._show_toast("Nothing left to put back", kind="info")
            return

        self.save_notes()
        self._editor_follows_external_change({n["id"] for n in restored})
        self.refresh_note_list()
        # The calendar draws an uncoloured note in its category's colour
        # (get_note_color), so it is redrawn.
        self.render_calendar()
        if homeless:
            self.set_status(
                f"Put back {len(restored)} note(s); {homeless} could not go "
                "back to a category that no longer exists")
        else:
            self.set_status(f"Put back {len(restored)} note(s)")

    def _undo_checklist_delete(self, items, index, item):
        """Put a removed checklist item back where it was. `items`, the list
        it left, is checked by IDENTITY: every change of what the editor
        holds rebinds `_working_checklist`, and an old list was "put back"
        into while nothing read it -- a confident lie. The stamp is fresh,
        unlike _undo_bulk_category's: this edit happened in the editor.
        """
        if self._get_checklist() is not items:
            self._show_toast("That note is no longer open", kind="info")
            return
        if any(existing is item for existing in items):
            # A second click on a toast that has not yet faded. Matched by
            # identity, not equality, so an item the user has since typed
            # again by hand is not mistaken for this one.
            self._show_toast("That item is already back", kind="info")
            return
        # Or grown back to full since, by an item added while the offer was up.
        if self._checklist_full(items, item.get("text", "")):
            return
        # The place is a preference: list.insert puts an index past the end
        # at the end, so no clamp is written.
        drawn = getattr(self, "_checklist_drawn", None)
        in_step = self._checklist_in_step(items)
        items.insert(index, item)
        if in_step and drawn["rows"]:
            # The one row back where it was, the others untouched.
            at = min(index, len(drawn["rows"]))
            after = drawn["rows"][at][1] if at < len(drawn["rows"]) else None
            above = drawn["rows"][at - 1][1] if at else None
            group = self._checklist_rows
            if after is None:
                record = self._build_checklist_row(at, item)
            elif above is not None and above.master is after.master:
                # The stacking order too, not only the packing: Tab walks the
                # tick boxes in it -- a row put back in the middle was last.
                record = self._build_checklist_row(at, item, before=after)
            elif above is not None and group.room(above.master):
                # At a chunk's edge, back into the chunk it left: put above,
                # the chunk before grew past its parking place.
                record = self._build_checklist_row(at, item, into=above.master)
            elif group.room(after.master):
                record = self._build_checklist_row(at, item, before=after)
            else:
                # Alone in its chunk, which went with it: a chunk of its own.
                record = self._build_checklist_row(
                    at, item, into=group.chunk_before(after.master))
            drawn["rows"].insert(at, record)
            self._update_checklist_progress()
        else:
            self._render_checklist_items()
        self._schedule_autosave()
        self.set_status("Checklist item put back")

    def _undo_occurrence_delete(self, note_id, date_str, own_edit=None,
                                uid=None, came_from=None):
        """Put back the one day removed from a series (its date in
        `exceptions` has no other way home); *came_from*: a moved day, back
        where it was held. `own_edit` is its text; `uid` finds the note.
        Only into the series held now -- turned off or picked anew, the Undo
        says it can't (three rescue-copy designs each broke).
        """
        note = self._note_for_undo(note_id, uid)
        if note is None:
            self._show_toast("That note is no longer here", kind="info")
            return
        here = self.selected_note_id == note["id"]
        # Read before: after, the only removed day back, the waiting
        # turn-off was made -- the series gone from the calendar.
        waits = here and self._repeat_off_waits()
        if here and not waits:
            # The editor saved FIRST (_editor_follows_external_change), the
            # day opened with no second save: after, its view read as an
            # edit, the series' text saved over the day's own.
            if self._flush_autosave() is False:
                # Going back means stay -- and the offer stays with it: the
                # day's own text is kept nowhere else.
                self._show_toast(
                    "Day removed",
                    action=lambda: self._undo_occurrence_delete(
                        note_id, date_str, own_edit, uid, came_from))
                return
        exceptions = set(note.get("exceptions") or [])
        if not is_recurring(note):
            self._show_toast("This note no longer repeats, so that day "
                             "can't come back", kind="info")
            return
        # The date the delete skipped: a moved day's is the one its rule
        # gives it, and the day comes back held where it was.
        skipped = came_from or date_str
        moves = dict(note.get("moved") or {})
        if came_from:
            others = [other for other, new in moves.items() if new == date_str and other != came_from]
            # A day moved onto the date holds it, as below: one a Restore
            # previous brought back was dropped as dead.
            from noteorganizer.core.recurrence import _rule_days_among
            if _rule_days_among(note, others) - exceptions:
                when = parse_date(date_str)
                self._show_toast(
                    f"Another day of this series is on {show_day(when) if when else date_str} now, "
                    "so that day can't come back", kind="info")
                return
            # A dead move onto the date goes, as Move this day drops one: two
            # moves onto one date were listed twice, and the phone's History
            # threw on the twin (round 19 of the final audit).
            for dead in others:
                del moves[dead]
            moves[came_from] = date_str
        # Asked of the calendar as if unskipped: a changed rule may lack the
        # day, and one put back showed on no calendar.
        day = parse_date(date_str)
        if day is None or expand_occurrences(
                dict(note, exceptions=sorted(exceptions - {skipped}),
                     moved=moves),
                day, day) != [date_str]:
            self._show_toast("This note's repeat no longer has that day, "
                             "so it can't come back", kind="info")
            return
        # Only onto a free date, as a move comes home (_day_is_free): a day
        # moved there since was hidden, its words read as this one's.
        if skipped in exceptions and (
                expand_occurrences(note, day, day) == [date_str]
                or date_str in (note.get("overrides") or {})):
            self._show_toast(
                f"Another day of this series is on {show_day(day)} now, so that day "
                "can't come back" if expand_occurrences(note, day, day) == [date_str]
                else f"This series keeps text or a colour of its own on {show_day(day)} "
                "now, so that day can't come back", kind="info")
            return
        if skipped not in exceptions and (
                not came_from
                or (note.get("moved") or {}).get(came_from) == date_str) and (
                not own_edit or date_str in (note.get("overrides") or {})):
            self._show_toast("That day is already back", kind="info")
            return
        # Otherwise the day is skipped, or the repeat was picked anew and has
        # it again without the text it had of its own: both go back below.
        exceptions.discard(skipped)
        note["exceptions"] = sorted(exceptions)
        if came_from:
            note["moved"] = moves
        # Its own edit goes back with it -- unless the day somehow has one
        # again already, which is newer than the one this Undo remembers.
        if own_edit and date_str not in (note.get("overrides") or {}):
            note.setdefault("overrides", {})[date_str] = dict(own_edit)
        note["updated"] = now_stamp()
        self.save_notes()
        self.refresh_note_list()
        self.render_calendar()
        # Not opened over a waiting turn-off: leaving made it, and the Undo
        # turned the whole series off (_flush_autosave).
        if not waits:
            self.open_note_in_tab(note, occurrence_date=date_str,
                                  flush=not here)
        else:
            # The series stays on screen, its days changed under it.
            self._update_occurrence_banner()
        self.set_status("Put that day back")

    def _attach_dup_preview(self, widget, note):
        """Show a small floating preview of a note's contents while the mouse
        hovers over its row in the duplicates dialog, so the user can tell the
        copies apart before choosing. Vanishes on mouse-leave — no clicking."""
        tip = {"win": None}

        def show(event):
            if tip["win"] is not None:
                return
            # Parented to the WINDOW: under a row it joined the panel's tree,
            # and CI's still pointer opened one that qa3 counted as a
            # twenty-sixth Trash row (measured: 25 -> 26).
            win = tk.Toplevel(widget.winfo_toplevel())
            # Held at once, so hide() takes it away whatever happens below.
            tip["win"] = win
            win.wm_overrideredirect(True)  # no title bar / borders
            win.configure(bg=self.colors["accent"])
            frame = tk.Frame(win, bg=self.colors["card"], padx=10, pady=8)
            frame.pack(padx=1, pady=1)
            # A Trash entry is as the file held it; its fields are read
            # from a shaped copy, as a note's are.
            shown = normalize_note(dict(note))

            def line(label, value):
                if not value:
                    return
                row = tk.Frame(frame, bg=self.colors["card"])
                row.pack(fill="x", anchor="w")
                tk.Label(row, text=f"{label}: ", font=("Segoe UI", 8, "bold"),
                         bg=self.colors["card"], fg=self.colors["subtext"]).pack(side="left")
                tk.Label(row, text=value, font=("Segoe UI", 8), bg=self.colors["card"],
                         fg=self.colors["text"], wraplength=self.px(260), justify="left"
                         ).pack(side="left")

            title = shown["title"].strip() or "(untitled)"
            line("Title", title[:60])
            # The words without the tables, and a line saying the tables
            # are there -- the calendar's rule; raw, a table read as bars.
            body, tables_here = core_tables.preview_text(shown["body"])
            body = body.strip()
            if body:
                preview = body[:120] + ("…" if len(body) > 120 else "")
                line("Note", preview)
            if tables_here:
                line("Holds", "▦ 1 table" if tables_here == 1
                     else "▦ %d tables" % tables_here)
            comments = shown["comments"].strip()
            if comments:
                line("Comments", comments[:80] + ("…" if len(comments) > 80 else ""))
            line("Date", show_date(shown["date"]))
            if shown["color"]:
                line("Color", shown["color"])
            atts = shown["attachments"]
            if atts:
                # Cut as the lines above are: a backup's names kept whole
                # stood this card taller than X can draw.
                line("Attachments", one_line(", ".join(
                    attachment_display_name(a.get("filename"), a.get("stored_as")) or "?"
                    for a in atts if isinstance(a, dict)), 160))
            # As held, not shaped: a load backfills a missing stamp with now.
            created = note.get("created")
            if isinstance(created, str) and created:
                line("Created", show_stamp(created))

            # Position just below-right of the cursor.
            win.wm_geometry(f"+{event.x_root + 14}+{event.y_root + 12}")

        def hide(event=None):
            if tip["win"] is not None:
                try:
                    tip["win"].destroy()
                except tk.TclError:
                    pass
                tip["win"] = None

        widget.bind("<Enter>", show)
        widget.bind("<Leave>", hide)
        # Also hide if the row is destroyed (dialog rebuild).
        widget.bind("<Destroy>", hide)

    def _bind_wheel_tree(self, root, handler):
        """Bind a mousewheel handler to a widget and all its descendants, so the
        wheel works anywhere over a dialog, not just on the scrollbar."""
        root.bind("<MouseWheel>", handler)
        for child in root.winfo_children():
            self._bind_wheel_tree(child, handler)



    def _days_left_in_trash(self, deleted_at):
        """How many days until this trashed note auto-purges. None if unknown."""
        return core_days_left_in_trash(deleted_at)

    def _move_notes_to_trash(self, notes_to_trash):
        """Move notes into the trash rather than destroying them (the work
        is in core/storage.py). Returns the entries appended, for an Undo to
        name exactly -- reading the trash's end was a guess. None when
        trash.json could not be written, said: the caller keeps the notes.
        """
        before = len(self.trash)
        ok, _exc = core_move_to_trash(self.trash, notes_to_trash)
        if not ok:
            self.show_warning(
                "Nothing was deleted",
                "The Trash could not be saved, so the note stays where it is. "
                + ("Its file could not be opened when Note Organizer started, "
                   "so nothing is saved to it until the app is opened again."
                   if _core_paths.writes_held(TRASH_FILE) else
                   "Is the disk full? Details are in crash_log.txt."))
            return None
        return self.trash[before:]

    def delete_current_note(self):
        """Delete the note open in the editor (the Delete button / shortcut)."""
        note = (self.find_note(self.selected_note_id)
                if self.selected_note_id is not None else None)
        if note is None:
            self.show_info("Nothing to delete", "No note is selected.")
            return
        # Unsaved typing goes with it, a turn-off held, as from the menu
        # (_context_delete_note).
        if self._flush_autosave(hold_repeat_off=True) is False:
            return
        self._delete_note(note, self.current_occurrence_date)

    def _delete_note(self, note, occurrence_date):
        """Delete a specific note (or one occurrence of it), no matter what
        the editor is showing. The target arrives as a parameter and the
        editor's selection is never touched on the way in, so cancelling
        either prompt leaves every bit of editor state exactly as it was —
        the selection-repointing shortcut this replaces let a cancelled
        delete aim the next autosave at the wrong note (see ISSUES_LOG)."""
        # Re-anchor on the stored dict: the calendar hands out
        # per-occurrence copies, and mutations below must land in
        # self.notes, not in a copy.
        note = self.find_note(note["id"])
        if note is None:
            return

        if is_recurring(note) and occurrence_date:
            scope = self.ask_occurrence_scope("Delete", occurrence_date)
            if scope is None:
                return
            if scope == "occurrence":
                # A moved day is skipped by the date its rule gives it, and
                # its move goes with it: kept, the move would outlive the
                # day, and an Undo of it would have nothing to bring back.
                origin = moved_from(note, occurrence_date)
                if origin is not None:
                    note["moved"].pop(origin, None)
                exceptions = set(note.get("exceptions") or [])
                exceptions.add(origin or occurrence_date)
                note["exceptions"] = sorted(exceptions)
                # Kept for the Undo below: the day's own title and text
                # went with it, and the Undo used to bring back the day
                # showing the series' text instead -- the edit gone for good.
                own_edit = note["overrides"].pop(occurrence_date, None)
                note["updated"] = now_stamp()
                self.save_notes()
                if (self.selected_note_id == note["id"]
                        and self.current_occurrence_date == occurrence_date):
                    # The editor was showing the occurrence that just
                    # stopped existing; start it fresh. Deleting some
                    # other note's occurrence leaves the editor alone.
                    self.new_note()
                self.refresh_note_list()
                self.render_calendar()
                self.set_status("Removed that one day")
                # The toast is this delete's only way back; with the uid, as
                # a freed id goes to the next new note.
                undo = (lambda nid=note["id"], day=occurrence_date,
                        edit=own_edit, uid=note.get("uid"), came=origin:
                        self._undo_occurrence_delete(nid, day, edit, uid,
                                                     came_from=came))
                self._show_toast("Day removed", action=undo)
                if self.selected_note_id == note["id"]:
                    self._update_occurrence_banner()
                return

        attachment_count = len(note.get("attachments") or [])
        warning = ""
        if attachment_count:
            plural = "s" if attachment_count != 1 else ""
            warning = f"\n\n{attachment_count} attached file{plural} will go to trash with it."
        confirm = self.ask_yes_no(
            "Delete note",
            ("Delete this entire repeating series?" if is_recurring(note)
             else "Are you sure you want to delete this note?") + warning,
            # Enter answers a question now: a reflexive one keeps the note.
            default="no"
        )
        if confirm:
            deleted_id = note["id"]
            # Move to trash (30-day recovery) rather than destroying it.
            doomed = [n for n in self.notes if n["id"] == deleted_id]
            moved = self._move_notes_to_trash(doomed)
            if moved is None:
                return   # trash.json refused it: the note stays, and that was said
            marks = [(e.get("id"), e.get("deleted_at")) for e in moved]
            self.notes = [n for n in self.notes if n["id"] != deleted_id]
            self.save_notes()
            # Close any open tab that pointed at the deleted note (force: its
            # underlying note is gone, so there's nothing to save).
            self.open_tabs = [t for t in self.open_tabs
                              if t["state"]["selected_note_id"] != deleted_id]
            if not self.open_tabs:
                self.active_tab_index = None
                self.new_note()
            # Another note in the editor stays as it is: "switched" to, it
            # came back from its opening copy, over what was saved since.
            self._sync_editor_snapshot()
            # The one card off, or a full rebuild when that is not certain.
            if not self._remove_note_cards([deleted_id]):
                self.refresh_note_list()
            self.render_calendar()
            # The window is a setting (Settings -> Recently deleted), so the
            # number is read, never written: this line promised thirty days
            # to someone who had chosen seven.
            self.set_status("Note moved to Trash (recoverable"
                            f"{trash_window_words('for')})")
            # The status line says where it went; the toast is the way
            # back. Settings -> Recently deleted was the only route home
            # until now, and it asks you to know the trash exists.
            self._show_toast("Note moved to Trash",
                             action=lambda: self._undo_trash(marks))

    def report_callback_exception(self, exc_type, exc_value, exc_tb):
        """Tk's handler for errors in a callback, which printed to a stderr
        the windowed build has none of: the failure is said, and logged
        where the crash handler logs."""
        import traceback
        details = "".join(traceback.format_exception(exc_type, exc_value, exc_tb))
        _core_diagnostics.append_crash_log("callback", details, APP_DIR)
        try:
            self._show_toast("Something went wrong with that — your other notes are safe", kind="error")
        except tk.TclError:
            pass

    def on_app_close(self):
        """Closing saves unasked, as switching away does; only a date or
        repeat not storable asks ("Go back and fix it" stays open). First a
        question on screen owns the window (closed under it, the process
        kept the lock), and a popup with typed work has its say."""
        if self._a_dialog_is_asking():
            self._bring_question_forward()
            return
        if not self._dismiss_mini_popup_asking(holding_work_only=True):
            return
        self._closing_window = True
        try:
            if self._save_on_the_way_out() is False:
                return
        finally:
            self._closing_window = False
        # Words a full checklist could not take are lost on closing: asked,
        # once, except for notes in the Trash.
        here = {n.get("uid") for n in self.notes}
        asked = {uid: text for uid, text in self._add_box_waiting.items()
                 if uid in here}
        waiting = list(asked.values())
        # The question says them: answered No, the next way out of their
        # note does not say them again (_waiting_said).
        self._waiting_said.update(asked)
        if waiting and not self.ask_yes_no(
                "Close without these items?",
                f"A checklist can have up to {MAX_CHECKLIST_ITEMS:,} items, and "
                + ("a full one could not take “%s”" % one_line(waiting[0], 80)
                   if len(waiting) == 1 else
                   f"full ones could not take {len(waiting)} items typed in their Add boxes")
                + ". Close anyway and lose "
                + ("it" if len(waiting) == 1 else "them") + "?",
                icon="warning", default="no"):
            return
        if getattr(self, "_notes_unsaved", False) and not self.ask_yes_no(
                "Close without saving?",
                "Your latest changes could not be saved, so they are only on "
                "the screen. Close anyway and lose them?",
                icon="warning", default="no"):
            return
        # A backup export/import may still be writing on its worker thread;
        # destroy() would kill it mid-file. Wait (capped) for it to finish,
        # then do what its completion would have done on the main thread.
        self._wait_for_io_workers()
        self._settle_background_work_at_close()
        self.destroy()

    def _save_on_the_way_out(self):
        """What the process going away must not lose: a short date settled,
        the editor and tabs saved, a failed notes write tried again. Run by
        the close and a session's end alike (a copy drifted). False when the
        person went back to a date -- never at a session's end."""
        if self._flush_autosave() is False:
            return False
        self._sync_active_tab()
        for i in range(len(self.open_tabs)):
            try:
                if not self.editor_state_matches_saved(
                        self.open_tabs[i]["state"]):
                    self.switch_to_tab(i)
                    self.save_current_note(auto=True)
            except Exception:
                # Closing must not get stuck behind a broken tab; the
                # autosaves along the way have the rest.
                self._log_swallowed("close: per-tab final save")
                continue
        if getattr(self, "_notes_unsaved", False):
            ok, _exc = core_save_notes(self.notes)
            self._notes_unsaved = not ok
        return True

    def on_session_end(self):
        """Windows is ending the session: save what the close saves, asking
        nothing. Only a question (WM_QUERYENDSESSION), which may be
        cancelled, so nothing needed is torn down -- a stopped backup hung
        its bar. See _settle_backups_at_session_end."""
        self._ending_session = True
        try:
            # A popup holding typed work (the template editor) keeps it: the
            # close asks it, and the session asks nothing.
            pop = getattr(self, "_mini_popup", None)
            quiet = getattr(pop, "_save_without_asking", None) if pop is not None else None
            if callable(quiet):
                try:
                    quiet()
                except Exception:
                    self._log_swallowed("session end: popup's work")
            self._save_on_the_way_out()
        except Exception:
            self._log_swallowed("session end: final save")
        finally:
            self._ending_session = False
        self._settle_backups_at_session_end()

    def _settle_backups_at_session_end(self):
        """A backup's worker at a session's end, right if it is cancelled: an
        export writes on (its file replaces the target whole); an import is
        dropped, said at once. Either leaves a line for the next start
        (announce_startup_changes), an export finishing takes it back."""
        export = self._export_state
        if export is not None and not export.get("done"):
            save_setting("backup_cut_short", {
                "kind": "export", "file": export.get("save_path") or "",
                "when": "session"})
        asking = getattr(self, "_import_asking", None)
        if asking is not None:
            # Its questions on screen, its files copied: what a session that
            # ends leaves behind is taken out by the next start, and the
            # files stay meanwhile, as an answer may still claim them.
            asking["asked_at_session_end"] = True
            save_setting("backup_cut_short", {
                "kind": "import", "file": asking.get("zip") or "", "when": "session",
                "copied": list(asking.get("copied") or []),
                "temp_dir": asking.get("temp_dir") or ""})
        state = self._import_state
        if state is None:
            return
        state["stop"] = True
        save_setting("backup_cut_short", {
            "kind": "import", "file": state.get("zip") or "", "when": "session"})
        # Stopped between two chunks of a megabyte (StoppableFile): moments.
        deadline = time.time() + 2.0
        for t in [t for t in getattr(self, "_io_workers", []) if t.is_alive()]:
            t.join(timeout=max(0.0, deadline - time.time()))
        if not state.get("done"):
            # Its poll reports the stop when it comes. Held past the join (a
            # file another program holds), the word names what it copied and
            # unpacked, for the next start to take out (round 8 of the audit).
            save_setting("backup_cut_short", {
                "kind": "import", "file": state.get("zip") or "", "when": "session",
                "copied": list(state.get("copied") or []),
                "temp_dir": state.get("temp_dir") or ""})
            return
        self._import_state = None
        if state.get("temp_dir"):
            shutil.rmtree(state["temp_dir"], ignore_errors=True)
        self._drop_unclaimed_import_files(state)
        try:
            self.export_progress_frame.place_forget()
            self.set_status(self._IMPORT_STOPPED_AT_SESSION_END)
        except tk.TclError:
            pass

    _IMPORT_STOPPED_AT_SESSION_END = (
        "The import was stopped as Windows began to sign out or shut down, so "
        "nothing from the backup was kept. Import it again to bring it in.")
    # Said when a question of the backup's is answered Cancel: asked while
    # the person may be typing, a stray Enter cancelled it without a word.
    _IMPORT_CANCELLED = "Import cancelled: nothing from the backup was added or changed."

    def _say_import_cancelled(self):
        """On the banner, and on the status line held against the autosave's
        "Auto-saved", which wrote over it within a second while the person
        typed on -- the road a stray key took to that Cancel."""
        self.set_status(self._IMPORT_CANCELLED)
        self._box_words_until = time.monotonic() + 8
        self._show_toast(self._IMPORT_CANCELLED, kind="info")

    def set_status(self, text, reassurance=False):
        # *reassurance* -- the autosave's own "Auto-saved" -- does not write
        # over the words a limited box said a moment ago (_say_by_the_box):
        # the paste they are about set off that very autosave.
        if reassurance and time.monotonic() < getattr(self, "_box_words_until", 0):
            return
        # New words end _say_nothing_is_left_out's claim on the line, or an
        # older save's words came back over a later one's.
        self._status_names_left_out = None
        # One line: it quotes names kept whole, and a title of 3,000 lines
        # stood the status bar taller than X can draw.
        self.status_lbl.config(text=one_line(text, 1000))

    def _on_data_write_failure(self, path, exc):
        """core/storage's on_write_failure: a data-file write failed. The
        notes file too (core's cleanup writes it directly; excluded, that
        failure was invisible). Deferred, so it never re-enters the saver."""
        name = os.path.basename(str(path))
        try:
            self.after(0, lambda: self._show_toast(
                f"Couldn't save {name} — details in crash_log.txt",
                kind="error"))
        except (tk.TclError, RuntimeError):
            pass

    def _run_toast_action(self):
        """Do whatever the toast on screen is offering, once.

        Cleared before it runs, so a double click cannot run it twice, and
        so a click landing as the toast disappears does nothing at all.
        """
        action, self._toast_action = self._toast_action, None
        self._hide_toast()
        if action is not None:
            action()

    def _run_toast_action_by_key(self):
        """The toast's Undo pressed from the keyboard: the banner goes, and
        the keyboard with it, so it lands on the list -- or the tabs."""
        self._run_toast_action()
        target = self._toast_landing()
        if target is not None:
            target.focus_set()

    def _toast_landing(self):
        """Where the keyboard goes when the banner's Undo goes from under it:
        the note list -- its arrow, while the list is put away -- or the tabs;
        or, on Settings, the entry of the section showing. Tk only notes a
        request for a hidden window, and the keyboard stayed on the Undo."""
        if getattr(self, "_settings_open", False):
            return (self._settings_nav_buttons or {}).get(
                getattr(self, "_settings_selected_section", None))
        try:
            on_notes = self.notebook.index("current") == self.TAB_NOTES
        except tk.TclError:
            return None
        if not on_notes:
            return self.notebook
        return self.sidebar_toggle if self._sidebar_hidden else self.canvas

    def _keyboard_off_toast(self):
        """The Undo hidden while the keyboard is on it -- the banner gone, or
        a banner with nothing to offer in its place: the keyboard lands where
        the Undo's own key sends it, never on a word no longer on screen."""
        if self._holds_keyboard(self.toast_action_lbl):
            target = self._toast_landing()
            if target is not None:
                target.focus_set()

    def _toast_undo_key(self, event):
        """Ctrl+Z, while the toast offers an Undo and the keyboard is not in
        a text box with typing of its own to take back: takes the offer.
        Eight seconds is short to reach the banner by Tab. A delete leaves
        the keyboard in the new note's title, and an Entry has no undo: Ctrl+Z
        there did nothing at all."""
        if (self._toast_action is None
                or not getattr(self, "_toast_action_undoes", True)
                or self._toast_hide_job is None
                or self._a_dialog_is_asking()):
            return None
        widget = getattr(event, "widget", None)
        try:
            if isinstance(widget, str):
                return None
            kind = widget.winfo_class()
            if kind in self._TYPING_CLASSES and not (
                    kind in ("Entry", "TEntry")
                    or (kind == "Text" and not self._can_edit_undo(widget))):
                return None
            # A one-line box only while nothing is typed in it (its hint
            # aside): a title begun after the delete had its typo "undone" by
            # the deleted note coming back over it.
            if kind in ("Entry", "TEntry"):
                hint = next((p for e, p in getattr(self, "_placeholders", ()) if e is widget), None)
                if widget.get() not in ("", hint):
                    return None
        except (tk.TclError, AttributeError):
            return None
        self._run_toast_action()
        return "break"

    def _hide_toast(self):
        self._keyboard_off_toast()
        try:
            self.toast_frame.place_forget()
        except tk.TclError:
            pass
        self._toast_action = None
        if self._toast_hide_job is not None:
            try:
                self.after_cancel(self._toast_hide_job)
            except (tk.TclError, ValueError):
                pass
            self._toast_hide_job = None

    def _show_toast(self, text, kind="success", action=None, action_text="Undo",
                    yield_to_action=False):
        """Briefly show a floating banner near the window's top, seen from
        any scroll or tab. With an `action`, one clickable word, up far
        longer (1.8 s is no time to decide). `yield_to_action`: reassurance
        that must not cover a one-time chance -- "Note updated" wiped an
        Undo within a second of its eight.
        """
        if yield_to_action and (self._offer_on_banner() or (
                self._toast_hide_job is not None
                and getattr(self, "_toast_kind", None) == "info")
                or getattr(self, "_words_hide_job", None) is not None):
            # Quiet costs nothing (the status line says it), and words on a
            # banner win too: "Note updated" covered "title shortened".
            return
        color = {"success": self.colors["success"],
                 "info": self.colors["accent"],
                 "error": self.colors["danger"]}.get(kind, self.colors["success"])
        # The mark follows the kind: a failure opened with a tick.
        mark = {"success": "✓", "info": "i", "error": "!"}.get(kind, "✓")
        self._toast_action = action
        # Ctrl+Z takes an Undo, never another word: "Show" on the '(earlier
        # text)' banner was taken as one (the audit's round 18).
        self._toast_action_undoes = action_text == "Undo"
        self._toast_kind = kind
        try:
            self.toast_frame.configure(bg=color)
            self.toast_lbl.configure(text=f"{mark}  {text}", bg=color,
                                     fg=letters_on(color))
            if action is not None:
                # Recoloured here, not tracked: see where it is built. Its
                # ring is drawn in the banner's own words' colour.
                self.toast_action_lbl._ring_on = letters_on(color)
                self.toast_action_lbl.configure(text=action_text, bg=color,
                                                fg=letters_on(color), padx=0)
                self._fill(self.toast_action_lbl, color)
                self.toast_action_lbl.pack(side="left", padx=(0, 14))
            else:
                self._keyboard_off_toast()
                self.toast_action_lbl.pack_forget()
            self.toast_frame.place(relx=0.5, rely=0.0, anchor="n", y=4)
            self.toast_frame.lift()
        except tk.TclError:
            return

        if self._toast_hide_job is not None:
            try:
                self.after_cancel(self._toast_hide_job)
            except (tk.TclError, ValueError):
                pass

        def hide():
            self._toast_hide_job = None
            # Not from under the keyboard: someone who Tabbed to Undo is
            # reading it, and it waits for them.
            try:
                held = str(self.tk.call("focus")) == str(self.toast_action_lbl)
            except tk.TclError:
                held = False
            if held and self._toast_action is not None:
                self._toast_hide_job = self.after(1000, hide)
                return
            self._hide_toast()

        self._toast_hide_job = self.after(8000 if action else self.TOAST_MS, hide)

    # How long a banner with nothing to offer stays up.
    TOAST_MS = 1800

    def _offer_on_banner(self):
        """Whether the banner holds what must not be covered: an Undo neither
        taken nor expired -- both clear _toast_action, so a stale one is never
        taken for a live offer -- or an error. The autosave that follows a
        failed action within its delay covered "something went wrong" with
        "Note updated", and the one message that mattered was gone."""
        return (self._toast_hide_job is not None
                and (self._toast_action is not None
                     or getattr(self, "_toast_kind", None) == "error"))

    def _show_words_beneath(self, text):
        """*text* on an info banner of its own, just beneath the banner, while
        that holds an offer (_offer_on_banner): the Undo keeps its place and
        its word, and the words are seen. Made at the first need, coloured
        at each showing as the banner is."""
        frame = getattr(self, "_words_frame", None)
        try:
            if frame is None:
                frame = self._words_frame = tk.Frame(self)
                self._words_lbl = tk.Label(frame, font=("Segoe UI", 9, "bold"),
                                           padx=14, pady=6)
                self._words_lbl.pack(side="left")
            colour = self.colors["accent"]
            frame.configure(bg=colour)
            self._words_lbl.configure(text=f"i  {text}", bg=colour,
                                      fg=letters_on(colour))
            below = max(self.toast_frame.winfo_height(),
                        self.toast_frame.winfo_reqheight())
            frame.place(relx=0.5, rely=0.0, anchor="n", y=4 + below + 4)
            frame.lift()
        except tk.TclError:
            return
        job = getattr(self, "_words_hide_job", None)
        if job is not None:
            try:
                self.after_cancel(job)
            except (tk.TclError, ValueError):
                pass
        self._words_hide_job = self.after(self.TOAST_MS, self._hide_words_beneath)

    def _hide_words_beneath(self):
        """The banner of _show_words_beneath goes, if it stands."""
        job = getattr(self, "_words_hide_job", None)
        self._words_hide_job = None
        if job is not None:
            try:
                self.after_cancel(job)
            except (tk.TclError, ValueError):
                pass
        frame = getattr(self, "_words_frame", None)
        if frame is not None:
            try:
                frame.place_forget()
            except tk.TclError:
                pass


def _draw_sharp_on_scaled_screens():
    """Tell Windows the app draws at the main screen's scale: stretched, the
    text was soft. Pixel sizes grow through NoteOrganizer.px. "System
    aware" (per monitor needs rebuilds Tk lacks): softer on a second screen,
    where "Sharp text on a scaled screen" turns it off. Before the first
    window; a failure changes nothing (ISSUES_LOG: "The DPI fix that made
    things worse")."""
    if not sys.platform.startswith("win"):
        return False
    try:
        import ctypes
        try:
            process_system_dpi_aware = 1
            return ctypes.windll.shcore.SetProcessDpiAwareness(
                process_system_dpi_aware) == 0
        except (AttributeError, OSError):
            # Windows 7 and 8.0 have no shcore.dll; the older call says the
            # same thing.
            return bool(ctypes.windll.user32.SetProcessDPIAware())
    except Exception:                                 # noqa: BLE001
        return False


def _main():
    """Launch the app with a top-level guard. In the --windowed .exe there's no
    console, so an unhandled exception would make the app vanish with no trace.
    This shows the error and, where possible, points the user at their data."""
    try:
        # One notebook, one app; locked here (qa builds several apps), BEFORE
        # initialise()'s migration. Resolved ONCE: asked twice, a launch
        # locked one folder and opened its twin's.
        _resolved = resolve_data_dir(
            os.path.dirname(os.path.abspath(__file__)))
        _data_dir = _resolved[0]
        if not single_instance.acquire(
                os.path.join(_data_dir, single_instance.LOCK_FILENAME)):
            import tkinter.messagebox as _mb
            root = tk.Tk()
            root.withdraw()
            _mb.showinfo(
                "Note Organizer is already open",
                "Note Organizer is already running on this notebook.\n\n"
                "Only one window can be open at a time: two would each keep "
                "their own copy of your notes, and whichever saved last "
                "would overwrite the other's work.\n\n"
                "Switch to the window that is already open — look for it in "
                "the taskbar.")
            root.destroy()
            return
        initialise(resolved=_resolved)
        # After initialise, which puts settings.json where it is read from,
        # and before the first window, which is when Windows stops listening.
        if get_setting(SHARP_TEXT_SETTING, True, expect=bool):
            _draw_sharp_on_scaled_screens()
        app = NoteOrganizer()
        app.protocol("WM_DELETE_WINDOW", app.on_app_close)
        # Signing out, restarting, shutting down: Windows ends the process
        # without WM_DELETE_WINDOW, and Tk says so with this one instead.
        app.protocol("WM_SAVE_YOURSELF", app.on_session_end)
        app.mainloop()
    except Exception as exc:  # noqa: BLE001 — last-resort catch-all on purpose
        import traceback
        details = traceback.format_exc()
        # A crash log next to the data, best-effort: before the data folder
        # is known there is nowhere to put it, and the window below still
        # shows (it once raised here and never did).
        log_path = _core_diagnostics.append_crash_log("crash", details, APP_DIR)
        try:
            root = tk.Tk()
            root.withdraw()
            msg = ("Note Organizer hit an unexpected error and needs to close.\n\n"
                   f"{type(exc).__name__}: {exc}\n\n"
                   "Your saved notes are safe on disk.")
            if log_path:
                msg += f"\n\nDetails were written to:\n{log_path}"
            # The standard dialog: the app's own may be what failed.
            from tkinter import messagebox as _messagebox
            _messagebox.showerror("Note Organizer", msg)
            root.destroy()
        except Exception:
            # Even the error dialog failed — print as a final fallback.
            print(details)


if __name__ == "__main__":
    _main()